#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define constants
#define SPI_MODE SPI_MODE0
#define SPI_SPEED 1000000
#define SPI_CS 8
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SCK 11
#define ADC_CHANNEL 0

// Define the SPI handle
gpio_export(SPI_CS);
gpio_fsel(SPI_CS, GPIO_FSEL_OUTP);
gpio_mode(SPI_CS, GPIO_MODE_OUTPUT);
gpio_pull_up(SPI_CS, GPIO_PULLUP_DISABLE);

// Define the ADC handle
int adc = -1;

// Define the signal handlers
void sigint_handler(int sig) {
    gpio_close(adc);
    gpio_close(SPI_CS);
    exit(0);
}

void sigterm_handler(int sig) {
    gpio_close(adc);
    gpio_close(SPI_CS);
    exit(0);
}

int main() {
    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize pigpio
    pigpio_init();

    // Initialize SPI
    if (gpio_export(SPI_MOSI) < 0) {
        printf("Failed to export SPI MOSI\n");
        return 1;
    }
    if (gpio_export(SPI_MISO) < 0) {
        printf("Failed to export SPI MISO\n");
        return 1;
    }
    if (gpio_export(SPI_SCK) < 0) {
        printf("Failed to export SPI SCK\n");
        return 1;
    }
    if (gpio_export(SPI_CS) < 0) {
        printf("Failed to export SPI CS\n");
        return 1;
    }
    if (gpio_fsel(SPI_CS, GPIO_FSEL_OUTP) < 0) {
        printf("Failed to set SPI CS as output\n");
        return 1;
    }
    if (gpio_mode(SPI_CS, GPIO_MODE_OUTPUT) < 0) {
        printf("Failed to set SPI CS as output\n");
        return 1;
    }
    if (gpio_pull_up(SPI_CS, GPIO_PULLUP_DISABLE) < 0) {
        printf("Failed to disable pull-up on SPI CS\n");
        return 1;
    }

    // Initialize ADC
    if (gpio_export(ADC_CHANNEL) < 0) {
        printf("Failed to export ADC channel\n");
        return 1;
    }
    if (gpio_fsel(ADC_CHANNEL, GPIO_FSEL_ADC) < 0) {
        printf("Failed to set ADC channel as input\n");
        return 1;
    }
    if (gpio_mode(ADC_CHANNEL, GPIO_MODE_INPUT) < 0) {
        printf("Failed to set ADC channel as input\n");
        return 1;
    }

    // Initialize SPI
    if (pigpio_spi_init(SPI_MODE, SPI_SPEED, SPI_CS) < 0) {
        printf("Failed to initialize SPI\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Set SPI CS high to select the sensor
        gpio_write(SPI_CS, 1);

        // Wait for 1ms
        usleep(1000);

        // Set SPI CS low to deselect the sensor
        gpio_write(SPI_CS, 0);

        // Read the ADC value
        int adc_value = pigpio_spi_read(ADC_CHANNEL, 1);

        // Check for errors
        if (adc_value < 0) {
            printf("Failed to read ADC value\n");
            return 1;
        }

        // Log the reading
        printf("%d %d\n", time(NULL), adc_value);

        // Wait for 1 second before taking the next reading
        sleep(1);
    }

    // Clean up
    pigpio_spi_close();
    gpio_close(SPI_CS);
    gpio_close(ADC_CHANNEL);
    gpio_unexport(SPI_CS);
    gpio_unexport(SPI_MOSI);
    gpio_unexport(SPI_MISO);
    gpio_unexport(SPI_SCK);
    pigpio_cleanup();
    return 0;
}

