#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define PI_GPIO4 4
#define PI_GPIO8 8
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE0
#define MCP3008_CHANNEL 0
#define MCP3008_BITS 10
#define CSV_FILE "flame_data.csv"

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    // Open SPI0
    int spi_fd = spiOpen(PI_GPIO8, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    int csv_fd = open(CSV_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (csv_fd < 0) {
        fprintf(stderr, "CSV file open failed\n");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up SPI
    spiTransfer(spi_fd, NULL, NULL, NULL, 1);

    // Set up GPIO4 as output
    gpioSetMode(PI_GPIO4, PI_MODE_OUTPUT);
    gpioToggle(PI_GPIO4);

    // Set up MCP3008 SPI
    spiTransfer(spi_fd, NULL, NULL, NULL, 1);
    gpioSetLevel(PI_GPIO8, 0);

    // Main loop
    while (1) {
        // Read KY-026 digital output
        int ky026_value = gpioRead(PI_GPIO4);
        if (ky026_value == 0) {
            printf("Flame detected\n");
            gpioToggle(PI_GPIO4);
        } else {
            printf("No flame detected\n");
            gpioToggle(PI_GPIO4);
        }

        // Read MCP3008 analog output
        int adc_value = spiTransfer(spi_fd, NULL, NULL, NULL, 1)[MCP3008_CHANNEL];
        if (adc_value < 0) {
            printf("SPI transfer failed\n");
            continue;
        }

        // Map ADC value to temperature
        int temperature = (adc_value * 10) / 1023;

        // Log data
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(NULL));
        fprintf(csv_fd, "%s,%d,%d\n", timestamp, ky026_value, temperature);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    close(csv_fd);
    gpioTerminate();
    return 0;
}

