    if (co_log == NULL) {
        perror("fopen co_log.txt");
        pigpio_i2c_close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    FILE *alert_log = fopen("alert_log.txt", "w");
    if (alert_log == NULL) {
