#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>

#define I2C_ADDRESS_1 0x48
#define I2C_ADDRESS_2 0x49
#define I2C_ADDRESS_3 0x50
#define I2C_ADDRESS_4 0x51
#define MIC_SENSITIVITY -38.0
#define REF_PRESSURE 20e-6
#define SAMPLE_RATE 100
#define SAMPLE_INTERVAL 100
#define LOG_FILE "audio_log.txt"

int main() {
    int i, j;
    int mic1, mic2;
    float avg_db1, avg_db2;
    float db1, db2;
    int fd1, fd2;
    struct sigaction sa;
    struct sigaction sa2;
    FILE *log_file;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up I2C bus 1
    if (gpioI2COpen(1, I2C_ADDRESS_1, 100000) < 0) {
        perror("gpioI2COpen");
        gpioTerminate();
        return 1;
    }
    if (gpioI2COpen(1, I2C_ADDRESS_2, 100000) < 0) {
        perror("gpioI2COpen");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return 1;
    }
    sa2.sa_handler = sigterm_handler;
    sigemptyset(&sa2.sa_mask);
    if (sigaction(SIGTERM, &sa2, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("fopen");
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read from I2C bus 1
        if (gpioI2CRead(1, I2C_ADDRESS_1, 0x00, 2, &mic1, NULL) < 0) {
            printf("Error reading from I2C bus 1\n");
            mic1 = -999.0;
        } else {
            mic1 = (mic1[0] << 8) | mic1[1];
        }
        if (gpioI2CRead(1, I2C_ADDRESS_2, 0x00, 2, &mic2, NULL) < 0) {
            printf("Error reading from I2C bus 1\n");
            mic2 = -999.0;
        } else {
            mic2 = (mic2[0] << 8) | mic2[1];
        }

        // Calculate sound pressure levels
        db1 = 20.0 * log10((mic1 * MIC_SENSITIVITY) / REF_PRESSURE);
        db2 = 20.0 * log10((mic2 * MIC_SENSITIVITY) / REF_PRESSURE);

        // Calculate average
        avg_db1 = (avg_db1 * (SAMPLE_RATE - 1) + db1) / SAMPLE_RATE;
        avg_db2 = (avg_db2 * (SAMPLE_RATE - 1) + db2) / SAMPLE_RATE;

        // Log data
        fprintf(log_file, "%f %f %f %f\n", time(NULL), avg_db1, avg_db2, avg_db1 - avg_db2);

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL * 1000000);
    }

    // Clean up
    gpioTerminate();
    fclose(log_file);
    return 0;
}

void sigint_handler(int sig) {
    printf("Received SIGINT\n");
    gpioTerminate();
    exit(0);
}

void sigterm_handler(int sig) {
    printf("Received SIGTERM\n");
    gpioTerminate();
    exit(0);
}

