#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>

#define SPI_MODE SPI_MODE0
#define SPI_SPEED 1000000
#define SPI_CS1 9
#define SPI_CS0 8
#define LED_PIN 27
#define THRESHOLD 0.7
#define SAMPLE_RATE 100
#define SAMPLE_WINDOW 100
#define FILE_NAME "audio_events.csv"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up SPI
    if (gpioSetMode(SPI_CS0, SPI_MODE) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SPI_CS1, SPI_MODE) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetClock(SPI_CS0, SPI_SPEED) < 0) {
        perror("gpioSetClock");
        gpioTerminate();
        return 1;
    }
    if (gpioSetClock(SPI_CS1, SPI_SPEED) < 0) {
        perror("gpioSetClock");
        gpioTerminate();
        return 1;
    }

    // Open file for writing
    int fd = open(FILE_NAME, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set up LED
    if (gpioMode(LED_PIN, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        close(fd);
        gpioTerminate();
        return 1;
    }
    gpioWrite(LED_PIN, 0);

    // Set up SPI channels
    int mic1, mic2;
    if (gpioGetPinMOSI(SPI_CS0) < 0) {
        perror("gpioGetPinMOSI");
        close(fd);
        gpioTerminate();
        return 1;
    }
    if (gpioGetPinMISO(SPI_CS0) < 0) {
        perror("gpioGetPinMISO");
        close(fd);
        gpioTerminate();
        return 1;
    }
    if (gpioGetPinSCK(SPI_CS0) < 0) {
        perror("gpioGetPinSCK");
        close(fd);
        gpioTerminate();
        return 1;
    }
    if (gpioGetPinSCL(SPI_CS0) < 0) {
        perror("gpioGetPinSCL");
        close(fd);
        gpioTerminate();
        return 1;
    }
    if (gpioGetPinCE(SPI_CS0) < 0) {
        perror("gpioGetPinCE");
        close(fd);
        gpioTerminate();
        return 1;
    }
    if (gpioGetPinCE(SPI_CS1) < 0) {
        perror("gpioGetPinCE");
        close(fd);
        gpioTerminate();
        return 1;
    }
    if (gpioGetPinMOSI(SPI_CS1) < 0) {
        perror("gpioGetPinMOSI");
        close(fd);
        gpioTerminate();
        return 1;
    }
    if (gpioGetPinMISO(SPI_CS1) < 0) {
        perror("gpioGetPinMISO");
        close(fd);
        gpioTerminate();
        return 1;
    }
    if (gpioGetPinSCK(SPI_CS1) < 0) {
        perror("gpioGetPinSCK");
        close(fd);
        gpioTerminate();
        return 1;
    }
    if (gpioGetPinSCL(SPI_CS1) < 0) {
        perror("gpioGetPinSCL");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set up SPI channels
    if (gpioSetupSPI(SPI_CS0, SPI_MODE, SPI_SPEED, SPI_MISO, SPI_MOSI, SPI_SCK) < 0) {
        perror("gpioSetupSPI");
        close(fd);
        gpioTerminate();
        return 1;
    }
    if (gpioSetupSPI(SPI_CS1, SPI_MODE, SPI_SPEED, SPI_MISO, SPI_MOSI, SPI_SCK) < 0) {
        perror("gpioSetupSPI");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set up timer
    struct itimerspec timer;
    timer.it_value.tv_sec = 0;
    timer.it_value.tv_nsec = 100000;
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_nsec = 0;
    if (setitimer(ITIMER_REAL, &timer, sizeof(timer)) < 0) {
        perror("setitimer");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        close(fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Sample audio
        int mic1_value, mic2_value;
        if (gpioRead(SPI_MISO, &mic1_value) < 0) {
            perror("gpioRead");
            close(fd);
            gpioTerminate();
            return 1;
        }
        if (gpioRead(SPI_MISO, &mic2_value) < 0) {
            perror("gpioRead");
            close(fd);
            gpioTerminate();
            return 1;
        }

        // Calculate RMS values
        double mic1_rms = sqrt(mic1_value * mic1_value / 32767.0);
        double mic2_rms = sqrt(mic2_value * mic2_value / 32767.0);

        // Check if either RMS value exceeds threshold
        if (mic1_rms > THRESHOLD || mic2_rms > THRESHOLD) {
            gpioWrite(LED_PIN, 1);
            sleep(0.5);
            gpioWrite(LED_PIN, 0);
        }

        // Log to file
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(NULL));
        fprintf(fd, "%s,%f,%f\n", timestamp, mic1_rms, mic2_rms);

        // Sleep for 1 ms
        usleep(1000);
    }

    // Clean up
    gpioTerminate();
    close(fd);
    return 0;
}

void sigint_handler(int sig) {
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    exit(0);
}

