        // Sleep for 1 ms
        usleep(1000);
    }

    // Clean up
    gpioTerminate();
    close(fd);
    return 0;
}

void sigint_handler(int sig) {
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    exit(0);
