    int status;
    unsigned char reg;
    float voltage;

    // Read the register
    status = i2cWriteDevice(ADC_ADDRESS, 0x00, &reg);
    if (status < 0) {
        printf("Error reading register\n");
        return;
    }

    // Read the voltage
    status = i2cReadDevice(ADC_ADDRESS, 0x00, &reg);
    if (status < 0) {
        printf("Error reading voltage\n");
        return;
    }

    // Convert the voltage to current
    voltage = (reg * CURRENT_SCALE) / 4096.0;

    // Add the current reading to the buffer
    if (CurrentBuffer.head == CurrentBuffer.tail) {
        CurrentBuffer.tail = 0;
    }
    CurrentBuffer.values[CurrentBuffer.tail] = voltage;
    CurrentBuffer.head = (CurrentBuffer.head + 1) % BUFFER_SIZE;
    CurrentBuffer.tail = (CurrentBuffer.tail + 1) % BUFFER_SIZE;

    // Calculate the average current
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += CurrentBuffer.values[i];
    }
    float averageCurrent = sum / BUFFER_SIZE;

    // Trigger the warning LED if the average current exceeds the threshold
    if (averageCurrent > CURRENT_THRESHOLD) {
