void sigterm_handler(int sig) {
    gpiod_close(&gpiod);
    spidev_close(SPI_DEVICE);
    exit(0);
}

int main(int argc, char **argv) {
    // Initialize signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize libgpiod
    gpiod_t *gpiod;
    gpiod_new(&gpiod, 0);

    // Initialize SPI
    spidev_t *spidev;
    spidev_new(&spidev, SPI_DEVICE, SPI_MOSI, SPI_MISO, SPI_SCLK, SPI_CS);

    // Open the CSV file for writing
    FILE *csv_file = fopen(CSV_FILE, "w");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        return 1;
    }

    // Write the header to the CSV file
    fprintf(csv_file, "Timestamp,Moisture1,Moisture2\n");

    while (1) {
        // Read the sensor values
        int moisture1, moisture2;
        int ret = spidev_read(spidev, &moisture1, &moisture2, MCP3008_CHANNELS);
        if (ret < 0) {
            perror("SPI read error");
            continue;
        }

        // Map the raw values to the moisture scale
        moisture1 = (moisture1 * MOISTURE_SCALE) / 1023.0;
        moisture2 = (moisture2 * MOISTURE_SCALE) / 1023.0;

        // Log the values to the CSV file
        fprintf(csv_file, "%d,%f,%f\n", time(NULL), moisture1, moisture2);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close the CSV file
    fclose(csv_file);

    // Close libgpiod and SPI
    gpiod_close(&gpiod);
    spidev_close(SPI_DEVICE);

    return 0;
}

