#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>

#define I2C_ADDRESS 0x40
#define I2C_ADDRESS_BIT 7
#define I2C_ADDRESS_MASK 0x3F
#define I2C_REG 0x00
#define I2C_REG_MASK 0x3F
#define I2C_DATA_SIZE 2
#define I2C_READ 0x00
#define I2C_WRITE 0x01
#define I2C_READ_BIT 0x01
#define I2C_WRITE_BIT 0x10
#define I2C_TIMEOUT 100
#define I2C_TIMEOUT_MS 100

int main(int argc, char **argv) {
    int i2c_fd;
    int i2c_status;
    int i2c_result;
    int gpio_fd;
    int gpio_status;
    int gpio_result;
    int pressure_kPa;
    char timestamp[32];
    char log_file[256];
    struct stat log_stat;
    struct timespec start_time;
    struct timespec end_time;
    struct timespec time_diff;

    // Initialize pigpio
    if (gpio_init() < 0) {
        fprintf(stderr, "pigpio_init failed: %d\n", gpio_get_error());
        return 1;
    }

    // Open I2C
    sprintf(log_file, "pressure_log.csv");
    if ((i2c_fd = open(log_file, O_RDWR | O_CREAT | O_WRONLY | O_APPEND, 0644)) < 0) {
        fprintf(stderr, "open %s failed: %d\n", log_file, errno);
        gpioTerminate();
        return 1;
    }

    // Check if file exists and create header row if necessary
    if (fstat(i2c_fd, &log_stat) < 0) {
        fprintf(stderr, "fstat %s failed: %d\n", log_file, errno);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (log_stat.st_size == 0) {
        fprintf(i2c_fd, "timestamp,pressure_kPa\n");
        fflush(i2c_fd);
    }

    while (1) {
        // Wait for SIGINT or SIGTERM
        struct sigaction sa;
        sa.sa_handler = sigaction(SIGINT, SIG_IGN, &sa);
        sa.sa_handler = sigaction(SIGTERM, SIG_IGN, &sa);

        // Read I2C
        i2c_status = pigpio_i2c_open(i2c_fd, I2C_ADDRESS, I2C_ADDRESS_BIT);
        if (i2c_status < 0) {
            fprintf(stderr, "pigpio_i2c_open failed: %d\n", i2c_status);
            continue;
        }

        i2c_result = pigpio_i2c_write(i2c_fd, I2C_REG, I2C_READ_BIT);
        if (i2c_result < 0) {
            fprintf(stderr, "pigpio_i2c_write failed: %d\n", i2c_result);
            pigpio_i2c_close(i2c_fd);
            continue;
        }

        i2c_result = pigpio_i2c_read(i2c_fd, I2C_REG, I2C_DATA_SIZE);
        if (i2c_result < 0) {
            fprintf(stderr, "pigpio_i2c_read failed: %d\n", i2c_result);
            pigpio_i2c_close(i2c_fd);
            continue;
        }

        // Convert raw value to pressure in kPa
        pressure_kPa = (i2c_result / 65535.0) * 500.0;

        // Log reading
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&now));
        fprintf(i2c_fd, "%s,%f\n", timestamp, pressure_kPa);
        fflush(i2c_fd);

        // Wait for 1 second
        clock_gettime(CLOCK_REALTIME, &start_time);
        sleep(1);
        clock_gettime(CLOCK_REALTIME, &end_time);
        time_diff.tv_sec = end_time.tv_sec - start_time.tv_sec;
        time_diff.tv_nsec = end_time.tv_nsec - start_time.tv_nsec;
        if (time_diff.tv_nsec < 0) {
            time_diff.tv_sec++;
            time_diff.tv_nsec += 1000000000;
        }
        sleep(time_diff.tv_sec);
    }

    // Close I2C and log file
    pigpio_i2c_close(i2c_fd);
    close(i2c_fd);

    // Flush and close log file
    if (fdatasync(i2c_fd) < 0) {
        fprintf(stderr, "fdatasync %s failed: %d\n", log_file, errno);
    }
    close(i2c_fd);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

