#include <fcntl.h>
#include <unistd.h>
#include <signal.h>

#define GPIO27 27
#define GPIO8  8
#define GPIO11 11
#define GPIO10 10
#define GPIO9   9
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define ADC_WIDTH 10
#define ADC_FULL_SCALE 1024
#define VCC 3.3
#define ZERO_CURRENT (VCC / 2)
#define SENSITIVITY 66e-3

int main(int argc, char **argv) {
    int gpio, spi, fd;
    unsigned char start_byte = 0x01;
    unsigned char config_byte;
    unsigned char result[3];
    unsigned int adc_value;
    unsigned int current;
    struct stat st;
    struct sigaction sa;
    int sigint, sigterm;

    // Initialize pigpio
    if (gpio = pigpioInit()) {
        printf("pigpio initialization failed\n");
        return 1;
    }

    // Set GPIO27 as output
    if (gpioMode(GPIO27, PI_OUTPUT) != 0) {
        printf("GPIO27 mode failed\n");
        pigpioTerminate();
        return 1;
    }

    // Set GPIO8, 11, 10, and 9 as SPI
    if (gpioMode(GPIO8, PI_SPI) != 0 ||
        gpioMode(GPIO11, PI_SPI) != 0 ||
        gpioMode(GPIO10, PI_SPI) != 0 ||
        gpioMode(GPIO9, PI_SPI) != 0) {
        printf("SPI mode failed\n");
        pigpioTerminate();
        return 1;
    }

    // Set SPI speed and mode
    if (gpioClockedHertz(GPIO8, SPI_SPEED) != 0 ||
        gpioMode(GPIO8, PI_SPI_MODE) != SPI_MODE) {
        printf("SPI speed and mode failed\n");
        pigpioTerminate();
        return 1;
    }

    // Open SPI handle
    if ((fd = spiOpen(GPIO8, GPIO11, GPIO10, GPIO9, SPI_MODE, SPI_SPEED)) < 0) {
        printf("SPI open failed\n");
        pigpioTerminate();
        return 1;
    }

    // Set up signal handlers
    sigint = sigemptyset();
    sigaddset(sigint, SIGINT);
    sigterm = sigemptyset();
    sigaddset(sigterm, SIGTERM);
    sa.sa_handler = sigpipe;
    sigaction(SIGINT, &sa, NULL);
    sa.sa_handler = sigpipe;
    sigaction(SIGTERM, &sa, NULL);

    // Open log file
    if ((fd = open("current_log.txt", O_WRONLY | O_APPEND | O_CREAT, 0644)) < 0) {
        printf("File open failed\n");
        close(fd);
        pigpioTerminate();
        return 1;
    }

    while (1) {
        // Read from MCP3008
        if (spiTransfer(fd, &start_byte, 1) < 0) {
            printf("SPI transfer failed\n");
            close(fd);
            pigpioTerminate();
            return 1;
        }
        if (spiTransfer(fd, &config_byte, 1) < 0) {
            printf("SPI transfer failed\n");
            close(fd);
            pigpioTerminate();
            return 1;
        }
        if (spiTransfer(fd, NULL, 1) < 0) {
            printf("SPI transfer failed\n");
            close(fd);
            pigpioTerminate();
            return 1;
        }

        // Extract ADC value
        adc_value = (config_byte & 0x3F) << 1;
        adc_value |= (result[1] & 0x3F);

        // Check for invalid ADC value
        if (adc_value < 0 || adc_value >= ADC_FULL_SCALE) {
            printf("Invalid ADC value\n");
            close(fd);
            pigpioTerminate();
            return 1;
        }

        // Convert ADC value to voltage
        current = (adc_value * SENSITIVITY * VCC) / ADC_FULL_SCALE;

        // Log reading
        if (fprintf(fd, "%d %f\n", (unsigned int)time(NULL), current) < 0) {
            printf("File write failed\n");
            close(fd);
            pigpioTerminate();
            return 1;
        }

        // Monitor current
        if (current > 10) {
            gpioWrite(GPIO27, 1);
            printf("OVERCURRENT\n");
            close(fd);
            pigpioTerminate();
            return 1;
        }
    }

    // Clean up
    close(fd);
    gpioWrite(GPIO27, 0);
    pigpioTerminate();
    return 0;
}

