#include <unistd.h>
#include <sys/types.h>
#include <signal.h>

#define SPI_MODE 0
#define SPI_SPEED 1000000
#define GPIO_ALARM 4
#define GPIO_CE0 8
#define GPIO_SCLK 11
#define GPIO_MOSI 10
#define GPIO_MISO 9
#define GPIO_CO 17
#define REF_V 3.3

int main(int argc, char **argv) {
    int spi_fd, gpio_fd;
    int ret;
    unsigned char adc_value;
    float voltage;
    struct sigaction sa;
    FILE *log_file;

    // Initialize logging
    openlog("co_sensor", LOG_PID, LOG_USER);
    setlogmask(LOG_UPTIME | LOG_LPR);

    // Set up signal handlers
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    sigaction(SIGINT, &sa, NULL);

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        return 1;
    }

    // Configure SPI
    if ((gpio_fd = gpioGetFd(GPIO_CE0)) < 0) {
        syslog(LOG_ERR, "Failed to get GPIO CE0 handle");
        gpioTerminate();
        return 1;
    }
    if ((ret = gpioModeGPIO0(gpio_fd)) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO CE0 mode");
        gpioTerminate();
        return 1;
    }
    if ((ret = gpioModeGPIO0(gpio_fd, GPIO_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO CE0 mode");
        gpioTerminate();
        return 1;
    }
    if ((ret = gpioModeGPIO0(gpio_fd, GPIO_OUTPUT PullUpDown) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO CE0 mode");
        gpioTerminate();
        return 1;
    }

    if ((gpio_fd = gpioGetFd(GPIO_SCLK)) < 0) {
        syslog(LOG_ERR, "Failed to get GPIO SCLK handle");
        gpioTerminate();
        return 1;
    }
    if ((ret = gpioModeGPIO0(gpio_fd) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO SCLK mode");
        gpioTerminate();
        return 1;
    }
    if ((ret = gpioModeGPIO0(gpio_fd, GPIO_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO SCLK mode");
        gpioTerminate();
        return 1;
    }
    if ((ret = gpioModeGPIO0(gpio_fd, GPIO_OUTPUT PullUpDown) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO SCLK mode");
        gpioTerminate();
        return 1;
    }

    if ((gpio_fd = gpioGetFd(GPIO_MOSI)) < 0) {
        syslog(LOG_ERR, "Failed to get GPIO MOSI handle");
        gpioTerminate();
        return 1;
    }
    if ((ret = gpioModeGPIO0(gpio_fd) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO MOSI mode");
        gpioTerminate();
        return 1;
    }
    if ((ret = gpioModeGPIO0(gpio_fd, GPIO_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO MOSI mode");
        gpioTerminate();
        return 1;
    }
    if ((ret = gpioModeGPIO0(gpio_fd, GPIO_OUTPUT PullUpDown) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO MOSI mode");
        gpioTerminate();
        return 1;
    }

    if ((gpio_fd = gpioGetFd(GPIO_MISO)) < 0) {
        syslog(LOG_ERR, "Failed to get GPIO MISO handle");
        gpioTerminate();
        return 1;
    }
    if ((ret = gpioModeGPIO0(gpio_fd) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO MISO mode");
        gpioTerminate();
        return 1;
    }
    if ((ret = gpioModeGPIO0(gpio_fd, GPIO_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO MISO mode");
        gpioTerminate();
        return 1;
    }

    if ((gpio_fd = gpioGetFd(GPIO_CO)) < 0) {
        syslog(LOG_ERR, "Failed to get GPIO CO handle");
        gpioTerminate();
        return 1;
    }
    if ((ret = gpioModeGPIO0(gpio_fd) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO CO mode");
        gpioTerminate();
        return 1;
    }
    if ((ret = gpioModeGPIO0(gpio_fd, GPIO_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO CO mode");
        gpioTerminate();
        return 1;
    }

    // Open SPI
    if ((spi_fd = spiOpen(gpio_fd, GPIO_SCLK, GPIO_MOSI, GPIO_MISO, SPI_MODE) < 0) {
        syslog(LOG_ERR, "Failed to open SPI");
        gpioTerminate();
        return 1;
    }

    // Set SPI speed
    if ((ret = spiSetClock(spi_fd, SPI_SPEED) < 0) {
        syslog(LOG_ERR, "Failed to set SPI speed");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up alarm
    if ((ret = gpioModeGPIO0(GPIO_ALARM, GPIO_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO ALARM mode");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }
    if ((ret = gpioWrite(gpio_fd, GPIO_ALARM, 0) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO ALARM high");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("co_log.txt", "w");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file");
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read ADC value
        if ((ret = spiTransfer(spi_fd, NULL, &adc_value, 1, NULL) < 0) {
            syslog(LOG_ERR, "Failed to read ADC value");
            gpioWrite(gpio_fd, GPIO_ALARM, 0);
            sleep(1);
            continue;
        }

        // Convert ADC value to voltage
        voltage = (adc_value * REF_V) / 1024.0;

        // Check voltage level
        if (voltage > 2.5) {
            gpioWrite(gpio_fd, GPIO_ALARM, 1);
        } else {
            gpioWrite(gpio_fd, GPIO_ALARM, 0);
        }

        // Log reading
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,Voltage: %.2f V\n",
                1900 + 2000 + time(NULL) / 3600,
                100 + (time(NULL) % 3600) / 60,
                time(NULL) % 60,
                (time(NULL) % 3600) / 60,
                time(NULL) % 60,
