    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed: %d\n", gpioErrno());
        return 1;
    }

    // Open SPI handle
    int spiHandle = spiOpen(SPI_BUS, SPI_CHANNEL, SPI_MODE, SPI_SPEED);
    if (spiHandle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spiErrno());
        gpioTerminate();
        return 1;
    }

