    FILE *logFile = fopen("methane_log.txt", "a");
    if (logFile == NULL) {
        fprintf(stderr, "log file open failed: %d\n", errno);
        spiClose(spiHandle);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read ADC value
        unsigned char rx[3];
        if (spiXfer(spiHandle, SPI_COMMAND, SPI_CONFIG, SPI_DUMMY, SPI_DUMMY, ADC_CHANNEL, 3, &rx) < 0) {
            fprintf(stderr, "SPI transfer failed: %d\n", spiErrno());
            continue;
        }

        // Extract ADC value
        unsigned int adcValue = ((rx[1] & 0x03) << 8) | rx[2];

