        float methaneConcentration = (float)adcValue * ADC_SCALE / 1023;

        // Log reading
        time_t now = time(NULL);
        struct tm *timeInfo = localtime(&now);
        fprintf(logFile, "%04d-%02d-%02d %02d:%02d:%02d %f PPM\n", timeInfo->tm_year + 1900, timeInfo->tm_mon + 1, timeInfo->tm_mday, timeInfo->tm_hour, timeInfo->tm_min, timeInfo->tm_sec, methaneConcentration);

        // Check for leak
        if (methaneConcentration > 1000) {
            fprintf(stderr, "LEAK DETECTED! Methane concentration: %f PPM\n", methaneConcentration);
        }
    }

    // Close log file
    fclose(logFile);

    // Close SPI handle
    spiClose(spiHandle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

