#define SCL_PIN 3
#define PRESSURE_OFFSET 0.5
#define PRESSURE_SENSITIVITY 0.1
#define PRESSURE_RANGE 100.0
#define LOG_FILE "pressure_log.txt"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up I2C pins
    if (gpioSetMode(SDA_PIN, PI_INPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SCL_PIN, PI_INPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (i2cInit(1, I2C_MODE_PCLK_PCS) < 0) {
        perror("i2cInit");
        gpioTerminate();
        return 1;
    }

    // Initialize ADS1115
    if (ads1115Init(1, 0, 0, 0) < 0) {
        perror("ads1115Init");
        i2cCleanUp();
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115
    if (ads1115SetGain(ADS1115_GAIN_2_144) < 0) {
        perror("ads1115SetGain");
        ads1115Deinit();
        i2cCleanUp();
        gpioTerminate();
        return 1;
    }

    // Configure I2C
    if (i2cSetClock(1, 100000) < 0) {
        perror("i2cSetClock");
        ads1115Deinit();
        i2cCleanUp();
        gpioTerminate();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        ads1115Deinit();
        i2cCleanUp();
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read ADC
        unsigned int adc_value = 0;
        if (ads1115Read(ADC_CHANNEL, &adc_value) < 0) {
            perror("ads1115Read");
            ads1115Deinit();
            i2cCleanUp();
            gpioTerminate();
            return 1;
        }

        // Validate ADC value
        if (adc_value < 0 || adc_value > 65535) {
            printf("Invalid ADC value: %u\n", adc_value);
            continue;
        }

        // Convert ADC value to voltage
        float voltage = (float)adc_value * (5.0 / 65535.0);

        // Apply offset and sensitivity
        float pressure = (voltage - PRESSURE_OFFSET) / PRESSURE_SENSITIVITY;

        // Validate pressure range
        if (pressure < 0 || pressure > PRESSURE_RANGE) {
            printf("Invalid pressure: %f\n", pressure);
            continue;
        }

        // Log pressure
        time_t now = time(NULL);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s %f\n", timestamp, pressure);
        printf("%s %f\n", timestamp, pressure);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    fclose(log_file);
    ads1115Deinit();
    i2cCleanUp();
    gpioTerminate();

    return 0;
}

