#define GPIO_MISO 9
#define GPIO_VREF 3.3

#define SPI_MODE 0
#define SPI_BIT_WIDTH 8
#define SPI_MAX_SPEED 1000000

#define TMP36_VREF 3.3
#define TMP36_MIN_TEMP -40
#define TMP36_MAX_TEMP 125

int main(int argc, char **argv) {
    int spi_fd, gpio_fd;
    gpiod_async_t *async;
    gpiod_async_pi_t *async_pi;
    spidev_t *spidev;
    struct spidev_request req;
    struct spidev_transfer transfer;
    struct stat sb;
    char log_file[256];
    char temp_str[10];
    int temp_celsius;
    int temp_int;
    int ret;

    // Initialize signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open SPI device
    if ((spi_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        perror("open");
        return 1;
    }

    // Configure SPI device
    if (ioctl(spi_fd, SPI_IOC_SET_MODE, SPI_MODE) < 0) {
        perror("ioctl");
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_SET_BIT_WIDTH, SPI_BIT_WIDTH) < 0) {
        perror("ioctl");
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_SET_MAX_SPEED, SPI_MAX_SPEED) < 0) {
        perror("ioctl");
        close(spi_fd);
        return 1;
    }

    // Open GPIO lines
    if ((gpio_fd = gpiod_async_open(GPIO_CE, GPIO CHIP, &async_pi)) < 0) {
        perror("gpiod_async_open");
        close(spi_fd);
        return 1;
    }

    // Open log file
    sprintf(log_file, "temperature_log.csv");
    if (access(log_file, F_OK) == 0) {
        if ((ret = open(log_file, O_RDWR | O_CREAT | O_TRUNC, 0644)) < 0) {
            perror("open");
            close(gpio_fd);
            gpiod_async_close(async_pi);
            close(spi_fd);
            return 1;
        }
    } else {
        if ((ret = open(log_file, O_RDWR | O_CREAT, 0644)) < 0) {
            perror("open");
            close(gpio_fd);
            gpiod_async_close(async_pi);
            close(spi_fd);
            return 1;
        }
    }

    // Configure SPI transfer
    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = NULL;
    transfer.tx_len = 0;
    transfer.rx_buf = NULL;
    transfer.rx_len = 0;
    transfer.num_transfers = 1;
    transfer.timeout = 1000;

    // Read ADC value
    while (1) {
        // Set CS line low
        if (gpiod_async_set_value(async_pi, GPIO_CE, 0) < 0) {
            perror("gpiod_async_set_value");
            break;
        }

        // Send SPI request
        if (spidev_request(spi_fd, &req, &transfer) < 0) {
            perror("spidev_request");
            break;
        }

        // Read ADC value
        if (spidev_read(spi_fd, &req, &transfer) < 0) {
            perror("spidev_read");
            break;
        }

        // Validate ADC value
        if (transfer.rx_len < 1 || transfer.rx_len > 2) {
            printf("Invalid ADC value\n");
            break;
        }
        temp_int = (transfer.rx_buf[0] << 8) | transfer.rx_buf[1];
        if (temp_int < 0 || temp_int > 4095) {
            printf("Invalid ADC value\n");
            break;
        }

        // Convert ADC value to voltage
        temp_celsius = (temp_int * GPIO_VREF / 4095.0) - 0.5;

        // Validate temperature
        if (temp_celsius < TMP36_MIN_TEMP || temp_celsius > TMP36_MAX_TEMP) {
            printf("Invalid temperature\n");
            break;
        }

        // Log temperature
        sprintf(temp_str, "%d,%d\n", time(NULL), temp_celsius);
        if (write(log_file, temp_str, strlen(temp_str)) < 0) {
            perror("write");
            break;
        }

        // Set CS line high
        if (gpiod_async_set_value(async_pi, GPIO_CE, 1) < 0) {
            perror("gpiod_async_set_value");
            break;
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Close log file
    if (close(log_file) < 0) {
        perror("close");
    }

    // Release GPIO lines
    if (gpiod_async_close(async_pi) < 0) {
        perror("gpiod_async_close");
    }

    // Release SPI device
    if (close(spi_fd) < 0) {
        perror("close");
    }

    return 0;
}

void sigint_handler(int sig) {
    // Release GPIO lines
    if (gpiod_async_close(async_pi) < 0) {
        perror("gpiod_async_close");
    }

    // Release SPI device
    if (close(spi_fd) < 0) {
        perror("close");
    }

    // Close log file
    if (close(log_file) < 0) {
        perror("close");
    }

    exit(0);
}

