#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>

#define SPI0 CS_PIN 8
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_MODE0 CS_PIN
#define ADXL335_X 0
#define ADXL335_Y 1
#define ADXL335_Z 2
#define ADXL335_G0 1.65
#define ADXL335_SENSITIVITY 300
#define ADXL335_G_THRESHOLD 2.0
#define LOG_FILE "impact_log.txt"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        printf("pigpio initialization failed\n");
        return 1;
    }

    // Set up SPI
    if (gpioSetMode(SPI0, PI_MODE_OUTPUT) < 0) {
        printf("Failed to set SPI mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetLevel(SPI0, PI_HIGH) < 0) {
        printf("Failed to set SPI high\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetLevel(SPI0, PI_LOW) < 0) {
        printf("Failed to set SPI low\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetLevel(SPI0, PI_LOW) < 0) {
        printf("Failed to set SPI low\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetLevel(SPI0, PI_HIGH) < 0) {
        printf("Failed to set SPI high\n");
        gpioTerminate();
        return 1;
    }

    // Open SPI
    if (spiOpen(SPI0, SPI_SPEED, SPI_MODE) < 0) {
        printf("Failed to open SPI\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    int log_fd = open(LOG_FILE, O_RDWR | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        printf("Failed to open log file\n");
        spiClose(SPI0);
        gpioTerminate();
        return 1;
    }

    // Set up ADXL335
    if (gpioSetLevel(ADXL335_X, PI_HIGH) < 0) {
        printf("Failed to set ADXL335 X\n");
        close(log_fd);
        spiClose(SPI0);
        gpioTerminate();
        return 1;
    }
    if (gpioSetLevel(ADXL335_Y, PI_HIGH) < 0) {
        printf("Failed to set ADXL335 Y\n");
        close(log_fd);
        spiClose(SPI0);
        gpioTerminate();
        return 1;
    }
    if (gpioSetLevel(ADXL335_Z, PI_HIGH) < 0) {
        printf("Failed to set ADXL335 Z\n");
        close(log_fd);
        spiClose(SPI0);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read ADXL335
        unsigned char adxl335_data[3];
        if (spiXfer(SPI0, adxl335_data, 3, 100) < 0) {
            printf("Failed to read ADXL335\n");
            close(log_fd);
            spiClose(SPI0);
            gpioTerminate();
            return 1;
        }

        // Compute acceleration magnitude
        float x = (adxl335_data[ADXL335_X] * 300) / 32767.0;
        float y = (adxl335_data[ADXL335_Y] * 300) / 32767.0;
        float z = (adxl335_data[ADXL335_Z] * 300) / 32767.0;
        float magnitude = sqrt(x * x + y * y + z * z);

        // Log data
        if (magnitude > ADXL335_G_THRESHOLD) {
            fprintf(log_fd, "%d,%d,%d,%f,%f,%f,IMPACT DETECTED\n", (int)time(NULL), (int)x, (int)y, (int)z, magnitude, magnitude);
        } else {
            fprintf(log_fd, "%d,%d,%d,%f,%f,%f\n", (int)time(NULL), (int)x, (int)y, (int)z, magnitude, magnitude);
        }

        // Check for SIGINT
        struct sigaction sa;
        sa.sa_handler = SIG_IGN;
        sigemptyset(&sa.sa_mask);
        sigaddset(&sa.sa_mask, SIGINT);
        if (sigaction(SIGINT, &sa, NULL) < 0) {
            printf("Failed to set SIGINT handler\n");
            close(log_fd);
            spiClose(SPI0);
            gpioTerminate();
            return 1;
        }

        // Sleep
        usleep(10000);
    }

    // Clean up
    close(log_fd);
    spiClose(SPI0);
    gpioTerminate();

    return 0;
}

