#define I2C_ADDRESS 0x67
#define I2C Bus 1
#define I2C_COMMAND 0x6845
#define I2C_READ 0x00
#define I2C_WRITE 0x01
#define I2C_SIZE 6

int main(int argc, char *argv[]) {
    // Initialize signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open I2C file descriptor
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set I2C bus number and address
    if (ioctl(fd, I2C_SLAVE, I2C_Bus) < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("environmental_data.csv", "a");
    if (log_file == NULL) {
        perror("fopen");
        close(fd);
        return 1;
    }

    while (1) {
        // Trigger high-precision reading
        if (ioctl(fd, I2C_COMMAND, I2C_WRITE) < 0) {
            perror("ioctl");
            sleep(5);
            continue;
        }

        // Wait for conversion to finish
        usleep(1000000);

        // Read 6 bytes from sensor
        char buffer[I2C_SIZE];
        if (read(fd, buffer, I2C_SIZE) < I2C_SIZE) {
            perror("read");
            sleep(5);
            continue;
        }

        // Apply calibration formulas
        uint8_t pressure = (buffer[0] << 8) | buffer[1];
        uint8_t temperature = (buffer[2] << 8) | buffer[3];
        uint8_t crc = buffer[4];
        uint8_t raw_temperature = (temperature & 0xFF);
        uint8_t raw_pressure = (pressure & 0xFF);
        float temperature_c = (raw_temperature - 40) * 0.01;
        float pressure_pa = (raw_pressure * 0.01);

        // Log data
        fprintf(log_file, "%s,%f,%f\n", time(NULL), temperature_c, pressure_pa);

        // Display data on console
        printf("Temperature: %.2f°C, Pressure: %.2f Pa\n", temperature_c, pressure_pa);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close log file and I2C file descriptor
    fclose(log_file);
    close(fd);

    return 0;
}

void sigint_handler(int sig) {
    printf("\nStopping...\n");
    exit(0);
}

void sigterm_handler(int sig) {
    printf("\nStopping...\n");
    exit(0);
}

