#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>
#include <libgpiod/libgpiod.h>
#include <pigpio.h>

#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_BITS 10
#define SPI_DUMMY 1
#define GPIO_Buzzer 18
#define GPIO_Flame 17
#define FILE_LOG "flame_log.txt"

int main() {
    // Initialize libgpiod
    gpiod_init();

    // Open log file
    int log_fd = open(FILE_LOG, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        return 1;
    }

    // Open SPI device
    int spidev_fd = open("/dev/spidev0.0", O_RDWR);
    if (spidev_fd < 0) {
        perror("open");
        return 1;
    }

    // Configure SPI
    struct spidev_config config = {
        .mode = SPI_MODE,
        .speed = SPI_SPEED,
        .bits = SPI_BITS,
        .dummy = SPI_DUMMY,
    };
    if (spidev_config(spidev_fd, &config) < 0) {
        perror("spidev_config");
        return 1;
    }

    // Open GPIO pins
    int gpio_fd = gpiod_open(GPIO_Buzzer, GPIO_DIR_OUT, GPIO_MODE_HIGH);
    if (gpio_fd < 0) {
        perror("gpiod_open");
        return 1;
    }
    gpiod_set_value(gpio_fd, GPIO_Buzzer, 1);

    int flame_fd = gpiod_open(GPIO_Flame, GPIO_DIR_IN, GPIO_MODE_INPUT);
    if (flame_fd < 0) {
        perror("gpiod_open");
        return 1;
    }

    // Read ambient temperature
    char temp_file[] = "ambient_temp.txt";
    struct stat sb;
    if (stat(temp_file, &sb) == -1) {
        printf("Error: %s not found\n", temp_file);
        printf("Using default temperature of 25.0°C\n");
        temp = 25.0;
    } else if (S_ISREG(sb.st_mode)) {
        FILE *file = fopen(temp_file, "r");
        if (file == NULL) {
            perror("fopen");
            return 1;
        }
        fscanf(file, "%f", &temp);
        fclose(file);
    } else {
        printf("Error: %s is not a file\n", temp_file);
        printf("Using default temperature of 25.0°C\n");
        temp = 25.0;
    }

    // Main loop
    while (1) {
        // Read ADC value
        int adc_value = 0;
        int retry = 0;
        while (retry < 3) {
            if (spidev_read(spidev_fd, &adc_value, 3) < 0) {
                perror("spidev_read");
                retry++;
                sleep(0.1);
            } else {
                break;
            }
        }
        if (retry >= 3) {
            printf("Error reading ADC value\n");
            continue;
        }

        // Convert ADC value to voltage
        int voltage = (adc_value >> 3) * 3.3 / 1023;

        // Calculate compensated voltage
        float compensated_voltage = voltage + (temp - 25.0) * 0.001;

        // Check for flame detection
        int flame = gpiod_get_value(flame_fd);
        if (flame == 1) {
            printf("%s,raw_adc,%f,voltage,%f,1\n", ctime(NULL), adc_value, compensated_voltage);
            gpiod_set_value(gpio_fd, GPIO_Buzzer, 1);
        } else {
            printf("%s,raw_adc,%f,voltage,%f,0\n", ctime(NULL), adc_value, compensated_voltage);
            gpiod_set_value(gpio_fd, GPIO_Buzzer, 0);
        }

        // Log temperature
        fprintf(log_fd, "%f,%f,%f,%d\n", time(NULL), adc_value, compensated_voltage, flame);

        // Sleep for 500ms
        sleep(0.5);
    }

    // Clean up
    gpiod_close(gpio_fd);
    gpiod_close(flame_fd);
    close(spidev_fd);
    close(log_fd);

    // Handle SIGINT
    signal(SIGINT, SIG_IGN);
    return 0;
}

