#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <json/json.h>

// Define constants
#define SPI_CHANNEL 0
#define LED_PIN 17
#define LED_HIGH 1
#define LED_LOW 0
#define HYST 5
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_FLAGS 0
#define SPI_CONFIG 0x80 | (SPI_CHANNEL << 4) | 0x00

// Define the JSON file
#define JSON_FILE "water_levels.json"

// Define the LED pin
int ledPin = LED_PIN;

// Define the SPI handle
int spiHandle = -1;

// Define the JSON file handle
FILE *jsonFile = NULL;

// Define the last water level reading
int lastWaterLevel = -1;

// Define the last water level timestamp
time_t lastWaterLevelTimestamp = 0;

// Define the hysteresis
int hysteresis = HYST;

// Define the interval between readings
int interval = 5000;

// Define the main loop
void mainLoop() {
    while (1) {
        // Read the water level
        int result = spiXfer(SPI_CONFIG, NULL, NULL, NULL, SPI_SPEED, SPI_MODE, SPI_FLAGS);
        if (result < 0) {
            pigpio_error("SPI transfer failed");
            continue;
        }

        // Parse the result
        int waterLevel = ((result[1] & 0x03) << 8) | result[2];

        // Convert the water level to a percentage
        waterLevel = (waterLevel * 100) / 1023;

        // Log the water level
        char timestamp[20];
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%3d", tm);
        char jsonEntry[256];
        sprintf(jsonEntry, "{\"timestamp\":\"%s\",\"water_level\":%d}", timestamp, waterLevel);
        if (jsonFile) {
            fprintf(jsonFile, "%s\n", jsonEntry);
            fflush(jsonFile);
        }

        // Check the water level
        if (waterLevel > lastWaterLevel + hysteresis && waterLevel > 75) {
            pigpio_set_mode(ledPin, PI_OUTPUT);
            pigpio_write(ledPin, LED_HIGH);
        } else if (waterLevel < lastWaterLevel - hysteresis && waterLevel < 70) {
            pigpio_set_mode(ledPin, PI_OUTPUT);
            pigpio_write(ledPin, LED_LOW);
        }

        // Update the last water level reading
        lastWaterLevel = waterLevel;
        lastWaterLevelTimestamp = now;

        // Sleep for the interval
        gpioDelay(interval);
    }
}

// Define the main function
int main() {
    // Initialize pigpio
    if (pigpio_init() < 0) {
        pigpio_error("pigpio_init failed");
        return 1;
    }

    // Open the SPI handle
    spiHandle = spi_open(0, SPI_CHANNEL, SPI_SPEED, SPI_MODE, SPI_FLAGS);
    if (spiHandle < 0) {
        pigpio_error("spi_open failed");
        pigpio_close();
        return 1;
    }

    // Open the JSON file
    jsonFile = fopen(JSON_FILE, "a");
    if (jsonFile == NULL) {
        pigpio_error("fopen failed");
        pigpio_close();
        return 1;
    }

    // Set the LED pin as an output
    pigpio_set_mode(ledPin, PI_OUTPUT);

    // Set the LED to low
    pigpio_write(ledPin, LED_LOW);

    // Start the main loop
    mainLoop();

    // Close the JSON file
    fclose(jsonFile);

    // Close the SPI handle
    spi_close(spiHandle);

    // Terminate pigpio
    pigpio_close();

    return 0;
}

