#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_CHANNEL 0
#define SPI_CE 8
#define SPI_CS 9
#define ADC_CHANNEL 0
#define LOG_FILE "soil_moisture.log"

int main(int argc, char *argv[]) {
    int gpio = -1;
    int spi = -1;
    int adc = -1;
    FILE *log_file = NULL;

    // Initialize pigpio
    if (gpio = pigpio_init(), gpio < 0) {
        fprintf(stderr, "pigpio_init() failed: %s\n", strerror(errno));
        return 1;
    }

    // Open SPI interface
    if (spi = gpio_export(SPI_CE, PI_INPUT), spi < 0) {
        fprintf(stderr, "gpio_export() failed: %s\n", strerror(errno));
        pigpio_close(gpio);
        return 1;
    }
    if (gpio = gpio_fsel(SPI_CE, PI_INPUT, PI_INT), gpio < 0) {
        fprintf(stderr, "gpio_fsel() failed: %s\n", strerror(errno));
        gpio_export(SPI_CE, PI_INPUT);
        gpio_close(spi);
        return 1;
    }
    if (spi = gpio_export(SPI_CS, PI_INPUT), spi < 0) {
        fprintf(stderr, "gpio_export() failed: %s\n", strerror(errno));
        gpio_fsel(SPI_CE, PI_INPUT, PI_INT);
        gpio_close(spi);
        gpio_close(gpio);
        return 1;
    }
    if (gpio = gpio_fsel(SPI_CS, PI_INPUT, PI_INT), gpio < 0) {
        fprintf(stderr, "gpio_fsel() failed: %s\n", strerror(errno));
        gpio_export(SPI_CS, PI_INPUT);
        gpio_export(SPI_CE, PI_INPUT);
        gpio_close(spi);
        gpio_close(gpio);
        return 1;
    }
    if (spi = gpio_mode(SPI_CE, PI_SPI, SPI_MODE, SPI_SPEED), spi < 0) {
        fprintf(stderr, "gpio_mode() failed: %s\n", strerror(errno));
        gpio_fsel(SPI_CS, PI_INPUT, PI_INT);
        gpio_fsel(SPI_CE, PI_INPUT, PI_INT);
        gpio_close(spi);
        gpio_close(gpio);
        return 1;
    }
    if (spi = gpio_mode(SPI_CS, PI_SPI, SPI_MODE, SPI_SPEED), spi < 0) {
        fprintf(stderr, "gpio_mode() failed: %s\n", strerror(errno));
        gpio_fsel(SPI_CS, PI_INPUT, PI_INT);
        gpio_fsel(SPI_CE, PI_INPUT, PI_INT);
        gpio_close(spi);
        gpio_close(gpio);
        return 1;
    }

    // Open ADC interface
    if (adc = spi_open(spi, SPI_CS, SPI_MODE, SPI_SPEED, SPI_CHANNEL, SPI_10BIT), adc < 0) {
        fprintf(stderr, "spi_open() failed: %s\n", strerror(errno));
        gpio_fsel(SPI_CS, PI_INPUT, PI_INT);
        gpio_fsel(SPI_CE, PI_INPUT, PI_INT);
        gpio_close(spi);
        gpio_close(gpio);
        return 1;
    }

    // Open log file
    if ((log_file = fopen(LOG_FILE, "a"), log_file == NULL) {
        fprintf(stderr, "fopen() failed: %s\n", strerror(errno));
        spi_close(adc);
        gpio_fsel(SPI_CS, PI_INPUT, PI_INT);
        gpio_fsel(SPI_CE, PI_INPUT, PI_INT);
        gpio_close(spi);
        gpio_close(gpio);
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    if (sigemptyset(&sa) < 0) {
        fprintf(stderr, "sigemptyset() failed: %s\n", strerror(errno));
        fclose(log_file);
        spi_close(adc);
        gpio_fsel(SPI_CS, PI_INPUT, PI_INT);
        gpio_fsel(SPI_CE, PI_INPUT, PI_INT);
        gpio_close(spi);
        gpio_close(gpio);
        return 1;
    }
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction() failed: %s\n", strerror(errno));
        sigemptyset(&sa);
        fclose(log_file);
        spi_close(adc);
        gpio_fsel(SPI_CS, PI_INPUT, PI_INT);
        gpio_fsel(SPI_CE, PI_INPUT, PI_INT);
        gpio_close(spi);
        gpio_close(gpio);
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction() failed: %s\n", strerror(errno));
        sigemptyset(&sa);
        fclose(log_file);
        spi_close(adc);
        gpio_fsel(SPI_CS, PI_INPUT, PI_INT);
        gpio_fsel(SPI_CE, PI_INPUT, PI_INT);
        gpio_close(spi);
        gpio_close(gpio);
        return 1;
    }

    // Main loop
