    struct spidev *spi;
    int ret;

    // Set up signal handler for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open SPI device
    spi = spidev_open(SPI_DEVICE, SPI_MODE, SPI_SPEED);
    if (spi == NULL) {
        perror("spidev_open");
        return 1;
    }

    // Configure SPI device
    ret = ioctl(spi, SPI_IOC_SET_MODE, SPI_MODE_0);
    if (ret < 0) {
        perror("ioctl");
        close(spi);
        return 1;
    }

    // Set up SPI data size
    ret = ioctl(spi, SPI_IOC_SET_SPEED, SPI_SPEED);
    if (ret < 0) {
        perror("ioctl");
        close(spi);
        return 1;
    }

    // Set up SPI data size
    ret = ioctl(spi, SPI_IOC_SET_BITS, SPI_3BIT);
    if (ret < 0) {
        perror("ioctl");
        close(spi);
        return 1;
    }

    // Set up SPI mode
    ret = ioctl(spi, SPI_IOC_SET_MODE, SPI_MODE_0);
    if (ret < 0) {
        perror("ioctl");
        close(spi);
        return 1;
    }

    // Open ADC device
    int adc_file = open("/dev/spidev0.0", O_RDWR);
    if (adc_file < 0) {
        perror("open");
        close(spi);
        return 1;
    }

    // Set up ADC channel
    ret = ioctl(adc_file, SPI_IOC_SET_CHANNEL, ADC_CHANNEL);
    if (ret < 0) {
        perror("ioctl");
        close(adc_file);
        close(spi);
        return 1;
    }

    while (1) {
        // Send SPI command
        ret = spidev_write(spi, SPI_DATA_SIZE, (void *) &0x00);
        if (ret < 0) {
            perror("spidev_write");
            break;
        }

        // Read ADC data
        char data[SPI_DATA_SIZE];
        ret = spidev_read(spi, SPI_DATA_SIZE, data);
        if (ret < 0) {
            perror("spidev_read");
            break;
        }

        // Calculate moisture percentage
        int raw_value = (data[0] << 8) | data[1];
        int moisture_percentage = (raw_value - CALIBRATION_DRY) * 100 / (CALIBRATION_WET - CALIBRATION_DRY);

        // Clamp moisture percentage
        moisture_percentage = (moisture_percentage < 0) ? 0 : (moisture_percentage > 100) ? 100 : moisture_percentage;

        // Log moisture percentage
        printf("Moisture percentage: %d%%\n", moisture_percentage);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close SPI device
    close(spi);
    close(adc_file);

    return 0;
}

