#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#define SPI_MODE SPI_MODE0
#define SPI_SPEED 1000000
#define SPI_DATA 0x00
#define SPI_CLOCK 0x01
#define SPI_CS 8
#define SPI_MISO 9
#define SPI_MOSI 10
#define SPI_SCK 11

#define ADC_CHANNEL 0
#define ADC_BITWIDTH 10
#define ADC_BITORDER MSBF
#define ADC_CLOCK 1000000
#define ADC_CONVERSION 0

#define PRESSURE_MIN 10
#define PRESSURE_MAX 150
#define PRESSURE_SPAN 140
#define PRESSURE_SCALE 0.5
#define PRESSURE_OFFSET 0.1

void sigint_handler(int sig) {
    pigpio_close();
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    sigaction(SIGINT, &sa, NULL);

    if (pigpio_init() < 0) {
        fprintf(stderr, "pigpio_init failed\n");
        return 1;
    }

    if (pigpio_spi_open(SPI_CS, SPI_MODE, SPI_SPEED) < 0) {
        fprintf(stderr, "pigpio_spi_open failed\n");
        pigpio_close();
        return 1;
    }

    if (pigpio_spi_config(SPI_CS, SPI_MODE, SPI_SPEED) < 0) {
        fprintf(stderr, "pigpio_spi_config failed\n");
        pigpio_spi_close();
        return 1;
    }

    if (pigpio_spi_write(SPI_CS, SPI_DATA, 0x00) < 0) {
        fprintf(stderr, "pigpio_spi_write failed\n");
        pigpio_spi_close();
        return 1;
    }

    if (pigpio_spi_write(SPI_CS, SPI_DATA, 0x01) < 0) {
        fprintf(stderr, "pigpio_spi_write failed\n");
        pigpio_spi_close();
        return 1;
    }

    while (1) {
        int adc_value;
        if (pigpio_spi_read(SPI_CS, SPI_MISO, &adc_value, 1) < 0) {
            fprintf(stderr, "pigpio_spi_read failed\n");
            pigpio_spi_close();
            return 1;
        }

        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "ADC value out of range\n");
            pigpio_spi_close();
            return 1;
        }

        double voltage = (adc_value * 3.3) / 1023.0;
        double pressure = (voltage - PRESSURE_OFFSET) / PRESSURE_SCALE * PRESSURE_SPAN + PRESSURE_MIN;

        time_t now = time(NULL);
        struct tm* ltm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", ltm);

        printf("%s %f\n", timestamp, pressure);

        usleep(1000000);
    }

    pigpio_spi_close();
    pigpio_close();
    return 0;
}

