#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define SPI_MODE 0
#define SPI_BIT_PER_WORD 8
#define SPI_CLOCK_SPEED 1000000
#define SPI_CHANNEL 0
#define MCP3008_READ_COMMAND 0x03
#define MCP3008_CONFIG_BYTE 0x00
#define MCP3008_DONT_CARE_BYTE 0xFF
#define MCP3008_CHANNEL 0
#define SPI_FILE "/dev/spidev0.0"

int main() {
    int fd;
    struct spidev_args args;
    struct spidev_config config;
    unsigned char readBuffer[3];
    unsigned int moisturePercentage;
    int ret;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open SPI device
    if ((fd = open(SPI_FILE, O_RDWR)) < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Configure SPI
    memset(&args, 0, sizeof(args));
    args.m mode = SPI_MODE;
    args.m bits = SPI_BIT_PER_WORD;
    args.m speed = SPI_CLOCK_SPEED;
    if (ioctl(fd, SPI_IOC_SETCONFIG, &config) < 0) {
        perror("ioctl");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set channel 0
    if (ioctl(fd, SPI_IOC_SETBIT, &args) < 0) {
        perror("ioctl");
        close(fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read from SPI
        if (read(fd, readBuffer, 3) < 3) {
            perror("read");
            close(fd);
            gpioTerminate();
            return 1;
        }

        // Extract 10-bit result
        unsigned int result = (readBuffer[0] << 8) | readBuffer[1];

        // Clamp to 0-100 range
        moisturePercentage = (result / 1023) * 100;

        // Log moisture percentage
        printf("%.2f%%\r", moisturePercentage);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    close(fd);
    gpioTerminate();

    return 0;
}

