#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CE0 8
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_DATA 0
#define SPI_CS 1
#define NUM_CHANNELS 4
#define CSV_FILE "environmental_data.csv"

int main(int argc, char **argv) {
    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Open SPI device
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    // Configure SPI0
    struct spidev_config config;
    memset(&config, 0, sizeof(config));
    config.cs_gpio = GPIO_CE0;
    config.mode = SPI_MODE;
    config.speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_SETCONFIG, &config) == -1) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    // Open CSV file
    int csv_fd = open(CSV_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (csv_fd == -1) {
        perror("open");
        close(fd);
        return 1;
    }

    // Open libgpiod lines
    struct gpiod_context *ctx;
    struct gpiod_line *line;
    ctx = gpiod_context_new(NULL);
    if (!ctx) {
        perror("gpiod_context_new");
        close(fd);
        close(csv_fd);
        return 1;
    }
    line = gpiod_line_new(ctx, GPIO_CE0, GpioLineDirectionOutput, NULL);
    if (!line) {
        gpiod_context_free(ctx);
        perror("gpiod_line_new");
        close(fd);
        close(csv_fd);
        return 1;
    }
    if (gpiod_line_set_value(line, 0) == -1) {
        gpiod_line_free(line);
        gpiod_context_free(ctx);
        perror("gpiod_line_set_value");
        close(fd);
        close(csv_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read voltage values
        struct spidev_request req;
        memset(&req, 0, sizeof(req));
        req.cs = SPI_CS;
        req.mode = SPI_MODE;
        req.speed = SPI_SPEED;
        req.buf = malloc(NUM_CHANNELS * sizeof(int));
        if (!req.buf) {
            perror("malloc");
            gpiod_line_free(line);
            gpiod_context_free(ctx);
            close(fd);
            close(csv_fd);
            return 1;
        }
        if (ioctl(fd, SPI_IOC_READ, &req) == -1) {
            perror("ioctl");
            free(req.buf);
            gpiod_line_free(line);
            gpiod_context_free(ctx);
            close(fd);
            close(csv_fd);
            return 1;
        }
        for (int i = 0; i < NUM_CHANNELS; i++) {
            req.buf[i] = req.buf[i] * 2.048 / 65535.0;
        }

        // Log voltage values
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(csv_fd, "%s,%d\n", timestamp, req.buf[0]);
        for (int i = 1; i < NUM_CHANNELS; i++) {
            fprintf(csv_fd, "%d,%d\n", i, req.buf[i]);
        }

        // Release resources
        free(req.buf);
    }

    // Clean up
    gpiod_line_free(line);
    gpiod_context_free(ctx);
    close(fd);
    close(csv_fd);
    return 0;
}

void sigint_handler(int sig) {
    // Clean up
    gpiod_line_free(line);
    gpiod_context_free(ctx);
    close(fd);
    close(csv_fd);
    exit(0);
}

