#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>

#define BUFFER_SIZE 20
#define BUFFER_INDEX 0
#define BUFFER_TIMESTAMP 1
#define BUFFER_MOISTURE 2
#define BUFFER_PUMP 3
#define BUFFER_MAX 1000
#define BUFFER_MIN 300
#define BUFFER_HYSTERESIS 100
#define BUFFER_LOG_FILE "moisture_log.txt"

int buffer[BUFFER_SIZE][3];
int buffer_index = 0;
int pump_state = 0;
int moisture_threshold_low = BUFFER_MIN;
int moisture_threshold_high = BUFFER_MAX + BUFFER_HYSTERESIS;
int moisture_threshold_hysteresis = BUFFER_HYSTERESIS;
int log_index = 0;
int log_size = 0;
int log_timestamp = 0;
int log_moisture = 0;
int log_pump = 0;
int spi_ce = 0;
int spi_mosi = 10;
int spi_miso = 9;
int spi_sclk = 11;
int relay_pin = 17;
int timer_id = -1;

void init_pigpio() {
    if (gpioInitialise() < 0) {
        printf("Error initializing pigpio\n");
        exit(1);
    }
}

void init_spi() {
    if (gpioSetMode(spi_ce, PI_MODE_OUTPUT) < 0) {
        printf("Error setting SPI CE pin mode\n");
        exit(1);
    }
    if (gpioSetMode(spi_mosi, PI_MODE_OUTPUT) < 0) {
        printf("Error setting SPI MOSI pin mode\n");
        exit(1);
    }
    if (gpioSetMode(spi_miso, PI_MODE_INPUT) < 0) {
        printf("Error setting SPI MISO pin mode\n");
        exit(1);
    }
    if (gpioSetMode(spi_sclk, PI_MODE_OUTPUT) < 0) {
        printf("Error setting SPI SCLK pin mode\n");
        exit(1);
    }
    if (gpioSetLevel(spi_ce, 1) < 0) {
        printf("Error setting SPI CE pin high\n");
        exit(1);
    }
}

void spi_transfer(int data) {
    if (gpioWrite(spi_ce, 0) < 0) {
        printf("Error setting SPI CE pin low\n");
        exit(1);
    }
    if (gpioWrite(spi_mosi, data & 0x01) < 0) {
        printf("Error writing SPI MOSI data\n");
        exit(1);
    }
    if (gpioRead(spi_miso) < 0) {
        printf("Error reading SPI MISO data\n");
        exit(1);
    }
    if (gpioWrite(spi_ce, 1) < 0) {
        printf("Error setting SPI CE pin high\n");
        exit(1);
    }
}

void read_moisture() {
    int data = 0;
    if (spi_transfer(0x00) < 0) {
        printf("Error reading moisture data\n");
        exit(1);
    }
    data = (spi_transfer(0x00) << 8) | spi_transfer(0x00);
    if (data < BUFFER_MIN) {
        pump_state = 1;
    } else if (data > BUFFER_MAX) {
        pump_state = 0;
    } else {
        if (data < moisture_threshold_low - moisture_threshold_hysteresis) {
            pump_state = 1;
        } else if (data > moisture_threshold_high + moisture_threshold_hysteresis) {
            pump_state = 0;
        } else {
            pump_state = 0;
        }
    }
    log_index = (log_index + 1) % BUFFER_SIZE;
    log_timestamp = time(NULL);
    log_moisture = data;
    log_pump = pump_state;
    buffer[log_index][BUFFER_TIMESTAMP] = log_timestamp;
    buffer[log_index][BUFFER_MOISTURE] = log_moisture;
    buffer[log_index][BUFFER_PUMP] = log_pump;
    log_size = (log_size + 1) % BUFFER_SIZE;
}

void log_buffer() {
    FILE *log_file = fopen(BUFFER_LOG_FILE, "a");
    if (log_file == NULL) {
        printf("Error opening log file\n");
        exit(1);
    }
    for (int i = 0; i < BUFFER_SIZE; i++) {
        fprintf(log_file, "%d %d %d %d\n", buffer[i][BUFFER_TIMESTAMP], buffer[i][BUFFER_MOISTURE], buffer[i][BUFFER_PUMP]);
    }
    fclose(log_file);
}

void timer_callback(int id) {
    read_moisture();
    log_buffer();
}

int main() {
    init_pigpio();
    init_spi();
    if (gpioWrite(relay_pin, 0) < 0) {
        printf("Error setting relay pin low\n");
        exit(1);
    }
    if (gpioWrite(spi_ce, 0) < 0) {
        printf("Error setting SPI CE pin low\n");
        exit(1);
