#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <unistd.h>
#include <errno.h>

#define I2C_ADDRESS 0x57
#define I2C Bus 1
#define MAX_LOG_FILE "health_log.txt"

// Structure to hold sensor data
typedef struct {
    uint16_t spo2;
    uint16_t hr;
} sensor_data_t;

// Function to read sensor data
sensor_data_t read_sensor_data(pigpio *gpio) {
    sensor_data_t data;
    uint8_t buffer[6];

    // Read FIFO data register in 6-byte bursts
    if (gpio->i2c_read(I2C Bus, I2C_ADDRESS, buffer, 6) != 6) {
        syslog(LOG_ERR, "I2C read error: %d", errno);
        return (sensor_data_t){0, 0};
    }

    // Extract SpO2 and IR data
    data.spo2 = (buffer[0] << 8) | buffer[1];
    data.hr = (buffer[2] << 8) | buffer[3];

    return data;
}

// Function to compute SpO2 using ratio-of-ratios method
float compute_spo2(uint16_t spo2, uint16_t hr) {
    // Simple implementation of ratio-of-ratios method
    // This is a placeholder, you may need to adjust the coefficients
    return (float)spo2 / (hr * 0.01);
}

// Function to detect peak on IR signal
int detect_peak(uint16_t ir) {
    // Simple peak detection using thresholding
    // This is a placeholder, you may need to adjust the threshold
    return (ir > 128) ? 1 : 0;
}

// Function to log data to file
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(stderr, "Timestamp: %s SpO2: %d HR: %d\n", timestamp, data.spo2, data.hr);
    fprintf(FILE *log_file, "%s SpO2: %d HR: %d\n", timestamp, data.spo2, data.hr);
}

// Function to handle sensor initialization
void init_sensor(pigpio *gpio) {
    // Reset sensor
    gpio->i2c_write(I2C Bus, I2C_ADDRESS, 0x06, 0x40);

    // Clear interrupts
    gpio->i2c_write(I2C Bus, I2C_ADDRESS, 0x0C, 0x00);

    // Configure SpO2 mode
    gpio->i2c_write(I2C Bus, I2C_ADDRESS, 0x03, 0x03);

    // Set SPO2_CONFIG
    gpio->i2c_write(I2C Bus, I2C_ADDRESS, 0x08, 0x27);

    // Set LED pulse amplitudes
    gpio->i2c_write(I2C Bus, I2C_ADDRESS, 0x09, 0x24);
    gpio->i2c_write(I2C Bus, I2C_ADDRESS, 0x0A, 0x24);
}

int main(int argc, char **argv) {
    pigpio *gpio;
    sensor_data_t data;
    FILE *log_file;

    // Initialize pigpio
    if (gpio = pigpio_init()) {
        syslog(LOG_ERR, "pigpio initialization failed: %d", gpio->err);
        return 1;
    }

    // Open log file
    log_file = fopen(MAX_LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %d", errno);
        pigpio_close(gpio);
        return 1;
    }

    // Verify sensor presence
    if (gpio->i2c_read(I2C Bus, I2C_ADDRESS, NULL, 1) != 1) {
        syslog(LOG_ERR, "Sensor not found");
        pigpio_close(gpio);
        fclose(log_file);
        return 1;
    }

    // Initialize sensor
    init_sensor(gpio);

    while (1) {
        // Read sensor data
        data = read_sensor_data(gpio);

        // Compute SpO2 and HR
        float spo2 = compute_spo2(data.spo2, data.hr);
        int hr = detect_peak(data.hr);

        // Log data
        if (spo2 < 95 || hr > 100) {
            log_data(data);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    pigpio_close(gpio);
    fclose(log_file);
    return 0;
}

