#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>

#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_CE0 17
#define SPI_MOSI 23
#define SPI_MISO 24
#define SPI_SCK 25
#define SPI_CS 0
#define SPI Bus 0
#define VREF 3.3

int main() {
    int spi_fd;
    int ret;
    char rx_buf[3];
    char timestamp[32];
    char filename[] = "analog_log.csv";
    struct stat sb;
    struct timespec t;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open SPI file
    if ((spi_fd = open(filename, O_RDWR | O_CREAT | O_TRUNC, 0644)) < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set up SPI
    if (gpioSetMode(SPI_CE0, PI_INPUT) < 0) {
        perror("gpioSetMode");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SPI_MOSI, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SPI_MISO, PI_INPUT) < 0) {
        perror("gpioSetMode");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SPI_SCK, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SPI_CS, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up SPI
    if (gpioSetClock(SPI Bus, SPI_SPEED, SPI_MODE) < 0) {
        perror("gpioSetClock");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Open SPI file for writing
    if (fstat(spi_fd, &sb) < 0) {
        perror("fstat");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Send SPI command
        if (gpioWrite(SPI_CE0, 0x01) < 0) {
            perror("gpioWrite");
            continue;
        }
        if (gpioWrite(SPI_CE0, (0x03 << 4)) < 0) {
            perror("gpioWrite");
            continue;
        }
        if (gpioWrite(SPI_CE0, 0x00) < 0) {
            perror("gpioWrite");
            continue;
        }

        // Read SPI data
        if (gpioRead(SPI_MISO, rx_buf, 3, 100) < 0) {
            perror("gpioRead");
            continue;
        }

        // Assemble 10-bit reading
        int value = (rx_buf[1] & 0x3F) | ((rx_buf[2] & 0x3F) << 6);

        // Calculate voltage
        double voltage = (value * VREF) / 1023.0;

        // Log data
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", localtime(&now));
        fprintf(spi_fd, "%s,%d,%f\n", timestamp, 0, voltage);

        // Sleep
        nanosleep(&t, NULL);
    }

    // Close SPI file
    close(spi_fd);

    // Terminate pigpio
    gpioTerminate();

    // Close CSV file
    if (close(spi_fd) < 0) {
        perror("close");
    }

    return 0;
}

