#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>
#include <libgpiod/libgpiod.h>

#define I2C_ADDRESS 0x48
#define RELAY_PIN 17
#define REED_PIN 27
#define ADC_CHANNEL 0
#define RELAY_VALUE 1
#define REED_VALUE 0
#define SAMPLES 10
#define INTERVAL 50
#define POLL_INTERVAL 200
#define THRESHOLD 0.8
#define LOG_FILE "/var/log/door_events.log"

int main() {
    // Initialize libgpiod
    gpiod_init();

    // Open I2C file descriptor
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set I2C address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    // Set up GPIO lines
    gpiod_context_t ctx;
    gpiod_context_new(&ctx);
    gpiod_line_t relay_line, reed_line;
    gpiod_line_new(&relay_line, RELAY_PIN, GpioDirectionOut, &ctx);
    gpiod_line_new(&reed_line, REED_PIN, GpioDirectionIn, &ctx);

    // Set up relay and reed lines
    gpiod_line_set_value(&relay_line, RELAY_VALUE);
    gpiod_line_set_value(&reed_line, REED_VALUE);

    // Take initial baseline samples
    double baseline_values[SAMPLES];
    for (int i = 0; i < SAMPLES; i++) {
        gpiod_line_read(&reed_line, NULL, NULL);
        usleep(50);
        gpiod_line_read(&reed_line, NULL, NULL);
        double value = gpiod_line_get_value(&reed_line);
        baseline_values[i] = value;
    }

    // Calculate initial threshold
    double threshold = 0;
    for (int i = 0; i < SAMPLES; i++) {
        threshold += baseline_values[i];
    }
    threshold /= SAMPLES;

    // Poll ADC and check for door opening
    while (1) {
        gpiod_line_read(&reed_line, NULL, NULL);
        usleep(POLL_INTERVAL);
        gpiod_line_read(&reed_line, NULL, NULL);
        double value = gpiod_line_get_value(&reed_line);
        if (value < threshold * THRESHOLD) {
            gpiod_line_set_value(&relay_line, RELAY_VALUE);
            usleep(3000);
            gpiod_line_set_value(&relay_line, RELAY_VALUE);
            gpiod_line_read(&reed_line, NULL, NULL);
            if (gpiod_line_get_value(&reed_line) == REED_VALUE) {
                FILE *log_file = fopen(LOG_FILE, "a");
                if (log_file == NULL) {
                    perror("fopen");
                    continue;
                }
                fprintf(log_file, "%d.%03d door opened\n", time(NULL) / 1000, (time(NULL) % 1000));
                fclose(log_file);
            } else {
                FILE *log_file = fopen(LOG_FILE, "a");
                if (log_file == NULL) {
                    perror("fopen");
                    continue;
                }
                fprintf(log_file, "%d.%03d door not opened\n", time(NULL) / 1000, (time(NULL) % 1000));
                fclose(log_file);
            }
        }
    }

    // Clean up
    gpiod_line_release(&reed_line);
    gpiod_line_release(&relay_line);
    gpiod_context_free(&ctx);
    close(fd);

    return 0;
}

