#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>
#include <linux/spi/spidev.h>

#define SPI0_BASE 0x3F200000
#define CS0 GPIO_8
#define CS1 GPIO_7
#define CS2 GPIO_25
#define SPI0_MOSI GPIO_10
#define SPI0_MISO GPIO_9
#define SPI0_SCLK GPIO_11
#define SPI0_SPEED 1000000
#define SPI0_MODE 0
#define SPI0_CPOL 0
#define SPI0_CPHA 0
#define SPI0_CHANNEL 0

#define CSV_FILE "soil_moisture_log.csv"

int main() {
    // Initialize libgpiod
    gpiod_init();

    // Open SPI0
    int spi0_fd = spidev_open(SPI0_BASE, SPI0_MOSI, SPI0_MISO, SPI0_SCLK, SPI0_SPEED, SPI0_MODE, SPI0_CPOL, SPI0_CPHA);
    if (spi0_fd < 0) {
        perror("spidev_open");
        return 1;
    }

    // Open CSV file
    int csv_fd = open(CSV_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (csv_fd < 0) {
        perror("open");
        return 1;
    }

    // Open CS lines
    gpiod_line_t cs0, cs1, cs2;
    cs0 = gpiod_line_new(SPI0_BASE, CS0, GPIOD_LINE_DIR_OUT, GPIOD_LINE_TYPE_GPIO, GPIOD_LINE_MODE_HIGH);
    if (!cs0) {
        perror("gpiod_line_new");
        return 1;
    }
    cs1 = gpiod_line_new(SPI0_BASE, CS1, GPIOD_LINE_DIR_OUT, GPIOD_LINE_TYPE_GPIO, GPIOD_LINE_MODE_HIGH);
    if (!cs1) {
        gpiod_line_destroy(cs0);
        perror("gpiod_line_new");
        return 1;
    }
    cs2 = gpiod_line_new(SPI0_BASE, CS2, GPIOD_LINE_DIR_OUT, GPIOD_LINE_TYPE_GPIO, GPIOD_LINE_MODE_HIGH);
    if (!cs2) {
        gpiod_line_destroy(cs0);
        gpiod_line_destroy(cs1);
        perror("gpiod_line_new");
        return 1;
    }

    // Open SPI0
    if (spidev_ioctl(spi0_fd, SPI_IOC_SET_MODE, SPI0_MODE) < 0) {
        perror("spidev_ioctl");
        return 1;
    }
    if (spidev_ioctl(spi0_fd, SPI_IOC_SET_CPOL, SPI0_CPOL) < 0) {
        perror("spidev_ioctl");
        return 1;
    }
    if (spidev_ioctl(spi0_fd, SPI_IOC_SET_CPHA, SPI0_CPHA) < 0) {
        perror("spidev_ioctl");
        return 1;
    }

    // Open CSV file for writing
    if (fputs("timestamp,sensor1,sensor2,sensor3\n", csv_fd) < 0) {
        perror("fputs");
        return 1;
    }

    // Main loop
    struct timespec start;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        // Set CS lines high
        gpiod_line_set_level(cs0, 1);
        gpiod_line_set_level(cs1, 1);
        gpiod_line_set_level(cs2, 1);

        // Read sensor values
        int sensor1 = 0, sensor2 = 0, sensor3 = 0;
        if (spidev_read(spi0_fd, (void *)&sensor1, 3) < 0) {
            sensor1 = -1;
        }
        if (spidev_read(spi0_fd, (void *)&sensor2, 3) < 0) {
            sensor2 = -1;
        }
        if (spidev_read(spi0_fd, (void *)&sensor3, 3) < 0) {
            sensor3 = -1;
        }

        // Convert sensor values
        sensor1 = (sensor1 & 0x3F) >> 2;
        sensor2 = (sensor2 & 0x3F) >> 2;
        sensor3 = sensor3 & 0xFF;

        // Log sensor values
        if (fputs(&start.tv_sec, csv_fd) < 0) {
            perror("fputs");
            return 1;
        }
        if (fputs(",", csv_fd) < 0) {
            perror("fputs");
            return 1;
        }
        if (fputs(&sensor1, csv_fd) < 0) {
            perror("fputs");
            return 1;
        }
        if (fputs(",", csv_fd) < 0) {
            perror("fputs");
            return 1;
        }
        if (fputs(&sensor2, csv_fd) < 0) {
            perror("fputs");
            return 1;
        }
        if (fputs(",", csv_fd) < 0) {
            perror("fputs");
            return 1;
        }
        if (fputs(&sensor3, csv_fd) < 0) {
            perror("fputs");
            return 1;
        }
        if (fputs("\n", csv_fd) < 0) {
            perror("fputs");
            return 1;
        }

        // Wait 5 seconds
        struct timespec end;
        clock_gettime(CLOCK_MONOTONIC, &end);
        timespec_diff(&end, &start, &start);
        timespec_diff(&end, &start, &start);
        if (timespec_diff(&end, &start).tv_sec > 5) {
            break;
        }
    }

    // Close CSV file
    if (close(csv_fd) < 0) {
        perror("close");
        return 1;
    }

    // Close SPI0
    if (spidev_close(spi0_fd) < 0) {
        perror("spidev_close");
        return 1;
    }

    // Destroy CS lines
    gpiod_line_destroy(cs2);
    gpiod_line_destroy(cs1);
    gpiod_line_destroy(cs0);

    // Exit
    return 0;
}

