        if (fputs(&sensor3, csv_fd) < 0) {
            perror("fputs");
            return 1;
        }
        if (fputs("\n", csv_fd) < 0) {
            perror("fputs");
            return 1;
        }

        // Wait 5 seconds
        struct timespec end;
        clock_gettime(CLOCK_MONOTONIC, &end);
        timespec_diff(&end, &start, &start);
        timespec_diff(&end, &start, &start);
        if (timespec_diff(&end, &start).tv_sec > 5) {
            break;
        }
    }

    // Close CSV file
    if (close(csv_fd) < 0) {
        perror("close");
        return 1;
    }

    // Close SPI0
    if (spidev_close(spi0_fd) < 0) {
        perror("spidev_close");
        return 1;
    }

    // Destroy CS lines
    gpiod_line_destroy(cs2);
    gpiod_line_destroy(cs1);
    gpiod_line_destroy(cs0);

    // Exit
    return 0;
}
```

This code uses libgpiod to control the CS lines and spidev to communicate with the SPI0 device. It logs the sensor values to a CSV file every 5 seconds. The code handles errors and releases resources on all exit paths.

