#define SPI_MODE SPI_MODE0
#define SPI_SPEED 1000000
#define SPI_DATA 0x00
#define SPI_CLOCK 0x01
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_CE 8
#define SPI_CS 0

#define EMA_ALPHA 0.1
#define THRESHOLD 0.2
#define LOG_FILE "/var/log/sound_events.log"

