#include <string.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>

#define I2C_ADDRESS 0x48
#define I2C_FILE "/dev/i2c-1"
#define GPIO_PIN 17
#define SAMPLE_RATE 100
#define CONTROL_BYTE 0x00

int main() {
    int fd;
    unsigned char control_byte = CONTROL_BYTE;
    unsigned char dummy_read;
    unsigned char sample;
    int gpio;
    struct i2c_file *i2c_file;
    struct i2c_file *i2c_file_lock;

    // Open I2C file descriptor
    fd = open(I2C_FILE, O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Lock I2C file descriptor
    i2c_file = i2c_open(fd, I2C_ADDRESS, 0);
    if (i2c_file == NULL) {
        perror("i2c_open");
        close(fd);
        return 1;
    }

    // Lock I2C file descriptor for exclusive access
    i2c_file_lock = i2c_lock(i2c_file);
    if (i2c_file_lock == NULL) {
        perror("i2c_lock");
        close(fd);
        i2c_close(i2c_file);
        return 1;
    }

    // Configure PCF8591 for single-ended mode on channel 0
    if (ioctl(i2c_file_lock, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(fd);
        i2c_unlock(i2c_file_lock);
        i2c_close(i2c_file);
        return 1;
    }
    if (ioctl(i2c_file_lock, I2C_SET_MODE, 0) < 0) {
        perror("ioctl");
        close(fd);
        i2c_unlock(i2c_file_lock);
        i2c_close(i2c_file);
        return 1;
    }
    if (ioctl(i2c_file_lock, I2C_SET_CHANNEL, 0) < 0) {
        perror("ioctl");
        close(fd);
        i2c_unlock(i2c_file_lock);
        i2c_close(i2c_file);
        return 1;
    }
    if (ioctl(i2c_file_lock, I2C_SET_MODE, 0x01) < 0) {
        perror("ioctl");
        close(fd);
        i2c_unlock(i2c_file_lock);
        i2c_close(i2c_file);
        return 1;
    }

    // Set control byte
    if (ioctl(i2c_file_lock, I2C_WRITE, &control_byte) < 0) {
        perror("ioctl");
        close(fd);
        i2c_unlock(i2c_file_lock);
        i2c_close(i2c_file);
        return 1;
    }

    // Read dummy byte to discard it
    if (read(i2c_file_lock, &dummy_read, 1) < 0) {
        perror("read");
        close(fd);
        i2c_unlock(i2c_file_lock);
        i2c_close(i2c_file);
        return 1;
    }

    // Set up GPIO pin for output
    gpio = gpio_get(gpio_get_number(GPIO_PIN));
    if (gpio < 0) {
        perror("gpio_get");
        close(fd);
        i2c_unlock(i2c_file_lock);
        i2c_close(i2c_file);
        return 1;
    }
    if (gpio_set_mode(gpio, GPIO_MODE_OUTPUT) < 0) {
        perror("gpio_set_mode");
        gpio_close(gpio);
        close(fd);
        i2c_unlock(i2c_file_lock);
        i2c_close(i2c_file);
        return 1;
    }

    while (1) {
        // Read sample
        if (read(i2c_file_lock, &sample, 1) < 0) {
            perror("read");
            close(fd);
            i2c_unlock(i2c_file_lock);
            i2c_close(i2c_file);
            gpio_close(gpio);
            return 1;
        }

        // Print sample value
        printf("%u\n", sample);

        // Sleep for sample rate
        usleep(SAMPLE_RATE * 1000);
    }

    // Clean up
    gpio_close(gpio);
    i2c_unlock(i2c_file_lock);
    i2c_close(i2c_file);
    close(fd);

    return 0;
}

