#include <pigpio.h>
#include <syslog.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define BUFFER_SIZE 10
#define THRESHOLD 500
#define SAMPLE_RATE 1
#define GPIO_SHUTDOWN 27

int main(int argc, char **argv) {
    int i, j;
    int gpio;
    int adc_channel = 0;
    int i2c_address = 0x48;
    int i2c_bus = 1;
    int sample_rate = SAMPLE_RATE;
    int threshold = THRESHOLD;
    int gpio_shutdown = GPIO_SHUTDOWN;
    int buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int last_reading = 0;
    int last_reading_index = 0;
    int error = 0;
    struct timespec start_time;
    struct timespec end_time;
    struct timespec interval;

    // Initialize pigpio
    if (gpio = pigpio_init()) {
        syslog(LOG_ERR, "pigpio initialization failed");
        return 1;
    }

    // Initialize I2C handle
    if (gpio_i2c_open(i2c_bus, i2c_address, &error) != 0) {
        syslog(LOG_ERR, "I2C initialization failed");
        pigpio_close(gpio);
        return 1;
    }

    // Initialize ADC handle
    if (gpio_i2c_adc_open(i2c_bus, i2c_address, 0, &error) != 0) {
        syslog(LOG_ERR, "ADC initialization failed");
        gpio_i2c_close(i2c_bus, i2c_address);
        pigpio_close(gpio);
        return 1;
    }

    // Configure ADC
    if (gpio_i2c_adc_config(i2c_bus, i2c_address, 0, 0, 0, 0, &error) != 0) {
        syslog(LOG_ERR, "ADC configuration failed");
        gpio_i2c_close(i2c_bus, i2c_address);
        pigpio_close(gpio);
        return 1;
    }

    // Configure GPIO
    if (gpio_mode(gpio_shutdown, GPIO_MODE_OUTPUT) != 0) {
        syslog(LOG_ERR, "GPIO shutdown configuration failed");
        gpio_i2c_close(i2c_bus, i2c_address);
        pigpio_close(gpio);
        return 1;
    }

    // Initialize circular buffer
    memset(buffer, 0, sizeof(buffer));

    // Start sampling
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (1) {
        // Sample ADC
        int raw_voltage;
        if (gpio_i2c_adc_read(i2c_bus, i2c_address, 0, 0, &raw_voltage, &error) != 0) {
            syslog(LOG_ERR, "ADC read failed");
            continue;
        }

        // Validate voltage reading
        if (raw_voltage < 0 || raw_voltage > 3.3) {
            syslog(LOG_ERR, "Invalid voltage reading");
            continue;
        }

        // Calculate magnetic field strength
        double magnetic_field = (raw_voltage - 2.5) / 1.4;

        // Store reading in buffer
        if (buffer_index == BUFFER_SIZE) {
            buffer_index = 0;
        }
        buffer[buffer_index] = magnetic_field;
        buffer_index++;

        // Calculate rolling average
        double rolling_average = 0;
        for (i = 0; i < BUFFER_SIZE; i++) {
            rolling_average += buffer[i];
        }
        rolling_average /= BUFFER_SIZE;

        // Check threshold
        if (rolling_average > threshold) {
            gpio_write(gpio_shutdown, 1);
            syslog(LOG_INFO, "Threshold exceeded, shutting down");
        }

        // Log reading
        syslog(LOG_INFO, "Magnetic field: %.2f Gauss", magnetic_field);

        // Sleep for sample rate
        clock_gettime(CLOCK_MONOTONIC, &end_time);
        interval.tv_sec = end_time.tv_sec - start_time.tv_sec;
        interval.tv_nsec = end_time.tv_nsec - start_time.tv_nsec;
        interval.tv_nsec -= interval.tv_sec * 1e9;
        if (interval.tv_nsec < 0) {
            interval.tv_sec++;
            interval.tv_nsec += 1e9;
        }
        usleep(interval.tv_sec * 1e6 + interval.tv_nsec);
        start_time = end_time;

        // Sleep for 1 second
        usleep(1000000);
    }

    // Stop I2C handle
    gpio_i2c_close(i2c_bus, i2c_address);

    // Reset GPIO
    gpio_write(gpio_shutdown, 0);

    // Terminate pigpio
    pigpio_close(gpio);

    // Close syslog
    syslog_close();

    return 0;
}

