#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_CHANNEL 0
#define SPI_CE 18
#define SPI_CS 23
#define ADC_CHANNEL 0
#define ADC_MODE 0
#define ADC_BITWIDTH 10
#define ADC_VREF 3.3

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up SPI
    if (gpioSetMode(SPI_CE, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetLevel(SPI_CE, 0) < 0) {
        perror("gpioSetLevel");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SPI_CS, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetLevel(SPI_CS, 0) < 0) {
        perror("gpioSetLevel");
        gpioTerminate();
        return 1;
    }

    // Open SPI
    if (gpioOpen(SPI_CE, SPI_MODE, SPI_SPEED, SPI_CHANNEL, SPI_CS, &spih) < 0) {
        perror("gpioOpen");
        gpioTerminate();
        return 1;
    }

    // Set up ADC
    if (gpioSetMode(ADC_CHANNEL, PI_INPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetLevel(ADC_CHANNEL, 0) < 0) {
        perror("gpioSetLevel");
        gpioTerminate();
        return 1;
    }

    // Set up ADC
    if (gpioSetMode(ADC_CHANNEL, SPI_MODE) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetLevel(ADC_CHANNEL, SPI_MODE) < 0) {
        perror("gpioSetLevel");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ADC_CHANNEL, ADC_MODE) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetLevel(ADC_CHANNEL, ADC_MODE) < 0) {
        perror("gpioSetLevel");
        gpioTerminate();
        return 1;
    }
    if (gpioSetLevel(ADC_CHANNEL, ADC_BITWIDTH) < 0) {
        perror("gpioSetLevel");
        gpioTerminate();
        return 1;
    }
    if (gpioSetLevel(ADC_CHANNEL, ADC_VREF) < 0) {
        perror("gpioSetLevel");
        gpioTerminate();
        return 1;
    }

    // Set up timer
    struct itimer it;
    it.it_value.tv_sec = 1;
    it.it_value.tv_usec = 0;
    if (itimerSet(&it) < 0) {
        perror("itimerSet");
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read ADC value
        int adc_value;
        if (gpioRead(ADC_CHANNEL, &adc_value) < 0) {
            perror("gpioRead");
            continue;
        }

        // Map ADC value to rainfall intensity level
        int intensity = (adc_value / 1023) * 10;

        // Log reading
        struct timespec now;
        clock_gettime(CLOCK_REALTIME, &now);
        printf("%ld %d %d\n", now.tv_sec, adc_value, intensity);

        // Close SPI
        if (gpioClose(spih) < 0) {
            perror("gpioClose");
            continue;
        }
    }

    // Clean up
    gpioTerminate();
    return 0;
