    if (pigpio_pwm_open(PWM_HANDLE, &pwm_config) < 0) {
        printf("pigpio_pwm_open failed\n");
        pigpio_spi_close(SPI_HANDLE);
        return 1;
    }

    // Create the ADC handle
    struct pigpio_adc_config adc_config = {
        .gpio = GPIO_POT,
        .bits = NUM_BITS
    };
    if (pigpio_adc_open(ADC_HANDLE, &adc_config) < 0) {
