        pigpio_pwm_close(PWM_HANDLE);
        pigpio_spi_close(SPI_HANDLE);
        return 1;
    }

    // Set the ADC bits
    if (pigpio_adc_set_bits(ADC_HANDLE, NUM_BITS) < 0) {
        printf("pigpio_adc_set_bits failed\n");
        pigpio_adc_close(ADC_HANDLE);
        pigpio_pwm_close(PWM_HANDLE);
        pigpio_spi_close(SPI_HANDLE);
        return 1;
    }

