    if (pigpio_pwm_set_duty(PWM_HANDLE, 0) < 0) {
        printf("pigpio_pwm_set_duty failed\n");
        pigpio_adc_close(ADC_HANDLE);
        pigpio_pwm_close(PWM_HANDLE);
        pigpio_spi_close(SPI_HANDLE);
        return 1;
