    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Read the ADC value
        int adc_value;
        if (pigpio_adc_read(ADC_HANDLE, &adc_value) < 0) {
            printf("pigpio_adc_read failed\n");
            break;
        }

        // Map the ADC value to the PWM duty
        int duty = (adc_value / 1023) * 100;

        // Update the PWM duty
        if (pigpio_pwm_set_duty(PWM_HANDLE, duty) < 0) {
            printf("pigpio_pwm_set_duty failed\n");
