#define SPI_MODE MSBFIRST
#define SPI_SPEED 1000000
#define SPI_CS 8
#define SPI_SCK 11
#define SPI_MOSI 10
#define SPI_MISO 9
#define MCP3008_CMD 0x01
#define MCP3008_CONFIG 0x03
#define MCP3008_CHANNEL 0

int main(int argc, char **argv) {
    int fd, ret;
    struct spidev_args args;
    struct spidev *spidev;
    unsigned char cmd[3];
    unsigned char config[1];
    unsigned char result[3];
    unsigned int raw;
    unsigned int voltage;
    struct sigaction sa;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open SPI device
    if ((fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set up SPI device
    memset(&args, 0, sizeof(args));
    args.spidev = fd;
    args.mode = SPI_MODE;
    args.speed = SPI_SPEED;
    ret = ioctl(fd, SPI_IOC_SETMODE, &args);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Send MCP3008 command
    cmd[0] = MCP3008_CMD;
    cmd[1] = MCP3008_CONFIG;
    cmd[2] = MCP3008_CHANNEL;
    ret = ioctl(fd, SPI_IOC Write, &cmd, 3);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Read result
    ret = ioctl(fd, SPI_IOC_READ, &result, 3);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Extract raw value
    raw = (result[0] << 8) | result[1];

    // Calculate voltage
    voltage = raw * 3.3 / 1024.0;

    // Print result
    printf("%u %f\n", raw, voltage);

    // Loop
    while (1) {
        // Wait for 500 ms
        usleep(500000);

        // Send MCP3008 command
        cmd[0] = MCP3008_CMD;
        cmd[1] = MCP3008_CONFIG;
        cmd[2] = MCP3008_CHANNEL;
