#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE0
#define SPI_SPEED 100000
#define SPI_CS 0
#define ADC_CHANNEL 0
#define PWM_PIN1 17
#define PWM_PIN2 27
#define THRESHOLD 500
#define LOG_FILE "vibration_log.txt"

int main(int argc, char **argv) {
    int spi_fd, adc_fd;
    int pin1, pin2;
    int pwm_freq = 100;
    int pwm_duty_cycle;
    int adc_value;
    int i;
    struct sigaction sa;
    struct sigaction sa2;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open SPI device
    if ((spi_fd = spidev(SPI_DEVICE, SPI_MODE, SPI_SPEED, SPI_CS)) < 0) {
        perror("spidev");
        gpioTerminate();
        return 1;
    }

    // Open ADC device
    if ((adc_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        perror("open");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up ADC
    if (ioctl(adc_fd, SPI_IOC_SET_MODE, SPI_MODE0) < 0) {
        perror("ioctl");
        close(adc_fd);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up PWM
    if (gpioSetupPWM(pwm_freq, PWM_PIN1, PWM_PIN2) < 0) {
        perror("gpioSetupPWM");
        close(adc_fd);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        close(adc_fd);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }
    sa2.sa_handler = sigterm_handler;
    sigemptyset(&sa2.sa_mask);
    if (sigaction(SIGTERM, &sa2, NULL) < 0) {
        perror("sigaction");
        close(adc_fd);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read ADC value
        if (read(adc_fd, &adc_value, sizeof(adc_value)) < sizeof(adc_value)) {
            perror("read");
            continue;
        }

        // Check if ADC value exceeds threshold
        if (adc_value > THRESHOLD) {
            // Map ADC value to PWM duty cycle
            pwm_duty_cycle = (adc_value / 1023) * 100;

            // Log event
            FILE *log_file = fopen(LOG_FILE, "a");
            if (log_file == NULL) {
                perror("fopen");
                continue;
            }
            fprintf(log_file, "%d %d\n", time(NULL), pwm_duty_cycle);
            fclose(log_file);

            // Set PWM duty cycle
            if (gpioSet PWM(pwm_freq, PWM_PIN1, pwm_duty_cycle) < 0) {
                perror("gpioSet PWM");
                continue;
            }
            if (gpioSet PWM(pwm_freq, PWM_PIN2, pwm_duty_cycle) < 0) {
                perror("gpioSet PWM");
                continue;
            }
        } else {
            // Turn motors off
            if (gpioSet PWM(pwm_freq, PWM_PIN1, 0) < 0) {
                perror("gpioSet PWM");
            }
            if (gpioSet PWM(pwm_freq, PWM_PIN2, 0) < 0) {
                perror("gpioSet PWM");
            }
        }

        // Sleep for 10 ms
        usleep(10000);
    }

    // Clean up
    gpioTerminate();
    close(adc_fd);
    close(spi_fd);

    return 0;
}

void sigint_handler(int sig) {
    gpioTerminate();
    close(adc_fd);
    close(spi_fd);
    exit(0);
}

void sigterm_handler(int sig) {
    gpioTerminate();
    close(adc_fd);
    close(spi_fd);
    exit(0);
}

