#include <unistd.h>
#include <sys/types.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/statvfs.h>
#include <time.h>
#include <errno.h>

#define MAX_LOG_FILE "tamper_log.csv"
#define MAX_LOG_LINE 256
#define MAX_LOG_DATA 1024

// Define constants for I2C addresses and SPI settings
#define BH1750_I2C_ADDR 0x23
#define MAX9814_I2C_ADDR 0x49
#define MCP3008_SPI_CE0 18
#define MCP3008_SPI_MOSI 23
#define MCP3008_SPI_MISO 24
#define MCP3008_SPI_SCK 25

// Define constants for I2C modes
#define BH1750_MODE_2 0x11

// Define constants for SPI settings
#define SPI_MODE_0 0
#define SPI_MODE_1 1
#define SPI_MODE_2 2
#define SPI_MODE_3 3

// Define constants for ADC settings
#define ADC_CHANNEL 0

// Define constants for log file mode
#define LOG_FILE_MODE_WRITE 0
#define LOG_FILE_MODE_APPEND 1

// Define constants for error codes
#define ERROR_OK 0
#define ERROR_I2C 1
#define ERROR_ADC 2
#define ERROR_SPI 3

// Define structure for log data
typedef struct {
    time_t timestamp;
    float sound_level_db;
    float light_level_lux;
    int error_code;
} log_data_t;

// Define function prototypes
void log_data(log_data_t *data);
void read_max9814(pigpio_t *gpio, int *data);
void read_bh1750(pigpio_t *gpio, int *data);
void setup_spi(pigpio_t *gpio);
void setup_i2c(pigpio_t *gpio);
void setup_log_file(pigpio_t *gpio);
void cleanup_log_file(pigpio_t *gpio);
void cleanup_spi(pigpio_t *gpio);
void cleanup_i2c(pigpio_t *gpio);
void cleanup(pigpio_t *gpio);

int main(int argc, char **argv) {
    // Initialize libgpiod
    pigpio_t *gpio = pigpio_init();
    if (gpio == NULL) {
        printf("Failed to initialize libgpiod\n");
        return 1;
    }

    // Set up SPI
    setup_spi(gpio);

    // Set up I2C
    setup_i2c(gpio);

    // Set up log file
    setup_log_file(gpio);

    // Main loop
    while (1) {
        // Read MAX9814 data
        int max9814_data[3];
        read_max9814(gpio, max9814_data);
        if (max9814_data[0] == 0) {
            printf("MAX9814 read error\n");
            log_data((log_data_t) {time(NULL), 0.0f, 0.0f, ERROR_ADC});
            continue;
        }

        // Read BH1750 data
        int bh1750_data[2];
        read_bh1750(gpio, bh1750_data);
        if (bh1750_data[0] == 0) {
            printf("BH1750 read error\n");
            log_data((log_data_t) {time(NULL), 0.0f, 0.0f, ERROR_I2C});
            continue;
        }

        // Calculate sound level in decibels
        float sound_level_db = 20.0f * log10(max9814_data[0] / 65535.0f);

        // Calculate light level in lux
        float light_level_lux = (bh1750_data[0] * 1000.0f) / 1.2f;

        // Log data
        log_data((log_data_t) {time(NULL), sound_level_db, light_level_lux, ERROR_OK});

        // Wait 5 seconds before logging again
        sleep(5);
    }

    // Clean up
    cleanup(gpio);

    return 0;
}

void log_data(log_data_t *data) {
    char log_line[MAX_LOG_LINE];
    sprintf(log_line, "%d,%f,%f,%d\n", data->timestamp, data->sound_level_db, data->light_level_lux, data->error_code);
    FILE *log_file = fopen(MAX_LOG_FILE, LOG_FILE_MODE_WRITE);
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return;
    }
    fprintf(log_file, "%s", log_line);
    fclose(log_file);
}

void read_max9814(pigpio_t *gpio, int *data) {
    // Set up SPI
    gpio_set_mode(MCP3008_SPI_CE0, SPI_MODE_0);
    gpio_set_mode(MCP3008_SPI_MOSI, SPI_MODE_0);
    gpio_set_mode(MCP3008_SPI_MISO, SPI_MODE_0);
    gpio_set_mode(MCP3008_SPI_SCK, SPI_MODE_0);

    // Send start bit
    gpio_write(MCP3008_SPI_MOSI, 0);

    // Read 10 bits
    for (int i = 0; i < 10; i++) {
        gpio_write(MCP3008_SPI_MOSI, 0);
        usleep(10);
        gpio_read(MCP3008_SPI_MISO, data + i);
    }

    // Send stop bit
    gpio_write(MCP3008_SPI_MOSI, 1);

    // Wait for clock to stabilize
    usleep(100);

    // Read data
    for (int i = 0; i < 3; i++) {
        gpio_read(MCP3008_SPI_MISO, data + i);
    }
}

void read_bh1750(pigpio_t *gpio, int *data) {
    // Set up I2C
    gpio_set_mode(MCP3008_SPI_CE0, SPI_MODE_0);
    gpio_set_mode(MCP3008_SPI_MOSI, SPI_MODE_0);
    gpio_set_mode(MCP3008_SPI_MISO, SPI_MODE_0);
    gpio_set_mode(MCP3008_SPI_SCK, SPI_MODE_0);

    // Send start condition
    gpio_write(MCP3008_SPI_MOSI, 0);
    usleep(10);
    gpio_write(MCP3008_SPI_MOSI, 1);

    // Send mode select
    gpio_write(MCP3008_SPI_MOSI, 0);
    usleep(10);
    gpio_write(MCP3008_SPI_MOSI, 0x11);

    // Wait for mode select to stabilize
    usleep(10);

    // Read data
    gpio_read(MCP3008_SPI_MISO, data);

    // Send stop condition
    gpio_write(MCP3008_SPI_MOSI, 0);
    usleep(10);
    gpio_write(MCP3008_SPI_MOSI, 1);

    // Wait for stop condition to stabilize
    usleep(10);
}

void setup_spi(pigpio_t *gpio) {
    // Open SPI device
    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd == -1) {
        printf("Failed to open SPI device\n");
        return;
    }

    // Set up SPI
    if (ioctl(spi_fd, SPI_IOC_SET_MODE, SPI_MODE_0) == -1) {
        printf("Failed to set SPI mode\n");
        close(spi_fd);
        return;
    }

    // Set up SPI clock
