int main(int argc, char **argv) {
    // Initialize libgpiod
    pigpio_t *gpio = pigpio_init();
    if (gpio == NULL) {
        printf("Failed to initialize libgpiod\n");
        return 1;
    }

    // Set up SPI
    setup_spi(gpio);

    // Set up I2C
    setup_i2c(gpio);

    // Set up log file
    setup_log_file(gpio);

    // Main loop
    while (1) {
        // Read MAX9814 data
        int max9814_data[3];
        read_max9814(gpio, max9814_data);
        if (max9814_data[0] == 0) {
            printf("MAX9814 read error\n");
            log_data((log_data_t) {time(NULL), 0.0f, 0.0f, ERROR_ADC});
            continue;
        }

        // Read BH1750 data
        int bh1750_data[2];
        read_bh1750(gpio, bh1750_data);
        if (bh1750_data[0] == 0) {
            printf("BH1750 read error\n");
            log_data((log_data_t) {time(NULL), 0.0f, 0.0f, ERROR_I2C});
            continue;
