void read_max9814(pigpio_t *gpio, int *data) {
    // Set up SPI
    gpio_set_mode(MCP3008_SPI_CE0, SPI_MODE_0);
    gpio_set_mode(MCP3008_SPI_MOSI, SPI_MODE_0);
    gpio_set_mode(MCP3008_SPI_MISO, SPI_MODE_0);
    gpio_set_mode(MCP3008_SPI_SCK, SPI_MODE_0);

    // Send start bit
    gpio_write(MCP3008_SPI_MOSI, 0);

    // Read 10 bits
    for (int i = 0; i < 10; i++) {
        gpio_write(MCP3008_SPI_MOSI, 0);
        usleep(10);
        gpio_read(MCP3008_SPI_MISO, data + i);
    }

    // Send stop bit
    gpio_write(MCP3008_SPI_MOSI, 1);

    // Wait for clock to stabilize
    usleep(100);

    // Read data
    for (int i = 0; i < 3; i++) {
        gpio_read(MCP3008_SPI_MISO, data + i);
    }
