        float moisture_level = (spi_buffer[0] * 3.3f / 65535.0f) * 100.0f;

        // Log the moisture level
        fprintf(timestamp_file, timestamp_format, "%s %f\n", time_string(), moisture_level);
        fflush(timestamp_file);

        // Check the moisture level
        if (moisture_level < MOISTURE_THRESHOLD) {
            // Turn on the pump
            if (gpio_write(RELAY_PIN, 0) < 0) {
                printf("Failed to turn on pump\n");
                gpio_set_handler(spi_handler);
                gpio_uninit();
                fclose(pump_state_file);
                fclose(timestamp_file);
                return 1;
            }
        } else {
            // Turn off the pump
            if (gpio_write(RELAY_PIN, RELAY_STATE) < 0) {
                printf("Failed to turn off pump\n");
                gpio_set_handler(spi_handler);
                gpio_uninit();
                fclose(pump_state_file);
                fclose(timestamp_file);
                return 1;
            }
        }

        // Wait for the log interval
        usleep(log_interval * 1000000);
    }

    // Clean up
    gpio_set_handler(spi_handler);
    gpio_uninit();
    fclose(pump_state_file);
    fclose(timestamp_file);

    return 0;
}
