#define SPI_CE0 17
#define SPI_MOSI 18
#define SPI_MISO 19
#define SPI_SCK 23
#define GPIO_FAN 18
#define GPIO_LED 4
#define ADC_CHANNEL 0
#define CO2_SLOPE 0.5
#define CO2_INTERCEPT -50
#define CO2_THRESHOLD 700
#define LOG_FILE "air_quality.log"

int main(int argc, char **argv) {
    pigpio *gpio = pigpio_get();
    if (!gpio) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return 1;
    }

    if (gpio_claim_input(GPIO_LED, PI_INPUT) != PI_OK) {
        syslog(LOG_ERR, "Failed to claim GPIO LED");
        gpio_close(gpio);
        return 1;
    }

    if (gpio_claim_output(GPIO_FAN, PI_OUTPUT) != PI_OK) {
        syslog(LOG_ERR, "Failed to claim GPIO fan");
        gpio_close(gpio);
        return 1;
    }

    if (gpio_mode(SPI_CE0, PI_SPI) != PI_OK) {
        syslog(LOG_ERR, "Failed to set SPI mode");
        gpio_close(gpio);
        return 1;
    }

    if (gpio_mode(SPI_MOSI, PI_SPI) != PI_OK) {
        syslog(LOG_ERR, "Failed to set SPI MOSI mode");
        gpio_close(gpio);
        return 1;
    }

    if (gpio_mode(SPI_MISO, PI_SPI) != PI_OK) {
        syslog(LOG_ERR, "Failed to set SPI MISO mode");
        gpio_close(gpio);
        return 1;
    }

    if (gpio_mode(SPI_SCK, PI_SPI) != PI_OK) {
        syslog(LOG_ERR, "Failed to set SPI SCK mode");
        gpio_close(gpio);
        return 1;
    }

    if (gpio_freq(SPI_SCK, 1000000) != PI_OK) {
        syslog(LOG_ERR, "Failed to set SPI clock frequency");
        gpio_close(gpio);
        return 1;
    }

    int fan_state = 0;
    int adc_value;
    int co2_ppm = 0;
    int retry_count = 0;

    while (1) {
        if (gpio_read(SPI_CE0, &adc_value) != PI_OK) {
            syslog(LOG_ERR, "Failed to read SPI CE0");
            retry_count++;
            if (retry_count > 5) {
                syslog(LOG_ERR, "Failed to read SPI CE0 after 5 retries");
                break;
            }
            usleep(100000);
            continue;
        }

        if (adc_value < 0 || adc_value > 1023) {
            syslog(LOG_ERR, "Invalid ADC value");
            retry_count++;
            if (retry_count > 5) {
                syslog(LOG_ERR, "Invalid ADC value after 5 retries");
                break;
            }
            usleep(100000);
            continue;
        }

        co2_ppm = (adc_value * CO2_SLOPE) + CO2_INTERCEPT;
        if (co2_ppm > CO2_THRESHOLD) {
            fan_state = 1;
        } else {
            fan_state = 0;
        }

        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time(NULL));
        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            syslog(LOG_ERR, "Failed to open log file");
            continue;
        }

        fprintf(log_file, "%s,%d,%d\n", timestamp, co2_ppm, fan_state);
        fclose(log_file);

        if (fan_state) {
            gpio_write(GPIO_FAN, PI_HIGH);
        } else {
            gpio_write(GPIO_FAN, PI_LOW);
        }

        usleep(5000000);
    }

    gpio_close(gpio);
    return 0;
}

