#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>

// Define constants
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_CE0 GPIO_NUM_8
#define SPI_MOSI GPIO_NUM_9
#define SPI_MISO GPIO_NUM_10
#define SPI_SCK GPIO_NUM_11
#define ADC_CHANNEL 0
#define ADC_CHANNEL_1 1
#define ADC_CHANNEL_2 2
#define VALVE_GPIO 17
#define VALVE_PWM 17
#define VALVE_MIN 0
#define VALVE_MAX 100
#define VALVE_MIN_DUTY 0
#define VALVE_MAX_DUTY 100
#define LOG_FILE "irrigation.log"

// Define signal handlers
void sigint_handler(int sig) {
    pigpio_close(VALVE_PWM);
    pigpio_close(SPI_CE0);
    pigpio_close(SPI_MOSI);
    pigpio_close(SPI_MISO);
    pigpio_close(SPI_SCK);
    pigpio_close(ADC_CHANNEL_0);
    pigpio_close(ADC_CHANNEL_1);
    pigpio_close(ADC_CHANNEL_2);
    pigpio_close(VALVE_GPIO);
    fclose(log_file);
    exit(0);
}

void sigterm_handler(int sig) {
    sigint_handler(sig);
    exit(0);
}

int main() {
    // Initialize pigpio
    if (pigpio_init() < 0) {
        perror("pigpio_init");
        return 1;
    }

    // Open SPI
    if (pigpio_spi_open(SPI_CE0, SPI_MODE, SPI_SPEED, SPI_MOSI, SPI_MISO, SPI_SCK) < 0) {
        perror("pigpio_spi_open");
        pigpio_close(VALVE_GPIO);
        pigpio_close(VALVE_PWM);
        pigpio_close(SPI_CE0);
        pigpio_close(SPI_MOSI);
        pigpio_close(SPI_MISO);
        pigpio_close(SPI_SCK);
        pigpio_close(ADC_CHANNEL_0);
        pigpio_close(ADC_CHANNEL_1);
        pigpio_close(ADC_CHANNEL_2);
        pigpio_close(VALVE_GPIO);
        return 1;
    }

    // Open valve PWM
    if (pigpio_pwm_open(VALVE_GPIO, VALVE_PWM, VALVE_MIN_DUTY, VALVE_MAX_DUTY, 100) < 0) {
        perror("pigpio_pwm_open");
        pigpio_close(VALVE_GPIO);
        pigpio_close(VALVE_PWM);
        pigpio_close(SPI_CE0);
        pigpio_close(SPI_MOSI);
        pigpio_close(SPI_MISO);
        pigpio_close(SPI_SCK);
        pigpio_close(ADC_CHANNEL_0);
        pigpio_close(ADC_CHANNEL_1);
        pigpio_close(ADC_CHANNEL_2);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("fopen");
        pigpio_close(VALVE_GPIO);
        pigpio_close(VALVE_PWM);
        pigpio_close(SPI_CE0);
        pigpio_close(SPI_MOSI);
        pigpio_close(SPI_MISO);
        pigpio_close(SPI_SCK);
        pigpio_close(ADC_CHANNEL_0);
        pigpio_close(ADC_CHANNEL_1);
        pigpio_close(ADC_CHANNEL_2);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Read ADC values
        int adc0 = pigpio_spi_xfer(SPI_CE0, 0x00, 1);
        int adc1 = pigpio_spi_xfer(SPI_CE0, 0x01, 1);
        int adc2 = pigpio_spi_xfer(SPI_CE0, 0x02, 1);

        // Check for errors
        if (adc0 < 0 || adc1 < 0 || adc2 < 0) {
            continue;
        }

        // Calculate average
        int avg = (adc0 + adc1 + adc2) / 3;

        // Map average to valve position
        int valve_position = VALVE_MAX - (avg * VALVE_MAX / 1023);

        // Log data
        fprintf(log_file, "%d %d %d %d\n", (int)time(NULL), adc0, adc1, adc2, avg, valve_position);

        // Set valve position
        pigpio_pwm_write(VALVE_PWM, valve_position);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    pigpio_close(VALVE_GPIO);
    pigpio_close(VALVE_PWM);
    pigpio_close(SPI_CE0);
    pigpio_close(SPI_MOSI);
    pigpio_close(SPI_MISO);
    pigpio_close(SPI_SCK);
    pigpio_close(ADC_CHANNEL_0);
    pigpio_close(ADC_CHANNEL_1);
    pigpio_close(ADC_CHANNEL_2);
    fclose(log_file);
    pigpioTerminate();
    return 0;
}

