#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>
#include <signal.h>

#define AQI_THRESHOLD 100
#define AQI_MAPPING 500
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define RELAY_PIN 18
#define RELAY_STATE 0

// Initialize pigpio
void init_pigpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        exit(1);
    }
}

// Read MCP3008 ADC value
uint16_t read_mcp3008(uint8_t channel) {
    uint8_t response[2];
    uint8_t retry = 0;
    while (retry < 3) {
        if (gpioGetMode(0, 0) != SPI_MODE) {
            syslog(LOG_ERR, "SPI mode not set");
            return 0;
        }
        if (gpioSetClock(0, SPI_SPEED) < 0) {
            syslog(LOG_ERR, "Failed to set SPI clock");
            return 0;
        }
        if (gpioTransfer(0, 0, response, 2, 0x01, 0x08 | (channel << 2)) < 0) {
            syslog(LOG_ERR, "Failed to read from MCP3008");
            return 0;
        }
        uint16_t value = (response[1] << 8) | response[0];
        if (value > 1023) {
            syslog(LOG_ERR, "MCP3008 value out of range");
            return 0;
        }
        return value;
    }
    return 0;
}

// Convert ADC value to AQI
int convert_to_aqi(uint16_t value) {
    return (int)((value * AQI_MAPPING) / 1023);
}

// Control relay
void control_relay(int state) {
    if (state) {
        gpioWrite(RELAY_PIN, RELAY_STATE);
    } else {
        gpioWrite(RELAY_PIN, 0);
    }
}

// Log AQI to file
void log_aqi(int aqi) {
    FILE *log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file");
        return;
    }
    fprintf(log_file, "%d %d\n", time(NULL), aqi);
    fclose(log_file);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    control_relay(0);
    gpioClose(0);
    fclose("air_quality.log");
    exit(0);
}

int main() {
    // Initialize pigpio
    init_pigpio();

    // Set up SPI
    if (gpioSetMode(0, SPI_MODE) < 0) {
        syslog(LOG_ERR, "Failed to set SPI mode");
        return 1;
    }
    if (gpioSetClock(0, SPI_SPEED) < 0) {
        syslog(LOG_ERR, "Failed to set SPI clock");
        return 1;
    }

    // Set up relay pin
    if (gpioMode(RELAY_PIN, GPIO_MODE_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set relay pin mode");
        return 1;
    }

    // Main loop
    while (1) {
        uint16_t aqi = convert_to_aqi(read_mcp3008(MCP3008_CHANNEL));
        if (aqi > AQI_THRESHOLD) {
            control_relay(1);
        } else {
            control_relay(0);
        }
        log_aqi(aqi);
        usleep(5000000);
    }

    // Signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Clean up
    gpioClose(0);
    fclose("air_quality.log");
    return 0;
}

