#include <libgpiod.h>
#include <linux/spi/spi.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CE0 8
#define SPI_CLOCK 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define CHANNEL 0
#define PPM_OFFSET 10.0

int main(int argc, char **argv) {
    // Initialize libgpiod
    gpiod_init();

    // Open SPI device
    int spidev_fd = open(SPI_DEVICE, O_RDWR);
    if (spidev_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Open log file
    int log_fd = open("alcohol_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        close(spidev_fd);
        return 1;
    }

    // Set up GPIO CE0 as output
    gpiod_gpio_set_direction(GPIO_CE0, gpiod_gpio_direction_output());
    gpiod_gpio_set_value(GPIO_CE0, 0);

    // Set up SPI
    struct spi_device_config config = {
        .mode = SPI_MODE,
        .bits = SPI_BITS,
        .clock = SPI_CLOCK,
        .chipselect = GPIO_CE0,
    };
    if (spidev_open(&config, spidev_fd) < 0) {
        perror("Failed to open SPI device");
        close(log_fd);
        close(spidev_fd);
        return 1;
    }

    // Set up SPI transfer
    struct spi_transfer tx = {
        .tx { .buf = (uint8_t *) &tx[0], .len = 1 },
        .rx { .buf = (uint8_t *) &rx[0], .len = 1 },
    };
    struct spi_transfer rx = {
        .tx = &tx,
        .rx = &rx,
        .len = 1,
    };
    if (spidev_transfer(spidev_fd, &rx, 1) < 0) {
        perror("Failed to transfer data");
        close(log_fd);
        close(spidev_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Send start command
        tx[0] = 0x01;
        if (spidev_transfer(spidev_fd, &tx, 1) < 0) {
            perror("Failed to send start command");
            continue;
        }

        // Send channel and mode command
        tx[0] = (CHANNEL << 4) | 0x80;
        if (spidev_transfer(spidev_fd, &tx, 1) < 0) {
            perror("Failed to send channel and mode command");
            continue;
        }

        // Read ADC value
        if (spidev_transfer(spidev_fd, &rx, 1) < 0) {
            perror("Failed to read ADC value");
            continue;
        }

        // Convert ADC value to PPM
        uint16_t adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        float ppm = (adc_value * 0.5) - PPM_OFFSET;

        // Classify reading
        char classification[50];
        if (ppm > 50) {
            sprintf(classification, "Alcohol detected! Limit exceeded.");
        } else if (ppm < 20) {
            sprintf(classification, "Sobriety confirmed.");
        } else {
            sprintf(classification, "Alcohol level within acceptable range.");
        }

        // Log reading
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S%z", localtime(NULL));
        fprintf(log_fd, "%s %f %s\n", timestamp, ppm, classification);

        // Check for sensor-absent conditions
        if (adc_value == 0 || adc_value == 1023) {
            if (spidev_transfer(spidev_fd, &rx, 1) < 0) {
                perror("Failed to retry ADC read");
                continue;
            }
            adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            if (adc_value == 0 || adc_value == 1023) {
                fprintf(log_fd, "Sensor-absent condition detected. Retrying...\n");
                continue;
            }
        }
    }

    // Clean up
    close(log_fd);
    close(spidev_fd);
    gpiod_gpio_set_direction(GPIO_CE0, gpiod_gpio_direction_input());
    gpiod_gpio_set_value(GPIO_CE0, 1);
    gpiod_exit();
    return 0;
}

