#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>

#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_CS 8
#define SPI_SCK 11
#define SPI_MOSI 10
#define SPI_MISO 9
#define GPIO_PUMP 18
#define GPIO_LOG 17
#define GPIO Soil 23

#define THRESHOLD 300

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up SPI
    if (gpioSetMode(SPI_SCK, PI_INPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SPI_MOSI, PI_INPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SPI_MISO, PI_INPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SPI_CS, PI_INPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    // Open SPI
    if (spiOpen(SPI_SCK, SPI_MOSI, SPI_MISO, SPI_CS, SPI_MODE, SPI_SPEED) < 0) {
        perror("spiOpen");
        gpioTerminate();
        return 1;
    }

    // Open log file
    struct stat sb;
    if (stat("irrigation.log", &sb) != 0) {
        if (mkdir("irrigation", 0777) < 0) {
            perror("mkdir");
            gpioTerminate();
            return 1;
        }
        if (fopen("irrigation/log.txt", "a") < 0) {
            perror("fopen");
            gpioTerminate();
            return 1;
        }
    }

    while (1) {
        // Read sensor data
        unsigned char data[3];
        if (spiXfer(data, NULL, 3, SPI_CS, 100) < 0) {
            perror("spiXfer");
            continue;
        }
        int moisture = (data[0] << 8) | data[1];

        // Log sensor reading
        if (fwrite(&moisture, sizeof(int), 1, FILE *log) < 0) {
            perror("fwrite");
            continue;
        }
        fprintf(log, "%d %d\n", time(NULL), moisture);

        // Check if moisture level is below threshold
        if (moisture < THRESHOLD) {
            // Turn on pump
            gpioWrite(GPIO_PUMP, 1);
            if (fwrite(&time(NULL), sizeof(time_t), 1, log) < 0) {
                perror("fwrite");
                continue;
            }
            fprintf(log, "Pump ON\n");
        } else {
            // Turn off pump
            gpioWrite(GPIO_PUMP, 0);
            if (fwrite(&time(NULL), sizeof(time_t), 1, log) < 0) {
                perror("fwrite");
                continue;
            }
            fprintf(log, "Pump OFF\n");
        }

        // Sleep for 60 seconds
        sleep(60);
    }

    // Clean up
    if (fclose(log) < 0) {
        perror("fclose");
    }
    if (spiClose() < 0) {
        perror("spiClose");
    }
    if (gpioTerminate() < 0) {
        perror("gpioTerminate");
    }

    return 0;
}

