#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// Define constants
#define MIN_SPEED 50
#define MAX_SPEED 255
#define SPI_CHANNEL 0
#define SPI_MOSI GPIO10
#define SPI_MISO GPIO9
#define SPI_SCLK GPIO11
#define SPI_CE0 GPIO8
#define GPIO_EN1 GPIO18
#define GPIO_DIR1 GPIO23
#define GPIO_EN2 GPIO24
#define GPIO_DIR2 GPIO25
#define GPIO_SPEED1 GPIO27
#define GPIO_SPEED2 GPIO28
#define ADC_CHANNEL1 0
#define ADC_CHANNEL2 1
#define SPI_SPEED 1000000 // 1 MHz

// Define the logarithmic function to map potentiometer values to speed factors
double speed_factor(double value) {
    return pow(2, (value / 1023.0));
}

// Define the motion profile
void motion_profile(pigpio *gpio) {
    int speed1, speed2;
    double pot1, pot2;
    int i;

    // Initialize GPIO pins
    gpioInitialise(gpio);
    gpioSetMode(gpio, GPIO_MODE_OUTPUT, GPIO_PINS_PULSE_WIDTH_PULSE);
    gpioSetPullUpDnResistor(gpio, GPIO_EN1, GPIO PullUp);
    gpioSetPullUpDnResistor(gpio, GPIO_DIR1, GPIO PullUp);
    gpioSetPullUpDnResistor(gpio, GPIO_EN2, GPIO PullUp);
    gpioSetPullUpDnResistor(gpio, GPIO_DIR2, GPIO PullUp);
    gpioSetMode(gpio, GPIO_MODE_OUTPUT, GPIO_PINS_PULSE_WIDTH_PULSE);
    gpioSetMode(gpio, GPIO_MODE_OUTPUT, GPIO_PINS_PULSE_WIDTH_PULSE);
    gpioSetMode(gpio, GPIO_MODE_OUTPUT, GPIO_PINS_PULSE_WIDTH_PULSE);
    gpioSetMode(gpio, GPIO_MODE_INPUT, GPIO_PINS_PULSE_WIDTH_PULSE);

    // Initialize SPI
    spiInit(gpio, SPI_CHANNEL, SPI_MOSI, SPI_MISO, SPI_SCLK, SPI_CE0, SPI_SPEED);
    spiSetBitMode(gpio, SPI_CHANNEL, SPI_MODE_0);

    // Read potentiometer values
    while (1) {
        pot1 = gpioRead(gpio, ADC_CHANNEL1);
        pot2 = gpioRead(gpio, ADC_CHANNEL2);

        // Map potentiometer values to speed factors
        speed1 = (int)round(speed_factor(pot1));
        speed2 = (int)round(speed_factor(pot2));

        // Limit speed values to MIN_SPEED and MAX_SPEED
        speed1 = (speed1 < MIN_SPEED) ? MIN_SPEED : (speed1 > MAX_SPEED ? MAX_SPEED : speed1);
        speed2 = (speed2 < MIN_SPEED) ? MIN_SPEED : (speed2 > MAX_SPEED ? MAX_SPEED : speed2);

        // Set speed values
        gpioWrite(gpio, GPIO_SPEED1, speed1);
        gpioWrite(gpio, GPIO_SPEED2, speed2);

        // Run motion profile
        for (i = MIN_SPEED; i <= MAX_SPEED; i++) {
            gpioWrite(gpio, GPIO_DIR1, 1);
            gpioWrite(gpio, GPIO_DIR2, 0);
            usleep(1000);
            gpioWrite(gpio, GPIO_SPEED1, i);
            gpioWrite(gpio, GPIO_SPEED2, i);
            usleep(1000);
            gpioWrite(gpio, GPIO_DIR1, 0);
            gpioWrite(gpio, GPIO_DIR2, 1);
            usleep(1000);
            gpioWrite(gpio, GPIO_SPEED1, i);
            gpioWrite(gpio, GPIO_SPEED2, i);
            usleep(1000);
        }

        // Hold constant speed for 2 seconds
        for (i = 0; i < 2000000; i++) {
            usleep(1000);
        }

        // Decelerate back to MIN_SPEED
        for (i = MAX_SPEED; i >= MIN_SPEED; i--) {
            gpioWrite(gpio, GPIO_SPEED1, i);
            gpioWrite(gpio, GPIO_SPEED2, i);
            usleep(1000);
            gpioWrite(gpio, GPIO_DIR1, 0);
            gpioWrite(gpio, GPIO_DIR2, 1);
            usleep(1000);
            gpioWrite(gpio, GPIO_SPEED1, i);
            gpioWrite(gpio, GPIO_SPEED2, i);
            usleep(1000);
            gpioWrite(gpio, GPIO_DIR1, 1);
            gpioWrite(gpio, GPIO_DIR2, 0);
            usleep(1000);
        }

        // Pause for 5 seconds
        usleep(5000000);

        // Reverse directions
        gpioWrite(gpio, GPIO_DIR1, 1);
        gpioWrite(gpio, GPIO_DIR2, 0);
    }
}

// Define signal handlers
void sigint_handler(int sig) {
    gpioTerminate(gpio);
    exit(0);
}

void sigterm_handler(int sig) {
    gpioTerminate(gpio);
    exit(0);
}

int main() {
    pigpio *gpio;
    int ret;

    // Initialize signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize pigpio
    gpio = pigpio_init();

    if (gpio == NULL) {
        printf("Failed to initialize pigpio\n");
        return 1;
    }

    // Run motion profile
    motion_profile(gpio);

    // Release resources
    gpioTerminate(gpio);
    pigpio_close(gpio);

    return 0;
}

