    // Initialize SPI
    spiInit(gpio, SPI_CHANNEL, SPI_MOSI, SPI_MISO, SPI_SCLK, SPI_CE0, SPI_SPEED);
    spiSetBitMode(gpio, SPI_CHANNEL, SPI_MODE_0);

    // Read potentiometer values
    while (1) {
        pot1 = gpioRead(gpio, ADC_CHANNEL1);
        pot2 = gpioRead(gpio, ADC_CHANNEL2);

        // Map potentiometer values to speed factors
        speed1 = (int)round(speed_factor(pot1));
        speed2 = (int)round(speed_factor(pot2));

        // Limit speed values to MIN_SPEED and MAX_SPEED
        speed1 = (speed1 < MIN_SPEED) ? MIN_SPEED : (speed1 > MAX_SPEED ? MAX_SPEED : speed1);
        speed2 = (speed2 < MIN_SPEED) ? MIN_SPEED : (speed2 > MAX_SPEED ? MAX_SPEED : speed2);

        // Set speed values
        gpioWrite(gpio, GPIO_SPEED1, speed1);
        gpioWrite(gpio, GPIO_SPEED2, speed2);

        // Run motion profile
        for (i = MIN_SPEED; i <= MAX_SPEED; i++) {
            gpioWrite(gpio, GPIO_DIR1, 1);
            gpioWrite(gpio, GPIO_DIR2, 0);
            usleep(1000);
            gpioWrite(gpio, GPIO_SPEED1, i);
            gpioWrite(gpio, GPIO_SPEED2, i);
            usleep(1000);
            gpioWrite(gpio, GPIO_DIR1, 0);
            gpioWrite(gpio, GPIO_DIR2, 1);
            usleep(1000);
            gpioWrite(gpio, GPIO_SPEED1, i);
            gpioWrite(gpio, GPIO_SPEED2, i);
            usleep(1000);
        }

        // Hold constant speed for 2 seconds
        for (i = 0; i < 2000000; i++) {
            usleep(1000);
        }

        // Decelerate back to MIN_SPEED
        for (i = MAX_SPEED; i >= MIN_SPEED; i--) {
            gpioWrite(gpio, GPIO_SPEED1, i);
            gpioWrite(gpio, GPIO_SPEED2, i);
            usleep(1000);
            gpioWrite(gpio, GPIO_DIR1, 0);
            gpioWrite(gpio, GPIO_DIR2, 1);
            usleep(1000);
            gpioWrite(gpio, GPIO_SPEED1, i);
            gpioWrite(gpio, GPIO_SPEED2, i);
            usleep(1000);
            gpioWrite(gpio, GPIO_DIR1, 1);
            gpioWrite(gpio, GPIO_DIR2, 0);
            usleep(1000);
        }

        // Pause for 5 seconds
        usleep(5000000);

        // Reverse directions
        gpioWrite(gpio, GPIO_DIR1, 1);
        gpioWrite(gpio, GPIO_DIR2, 0);
    }
}

// Define signal handlers
void sigint_handler(int sig) {
    gpioTerminate(gpio);
    exit(0);
}

void sigterm_handler(int sig) {
    gpioTerminate(gpio);
    exit(0);
}

int main() {
    pigpio *gpio;
    int ret;

    // Initialize signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize pigpio
    gpio = pigpio_init();

    if (gpio == NULL) {
        printf("Failed to initialize pigpio\n");
        return 1;
    }

    // Run motion profile
    motion_profile(gpio);

    // Release resources
    gpioTerminate(gpio);
    pigpio_close(gpio);

    return 0;
}
```

This code uses the pigpio library to control the GPIO pins, SPI interface, and ADC channels on the Raspberry Pi 4 Model B. It reads the values from the potentiometers, maps them to speed factors using a logarithmic function, and runs a motion profile that moves the motors forward and backward simultaneously, accelerating and decelerating between the minimum and maximum speeds. The code also handles errors and releases all resources when the program exits.

