#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <math.h>

#define LED_PIN 17
#define SPI_CS 8
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SCLK 11
#define ADC_CHANNEL 0
#define CALIBRATION_TIME 5000 // 5 seconds
#define LED_DEBOUNCE_TIME 10 // 10 ms
#define THRESHOLD 10 // 10% above average ambient level

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("pigpio initialization failed");
        return 1;
    }

    // Set up SPI
    if (gpioMode(SPI_SCLK, PI_OUTPUT) < 0) {
        perror("SPI SCLK mode failed");
        gpioTerminate();
        return 1;
    }
    if (gpioMode(SPI_MOSI, PI_OUTPUT) < 0) {
        perror("SPI MOSI mode failed");
        gpioTerminate();
        return 1;
    }
    if (gpioMode(SPI_MISO, PI_INPUT) < 0) {
        perror("SPI MISO mode failed");
        gpioTerminate();
        return 1;
    }
    if (gpioMode(SPI_CS, PI_OUTPUT) < 0) {
        perror("SPI CS mode failed");
        gpioTerminate();
        return 1;
    }

    // Create SPI handle
    int spiHandle = spiOpen(SPI_SCLK, SPI_MOSI, SPI_MISO, SPI_CS, 1000000);
    if (spiHandle < 0) {
        perror("SPI handle creation failed");
        gpioTerminate();
        return 1;
    }

    // Set up LED
    if (gpioMode(LED_PIN, PI_OUTPUT) < 0) {
        perror("LED mode failed");
        spiClose(spiHandle);
        gpioTerminate();
        return 1;
    }

    // Calibrate for 5 seconds
    int ambientLevel = 0;
    for (int i = 0; i < CALIBRATION_TIME; i++) {
        int sample = spiXfer(spiHandle, NULL, NULL, 1, 0);
        if (sample < 0) {
            perror("SPI transfer failed");
            spiClose(spiHandle);
            gpioTerminate();
            return 1;
        }
        ambientLevel += sample;
    }
    ambientLevel /= CALIBRATION_TIME;

    // Set noise threshold
    int threshold = ambientLevel * THRESHOLD / 100;

    while (1) {
        // Read ADC sample
        int sample = spiXfer(spiHandle, NULL, NULL, 1, 0);
        if (sample < 0) {
            perror("SPI transfer failed");
            spiClose(spiHandle);
            gpioTerminate();
            return 1;
        }

        // Check if sound level exceeds threshold
        if (sample > threshold) {
            // Debounce LED activation
            int debounceCount = 0;
            int lastActivationTime = 0;
            while (gpioRead(LED_PIN) && debounceCount < LED_DEBOUNCE_TIME) {
                usleep(10);
                debounceCount++;
                lastActivationTime = time(NULL);
            }
            if (debounceCount >= LED_DEBOUNCE_TIME) {
                gpioWrite(LED_PIN, 1);
                printf("Sound level exceeds threshold\n");
            }
        }

        // Update ambient level
        ambientLevel = (ambientLevel * 9 + sample) / 10;
    }

    // Clean up
    gpioWrite(LED_PIN, 0);
    spiClose(spiHandle);
    gpioTerminate();
    return 0;
}

