#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_CE 18
#define SPI_MOSI 23
#define SPI_MISO 24
#define SPI_SCK 25
#define ADC_CHANNEL 0
#define LOG_FILE "airflow_log.txt"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open log file
    int log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set up SPI
    if (gpioSetupSPI(SPI_CE, SPI_CHANNEL, SPI_MOSI, SPI_MISO, SPI_SCK, 1000000) < 0) {
        perror("gpioSetupSPI");
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Set up ADC
    if (gpioSetupADC(ADC_CHANNEL, 0) < 0) {
        perror("gpioSetupADC");
        gpioDestroySPI(SPI_CE, SPI_CHANNEL, SPI_MOSI, SPI_MISO, SPI_SCK);
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Set up timer
    if (gpioSetupTimer(0, PI_TIMER_MODE_PERIODIC, 100) < 0) {
        perror("gpioSetupTimer");
        gpioDestroySPI(SPI_CE, SPI_CHANNEL, SPI_MOSI, SPI_MISO, SPI_SCK);
        gpioDestroyADC(ADC_CHANNEL);
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Set up timer callback
    gpioCallback(0, PI_TIMER_EDGE_BOTH, [](void *arg) {
        int voltage = gpioGetADCValue(ADC_CHANNEL);
        if (voltage < 0) {
            printf("ERROR: ADC read failed\n");
            return;
        }
        double airflow = (voltage - 0.5) / (4.5 - 0.5) * 200;
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        printf("%s %f SLPM\n", timestamp, airflow);
        fwrite(&timestamp, sizeof(timestamp), 1, log_fd);
        fwrite(&airflow, sizeof(airflow), 1, log_fd);
    });

    // Run indefinitely
    while (1) {
        // Do nothing
    }

    // Clean up
    gpioDestroyTimer(0);
    gpioDestroySPI(SPI_CE, SPI_CHANNEL, SPI_MOSI, SPI_MISO, SPI_SCK);
    gpioDestroyADC(ADC_CHANNEL);
    close(log_fd);
    gpioTerminate();

    return 0;
}

