#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod/gpiod.h>
#include <spidev.h>

#define GPIO8 8
#define CS 24
#define MOSI 19
#define MISO 21
#define SCLK 23
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MAX_SPEED 1000000
#define SPI_MAX_SIZE 3
#define ADMP401_CHANNEL 0
#define MCP3008_CHANNEL 0
#define LOG_FILE "audio_log.txt"

int main() {
    // Initialize GPIO line request
    gpiod_request_t req;
    gpiod_request_init(&req, GPIO8, GPIOD_REQUEST_OUTPUT, GPIOD_LINE, GPIOD_LINE_HIGH);
    if (gpiod_request_open(&req) < 0) {
        perror("gpiod_request_open");
        return 1;
    }

    // Initialize SPI device
    spidev_t *spidev;
    if ((spidev = spidev_open("/dev/spidev0.0", O_RDWR)) < 0) {
        perror("spidev_open");
        gpiod_request_close(&req);
        return 1;
    }

    // Set SPI mode, speed, and bits
    if (spidev_ioctl(spidev, SPI_IOC_SET_MODE, SPI_MODE) < 0) {
        perror("spidev_ioctl");
        spidev_close(spidev);
        gpiod_request_close(&req);
        return 1;
    }
    if (spidev_ioctl(spidev, SPI_IOC_SET_SPEED, SPI_SPEED) < 0) {
        perror("spidev_ioctl");
        spidev_close(spidev);
        gpiod_request_close(&req);
        return 1;
    }
    if (spidev_ioctl(spidev, SPI_IOC_SET Bits, SPI_BITS) < 0) {
        perror("spidev_ioctl");
        spidev_close(spidev);
        gpiod_request_close(&req);
        return 1;
    }

    // Open log file
    int log_fd = open(LOG_FILE, O_RDWR | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        perror("open");
        spidev_close(spidev);
        gpiod_request_close(&req);
        return 1;
    }

    // Set up SPI transfer
    uint8_t cmd[SPI_MAX_SIZE] = {0x01, (0x08 | (ADMP401_CHANNEL << 4) | 0x00};
    uint8_t rx_buf[SPI_MAX_SIZE];

    // Main loop
    clock_t start_time = clock_gettime(CLOCK_MONOTONIC_RAW);
    while (1) {
        // Request GPIO line
        if (gpiod_request_open(&req) < 0) {
            perror("gpiod_request_open");
            break;
        }

        // Drive CS low
        gpiod_request_set_value(&req, GPIO8, GPIOD_LINE_LOW);

        // Send command
        if (spidev_write(spidev, cmd, 1) < 0) {
            perror("spidev_write");
            break;
        }

        // Read result
        if (spidev_read(spidev, rx_buf, SPI_MAX_SIZE) < 0) {
            perror("spidev_read");
            break;
        }

        // Parse result
        uint16_t raw_adc = (rx_buf[1] << 8) | rx_buf[2];

        // Log result
        char timestamp[20];
        clock_gettime(CLOCK_MONOTONIC_RAW, &start_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%6N", localtime(&start_time));
        fprintf(log_fd, "%s|%u\n", timestamp, raw_adc);
        fflush(log_fd);

        // Sleep until next sample deadline
        struct timespec deadline;
        deadline.tv_sec = (clock_gettime(CLOCK_MONOTONIC_RAW).tv_sec + 1) / 1000000000;
        deadline.tv_nsec = (clock_gettime(CLOCK_MONOTONIC_RAW).tv_nsec + 1000000) % 1000000000;
        nanosleep(&deadline, NULL);

        // Drive CS high
        gpiod_request_set_value(&req, GPIO8, GPIOD_LINE_HIGH);
    }

    // Close log file
    if (close(log_fd) < 0) {
        perror("close");
    }

    // Close SPI device
    if (spidev_close(spidev) < 0) {
        perror("spidev_close");
    }

    // Close GPIO line request
    if (gpiod_request_close(&req) < 0) {
        perror("gpiod_request_close");
    }

    return 0;
}

