#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <sys/mount.h>
#include <sys/statvfs.h>
#include <time.h>

#define SPI_CE0 17
#define SPI_MOSI 23
#define SPI_MISO 24
#define SPI_SCK 25
#define ADC_CHANNEL 0
#define VREF 3.3
#define PPM_PER_V 1000.0
#define LOG_FILE "gas_log.txt"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set SPI clock to 1 MHz
    if (gpioSetClock(SPI_CE0, PI_RISING, 1000000) < 0) {
        perror("gpioSetClock");
        gpioTerminate();
        return 1;
    }

    // Set SPI mode to 0 (single-ended)
    if (gpioSetMode(SPI_CE0, PI_MODE_0) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    // Open log file
    int log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Map log file to memory
    struct stat sb;
    if (fstat(log_fd, &sb) < 0) {
        perror("fstat");
        close(log_fd);
        gpioTerminate();
        return 1;
    }
    void* log_ptr = mmap(NULL, sb.st_size, PROT_READ | PROT_WRITE, MAP_SHARED, log_fd, 0);
    if (map failed) {
        perror("mmap");
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read ADC value
        int adc_value = 0;
        int retry = 0;
        while (retry < 3) {
            if (gpioRead(SPI_CE0, &adc_value) < 0) {
                if (errno == EIO) {
                    usleep(100000);
                    retry++;
                } else {
                    perror("gpioRead");
                    gpioTerminate();
                    return 1;
                }
            } else {
                break;
            }
        }

        // Convert ADC value to voltage
        float voltage = (adc_value * VREF) / 1024.0;

        // Calculate PPM
        float ppm = voltage * PPM_PER_V;

        // Log timestamp, voltage, and PPM
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        char log_str[64];
        strftime(log_str, sizeof(log_str), "%Y-%m-%d %H:%M:%S", localtime(&ts));
        fwrite(log_str, strlen(log_str), 1, log_ptr);
        fwrite(&ts.tv_sec, sizeof(ts.tv_sec), 1, log_ptr);
        fwrite(&ts.tv_nsec, sizeof(ts.tv_nsec), 1, log_ptr);
        fwrite(&adc_value, sizeof(adc_value), 1, log_ptr);
        fwrite(&voltage, sizeof(voltage), 1, log_ptr);
        fwrite(&ppm, sizeof(ppm), 1, log_ptr);
        fwrite("\n", 1, 1, log_ptr);

        // Print voltage and PPM to console
        printf("%.2f V, %.2f PPM\n", voltage, ppm);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Close log file
    if (munmap(log_ptr, sb.st_size) < 0) {
        perror("munmap");
        return 1;
    }
    close(log_fd);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

void sigint_handler(int sig) {
    // Close log file
    close(log_fd);

    // Terminate pigpio
    gpioTerminate();

    // Exit
    exit(0);
}

