#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod/gpiod.h>
#include <gpiod/gpiod-internal.h>

#define GPIO4 4
#define GPIO17 17
#define GPIO27 27
#define VCC 3.3
#define V_QUIESCENT 1.65
#define SENSITIVITY 0.025
#define SAMPLE_INTERVAL 100
#define SAMPLE_RATE 10  // 10 Hz

int main(int argc, char **argv) {
    int fd[3];
    gpiod_line_request_input_t line_requests[3];
    gpiod_line_request_input_t *line_requests = line_requests;
    gpiod_line_request_input_t *end = line_requests + 3;
    int i, j;
    int ret;
    int sample_count = 0;
    FILE *fp;

    // Initialize libgpiod
    gpiod_init();

    // Open the log file
    fp = fopen("magnetic_log.txt", "w");
    if (fp == NULL) {
        perror("fopen");
        return 1;
    }

    // Request GPIO access
    for (i = 0; i < 3; i++) {
        ret = gpiod_line_request_input(&line_requests[i]);
        if (ret < 0) {
            perror("gpiod_line_request_input");
            return 1;
        }
        line_requests[i].line = GPIO4 + i;
        line_requests[i].direction = GPIOD_IN;
        line_requests[i].flags = GPIOD_LINE_REQUEST_INPUT;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    while (1) {
        // Read GPIO values
        for (i = 0; i < 3; i++) {
            ret = gpiod_line_read(line_requests[i].line);
            if (ret < 0) {
                perror("gpiod_line_read");
                continue;
            }
            if (line_requests[i].value == 0) {
                printf("GPIO %d is LOW\n", line_requests[i].line);
                continue;
            }
            printf("GPIO %d is HIGH\n", line_requests[i].line);
        }

        // Calculate magnetic field strength
        float V_out[3];
        for (i = 0; i < 3; i++) {
            V_out[i] = VCC - V_QUIESCENT;
        }
        for (i = 0; i < 3; i++) {
            V_out[i] *= SENSITIVITY;
        }
        for (i = 0; i < 3; i++) {
            if (V_out[i] > 100 * 1000) {
                printf("Warning: sensor %d exceeds maximum magnetic field strength\n", i + 1);
            } else if (V_out[i] < -100 * 1000) {
                printf("Warning: sensor %d underflows\n", i + 1);
            }
        }

        // Log magnetic field strength
        for (i = 0; i < 3; i++) {
            fprintf(fp, "%f,", V_out[i]);
        }
        fprintf(fp, "\n");
        fflush(fp);

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL * 1000);
        sample_count++;
        if (sample_count >= SAMPLE_RATE) {
            sample_count = 0;
        }
    }

    // Clean up
    for (i = 0; i < 3; i++) {
        gpiod_line_release(line_requests[i].line);
    }
    fclose(fp);
    gpiod_exit();
    return 0;
}

void sigint_handler(int sig) {
    printf("Received SIGINT, exiting...\n");
    for (int i = 0; i < 3; i++) {
        gpiod_line_release(line_requests[i].line);
    }
    fclose(fp);
    gpiod_exit();
    exit(0);
}

