#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <syslog.h>

// Define constants
#define GPIO_RELAY 17
#define GPIO_CE0 18
#define SPI_SPEED 500000
#define ADC_CHANNEL 0
#define LOG_FILE "watering.log"

// Define signal handlers
void sigint_handler(int sig) {
    pigpio_close(GPIO_RELAY);
    pigpio_close(GPIO_CE0);
    exit(0);
}

void sigterm_handler(int sig) {
    pigpio_close(GPIO_RELAY);
    pigpio_close(GPIO_CE0);
    exit(0);
}

int main() {
    // Initialize pigpio
    if (pigpio_init() < 0) {
        syslog(LOG_ERR, "pigpio_init failed");
        exit(1);
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Set up GPIO and SPI
    if (pigpio_gpio_fsel(GPIO_RELAY, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as input", GPIO_RELAY);
        pigpio_close(GPIO_RELAY);
        pigpio_close(GPIO_CE0);
        exit(1);
    }
    if (pigpio_gpio_fsel(GPIO_CE0, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", GPIO_CE0);
        pigpio_close(GPIO_RELAY);
        pigpio_close(GPIO_CE0);
        exit(1);
    }
    if (pigpio_spi_open(GPIO_CE0, SPI_SPEED, SPI_MODE_0) < 0) {
        syslog(LOG_ERR, "Failed to open SPI interface");
        pigpio_close(GPIO_RELAY);
        pigpio_close(GPIO_CE0);
        exit(1);
    }

    // Set up ADC
    if (pigpio_adc_open(ADC_CHANNEL, SPI_SPEED, SPI_MODE_0) < 0) {
        syslog(LOG_ERR, "Failed to open ADC channel %d", ADC_CHANNEL);
        pigpio_close(GPIO_RELAY);
        pigpio_close(GPIO_CE0);
        pigpio_spi_close(GPIO_CE0);
        exit(1);
    }

    // Set up relay pin as output
    if (pigpio_gpio_mode(GPIO_RELAY, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", GPIO_RELAY);
        pigpio_close(GPIO_RELAY);
        pigpio_close(GPIO_CE0);
        pigpio_spi_close(GPIO_CE0);
        exit(1);
    }

    // Set relay pin high to ensure it's off initially
    if (pigpio_gpio_write(GPIO_RELAY, 1) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d high", GPIO_RELAY);
        pigpio_close(GPIO_RELAY);
        pigpio_close(GPIO_CE0);
        pigpio_spi_close(GPIO_CE0);
        exit(1);
    }

    // Log program start
    time_t now = time(NULL);
    syslog(LOG_INFO, "Program started at %s", ctime(&now));

    while (1) {
        // Read ADC value
        int adc_value = pigpio_adc_read(ADC_CHANNEL);
        if (adc_value < 0) {
            syslog(LOG_ERR, "Failed to read ADC value");
            continue;
        }

        // Calculate moisture level
        int moisture_level = (adc_value * 100) / 1023;

        // Log moisture level
        syslog(LOG_INFO, "Moisture level: %d%%", moisture_level);

        // Turn on pump if moisture level falls below 30%
        if (moisture_level < 30) {
            if (pigpio_gpio_write(GPIO_RELAY, 0) < 0) {
                syslog(LOG_ERR, "Failed to set GPIO %d low", GPIO_RELAY);
                continue;
            }
        }
        // Turn off pump if moisture level rises to 30% or above
        else if (moisture_level >= 30) {
            if (pigpio_gpio_write(GPIO_RELAY, 1) < 0) {
                syslog(LOG_ERR, "Failed to set GPIO %d high", GPIO_RELAY);
                continue;
            }
        }

        // Log pump state
        syslog(LOG_INFO, "Pump state: %s", (pigpio_gpio_read(GPIO_RELAY) == 0) ? "off" : "on");

        // Sleep for 60 seconds
        sleep(60);
    }

    // Turn off pump on exit
    pigpio_gpio_write(GPIO_RELAY, 1);

    // Close all resources
    pigpio_adc_close(ADC_CHANNEL);
    pigpio_spi_close(GPIO_CE0);
    pigpio_close(GPIO_RELAY);
    pigpio_cleanup();
    exit(0);
}

