#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <cJSON.h>

// MQTT broker settings
#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_QOS 0

// GPIO settings
#define GPIO_LED 17

// Exponential backoff delay multiplier
#define BACKOFF_MULTIPLIER 2

// Maximum backoff delay
#define MAX_BACKOFF_DELAY 60

// Signal handlers
void sigint_handler(int sig) {
    mosquitto_disconnect(mosq, MQTT_CLIENT_ID, 0);
    gpioTerminate(gpio);
    exit(0);
}

void sigterm_handler(int sig) {
    mosquitto_disconnect(mosq, MQTT_CLIENT_ID, 0);
    gpioTerminate(gpio);
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO17 as output
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO17 as output: %s\n", strerror(errno));
        gpioTerminate(gpio);
        return 1;
    }

    // Turn off the LED on startup
    if (gpioWrite(GPIO_LED, 0) < 0) {
        fprintf(stderr, "Error turning off LED on startup: %s\n", strerror(errno));
        gpioTerminate(gpio);
        return 1;
    }

    // Initialize MQTT
    mosquitto *mosq;
    mosq = mosquitto_new(NULL, 1, NULL);
    if (!mosq) {
        fprintf(stderr, "Error initializing MQTT: %s\n", strerror(errno));
        gpioTerminate(gpio);
        return 1;
    }

    // Set MQTT callback functions
    mosquitto_set_callback(mosq, mqtt_callback, NULL);

    // Connect to MQTT broker
    if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, MQTT_CLIENT_ID, MQTT_QOS) != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(mosq));
        mosquitto_destroy(mosq);
        gpioTerminate(gpio);
        return 1;
    }

    // Subscribe to MQTT topic
    if (mosquitto_subscribe(mosq, MQTT_TOPIC, mqtt_callback, NULL) != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error subscribing to MQTT topic: %s\n", mosquitto_strerror(mosq));
        mosquitto_disconnect(mosq, MQTT_CLIENT_ID, 0);
        mosquitto_destroy(mosq);
        gpioTerminate(gpio);
        return 1;
    }

    // Main loop
    while (1) {
        // Sleep for 1 second
        sleep(1);

        // Check for disconnection
        if (mosquitto_isconnected(mosq) == 0) {
            // Reconnect with exponential backoff
            int backoff_delay = 1;
            while (backoff_delay <= MAX_BACKOFF_DELAY) {
                mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, MQTT_CLIENT_ID, MQTT_QOS);
                if (mosquitto_isconnected(mosq) == 1) {
                    break;
                }
                sleep(backoff_delay);
                backoff_delay *= BACKOFF_MULTIPLIER;
            }
        }
    }

    // Clean up
    mosquitto_disconnect(mosq, MQTT_CLIENT_ID, 0);
    mosquitto_destroy(mosq);
    gpioTerminate(gpio);

    return 0;
}

// MQTT callback function
void mqtt_callback(struct mosquitto *mosq, void *user_data, int mid, const char *topic, int qos, int mid, const char *payload, int retained) {
    // Parse JSON payload
    cJSON *json = cJSON_Parse(payload);
    if (!json) {
        fprintf(stderr, "Error parsing JSON payload: %s\n", cJSON_GetErrorPtr(json));
        return;
    }

    // Check if the payload contains the expected key
    cJSON *led_state = cJSON_GetObjectItem(json, "led_state");
    if (!led_state) {
        fprintf(stderr, "Error: expected key 'led_state' in JSON payload\n");
        cJSON_Delete(json);
        return;
    }

    // Check if the value is a boolean
    if (cJSON_IsBool(led_state)) {
        // Set GPIO17 HIGH if led_state is true, LOW if false
        if (cJSON_GetBoolValue(led_state)) {
            gpioWrite(GPIO_LED, 1);
        } else {
            gpioWrite(GPIO_LED, 0);
        }
    } else {
        fprintf(stderr, "Error: invalid value for 'led_state' in JSON payload\n");
        cJSON_Delete(json);
        return;
    }

    // Clean up
    cJSON_Delete(json);
}

