#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>
#include <gpiod/gpiod.h>

// Define constants
#define GPIO17 17
#define GPIO18 18
#define LED_PIN GPIO18
#define DELAY 100

// Define a function to handle the signal
void sig_handler(int sig) {
    // Cleanly release all GPIO lines
    gpiod_release_lines();
    exit(0);
}

int main() {
    // Register signal handler for SIGINT and SIGTERM
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Initialize libgpiod
    if (gpiod_init() != 0) {
        fprintf(stderr, "Error initializing libgpiod: %s\n", gpiod_strerror());
        return 1;
    }

    // Open the chip
    struct gpiod_chip *chip = gpiod_chip_open("gpio-17", GPIO17);
    if (!chip) {
        fprintf(stderr, "Error opening chip: %s\n", gpiod_strerror());
        gpiod_exit();
        return 1;
    }

    // Open the line
    struct gpiod_line *line = gpiod_line_open(chip, "line-17", GPIO17);
    if (!line) {
        fprintf(stderr, "Error opening line: %s\n", gpiod_strerror());
        gpiod_chip_close(chip);
        gpiod_exit();
        return 1;
    }

    // Request the line
    if (gpiod_line_request(line, GPIO17, GPIO17, GPIO17, 0, 0, 0) != 0) {
        fprintf(stderr, "Error requesting line: %s\n", gpiod_strerror());
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        gpiod_exit();
        return 1;
    }

    // Open the LED pin
    struct gpiod_line *led_line = gpiod_line_open(chip, "line-18", GPIO18);
    if (!led_line) {
        fprintf(stderr, "Error opening LED line: %s\n", gpiod_strerror());
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        gpiod_exit();
        return 1;
    }

    // Request the LED pin
    if (gpiod_line_request(led_line, GPIO18, GPIO18, GPIO18, 0, 0, 0) != 0) {
        fprintf(stderr, "Error requesting LED line: %s\n", gpiod_strerror());
        gpiod_line_close(led_line);
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        gpiod_exit();
        return 1;
    }

    // Read the sensor value
    while (1) {
        int value = gpiod_line_get_value(line);
        if (value == 0) {
            // Blink the LED
            gpiod_line_set_value(led_line, 1);
            usleep(1000000);
            gpiod_line_set_value(led_line, 0);
            usleep(1000000);
        }
        printf("%d\n", value);
        usleep(DELAY * 1000);
    }

    // Cleanly release all GPIO lines
    gpiod_line_close(led_line);
    gpiod_line_close(line);
    gpiod_chip_close(chip);
    gpiod_exit();
    return 0;
}

