#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>

#define BUFFER_SIZE 120
#define FILE_NAME "temp_log.dat"

// Define the SPI configuration
#define SPI_CE0 8
#define SPI_MOSI 9
#define SPI_MISO 10
#define SPI_SCK 11

// Define the LM35 and MCP3008 configuration
#define LM35_VREF 3.3
#define LM35_OFFSET 0.0005

// Define the SPI protocol
#define SPI_START 0x01
#define SPI_MODE 0x80
#define SPI_CHANNEL 0x80

// Define the SPI transfer function
void spi_transfer(pigpio_t *gpio, uint8_t *rx, uint8_t *tx) {
    uint8_t tx_buf[3] = {SPI_START, SPI_MODE, SPI_CHANNEL};
    uint8_t rx_buf[3];
    int ret;

    // Set the SPI mode
    gpio_set_mode(gpio, SPI_MOSI, PI_INPUT);
    gpio_set_mode(gpio, SPI_MISO, PI_INPUT);
    gpio_set_mode(gpio, SPI_SCK, PI_OUTPUT);
    gpio_set_level(gpio, SPI_SCK, 1);
    gpio_set_level(gpio, SPI_CE0, 0);

    // Send the SPI protocol
    gpio_write(gpio, SPI_CE0, 1);
    gpio_write(gpio, SPI_CE0, 0);
    gpio_write(gpio, SPI_CE0, 1);
    gpio_write(gpio, SPI_CE0, 0);
    gpio_write(gpio, SPI_CE0, 1);
    gpio_write(gpio, SPI_CE0, 0);

    // Send the channel number
    tx_buf[0] = SPI_CHANNEL;
    gpio_write(gpio, SPI_CE0, 1);
    gpio_write(gpio, SPI_CE0, 0);
    gpio_write(gpio, SPI_CE0, 1);
    gpio_write(gpio, SPI_CE0, 0);
    gpio_write(gpio, SPI_CE0, 1);
    gpio_write(gpio, SPI_CE0, 0);
    gpio_write(gpio, SPI_CE0, tx_buf[0]);

    // Send the don't-care byte
    tx_buf[1] = 0x00;
    gpio_write(gpio, SPI_CE0, 1);
    gpio_write(gpio, SPI_CE0, 0);
    gpio_write(gpio, SPI_CE0, 1);
    gpio_write(gpio, SPI_CE0, 0);
    gpio_write(gpio, SPI_CE0, 1);
    gpio_write(gpio, SPI_CE0, 0);
    gpio_write(gpio, SPI_CE0, tx_buf[1]);

    // Receive the result
    for (int i = 0; i < 3; i++) {
        rx_buf[i] = gpio_read(gpio, SPI_MISO);
    }

    // Check for errors
    if (rx_buf[0] != SPI_START) {
        printf("SPI transfer error\n");
        return;
    }

    // Extract the result
    uint16_t result = (rx_buf[1] & 0x03) << 8 | rx_buf[2];

    // Calculate the temperature
    float temperature = (result * LM35_OFFSET) / 1000.0;

    // Log the temperature
    printf("Temperature: %.2f °C\n", temperature);

    // Write to the file
    FILE *file = fopen(FILE_NAME, "ab+");
    if (file == NULL) {
        printf("Error opening file\n");
        return;
    }

    // Write the temperature to the file
    fwrite(&temperature, sizeof(float), 1, file);

    // Close the file
    fclose(file);
}

int main() {
    // Initialize pigpio
    pigpio_init();

    // Open the SPI interface
    pigpio_t *gpio = pigpio_open(SPI_CE0, PI_INPUT, PI_INT_EDGE_RISING);
    if (gpio == NULL) {
        printf("Error opening SPI interface\n");
        return 1;
    }

    // Initialize the SPI
    pigpio_spi_init(gpio, SPI_CE0, SPI_MOSI, SPI_MISO, SPI_SCK);

    // Create a circular buffer
    float *buffer = malloc(BUFFER_SIZE * sizeof(float));
    if (buffer == NULL) {
        printf("Error allocating memory\n");
        return 1;
    }

    // Initialize the buffer
    for (int i = 0; i < BUFFER_SIZE; i++) {
        buffer[i] = 0.0;
    }

    // Set up the signal handlers
    signal(SIGINT, SIG_IGN);
    signal(SIGTERM, SIG_IGN);

    // Main loop
    while (1) {
        // Read the temperature
        spi_transfer(gpio, NULL, NULL);

        // Update the buffer
        for (int i = BUFFER_SIZE - 1; i > 0; i--) {
            buffer[i] = buffer[i - 1];
        }
        buffer[0] = 0.0;

        // Check if the buffer is full
        if (BUFFER_SIZE == 120) {
            // Open the file
            FILE *file = fopen(FILE_NAME, "wb+");
            if (file == NULL) {
                printf("Error opening file\n");
                continue;
            }

            // Write the buffer to the file
            fwrite(buffer, sizeof(float), BUFFER_SIZE, file);

            // Close the file
            fclose(file);
        }

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close the SPI interface
    pigpio_close(gpio);

    // Free the buffer
    free(buffer);

    // Terminate pigpio
    pigpioTerminate();

    return 0;
}

