#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/statvfs.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spi.h>
#include <linux/spi/spi.h>

#define I2C_ADDRESS 0x23
#define SPI_DEVICE 0
#define SPI_CHANNEL 0
#define FILE_NAME "environmental_log.txt"

int main(int argc, char *argv[]) {
    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Open I2C device
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("open");
        return 1;
    }

    // Open SPI device
    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd == -1) {
        perror("open");
        close(i2c_fd);
        return 1;
    }

    // Set up I2C and SPI parameters
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
        perror("ioctl");
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_SET_MODE, SPI_MODE0) == -1) {
        perror("ioctl");
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    // Open log file
    int log_fd = open(FILE_NAME, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        perror("open");
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    // Set up I2C and SPI callbacks
    struct i2c_client *client;
    struct spi_device *spi;
    struct i2c_client *i2c_client;
    struct spi_device *spi_device;
    struct i2c_client *i2c_client2;
    struct spi_device *spi_device2;

    client = i2c_get_client(i2c_fd, I2C_ADDRESS);
    if (!client) {
        perror("i2c_get_client");
        close(i2c_fd);
        close(spi_fd);
        close(log_fd);
        return 1;
    }
    i2c_client = client;
    i2c_client->dev = (struct i2c_dev *)malloc(sizeof(struct i2c_dev));
    i2c_client->dev->addr = I2C_ADDRESS;
    i2c_client->dev->flags = I2C_CLIENT_FLAG_NONE;

    spi = spi_open(spi_fd, SPI_DEVICE, SPI_CHANNEL);
    if (!spi) {
        perror("spi_open");
        close(i2c_fd);
        close(spi_fd);
        close(log_fd);
        free(i2c_client->dev);
        free(client);
        return 1;
    }
    spi_device = spi->dev;
    spi_device->mode = SPI_MODE0;

    // Read I2C and SPI data
    struct i2c_msg msg;
    struct spi_msg spi_msg;
    char i2c_buf[3];
    char spi_buf[3];
    int i2c_len = 3;
    int spi_len = 3;
    int i2c_ret = 0;
    int spi_ret = 0;
    int light_level = 0;
    int sound_level = 0;

    while (1) {
        // Read I2C data
        msg.msg_type = I2C_READ;
        msg.addr = I2C_ADDRESS;
        msg.flags = I2C_MMB;
        msg.len = i2c_len;
        msg.buf = i2c_buf;
        i2c_ret = i2c_master_send(i2c_fd, &msg);
        if (i2c_ret < 0) {
            perror("i2c_master_send");
            break;
        }
        i2c_ret = i2c_master_recv(i2c_fd, &msg, i2c_len);
        if (i2c_ret < 0) {
            perror("i2c_master_recv");
            break;
        }
        light_level = i2c_buf[0];

        // Read SPI data
        msg.msg_type = SPI_READ;
        msg.addr = SPI_DEVICE;
        msg.flags = SPI_MMB;
        msg.len = spi_len;
        msg.buf = spi_buf;
        spi_ret = spi_master_send(spi_fd, &msg);
        if (spi_ret < 0) {
            perror("spi_master_send");
            break;
        }
        spi_ret = spi_master_recv(spi_fd, &msg, spi_len);
        if (spi_ret < 0) {
            perror("spi_master_recv");
            break;
        }
        sound_level = spi_buf[0];

        // Format log entry
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        char log_entry[100];
        sprintf(log_entry, "%s, Light: %d, Sound: %d", timestamp, light_level, sound_level);

        // Write log entry to file
        if (write(log_fd, log_entry, strlen(log_entry)) != strlen(log_entry) || ferror(log_fd)) {
            perror("write");
            break;
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Close resources
    close(i2c_fd);
    close(spi_fd);
    close(log_fd);
    free(i2c_client->dev);
    free(client);
    return 0;
}

