#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <termios.h>
#include <unistd.h>

#define SPI_CE0 17
#define SPI_MOSI 23
#define SPI_MISO 24
#define SPI_SCK 25
#define I2C_ADDRESS 0x62
#define DAC_ADDRESS 0x60
#define DAC_PIN 18
#define LOG_FILE "temperature_log.txt"

int main(int argc, char **argv) {
    int spi_fd, i2c_fd;
    int spi_mode = 0;
    int spi_speed = 500000;
    int i2c_speed = 100000;
    int dac_pin = DAC_PIN;
    int sensor_channel = 0;
    int retry_count = 0;
    int retry_delay = 100;
    int log_fd = -1;
    int log_file_exists = 0;
    int log_file_size = 0;
    int log_offset = 0;
    int log_buffer[1024];
    char log_buffer_str[1024];
    char log_timestamp[32];
    int temperature;
    int dac_value;
    struct timespec start_time;
    struct timespec end_time;
    struct sigaction sa;

    // Initialize pigpio
    if (pigpio_init() < 0) {
        perror("pigpio_init");
        return 1;
    }

    // Set up SPI
    if (pigpio_spi_open(SPI_CE0, SPI_MOSI, SPI_MISO, SPI_SCK, &spi_fd) < 0) {
        perror("pigpio_spi_open");
        pigpio_cleanup();
        return 1;
    }
    if (pigpio_spi_mode(spi_fd, spi_mode) < 0) {
        perror("pigpio_spi_mode");
        pigpio_spi_close(spi_fd);
        pigpio_cleanup();
        return 1;
    }
    if (pigpio_spi_speed(spi_fd, spi_speed) < 0) {
        perror("pigpio_spi_speed");
        pigpio_spi_close(spi_fd);
        pigpio_cleanup();
        return 1;
    }

    // Set up I2C
    if (pigpio_i2c_open(1, I2C_ADDRESS, I2C_SPEED, &i2c_fd) < 0) {
        perror("pigpio_i2c_open");
        pigpio_spi_close(spi_fd);
        pigpio_cleanup();
        return 1;
    }

    // Set up DAC
    if (pigpio_gpio_fsel(dac_pin, PI_INPUT) < 0) {
        perror("pigpio_gpio_fsel");
        pigpio_i2c_close(i2c_fd);
        pigpio_spi_close(spi_fd);
        pigpio_cleanup();
        return 1;
    }
    if (pigpio_gpio_mode(dac_pin, PI_INPUT) < 0) {
        perror("pigpio_gpio_mode");
        pigpio_i2c_close(i2c_fd);
        pigpio_spi_close(spi_fd);
        pigpio_cleanup();
        return 1;
    }

    // Open log file
    log_fd = open(LOG_FILE, O_RDWR | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        pigpio_i2c_close(i2c_fd);
        pigpio_spi_close(spi_fd);
        pigpio_cleanup();
        return 1;
    }
    if (fstat(log_fd, &log_file_size) < 0) {
        perror("fstat");
        close(log_fd);
        pigpio_i2c_close(i2c_fd);
        pigpio_spi_close(spi_fd);
        pigpio_cleanup();
        return 1;
    }
    if (fseek(log_fd, 0, SEEK_END) < 0) {
        perror("fseek");
        close(log_fd);
        pigpio_i2c_close(i2c_fd);
        pigpio_spi_close(spi_fd);
        pigpio_cleanup();
        return 1;
    }
