#include <stdlib.h>
#include <time.h>
#include <string.h>

#define SPI_CE0 17
#define SPI_MOSI 18
#define SPI_MISO 19
#define SPI_SCK 23
#define LOG_FILE "soil_data.txt"

int main(int argc, char **argv) {
    int adc_channel[3] = {0, 1, 2};
    int adc_value[3];
    int i;
    int spi_fd;
    int ret;
    struct timespec delay;
    struct timespec start_time;
    struct timespec end_time;
    struct timespec sleep_time;
    char log_line[256];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    // Open SPI interface
    if ((spi_fd = spiOpen(SPI_CE0, SPI_MOSI, SPI_MISO, SPI_SCK, 1000000)) < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up SPI mode
    if (spiXfer(spi_fd, NULL, NULL, 0, 0) < 0) {
        fprintf(stderr, "SPI mode setup failed\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up SPI chip select
    if (gpioMode(SPI_CE0, PI_OUTPUT) < 0) {
        fprintf(stderr, "SPI CE0 mode setup failed\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }
    gpioWrite(SPI_CE0, 1);

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "log file open failed\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Log header
    fprintf(log_file, "Timestamp\tChannel\tMoisture\n");

    while (1) {
        // Read ADC values
        for (i = 0; i < 3; i++) {
            ret = spiXfer(spi_fd, NULL, &adc_value[i], 1, 0);
            if (ret < 0) {
                fprintf(stderr, "SPI read failed\n");
                spiClose(spi_fd);
                gpioTerminate();
                return 1;
            }
            if (adc_value[i] < 0 || adc_value[i] > 1023) {
                fprintf(stderr, "Invalid ADC value %d for channel %d\n", adc_value[i], i);
                continue;
            }
            adc_value[i] = (1.0 - (adc_value[i] / 1023.0)) * 100.0;
        }

        // Log data
        clock_gettime(CLOCK_REALTIME, &start_time);
        for (i = 0; i < 3; i++) {
            sprintf(log_line, "%04d-%02d-%02d %02d:%02d:%02d\t%d\t%.2f\n",
                    start_time.tv_sec, start_time.tv_usec / 1000000,
                    start_time.tv_sec % 100, start_time.tv_sec / 100,
                    start_time.tv_nsec / 1000000000, start_time.tv_nsec % 1000000000,
                    i, adc_value[i]);
            fprintf(log_file, "%s", log_line);
        }

        // Sleep for 60 seconds
        clock_gettime(CLOCK_REALTIME, &end_time);
        sleep_time.tv_sec = end_time.tv_sec + 60;
        sleep_time.tv_nsec = end_time.tv_nsec;
        gpioDelay(100000000);
        clock_gettime(CLOCK_REALTIME, &end_time);
        if (end_time.tv_sec != sleep_time.tv_sec || end_time.tv_nsec != sleep_time.tv_nsec) {
            fprintf(stderr, "Sleep time error\n");
            spiClose(spi_fd);
            gpioTerminate();
            return 1;
        }
    }

    // Close log file
    fclose(log_file);

    // Close SPI interface
    spiClose(spi_fd);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

