#define RELAY_DURATION 1

// Define the number of relays
#define NUM_RELAYS 4

// Define the signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    // Release all GPIO lines
    gpiod_line_release(gpiod_line_get(gpiod_line_get_instance(), RELAY1));
    gpiod_line_release(gpiod_line_get(gpiod_line_get_instance(), RELAY2));
    gpiod_line_release(gpiod_line_get(gpiod_line_get_instance(), RELAY3));
    gpiod_line_release(gpiod_line_get(gpiod_line_get_instance(), RELAY4));

    // Exit the program
    exit(0);
}

int main() {
    // Install the signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize libgpiod
    if (gpiod_init() != 0) {
        fprintf(stderr, "Error initializing libgpiod\n");
        return 1;
    }

    // Get the instance of the GPIO controller
    gpiod_line_t *line;
    if ((line = gpiod_line_get_instance()) == NULL) {
        fprintf(stderr, "Error getting GPIO instance\n");
        gpiod_exit();
        return 1;
    }

    // Request the GPIO lines for the relays
    if (gpiod_line_request_output(line, RELAY1) != 0) {
