#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod/gpiod.h>

// Define the GPIO pin numbers for the relays
#define RELAY1 17
#define RELAY2 22
#define RELAY3 23
#define RELAY4 24

// Define the duration of the relay activation and deactivation in seconds
#define RELAY_DURATION 1

// Define the number of relays
#define NUM_RELAYS 4

// Define the signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    // Release all GPIO lines
    gpiod_line_release(gpiod_line_get(gpiod_line_get_instance(), RELAY1));
    gpiod_line_release(gpiod_line_get(gpiod_line_get_instance(), RELAY2));
    gpiod_line_release(gpiod_line_get(gpiod_line_get_instance(), RELAY3));
    gpiod_line_release(gpiod_line_get(gpiod_line_get_instance(), RELAY4));

    // Exit the program
    exit(0);
}

int main() {
    // Install the signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize libgpiod
    if (gpiod_init() != 0) {
        fprintf(stderr, "Error initializing libgpiod\n");
        return 1;
    }

    // Get the instance of the GPIO controller
    gpiod_line_t *line;
    if ((line = gpiod_line_get_instance()) == NULL) {
        fprintf(stderr, "Error getting GPIO instance\n");
        gpiod_exit();
        return 1;
    }

    // Request the GPIO lines for the relays
    if (gpiod_line_request_output(line, RELAY1) != 0) {
        fprintf(stderr, "Error requesting GPIO line %d\n", RELAY1);
        gpiod_line_release(line);
        gpiod_exit();
        return 1;
    }
    if (gpiod_line_request_output(line, RELAY2) != 0) {
        fprintf(stderr, "Error requesting GPIO line %d\n", RELAY2);
        gpiod_line_release(line);
        gpiod_exit();
        return 1;
    }
    if (gpiod_line_request_output(line, RELAY3) != 0) {
        fprintf(stderr, "Error requesting GPIO line %d\n", RELAY3);
        gpiod_line_release(line);
        gpiod_exit();
        return 1;
    }
    if (gpiod_line_request_output(line, RELAY4) != 0) {
        fprintf(stderr, "Error requesting GPIO line %d\n", RELAY4);
        gpiod_line_release(line);
        gpiod_exit();
        return 1;
    }

    // Set the initial state of the relays to LOW (inactive)
    if (gpiod_line_set_value(line, RELAY1, 0) != 0) {
        fprintf(stderr, "Error setting GPIO line %d to LOW\n", RELAY1);
        gpiod_line_release(line);
        gpiod_exit();
        return 1;
    }
    if (gpiod_line_set_value(line, RELAY2, 0) != 0) {
        fprintf(stderr, "Error setting GPIO line %d to LOW\n", RELAY2);
        gpiod_line_release(line);
        gpiod_exit();
        return 1;
    }
    if (gpiod_line_set_value(line, RELAY3, 0) != 0) {
        fprintf(stderr, "Error setting GPIO line %d to LOW\n", RELAY3);
        gpiod_line_release(line);
        gpiod_exit();
        return 1;
    }
    if (gpiod_line_set_value(line, RELAY4, 0) != 0) {
        fprintf(stderr, "Error setting GPIO line %d to LOW\n", RELAY4);
        gpiod_line_release(line);
        gpiod_exit();
        return 1;
    }

    // Main loop
    while (1) {
        // Activate the first relay
        if (gpiod_line_set_value(line, RELAY1, 1) != 0) {
            fprintf(stderr, "Error activating GPIO line %d\n", RELAY1);
            gpiod_line_release(line);
            gpiod_exit();
            return 1;
        }
        usleep(RELAY_DURATION * 1000000);

        // Deactivate the first relay
        if (gpiod_line_set_value(line, RELAY1, 0) != 0) {
            fprintf(stderr, "Error deactivating GPIO line %d\n", RELAY1);
            gpiod_line_release(line);
            gpiod_exit();
            return 1;
        }

        // Activate the second relay
        if (gpiod_line_set_value(line, RELAY2, 1) != 0) {
            fprintf(stderr, "Error activating GPIO line %d\n", RELAY2);
            gpiod_line_release(line);
            gpiod_exit();
            return 1;
        }
        usleep(RELAY_DURATION * 1000000);

        // Deactivate the second relay
        if (gpiod_line_set_value(line, RELAY2, 0) != 0) {
            fprintf(stderr, "Error deactivating GPIO line %d\n", RELAY2);
            gpiod_line_release(line);
            gpiod_exit();
            return 1;
        }

        // Activate the third relay
        if (gpiod_line_set_value(line, RELAY3, 1) != 0) {
            fprintf(stderr, "Error activating GPIO line %d\n", RELAY3);
            gpiod_line_release(line);
            gpiod_exit();
            return 1;
        }
        usleep(RELAY_DURATION * 1000000);

        // Deactivate the third relay
        if (gpiod_line_set_value(line, RELAY3, 0) != 0) {
            fprintf(stderr, "Error deactivating GPIO line %d\n", RELAY3);
            gpiod_line_release(line);
            gpiod_exit();
            return 1;
        }

        // Activate the fourth relay
        if (gpiod_line_set_value(line, RELAY4, 1) != 0) {
            fprintf(stderr, "Error activating GPIO line %d\n", RELAY4);
            gpiod_line_release(line);
            gpiod_exit();
            return 1;
        }
        usleep(RELAY_DURATION * 1000000);

        // Deactivate the fourth relay
        if (gpiod_line_set_value(line, RELAY4, 0) != 0) {
            fprintf(stderr, "Error deactivating GPIO line %d\n", RELAY4);
            gpiod_line_release(line);
            gpiod_exit();
            return 1;
        }
    }

    // Release all GPIO lines
    gpiod_line_release(line);
    gpiod_exit();

    return 0;
}
