#define SPI_CE 0
#define ADC_CHANNEL 0
#define SPI_SPEED 1000000
#define LED_PIN 16
#define SOUND_THRESHOLD 500
#define DEBOUNCE_DELAY 10
#define LOG_FILE "sound_events.log"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up SPI
    if (gpioSetMode(ADC_GPIO, PI_MODE_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(ADC_GPIO, 0) < 0) {
        perror("gpioWrite");
        gpioTerminate();
        return 1;
    }
    if (gpioSetClock(ADC_GPIO, SPI_SPEED) < 0) {
        perror("gpioSetClock");
        gpioTerminate();
        return 1;
    }

    // Set up LED
    if (gpioMode(LED_GPIO, PI_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(LED_GPIO, 0) < 0) {
        perror("gpioWrite");
        gpioTerminate();
        return 1;
    }

