#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

#define GPIO_MAX 1023
#define GPIO_LED 16
#define GPIO_MIC 26
#define LED_PIN GPIO_LED
#define MIC_PIN GPIO_MIC
#define DEBOUNCE_TIME 50
#define DETECTION_THRESHOLD 700
#define DETECTION_TIME 500
#define BUS_ERROR_CODE -1
#define SENSOR_ABSENT_CODE -2

int main(int argc, char *argv[]) {
    int pi;
    int adc;
    int led;
    int mic;
    int state = 0;
    struct timespec start_time;
    struct timespec end_time;
    struct timespec delay;

    // Initialize pigpio
    if (pi = pigpio_init()) {
        printf("pigpio initialization failed: %d\n", pi);
        return 1;
    }

    // Set up GPIO mode
    if (pi->gpio_mode(MIC_PIN, PI_INPUT) != 0) {
        printf("GPIO %d input mode failed: %d\n", MIC_PIN, pi->gpio_mode(MIC_PIN));
        pigpio_cleanup();
        return 1;
    }

    // Set up GPIO mode for LED
    if (pi->gpio_mode(LED_PIN, PI_OUTPUT) != 0) {
        printf("GPIO %d output mode failed: %d\n", LED_PIN, pi->gpio_mode(LED_PIN));
        pigpio_cleanup();
        return 1;
    }

    // Set up ADC
    if (adc = pi->adc_config(MIC_PIN, PI_ADC_10BIT, PI_ADC_DEFAULT, PI_ADC_DEFAULT)) {
        printf("ADC setup failed: %d\n", adc);
        pigpio_cleanup();
        return 1;
    }

    // Set up GPIO pin for LED
    if (pi->gpio_mode(LED_PIN, PI_OUTPUT PullUp) != 0) {
        printf("GPIO %d pull-up mode failed: %d\n", LED_PIN, pi->gpio_mode(LED_PIN));
        pigpio_cleanup();
        return 1;
    }

    // Set up GPIO pin for LED
    if (pi->gpio_write(LED_PIN, 0) != 0) {
        printf("GPIO %d write failed: %d\n", LED_PIN, pi->gpio_write(LED_PIN));
        pigpio_cleanup();
        return 1;
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        printf("signal handler setup failed: %d\n", sigaction(SIGINT, &sa, NULL));
        pigpio_cleanup();
        return 1;
    }

    while (1) {
        // Read ADC value
        if (pi->adc_read(MIC_PIN, &adc) != 0) {
            printf("ADC read failed: %d\n", pi->adc_read(MIC_PIN, &adc));
            break;
        }

        // Check if signal is above detection threshold
        if (adc > DETECTION_THRESHOLD) {
            // Turn on LED
            if (pi->gpio_write(LED_PIN, 1) != 0) {
                printf("GPIO %d write failed: %d\n", LED_PIN, pi->gpio_write(LED_PIN));
                break;
            }

            // Record start time
            clock_gettime(CLOCK_REALTIME, &start_time);

            // Wait for detection time
            clock_gettime(CLOCK_REALTIME, &end_time);
            nanosleep(&delay, NULL);
            clock_gettime(CLOCK_REALTIME, &end_time);

            // Turn off LED
            if (pi->gpio_write(LED_PIN, 0) != 0) {
                printf("GPIO %d write failed: %d\n", LED_PIN, pi->gpio_write(LED_PIN));
                break;
            }

            // Apply debounce
            struct timespec debounce_delay;
            clock_gettime(CLOCK_REALTIME, &debounce_delay);
            nanosleep(&debounce_delay, NULL);
        }
    }

    // Turn off LED
    if (pi->gpio_write(LED_PIN, 0) != 0) {
        printf("GPIO %d write failed: %d\n", LED_PIN, pi->gpio_write(LED_PIN));
    }

    // Clean up
    if (pi->adc_close(adc) != 0) {
        printf("ADC close failed: %d\n", pi->adc_close(adc));
    }
    if (pi->gpio_mode(MIC_PIN, PI_INPUT) != 0) {
        printf("GPIO %d input mode failed: %d\n", MIC_PIN, pi->gpio_mode(MIC_PIN));
    }
    if (pi->gpio_mode(LED_PIN, PI_OUTPUT) != 0) {
        printf("GPIO %d output mode failed: %d\n", LED_PIN, pi->gpio_mode(LED_PIN));
    }
    if (pi->gpio_write(LED_PIN, 0) != 0) {
        printf("GPIO %d write failed: %d\n", LED_PIN, pi->gpio_write(LED_PIN));
    }
    if (pi->gpio_cleanup() != 0) {
        printf("pigpio cleanup failed: %d\n", pi->gpio_cleanup());
    }

    return 0;
}

void sigint_handler(int sig) {
    // Turn off LED
    if (pi->gpio_write(LED_PIN, 0) != 0) {
        printf("GPIO %d write failed: %d\n", LED_PIN, pi->gpio_write(LED_PIN));
    }

    // Clean up
    if (pi->adc_close(BUS_ERROR_CODE) != 0) {
        printf("ADC close failed: %d\n", pi->adc_close(BUS_ERROR_CODE));
    }
    if (pi->gpio_mode(MIC_PIN, PI_INPUT) != 0) {
        printf("GPIO %d input mode failed: %d\n", MIC_PIN, pi->gpio_mode(MIC_PIN));
    }
    if (pi->gpio_mode(LED_PIN, PI_OUTPUT) != 0) {
        printf("GPIO %d output mode failed: %d\n", LED_PIN, pi->gpio_mode(LED_PIN));
    }
    if (pi->gpio_write(LED_PIN, 0) != 0) {
        printf("GPIO %d write failed: %d\n", LED_PIN, pi->gpio_write(LED_PIN));
    }
    if (pi->gpio_cleanup() != 0) {
        printf("pigpio cleanup failed: %d\n", pi->gpio_cleanup());
    }

    exit(0);
}

