#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/ioctl.h>
#include <pigpio.h>

#define GPIO 17
#define DISTANCE_LOG_FILE "distance_log.txt"
#define DISTANCE_THRESHOLD 200
#define DISTANCE_CONSTANT_A 26.0
#define DISTANCE_CONSTANT_B -6.0

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set GPIO 17 as an input
    if (gpioMode(GPIO, GPIO_IN) < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }

    // Open log file for append mode
    int log_fd = open(DISTANCE_LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read GPIO 17
        int gpio_value = gpioGet(GPIO);
        if (gpio_value < 0) {
            perror("gpioGet");
            sleep(1);
            continue;
        }

        // Convert GPIO value to voltage (0V for low, 3.3V for high)
        float voltage = gpio_value == 0 ? 0.0f : 3.3f;

        // Convert voltage to distance
        float distance = DISTANCE_CONSTANT_A * voltage + DISTANCE_CONSTANT_B;

        // Log reading
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_fd, "%s %f\n", timestamp, distance);

        // Check if distance is below threshold
        if (distance < DISTANCE_THRESHOLD) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }
    }

    // Clean up
    close(log_fd);
    gpioTerminate();
    return 0;
}

