#include <unistd.h>
#include <gpiod/gpiod.h>
#include <spidev.h>

#define GPIO_CE 10
#define GPIO_MOSI 9
#define GPIO_MISO 8
#define GPIO_SCLK 11
#define GPIO_PUMP 17
#define GPIO_RELAY 23
#define GPIO_RELAY_DIR 24
#define GPIO_RELAY_ENABLE 25

#define ADC_CHANNEL 0
#define ADC_CALIBRATION_DRY 800
#define ADC_CALIBRATION_WET 300
#define LOG_FILE "soil_moisture.log"

int main(int argc, char **argv) {
    int spidev_fd, pump_fd, relay_fd, relay_dir_fd, relay_enable_fd;
    int spidev_flags = SPI_MODE_0;
    int spidev_bits = 8;
    int spidev_speed = 1000000;
    int spidev_ce = GPIO_CE;
    int spidev_mosi = GPIO_MOSI;
    int spidev_miso = GPIO_MISO;
    int spidev_sclk = GPIO_SCLK;
    int pump_fd = -1;
    int relay_fd = -1;
    int relay_dir_fd = -1;
    int relay_enable_fd = -1;
    int adc_value = 0;
    int moisture_level = 0;
    int pump_status = 0;
    struct gpiod_context *ctx;
    struct gpiod_line *line;
    struct gpiod_line_event *event;
    struct spidev *spidev;
    struct stat log_stat;
    struct timespec last_read;

    // Initialize libgpiod
    ctx = gpiod_context_new();
    if (!ctx) {
        perror("gpiod_context_new");
        return 1;
    }

    // Create a new line for the pump
    line = gpiod_line_new(ctx, GPIO_PUMP, GpioDirectionOut, NULL);
    if (!line) {
        perror("gpiod_line_new");
        gpiod_context_free(ctx);
        return 1;
    }

    // Create a new line for the relay
    line = gpiod_line_new(ctx, GPIO_RELAY_DIR, GpioDirectionOut, NULL);
    if (!line) {
        perror("gpiod_line_new");
        gpiod_line_free(line);
        gpiod_context_free(ctx);
        return 1;
    }

    // Create a new line for the relay enable
    line = gpiod_line_new(ctx, GPIO_RELAY_ENABLE, GpioDirectionOut, NULL);
    if (!line) {
        perror("gpiod_line_new");
        gpiod_line_free(line);
        gpiod_line_free(line);
        gpiod_context_free(ctx);
        return 1;
    }

    // Create a new spidev device
    spidev_fd = spidev_open("/dev/spidev0.0", O_RDWR, spidev_flags);
    if (spidev_fd < 0) {
        perror("spidev_open");
        gpiod_line_free(line);
        gpiod_line_free(line);
        gpiod_line_free(line);
        gpiod_context_free(ctx);
        return 1;
    }

    // Configure the spidev device
    spidev_set_bits(spidev_fd, spidev_bits);
    spidev_set_speed(spidev_fd, spidev_speed);
    spidev_set_ce(spidev_fd, spidev_ce);
    spidev_set_mosi(spidev_fd, spidev_mosi);
    spidev_set_miso(spidev_fd, spidev_miso);
    spidev_set_sclk(spidev_fd, spidev_sclk);

    // Open the log file
    log_stat.st_mode = S_IRUSR | S_IWUSR;
    if (access(LOG_FILE, F_OK) == -1) {
        if (mkdir(LOG_FILE, log_stat.st_mode) == -1) {
            perror("mkdir");
            close(spidev_fd);
            gpiod_line_free(line);
            gpiod_line_free(line);
            gpiod_line_free(line);
            gpiod_context_free(ctx);
            return 1;
        }
    }

    // Open the log file for writing
    if ((log_fd = open(LOG_FILE, O_WRONLY | O_CREAT, log_stat.st_mode)) == -1) {
