#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/stat.h>

#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_CS 8
#define GPIO_CS 8
#define GPIO_DIN 9
#define GPIO_CLK 11
#define GPIO_DOUT 10
#define GPIO_VREF 3
#define GPIO_VCC 4
#define GPIO_VOUT 5
#define GPIO_VREF_PIN GPIO_VREF
#define GPIO_VCC_PIN GPIO_VCC
#define GPIO_VOUT_PIN GPIO_VOUT
#define GPIO_DIN_PIN GPIO_DIN
#define GPIO_CLK_PIN GPIO_CLK
#define GPIO_CS_PIN GPIO_CS
#define GPIO_LOG_FILE "magnetic_log.txt"

int main() {
    // Initialize GPIO
    int gpio = gpioInitialise();
    if (gpio < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set GPIO pin modes
    gpioSetMode(GPIO_VREF_PIN, PI_INPUT);
    gpioSetMode(GPIO_VCC_PIN, PI_INPUT);
    gpioSetMode(GPIO_VOUT_PIN, PI_OUTPUT);
    gpioSetMode(GPIO_DIN_PIN, PI_INPUT);
    gpioSetMode(GPIO_CLK_PIN, PI_OUTPUT);
    gpioSetMode(GPIO_CS_PIN, PI_OUTPUT);

    // Open SPI file descriptor
    int spidev = open("/dev/spidev0.0", O_RDWR | O_NONBLOCK);
    if (spidev < 0) {
        perror("open");
        return 1;
    }

    // Set SPI parameters
    ioctl(spidev, SPI_IOC_SET_MODE, SPI_MODE);
    ioctl(spidev, SPI_IOC_SET_SPEED, SPI_SPEED);
    ioctl(spidev, SPI_IOC_SET Bits, SPI_BITS);

    // Open log file
    FILE *log_file = fopen(GPIO_LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return 1;
    }

    // Set GPIO pin states
    gpioWrite(GPIO_CS_PIN, 0);
    gpioWrite(GPIO_CLK_PIN, 1);
    gpioWrite(GPIO_DIN_PIN, 0);
    gpioWrite(GPIO_VREF_PIN, 1);

    // Main loop
    while (1) {
        // Read ADC value
        uint16_t adc_value = 0;
        if (ioctl(spidev, SPI_IOC_READ, &adc_value) < 0) {
            perror("ioctl");
            continue;
        }

        // Compute Vout_mV
        float Vout_mV = (float)adc_value * 3300 / 1023;

        // Compute B (mT)
        float B = (Vout_mV - 1650) / 100;

        // Print B to log file
        fprintf(log_file, "%lu,%f\n", time(NULL), B * 100.0);

        // Release GPIO pin states
        gpioWrite(GPIO_CS_PIN, 1);
        gpioWrite(GPIO_CLK_PIN, 0);
        gpioWrite(GPIO_DIN_PIN, 0);
        gpioWrite(GPIO_VREF_PIN, 0);

        // Sleep for 500 ms
        usleep(500000);
    }

    // Clean up
    gpioWrite(GPIO_CS_PIN, 0);
    gpioWrite(GPIO_CLK_PIN, 1);
    gpioWrite(GPIO_DIN_PIN, 0);
    gpioWrite(GPIO_VREF_PIN, 1);
    gpioClose(GPIO_VREF_PIN);
    gpioClose(GPIO_VCC_PIN);
    gpioClose(GPIO_VOUT_PIN);
    gpioClose(GPIO_DIN_PIN);
    gpioClose(GPIO_CLK_PIN);
    gpioClose(GPIO_CS_PIN);
    gpioTerminate(gpio);
    close(spidev);
    fclose(log_file);
    return 0;
}

