#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_CS 17
#define ADC_CHANNEL 0
#define ADC_MODE 0
#define ADC_BIT_WIDTH 10
#define LOG_FILE "moisture_log.txt"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open SPI
    if (gpioSetupSPI(SPI_CS, SPI_MODE, SPI_SPEED) < 0) {
        perror("gpioSetupSPI");
        gpioTerminate();
        return 1;
    }

    // Open log file
    struct stat sb;
    if (stat(LOG_FILE, &sb) != 0) {
        if (mkdir(LOG_FILE, 0755) != 0) {
            perror("mkdir");
            gpioTerminate();
            return 1;
        }
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read ADC value
        unsigned int adc_value = 0;
        unsigned char rx_buf[3];
        if (gpioGetSPIRead(SPI_CHANNEL, rx_buf, 3, SPI_CS) < 0) {
            fprintf(log_file, "%s - ADC read failed\n", ctime(NULL));
            continue;
        }

        // Parse ADC value
        adc_value = (rx_buf[1] << 8) | rx_buf[2];

        // Log reading
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s - %u\n", timestamp, adc_value);

        // Clean up
        gpioCleanupSPI(SPI_CHANNEL);
        gpioTerminate();
        return 0;
    }
}

