#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/spi/spi.h>
#include <linux/spi/spi.h>
#include <pigpio.h>
#include <libgpiod/libgpiod.h>

// Define constants
#define GPIO_PIN 17
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_CHANNEL 0
#define SPI_SPEED 100000
#define SPI_MODE 0
#define GPIO_MODE_OUTPUT
#define GPIO_OUTPUT_VALUE 0
#define FILE_NAME "current_log.txt"

// Define signal handlers
void sigint_handler(int sig) {
    gpio_close(GPIO_PIN);
    close(SPI_DEVICE);
    close(FILE_NAME);
    exit(0);
}

void sigterm_handler(int sig) {
    gpio_close(GPIO_PIN);
    close(SPI_DEVICE);
    close(FILE_NAME);
    exit(0);
}

int main() {
    // Initialize signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize libgpiod
    gpiod_init();

    // Initialize GPIO pin
    gpio_init();
    gpio_set_mode(GPIO_PIN, GPIO_MODE_OUTPUT);
    gpio_set_value(GPIO_PIN, GPIO_OUTPUT_VALUE);

    // Open SPI device
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Configure SPI
    struct spi_ioc_transfer transfer = {
        .tx { .buf = NULL, .len = 0, .flags = 0 },
        .rx { .buf = NULL, .len = 0, .flags = 0 },
        .speed = SPI_SPEED,
        .mode = SPI_MODE,
        .bits = 8,
        .cs_gpios = { { GPIO_PIN, GPIO_DIR_IN, GPIO_LEVEL_HIGH } },
        .cs_change = NULL,
        .tx_desc = NULL,
        .rx_desc = NULL
    };
    if (ioctl(spi_fd, SPI_IOC_SET_MODE, &transfer) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }

    // Open log file
    int log_fd = open(FILE_NAME, O_RDWR | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        close(spi_fd);
        return 1;
    }

    // Map log file
    struct stat sb;
    if (fstat(log_fd, &sb) < 0) {
        perror("Failed to get log file stats");
        close(log_fd);
        close(spi_fd);
        return 1;
    }
    void* log_ptr = mmap(NULL, sb.st_size, PROT_READ | PROT_WRITE, MAP_SHARED, log_fd, 0);
    if (log_ptr == MAP_FAILED) {
        perror("Failed to map log file");
        close(log_fd);
        close(spi_fd);
        return 1;
    }

    // Read from SPI device
    char buffer[256];
    while (1) {
        // Read from SPI device
        if (read(spi_fd, buffer, 256) < 0) {
            perror("Failed to read from SPI device");
            close(spi_fd);
            close(log_fd);
            return 1;
        }

        // Convert SPI data to analog value
        int analog_value = (buffer[0] - 128) * 5 / 1024;

        // Calculate current
        double current = analog_value * 0.1; // 100 mV/A

        // Log current and timestamp
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL));
        fprintf(log_ptr, "%s,%f\n", timestamp, current);

        // Sleep for 1 second
        sleep(1);
    }

    // Close log file
    munmap(log_ptr, sb.st_size);
    close(log_fd);

    // Close SPI device
    close(spi_fd);

    // Close GPIO pin
    gpio_close(GPIO_PIN);

    // Clean up libgpiod
    gpiod_exit();

    return 0;
}
```

This code initializes the GPIO pin, SPI device, and log file, and then enters an infinite loop where it reads from the SPI device, converts the data to an analog value, calculates the current, logs the current and timestamp to the log file, and sleeps for 1 second. The signal handlers are used to clean up the GPIO pin, SPI device, and log file when the program is interrupted or terminated.

