#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <gpiod/gpiod.h>
#include <gpiod/chip.h>
#include <gpiod/line.h>

#define GPIO4 4
#define GPIO17 17

int main(int argc, char **argv) {
    // Initialize libgpiod
    if (gpiod_init() != 0) {
        fprintf(stderr, "Error initializing libgpiod: %s\n", gpiod_strerror());
        return 1;
    }

    // Open the chip
    gpiod_chip_t *chip;
    if ((chip = gpiod_chip_open_by_number(0)) == NULL) {
        fprintf(stderr, "Error opening chip: %s\n", gpiod_strerror());
        gpiod_exit();
        return 1;
    }

    // Request the GPIO lines
    gpiod_line_t *line1, *line2;
    if ((line1 = gpiod_line_request_input(chip, GPIO4)) == NULL) {
        fprintf(stderr, "Error requesting GPIO4: %s\n", gpiod_strerror());
        gpiod_chip_close(chip);
        gpiod_exit();
        return 1;
    }
    if ((line2 = gpiod_line_request_input(chip, GPIO17)) == NULL) {
        fprintf(stderr, "Error requesting GPIO17: %s\n", gpiod_strerror());
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        gpiod_exit();
        return 1;
    }

    // Set the direction of the lines to input
    if (gpiod_line_set_direction(line1, GpioDirectionInput) != 0) {
        fprintf(stderr, "Error setting direction of GPIO4: %s\n", gpiod_strerror());
        gpiod_line_release(line1);
        gpiod_line_release(line2);
