#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

volatile sig_atomic_t termination = 0;

void signal_handler(int signal) {
    pigpio_close(SPI_HANDLE);
    pigpioTerminate();
    exit(0);
}

int read_mcp3008(int channel) {
    spi_config_t config;
    int adc_value;
    int ret;

    config.speed = SPI_BAUD;
    config.mode = SPI_MODE_1;
    config.bits = 8;
    config.channel = channel;
    config.gpio = SPI_CE0;
    config.gpio_flags = SPI_CSN;

    ret = pigpio_spi_open(&config, &SPI_HANDLE);
    if (ret < 0) {
        printf("Error opening SPI handle\n");
        return -1;
    }

    ret = pigpio_spi_transfer(SPI_HANDLE, 0x01, 0x80 | (channel << 4), 0x00);
    if (ret < 0) {
        printf("Error transferring data to SPI\n");
        pigpio_spi_close(SPI_HANDLE);
        return -1;
    }

    ret = pigpio_spi_transfer(SPI_HANDLE, 0x00, 0x00);
    if (ret < 0) {
        printf("Error reading from SPI\n");
        pigpio_spi_close(SPI_HANDLE);
        return -1;
    }

    ret = pigpio_spi_transfer(SPI_HANDLE, 0x00, &adc_value);
    if (ret < 0) {
        printf("Error reading ADC value from SPI\n");
        pigpio_spi_close(SPI_HANDLE);
        return -1;
    }

    pigpio_spi_close(SPI_HANDLE);
    return adc_value;
}

double calculate_moisture_level(int adc_value) {
    return 100.0 - ((adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC)) * 100.0;
}

void log_data(double moisture_level) {
    time_t now;
    char log_line[256];

    time(&now);
    strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S", localtime(&now));
    sprintf(log_line + strlen(log_line), ",%f", moisture_level);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        printf("Error opening log file\n");
        return;
    }
    fprintf(log_file, "%s\n", log_line);
    fclose(log_file);
}

int main() {
    int adc_value;
    int i;

    pigpio_init();
    if (pigpio_init() < 0) {
        printf("Error initializing pigpio\n");
        return 1;
    }

    SPI_HANDLE = pigpio_spi_open(SPI_CHANNEL, SPI_BAUD, SPI_MODE_1, SPI_CSN, SPI_CE0);
    if (SPI_HANDLE < 0) {
        printf("Error opening SPI handle\n");
        pigpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!termination) {
        adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < MIN_ADC || adc_value > MAX_ADC) {
            printf("Invalid ADC value\n");
            continue;
        }
        double moisture_level = calculate_moisture_level(adc_value);
        log_data(moisture_level);
        printf("%.2f\n", moisture_level);
        sleep(READ_DELAY);
    }

    pigpio_spi_close(SPI_HANDLE);
    pigpioTerminate();
    return 0;
}

