#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <termios.h>
#include <unistd.h>

#define GPIO17 17
#define DEBOUNCE_DELAY 200
#define CAPTURE_DELAY 50
#define CAPTURE_WIDTH 1280
#define CAPTURE_HEIGHT 720
#define CAPTURE_FORMAT "jpeg"
#define CAPTURE_DIR "/home/pi/security_cam"
#define CAPTURE_FILE "%Y-%m-%d-%H-%M-%S-%f.jpg"

int main(int argc, char **argv) {
    int gpio;
    pigpio *p;
    struct termios oldt, newt;
    struct sigaction sa;
    struct stat sb;
    char filename[256];
    char *arg;
    int child;
    int state;
    int state_prev;
    int ret;

    // Initialize pigpio
    p = pigpio_init();
    if (p == -1) {
        syslog(LOG_ERR, "pigpio_init failed");
        return 1;
    }

    // Configure GPIO17 as input with pull-down resistor
    gpio = pigpio_open(GPIO17, PI_INPUT, PI PullDown);
    if (gpio == -1) {
        syslog(LOG_ERR, "pigpio_open failed");
        pigpio_close(p);
        return 1;
    }

    // Set up signal handlers
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction failed");
        pigpio_close(p);
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction failed");
        pigpio_close(p);
        return 1;
    }

    // Main loop
    while (1) {
        // Read the current state of GPIO17
        state = pigpio_read(gpio);
        if (state != state_prev) {
            // Debounce delay
            usleep(DEBOUNCE_DELAY * 1000);

            // Read the state again to confirm
            state = pigpio_read(gpio);
            if (state == 1) {
                // Motion detected, capture image
                // Construct output path
                snprintf(filename, sizeof(filename), "%s/%s", CAPTURE_DIR, CAPTURE_FILE);
                if (stat(filename, &sb) != 0) {
                    syslog(LOG_ERR, "stat failed");
                    continue;
                }
                if (S_ISDIR(sb.st_mode)) {
                    syslog(LOG_ERR, "capture directory does not exist");
                    continue;
                }

                // Create output directory if it doesn't exist
                if (mkdir(CAPTURE_DIR, 0755) == -1) {
                    syslog(LOG_ERR, "mkdir failed");
                    continue;
                }

                // Capture image
                arg = malloc(strlen(filename) + 1);
                strcpy(arg, filename);
                child = fork();
                if (child == -1) {
                    syslog(LOG_ERR, "fork failed");
                    free(arg);
                    continue;
                }
                if (child == 0) {
                    // Child process
                    close(0);
                    close(1);
                    close(2);
                    dup2 fileno(stdin), 0;
                    dup2 fileno(stdout), 1;
                    dup2 fileno(stderr), 2;
                    close(0);
                    close(1);
                    close(2);
                    execvp("libcamera-still", (char **)arg);
                    syslog(LOG_ERR, "execvp failed");
                    _exit(1);
                } else {
                    // Parent process
                    close(0);
                    close(1);
                    close(2);
                    waitpid(child, NULL, 0);
                    free(arg);
                    syslog(LOG_INFO, "capture successful");
                }
            }
        }
        state_prev = state;
        usleep(CAPTURE_DELAY * 1000);
    }

    // Release pigpio resources
    pigpio_close(p);
    syslog(LOG_INFO, "pigpio_close");

    // Close syslog
    close(STDOUT_FILENO);
    close(STDERR_FILENO);
    syslog_close();

    return 0;
}

void sigint_handler(int sig) {
    // Stop the main loop
    syslog(LOG_INFO, "SIGINT received");
    return;
}

void sigterm_handler(int sig) {
    // Stop the main loop
    syslog(LOG_INFO, "SIGTERM received");
    return;
}

