#include <pigpio.h>
#include <linux/videodev2.h>

#define BUFFER_SIZE 640 * 480 * 3
#define FILE_NAME "frame_log.txt"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open the video device
    int fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Get the video device structure
    struct v4l2_buffer v4l2_buf;
    if (ioctl(fd, V4L2_QUERY Capabilities, &v4l2_buf) < 0) {
        perror("V4L2_QUERY Capabilities");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Check if the device supports the requested resolution
    if (v4l2_buf.format.width != 640 || v4l2_buf.format.height != 480) {
        fprintf(stderr, "Unsupported resolution\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Create a memory map for the frame buffer
    void* mem = mmap(NULL, v4l2_buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (mem == MAP_FAILED) {
        perror("mmap");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Create a file for logging
    int log_fd = open(FILE_NAME, O_RDWR | O_CREAT | O_TRUNC, 0644);
