#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/videodev2.h>

#define BUFFER_SIZE 640 * 480 * 2  // YUYV format
#define MAX_FRAGMENTS 4
#define MAX_FRAGMENT_SIZE 65000
#define HEADER_SIZE 16

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    inet_pton(AF_INET, argv[1], &server_addr.sin_addr);
    server_addr.sin_port = htons(atoi(argv[2]));

    int fd = pigpio_open("/dev/video0", O_RDWR);
    if (fd < 0) {
        perror("pigpio_open");
        return 1;
    }

    struct v4l2_buffer buffer;
    buffer.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buffer.index = 0;
    buffer.count = 1;
    buffer.mtype = V4L2_MMAP;
    buffer.m.mmap = NULL;
    buffer.m.map = NULL;

    if (ioctl(fd, VIDIOC_G_FMT, &buffer) < 0) {
        perror("VIDIOC_G_FMT");
        pigpio_close(fd);
        return 1;
    }

    if (buffer.format != VX_YUYV_640_480) {
        fprintf(stderr, "Unsupported format\n");
        pigpio_close(fd);
        return 1;
    }

    struct v4l2_mmap mmap;
    mmap.type = V4L2_MMAP;
    mmap.m.mmap = NULL;
    mmap.m.map = NULL;
    mmap.width = buffer.width;
    mmap.height = buffer.height;
    mmap.field = V4L2_MMAP_MMAP;
    mmap.format = buffer.format;
    mmap.count = buffer.count;

    if (ioctl(fd, VIDIOC_G_MMAP, &mmap) < 0) {
        perror("VIDIOC_G_MMAP");
        pigpio_close(fd);
        return 1;
    }

    int socket_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (socket_fd < 0) {
        perror("socket");
        pigpio_close(fd);
        return 1;
    }

    struct sockaddr_in server_addr2;
    server_addr2.sin_family = AF_INET;
    inet_pton(AF_INET, argv[1], &server_addr2.sin_addr);
    server_addr2.sin_port = htons(atoi(argv[2]));

    if (bind(socket_fd, (struct sockaddr *)&server_addr2, sizeof(server_addr2)) < 0) {
        perror("bind");
        close(socket_fd);
        pigpio_close(fd);
        return 1;
    }

    struct iovec iov;
    iov.iov_base = mmap.m.map;
    iov.iov_len = mmap.m.map_size;

    while (1) {
        struct msghdr msg;
        msg.msg_name = NULL;
        msg.msg_namelen = 0;
        msg.msg_iov = &iov;
        msg.msg_iovlen = 1;
        msg.msg_control = NULL;
        msg.msg_controllen = 0;
        msg.msg_flags = 0;

        int bytes_sent = sendto(socket_fd, &msg, sizeof(msg), 0);
        if (bytes_sent < 0) {
            perror("sendto");
            break;
        }

        if (bytes_sent > 0) {
            int bytes_received = recvfrom(socket_fd, NULL, 0, 0, NULL, NULL);
            if (bytes_received < 0) {
                perror("recvfrom");
                break;
            }
        }

        if (mmap.m.map_size < BUFFER_SIZE) {
            struct v4l2_buffer buffer2;
            buffer2.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
            buffer2.index = mmap.m.map + 1;
            buffer2.count = 1;
            buffer2.mtype = V4L2_MMAP;
            buffer2.m.map = NULL;
            buffer2.m.map_size = BUFFER_SIZE;

            if (ioctl(fd, VIDIOC_G_MMAP, &buffer2) < 0) {
                perror("VIDIOC_G_MMAP");
                break;
            }

            memcpy(mmap.m.map, buffer2.m.map, buffer2.m.map_size);
            mmap.m.map_size += buffer2.m.map_size;
        }

        struct v4l2_buffer buffer3;
        buffer3.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buffer3.index = mmap.m.map;
        buffer3.count = 1;
        buffer3.mtype = V4L2_MMAP;
        buffer3.m.map = NULL;
        buffer3.m.map_size = BUFFER_SIZE;

        if (ioctl(fd, VIDIOC_G_MMAP, &buffer3) < 0) {
            perror("VIDIOC_G_MMAP");
            break;
        }

        if (mmap.m.map_size >= BUFFER_SIZE * MAX_FRAGMENTS) {
            break;
        }

        struct iovec iov2;
        iov2.iov_base = buffer3.m.map;
        iov2.iov_len = buffer3.m.map_size;

        msg.msg_iov = &iov2;
        msg.msg_iovlen = 1;

        int bytes_sent2 = sendto(socket_fd, &msg, sizeof(msg), 0);
        if (bytes_sent2 < 0) {
            perror("sendto");
            break;
        }

        if (bytes_sent2 > 0) {
            int bytes_received2 = recvfrom(socket_fd, NULL, 0, 0, NULL, NULL);
            if (bytes_received2 < 0) {
                perror("recvfrom");
                break;
            }
        }
    }

    munmap(mmap.m.map, mmap.m.map_size);
    close(socket_fd);
    pigpio_close(fd);

    return 0;
}

