#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <signal.h>
#include <linux/videodev2.h>
#include <pigpio.h>

#define BUFFER_SIZE 1920 * 1080 * 3 // 3 bytes per pixel (RGB)
#define NUM_BUFFERS 4

int main() {
    // Install signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Open device
    int fd = open("/dev/video0", O_RDWR);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    // Check device capabilities
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_GETCAPABILITIES, &cap) == -1) {
        perror("VIDIOC_GETCAPABILITIES");
        close(fd);
        return 1;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE) || !(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support video capture or streaming\n");
        close(fd);
        return 1;
    }

    // Request format and capabilities
    struct v4l2_format fmt;
    if (ioctl(fd, VIDIOC_G_FMT, &fmt) == -1) {
        perror("VIDIOC_G_FMT");
        close(fd);
        return 1;
    }
    if (fmt.format != V4L2_PIX_FMT_MJPEG || fmt.width != 1920 || fmt.height != 1080) {
        fprintf(stderr, "Unsupported format or resolution\n");
        close(fd);
        return 1;
    }

    // Request capabilities
    struct v4l2_capability req;
    req.capabilities = V4L2_CAP_STREAMING;
    if (ioctl(fd, VIDIOC_GCAP, &req) == -1) {
        perror("VIDIOC_GCAP");
        close(fd);
        return 1;
    }

    // Request MMAP buffers
    struct v4l2_mmap buf;
    buf.count = NUM_BUFFERS;
    buf.length = BUFFER_SIZE * buf.count;
    buf.format = fmt.format;
    buf.field = V4L2_FIELD_NONE;
    if (ioctl(fd, VIDIOC_MMAP, &buf) == -1) {
        perror("VIDIOC_MMAP");
        close(fd);
        return 1;
    }

    // MMAP buffers
    void* buffers[NUM_BUFFERS];
    for (int i = 0; i < NUM_BUFFERS; i++) {
        if (mmap(buf.base + i * BUFFER_SIZE, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.offset + i * buf.length) == MAP_FAILED) {
            perror("mmap");
            close(fd);
            return 1;
        }
        buffers[i] = mmap(buf.base + i * BUFFER_SIZE, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.offset + i * buf.length);
        if (buffers[i] == MAP_FAILED) {
            perror("mmap");
            close(fd);
            return 1;
        }
    }

    // Start streaming
    if (ioctl(fd, VIDIOC_STREAMON, NULL) == -1) {
        perror("VIDIOC_STREAMON");
        close(fd);
        return 1;
    }

    // Dequeue and write frame
    struct v4l2_buffer buf2;
    buf2.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf2.index = 0;
    buf2.memory = V4L2_MEMORY_MMAP;
    buf2.length = BUFFER_SIZE;
    if (ioctl(fd, VIDIOC_DQBUF, &buf2) == -1) {
        perror("VIDIOC_DQBUF");
        close(fd);
        return 1;
    }
    if (buf2.bytesused <= 0) {
        fprintf(stderr, "No frame available\n");
        close(fd);
        return 1;
    }
    FILE* file = fopen("image.jpg", "wb");
    if (file == NULL) {
        perror("fopen");
        close(fd);
        return 1;
    }
    fwrite(buf2.buffer, buf2.length, 1, file);
    fclose(file);

    // Clean up
    for (int i = 0; i < NUM_BUFFERS; i++) {
        munmap(buffers[i], BUFFER_SIZE);
    }
    close(fd);

    return 0;
}

void sigint_handler(int sig) {
    // Stop streaming
    if (ioctl(fd, VIDIOC_STREAMOFF, NULL) == -1) {
        perror("VIDIOC_STREAMOFF");
        return;
    }

    // Munmap buffers
    for (int i = 0; i < NUM_BUFFERS; i++) {
        munmap(buffers[i], BUFFER_SIZE);
    }

    // Close file
    fclose(file);

    // Close device
    close(fd);
}

