#include <fcntl.h>
#include <unistd.h>
#include <sys/select.h>
#include <signal.h>
#include <pigpio.h>
#include <libjpeg.h>

#define WIDTH  640
#define HEIGHT 480
#define KERNEl 2
#define QUALITY 75

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open the USB camera
    int fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Request a buffer
    struct v4l2_buffer buf;
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.index = 0;
    buf.length = 0;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.m.m.offset = 0;
    buf.m.m.size = sizeof(buf);
    if (ioctl(fd, VIDIOC_G_FMT, &buf) < 0) {
        perror("VIDIOC_G_FMT");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Map the buffer
    void* ptr = mmap(NULL, buf.m.m.size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.m.offset);
    if (ptr == MAP_FAILED) {
        perror("mmap");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set the format to YUYV
    struct v4l2_format fmt;
    fmt.type = V4L2_FMT_YUYV;
    fmt.fmt.pix_size = buf.m.m.size;
    fmt.fmt.pix_format = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix_field = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix_encoding = V4L2_PIX_FMT_YUYV;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        munmap(ptr, buf.m.m.size);
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set the resolution to 640x480
    struct v4l2_control control;
    control.id = V4L2_CTRL_V4L2_CTRL_S Can1;
    control.value = 0x00000001;
    if (ioctl(fd, VIDIOC_S_CTRL, &control) < 0) {
        perror("VIDIOC_S_CTRL");
        munmap(ptr, buf.m.m.size);
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set the frame rate to 30 FPS
    control.id = V4L2_CTRL_V4L2_CTRL_S Can2;
    control.value = 0x00000003;
    if (ioctl(fd, VIDIOC_S_CTRL, &control) < 0) {
        perror("VIDIOC_S_CTRL");
        munmap(ptr, buf.m.m.size);
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set the queue size to 1
    control.id = V4L2_CTRL_V4L2_CTRL_S Can3;
    control.value = 0x00000001;
    if (ioctl(fd, VIDIOC_S_CTRL, &control) < 0) {
        perror("VIDIOC_S_CTRL");
