#include <unistd.h>
#include <pigpio.h>
#include <linux/videodev2.h>

#define VIDEO_DEVICE "/dev/video0"

int main() {
    int fd, ret;
    struct v4l2_capability cap;
    struct v4l2_frmsize_range frmsize;
    struct v4l2_frameintervals frameintervals;
    struct v4l2_control control;
    char buf[1024];

    // Open the device
    fd = open(VIDEO_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open device");
        return 1;
    }

    // Query capabilities
    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret < 0) {
        perror("Failed to query capabilities");
        close(fd);
        return 1;
    }

    // Check if the device supports frame-size and interval enumeration
    if (!(cap.capabilities & V4L2_CAP_VIDEO_M2M) || !(cap.capabilities & V4L2_CAP_VIDEO_M2M)) {
        printf("Device does not support frame-size or interval enumeration\n");
        close(fd);
        return 1;
    }

    // Enumerate frame sizes
    ret = ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize);
    if (ret < 0) {
        perror("Failed to enumerate frame sizes");
        close(fd);
        return 1;
    }

    // Print supported resolutions
    printf("Supported resolutions:\n");
    for (int i = 0; i < frmsize.count; i++) {
        printf("%dx%d\n", frmsize.width[i], frmsize.height[i]);
    }

    // Enumerate frame intervals
    ret = ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frameintervals);
    if (ret < 0) {
        perror("Failed to enumerate frame intervals");
        close(fd);
        return 1;
    }

    // Print supported frame rates
    printf("Supported frame rates:\n");
    for (int i = 0; i < frameintervals.count; i++) {
        printf("%d FPS\n", frameintervals.interval[i].num);
    }

    // Query autofocus support
    ret = ioctl(fd, VIDIOC_QUERYCTRL, &control);
    if (ret < 0) {
        perror("Failed to query autofocus support");
        close(fd);
        return 1;
    }

    // Check if autofocus is supported
    if (control.capabilities & V4L2_CTRL_TYPE_AUTOFocus) {
        printf("Autofocus is supported\n");
    } else {
        printf("Autofocus is not supported\n");
    }

    // Close the device
    close(fd);

    return 0;
}

