// Define constants for servo positions
#define SERVO_MIN 1000
#define SERVO_MAX 2000
#define SERVO_CENTER 1500

// Define constants for button pins
#define BUTTON_UP GPIO6
#define BUTTON_DOWN GPIO7
#define BUTTON_LEFT GPIO8
#define BUTTON_RIGHT GPIO9

// Define constants for servo pins
#define SERVO_PAN GPIO4
#define SERVO_TILT GPIO5

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio: %d\n", gpioInitialise());
        return 1;
    }

    // Configure internal pull-up resistors on button pins
    gpioSetMode(BUTTON_UP, GPIO_INPUT);
    gpioSetMode(BUTTON_DOWN, GPIO_INPUT);
    gpioSetMode(BUTTON_LEFT, GPIO_INPUT);
    gpioSetMode(BUTTON_RIGHT, GPIO_INPUT);
    gpioClev(BUTTON_UP);
    gpioClev(BUTTON_DOWN);
    gpioClev(BUTTON_LEFT);
    gpioClev(BUTTON_RIGHT);

    // Configure servo pins for PWM output
    gpioSetMode(SERVO_PAN, GPIO_MODE PWM);
    gpioSetMode(SERVO_TILT, GPIO_MODE PWM);
    gpioPWMWrite(SERVO_PAN, SERVO_CENTER);
    gpioPWMWrite(SERVO_TILT, SERVO_CENTER);

    // Install SIGINT/SIGTERM handler
    signal(SIGINT, sigHandler);
    signal(SIGTERM, sigHandler);

    // Print startup message
    printf("Pigpio camera pan-tilt system\n");
    printf("  - Pan servo: GPIO4 (servo pin)\n");
    printf("  - Tilt servo: GPIO5 (servo pin)\n");
    printf("  - Up button: GPIO6 (active-low)\n");
    printf("  - Down button: GPIO7 (active-low)\n");
    printf("  - Left button: GPIO8 (active-low)\n");
    printf("  - Right button: GPIO9 (active-low)\n");
    printf("  - Servo center position: %d us\n", SERVO_CENTER);

    // Main loop
    while (1) {
        // Read button states
        int up = gpioRead(BUTTON_UP);
        int down = gpioRead(BUTTON_DOWN);
        int left = gpioRead(BUTTON_LEFT);
        int right = gpioRead(BUTTON_RIGHT);

        // Update servo positions
        int pan = SERVO_CENTER;
        int tilt = SERVO_CENTER;
        if (up == 0) {
            pan += 10;
            if (pan < SERVO_MIN) pan = SERVO_MIN;
            if (pan > SERVO_MAX) pan = SERVO_MAX;
        }
        if (down == 0) {
            tilt += 10;
            if (tilt < SERVO_MIN) tilt = SERVO_MIN;
            if (tilt > SERVO_MAX) tilt = SERVO_MAX;
        }
        if (left == 0) {
            tilt -= 10;
            if (tilt < SERVO_MIN) tilt = SERVO_MIN;
            if (tilt > SERVO_MAX) tilt = SERVO_MAX;
        }
        if (right == 0) {
            pan -= 10;
            if (pan < SERVO_MIN) pan = SERVO_MIN;
            if (pan > SERVO_MAX) pan = SERVO_MAX;
        }

        // Write new servo positions
        gpioPWMWrite(SERVO_PAN, pan);
        gpioPWMWrite(SERVO_TILT, tilt);

        // Delay
        usleep(50 * 1000);
    }

    // Clean up
    gpioTerminate();
    return 0;
}

void sigHandler(int sig) {
    // Stop PWM on both servo pins
    gpioPWMWrite(SERVO_PAN, 0);
    gpioPWMWrite(SERVO_TILT, 0);

    // Clean up
    gpioTerminate();
    exit(0);
}

