            if (pan > SERVO_MAX) pan = SERVO_MAX;
        }

        // Write new servo positions
        gpioPWMWrite(SERVO_PAN, pan);
        gpioPWMWrite(SERVO_TILT, tilt);

        // Delay
        usleep(50 * 1000);
    }

    // Clean up
    gpioTerminate();
    return 0;
}

void sigHandler(int sig) {
    // Stop PWM on both servo pins
    gpioPWMWrite(SERVO_PAN, 0);
    gpioPWMWrite(SERVO_TILT, 0);

    // Clean up
    gpioTerminate();
    exit(0);
}
