    int gpio_fd;
    struct gpiod_context *ctx;
    struct gpiod_line *line;
    struct gpiod_line_event *event;
    struct stat sb;
    char filename[256];
    char log_message[256];

    // Open log file for writing
    if (access(LOG_FILE, W_OK) != 0) {
        syslog(LOG_ERR, "Failed to open log file %s for writing", LOG_FILE);
        return 1;
    }

    // Open GPIO chip
    gpio_fd = gpiod_open("/dev/gpiod", O_RDWR);
    if (gpio_fd < 0) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        return 1;
    }

    // Claim GPIO17 as input with edge-falling detection
    ctx = gpiod_context_new(gpio_fd, GPIO_PIN);
    if (!ctx) {
        syslog(LOG_ERR, "Failed to create gpiod context");
        gpiod_close(gpio_fd);
        return 1;
    }

    line = gpiod_line_new(ctx, GPIO_PIN, GpioEdgeFalling, NULL);
    if (!line) {
        syslog(LOG_ERR, "Failed to create gpiod line");
        gpiod_context_free(ctx);
