    if (camera_fd < 0) {
        syslog(LOG_ERR, "Failed to open camera");
        gpiod_line_free(line);
        gpiod_context_free(ctx);
        gpiod_close(gpio_fd);
        return 1;
    }

    // Get image dimensions
    if (camera_get_parameter(camera_fd, CAMERA_PARAM_WIDTH, &sb) < 0) {
        syslog(LOG_ERR, "Failed to get camera parameter");
        camera_close(camera_fd);
        gpiod_line_free(line);
        gpiod_context_free(ctx);
        gpiod_close(gpio_fd);
        return 1;
    }

    // Create timestamped filename
    time_t now = time(NULL);
    strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S_%c.jpg", localtime(&now));

