    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file for writing");
        camera_close(camera_fd);
        gpiod_line_free(line);
        gpiod_context_free(ctx);
        gpiod_close(gpio_fd);
        return 1;
    }

