    event = gpiod_line_wait_for_event(line, 1000);
    if (!event) {
        syslog(LOG_ERR, "Failed to wait for event");
        fclose(log_file);
        camera_close(camera_fd);
        gpiod_line_free(line);
        gpiod_context_free(ctx);
        gpiod_close(gpio_fd);
        return 1;
    }

    // Log event
    syslog(LOG_INFO, "Motion detected at %s", filename);

