    char command[256];
    sprintf(command, "libcamera-still -o %s --width %d --height %d -q 85 --timeout 2000 --nopreview", filename, sb.st_w, sb.st_h, sb.st_h);
    int ret = system(command);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to capture image: %s", command);
        fclose(log_file);
        camera_close(camera_fd);
        gpiod_line_free(line);
        gpiod_context_free(ctx);
        gpiod_close(gpio_fd);
        return 1;
    }

    // Log result
    if (ret == 0) {
        syslog(LOG_INFO, "Image captured successfully");
    } else {
        syslog(LOG_ERR, "Failed to capture image: %s", command);
    }

    // Close log file
    fclose(log_file);

    // Release resources
    gpiod_line_free(line);
    gpiod_context_free(ctx);
    gpiod_close(gpio_fd);
    camera_close(camera_fd);

    return 0;
}

