#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/select.h>
#include <sys/ioctl.h>
#include <sys/videodev2.h>
#include <errno.h>

#define WIDTH  640
#define HEIGHT 480
#define CROP_X 100
#define CROP_Y 50
#define CROP_W 200
#define CROP_H 150

int main() {
    int fd, ret;
    struct v4l2_buffer buf;
    struct v4l2_format fmt;
    struct v4l2_request_buf req;
    struct v4l2_image img;
    void *mem;
    struct stat sb;
    struct sigaction sa;

    // Install signal handler
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    sigaddset(&sa.sa_mask, SIGTERM);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open /dev/video0
    if ((fd = open("/dev/video0", O_RDWR)) < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Verify it's a V4L2 device
    if (ioctl(fd, VIDIOC_QUERYCAP, &sb) < 0) {
        perror("VIDIOC_QUERYCAP");
        exit(EXIT_FAILURE);
    }
    if (!(sb.cap & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Not a V4L2 video capture device\n");
        exit(EXIT_FAILURE);
    }

    // Set up V4L2 format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_PIX_FMT_YUYV;
    fmt.width = WIDTH;
    fmt.height = HEIGHT;
    fmt.field = V4L2_FIELD_NONE;
    fmt.colorspace = V4L2_COLORSPACE_SMPTE170;
    fmt.yuv_format = V4L2_YUYV;
    fmt.yuv_width = WIDTH;
    fmt.yuv_height = HEIGHT;
    fmt.yuv_component_count = 2;
    fmt.yuv_component_type = V4L2_YUYV;
    fmt.yuv_chroma_location = V4L2_CHromaLocation_420;

    // Negotiate format
    if (ioctl(fd, VIDIOC_SIOCSETFB, &fmt) < 0) {
        perror("VIDIOC_SIOCSETFB");
        exit(EXIT_FAILURE);
    }

    // Request a single buffer
    memset(&req, 0, sizeof(req));
    req.type = V4L2_TYPE_BUFFER;
    req.count = 1;
    req.memory = V4L2_MEMORY_MMAP;
    req.m mem = NULL;
    req.m.m mem = NULL;
    req.m.m mem = NULL;
    req.m.m mem = NULL;
    ret = ioctl(fd, VIDIOC_REQBUFS, &req);
    if (ret < 0) {
        perror("VIDIOC_REQBUFS");
        exit(EXIT_FAILURE);
    }

    // Map the buffer
    if ((mem = mmap(NULL, req.size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, req.index)) == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    // Query the buffer
    memset(&buf, 0, sizeof(buf));
    ret = ioctl(fd, VIDIOC_QUERYBUF, &buf);
    if (ret < 0) {
        perror("VIDIOC_QUERYBUF");
        exit(EXIT_FAILURE);
    }

    // Start streaming
    ret = ioctl(fd, VIDIOC_QBUF, &buf);
    if (ret < 0) {
        perror("VIDIOC_QBUF");
        exit(EXIT_FAILURE);
    }

    // Wait for a frame
    struct timeval tv;
    tv.tv_sec = 2;
    tv.tv_usec = 0;
    fd_set set;
    FD_ZERO(&set);
    FD_SET(fd, &set);
    ret = select(fd + 1, &set, NULL, NULL, &tv);
    if (ret < 0) {
        perror("select");
        exit(EXIT_FAILURE);
    }
    if (ret == 0) {
        printf("Timeout\n");
        exit(EXIT_FAILURE);
    }
    if (ret > 0 && FD_ISSET(fd, &set)) {
        // Dequeue the buffer
        ret = ioctl(fd, VIDIOC_QBUF, &buf);
        if (ret < 0) {
            perror("VIDIOC_QBUF");
            exit(EXIT_FAILURE);
        }

        // Verify the frame
        if (buf.length != WIDTH * HEIGHT * 2) {
            fprintf(stderr, "Invalid frame size\n");
            exit(EXIT_FAILURE);
        }
        if (buf.field != V4L2_FIELD_NONE) {
            fprintf(stderr, "Invalid field\n");
            exit(EXIT_FAILURE);
        }
        if (buf.format != V4L2_PIX_FMT_YUYV) {
            fprintf(stderr, "Invalid format\n");
            exit(EXIT_FAILURE);
        }

        // Crop the frame
        void *src = mem + buf.data;
        void *dst = src + buf.data + buf.planes[0].offset;
        memcpy(dst, src, WIDTH * HEIGHT * 2);
        for (int y = 0; y < HEIGHT; y++) {
            for (int x = 0; x < WIDTH; x++) {
                int src_y = y * WIDTH + x;
                int dst_y = y * WIDTH + x;
                int src_y2 = (y + CROP_Y) * WIDTH + x;
                int dst_y2 = (y + CROP_Y) * WIDTH + x;
                int src_u = src_y * 2;
                int dst_u = dst_y * 2;
                int src_v = src_y2 * 2;
                int dst_v = dst_y2 * 2;
                memcpy(dst + dst_u, src + src_u, 2);
                memcpy(dst + dst_v, src + src_v, 2);
            }
        }

        // Save the cropped frame
        FILE *f = fopen("cropped.yuv", "wb");
        if (f == NULL) {
            perror("fopen");
            exit(EXIT_FAILURE);
        }
        fwrite(dst, 2, WIDTH * HEIGHT, f);
        fclose(f);
    }

    // Munmap the buffer
    munmap(mem, req.size);

    // Close the file descriptor
    if (close(fd) < 0) {
        perror("close");
        exit(EXIT_FAILURE);
    }

    return EXIT_SUCCESS;
}

