// Define constants for servo angles and PWM frequencies
#define SERVO_MIN 0
#define SERVO_MAX 180
#define SERVO_MIN_PWM 500
#define SERVO_MAX_PWM 2500
#define PWM_FREQ 50

// Define constants for GPIO pins
#define PAN_PIN 17
#define TILT_PIN 18

// Define a structure to hold servo angles and PWM values
typedef struct {
    int pan_angle;
    int tilt_angle;
    int pan_pwm;
    int tilt_pwm;
} ServoConfig;

// Function to initialize pigpio
void init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio: %d\n", gpioInitialise());
        exit(1);
    }
}

// Function to clean up pigpio
void cleanup_pigpio() {
    gpioTerminate();
}

// Function to set servo angles and PWM values
void set_servos(ServoConfig *servo) {
    if (servo->pan_angle < SERVO_MIN || servo->pan_angle > SERVO_MAX) {
        fprintf(stderr, "Error: Pan angle out of range (%d)\n", servo->pan_angle);
        return;
    }
    if (servo->tilt_angle < SERVO_MIN || servo->tilt_angle > SERVO_MAX) {
        fprintf(stderr, "Error: Tilt angle out of range (%d)\n", servo->tilt_angle);
        return;
    }
    if (gpioWrite(PAN_PIN, servo->pan_pwm) < 0) {
        fprintf(stderr, "Error setting pan servo PWM: %d\n", gpioWrite(PAN_PIN));
        return;
    }
    if (gpioWrite(TILT_PIN, servo->tilt_pwm) < 0) {
        fprintf(stderr, "Error setting tilt servo PWM: %d\n", gpioWrite(TILT_PIN));
        return;
    }
}

// Function to read user input
void read_input(ServoConfig *servo) {
    char input;
    scanf(" %c", &input);
    if (input == 'q') {
        servo->pan_angle = servo->tilt_angle = SERVO_MIN;
        servo->pan_pwm = SERVO_MIN_PWM;
        servo->tilt_pwm = SERVO_MIN_PWM;
        return;
    }
    if (input == '\n') {
        return;
    }
    if (input == 'u') {
        servo->pan_angle = (servo->pan_angle + 5) % (SERVO_MAX - SERVO_MIN + 1) + SERVO_MIN;
        servo->tilt_angle = (servo->tilt_angle + 5) % (SERVO_MAX - SERVO_MIN + 1) + SERVO_MIN;
    } else if (input == 'd') {
        servo->pan_angle = (servo->pan_angle - 5 + SERVO_MAX) % (SERVO_MAX - SERVO_MIN + 1) + SERVO_MIN;
