void update_lcd(int flow_rate, int volume) {
    char flow_rate_str[10];
    sprintf(flow_rate_str, "%d", flow_rate);
    char volume_str[10];
    sprintf(volume_str, "%d", volume);
    char lcd_buffer[LCD_ROWS * (LCD_COLS + 1)];
    sprintf(lcd_buffer, "Flow Rate: %s | Volume: %s", flow_rate_str, volume_str);
    if (i2cWrite(I2C_BUS, I2C_ADDRESS, lcd_buffer, LCD_ROWS * (LCD_COLS + 1)) < 0) {
        perror("i2cWrite");
    }
}

int main() {
    struct sigaction sa;
    struct sigaction old_sa, new_sa;

    // Initialize pigpio
    init_pigpio();

    // Set up signal handlers
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, &old_sa) < 0) {
        perror("sigaction");
        exit(1);
    }
    sa.sa_handler = sigterm_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGTERM, &sa, &old_sa) < 0) {
        perror("sigaction");
        exit(1);
    }

    // Initialize variables
    int pulses = 0;
    int volume = 0;
    struct timeval last_update = timeval();
    struct timeval current_time;

    while (1) {
        // Read pulses from the sensor
        pulses = read_pulses();
        if (pulses < 0) {
            continue;
        }

        // Calculate flow rate
        int flow_rate = pulses / UPDATE_INTERVAL;

        // Update volume
        volume += flow_rate;

        // Update last update time
        gettimeofday(&current_time, NULL);
        if (current_time.tv_sec - last_update.tv_sec > UPDATE_INTERVAL) {
            last_update = current_time;
            printf("Flow Rate: %d L/min, Volume: %d L\n", flow_rate, volume);
        }

        // Update LCD display
        update_lcd(flow_rate, volume);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up pigpio resources
    cleanup_pigpio();

    return 0;
}

void sigint_handler(int sig) {
    cleanup_pigpio();
    exit(0);
}

void sigterm_handler(int sig) {
    cleanup_pigpio();
    exit(0);
