#include <sys/wait.h>
#include <unistd.h>
#include <gpiod/gpiod.h>

// Define constants
#define ROWS 8
#define COLS 8
#define DELAY 150

// Define GPIO pin numbers
#define ROW_PINS { GPIO2, GPIO3, GPIO4, GPIO17, GPIO27, GPIO22, GPIO10, GPIO9 }
#define COL_PINS { GPIO14, GPIO15, GPIO18, GPIO23, GPIO24, GPIO25, GPIO8, GPIO7 }

// Define signal handlers
void sigint_handler(int sig) {
    gpiod_chip_close(chip);
    exit(0);
}

void sigterm_handler(int sig) {
    gpiod_chip_close(chip);
    exit(0);
}

int main(int argc, char **argv) {
    // Initialize signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Create a new chip
    chip = gpiod_chip_open("gpiochip-pi", NULL, NULL);
    if (!chip) {
        fprintf(stderr, "Failed to create chip\n");
        return 1;
    }

    // Open row and column lines
    for (int i = 0; i < ROWS; i++) {
        int row = gpiod_line_request_output(chip, ROW_PINS[i], GPIOF_OUTPUT, NULL);
        if (!row) {
            fprintf(stderr, "Failed to open row %d\n", ROW_PINS[i]);
            gpiod_chip_close(chip);
            return 1;
        }
    }
    for (int i = 0; i < COLS; i++) {
        int col = gpiod_line_request_output(chip, COL_PINS[i], GPIOF_OUTPUT, NULL);
        if (!col) {
            fprintf(stderr, "Failed to open column %d\n", COL_PINS[i]);
            for (int j = 0; j < ROWS; j++) {
                gpiod_line_release(chip, ROW_PINS[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Set up chip
    gpiod_chip_set_chip(chip, NULL, NULL);

    // Main loop
    while (1) {
        // Clear the matrix
        for (int i = 0; i < ROWS; i++) {
            for (int j = 0; j < COLS; j++) {
                gpiod_line_set(chip, COL_PINS[j], GPIOF_HIGH);
                gpiod_line_set(chip, ROW_PINS[i], GPIOF_LOW);
            }
        }

        // Scan columns
        for (int i = 0; i < COLS; i++) {
            gpiod_line_set(chip, COL_PINS[i], GPIOF_LOW);
            for (int j = 0; j < ROWS; j++) {
                gpiod_line_set(chip, ROW_PINS[j], GPIOF_HIGH);
            }
            usleep(DELAY * 1000);
        }
    }

    // Clean up
    for (int i = 0; i < ROWS; i++) {
        gpiod_line_release(chip, ROW_PINS[i]);
    }
    for (int i = 0; i < COLS; i++) {
        gpiod_line_release(chip, COL_PINS[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}
