#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDRESS 0x4C
#define I2C_REGISTER 0x0D
#define I2C_READ 0x00
#define I2C_WRITE 0x01
#define FILE_NAME "depth_log.csv"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C handle
    int i2c_fd = pigpioOpen(1, PI_I2C, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    int log_fd = open(FILE_NAME, O_RDWR | O_CREAT | O_WRONLY, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Check if file exists and write header row
    struct stat sb;
    if (fstat(log_fd, &sb) == -1) {
        fprintf(stderr, "Failed to get file stats\n");
        close(log_fd);
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (sb.st_size == 0) {
        fprintf(log_fd, "timestamp,distance\n");
    }

    // Main loop
    while (1) {
        // Write register address
        if (pigpioWrite(i2c_fd, I2C_ADDRESS, I2C_WRITE, &I2C_REGISTER) < 0) {
            fprintf(stderr, "Failed to write to I2C register\n");
            close(log_fd);
            pigpioClose(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Read two bytes
        unsigned char data[2];
        if (pigpioRead(i2c_fd, I2C_ADDRESS, I2C_READ, data, 2) < 0) {
            fprintf(stderr, "Failed to read from I2C register\n");
            close(log_fd);
            pigpioClose(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Convert big-endian bytes to 16-bit distance
        int distance = (data[0] << 8) | data[1];

        // Log timestamped distance reading
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_fd, "%s,%d\n", timestamp, distance);

        // Sleep for 100ms
        usleep(100000);
    }

    // Close log file
    close(log_fd);

    // Close I2C handle
    pigpioClose(i2c_fd);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

