#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <libgpiod/libgpiod.h>

#define GPIO_LINE 4
#define GPIO_LED 17
#define POLL_INTERVAL 100
#define LOG_FILE "proximity.log"

int main(int argc, char **argv) {
    gpiod_context_t ctx;
    gpiod_chip_t chip;
    gpiod_line_t line;
    gpiod_line_event_t event;
    gpiod_line_event_filter_t filter;
    gpiod_line_event_filter_add(&filter, GpioEventEdgeFalling, NULL, NULL);
    gpiod_line_event_filter_add(&filter, GpioEventRising, NULL, NULL);
    gpiod_line_event_filter_add(&filter, GpioEventEdgeBoth, NULL, NULL);

    // Open the GPIO chip
    if (gpiod_chip_open_by_name(&chip, "gpiochip4") < 0) {
        if (gpiod_chip_open_by_name(&chip, "gpiochip0") < 0) {
            perror("Failed to open GPIO chip");
            return 1;
        }
    }

    // Open the GPIO line
    if (gpiod_line_open(&line, &chip, GPIO_LINE, GPIO_INPUT) < 0) {
        perror("Failed to open GPIO line");
        return 1;
    }

    // Set the initial state of the LED
    if (gpiod_line_set_value(&line, GPIO_LED, 0) < 0) {
        perror("Failed to set LED value");
        return 1;
    }

    // Register the event filter
    if (gpiod_line_event_register(&line, &filter) < 0) {
        perror("Failed to register event filter");
        return 1;
    }

    // Poll the GPIO line
    while (1) {
        // Wait for the next event
        gpiod_line_wait(&line, POLL_INTERVAL);

        // Check if an event occurred
        if (gpiod_line_get_event(&line, &event) < 0) {
            perror("Failed to get event");
            return 1;
        }

        // Check if the event is a falling edge
        if (event.type == GpioEventEdgeFalling) {
            // Log the event
            time_t now = time(NULL);
            struct tm *timeinfo;
            char timestamp[32];
            timeinfo = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);
            FILE *log_file = fopen(LOG_FILE, "a");
            if (log_file == NULL) {
                perror("Failed to open log file");
                return 1;
            }
            fprintf(log_file, "%s Object detected\n", timestamp);
            fclose(log_file);

            // Blink the LED
            gpiod_line_set_value(&line, GPIO_LED, 1);
            usleep(POLL_INTERVAL * 1000);
            gpiod_line_set_value(&line, GPIO_LED, 0);
        }
    }

    // Release resources
    gpiod_line_close(&line);
    gpiod_chip_close(&chip);

    return 0;
}

