#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/types.h>
#include <sys/wait.h>

#define I2C_ADDRESS 0x39
#define I2C Bus 1
#define CSV_FILE "color_proximity_log.csv"

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C bus
    int i2c_fd = pigpio_i2c_open(I2C Bus, I2C_ADDRESS);
    if (i2c_fd < 0) {
        perror("pigpio_i2c_open");
        gpioTerminate();
        return 1;
    }

    // Read sensor ID register
    unsigned char sensor_id;
    if (pigpio_i2c_read(i2c_fd, 0x92, &sensor_id) < 0) {
        pigpio_i2c_close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (sensor_id != 0xAB) {
        pigpio_i2c_close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (pigpio_i2c_write(i2c_fd, 0x80, 0x03) < 0) {
        pigpio_i2c_close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (pigpio_i2c_write(i2c_fd, 0x81, 0xDB) < 0) {
        pigpio_i2c_close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (pigpio_i2c_write(i2c_fd, 0x83, 0xF6) < 0) {
        pigpio_i2c_close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (pigpio_i2c_write(i2c_fd, 0x8E, 0x87) < 0) {
        pigpio_i2c_close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (pigpio_i2c_write(i2c_fd, 0xF1, 0x03) < 0) {
        pigpio_i2c_close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (pigpio_i2c_write(i2c_fd, 0x90, 0x01) < 0) {
        pigpio_i2c_close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    int csv_fd = open(CSV_FILE, O_RDWR | O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (csv_fd < 0) {
        perror("open");
        pigpio_i2c_close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    struct timespec start_time;
    struct timespec end_time;
    while (1) {
        // Read RGB values
        unsigned char rgb[6];
        if (pigpio_i2c_read(i2c_fd, 0x96, rgb) < 0) {
            pigpio_i2c_close(i2c_fd);
            gpioTerminate();
            return 1;
        }
        unsigned int red = (rgb[0] << 8) | rgb[1];
        unsigned int green = (rgb[2] << 8) | rgb[3];
        unsigned int blue = (rgb[4] << 8) | rgb[5];

        // Read proximity value
        unsigned char proximity;
        if (pigpio_i2c_read(i2c_fd, 0x9C, &proximity) < 0) {
            pigpio_i2c_close(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Log data
        if (proximity > 200) {
            time_t now = time(NULL);
            struct tm *time_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);
            fprintf(csv_fd, "%s,%d,%d,%d,%d\n", timestamp, red, green, blue, proximity);
        }

        // Sleep for 100 ms
        clock_gettime(CLOCK_MONOTONIC, &start_time);
        usleep(100000);
        clock_gettime(CLOCK_MONOTONIC, &end_time);
        if (end_time.tv_sec != start_time.tv_sec || end_time.tv_nsec != start_time.tv_nsec) {
            // Sleep for remaining time
            usleep((end_time.tv_sec - start_time.tv_sec) * 1000000 + (end_time.tv_nsec - start_time.tv_nsec));
        }
    }

    // Close I2C bus and CSV file
    pigpio_i2c_close(i2c_fd);
    close(csv_fd);
    gpioTerminate();

    return 0;
}

