#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pigpio.h>
#include <stdint.h>
#include <stdbool.h>

#define I2C_ADDRESS 0x5A
#define I2C_FILE "/dev/i2c-1"
#define MEAS_RATE0 0x08
#define COMMAND 0x47
#define PART_ID 0x00
#define PS_DATA0 0x24
#define PS_DATA1 0x25
#define CSV_FILE "heartrate.csv"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    // Install signal handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open I2C file
    int fd = open(I2C_FILE, O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(fd);
        return 1;
    }

    // Read PART_ID register
    uint8_t part_id;
    if (i2c_smbus_read_byte(fd, PART_ID) < 0) {
        perror("i2c_smbus_read_byte");
        close(fd);
        return 1;
    }
    if (part_id != 0x55) {
        fprintf(stderr, "Invalid Si1182 part ID 0x%02x\n", part_id);
        close(fd);
        return 1;
    }

    // Configure continuous proximity measurement
    if (i2c_smbus_write_byte(fd, MEAS_RATE0, 0x01) < 0) {
        perror("i2c_smbus_write_byte");
        close(fd);
        return 1;
    }
    if (i2c_smbus_write_byte(fd, COMMAND, 0x01) < 0) {
        perror("i2c_smbus_write_byte");
        close(fd);
        return 1;
    }

    // Open CSV file
    FILE *fp = fopen(CSV_FILE, "w");
    if (!fp) {
        perror("fopen");
        close(fd);
        return 1;
    }

    while (running) {
        // Read proximity data
        uint16_t data = i2c_smbus_read_word_data(fd, PS_DATA0, PS_DATA1);
        if (data < 0) {
            fprintf(stderr, "I2C read failed\n");
            continue;
        }

        // Combine data and compute BPM
        uint16_t combined = (data >> 8) | (data & 0xFF);
        uint32_t timestamp = time(NULL);
        uint32_t bpm = (combined * 1000) / 10;

        // Log sample
        fprintf(fp, "%lu,%d\n", timestamp, bpm);
        fflush(fp);
    }

    // Close I2C file and CSV file
    close(fd);
    fclose(fp);

    return 0;
}

