#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDRESS 0x29
#define I2C_TIMEOUT 100
#define GPIO_PIN 17
#define GPIO_MODE_OUTPUT
#define GPIO Pull_up_down GPIO_PUD_UP

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Check if I2C bus 1 is available
    int i2c_fd = -1;
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO 17 with pull-up
    if (gpioMode(GPIO_PIN, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (gpioPullUpDn(GPIO_PIN, GPIO Pull_up_down) < 0) {
        perror("gpioPullUpDn");
        close(i2c_fd);
        gpioTerminate();
        return 1;
