#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDRESS 0x45
#define I2C Bus 1
#define SAMPLE_INTERVAL 200
#define SAMPLE_RATE 50
#define BUFFER_SIZE 10

char timestamp[BUFFER_SIZE];

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C handle
    int i2c_fd = pigpioOpen(I2C Bus, pigpioI2C_MODE_BROADCAST, NULL);
    if (i2c_fd < 0) {
        perror("pigpioOpen");
        gpioTerminate();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("distance_log.txt", "w");
    if (log_file == NULL) {
        perror("fopen");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    struct timespec start_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (1) {
        // Trigger measurement
        pigpioWrite(i2c_fd, I2C_ADDRESS, pigpioWRITE, 0x00, 1);

        // Wait for 50 ms
        usleep(50 * 1000);

        // Read 16-bit distance result
        unsigned short distance;
        if (pigpioRead(i2c_fd, I2C_ADDRESS, pigpioREAD, 0x00, &distance, 2) < 0) {
            printf("I2C read error\n");
            continue;
        }

        // Convert distance to millimeters
        distance >>= 1;
        distance *= 2;

        // Format timestamp
        strftime(timestamp, BUFFER_SIZE, "%Y-%m-%d %H:%M:%S", localtime(&start_time));

        // Log and print distance
        fprintf(log_file, "%s, %d\n", timestamp, distance);
        printf("%s, %d\n", timestamp, distance);

        // Sleep for SAMPLE_INTERVAL ms
        usleep(SAMPLE_INTERVAL * 1000);
    }

    // Close log file and I2C handle
    fclose(log_file);
    pigpioClose(i2c_fd);
    gpioTerminate();

    return 0;
}

