    if (gpioSetup(GPIO17, PI_OUTPUT) < 0 || gpioSetup(GPIO18, PI_OUTPUT) < 0) {
        perror("gpioSetup");
        gpioTerminate();
        return 1;
    }

    // Set GPIO 17 and 18 as high to initialize the sensors
    gpioWrite(GPIO17, 1);
    gpioWrite(GPIO18, 1);
    usleep(100000); // Wait for 100ms

    // Open log file for writing
    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("fopen");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    while (1) {
        // Read both sensors
        int sensor1 = gpioRead(GPIO17);
        int sensor2 = gpioRead(GPIO18);

        // Log the readings
