            i2c_close(i2c_fd);
            pigpio_close(pigpio);
            return 1;
        }
        pigpio_write(pigpio, GPIO_PIN, PI_HIGH);
    } else {
        pigpio_write(pigpio, GPIO_PIN, PI_LOW);
    }

    // Repeat loop
    while (1) {
        // Read distance measurement
        ret = i2c_send_recv(i2c_fd, &msg, 100);
        if (ret < 0) {
            perror("i2c_send_recv");
            close(log_fd);
            i2c_close(i2c_fd);
            pigpio_close(pigpio);
            return 1;
        }

        // Convert distance to centimeters
        distance = (buf[0] << 8) | buf[1];

        // Log distance measurement
        gettimeofday(&end_time, NULL);
        tv.tv_sec = end_time.tv_sec;
        tv.tv_usec = end_time.tv_nsec / 1000;
        printf("%s %d\n", ctime(&tv), distance);
        write(log_fd, &distance, sizeof(distance));

        // Check distance and turn on LED
        if (distance < 20) {
            pigpio_write(pigpio, GPIO_PIN, PI_HIGH);
        } else {
            pigpio_write(pigpio, GPIO_PIN, PI_LOW);
        }
    }

    // Clean up
    pigpio_close(pigpio);
    close(log_fd);
    i2c_close(i2c_fd);
    pigpio_exit();
    return 0;
}

