#include <sys/ioctl.h>
#include <termios.h>
#include <unistd.h>

#define I2C_ADDRESS 0x60
#define I2C_ADDRESS2 0x61
#define I2C_REG_PROXIMITY 0x18
#define I2C_REG_AMBIENT_LIGHT 0x16
#define FILE_NAME "biometric_log.txt"

int main() {
    int i2c_fd = -1;
    int i2c_fd2 = -1;
    int pigpio = -1;
    FILE *log_file = NULL;

    // Initialize pigpio
    pigpio = pigpio_init();
    if (pigpio < 0) {
        perror("pigpio_init");
        return 1;
    }

    // Open I2C file descriptor
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        pigpio_close(pigpio);
        return 1;
    }

    // Set I2C bus parameters
    struct i2c_config config;
    config.sda = 5; // GPIO 5
    config.scl = 4; // GPIO 4
    config.mode = I2C_MODE_BUTTERfly;
    config.speed = 100000;
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        pigpio_close(pigpio);
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS2) < 0) {
        perror("ioctl");
        close(i2c_fd);
        pigpio_close(pigpio);
        return 1;
    }

    // Open log file
    log_file = fopen(FILE_NAME, "w");
    if (log_file == NULL) {
        perror("fopen");
        close(i2c_fd);
        pigpio_close(pigpio);
        return 1;
    }

    while (1) {
        // Read proximity data
        int proximity_value = 0;
        for (int retry = 0; retry < 3; retry++) {
            if (i2c_read(i2c_fd, I2C_ADDRESS, I2C_REG_PROXIMITY, &proximity_value, 2) < 0) {
                if (errno == EIO) {
                    if (retry < 2) {
                        usleep(100000); // wait 100ms before retrying
                    } else {
                        break;
                    }
                } else {
                    perror("i2c_read");
                    break;
                }
            } else {
                break;
            }
        }

        // Read ambient light data
        int ambient_light_value = 0;
        for (int retry = 0; retry < 3; retry++) {
            if (i2c_read(i2c_fd, I2C_ADDRESS2, I2C_REG_AMBIENT_LIGHT, &ambient_light_value, 2) < 0) {
                if (errno == EIO) {
                    if (retry < 2) {
                        usleep(100000); // wait 100ms before retrying
                    } else {
                        break;
                    }
                } else {
                    perror("i2c_read");
                    break;
                }
            } else {
                break;
            }
        }

        // Log data
        fprintf(log_file, "%d %d %d\n", (unsigned long)time(NULL), proximity_value, ambient_light_value);

        // Sleep for 500ms
        usleep(500000);
    }

    // Close I2C file descriptor
    close(i2c_fd);
    close(i2c_fd2);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    pigpio_close(pigpio);

    return 0;
}

