#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>
#include <time.h>

#define I2C_ADDRESS 0x50
#define COMMAND_FRAME { 0x50, 0x0A, 0x00, 0x01 }
#define RESPONSE_FRAME_SIZE 15
#define DISTANCE_OFFSET 11
#define DISTANCE_SIZE 2
#define LOG_FILE "intrusion_log.txt"

int main() {
    int fd;
    struct i2c_msg msg;
    struct i2c_msg resp;
    unsigned char cmd[4];
    unsigned char resp_buf[RESPONSE_FRAME_SIZE];
    unsigned char *ptr;
    unsigned char *ptr2;
    unsigned int distance;
    unsigned int i;
    struct timespec start, end;
    struct sigaction sa;
    int ret;
    int log_fd;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set I2C address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set command frame
    memcpy(cmd, COMMAND_FRAME, 4);

    // Sample 10 times per cycle
    for (i = 0; i < 10; i++) {
        // Write command frame
        if (write(fd, cmd, 4) < 0) {
            perror("write");
            close(fd);
            gpioTerminate();
            return 1;
        }

        // Wait at least 10 ms
        usleep(10000);

        // Read response frame
        ret = read(fd, resp_buf, RESPONSE_FRAME_SIZE);
        if (ret < 0) {
            perror("read");
            close(fd);
            gpioTerminate();
            return 1;
        }

        // Validate header
        if (resp_buf[0] != I2C_ADDRESS) {
            printf("Invalid response header\n");
            continue;
        }

        // Extract distance
        ptr = resp_buf + DISTANCE_OFFSET;
        distance = (resp_buf[DISTANCE_SIZE] << 8) | resp_buf[DISTANCE_SIZE + 1];

        // Log event if distance is less than 1000 mm
        if (distance < 1000) {
            time_t now = time(NULL);
            struct tm *ltm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", ltm);
            FILE *log_file = fopen(LOG_FILE, "a");
            if (log_file == NULL) {
                perror("fopen");
                continue;
            }
            fprintf(log_file, "%s %d\n", timestamp, distance);
            fclose(log_file);
        }

        // Delay between sampling cycles
        usleep(100000);
    }

    // Close I2C file descriptor
    close(fd);

    // Terminate GPIO
    gpioTerminate();

    return 0;
}

