#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>

#define I2C_ADDRESS 0x29
#define I2C_TIMEOUT 100
#define I2C_READ 0x00
#define I2C_WRITE 0x01
#define SYSRANGE_START 0x00
#define RESULT_INTERRUPT_STATUS 0x13
#define RESULT_RANGE_STATUS 0x14
#define SYSTEM_INTERRUPT_CLEAR 0x0B

int main() {
    int gpio;
    int i2c_fd;
    unsigned char model_id;
    unsigned char range_status[2];
    unsigned char result_status;
    unsigned int distance;
    struct timespec start_time;
    struct timespec end_time;
    struct sigaction sa;

    // Initialize pigpio
    if (gpio = pigpio_init()) {
        fprintf(stderr, "pigpio_init() failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C device
    if ((i2c_fd = gpio_i2c_open(1, I2C_ADDRESS, GPIO_I2C_MODE_READ_WRITE)) < 0) {
        fprintf(stderr, "gpio_i2c_open() failed: %s\n", strerror(errno));
        pigpioTerminate();
        return 1;
    }

    // Verify sensor is present
    if (gpio_i2c_read(i2c_fd, 0xC0, &model_id, 1) < 0) {
        fprintf(stderr, "gpio_i2c_read() failed: %s\n", strerror(errno));
        gpio_i2c_close(i2c_fd);
        pigpioTerminate();
        return 1;
    }
    if (model_id != 0xEE) {
        fprintf(stderr, "Sensor model ID mismatch: 0x%02x != 0xEE\n", model_id);
        gpio_i2c_close(i2c_fd);
        pigpioTerminate();
        return 1;
    }

    // Perform single-shot ranging loop
    while (1) {
        // Start measurement
        if (gpio_i2c_write(i2c_fd, SYSRANGE_START, I2C_WRITE) < 0) {
            fprintf(stderr, "gpio_i2c_write() failed: %s\n", strerror(errno));
            continue;
        }

        // Wait for measurement to complete
        struct timespec start_time = clock_gettime(CLOCK_MONOTONIC);
        while (1) {
            if (gpio_i2c_read(i2c_fd, RESULT_INTERRUPT_STATUS, &result_status, 1) < 0) {
                fprintf(stderr, "gpio_i2c_read() failed: %s\n", strerror(errno));
                continue;
            }
            if (result_status & (1 << 0)) {
                break;
            }
            usleep(I2C_TIMEOUT * 1000);
        }

        // Read distance
        if (gpio_i2c_read(i2c_fd, RESULT_RANGE_STATUS, range_status, 2) < 0) {
            fprintf(stderr, "gpio_i2c_read() failed: %s\n", strerror(errno));
            continue;
        }
        distance = (range_status[1] << 8) | range_status[0];

        // Clear interrupt
        if (gpio_i2c_write(i2c_fd, SYSTEM_INTERRUPT_CLEAR, I2C_WRITE) < 0) {
            fprintf(stderr, "gpio_i2c_write() failed: %s\n", strerror(errno));
            continue;
        }

        // Print reading
        struct timespec end_time = clock_gettime(CLOCK_MONOTONIC);
        double elapsed = (end_time.tv_sec - start_time.tv_sec) + (end_time.tv_nsec - start_time.tv_nsec) / 1e9;
        printf("%04d-%02d-%02d %02d:%02d:%02d Distance: %u mm\n",
               start_time.tv_sec, start_time.tv_nsec / 1e9, end_time.tv_sec, end_time.tv_nsec / 1e9, (int)elapsed, distance);
        sleep(0.5);
    }

    // Handle SIGINT and SIGTERM
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa);
    sigaddset(&sa, SIGINT);
    sigaddset(&sa, SIGTERM);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction() failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction() failed: %s\n", strerror(errno));
    }

    // Close I2C device
    gpio_i2c_close(i2c_fd);

    // Terminate pigpio
    pigpioTerminate();

    return 0;
}

