#include <stdlib.h>
#include <signal.h>
#include <unistd.h>

#define I2C_ADDRESS 0x39
#define I2C_REG_CONFIG 0x18
#define I2C_REG_IRQ_STATUS 0x25
#define I2C_REG_PROXIMITY_L 0x2A
#define I2C_REG_PROXIMITY_H 0x2B
#define I2C_REG_PROXIMITY 0x2B
#define I2C_BIT_PROXIMITY 0
#define I2C_BIT_IRQ 0
#define I2C_BIT_ERROR 1

int main() {
    int i2c_fd = pigpio_i2c_open(1, I2C_ADDRESS, 0);
    if (i2c_fd < 0) {
        perror("i2c_open");
        return 1;
    }

    if (pigpio_i2c_write(i2c_fd, I2C_REG_CONFIG, 0x01) < 0) {
        perror("i2c_write");
        pigpio_i2c_close(i2c_fd);
        return 1;
    }

    while (1) {
        int status = pigpio_i2c_read(i2c_fd, I2C_REG_IRQ_STATUS, 1, &I2C_BIT_IRQ);
        if (status < 0) {
            perror("i2c_read");
            pigpio_i2c_close(i2c_fd);
            return 1;
        }

        if (I2C_BIT_IRQ & I2C_BIT_IRQ) {
            int result = pigpio_i2c_read(i2c_fd, I2C_REG_PROXIMITY_L, 1, &I2C_REG_PROXIMITY);
