#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/select.h>
#include <termios.h>
#include <sys/ioctl.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>

#define I2C_ADDRESS 0x4C
#define I2C_SLAVE_ADDRESS 0x04
#define I2C_READ_REGISTER 0x00
#define I2C_READ_COUNT 16
#define I2C_READ_OFFSET 0
#define I2C_READ_FACTOR 0.125

void sigint_handler(int sig) {
    close(0);
    close(1);
    close(2);
    exit(0);
}

int main() {
    struct termios oldt, newt;
    struct sigaction sa;

    // Install SIGINT/SIGTERM handler
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    sigaddset(&sa.sa_mask, SIGTERM);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C device
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, I2C_SLAVE_ADDRESS) < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    // Verify device response
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    // Set up terminal for non-blocking I/O
    tcgetattr(fd, &oldt);
    newt = oldt;
    newt.c_lflag &= ~ICANON;
    newt.c_lflag &= ~ECHO;
    newt.c_cc[VMIN] = 0;
    newt.c_cc[VTIME] = 0;
    if (tcsetattr(fd, TCSANOW, &newt) < 0) {
        perror("tcsetattr");
        close(fd);
        return 1;
    }

    while (1) {
        struct i2c_msg msg;
        struct i2c_dev_info info;
        int ret;

        // Read I2C device
        msg.msg_name = NULL;
        msg.msg_len = 0;
        msg.msg_addr = I2C_ADDRESS;
        msg.msg_flags = 0;
        msg.msg_buffer = NULL;
        msg.msg_num = I2C_READ_COUNT;
        msg.msg_offset = I2C_READ_OFFSET;

        ret = i2c_master_block_trans(fd, &msg, &info);
        if (ret < 0) {
            if (errno == EIO) {
                // Retry on I2C read failure
                usleep(500000);
                continue;
            } else {
                perror("i2c_master_block_trans");
                close(fd);
                return 1;
            }
        }

        // Convert raw value to millimeters
        uint16_t distance = (info.i2c_msg->buf[I2C_READ_OFFSET] << 8) | info.i2c_msg->buf[I2C_READ_OFFSET + 1];
        double dist = (distance * I2C_READ_FACTOR);

        printf("Distance: %.2f mm\n", dist);

        // Sleep for 500 ms
        nanosleep(NULL, NULL);
    }

    return 0;
}

