#define MAX_ECHO_TIMEOUT 200  // ms
#define MIN_ECHO_TIMEOUT 200  // ms
#define TRIGGER_PULSE_DURATION 10  // us
#define LOG_INTERVAL 1000  // ms

// Define a function to calculate distance from the HC-SR04 sensor
double calculate_distance(uint32_t pulse_duration) {
    return (pulse_duration * 0.0343) / 2;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up GPIO pins
    if (gpioSetMode(TRIGGER_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set up trigger pin %d\n", TRIGGER_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set up echo pin %d\n", ECHO_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioPullUp(TRIGGER_PIN, PI_HIGH) < 0) {
        fprintf(stderr, "Failed to enable pull-up on trigger pin %d\n", TRIGGER_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioPullUp(ECHO_PIN, PI_HIGH) < 0) {
        fprintf(stderr, "Failed to enable pull-up on echo pin %d\n", ECHO_PIN);
        gpioTerminate();
        return 1;
    }

    // Set up a signal handler for SIGINT and SIGTERM
    signal(SIGINT, SIGTERMHandler);
    signal(SIGTERM, SIGTERMHandler);

    // Main loop
    while (1) {
        // Send a 10 microsecond trigger pulse
        gpioWrite(TRIGGER_PIN, 1);
        usleep(TRIGGER_PULSE_DURATION * 1000);
        gpioWrite(TRIGGER_PIN, 0);

        // Wait for the echo pulse
        uint32_t start_time = gpioTick();
        uint32_t echo_start_time = 0;
        while (1) {
            if (gpioRead(ECHO_PIN) == 0) {
                echo_start_time = gpioTick();
                break;
            }
            usleep(10);
        }

        if (echo_start_time == 0) {
            // No echo detected, skip this iteration
            continue;
        }

        // Wait for the echo pulse to end
        uint32_t echo_end_time = gpioTick();
        if (echo_end_time - echo_start_time > MAX_ECHO_TIMEOUT) {
            // Echo timeout, skip this iteration
            continue;
        }

        // Calculate the pulse duration
        uint32_t pulse_duration = echo_end_time - echo_start_time;

        // Check for invalid pulse durations
        if (pulse_duration <= MIN_PULSE_DURATION || pulse_duration > MAX_PULSE_DURATION) {
            fprintf(stderr, "Invalid pulse duration %u us\n", pulse_duration);
            continue;
        }

        // Calculate the distance
        double distance = calculate_distance(pulse_duration);

        // Log the reading
        printf("%f cm\n", distance);

        // Wait for the next log interval
        usleep((LOG_INTERVAL - (echo_end_time - start_time)) * 1000);
    }

    // Clean up
    gpioTerminate();
    return 0;
}

void SIGTERMHandler(int signal) {
    gpioTerminate();
    exit(0);
}
