#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_PIN 17
#define GPIO_Buzzer 18
#define CHIP_ID 0x80
#define LINE 0x00
#define LINE_MASK 0x01

int main() {
    // Initialize signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    // Open the chip
    struct gpiod_chip *chip;
    chip = gpiod_chip_open(CHIP_ID, GPIO_PIN, 0, NULL);
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Open the line
    struct gpiod_line *line;
    line = gpiod_line_open(chip, LINE, 0, NULL);
    if (!line) {
        gpiod_chip_close(chip);
        perror("gpiod_line_open");
        return 1;
    }

    // Set the line direction
    if (gpiod_line_direction(line, GpioDirectionActiveLow) < 0) {
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        perror("gpiod_line_direction");
        return 1;
    }

    // Open the buzzer
    struct gpiod_line *buzzer;
    buzzer = gpiod_line_open(chip, GPIO_Buzzer, 0, NULL);
    if (!buzzer) {
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        perror("gpiod_line_open");
        return 1;
    }

    // Set the buzzer direction
    if (gpiod_line_direction(buzzer, GpioDirectionActiveHigh) < 0) {
        gpiod_line_close(buzzer);
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        perror("gpiod_line_direction");
        return 1;
    }

    // Poll the sensor
    struct timespec ts;
    while (1) {
        // Read the sensor
        int value;
        if (gpiod_line_read(line, &value) < 0) {
            gpiod_line_close(buzzer);
            gpiod_line_close(line);
            gpiod_chip_close(chip);
            perror("gpiod_line_read");
            return 1;
        }

        // Log the state
        char timestamp[32];
        time_t now = time(&ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%6N", localtime(&now));
        if (value == 0) {
            printf("%s: Obstacle detected\n", timestamp);
        } else {
            printf("%s: Obstacle removed\n", timestamp);
        }

        // Activate the buzzer if an obstacle is detected
        if (value == 0) {
            if (gpiod_line_write(buzzer, 1) < 0) {
                gpiod_line_close(buzzer);
                gpiod_line_close(line);
                gpiod_chip_close(chip);
                perror("gpiod_line_write");
                return 1;
            }
        } else {
            if (gpiod_line_write(buzzer, 0) < 0) {
                gpiod_line_close(buzzer);
                gpiod_line_close(line);
                gpiod_chip_close(chip);
                perror("gpiod_line_write");
                return 1;
            }
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    gpiod_line_close(buzzer);
    gpiod_line_close(line);
    gpiod_chip_close(chip);

    return 0;
}

void sigint_handler(int sig) {
    // Clean up
    gpiod_line_close(buzzer);
    gpiod_line_close(line);
    gpiod_chip_close(chip);

    // Exit
    exit(0);
}

