        time_t now = time(&ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%6N", localtime(&now));
        if (value == 0) {
            printf("%s: Obstacle detected\n", timestamp);
        } else {
            printf("%s: Obstacle removed\n", timestamp);
        }

        // Activate the buzzer if an obstacle is detected
        if (value == 0) {
            if (gpiod_line_write(buzzer, 1) < 0) {
                gpiod_line_close(buzzer);
                gpiod_line_close(line);
                gpiod_chip_close(chip);
                perror("gpiod_line_write");
                return 1;
            }
        } else {
            if (gpiod_line_write(buzzer, 0) < 0) {
                gpiod_line_close(buzzer);
                gpiod_line_close(line);
                gpiod_chip_close(chip);
                perror("gpiod_line_write");
                return 1;
            }
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    gpiod_line_close(buzzer);
    gpiod_line_close(line);
    gpiod_chip_close(chip);

    return 0;
}

void sigint_handler(int sig) {
    // Clean up
    gpiod_line_close(buzzer);
    gpiod_line_close(line);
    gpiod_chip_close(chip);

    // Exit
    exit(0);
}
