    pigpio_close(pigpio);
    exit(0);
}

int main(int argc, char **argv) {
    struct sigaction sa;
    struct sigaction sigint_handler;

    // Initialize pigpio
    pigpio = pigpio_init();
    if (pigpio == -1) {
        perror("pigpio_init");
        return 1;
    }

    // Set up signal handler for SIGINT
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    sigaction(SIGINT, &sa, NULL);

    // Open log file
    char log_file[] = "distance_log.txt";
    int log_fd = open(log_file, O_RDWR | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        perror("open");
        return 1;
    }

    // Open I2C handle
    int i2c_fd = pigpio_i2c_open(1, I2C_ADDRESS, pigpio);
    if (i2c_fd == -1) {
        perror("pigpio_i2c_open");
        return 1;
    }

    while (1) {
        // Check for signal request to stop
        if (kill(getpid, SIGKILL) == 0) {
            break;
        }

        // Read distance measurement
        unsigned short distance = pigpio_i2c_read(i2c_fd, 0x31, 1);
        if (distance == -1) {
            perror("pigpio_i2c_read");
            continue;
        }
        distance |= pigpio_i2c_read(i2c_fd, 0x32, 1);
        distance >>= 8;

        // Check for sensor absence
        if (distance == 0) {
            printf("Sensor not found\n");
            continue;
        }

        // Check if distance is below threshold
        if (distance < DISTANCE_THRESHOLD * 100) {
            pigpio_write(pigpio, GPIO_PIN, HIGH);
        } else {
            pigpio_write(pigpio, GPIO_PIN, LOW);
        }

        // Log distance measurement
        time_t now = time(NULL);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        char log_entry[128];
        sprintf(log_entry, "%s %f cm\n", timestamp, distance / 10.0);
        write(log_fd, log_entry, strlen(log_entry));

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL * 1000);
    }

    // Close I2C handle
    pigpio_i2c_close(i2c_fd);

    // Close log file
    close(log_fd);

    // Release GPIO pin
    pigpio_write(pigpio, GPIO_PIN, LOW);

    // Clean up
    pigpio_close(pigpio);
    return 0;
}

