#define I2C_ADDRESS 0x5A
#define I2C_TIMEOUT 0.1
#define I2C_RETRY 3
#define FILE_NAME "distance_log.csv"

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C file for writing
    int fd = open(FILE_NAME, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set up I2C bus 1
    if (gpioSetMode(1, PI_MODE PullUpDnSel) < 0) {
        perror("gpioSetMode");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Write to I2C address to trigger measurement
    if (gpioWrite(1, I2C_ADDRESS, 0x00) < 0) {
        perror("gpioWrite");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Delay for 10 ms
    usleep(10000);

    // Read distance data
    unsigned char data[2];
    int retry = 0;
    while (1) {
        // Read from I2C address
        if (gpioRead(1, I2C_ADDRESS, data, 2, I2C_TIMEOUT) < 0) {
            if (retry < I2C_RETRY) {
                retry++;
                usleep(1000);
            } else {
                perror("gpioRead");
                close(fd);
                gpioTerminate();
                return 1;
            }
        } else {
            retry = 0;
        }

        // Convert distance to centimeters
        int distance = (data[0] << 8) | data[1];

        // Append to file
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(fd, "%s,%d\n", timestamp, distance);

        // Delay for 100 ms
        usleep(100000);
    }

    // Close file
    close(fd);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

