#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>

#define GPIO_17 17
#define GPIO_27 27
#define DEBOUNCE 50
#define POLL_INTERVAL 10
#define LOG_FILE "proximity_log.txt"

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(GPIO_17, PI_INPUT) < 0) {
        perror("gpioSetMode(GPIO_17)");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GPIO_27, PI_INPUT) < 0) {
        perror("gpioSetMode(GPIO_27)");
        gpioTerminate();
        return 1;
    }

    // Open log file
    int log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set up timer for polling
    struct itimerspec timer;
    timer.it_value.tv_sec = 0;
    timer.it_value.tv_nsec = POLL_INTERVAL * 1000000;
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_nsec = POLL_INTERVAL * 1000000;
    if (clock_settime(CLOCK_MONOTONIC, &timer) < 0) {
        perror("clock_settime");
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read sensor values
        int sensor1 = gpioRead(GPIO_17);
        int sensor2 = gpioRead(GPIO_27);

        // Log state transitions
        if (sensor1 == 0 && sensor2 == 1) {
            time_t now = time(NULL);
            struct tm *ltm = localtime(&now);
            char log_str[64];
            strftime(log_str, sizeof(log_str), "%Y-%m-%d %H:%M:%S%z", ltm);
            fprintf(log_fd, "%s - Sensor 1 - DETECTED\n", log_str);
        } else if (sensor1 == 1 && sensor2 == 0) {
            time_t now = time(NULL);
            struct tm *ltm = localtime(&now);
            char log_str[64];
            strftime(log_str, sizeof(log_str), "%Y-%m-%d %H:%M:%S%z", ltm);
            fprintf(log_fd, "%s - Sensor 1 - CLEARED\n", log_str);
        } else if (sensor1 == 0 && sensor2 == 0) {
            time_t now = time(NULL);
            struct tm *ltm = localtime(&now);
            char log_str[64];
            strftime(log_str, sizeof(log_str), "%Y-%m-%d %H:%M:%S%z", ltm);
            fprintf(log_fd, "%s - Sensor 1 - IDLE\n", log_str);
        } else if (sensor1 == 1 && sensor2 == 1) {
            time_t now = time(NULL);
            struct tm *ltm = localtime(&now);
            char log_str[64];
            strftime(log_str, sizeof(log_str), "%Y-%m-%d %H:%M:%S%z", ltm);
            fprintf(log_fd, "%s - Sensor 2 - IDLE\n", log_str);
        }

        // Debounce
        if (sensor1 == 0 && sensor1 != gpioRead(GPIO_17, GPIO_EDGE_BOTH)) {
            time_t now = time(NULL);
            struct tm *ltm = localtime(&now);
            char log_str[64];
            strftime(log_str, sizeof(log_str), "%Y-%m-%d %H:%M:%S%z", ltm);
            fprintf(log_fd, "%s - Sensor 1 - DEBOUNCE\n", log_str);
        }
        if (sensor2 == 1 && sensor2 != gpioRead(GPIO_27, GPIO_EDGE_BOTH)) {
            time_t now = time(NULL);
            struct tm *ltm = localtime(&now);
            char log_str[64];
            strftime(log_str, sizeof(log_str), "%Y-%m-%d %H:%M:%S%z", ltm);
            fprintf(log_fd, "%s - Sensor 2 - DEBOUNCE\n", log_str);
        }

        // Sleep for polling interval
        usleep(POLL_INTERVAL * 1000000);
    }

    // Close log file
    if (close(log_fd) < 0) {
        perror("close");
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

