#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/select.h>
#include <sys/time.h>
#include <sys/types.h>
#include <signal.h>

#define I2C_ADDRESS 0x49
#define I2C Bus 1
#define MEAS_TRIGGER 0x04
#define MEAS_STATUS 0x06
#define DIST_HIGH 0x08
#define DIST_LOW 0x09

void i2c_read(int fd, uint8_t reg, uint8_t *data, size_t size) {
    if (ioctl(fd, I2C_SLAVE, I2C Bus) < 0) {
        fprintf(stderr, "I2C error: %d\n", errno);
        return;
    }

    if (write(fd, &reg, 1) < 0) {
        fprintf(stderr, "I2C write error: %d\n", errno);
        return;
    }

    if (read(fd, data, size) < 0) {
        fprintf(stderr, "I2C read error: %d\n", errno);
        return;
    }

    if (ioctl(fd, I2C_SLAVE, I2C Bus) < 0) {
        fprintf(stderr, "I2C error: %d\n", errno);
        return;
    }
}

int main() {
    int fd;
    struct timespec start, end;
    struct timeval tv;
    struct iovec iov;
    char buffer[2];
    uint16_t distance;
    FILE *log_file;

    // Open I2C file descriptor
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set I2C bus number
    if (ioctl(fd, I2C_SLAVE, I2C Bus) < 0) {
        perror("I2C set slave");
        close(fd);
        return 1;
    }

    // Trigger a single range measurement
    i2c_read(fd, MEAS_TRIGGER, &buffer, 1);
    if (buffer[0] != 0x01) {
        fprintf(stderr, "Invalid MEAS_TRIGGER value\n");
        close(fd);
        return 1;
    }

    // Wait for data-ready
    tv.tv_sec = 0;
    tv.tv_usec = 50;
    if (select(fd, NULL, NULL, NULL, &tv) < 0) {
        perror("select");
        close(fd);
        return 1;
    }

    i2c_read(fd, MEAS_STATUS, &buffer, 1);
    if (!(buffer[0] & 0x01)) {
