#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDRESS 0x4C
#define I2C_ADDRESS_RETRY 3
#define I2C_RETRY_DELAY 10
#define I2C_READ_SIZE 2

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Initialize I2C
    if (gpioI2CInit(1) < 0) {
        perror("gpioI2CInit");
        gpioTerminate();
        return 1;
    }

    // Open I2C handle
    int i2c_handle = gpioI2COpen(1, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        perror("gpioI2COpen");
        gpioTerminate();
        return 1;
    }

    // Set I2C clock speed
    if (gpioI2CSetClock(i2c_handle, 400000) < 0) {
        perror("gpioI2CSetClock");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read sensor data
    int retry = 0;
    while (1) {
        // Read sensor data
        int data = 0;
        if (gpioI2CRead(i2c_handle, I2C_ADDRESS, &data, I2C_READ_SIZE) < 0) {
            if (retry < I2C_ADDRESS_RETRY) {
                usleep(I2C_RETRY_DELAY * 1000);
                retry++;
            } else {
                printf("Failed to read from sensor\n");
                break;
            }
        } else {
            retry = 0;
        }

        // Calculate distance
        if (data & 0x80) {
            int distance = (data & 0x7F) * 0.15625;
            printf("%d.%03d\n", (int)distance, (int)((data & 0x3) * 4));
        } else {
            printf("Sensor not found\n");
            break;
        }
    }

    // Close I2C handle
    gpioI2CClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

