#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define constants
#define I2C_ADDRESS 0x29
#define I2C Bus 1
#define RESET_REG 0x7FFF
#define RANGE_REG 0x0009
#define STATUS_REG 0x0046
#define DIST_HIGH_REG 0x0096
#define DIST_LOW_REG 0x0097
#define DIST_MASK 0x0001
#define DIST_SHIFT 0

// Initialize pigpio
void init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }
}

// Close pigpio
void cleanup_pigpio() {
    gpioTerminate();
}

// I2C write function
int i2c_write(uint8_t reg, uint8_t value) {
    if (gpioWrite(I2C Bus, reg, value) < 0) {
        fprintf(stderr, "I2C write error\n");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(uint8_t reg) {
    uint8_t value;
    if (gpioRead(I2C Bus, reg, &value) < 0) {
        fprintf(stderr, "I2C read error\n");
        return -1;
    }
    return value;
}

// Interrupt handler
void interrupt_handler(int sig) {
    cleanup_pigpio();
    exit(0);
}

int main() {
    // Install interrupt handlers
    signal(SIGINT, interrupt_handler);
    signal(SIGTERM, interrupt_handler);

    // Initialize pigpio
    init_pigpio();

    // Open I2C bus
    if (gpioI2COpen(I2C Bus, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        cleanup_pigpio();
        exit(1);
    }

    // Perform startup sequence
    if (i2c_write(RESET_REG, 0x00) < 0) {
        cleanup_pigpio();
        exit(1);
    }
    usleep(10);
    if (i2c_write(RESET_REG, 0x00) < 0) {
        cleanup_pigpio();
        exit(1);
    }
    if (i2c_write(RANGE_REG, 0x00) < 0) {
        cleanup_pigpio();
        exit(1);
    }

    // Main loop
    while (1) {
        // Poll interrupt status
        uint8_t status = i2c_read(STATUS_REG);
        if (!(status & DIST_MASK)) {
            continue;
        }

        // Read distance data
        uint16_t distance = (i2c_read(DIST_HIGH_REG) << DIST_SHIFT) | i2c_read(DIST_LOW_REG);

        // Log distance data
        time_t now = time(NULL);
        struct tm* ltm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%06lu", ltm);
        printf("%s, Distance: %d mm\n", timestamp, distance);

        // Wait 500 ms before next iteration
        usleep(500000);
    }

    // Clean up
    cleanup_pigpio();
    return 0;
}

