#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <signal.h>
#include <errno.h>

// Define constants
#define I2C_ADDRESS 0x29
#define I2C Bus 1
#define GPIO_BUZZER 22
#define DISTANCE_THRESHOLD 100
#define DISTANCE_INTERVAL 500

// Define structures
typedef struct {
    int i2c_fd;
    pigpio gpio;
} sensor_config_t;

// Define functions
void init_sensor(sensor_config_t *config);
void read_distance(sensor_config_t *config);
void activate_buzzer(sensor_config_t *config);
void deactivate_buzzer(sensor_config_t *config);
void cleanup(sensor_config_t *config);

// Main function
int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio\n");
        return 1;
    }

    // Create sensor configuration
    sensor_config_t config;
    config.i2c_fd = -1;
    config.gpio = -1;

    // Initialize sensor
    init_sensor(&config);

    // Main loop
    while (1) {
        // Read distance
        read_distance(&config);

        // Check if distance is below threshold
        if (config.gpio.distance < DISTANCE_THRESHOLD) {
            // Activate buzzer
            activate_buzzer(&config);
        } else {
            // Deactivate buzzer
            deactivate_buzzer(&config);
        }

        // Sleep for interval
        usleep(DISTANCE_INTERVAL * 1000);
    }

    // Clean up
    cleanup(&config);

    // Finalize pigpio
    gpioTerminate();
    return 0;
}

// Initialize sensor
void init_sensor(sensor_config_t *config) {
    // Open I2C bus
    if (i2cOpen(I2C Bus, I2C_ADDRESS, &config->i2c_fd) < 0) {
        printf("Failed to open I2C bus\n");
        return;
    }

    // Configure sensor
    if (i2cWriteByte(config->i2c_fd, 0x0001) < 0) {
        printf("Failed to configure sensor\n");
        i2cClose(config->i2c_fd);
        return;
    }
    if (i2cWriteByte(config->i2c_fd, 0x0001) < 0) {
        printf("Failed to configure sensor\n");
        i2cClose(config->i2c_fd);
        return;
    }
    if (i2cWriteByte(config->i2c_fd, 0x0007) < 0) {
        printf("Failed to configure sensor\n");
        i2cClose(config->i2c_fd);
        return;
    }
    if (i2cWriteByte(config->i2c_fd, 0x0096) < 0) {
        printf("Failed to configure sensor\n");
        i2cClose(config->i2c_fd);
        return;
    }

    // Configure GPIO
    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio\n");
        i2cClose(config->i2c_fd);
        return;
    }
    if (gpioSetup(config->gpio, GPIO_MODE_OUTPUT) < 0) {
        printf("Failed to set up GPIO\n");
        gpioTerminate();
        i2cClose(config->i2c_fd);
        return;
    }
    if (gpioWrite(config->gpio, GPIO_BUZZER) < 0) {
        printf("Failed to set up GPIO\n");
        gpioTerminate();
        i2cClose(config->i2c_fd);
        return;
    }

    // Set initial distance value
    if (i2cReadByte(config->i2c_fd, 0x00) < 0) {
        printf("Failed to read distance\n");
        gpioTerminate();
        i2cClose(config->i2c_fd);
        return;
    }
}

// Read distance
void read_distance(sensor_config_t *config) {
    // Read distance
    if (i2cReadByte(config->i2c_fd, 0x00) < 0) {
        printf("Failed to read distance\n");
        return;
    }

    // Get distance value
    int distance = i2cReadByte(config->i2c_fd, 0x00);

    // Update GPIO
    if (gpioRead(config->gpio, GPIO_BUZZER) < 0) {
        printf("Failed to read GPIO\n");
        return;
    }

    // Update distance value
    config->gpio.distance = distance;
}

// Activate buzzer
void activate_buzzer(sensor_config_t *config) {
    // Set GPIO high
    if (gpioWrite(config->gpio, GPIO_BUZZER) < 0) {
        printf("Failed to set GPIO high\n");
        return;
    }
}

// Deactivate buzzer
void deactivate_buzzer(sensor_config_t *config) {
    // Set GPIO low
    if (gpioWrite(config->gpio, GPIO_BUZZER) < 0) {
        printf("Failed to set GPIO low\n");
        return;
    }
}

// Clean up
void cleanup(sensor_config_t *config) {
    // Close I2C bus
    if (config->i2c_fd != -1) {
        i2cClose(config->i2c_fd);
        config->i2c_fd = -1;
    }

    // Release GPIO
    if (config->gpio != -1) {
        gpioTerminate();
        config->gpio = -1;
    }
