    error = pigpio_write(I2C_ADDRESS, 0x0000, 0x00);
    if (error < 0) {
        perror("pigpio_write");
        return 1;
    }
    error = pigpio_write(I2C_ADDRESS, 0x0000, 0x01);
    if (error < 0) {
        perror("pigpio_write");
        return 1;
    }

    // Configure the timing budget
    error = pigpio_write(I2C_ADDRESS, 0x0080, 0x02);
    if (error < 0) {
        perror("pigpio_write");
