        perror("msgctl");
    }
    if (msgctl(msgq, IPC_RMID, 0) < 0) {
        perror("msgctl");
    }
    if (gpio_close()) {
        perror("gpio_close");
    }
    if (pi_close()) {
        perror("pi_close");
    }
    if (close(i2c_fd) < 0) {
        perror("close");
    }

    return 0;
}

void sigint_handler(int sig) {
    // Clean up
    if (msgctl(msgq, IPC_RMID, 0) < 0) {
        perror("msgctl");
    }
    if (msgctl(msgq, IPC_SET, 0) < 0) {
        perror("msgctl");
    }
    if (close(msgq) < 0) {
        perror("close");
    }
    if (gpio_close()) {
        perror("gpio_close");
    }
    if (pi_close()) {
        perror("pi_close");
    }
    if (close(i2c_fd) < 0) {
        perror("close");
    }
    exit(0);
}
