        fprintf(stderr, "Failed to set GPIO %d to output\n", TRIGGER_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to output\n", BUZZER_PIN);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode to input for echo
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to input\n", ECHO_PIN);
        gpioTerminate();
        return 1;
    }

    // Set up interrupt-driven measurement
    gpioSetAlertFuncEx(TRIGGER_PIN, gpioCallback, NULL, NULL, NULL);
    if (gpioSetAlertFuncEx(ECHO_PIN, gpioCallback, NULL, NULL, NULL) < 0) {
        fprintf(stderr, "Failed to set up interrupt-driven measurement\n");
        gpioTerminate();
        return 1;
    }

    // Set up buzzer
    gpioWrite(BUZZER_PIN, 1);

    while (1) {
        // Wait for 100 ms
        usleep(100000);

        // Check if there's an interrupt
        if (gpioRead(ECHO_PIN) == 0) {
            // Calculate distance
            unsigned long echoTime = gpioGetTick() - gpioGetTick();
            if (echoTime == 0) {
                // Sensor-absent (timeout/no echo)
                printf("Sensor absent\n");
            } else {
                unsigned long distance = (echoTime / 2) * SOUND_SPEED / 1000000;
                if (distance < DISTANCE_MIN || distance > DISTANCE_MAX) {
                    // Invalid reading (out-of-range)
                    printf("Invalid reading: %lu cm\n", distance);
                } else if (distance < DISTANCE_THRESHOLD) {
                    // Activate buzzer
                    gpioWrite(BUZZER_PIN, 1);
                } else {
                    // Deactivate buzzer
                    gpioWrite(BUZZER_PIN, 0);
                }
                printf("%lu cm\n", distance);
            }
        }
    }

    // Clean up
    gpioTerminate();
    return 0;
}

void gpioCallback(int gpio, int level, void *user_data) {
    if (gpio == ECHO_PIN) {
        // Calculate distance
        unsigned long echoTime = gpioGetTick() - gpioGetTick();
        if (echoTime == 0) {
            // Sensor-absent (timeout/no echo)
