#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>

// Define constants
#define TRIG_PIN 23
#define ECHO_PIN 24
#define SOUND_SPEED 343
#define MIN_PULSE_WIDTH 100
#define MAX_PULSE_WIDTH 30000
#define MEASUREMENT_INTERVAL 200
#define LOG_FILE "distance_log.txt"

// Define structures for callback functions
typedef struct {
    void (*rising_edge)(unsigned int);
    void (*falling_edge)(unsigned int);
} callback_t;

// Define callback functions
void rising_edge_callback(unsigned int tick) {
    printf("Rising edge detected at %u us\n", tick);
}

void falling_edge_callback(unsigned int tick) {
    printf("Falling edge detected at %u us\n", tick);
}

// Define main function
int main(int argc, char **argv) {
    // Initialize pigpio with error checking
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %d\n", gpioInitialise());
        return 1;
    }

    // Set TRIG pin as output, low
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIG pin as output: %d\n", gpioSetMode(TRIG_PIN, PI_OUTPUT));
        gpioTerminate();
        return 1;
    }
    gpioWrite(TRIG_PIN, 0);

    // Set ECHO pin as input with pull-down resistor
    if (gpioSetMode(ECHO_PIN, PI_INPUT PullDown) < 0) {
        fprintf(stderr, "Failed to set ECHO pin as input with pull-down resistor: %d\n", gpioSetMode(ECHO_PIN, PI_INPUT PullDown));
        gpioTerminate();
        return 1;
    }

    // Register alert callback on ECHO
    callback_t callbacks = {rising_edge_callback, falling_edge_callback};
    if (gpioAttachInterrupt(ECHO_PIN, &callbacks, GPIO_EDGE_BOTH) < 0) {
        fprintf(stderr, "Failed to register alert callback on ECHO pin: %d\n", gpioAttachInterrupt(ECHO_PIN, &callbacks, GPIO_EDGE_BOTH));
        gpioTerminate();
        return 1;
    }

    // Generate a 10 microsecond trigger pulse
    usleep(10000);

    // Open log file for append mode
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Main measurement loop
    while (1) {
        // Wait for 200 ms
        usleep(MEASUREMENT_INTERVAL * 1000);

        // Trigger pulse
        gpioWrite(TRIG_PIN, 1);
        usleep(10);

        // Wait for ECHO pulse
        unsigned int rising_edge_tick = 0;
        unsigned int falling_edge_tick = 0;
        unsigned int start_time = clock_gettime(CLOCK_MONOTONIC, NULL);
        while (gpioRead(ECHO_PIN) == 0) {
            rising_edge_tick = gpioGetTick();
        }
        while (gpioRead(ECHO_PIN) == 1) {
            falling_edge_tick = gpioGetTick();
        }
        unsigned int duration = falling_edge_tick - rising_edge_tick;

        // Validate pulse width
        if (duration < MIN_PULSE_WIDTH) {
            fprintf(stderr, "Invalid pulse width: %u us (below minimum)\n", duration);
            fprintf(log_file, "%s %u us\n", ctime(&start_time), duration);
        } else if (duration > MAX_PULSE_WIDTH) {
            fprintf(stderr, "Invalid pulse width: %u us (above maximum)\n", duration);
            fprintf(log_file, "%s %u us\n", ctime(&start_time), duration);
        } else {
            // Calculate distance
            unsigned int distance = (duration / 2) * SOUND_SPEED / 1000;
            fprintf(stderr, "Valid distance: %.2f cm\n", distance);
            fprintf(log_file, "%s %f cm\n", ctime(&start_time), distance);
        }

        // Check for timeout
        if (clock_gettime(CLOCK_MONOTONIC, NULL) - start_time > 60 * 1000) {
            fprintf(stderr, "Timeout: no echo received within 60 ms\n");
            fprintf(log_file, "%s %f s\n", ctime(&start_time), (clock_gettime(CLOCK_MONOTONIC, NULL) - start_time) / 1000.0);
        }
    }

    // Close log file
    fclose(log_file);

    // Release GPIO resources
    gpioTerminate();

    return 0;
}

