#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_ADDRESS 0x29
#define I2C Bus 1
#define GPIO23 23
#define GPIO24 24
#define GPIO18 18
#define GPIO2 2
#define GPIO3 3
#define SERVO_PIN GPIO18
#define SERVO_MIN 1000
#define SERVO_MAX 6000
#define DISTANCE_THRESHOLD_LOW 50
#define DISTANCE_THRESHOLD_HIGH 60
#define LOG_FILE "parking_log.txt"

// Initialize pigpio
void init_pigpio() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio\n");
        exit(1);
    }
}

// Initialize VL53L1X sensor
void init_vl53l1x(int fd) {
    if (ioctl(fd, VL53L1X_Init, 0) < 0) {
        printf("Failed to initialize VL53L1X sensor\n");
        exit(1);
    }
    if (ioctl(fd, VL53L1X_SetAddress, I2C_ADDRESS) < 0) {
        printf("Failed to set VL53L1X address\n");
        exit(1);
    }
    if (ioctl(fd, VL53L1X_SetInterrupt, GPIO24) < 0) {
        printf("Failed to set VL53L1X interrupt\n");
        exit(1);
    }
    if (ioctl(fd, VL53L1X_SetInterruptMode, VL53L1X_INT_MODE_EDGE_RISING) < 0) {
        printf("Failed to set VL53L1X interrupt mode\n");
        exit(1);
    }
}

// Read distance from VL53L1X sensor
int read_distance(int fd) {
    unsigned char data[6];
    if (ioctl(fd, VL53L1X_ReadRange, data) < 0) {
        printf("Failed to read distance from VL53L1X sensor\n");
        exit(1);
    }
    return (data[0] << 8) | data[1];
}

// Set servo motor PWM
void set_servo(int pin, int value) {
    if (gpioSet PWM(pin, value) < 0) {
        printf("Failed to set servo motor PWM\n");
        exit(1);
    }
}

// Log gate state changes
void log_gate_state(int distance) {
    time_t now = time(NULL);
    struct tm* ltm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", ltm);
    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        exit(1);
    }
    fprintf(log_file, "%s %d %d\n", timestamp, distance, (distance < DISTANCE_THRESHOLD_LOW ? 0 : 1));
    fclose(log_file);
}

// Handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    gpioCleanUp();
    exit(0);
}

int main() {
    // Initialize pigpio
    init_pigpio();

    // Open VL53L1X sensor
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        printf("Failed to open I2C bus\n");
        exit(1);
    }

    // Initialize VL53L1X sensor
    init_vl53l1x(fd);

    // Set up GPIOs
    if (gpioMode(GPIO2, PI_INPUT) < 0) {
        printf("Failed to set GPIO2 as input\n");
        exit(1);
    }
    if (gpioMode(GPIO3, PI_INPUT) < 0) {
        printf("Failed to set GPIO3 as input\n");
        exit(1);
    }
    if (gpioMode(GPIO23, PI_OUTPUT) < 0) {
        printf("Failed to set GPIO23 as output\n");
        exit(1);
    }
    if (gpioMode(GPIO24, PI_INPUT) < 0) {
        printf("Failed to set GPIO24 as input\n");
        exit(1);
    }
    if (gpioMode(GPIO18, PI_OUTPUT) < 0) {
        printf("Failed to set GPIO18 as output\n");
        exit(1);
    }

    // Set up servo motor
    if (gpioMode(SERVO_PIN, PI_OUTPUT) < 0) {
        printf("Failed to set servo motor pin as output\n");
        exit(1);
    }

    // Set up PWM
    if (gpioPWM(SERVO_PIN, SERVO_MIN, SERVO_MAX) < 0) {
        printf("Failed to set servo motor PWM\n");
        exit(1);
    }

    // Set up I2C bus
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        printf("Failed to set I2C address\n");
        exit(1);
    }

    // Main loop
    while (1) {
        int distance = read_distance(fd);
        if (distance == 0) {
            // Object detected, open gate
            set_servo(SERVO_PIN, SERVO_MIN);
            log_gate_state(DISTANCE_THRESHOLD_LOW);
        } else if (distance > DISTANCE_THRESHOLD_HIGH) {
            // Object not detected, close gate
            set_servo(SERVO_PIN, SERVO_MAX);
            log_gate_state(DISTANCE_THRESHOLD_HIGH);
        } else {
            // Object detected, close gate
            set_servo(SERVO_PIN, SERVO_MAX);
            log_gate_state(DISTANCE_THRESHOLD_LOW);
        }
        usleep(100000);
    }

    // Clean up
    gpioCleanUp();
    close(fd);
    return 0;
}

