#define I2C_ADDRESS 0x29
#define I2C_TIMEOUT 100
#define GPIO_18 18
#define GPIO_19 19
#define DISTANCE_THRESHOLD 200
#define POLL_INTERVAL 500

int main(int argc, char **argv) {
    int i2c_fd;
    int gpio_fd;
    int ret;
    struct timespec start_time;
    struct timespec end_time;
    struct timespec time_diff;
    char log_file[256];
    char timestamp[32];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return 1;
    }

    // Open I2C handle
    i2c_fd = i2cOpen(I2C_BUS_1, I2C_ADDRESS, I2C_TIMEOUT);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C handle");
        gpioTerminate();
        return 1;
    }

    // Configure VL53L1X timing budget
    ret = i2cWriteI2CBlockData(i2c_fd, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to configure VL53L1X timing budget");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Configure VL53L1X ranging
    ret = i2cWriteI2CBlockData(i2c_fd, 0x10, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to configure VL53L1X ranging");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Start ranging
    ret = i2cWriteI2CBlockData(i2c_fd, 0x10, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to start VL53L1X ranging");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    sprintf(log_file, "/var/log/gate_events.log");
    if (access(log_file, W_OK) != 0) {
        mkdir(log_file, 0755);
    }
    FILE *log_file_ptr = fopen(log_file, "a");
    if (log_file_ptr == NULL) {
        syslog(LOG_ERR, "Failed to open log file");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Get current time
        clock_gettime(CLOCK_REALTIME, &start_time);

        // Poll sensor
        ret = i2cReadI2CBlockData(i2c_fd, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to read VL53L1X data");
            i2cClose(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Check distance
        uint16_t distance = (ret >> 8) & 0x0000FFFF;
        if (distance < DISTANCE_THRESHOLD) {
            // Open gate
            gpioWrite(GPIO_18, 1);
            gpioWrite(GPIO_19, 0);
            sprintf(timestamp, "%Y-%m-%d %H:%M:%S.%06d", start_time.tv_sec, start_time.tv_nsec / 1000000000, start_time.tv_nsec % 1000000000);
            fprintf(log_file, "%s: Gate open\n", timestamp);
        } else {
            // Close gate
            gpioWrite(GPIO_18, 0);
            gpioWrite(GPIO_19, 1);
            sprintf(timestamp, "%Y-%m-%d %H:%M:%S.%06d", start_time.tv_sec, start_time.tv_nsec / 1000000000, start_time.tv_nsec % 1000000000);
            fprintf(log_file, "%s: Gate closed\n", timestamp);
        }

        // Sleep for POLL_INTERVAL ms
        usleep(POLL_INTERVAL * 1000);

        // Check for sensor-absent or bus-error
        ret = i2cReadI2CBlockData(i2c_fd, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00);
        if (ret < 0) {
            syslog(LOG_ERR, "Sensor-absent or bus-error");
            i2cClose(i2c_fd);
            gpioTerminate();
            return 1;
        }
    }

    // Clean up
    fclose(log_file_ptr);
    i2cClose(i2c_fd);
    gpioTerminate();

    return 0;
}
