#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <sys/select.h>
#include <termios.h>
#include <unistd.h>

#define I2C_ADDRESS 0x5A
#define I2C Bus 1
#define GPIO_LED 27
#define GPIO_ELECTRODE 0
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x05
#define LED_PIN GPIO_LED
#define LED_HIGH 1
#define LED_LOW 0

int main(int argc, char *argv[]) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up I2C
    if (i2cInit(I2C Bus, NULL) < 0) {
        perror("i2cInit");
        gpioTerminate();
        return 1;
    }

    // Open MPR121 I2C device
    int fd = i2cOpen(I2C Bus, I2C_ADDRESS, NULL);
    if (fd < 0) {
        perror("i2cOpen");
        i2cClose(I2C Bus, I2C_ADDRESS);
        gpioTerminate();
        return 1;
    }

    // Read device ID
    unsigned char device_id[3];
    if (i2cRead(fd, device_id, 3, NULL) < 0) {
        perror("i2cRead");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }
    printf("Device ID: 0x%02x%02x%02x\n", device_id[0], device_id[1], device_id[2]);

    // Configure MPR121 registers
    unsigned char ffir = 0x00;
    unsigned char sfi = 0x00;
    unsigned char esi = 0x00;
    unsigned char debounce = 0x00;
    unsigned char afec = 0x00;
    unsigned char baseline = 0x00;

    if (i2cWrite(fd, 0x00, &ffir) < 0) {
        perror("i2cWrite");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }
    if (i2cWrite(fd, 0x01, &sfi) < 0) {
        perror("i2cWrite");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }
    if (i2cWrite(fd, 0x02, &esi) < 0) {
        perror("i2cWrite");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }
    if (i2cWrite(fd, 0x03, &debounce) < 0) {
        perror("i2cWrite");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }
    if (i2cWrite(fd, 0x04, &afec) < 0) {
        perror("i2cWrite");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }
    if (i2cWrite(fd, 0x05, &baseline) < 0) {
        perror("i2cWrite");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    // Configure touch threshold and release threshold
    if (i2cWrite(fd, 0x06, &TOUCH_THRESHOLD) < 0) {
        perror("i2cWrite");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }
    if (i2cWrite(fd, 0x07, &RELEASE_THRESHOLD) < 0) {
        perror("i2cWrite");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    // Set up GPIO pin
    if (gpioMode(GPIO_LED, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(GPIO_LED, GPIO_LOW) < 0) {
        perror("gpioWrite");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        unsigned char status;
        if (i2cRead(fd, 0x00, &status, NULL) < 0) {
            perror("i2cRead");
            i2cClose(fd);
            gpioTerminate();
            return 1;
        }
        if (status & 0x01) {
            printf("Proximity detected at %d\n", time(NULL));
            gpioWrite(GPIO_LED, GPIO_HIGH);
            sleep(1);
            gpioWrite(GPIO_LED, GPIO_LOW);
        }
    }

    // Clean up
    gpioWrite(GPIO_LED, GPIO_LOW);
    i2cClose(fd);
    gpioTerminate();
    return 0;
}

