#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <signal.h>
#include <libgpiod.h>
#include <libgpiod/err.h>

#define GPIO17 17
#define GPIO18 18
#define TRIG 0
#define ECHO 1
#define SOUND_SPEED 343.0
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define LOG_FILE "distance_log.txt"

volatile sig_atomic_t stop = 0;

void sigint_handler(int sig) {
    gpiod_line_release(line);
    gpiod_line_release(line_echo);
    fclose(log_file);
    exit(0);
}

int main() {
    struct gpiod_context ctx;
    struct gpiod_line *line;
    struct gpiod_line *line_echo;
    struct gpiod_request *req;
    struct gpiod_request *req_echo;
    struct timespec start, end;
    struct timespec now;
    struct timespec delay;
    struct timespec sleep;
    struct timespec timeout;
    int ret;

    // Initialize libgpiod
    ret = gpiod_init(&ctx);
    if (ret != 0) {
        fprintf(stderr, "gpiod_init failed: %d\n", ret);
        return 1;
    }

    // Open lines
    ret = gpiod_line_request_output(&ctx, GPIO17, &line, NULL);
    if (ret != 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %d\n", ret);
        gpiod_exit(&ctx);
        return 1;
    }

    ret = gpiod_line_request_input(&ctx, GPIO18, &line_echo, NULL);
    if (ret != 0) {
        fprintf(stderr, "gpiod_line_request_input failed: %d\n", ret);
        gpiod_line_release(line);
        gpiod_exit(&ctx);
        return 1;
    }

    // Set up request
    ret = gpiod_line_request(&ctx, line, TRIG, &req, NULL);
    if (ret != 0) {
        fprintf(stderr, "gpiod_line_request failed: %d\n", ret);
        gpiod_line_release(line);
        gpiod_line_release(line_echo);
        gpiod_exit(&ctx);
        return 1;
    }

    ret = gpiod_line_request(&ctx, line_echo, ECHO, &req_echo, NULL);
    if (ret != 0) {
        fprintf(stderr, "gpiod_line_request failed: %d\n", ret);
        gpiod_line_release(line);
        gpiod_line_release(line_echo);
        gpiod_exit(&ctx);
        return 1;
    }

    // Set up request parameters
    gpiod_request_set(&req, GpioDirection, GpioOutput);
    gpiod_request_set(&req, GpioLevel, GpioLow);
    gpiod_request_set(&req, GpioDuration, GpioMicroseconds, 5);
    gpiod_request_set(&req, GpioEdge, GpioRising, GpioNone);
    gpiod_request_set(&req, GpioState, GpioLow);

    gpiod_request_set(&req_echo, GpioDirection, GpioInput);
    gpiod_request_set(&req_echo, GpioEdge, GpioRising, GpioNone);
    gpiod_request_set(&req_echo, GpioState, GpioLow);

    // Start measuring
    gpiod_request_start(&req);
    gpiod_request_start(&req_echo);

    while (!stop) {
        // Wait for trigger
        gpiod_request_wait(&req, &start, &timeout, 0);
        if (gpiod_request_get(&req, GpioLevel, &ret) != 0) {
            fprintf(stderr, "gpiod_request_get failed: %d\n", ret);
            gpiod_line_release(line);
            gpiod_line_release(line_echo);
            gpiod_exit(&ctx);
            return 1;
        }

        // Wait for echo
        gpiod_request_wait(&req_echo, &end, &timeout, 0);
        if (gpiod_request_get(&req_echo, GpioLevel, &ret) != 0) {
            fprintf(stderr, "gpiod_request_get failed: %d\n", ret);
            gpiod_line_release(line);
            gpiod_line_release(line_echo);
            gpiod_exit(&ctx);
            return 1;
        }

        // Check if echo is present
        if (gpiod_request_get(&req_echo, GpioLevel, &ret) == 0) {
            fprintf(stderr, "No echo detected\n");
            gpiod_line_release(line);
            gpiod_line_release(line_echo);
            gpiod_exit(&ctx);
            return 1;
        }

        // Measure distance
        gpiod_request_get(&req, GpioLevel, &ret);
        gpiod_request_get(&req_echo, GpioLevel, &ret);
