#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <syslog.h>
#include <unistd.h>
#include <sys/types.h>
#include <signal.h>

#define I2C_ADDRESS 0x29
#define I2C_ADDRESS_MASK 0x01
#define GPIO_PIN 27
#define GPIO_PIN_MASK 0x01
#define I2C_TIMEOUT 0x00
#define I2C_CONTINUOUS_MODE 0x00
#define I2C_START_RANGING 0x01
#define I2C_REG_XSHUT 0x0018
#define I2C_REG_STATUS 0x0016
#define I2C_REG_DISTANCE 0x0014

int main(int argc, char **argv) {
    int i2c_fd = -1;
    int gpio_fd = -1;
    int ret = 0;

    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    // Open pigpio
    if (pigpio_init() < 0) {
        perror("pigpio_init");
        return 1;
    }

    // Open I2C device
    if ((i2c_fd = pigpio_i2c_open(I2C_ADDRESS, I2C_ADDRESS_MASK, 100000)) < 0) {
        perror("pigpio_i2c_open");
        pigpio_close(i2c_fd);
        pigpio_exit();
        return 1;
    }

    // Configure GPIO27 as an output
    if (pigpio_mode(GPIO27, PI_OUTPUT) < 0) {
        perror("pigpio_mode");
        pigpio_close(i2c_fd);
        pigpio_exit();
        return 1;
    }
    if (pigpio_write(GPIO27, 0) < 0) {
        perror("pigpio_write");
        pigpio_close(i2c_fd);
        pigpio_exit();
        return 1;
    }

    // Initialise the sensor
    if (pigpio_write(i2c_fd, I2C_REG_XSHUT, I2C_CONTINUOUS_MODE) < 0) {
        perror("pigpio_write");
        pigpio_close(i2c_fd);
        pigpio_exit();
        return 1;
    }
    if (pigpio_write(i2c_fd, I2C_REG_STATUS, I2C_TIMEOUT) < 0) {
        perror("pigpio_write");
        pigpio_close(i2c_fd);
        pigpio_exit();
        return 1;
    }
    if (pigpio_write(i2c_fd, I2C_REG_DISTANCE, I2C_START_RANGING) < 0) {
        perror("pigpio_write");
        pigpio_close(i2c_fd);
        pigpio_exit();
        return 1;
    }

    // Main loop
    while (1) {
        // Read distance and status
        if (pigpio_i2c_read(i2c_fd, I2C_REG_DISTANCE, 2, 0, 0, NULL, 0) < 0) {
            perror("pigpio_i2c_read");
            continue;
        }
        uint16_t distance = pigpio_i2c_read(i2c_fd, I2C_REG_DISTANCE, 2, 0, 0, NULL, 0)[0];
        uint8_t status = pigpio_i2c_read(i2c_fd, I2C_REG_STATUS, 1, 0, 0, NULL, 0)[0];

        // Log data
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        syslog(LOG_INFO, "Timestamp: %ld, Distance: %d mm, Status: %d", ts.tv_sec, distance, status);

        // Wait 100 ms
        usleep(100000);
    }

    // Clean up
    pigpio_close(i2c_fd);
    pigpio_exit();
    return 0;
}

