#include <sys/stat.h>
#include <errno.h>

#define I2C_ADDRESS 0x29
#define I2C_ADDRESS2 0x00
#define GPIO_PIN 24
#define GPIO_PIN2 17
#define RANGING_MODE 0x00
#define SHORT_RANGE 0x00
#define START_RANGE 0x01
#define DISTANCE_REG 0x0089
#define DISTANCE_REG2 0x008A
#define DISTANCE_OFFSET 0x1000
#define DISTANCE_MAX 0xFFFF
#define DISTANCE_MIN 0x0000
#define DISTANCE_MAX_MM 1000
#define DISTANCE_MIN_MM 0
#define DISTANCE_STEP 10
#define LOG_FILE "gate_log.txt"

int main() {
    int i2c_fd;
    int gpio_fd;
    int ret;
    int distance;
    int prev_distance;
    struct sigaction sa;
    struct sigaction sa2;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        printf("pigpio initialization failed\n");
        return 1;
    }

    // Open I2C handle
    i2c_fd = i2cOpen(I2C_ADDRESS, 0, 100000);
    if (i2c_fd < 0) {
        printf("I2C open failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        printf("sigaction failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    sa2.sa_handler = sigaction(SIGTERM, &sa2, NULL);
    if (sigaction(SIGTERM, &sa2, NULL) < 0) {
        printf("sigaction failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    if (gpioMode(GPIO_PIN, PI_OUTPUT) < 0) {
        printf("gpioMode failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as high to open the gate
    if (gpioWrite(GPIO_PIN, 1) < 0) {
        printf("gpioWrite failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Read model ID
    ret = i2cWrite(i2c_fd, 0x010F, 1);
    if (ret < 0) {
        printf("i2cWrite failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    ret = i2cRead(i2c_fd, 0x010F, 1);
    if (ret < 0) {
        printf("i2cRead failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (ret != 0xEA) {
        printf("Invalid model ID\n");
        gpioTerminate();
        return 1;
    }

    // Set ranging mode
    ret = i2cWrite(i2c_fd, 0x0021, RANGING_MODE);
    if (ret < 0) {
        printf("i2cWrite failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Start ranging
    ret = i2cWrite(i2c_fd, 0x0015, START_RANGE);
    if (ret < 0) {
        printf("i2cWrite failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Read distance
    ret = i2cRead(i2c_fd, DISTANCE_REG, 2);
    if (ret < 0) {
        printf("i2cRead failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    distance = (ret >> 8) & 0xFF;
    distance += (ret & 0xFF);
    distance *= DISTANCE_OFFSET;
    distance /= DISTANCE_MAX;
    printf("Distance: %.2f cm\n", distance);

    // Main loop
    while (1) {
        // Read distance
        ret = i2cRead(i2c_fd, DISTANCE_REG, 2);
        if (ret < 0) {
            printf("i2cRead failed: %s\n", strerror(errno));
            gpioTerminate();
            return 1;
        }
        distance = (ret >> 8) & 0xFF;
        distance += (ret & 0xFF);
        distance *= DISTANCE_OFFSET;
        distance /= DISTANCE_MAX;
        printf("Distance: %.2f cm\n", distance);

        // Open gate if distance is less than 20 cm
        if (distance < 20) {
            gpioWrite(GPIO_PIN2, 1);
            printf("Gate open\n");
        } else {
            gpioWrite(GPIO_PIN2, 0);
            printf("Gate closed\n");
        }

        // Log distance and gate state
        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            printf("fopen failed: %s\n", strerror(errno));
            gpioTerminate();
            return 1;
        }
        fprintf(log_file, "%d %d %d\n", (int)time(NULL), (int)distance, (int)gpioRead(GPIO_PIN2));
        fclose(log_file);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    gpioTerminate();
    close(i2c_fd);
    return 0;
}

