    if (vl53l1xEnableSignalRateCheck(I2C Bus, I2C_ADDRESS) < 0) {
        printf("Failed to enable signal rate check\n");
        vl53l1xDeinit(I2C Bus, I2C_ADDRESS);
        gpioTerminate();
        return 1;
    }

