#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define I2C_ADDRESS 0x60
#define GPIO_PIN 27
#define PROXIMITY_LOG_FILE "proximity.log"

int main(int argc, char **argv) {
    int i2c_fd = -1;
    int gpio_fd = -1;
    int threshold = 1000;
    int i2c_address = I2C_ADDRESS;
    int gpio = -1;
    int status = 0;
    int log_fd = -1;
    int log_file = 0;
    int running = 0;
    struct timespec last_timestamp;
    struct timespec current_timestamp;
    struct timespec interval;
    struct timespec sleep_time;
    int ret;
    int err;

    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-a") == 0) {
            if (i + 1 >= argc) {
                fprintf(stderr, "Error: -a requires a value\n");
                return 1;
            }
            i2c_address = atoi(argv[++i]);
            if (i2c_address < 0 || i2c_address > 0xFF) {
                fprintf(stderr, "Error: Invalid I2C address\n");
                return 1;
            }
        } else if (strcmp(argv[i], "-t") == 0) {
            if (i + 1 >= argc) {
                fprintf(stderr, "Error: -t requires a value\n");
                return 1;
            }
            threshold = atoi(argv[++i]);
            if (threshold < 0 || threshold > 65535) {
                fprintf(stderr, "Error: Invalid threshold\n");
                return 1;
            }
        } else {
            fprintf(stderr, "Error: Unknown option %s\n", argv[i]);
            return 1;
        }
    }

    // Initialize pigpio
    if (pigpio_init() < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    if ((i2c_fd = pigpio_i2c_open(1, I2C_ADDRESS, 0)) < 0) {
        fprintf(stderr, "Error opening I2C bus 1: %s\n", strerror(errno));
        pigpio_exit();
        return 1;
    }

    // Configure GPIO
    if ((gpio_fd = pigpio_i2c_gpio_open(i2c_fd, GPIO_PIN, 0)) < 0) {
        fprintf(stderr, "Error configuring GPIO %d: %s\n", GPIO_PIN, strerror(errno));
        pigpio_i2c_close(i2c_fd);
        pigpio_exit();
        return 1;
    }

    // Set up interrupt handler
    if (pigpio_i2c_gpio_set_edge_detect(gpio_fd, PI_RISING) < 0) {
        fprintf(stderr, "Error setting edge detect on GPIO %d: %s\n", GPIO_PIN, strerror(errno));
        pigpio_i2c_close(i2c_fd);
        pigpio_i2c_gpio_close(gpio_fd);
        pigpio_exit();
        return 1;
    }

    // Set up interrupt handler
    if (pigpio_i2c_gpio_set_interrupt_handler(gpio_fd, 0, interrupt_handler) < 0) {
        fprintf(stderr, "Error setting interrupt handler on GPIO %d: %s\n", GPIO_PIN, strerror(errno));
        pigpio_i2c_close(i2c_fd);
        pigpio_i2c_gpio_close(gpio_fd);
        pigpio_exit();
        return 1;
    }

    // Open log file
    if ((log_fd = open(PROXIMITY_LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        fprintf(stderr, "Error opening log file %s: %s\n", PROXIMITY_LOG_FILE, strerror(errno));
        pigpio_i2c_close(i2c_fd);
        pigpio_i2c_gpio_close(gpio_fd);
        pigpio_exit();
        return 1;
    }

    // Set up interval timer
    if (clock_gettime(CLOCK_REALTIME, &last_timestamp) < 0) {
        fprintf(stderr, "Error getting current time: %s\n", strerror(errno));
        close(log_fd);
        pigpio_i2c_close(i2c_fd);
        pigpio_i2c_gpio_close(gpio_fd);
        pigpio_exit();
        return 1;
    }

    while (1) {
        // Check if interrupt pending
        if (pigpio_i2c_gpio_get_interrupt(gpio_fd) > 0) {
            // Read proximity value
            if ((ret = pigpio_i2c_read(i2c_fd, 0x08, 1, 0, 0)) < 0) {
                fprintf(stderr, "Error reading proximity value: %s\n", strerror(errno));
                pigpio_i2c_close(i2c_fd);
                pigpio_i2c_gpio_close(gpio_fd);
                pigpio_exit();
                return 1;
            }
            if ((ret = pigpio_i2c_read(i2c_fd, 0x09, 1, 0, 0)) < 0) {
                fprintf(stderr, "Error reading proximity value: %s\n", strerror(errno));
                pigpio_i2c_close(i2c_fd);
                pigpio_i2c_gpio_close(gpio_fd);
                pigpio_exit();
                return 1;
            }

            // Check proximity value
            if (threshold > 0) {
                if (pigpio_i2c_read(i2c_fd, 0x08, 1, 0, 0) > threshold) {
                    status = 'A';
                } else {
                    status = 'S';
                }
            } else {
                status = 'S';
            }

            // Log proximity value
            if (log_fd >= 0) {
                time_t now;
                time(&now);
                struct tm *timeinfo;
                timeinfo = localtime(&now);
                strftime(PROXIMITY_LOG_FILE, 1024, "%Y-%m-%d %H:%M:%S", timeinfo);
                fprintf(log_fd, "%s %d %c\n", PROXIMITY_LOG_FILE, pigpio_i2c_read(i2c_fd, 0x08, 1, 0, 0), status);
            }

            // Reset interrupt
            pigpio_i2c_gpio_clear_interrupt(gpio_fd);
        }

        // Sleep
        if (clock_gettime(CLOCK_REALTIME, &current_timestamp) < 0) {
            fprintf(stderr, "Error getting current time: %s\n", strerror(errno));
            close(log_fd);
            pigpio_i2c_close(i2c_fd);
            pigpio_i2c_gpio_close(gpio_fd);
            pigpio_exit();
            return 1;
        }

        // Calculate sleep time
        if (clock_gettime(CLOCK_REALTIME, &current_timestamp) < 0) {
            fprintf(stderr, "Error getting current time: %s\n", strerror(errno));
            close(log_fd);
            pigpio_i2c_close(i2c_fd);
            pigpio_i2c_gpio_close(gpio_fd);
            pigpio_exit();
            return 1;
        }

        interval.tv_sec = current_timestamp.tv_sec - last_timestamp.tv_sec;
        interval.tv_nsec = current_timestamp.tv_nsec - last_timestamp.tv_nsec;
        if (interval.tv_nsec < 0) {
            interval.tv_sec--;
            interval.tv_nsec += 1000000000;
        }
        sleep_time.tv_sec = interval.tv_sec;
        sleep_time.tv_nsec = interval.tv_nsec;

        // Sleep
        if (clock_nanosleep(&sleep_time, NULL) < 0) {
            fprintf(stderr, "Error sleeping: %s\n", strerror(errno));
            close(log_fd);
            pigpio_i2c_close(i2c_fd);
            pigpio_i2c_gpio_close(gpio_fd);
            pigpio_exit();
            return 1;
        }

        last_timestamp = current_timestamp;
    }

    // Clean up
    if (log_fd >= 0) {
        close(log_fd);
    }
    pigpio_i2c_close(i2c_fd);
    pigpio_i2c_gpio_close(gpio_fd);
    pigpio_exit();

    return 0;
}

void interrupt_handler(int gpio, int level, void *data) {
    if (data == NULL) {
        return;
    }

    int *threshold = (int *)data;
    int *proximity = (int *)data + 1;

    if (*proximity > *threshold) {
        *proximity = 0;
        fprintf(stderr, "ALERT\n");
    } else {
        *proximity = 0;
        fprintf(stderr, "SAFE\n");
    }
}

