            return 1;
        }

        interval.tv_sec = current_timestamp.tv_sec - last_timestamp.tv_sec;
        interval.tv_nsec = current_timestamp.tv_nsec - last_timestamp.tv_nsec;
        if (interval.tv_nsec < 0) {
            interval.tv_sec--;
            interval.tv_nsec += 1000000000;
        }
        sleep_time.tv_sec = interval.tv_sec;
        sleep_time.tv_nsec = interval.tv_nsec;

        // Sleep
        if (clock_nanosleep(&sleep_time, NULL) < 0) {
            fprintf(stderr, "Error sleeping: %s\n", strerror(errno));
            close(log_fd);
            pigpio_i2c_close(i2c_fd);
            pigpio_i2c_gpio_close(gpio_fd);
            pigpio_exit();
            return 1;
        }

        last_timestamp = current_timestamp;
    }

    // Clean up
    if (log_fd >= 0) {
        close(log_fd);
    }
    pigpio_i2c_close(i2c_fd);
    pigpio_i2c_gpio_close(gpio_fd);
    pigpio_exit();

    return 0;
}

void interrupt_handler(int gpio, int level, void *data) {
    if (data == NULL) {
        return;
    }

    int *threshold = (int *)data;
    int *proximity = (int *)data + 1;

    if (*proximity > *threshold) {
        *proximity = 0;
        fprintf(stderr, "ALERT\n");
    } else {
        *proximity = 0;
        fprintf(stderr, "SAFE\n");
    }
}
