    signal(SIGTERM, sigtermHandler);

    // Open the speaker pin
    if (pigpioOpen(GPIO_SPEAKER, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to open speaker pin\n");
        pigpioTerminate();
        return 1;
    }

