        fprintf(stderr, "Failed to set PWM frequency and duty cycle\n");
        pigpioClose(GPIO_TRIGGER);
        pigpioClose(GPIO_ECHO);
        pigpioClose(GPIO_SPEAKER);
        pigpioTerminate();
        return 1;
    }

    // Set the PWM channel to generate a tone
    if (pigpioHardwarePWMConfig(PWM_CHANNEL, PWM_FREQ_MIN, PWM_DUTY_CYCLE) < 0) {
        fprintf(stderr, "Failed to set PWM channel to generate a tone\n");
        pigpioClose(GPIO_TRIGGER);
        pigpioClose(GPIO_ECHO);
        pigpioClose(GPIO_SPEAKER);
        pigpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read the trigger and echo values
        int triggerValue = pigpioRead(GPIO_TRIGGER);
        int echoValue = pigpioRead(GPIO_ECHO);

        // Check if the echo is valid
        if (echoValue == 0) {
            continue;
        }

        // Calculate the distance
        double distance = (echoValue * 0.034375) / 2;

        // Calculate the frequency
        double frequency = frequencyFromDistance(distance);

        // Set the PWM frequency
        if (pigpioHardwarePWMConfig(PWM_CHANNEL, frequency, PWM_DUTY_CYCLE) < 0) {
            fprintf(stderr, "Failed to set PWM frequency\n");
            continue;
        }

        // Generate the tone
        pigpioWrite(GPIO_SPEAKER, 1);
        pigpioWaveTxBusy(PWM_CHANNEL, TRIGGER_PULSE_US, TIMEOUT_MS);
    }

    // Clean up
    pigpioClose(GPIO_TRIGGER);
    pigpioClose(GPIO_ECHO);
    pigpioClose(GPIO_SPEAKER);
    pigpioTerminate();
    return 0;
}

