        printf("pigpio initialization failed\n");
        exit(1);
    }
    if (gpio_mode(TRIGGER_PIN, PI_INPUT) != 0) {
        printf("Failed to set %d as input\n", TRIGGER_PIN);
        exit(1);
    }
