        exit(1);
    }
    if (gpio_mode(PWM_PIN, PI_OUTPUT) != 0) {
        printf("Failed to set %d as output\n", PWM_PIN);
        exit(1);
    }
    if (gpioHardwarePWM(PWM_PIN, PI_HIGH) != 0) {
        printf("Failed to set %d as PWM output\n", PWM_PIN);
        exit(1);
    }
}

// Function to read distance from HC-SR04 sensor
int read_distance() {
    gpioWrite(TRIGGER_PIN, TRIGGER_LEVEL);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(10);
    int start_time = gpioRead(ECHO_PIN);
    gpioDelay(5);
    int end_time = gpioRead(ECHO_PIN);
    if (end_time == start_time) {
        printf("Timeout reading distance\n");
        return -1;
    }
    int distance = (end_time - start_time) * 34300 / 2;
    return distance;
}

