int calculate_freq(int distance) {
    if (distance < MIN_DIST) {
        return MIN_FREQ;
    } else if (distance > MAX_DIST) {
        return MAX_FREQ;
    } else {
        return MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (MAX_DIST - distance) / (MAX_DIST - MIN_DIST);
    }
}

