#include <pigpio.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TRIGGER_PULSE 10
#define ECHO_TIMEOUT 50
#define SOUND_SPEED 29.1
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400
#define TOO_CLOSE_THRESHOLD 10

int main() {
    int pi;
    int trig_state = 0;
    int echo_state = 0;
    int pulse_width = 0;
    int distance = 0;
    int too_close = 0;
    int running = 1;
    int sigint_received = 0;

    // Initialize pigpio
    if (pi = pigpio_init()) {
        printf("pigpio initialization failed\n");
        return 1;
    }

    // Set up GPIO pins
    if (pi->gpio_fsel(TRIGGER_PIN, PI_OUTPUT) != 0) {
        printf("Failed to set trigger pin as output\n");
        pigpio_close(pi);
        return 1;
    }
    if (pi->gpio_fsel(ECHO_PIN, PI_INPUT) != 0) {
        printf("Failed to set echo pin as input\n");
        pigpio_close(pi);
        return 1;
    }

    while (running) {
        // Send trigger pulse
        if (pi->gpio_write(TRIGGER_PIN, 1) != 0) {
            printf("Failed to send trigger pulse\n");
            break;
        }
        usleep(TRIGGER_PULSE);

        // Measure echo pulse width
        if (pi->gpio_read(ECHO_PIN, &echo_state) != 0) {
            printf("Failed to read echo state\n");
            break;
        }
        if (echo_state == 0) {
            printf("Invalid reading\n");
            continue;
        }
        if (pi->gpio_read(ECHO_PIN, &pulse_width) != 0) {
            printf("Failed to read echo pulse width\n");
            break;
        }

        // Calculate distance
        distance = (pulse_width / 2) / (ECHO_TIMEOUT * SOUND_SPEED);
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            printf("Invalid reading\n");
        } else if (distance < TOO_CLOSE_THRESHOLD) {
            printf("Too close!\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
        }

        // Check for SIGINT
        if (sigint_received) {
            break;
        }

        // Release resources
        if (pi->gpio_write(TRIGGER_PIN, 0) != 0) {
            printf("Failed to release trigger pin\n");
        }
        if (pi->gpio_fsel(TRIGGER_PIN, PI_INPUT) != 0) {
            printf("Failed to set trigger pin as input\n");
        }
        if (pi->gpio_fsel(ECHO_PIN, PI_INPUT) != 0) {
            printf("Failed to set echo pin as input\n");
        }
        if (pi->gpio_read(ECHO_PIN, &echo_state) != 0) {
            printf("Failed to read echo state\n");
        }
        if (pi->gpio_read(ECHO_PIN, &pulse_width) != 0) {
            printf("Failed to read echo pulse width\n");
        }
    }

    // Release resources
    if (pi) {
        pigpio_close(pi);
    }

    return 0;
}

