#define I2C_ADDRESS 0x60
#define I2C_ADDRESS_RETRY 3
#define I2C_ADDRESS_RETRY_DELAY 10
#define I2C_READ_TIMEOUT 1000
#define I2C_WRITE_TIMEOUT 1000
#define LOG_FILE "si1120_log.txt"

int main() {
    int i2c_fd = -1;
    int i2c_retry = 0;
    int log_fd = -1;
    int pi = -1;
    struct stat sb;
    struct timespec ts;
    struct timespec last_ts;
    unsigned char i2c_read[2];
    unsigned char i2c_write[1];
    unsigned short data;

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd < 0) {
        perror("open");
        return 1;
    }

    // Initialize pigpio
    if (pi = pigpio_init(), pi < 0) {
        perror("pigpio_init");
        return 1;
    }

    // Open I2C device
    if (i2c_fd = pigpio_i2c_open(I2C_ADDRESS, 1, 1000), i2c_fd < 0) {
        perror("pigpio_i2c_open");
        pigpio_close(pi);
        return 1;
    }

    // Reset sensor
    if (pigpio_i2c_write(i2c_fd, 0x30, 0x01, 1000), i2c_retry < I2C_ADDRESS_RETRY) {
        i2c_retry++;
        usleep(I2C_ADDRESS_RETRY_DELAY * 1000);
    } else {
        pigpio_close(i2c_fd);
        pigpio_close(pi);
        return 1;
    }

    // Verify part ID
    if (pigpio_i2c_read(i2c_fd, 0x00, 1, 1000, &i2c_read[0], 1), i2c_retry < I2C_ADDRESS_RETRY) {
        i2c_retry++;
        usleep(I2C_ADDRESS_RETRY_DELAY * 1000);
    } else {
        pigpio_close(i2c_fd);
        pigpio_close(pi);
        return 1;
    }
    if (i2c_read[0] != 0x41) {
        pigpio_close(i2c_fd);
        pigpio_close(pi);
        return 1;
    }

    // Read ALS and proximity data
    while (1) {
        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        if (ts.tv_sec != last_ts.tv_sec || ts.tv_nsec != last_ts.tv_nsec) {
            last_ts = ts;
            fprintf(log_fd, "%04d-%02d-%02d %02d:%02d:%02d\n", ts.tv_year, ts.tv_mon + 1, ts.tv_mday, ts.tv_hour, ts.tv_min, ts.tv_sec);
        }

        // Read ALS data
        if (pigpio_i2c_read(i2c_fd, 0x22, 1, I2C_READ_TIMEOUT, &i2c_read[0], 1), i2c_retry < I2C_ADDRESS_RETRY) {
            i2c_retry++;
            usleep(I2C_ADDRESS_RETRY_DELAY * 1000);
        } else {
            pigpio_close(i2c_fd);
            pigpio_close(pi);
            return 1;
        }
        data = (i2c_read[0] << 8) | i2c_read[1];
        printf("%d %d\n", data, data);

        // Read proximity data
        if (pigpio_i2c_read(i2c_fd, 0x18, 1, I2C_READ_TIMEOUT, &i2c_read[0], 1), i2c_retry < I2C_ADDRESS_RETRY) {
            i2c_retry++;
            usleep(I2C_ADDRESS_RETRY_DELAY * 1000);
        } else {
            pigpio_close(i2c_fd);
            pigpio_close(pi);
            return 1;
        }
        data = (i2c_read[0] << 8) | i2c_read[1];
        printf("%d %d\n", data, data);

        // Sleep for 500 ms
        usleep(500000);
    }

    // Close log file
    close(log_fd);

    // Close I2C device
    pigpio_i2c_close(i2c_fd);

    // Close pigpio
    pigpio_close(pi);

    return 0;
}

