#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <unistd.h>

#define I2C_ADDRESS 0x60
#define I2C_WRITE_SEQUENCE 0x03, 0x07, 0x02, 0x06, 0x00, 0x0B, 0x21, 0x00, 0x00, 0x24, 0x49, 0x22, 0x03, 0x0C, 0x0F, 0x0F, 0x03, 0x11, 0x07, 0x0D, 0x03, 0x80
#define I2C_READ_REGISTER 0x16, 0x17
#define LOG_FILE "proximity_log.txt"

int main() {
    int i2c_fd = -1;
    int gpio_fd = -1;
    int retry_count = 0;
    int retry_limit = 3;
    char timestamp[20];
    char log_message[256];

    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    // Open I2C interface
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }
    if (i2cOpen(&i2c_fd, I2C_ADDRESS, 100000) < 0) {
        perror("i2cOpen");
        gpioTerminate();
        return 1;
    }

    // Write initialisation sequence
    if (i2cWriteByteData(i2c_fd, I2C_WRITE_SEQUENCE, sizeof(I2C_WRITE_SEQUENCE)) < 0) {
        retry_count++;
        if (retry_count <= retry_limit) {
            printf("I2C write error, retrying...\n");
            sleep(1);
            retry_count++;
        } else {
            printf("I2C write error, giving up.\n");
            gpioTerminate();
            return 1;
        }
    }

    // Read and log proximity data
    while (1) {
        // Read proximity data
        if (i2cReadByteData(i2c_fd, I2C_READ_REGISTER, sizeof(I2C_READ_REGISTER)) < 0) {
            retry_count++;
            if (retry_count <= retry_limit) {
                printf("I2C read error, retrying...\n");
                sleep(1);
                retry_count++;
            } else {
                printf("I2C read error, giving up.\n");
                gpioTerminate();
                return 1;
            }
        }

        // Combine low and high bytes into 16-bit unsigned integer
        unsigned short proximity_value = (i2cReadByteData(i2c_fd, I2C_READ_REGISTER, sizeof(I2C_READ_REGISTER)) << 8) | i2cReadByteData(i2c_fd, I2C_READ_REGISTER, sizeof(I2C_READ_REGISTER));

        // Append timestamp and reading to log file
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        sprintf(log_message, "%s %d\n", timestamp, proximity_value);
        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("fopen");
            gpioTerminate();
            return 1;
        }
        fwrite(log_message, sizeof(log_message), 1, log_file);
        fclose(log_file);

        // Sleep for 1 second before taking the next reading
        sleep(1);
    }

    // Clean up
    gpioTerminate();
    if (i2cClose(i2c_fd) < 0) {
        perror("i2cClose");
    }
    return 0;
}

void sigint_handler(int sig) {
    printf("Received SIGINT, shutting down...\n");
    gpioTerminate();
    i2cClose(i2c_fd);
    exit(0);
}

