#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>

// Define constants
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27
#define TRIGGER_PULSE_US 10
#define DISTANCE_THRESHOLD 20

// Define structures for interrupt handlers
typedef struct {
    void (*rising_edge)(void);
    void (*falling_edge)(void);
} EdgeHandler;

// Define the edge handler for the echo pin
EdgeHandler echo_edge_handler = {
    .rising_edge = echo_rising_edge,
    .falling_edge = echo_falling_edge
};

// Define the interrupt handler for the echo pin
void echo_rising_edge(void) {
    // Record the rising edge timestamp
    double rising_timestamp = gpioGetTimestamp();
    // Record the falling edge timestamp
    double falling_timestamp = gpioGetTimestamp();
    // Calculate the echo pulse width
    double echo_pulse_width = (falling_timestamp - rising_timestamp) / 1000000.0;
    // Calculate the distance
    double distance = echo_pulse_width * 0.0343 / 2;
    // Print the distance to stdout
    printf("%.2f cm\n", distance);
    // Set the buzzer pin high if the distance is below the threshold
    gpioWrite(BUZZER_PIN, 1);
    if (distance < DISTANCE_THRESHOLD) {
        printf("Buzzer activated\n");
    } else {
        printf("Buzzer deactivated\n");
    }
}

void echo_falling_edge(void) {
    // Set the buzzer pin low
    gpioWrite(BUZZER_PIN, 0);
