#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18
#define SERVO_MIN 500
#define SERVO_MAX 2500
#define SERVO_CENTER 1500
#define SERVO_LEFT 90
#define SERVO_RIGHT 180
#define SERVO_LEFT_CM 200
#define SERVO_RIGHT_CM 110
#define SERVO_LEFT_DEG 0
#define SERVO_RIGHT_DEG 180
#define SERVO_CENTER_DEG 90
#define SERVO_STEP 10
#define SERVO_SPEED 10

int main() {
    int gpio;
    int servo_angle = SERVO_CENTER_DEG;
    int servo_position = SERVO_CENTER;
    int distance;
    int retry = 0;
    int last_distance = -1.0;
    int last_angle = SERVO_CENTER_DEG;
    int last_time = 0;

    // Initialize pigpio
    if (gpio = pigpio_init()) {
        printf("pigpio initialization failed\n");
        return 1;
    }

    // Set up GPIO pins
    if (gpioInitialise(gpio, TRIGGER_PIN, PI_INPUT) != 0) {
        printf("Failed to set up trigger pin %d\n", TRIGGER_PIN);
        pigpio_close(gpio);
        return 1;
    }
    if (gpioInitialise(gpio, ECHO_PIN, PI_INPUT) != 0) {
        printf("Failed to set up echo pin %d\n", ECHO_PIN);
        pigpio_close(gpio);
        return 1;
    }
    if (gpioInitialise(gpio, SERVO_PIN, PI_OUTPUT) != 0) {
        printf("Failed to set up servo pin %d\n", SERVO_PIN);
        pigpio_close(gpio);
        return 1;
    }

    // Set up servo
    if (gpioServoWrite(gpio, SERVO_PIN, SERVO_CENTER_DEG) != 0) {
        printf("Failed to set up servo\n");
        pigpio_close(gpio);
        return 1;
    }

    while (1) {
        // Measure distance
        if (gpioGet(gpio, ECHO_PIN, &distance, 1000) != 0) {
            printf("Failed to measure distance\n");
            distance = -1.0;
            retry++;
            if (retry > 5) {
                break;
            }
            continue;
        }

        // Convert distance to centimeters
        distance /= 2.0;

        // Update servo angle
        if (distance < SERVO_LEFT_CM) {
            servo_angle = SERVO_LEFT_DEG;
