        printf("%.2f cm\n", distance);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    gpioTerminate(gpio);
    pigpio_close(gpio);

    // Handle SIGINT
    signal(SIGINT, SIG_IGN);

    return 0;
}

