#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <termios.h>
#include <unistd.h>

#define I2C_ADDRESS 0x29
#define I2C Bus 1
#define GPIO_PIN 18
#define SERVO_MIN 1000
#define SERVO_MAX 2000
#define DISTANCE_THRESHOLD 200
#define DISTANCE_HYSTERESIS 50
#define LOG_FILE "gate_log.txt"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C handle
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set I2C mode
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X
    unsigned char model_id;
    if (read(&model_id, &model_id, 1) != 1) {
        perror("read");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (model_id != 0xEA) {
        printf("Invalid model ID\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set timing budget
    unsigned char timing_budget;
    if (read(&timing_budget, &timing_budget, 1) != 1) {
        perror("read");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (timing_budget != 0x01) {
        printf("Invalid timing budget\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Start ranging
    unsigned char start_range;
    if (write(&start_range, &start_range, 1) != 1) {
        perror("write");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open gate
    int servo_fd = open("/dev/pwm0", O_RDWR);
    if (servo_fd < 0) {
        perror("open");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    struct termios oldt, newt;
    tcgetattr(servo_fd, &oldt);
    newt = oldt;
    newt.c_cflag &= ~CSIZE;
    newt.c_cflag &= ~PARENB;
    newt.c_cflag &= ~CSTOPB;
    newt.c_cflag &= ~CRTSCTS;
    newt.c_lflag &= ~ICANON;
    newt.c_lflag &= ~ECHO;
    newt.c_lflag &= ~ECHOE;
    newt.c_lflag &= ~ISIG;
    newt.c_oflag &= ~OPOST;
    newt.c_oflag &= ~OPOST;
    newt.c_cc[VMIN] = 0;
    newt.c_cc[VTIME] = 0;
    if (tcsetattr(servo_fd, TCSANOW, &newt) != 0) {
        perror("tcsetattr");
        close(i2c_fd);
        close(servo_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    int log_fd = open(LOG_FILE, O_RDWR | O_CREAT | O_WRONLY, 0644);
    if (log_fd < 0) {
        perror("open");
        close(i2c_fd);
        close(servo_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        unsigned char distance;
        if (read(&distance, &distance, 1) != 1) {
            perror("read");
            close(i2c_fd);
            close(servo_fd);
            close(log_fd);
            gpioTerminate();
            return 1;
        }

        if (distance < DISTANCE_THRESHOLD) {
            printf("Object detected, opening gate...\n");
            unsigned char pulse_width = SERVO_MIN + (SERVO_MAX - SERVO_MIN) * (DISTANCE_THRESHOLD - DISTANCE_HYSTERESIS) / (DISTANCE_THRESHOLD - DISTANCE_HYSTERESIS);
            if (write(&pulse_width, &pulse_width, 1) != 1) {
                perror("write");
                close(i2c_fd);
                close(servo_fd);
                close(log_fd);
                gpioTerminate();
                return 1;
            }
            if (write(servo_fd, &pulse_width, 1) != 1) {
                perror("write");
                close(i2c_fd);
                close(servo_fd);
                close(log_fd);
                gpioTerminate();
                return 1;
            }
            if (write(log_fd, "Open\n", 4) != 4) {
                perror("write");
                close(i2c_fd);
                close(servo_fd);
                close(log_fd);
                gpioTerminate();
                return 1;
            }
        } else if (distance > DISTANCE_THRESHOLD + DISTANCE_HYSTERESIS) {
            printf("Object moved away, closing gate...\n");
            unsigned char pulse_width = SERVO_MAX - SERVO_MIN + (SERVO_MIN - SERVO_MAX) * (DISTANCE_HYSTERESIS) / (DISTANCE_THRESHOLD + DISTANCE_HYSTERESIS);
            if (write(&pulse_width, &pulse_width, 1) != 1) {
                perror("write");
                close(i2c_fd);
                close(servo_fd);
                close(log_fd);
                gpioTerminate();
                return 1;
            }
            if (write(servo_fd, &pulse_width, 1) != 1) {
                perror("write");
                close(i2c_fd);
                close(servo_fd);
                close(log_fd);
                gpioTerminate();
                return 1;
            }
            if (write(log_fd, "Close\n", 5) != 5) {
                perror("write");
                close(i2c_fd);
                close(servo_fd);
                close(log_fd);
                gpioTerminate();
                return 1;
            }
        }
    }

    return 0;
}

