#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18
#define TRIGGER_PULSE_US 10
#define MAX_DISTANCE 400
#define MIN_DISTANCE 2
#define MAX_ANGLE 180
#define MIN_ANGLE 0
#define SERVO_PULSE_WIDTH_0 500
#define SERVO_PULSE_WIDTH_180 2500
#define SERVO_SPEED 0.0343

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio\n");
        return 1;
    }

    // Set up GPIO pins
    if (gpioSetMode(TRIGGER_PIN, PI_INPUT) < 0) {
        printf("Failed to set up GPIO %d as input\n", TRIGGER_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        printf("Failed to set up GPIO %d as input\n", ECHO_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        printf("Failed to set up GPIO %d as output\n", SERVO_PIN);
        gpioTerminate();
        return 1;
    }

    // Set up servo
    if (gpioServo(SERVO_PIN, SERVO_PULSE_WIDTH_0) < 0) {
        printf("Failed to set up servo on GPIO %d\n", SERVO_PIN);
        gpioTerminate();
        return 1;
    }

    // Set up trigger and echo pin as output
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        printf("Failed to set up GPIO %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(ECHO_PIN, 0) < 0) {
        printf("Failed to set up GPIO %d as output\n", ECHO_PIN);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigHandler);

    while (1) {
        // Trigger sensor
        gpioWrite(TRIGGER_PIN, 1);
        usleep(TRIGGER_PULSE_US);
        gpioWrite(TRIGGER_PIN, 0);

        // Measure echo pulse width
        struct timespec start, end;
        gpioTick(&start);
        if (gpioRead(ECHO_PIN) < 0) {
            printf("Failed to read GPIO %d\n", ECHO_PIN);
            gpioTerminate();
            return 1;
        }
        gpioTick(&end);
        if (end.tv_sec - start.tv_sec > 0.05 || end.tv_nsec - start.tv_nsec > 50000000) {
            printf("Timeout measuring echo pulse width\n");
            continue;
        }
        unsigned long pulse_width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec);
        if (pulse_width < 0) {
            printf("Invalid pulse width\n");
            continue;
        }

        // Calculate distance
        double distance = (pulse_width * SERVO_SPEED) / 2;
        if (distance < MIN_DISTANCE) {
            distance = MIN_DISTANCE;
        } else if (distance > MAX_DISTANCE) {
            distance = MAX_DISTANCE;
        }

        // Map distance to angle
        double angle = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE;

        // Print distance and angle
        printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);

        // Set servo angle
        if (angle < MIN_ANGLE) {
            gpioServo(SERVO_PIN, SERVO_PULSE_WIDTH_0);
        } else if (angle > MAX_ANGLE) {
            gpioServo(SERVO_PIN, SERVO_PULSE_WIDTH_180);
        } else {
            gpioServo(SERVO_PIN, SERVO_PULSE_WIDTH_0 + (SERVO_PULSE_WIDTH_180 - SERVO_PULSE_WIDTH_0) * (angle - MIN_ANGLE) / (MAX_ANGLE - MIN_ANGLE));
        }

        // Delay
        usleep(100000);
    }

    // Clean up
    gpioTerminate();
    return 0;
}

void sigHandler(int sig) {
    printf("Stopping servo\n");
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    exit(0);
}

