#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

#define I2C_ADDRESS 0x40
#define I2C_BUS 1
#define CONFIG_REGISTER 0x03
#define TEMPERATURE_REGISTER 0x01
#define HUMIDITY_REGISTER 0x02

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up I2C
    if (gpioI2CInit(I2C_BUS) < 0) {
        perror("gpioI2CInit");
        gpioTerminate();
        return 1;
    }

    // Open I2C handle
    if (gpioI2COpen(I2C_BUS, I2C_ADDRESS) < 0) {
        perror("gpioI2COpen");
        gpioI2CClose(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Wait for SIGINT
    signal(SIGINT, SIG_IGN);

    while (1) {
        // Write to CONFIG register
        if (gpioI2CWrite(I2C_BUS, CONFIG_REGISTER, 0x00) < 0) {
            gpioI2CClose(I2C_BUS);
            gpioTerminate();
            return 1;
        }
        usleep(10);

        // Wait for conversion
        usleep(10);

        // Read temperature and humidity
        unsigned char raw_temp = 0;
        unsigned char raw_humidity = 0;
        if (gpioI2CRead(I2C_BUS, TEMPERATURE_REGISTER, &raw_temp) < 0) {
            gpioI2CClose(I2C_BUS);
            gpioTerminate();
            return 1;
        }
        if (gpioI2CRead(I2C_BUS, HUMIDITY_REGISTER, &raw_humidity) < 0) {
            gpioI2CClose(I2C_BUS);
            gpioTerminate();
            return 1;
        }

        // Convert readings
        float temperature = (175.72 * raw_temp) / 65536.0 - 46.85;
        float humidity = (125.0 * raw_humidity) / 65536.0 - 6.0;

        // Print readings
        printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temperature, humidity);

        // Close I2C handle
        gpioI2CClose(I2C_BUS);
        gpioTerminate();

        // Wait 2 seconds before repeating
        sleep(2);
    }

    return 0;
}

