#define I2C_ADDRESS 0x68
#define I2C_ADDRESS_ACCEL 0x3B
#define I2C_ADDRESS_WHO_AM_I 0x00
#define I2C_ADDRESS_PWR_MGMT_1 0x6B
#define I2C_ADDRESS_ACCEL_CONFIG 0x1C
#define I2C_ADDRESS_GYRO_CONFIG 0x1B
#define I2C_ADDRESS_SAMPLE_RATE_DIVIDER 0x19
#define I2C_ADDRESS_ACCEL_DATA 0x3B

int main(int argc, char **argv) {
    int i2c_fd;
    int i2c_result;
    int sample_rate_divider;
    int accel_config;
    int gyro_config;
    int accel_data[6];
    int gyro_data[6];
    int temperature;
    int error;
    int status;
    int gpio_fd;
    struct sigaction sa;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up signal handlers
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGPIPE);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C handle
    if ((i2c_fd = i2cOpen(I2C_ADDRESS, 0, 1000)) < 0) {
        perror("i2cOpen");
        gpioTerminate();
        return 1;
    }

    // Verify sensor is present
    if ((i2c_result = i2cWriteI2CBlockData(i2c_fd, I2C_ADDRESS_WHO_AM_I, 1, &status)) < 0) {
        perror("i2cWriteI2CBlockData");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (status != 0x68) {
        printf("Sensor not found\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Reset device
    if ((i2c_result = i2cWriteI2CBlockData(i2c_fd, I2C_ADDRESS_PWR_MGMT_1, 1, &error)) < 0) {
        perror("i2cWriteI2CBlockData");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    usleep(100000); // wait for device to stabilize
    if ((i2c_result = i2cWriteI2CBlockData(i2c_fd, I2C_ADDRESS_PWR_MGMT_1, 1, &error)) < 0) {
        perror("i2cWriteI2CBlockData");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (error != 0) {
        printf("Failed to reset device\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set sample-rate divider
    if ((i2c_result = i2cWriteI2CBlockData(i2c_fd, I2C_ADDRESS_SAMPLE_RATE_DIVIDER, 1, &sample_rate_divider)) < 0) {
        perror("i2cWriteI2CBlockData");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (sample_rate_divider != 7) {
        printf("Failed to set sample-rate divider\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set accelerometer and gyroscope configurations
    if ((i2c_result = i2cWriteI2CBlockData(i2c_fd, I2C_ADDRESS_ACCEL_CONFIG, 1, &accel_config)) < 0) {
