#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define I2C_ADDRESS 0x44
#define I2C Bus 1
#define I2C_COMMAND 0xFD
#define I2C_READ 0x00
#define I2C_WRITE 0x01
#define CRC8_POLYNOMINAL 0x31
#define CRC8_INIT_VALUE 0xFF

int main(int argc, char **argv) {
    int i2c_fd = -1;
    int ret;
    int temperature, humidity;
    unsigned char crc8, crc8_read;
    unsigned char raw[7];
    int sigint_received = 0;
    int sigterm_received = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set I2C address and mode
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set I2C clock speed
    if (ioctl(i2c_fd, I2C_SMBUS_SET_CLOCK, 100000) < 0) {
        perror("ioctl");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (!sigint_received && !sigterm_received) {
        // Send command to start measurement
        if (write(i2c_fd, &I2C_COMMAND, 1) < 0) {
            perror("write");
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Wait at least 10 ms
        usleep(10000);

        // Read 6 bytes
        if (read(i2c_fd, raw, 6) < 6) {
            perror("read");
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Validate CRC-8 checksum
        crc8 = raw[5];
        crc8_read = raw[6];
        if ((crc8 != crc8_read) || (crc8 != (crc8_read ^ (crc8_read >> 1))) || (crc8 != (crc8_read >> 2))) {
            fprintf(stderr, "CRC-8 checksum error\n");
            continue;
        }

        // Convert raw values
        temperature = (raw[0] << 8) | raw[1];
        humidity = (raw[2] << 8) | raw[3];

        // Clamp values to 0-100%
        temperature = (temperature - 45) * 175 / 65535;
        humidity = (-6 + (humidity * 125) / 65535) * 100;

        // Print readings
        printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temperature, humidity);

        // Wait 5 seconds before next measurement
        sleep(5);
    }

    // Close I2C handle
    close(i2c_fd);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

