#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/select.h>
#include <signal.h>

#define I2C_ADDRESS 0x5A
#define I2C_REG_AMBIENT 0x06
#define I2C_REG_OBJECT 0x07
#define I2C_READ 0x00
#define I2C_WRITE 0x80
#define FILE_NAME "temperature_log.csv"

int main() {
    int i2c_fd, log_fd;
    struct sigaction sa;
    struct sigaction sigint_handler;
    char buffer[3];
    int bytes_read;
    time_t timestamp;
    struct timespec delay;

    // Initialize signal handler for SIGINT
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    sigaction(SIGINT, &sa, NULL);

    // Open I2C file descriptor
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C file descriptor");
        return 1;
    }

    // Set I2C address and mode
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    if ((log_fd = open(FILE_NAME, O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        // Read ambient and object temperatures
        if (read(i2c_fd, buffer, 2) < 2) {
            perror("Failed to read from I2C device");
            continue;
        }

        // Check if sensor is present
        if (buffer[0] == 0x00) {
            printf("Sensor not found.\n");
            continue;
        }

        // Extract temperatures
        int ambient = (buffer[0] << 8) | buffer[1];
        int object = (buffer[0] << 8) | buffer[1];

        // Log temperatures
        timestamp = time(NULL);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&timestamp));
        fprintf(log_fd, "%s,%d,%d\n", buffer, ambient, object);

        // Delay before next read
        nanosleep(&delay, NULL);
        delay.tv_sec = 5;
        delay.tv_nsec = 0;

        // Check for SIGINT
        if (killpg(0, SIGINT) == -1) {
            break;
        }
    }

    // Close I2C file descriptor and log file
    close(i2c_fd);
    close(log_fd);

    return 0;
}

