#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/statvfs.h>
#include <errno.h>
#include <signal.h>

#define I2C_ADDRESS 0x4A
#define I2C Bus 1
#define FILE_NAME "enclosure_temp_log.txt"
#define ERROR_LOG "error_log.txt"

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open log files
    int log_fd = open(FILE_NAME, O_RDWR | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    int error_fd = open(ERROR_LOG, O_RDWR | O_CREAT | O_APPEND, 0644);
    if (error_fd < 0) {
        perror("open");
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Map log file for writing
    struct stat sb;
    if (fstat(log_fd, &sb) < 0) {
        perror("fstat");
        close(log_fd);
        close(error_fd);
        gpioTerminate();
        return 1;
    }
    void *log_ptr = mmap(NULL, sb.st_size, PROT_READ | PROT_WRITE, MAP_SHARED, log_fd, 0);
    if (log_ptr == MAP_FAILED) {
        perror("mmap");
        close(log_fd);
        close(error_fd);
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    if (i2cInit(I2C Bus) < 0) {
        perror("i2cInit");
        close(log_fd);
        close(error_fd);
        munmap(log_ptr, sb.st_size);
        gpioTerminate();
        return 1;
    }

    // Open I2C device
    if (i2cOpen(I2C Bus, I2C_ADDRESS, NULL) < 0) {
        perror("i2cOpen");
        close(log_fd);
        close(error_fd);
        i2cDeinit(I2C Bus);
        munmap(log_ptr, sb.st_size);
        gpioTerminate();
        return 1;
    }

    // Set I2C clock speed
    if (i2cSetClock(I2C Bus, 100000) < 0) {
        perror("i2cSetClock");
        close(log_fd);
        close(error_fd);
        i2cClose(I2C Bus);
        munmap(log_ptr, sb.st_size);
        gpioTerminate();
        return 1;
    }

    // Define I2C read function
    void *i2c_read(void *data, size_t size) {
        return i2cRead(I2C Bus, I2C_ADDRESS, data, size);
    }

    // Define signal handler for Ctrl+C
    void sigint_handler(int sig) {
        close(log_fd);
        close(error_fd);
        i2cClose(I2C Bus);
        munmap(log_ptr, sb.st_size);
        gpioTerminate();
        exit(0);
    }

    // Register signal handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Read temperature
        void *data = malloc(sizeof(int16_t));
        if (i2c_read(data, sizeof(int16_t)) < 0) {
            perror("i2c_read");
            continue;
        }

        // Check for errors
        if (data == NULL) {
            fprintf(error_fd, "Error reading from sensor\n");
            continue;
        }

        int16_t temperature = *(int16_t *)data;
        free(data);

        // Log temperature
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_ptr, "%s %d\n", timestamp, temperature);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    close(log_fd);
    close(error_fd);
    i2cClose(I2C Bus);
    munmap(log_ptr, sb.st_size);
    gpioTerminate();

    return 0;
}

