#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <time.h>

#define I2C_ADDRESS 0x44
#define I2C Bus 1
#define GPIO_SDA GPIO2
#define GPIO_SCL GPIO3
#define I2C_FILE "/dev/i2c-1"
#define LOG_FILE "sht40_log.txt"

int main() {
    int fd;
    struct timespec delay;
    struct timespec last_log_time;
    struct timespec start_time;
    unsigned char raw[6];
    unsigned char crc;
    int retry = 0;
    int retry_count = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C file descriptor
    fd = open(I2C_FILE, O_RDWR);
    if (fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set I2C bus parameters
    if (ioctl(fd, I2C_SLAVE, I2C_Bus) < 0) {
        perror("ioctl");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set I2C clock speed
    if (ioctl(fd, I2C_SMBUS, I2C_CLOCK, 100000) < 0) {
        perror("ioctl");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set I2C address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Wait for the first measurement to complete
    usleep(10000);

    // Main loop
    while (1) {
        // Read raw data
        if (read(fd, raw, 6) < 6) {
            perror("read");
            retry++;
            if (retry >= 10) {
                retry = 0;
                continue;
            }
            usleep(10000);
            continue;
        }

        // Calculate CRC
        crc = raw[5];
        for (int i = 0; i < 6; i++) {
            crc ^= raw[i];
        }
        for (int i = 0; i < 8; i++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
            if (crc & 0x80) {
                crc ^= 0x31;
            }
        }

        // Validate CRC
        if (crc != raw[5]) {
            printf("Invalid CRC\n");
            retry++;
            if (retry >= 10) {
                retry = 0;
                continue;
            }
            usleep(10000);
            continue;
        }

        // Calculate temperature and humidity
        float temperature = -45 + 175 * raw[0] / 65535.0;
        float humidity = 100 * raw[2] / 65535.0;

        // Log reading
        time_t now = time(NULL);
        struct timespec now_time;
        clock_gettime(CLOCK_REALTIME, &now_time);
        now_time.tv_sec += now.tv_sec;
        now_time.tv_nsec += now.tv_nsec;
        now_time.tv_nsec += 500000000; // add 500ms
        if (now_time.tv_nsec >= 1000000000) {
            now_time.tv_sec++;
            now_time.tv_nsec -= 1000000000;
        }
        if (now_time.tv_sec > last_log_time.tv_sec) {
            last_log_time = now_time;
            printf("%f %f\n", now_time.tv_sec, now_time.tv_nsec / 1000000000.0);
            printf("%.2f %.2f\n", temperature, humidity);
            fflush(stdout);
        }

        // Wait for the next measurement to complete
        usleep(10000);
    }

    // Clean up
    close(fd);
    gpioTerminate();
    return 0;
}

