#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>

#define I2C_ADDRESS 0x28
#define I2C Bus 1
#define I2C_COMMAND 0x21
#define I2C_READ_DATA 0x96
#define I2C_READ_LENGTH 6
#define I2C_RETRY_ATTEMPTS 3
#define I2C_RETRY_BACKOFF_MULTIPLIER 2
#define I2C_RETRY_BACKOFF_MIN 100
#define I2C_RETRY_BACKOFF_MAX 1000

volatile sig_atomic_t exit = 0;

void i2c_retry(int fd, int attempts, int backoff) {
    if (attempts > 0) {
        if (i2cWriteDevice(fd, I2C_COMMAND, I2C_READ_DATA) < 0) {
            sleep(backoff);
            i2c_retry(fd, attempts - 1, backoff * I2C_RETRY_BACKOFF_MULTIPLIER);
        } else {
            i2cReadDevice(fd, I2C_READ_LENGTH, NULL, I2C_READ_LENGTH, NULL);
        }
    } else {
        close(fd);
    }
}

int main() {
    int i2c_fd = -1;
    int log_fd = -1;
    int retry_attempts = 0;
    int retry_backoff = I2C_RETRY_BACKOFF_MIN;

    gpioInitialise();

    if (gpioOpen(17, PI_INPUT) < 0) {
        printf("Failed to open GPIO 17 for I2C SCL\n");
        gpioTerminate();
        return 1;
    }

    if ((i2c_fd = i2cOpen(I2C Bus, I2C_ADDRESS)) < 0) {
        printf("Failed to open I2C bus 1 at address 0x28\n");
        gpioTerminate();
        return 1;
    }

    if ((log_fd = open("airflow.log", O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        printf("Failed to open log file\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (!exit) {
        if (i2cWriteDevice(i2c_fd, I2C_COMMAND, I2C_READ_DATA) < 0) {
            retry_attempts = 0;
            retry_backoff = I2C_RETRY_BACKOFF_MIN;
        } else {
            retry_attempts = 0;
            retry_backoff = I2C_RETRY_BACKOFF_MIN;
        }

        while (retry_attempts > 0) {
            if (i2cWriteDevice(i2c_fd, I2C_COMMAND, I2C_READ_DATA) < 0) {
                sleep(retry_backoff);
                retry_attempts--;
                retry_backoff *= I2C_RETRY_BACKOFF_MULTIPLIER;
                if (retry_attempts > I2C_RETRY_ATTEMPTS) {
                    retry_attempts = I2C_RETRY_ATTEMPTS;
                    retry_backoff = I2C_RETRY_BACKOFF_MIN;
                }
            } else {
                break;
            }
        }

        if (i2cReadDevice(i2c_fd, I2C_READ_LENGTH, NULL, I2C_READ_LENGTH, NULL) < 0) {
            retry_attempts = 0;
            retry_backoff = I2C_RETRY_BACKOFF_MIN;
        } else {
            uint8_t raw_pressure = i2cReadDevice(i2c_fd, I2C_READ_LENGTH, NULL, I2C_READ_LENGTH, NULL)[0];
            uint8_t raw_temperature = i2cReadDevice(i2c_fd, I2C_READ_LENGTH, NULL, I2C_READ_LENGTH, NULL)[1];
            uint8_t crc = i2cReadDevice(i2c_fd, I2C_READ_LENGTH, NULL, I2C_READ_LENGTH, NULL)[2];
            uint8_t crc_check = (raw_pressure << 8) | raw_temperature;
            if (crc != crc_check) {
                retry_attempts = 0;
                retry_backoff = I2C_RETRY_BACKOFF_MIN;
            } else {
                float pressure_pa = (raw_pressure << 8 | raw_temperature) / 60.0;
                float raw_temperature_c = raw_temperature / 200.0;
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time(NULL));
                fprintf(log_fd, "%s,%f,%f\n", timestamp, pressure_pa, raw_temperature_c);
                fflush(log_fd);
            }
        }

        sleep(0.1);
    }

    close(log_fd);
    i2cClose(i2c_fd);
    gpioClose(17);
    gpioTerminate();

    return 0;
}

