#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>

#define I2C_ADDRESS 0x4A
#define I2C Bus 1
#define MEASUREMENT_COMMAND 0x2C06
#define WAIT_TIME 15
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG "error_log.txt"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C bus
    if (gpioI2COpen(I2C Bus, I2C_ADDRESS) < 0) {
        perror("gpioI2COpen");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return 1;
    }

    // Open log files
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        gpioTerminate();
        return 1;
    }
    FILE *error_log = fopen(ERROR_LOG, "a");
    if (error_log == NULL) {
        perror("fopen");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Issue measurement command
        if (gpioI2CSingleWrite(I2C Bus, MEASUREMENT_COMMAND, 0) < 0) {
            fprintf(error_log, "%s: I2C write failed\n", ctime(&time(NULL)));
            continue;
        }

        // Wait for conversion
        usleep(WAIT_TIME * 1000);

        // Read 3 bytes
        unsigned char raw[3];
        if (gpioI2CRead(I2C Bus, raw, 3) < 0) {
            fprintf(error_log, "%s: I2C read failed\n", ctime(&time(NULL)));
            continue;
        }

        // Validate CRC-8 checksum
        unsigned char crc = raw[2];
        if (crc != (crc = (crc ^ (crc << 1)) & 0xFF) || crc != CRC_INIT) {
            fprintf(error_log, "%s: CRC mismatch\n", ctime(&time(NULL)));
            continue;
        }

        // Convert raw value to degrees Celsius
        float temperature = -45 + 175 * (raw[0] / 65535.0);

        // Log reading
        fprintf(log_file, "%s %f\n", ctime(&time(NULL)), temperature);
    }

    // Clean up
    gpioTerminate();
    fclose(log_file);
    fclose(error_log);
    return 0;
}

void sigint_handler(int sig) {
    // Close I2C bus
    gpioI2CClose(I2C Bus);

    // Close log files
    fclose(LOG_FILE);
    fclose(ERROR_LOG);

    // Exit
    exit(0);
}

