        clock_gettime(CLOCK_MONOTONIC, &start_time);

        // Send measurement command
        if (write(fd, &SENSIRION_COMMAND, 1) < 0) {
            perror("write");
            continue;
        }

        // Wait for 8.5 ms
        usleep(8500);

        // Read measurement
        if (read(fd, raw, SENSIRION_MEASUREMENT_SIZE) < SENSIRION_MEASUREMENT_SIZE) {
            perror("read");
            continue;
        }

        // Calculate CRC
        crc = 0xFF;
        for (int i = 0; i < SENSIRION_MEASUREMENT_SIZE; i++) {
            crc = (crc ^ raw[i]) ^ (crc << 1);
            crc &= 0xFF;
        }

        // Validate CRC
        if (crc != raw[SENSIRION_MEASUREMENT_SIZE - 1]) {
            printf("CRC mismatch: expected %02x, got %02x\n", SENSIRION_INIT, raw[SENSIRION_MEASUREMENT_SIZE - 1]);
            continue;
        }

        // Convert temperature and humidity
        float temperature = -45 + (raw[0] * 175.0 / 65535.0);
        float humidity = (raw[1] * 100.0 / 65535.0);

        // Log reading
        time_t now = time(NULL);
        struct tm* time_info = localtime(&now);
        char log_string[256];
        strftime(log_string, sizeof(log_string), "%Y-%m-%d %H:%M:%S", time_info);
        printf("%s %f %f\n", log_string, temperature, humidity);

        // Log to file
        FILE* log_file = fopen("sht40_log.txt", "a");
        if (log_file == NULL) {
            perror("fopen");
            continue;
        }
        fprintf(log_file, "%f %f\n", temperature, humidity);
        fclose(log_file);
    }

    // Clean up
    close(fd);
    return 0;
}

void sigint_handler(int sig) {
    sigint_received = 1;
}
