#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <sys/select.h>
#include <termios.h>
#include <unistd.h>

#define BUFFER_SIZE 60
#define I2C_ADDRESS 0x40
#define I2C Bus 1
#define GPIO_PIN 18
#define TEMPERATURE_COMMAND 0xE3
#define HUMIDITY_COMMAND 0xE5
#define TEMPERATURE_OFFSET 46.85
#define HUMIDITY_OFFSET 6.0
#define TEMPERATURE_HYST 1.0
#define HUMIDITY_HYST 2.0
#define FAN_PIN GPIO_PIN
#define FAN_STATE_ON 1
#define FAN_STATE_OFF 0

int main(int argc, char **argv) {
    int i, j;
    int i2c_fd;
    int fan_state = FAN_STATE_OFF;
    unsigned char raw_temperature, raw_humidity;
    unsigned int temperature, humidity;
    struct timespec start_time;
    struct timespec end_time;
    struct timespec sleep_time;
    struct sigaction sa;
    struct sigaction old_sa;
    struct termios old_termios;
    struct termios new_termios;
    unsigned char buffer[BUFFER_SIZE][2];
    int buffer_index = 0;
    int retry_count = 0;
    int retry_limit = 3;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up I2C
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up fan pin
    if (gpioMode(FAN_PIN, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(FAN_PIN, FAN_STATE_ON) < 0) {
        perror("gpioWrite");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, &old_sa) < 0) {
        perror("sigaction");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up terminal
    tcgetattr(STDIN_FILENO, &old_termios);
    new_termios = old_termios;
    new_termios.c_lflag &= ~ICANON;
    new_termios.c_lflag &= ~ECHO;
    new_termios.c_cc[VMIN] = 1;
    new_termios.c_cc[VTIME] = 0;
    if (tcsetattr(STDIN_FILENO, TCSANOW, &new_termios) < 0) {
        perror("tcsetattr");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read temperature and humidity
        if (i2c_read(i2c_fd, &raw_temperature, 1, TEMPERATURE_COMMAND) < 0) {
            if (retry_count < retry_limit) {
                retry_count++;
                usleep(10000);
                continue;
            } else {
                printf("Temperature read failed\n");
                break;
            }
        }

        if (i2c_read(i2c_fd, &raw_humidity, 1, HUMIDITY_COMMAND) < 0) {
            if (retry_count < retry_limit) {
                retry_count++;
                usleep(10000);
                continue;
            } else {
                printf("Humidity read failed\n");
                break;
            }
        }

        // Convert raw values
        temperature = (175.72 * raw_temperature) / 65536.0 - TEMPERATURE_OFFSET;
        humidity = (125.0 * raw_humidity) / 65536.0 - HUMIDITY_OFFSET;

        // Log reading
        struct timespec now;
        clock_gettime(CLOCK_REALTIME, &now);
        if (buffer_index >= BUFFER_SIZE) {
            buffer_index = 0;
        }
        buffer[buffer_index][0] = now.tv_sec;
        buffer[buffer_index][1] = temperature;
        buffer[buffer_index + 1][0] = now.tv_sec;
        buffer[buffer_index + 1][1] = humidity;
        buffer_index += 2;

        // Print reading
        printf("%u %f %f\n", buffer[buffer_index - 2][0], buffer[buffer_index - 2][1], buffer[buffer_index - 1][1]);

        // Update fan state
        if (temperature > 28.0 + TEMPERATURE_HYST) {
            fan_state = FAN_STATE_ON;
        } else if (temperature < 27.0 - TEMPERATURE_HYST) {
            fan_state = FAN_STATE_OFF;
        }

        // Set fan state
        if (fan_state == FAN_STATE_ON) {
            if (gpioWrite(FAN_PIN, FAN_STATE_ON) < 0) {
                perror("gpioWrite");
                break;
            }
        } else {
            if (gpioWrite(FAN_PIN, FAN_STATE_OFF) < 0) {
                perror("gpioWrite");
                break;
            }
        }

        // Sleep
        sleep_time.tv_sec = 2;
        sleep_time.tv_nsec = 0;
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    gpioTerminate();
    close(i2c_fd);
    return 0;
}

void sigint_handler(int sig) {
    // Turn off fan
    if (gpioWrite(FAN_PIN, FAN_STATE_OFF) < 0) {
        perror("gpioWrite");
    }

    // Close I2C
    close(i2c_fd);

    // Exit
    exit(0);
}

