#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>
#include <signal.h>

#define I2C_ADDRESS 0x62
#define I2C_CLOCK 100000
#define I2C_SPEED 100000
#define CRC_POLYNOM 0x31
#define CRC_INIT 0xFF
#define CRC_CHECKSUM 0x3F
#define MEASUREMENT_COMMAND 0x21B1
#define READ_DATA 0xEC05
#define DATA_READY 0xE4B8
#define STOP_MEASUREMENT 0x3F86

int main(int argc, char **argv) {
    int i2c_fd;
    int ret;
    int retry = 0;
    int retry_count = 0;
    int log_fd;
    struct sigaction sa;
    struct sigaction old_sa;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    // Set up signal handler for SIGINT
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, &old_sa) < 0) {
        fprintf(stderr, "Failed to set up signal handler\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus 1
    if ((i2c_fd = pigpioOpen(1, PI_I2C, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return 1;
    }

    // Set I2C clock speed
    if (pigpioSetI2CClock(i2c_fd, I2C_SPEED) < 0) {
        fprintf(stderr, "Failed to set I2C clock speed\n");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Send Start Periodic Measurement command
    if (pigpioWrite(i2c_fd, MEASUREMENT_COMMAND, 1) < 0) {
        fprintf(stderr, "Failed to send Start Periodic Measurement command\n");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Wait for 1 second before reading data
    sleep(1);

    // Poll for data-ready flag
    while (1) {
        if (pigpioRead(i2c_fd, DATA_READY, 1) < 0) {
            fprintf(stderr, "Failed to read data-ready flag\n");
            pigpioClose(i2c_fd);
            gpioTerminate();
            return 1;
        }
        if (pigpioRead(i2c_fd, DATA_READY, 1) & 0x80) {
            break;
        }
        usleep(10000);
    }

    // Read 9 bytes (6 data bytes plus 3 CRC bytes)
    if (pigpioRead(i2c_fd, READ_DATA, 9) < 0) {
        fprintf(stderr, "Failed to read data\n");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

