        printf("pigpioI2CWrite failed\n");
        exit(1);
    }
    while (pigpioI2CRead(I2C_ADDRESS, 0x00) & (1 << 0) == 0) {
        // wait for data ready
    }
    if (pigpioI2CRead(I2C_ADDRESS, 0x00) & (1 << 0) == 0) {
        printf("Sensor not found\n");
        exit(1);
    }
    if (pigpioI2CRead(I2C_ADDRESS, 0xEC05) < 0) {
        printf("pigpioI2CRead failed\n");
        exit(1);
    }
    for (int i = 0; i < I2C_DATA_SIZE; i += 2) {
        uint16_t data = pigpioI2CRead(I2C_ADDRESS, 0xEC05);
        uint8_t crc = pigpioI2CRead(I2C_ADDRESS, 0xEC05 + I2C_CRC_SIZE);
        uint8_t checksum = (crc >> 1) ^ (crc & 1);
        if (checksum != I2C_CHECKSUM) {
