        buffer[buffer_index++] = co2;
        if (buffer_index >= BUFFER_SIZE) {
            buffer_index = 0;
        }
    }
    if (pigpioI2CWrite(I2C_ADDRESS, 0x3F86) < 0) {
        printf("pigpioI2CWrite failed\n");
        exit(1);
    }
}

