uint8_t calculate_crc(uint8_t *data, uint8_t length) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < length; i++) {
        crc = (crc >> 1);
        if (crc & 0x80) {
            crc = (crc ^ 0x31);
        }
        crc = (crc ^ data[i]);
    }
    return crc;
}

