#define TEMPERATURE_OFFSET 0x01
#define SCALE_FACTOR_OFFSET 0x02
#define CRC_OFFSET 0x03

#define PRESSURE_SIZE 4
#define TEMPERATURE_SIZE 2
#define SCALE_FACTOR_SIZE 1

#define CSV_FILE "airflow.csv"

int main(int argc, char **argv) {
    int i2c_fd = -1;
    int gpio_fd = -1;
    struct sigaction sa;
    struct sigaction sa_int, sa_term;
    FILE *csv_file = NULL;

    // Initialize signal handlers
    sa.sa_handler = sigint_handler;
    sa_int.sa_handler = sigint_handler;
    sa_term.sa_handler = sigterm_handler;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa_term, NULL);
    sigaction(SIGBUS, &sa_int, NULL);

    // Open I2C file descriptor
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C file descriptor");
        return 1;
    }

    // Set I2C address and mode
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_BUS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        // Send continuous measurement command
        if (write(i2c_fd, &I2C_COMMAND, sizeof(I2C_COMMAND)) < 0) {
            perror("Failed to send I2C command");
            break;
        }

        // Wait for conversion time
        usleep(45000);

        // Read 9 bytes containing pressure, temperature, and scale factor
        char buffer[9];
        if (read(i2c_fd, buffer, 9) < 9) {
            perror("Failed to read sensor data");
            break;
        }

        // Validate CRC-8 checksums
        uint8_t crc8_pressure = (buffer[PRESSURE_SIZE + TEMPERATURE_SIZE] & 0xFF);
        uint8_t crc8_temperature = (buffer[PRESSURE_SIZE + TEMPERATURE_SIZE + SCALE_FACTOR_SIZE] & 0xFF);
        if ((crc8_pressure != (crc8_temperature ^ (crc8_temperature << 1)) ^ CRC_8_POLYNOMINAL) ||
            (crc8_temperature != (crc8_temperature ^ (crc8_temperature << 1)) ^ CRC_8_POLYNOMINAL)) {
            perror("Invalid CRC-8 checksum");
            break;
        }

        // Convert raw data to pressure and temperature
        float pressure = (buffer[PRESSURE_OFFSET] << 8) | buffer[PRESSURE_SIZE];
        float temperature = (buffer[TEMPERATURE_OFFSET] << 8) | buffer[TEMPERATURE_SIZE];

        // Log data to CSV file
        fprintf(csv_file, "%f,%f\n", time(NULL), pressure);
        fflush(csv_file);
    }

    // Close I2C file descriptor and CSV file
    close(i2c_fd);
    fclose(csv_file);

    // Restore signal handlers
    sigaction(SIGINT, NULL, &sa);
    sigaction(SIGTERM, NULL, &sa);

    return 0;
}

void sigint_handler(int sig) {
    // Graceful shutdown
    close(i2c_fd);
    fclose(csv_file);
    exit(0);
}

void sigterm_handler(int sig) {
    // Graceful shutdown
    close(i2c_fd);
    fclose(csv_file);
    exit(0);
}

void sigbus_handler(int sig) {
    // Handle bus error
    perror("Bus error");
    exit(1);
}

