#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>

#define I2C_ADDRESS 0x44
#define I2C_ADDRESS_MASK 0x01
#define I2C_DATA_SIZE 6
#define CRC_POLYNOMINAL 0x31
#define CRC_INIT_VALUE 0xFF

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up I2C
    if (gpioSetMode(1, PI_MODE PullUp) < 0) {
        fprintf(stderr, "Failed to set I2C mode\n");
        gpioTerminate();
        return 1;
    }

    // Set up I2C clock stretching
    if (gpioSetI2CBit(1, PI_I2C_CLOCK_STRETCHING, 0) < 0) {
        fprintf(stderr, "Failed to set I2C clock stretching\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C handle
    int fd = pigpioOpen(1, PI_I2C, 0);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        gpioTerminate();
        return 1;
    }

    // Set I2C address
    if (pigpioWrite(fd, I2C_ADDRESS, 0) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        pigpioClose(fd);
        gpioTerminate();
        return 1;
    }

    // Set I2C address mask
    if (pigpioWrite(fd, I2C_ADDRESS_MASK, 0) < 0) {
        fprintf(stderr, "Failed to set I2C address mask\n");
        pigpioClose(fd);
        gpioTerminate();
        return 1;
    }

    // Send single-shot high-repeatability command
    if (pigpioWrite(fd, 0x2400, 0) < 0) {
        fprintf(stderr, "Failed to send command\n");
        pigpioClose(fd);
        gpioTerminate();
        return 1;
    }

    // Wait for 15 ms
    usleep(15000);

    // Read 6 bytes
    unsigned char raw[I2C_DATA_SIZE];
    if (pigpioRead(fd, raw, I2C_DATA_SIZE) < 0) {
        fprintf(stderr, "Failed to read data\n");
        pigpioClose(fd);
        gpioTerminate();
        return 1;
    }

    // Validate CRC-8 checksums
    unsigned char crc8 = (raw[I2C_DATA_SIZE - 1] << 1) | raw[I2C_DATA_SIZE - 2];
    if (crc8 != (crc8 ^ (crc8 >> 1))) {
        fprintf(stderr, "Invalid CRC-8 checksum\n");
        pigpioClose(fd);
        gpioTerminate();
        return 1;
    }

    // Convert raw values
    float temperature = -45 + 175 * raw[0] / 65535.0f;
    float humidity = 100 * raw[1] / 65535.0f;

    // Log reading
    time_t now = time(NULL);
    struct tm *ltm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", ltm);
    FILE *fp = fopen("environment.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file\n");
        pigpioClose(fd);
        gpioTerminate();
        return 1;
    }
    if (fputs(timestamp, fp) == EOF) {
        fprintf(stderr, "Failed to write to file\n");
        fclose(fp);
        pigpioClose(fd);
        gpioTerminate();
        return 1;
    }
    if (fputs(",", fp) == EOF) {
        fprintf(stderr, "Failed to write to file\n");
        fclose(fp);
        pigpioClose(fd);
        gpioTerminate();
        return 1;
    }
    if (fputs("temperature_c", fp) == EOF) {
        fprintf(stderr, "Failed to write to file\n");
        fclose(fp);
        pigpioClose(fd);
        gpioTerminate();
        return 1;
    }
    if (fputs(",", fp) == EOF) {
        fprintf(stderr, "Failed to write to file\n");
        fclose(fp);
        pigpioClose(fd);
        gpioTerminate();
        return 1;
    }
    if (fputs(fprintf(fp, "%.2f", temperature), fp) == EOF) {
        fprintf(stderr, "Failed to write to file\n");
        fclose(fp);
        pigpioClose(fd);
        gpioTerminate();
        return 1;
    }
    if (fputs(",", fp) == EOF) {
        fprintf(stderr, "Failed to write to file\n");
        fclose(fp);
        pigpioClose(fd);
        gpioTerminate();
        return 1;
    }
    if (fputs("humidity_pct", fp) == EOF) {
        fprintf(stderr, "Failed to write to file\n");
        fclose(fp);
        pigpioClose(fd);
        gpioTerminate();
        return 1;
    }
    if (fputs(",", fp) == EOF) {
        fprintf(stderr, "Failed to write to file\n");
        fclose(fp);
        pigpioClose(fd);
        gpioTerminate();
        return 1;
    }
    if (fputs(fprintf(fp, "%.2f", humidity), fp) == EOF) {
        fprintf(stderr, "Failed to write to file\n");
        fclose(fp);
        pigpioClose(fd);
        gpioTerminate();
        return 1;
    }
    if (fputs("\n", fp) == EOF) {
        fprintf(stderr, "Failed to write to file\n");
        fclose(fp);
        pigpioClose(fd);
        gpioTerminate();
        return 1;
    }
    fclose(fp);

    // Sleep for 5 seconds before next reading
    sleep(5);

    // Clean up
    pigpioClose(fd);
    gpioTerminate();

    return 0;
}

