        pigpioClose(fd);
        gpioTerminate();
        return 1;
    }
    if (fputs(fprintf(fp, "%.2f", humidity), fp) == EOF) {
        fprintf(stderr, "Failed to write to file\n");
        fclose(fp);
        pigpioClose(fd);
        gpioTerminate();
        return 1;
    }
    if (fputs("\n", fp) == EOF) {
        fprintf(stderr, "Failed to write to file\n");
        fclose(fp);
        pigpioClose(fd);
        gpioTerminate();
        return 1;
    }
    fclose(fp);

    // Sleep for 5 seconds before next reading
    sleep(5);

    // Clean up
    pigpioClose(fd);
    gpioTerminate();

    return 0;
}
