            perror("read");
            continue;
        }
        if (read(fd, &raw_humidity + 1, 1) == -1) {
            perror("read");
            continue;
        }
        if (read(fd, &crc, 1) == -1) {
            perror("read");
            continue;
        }
        if (crc != CRC_MAX) {
            printf("CRC error\n");
            continue;
