            perror("read");
            continue;
        }
        if (crc != CRC_MAX) {
            printf("CRC error\n");
            continue;
        }
        temperature = (uint16_t) ((raw_temperature & 0xFF) << 8) | (raw_temperature >> 8);
        temperature = 175.72 * temperature / 65536.0 - 46.85;

        // Log to CSV file
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&start));
        FILE *fp = fopen(CSV_FILE, "a");
        if (fp == NULL) {
            perror("fopen");
            continue;
        }
        fprintf(fp, "%s,%f,%f\n", timestamp, temperature, humidity);
        fclose(fp);

        // Sleep for 5 seconds
        clock_gettime(&start, &end);
        interval.tv_sec = end.tv_sec - start.tv_sec;
        interval.tv_nsec = end.tv_nsec - start.tv_nsec;
        if (interval.tv_nsec < 0) {
            interval.tv_sec++;
            interval.tv_nsec += 1000000000;
        }
        nanosleep(&interval, NULL);
    }

    // Close I2C file descriptor
    if (close(fd) == -1) {
        perror("close");
        return 1;
    }

    return 0;
}

void sigint_handler(int sig) {
    sigint_received = 1;
    exit(0);
}

void sigterm_handler(int sig) {
    sigterm_received = 1;
    close(0);
    close(1);
    close(2);
    exit(0);
