#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>
#include <signal.h>

#define I2C_ADDRESS 0x25
#define I2C Bus 1
#define SCALE_FACTOR 60.0
#define CRC_POLYNOM 0x31
#define MEASUREMENT_COMMAND 0x3603
#define MEASUREMENT_LENGTH 9
#define LOG_FILE "pressure_log.txt"

int main(int argc, char **argv) {
    pigpio *gpio = pigpio_get();
    if (!gpio) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return 1;
    }

    if (gpio_i2c_open(gpio, I2C Bus, I2C_ADDRESS, 1000) != 0) {
        syslog(LOG_ERR, "Failed to open I2C bus");
        pigpio_close(gpio);
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file");
        pigpio_close(gpio);
        return 1;
    }

    while (1) {
        if (gpio_i2c_write(gpio, I2C Bus, I2C_ADDRESS, MEASUREMENT_COMMAND) != 0) {
            syslog(LOG_ERR, "Failed to write measurement command");
            break;
        }

        usleep(45 * 1000);

        unsigned char buffer[MEASUREMENT_LENGTH];
        if (gpio_i2c_read(gpio, I2C Bus, I2C_ADDRESS, buffer, MEASUREMENT_LENGTH) != MEASUREMENT_LENGTH) {
            syslog(LOG_ERR, "Failed to read measurement data");
            break;
        }

        unsigned char crc = buffer[MEASUREMENT_LENGTH - 1];
        unsigned char crc_calculated = 0;
        for (int i = 0; i < MEASUREMENT_LENGTH - 1; i++) {
            crc_calculated = (crc_calculated << 1) ^ (crc_calculated >> 7) ^ buffer[i];
        }
        if (crc_calculated != crc) {
            syslog(LOG_ERR, "CRC mismatch");
            break;
        }

        double pressure = (buffer[0] * 256 + buffer[1]) * SCALE_FACTOR;
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s %f Pa\n", timestamp, pressure);
    }

    fclose(log_file);
    pigpio_close(gpio);
    return 0;
}

