#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>

#define I2C_ADDRESS 0x28
#define I2C Bus 1
#define GPIO_PIN 18
#define PWM_FREQ 25000
#define PWM_MAX 100
#define PWM_MIN 0
#define SLPM_0 0
#define SLPM_10 14745
#define SLPM_COUNT 1638
#define SAMPLE_INTERVAL 100
#define LOG_FILE "flow_log.txt"

int main(int argc, char **argv) {
    int i2c_fd, gpio_fd;
    int status;
    unsigned char i2c_buf[2];
    unsigned int flow_rate;
    unsigned int pwm_duty;
    struct sigaction sa;
    FILE *log_file;

    // Initialize pigpio
    if (gpio_init() < 0) {
        perror("gpio_init");
        return 1;
    }

    // Set up I2C
    if ((status = gpio_export(I2C Bus, GPIO_PIN) < 0) || (status = gpio_firmware_set_mode(I2C Bus, GPIO_PIN, PI_MODE_INPUT) < 0)) {
        perror("gpio_export");
        gpio_unexport(I2C Bus, GPIO_PIN);
        gpio_firmware_set_mode(I2C Bus, GPIO_PIN, PI_MODE_INPUT);
        return 1;
    }

    // Set up I2C
    if ((status = i2c_open(I2C Bus, I2C_ADDRESS, &i2c_fd) < 0) || (status = i2c_set_clock_frequency(i2c_fd, 100000) < 0)) {
        perror("i2c_open");
        i2c_close(i2c_fd);
        gpio_firmware_set_mode(I2C Bus, GPIO_PIN, PI_MODE_INPUT);
        return 1;
    }

    // Set up PWM
    if ((status = gpio_mode(GPIO_PIN, PI_MODE_OUTPUT) < 0) || (status = gpio_firmware_set_mode(GPIO_PIN, PI_MODE Hardware_PWM) < 0)) {
        perror("gpio_mode");
        i2c_close(i2c_fd);
        gpio_firmware_set_mode(I2C Bus, GPIO_PIN, PI_MODE_INPUT);
        return 1;
    }

    // Set up PWM
    if ((status = pwm_set_frequency(GPIO_PIN, PWM_FREQ) < 0) || (status = pwm_set_duty(GPIO_PIN, PWM_MAX) < 0)) {
        perror("pwm_set_frequency");
        pwm_set_duty(GPIO_PIN, PWM_MIN);
        gpio_firmware_set_mode(I2C Bus, GPIO_PIN, PI_MODE_INPUT);
        return 1;
    }

    // Set up signal handlers
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    sa.sa_handler = sigterm_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    // Open log file
    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        perror("fopen");
        return 1;
    }

    while (1) {
        // Read sensor data
        if ((status = i2c_read(i2c_fd, i2c_buf, 2) < 0) || (status = i2c_get_byte(i2c_fd, i2c_buf[0], 1) < 0)) {
            perror("i2c_read");
            i2c_close(i2c_fd);
            gpio_firmware_set_mode(I2C Bus, GPIO_PIN, PI_MODE_INPUT);
            fclose(log_file);
            return 1;
        }

        // Mask off status bits and shift right
        flow_rate = (i2c_buf[0] & 0x03) >> 2;

        // Convert flow rate to PWM duty cycle
        pwm_duty = (flow_rate * PWM_MAX / SLPM_10) + PWM_MIN;

        // Set PWM duty cycle
        if (pwm_set_duty(GPIO_PIN, pwm_duty) < 0) {
            perror("pwm_set_duty");
            i2c_close(i2c_fd);
            gpio_firmware_set_mode(I2C Bus, GPIO_PIN, PI_MODE_INPUT);
            fclose(log_file);
            return 1;
        }

        // Log reading
        fprintf(log_file, "%d,%d\n", (unsigned long)time(NULL), flow_rate);

        // Sleep
        usleep(SAMPLE_INTERVAL * 1000);
    }

    // Clean up
    pwm_set_duty(GPIO_PIN, PWM_MIN);
    i2c_close(i2c_fd);
    gpio_firmware_set_mode(I2C Bus, GPIO_PIN, PI_MODE_INPUT);
    fclose(log_file);
    gpio_unexport(I2C Bus, GPIO_PIN);
    gpio_firmware_set_mode(I2C Bus, GPIO_PIN, PI_MODE_INPUT);
    gpio_cleanup();
    exit(0);
}

void sigint_handler(int sig) {
    // Turn off fan
    pwm_set_duty(GPIO_PIN, PWM_MIN);
    // Close I2C
    i2c_close(i2c_fd);
    // Flush and close log file
    fclose(log_file);
    // Terminate pigpio
    gpio_firmware_set_mode(I2C Bus, GPIO_PIN, PI_MODE_INPUT);
    gpio_cleanup();
    exit(0);
}

void sigterm_handler(int sig) {
    // Turn off fan
    pwm_set_duty(GPIO_PIN, PWM_MIN);
    // Close I2C
    i2c_close(i2c_fd);
    // Flush and close log file
    fclose(log_file);
    // Terminate pigpio
    gpio_firmware_set_mode(I2C Bus, GPIO_PIN, PI_MODE_INPUT);
    gpio_cleanup();
    exit(0);
}

