#define I2C_ADDRESS 0x5D
#define I2C_ADDRESS2 0x5E
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x10
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C
#define BLOCK_DATA_UPDATE 0xB0
#define OUTPUT_RATE 10
#define ACTIVE_MODE 0x01
#define PRESSURE_FORMAT 4096.0
#define TEMPERATURE_FORMAT 480.0

volatile sig_atomic_t exit = 0;

int main() {
    int i;
    int i2c_fd;
    int pressure;
    int temperature;
    struct timespec ts;
    struct tm *timeinfo;
    FILE *log_file;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(1);
    }

    // Open I2C
    if ((i2c_fd = i2cOpen(I2C_ADDRESS, I2C_ADDRESS2, 100000)) < 0) {
        perror("i2cOpen");
        exit(1);
    }

    // Read WHO_AM_I register
    if (i2cWrite(i2c_fd, WHO_AM_I, 1) < 0) {
        syslog(LOG_ERR, "Failed to write to WHO_AM_I register");
        i2cClose(i2c_fd);
        gpioTerminate();
        exit(1);
    }
    if (i2cRead(i2c_fd, WHO_AM_I, 1, &pressure) < 0) {
        syslog(LOG_ERR, "Failed to read WHO_AM_I register");
        i2cClose(i2c_fd);
        gpioTerminate();
        exit(1);
    }
    if (pressure != 0xB1) {
        syslog(LOG_ERR, "Invalid WHO_AM_I register value: %d", pressure);
        i2cClose(i2c_fd);
        gpioTerminate();
        exit(1);
    }

    // Configure CTRL_REG1
    if (i2cWrite(i2c_fd, CTRL_REG1, 1) < 0) {
        syslog(LOG_ERR, "Failed to write to CTRL_REG1 register");
        i2cClose(i2c_fd);
        gpioTerminate();
        exit(1);
    }
    if (i2cWrite(i2c_fd, CTRL_REG1, BLOCK_DATA_UPDATE | OUTPUT_RATE | ACTIVE_MODE) < 0) {
        syslog(LOG_ERR, "Failed to write to CTRL_REG1 register");
        i2cClose(i2c_fd);
        gpioTerminate();
        exit(1);
    }

    // Read pressure and temperature
    while (!exit) {
        // Read pressure
        if (i2cRead(i2c_fd, PRESS_OUT_XL, 2, &pressure) < 0) {
            syslog(LOG_ERR, "Failed to read pressure register");
            continue;
        }
        pressure = (pressure << 16) | i2cRead(i2c_fd, PRESS_OUT_L, 1);
        pressure /= PRESSURE_FORMAT;
        if (pressure < 0) {
            pressure += 0x10000;
        }

        // Read temperature
        if (i2cRead(i2c_fd, TEMP_OUT_L, 2, &temperature) < 0) {
            syslog(LOG_ERR, "Failed to read temperature register");
            continue;
        }
        temperature = (temperature << 8) | i2cRead(i2c_fd, TEMP_OUT_H, 1);
        temperature = 42.5 + (temperature / TEMPERATURE_FORMAT);

        // Log data
        timeinfo = localtime(&ts);
        strftime(log_file, 100, "%Y-%m-%d %H:%M:%S, Pressure: %.2f hPa, Temperature: %.2f °C", timeinfo, pressure, temperature);
        if (fputs(log_file, stdout) < 0) {
            syslog(LOG_ERR, "Failed to write to stdout");
        }
        if (fwrite(log_file, 1, strlen(log_file), "\n") < 0) {
            syslog(LOG_ERR, "Failed to write to log file");
        }
        if (fclose(log_file) < 0) {
            syslog(LOG_ERR, "Failed to close log file");
        }

        // Delay for 1 second
        gpioDelay(1000);

        // Check for SIGINT
        if (killpg(0, SIGINT) == 0) {
            exit = 1;
        }
    }

    // Close I2C
    i2cClose(i2c_fd);

    // Close log file
    if ((log_file = fopen("environmental_data.txt", "a")) == NULL) {
        syslog(LOG_ERR, "Failed to open log file");
    }
    if (fclose(log_file) < 0) {
        syslog(LOG_ERR, "Failed to close log file");
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

