#include <unistd.h>
#include <time.h>

#define BUFFER_SIZE 10
#define LED_GPIO 17
#define I2C_ADDRESS 0x48
#define I2C_REG 0x00
#define I2C Bus 1

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio\n");
        return 1;
    }

    // Set up I2C bus
    if (gpioI2COpen(I2C Bus, I2C_ADDRESS) < 0) {
        printf("Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set up LED pin
    if (gpioMode(LED_GPIO, GPIO_MODE_OUTPUT) < 0) {
        printf("Failed to set up LED pin\n");
        gpioI2CClose(I2C Bus);
        gpioTerminate();
        return 1;
    }

    // Set up LED pin as output
    if (gpioWrite(LED_GPIO, 1) < 0) {
        printf("Failed to set up LED pin\n");
        gpioI2CClose(I2C Bus);
        gpioTerminate();
        return 1;
    }

    // Create a circular buffer to store temperature readings
    int buffer[BUFFER_SIZE];
    int bufferIndex = 0;

    // Create a running average
    double runningAverage = 0.0;

    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = sigintHandler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        printf("Failed to install signal handler\n");
        gpioI2CClose(I2C Bus);
        gpioTerminate();
        return 1;
    }
    sa.sa_handler = sigtermHandler;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        printf("Failed to install signal handler\n");
        gpioI2CClose(I2C Bus);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read temperature from STLM75
        unsigned char tempData[2];
        if (gpioI2CReadWordData(I2C Bus, I2C_ADDRESS, I2C_REG, tempData, 2) < 0) {
            continue;
        }

        // Swap bytes and right-shift to get temperature
        int temp = (tempData[1] << 7) | (tempData[0] >> 7);
        temp >>= 7;

        // Store temperature in buffer
        if (bufferIndex >= BUFFER_SIZE) {
            bufferIndex = 0;
        }
        buffer[bufferIndex] = temp;
        runningAverage = (runningAverage * (BUFFER_SIZE - 1) + temp) / BUFFER_SIZE;

        // Turn on LED if average temperature exceeds 28.0 °C
        if (runningAverage > 28.0) {
            gpioWrite(LED_GPIO, 1);
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    gpioI2CClose(I2C Bus);
    gpioTerminate();
    return 0;
}

void sigintHandler(int sig) {
    printf("Received SIGINT\n");
    gpioWrite(LED_GPIO, 0);
    gpioI2CClose(I2C Bus);
    gpioTerminate();
    exit(0);
}

void sigtermHandler(int sig) {
    printf("Received SIGTERM\n");
    gpioWrite(LED_GPIO, 0);
    gpioI2CClose(I2C Bus);
    gpioTerminate();
    exit(0);
}

