#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <sys/statvfs.h>

#define I2C_ADDRESS 0x61
#define I2C_BUS 1
#define MEASUREMENT_INTERVAL 2000 // 2 seconds
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT_VALUE 0xFF
#define CRC_MAX_SIZE 18
#define CRC_MAX_VALUE 0xFF

#define SCD30_COMMAND_READ_DATA 0x0300
#define SCD30_COMMAND_READ_DATA_READY 0x0202
#define SCD30_COMMAND_WRITE_DATA 0x0301
#define SCD30_COMMAND_WRITE_DATA_READY 0x0201

#define SCD30_MEASUREMENT_INTERVAL 2
#define SCD30_AMBIENT_PRESS_COMP 0

int main(int argc, char *argv[]) {
    int i, j;
    int i2c_fd;
    int gpio_fd;
    int gpio_pin;
    int gpio_level;
    int ret;
    struct sigaction sa;
    struct sigaction sa_int;
    struct sigaction sa_term;
    struct stat sb;
    struct statvfs st;
    struct i2c_msg msg[2];
    struct i2c_msg *msg_ptr;
    unsigned char crc;
    unsigned char data[SCD30_CRC_MAX_SIZE];
    unsigned char crc_value[SCD30_CRC_MAX_SIZE];
    time_t t;
    struct timespec ts;
    struct timespec ts_prev;
    struct timespec ts_next;
    char log_file[256];
    char log_line[256];

    // Initialize signal handlers
    sa.sa_handler = sigint_handler;
    sa_int.sa_handler = sigint_handler;
    sa_term.sa_handler = sigterm_handler;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    sigaddset(&sa_int.sa_mask, SIGINT);
    sigaddset(&sa_term.sa_mask, SIGINT);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa_int, NULL);
    sigaction(SIGTERM, &sa_term, NULL);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    // Open I2C bus
    if ((i2c_fd = i2cOpen(I2C_BUS, I2C_ADDRESS)) < 0) {
        fprintf(stderr, "I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    sprintf(log_file, "air_quality.log");
    if ((gpio_fd = open(log_file, O_RDWR | O_CREAT | O_APPEND, 0644)) < 0) {
        fprintf(stderr, "log file open failed\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up I2C message
    msg[0].addr = I2C_ADDRESS;
    msg[0].flags = I2C_MMSG_NO_BLOCK;
    msg[0].len = SCD30_CRC_MAX_SIZE;
    msg[0].data = data;
    msg[0].flags |= I2C_MMSG_WRITE;
    msg[1].addr = I2C_ADDRESS;
    msg[1].flags = I2C_MMSG_NO_BLOCK;
    msg[1].len = SCD30_CRC_MAX_SIZE;
    msg[1].data = crc_value;

    // Set up GPIO pin
    gpio_pin = gpioGetPin(17);
    if (gpio_pin < 0) {
        fprintf(stderr, "GPIO pin not found\n");
        i2cClose(i2c_fd);
        close(gpio_fd);
        gpioTerminate();
        return 1;
    }

    // Set up GPIO level
    gpio_level = 0;
    if (gpioWrite(gpio_pin, gpio_level) < 0) {
        fprintf(stderr, "GPIO write failed\n");
        i2cClose(i2c_fd);
        close(gpio_fd);
        gpioTerminate();
        return 1;
    }

    // Start continuous measurement
    while (1) {
        // Poll data-ready flag
        if (i2cReadDevice(i2c_fd, SCD30_COMMAND_READ_DATA_READY, 1, 0, 1000) < 0) {
            fprintf(stderr, "I2C read failed\n");
            continue;
        }

        // Read measurement
        if (i2cReadDevice(i2c_fd, SCD30_COMMAND_READ_DATA, 1, 0, 1000) < 0) {
            fprintf(stderr, "I2C read failed\n");
            continue;
        }

        // Read CRC
