            fprintf(stderr, "I2C read failed\n");
            continue;
        }

        // Calculate CRC
        crc = 0;
        for (i = 0; i < SCD30_CRC_MAX_SIZE; i++) {
            crc = crc ^ crc_value[i];
            for (j = 0; j < 8; j++) {
                if (crc & 0x80) {
