                } else {
                    crc <<= 1;
                }
            }
        }

        // Check CRC
        if (crc != CRC_INIT_VALUE) {
            fprintf(stderr, "CRC mismatch\n");
            continue;
        }

        // Read CO2, temperature, and humidity
        for (i = 0; i < SCD30_CRC_MAX_SIZE - 3; i++) {
            data[i] = i2cReadDevice(i2c_fd, SCD30_COMMAND_READ_DATA, 1, 0, 1000)[i];
        }

        // Calculate CO2, temperature, and humidity
        unsigned char co2 = data[0];
        unsigned char temperature = data[1];
        unsigned char humidity = data[2];

        // Log data
        t = time(NULL);
        ts.tv_sec = t;
        ts.tv_nsec = 0;
        ts_prev.tv_sec = t;
        ts_prev.tv_nsec = 0;
        ts_next.tv_sec = t + MEASUREMENT_INTERVAL;
        ts_next.tv_nsec = 0;
        strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S%z", localtime(&ts));
        sprintf(log_line + strlen(log_line), ",%d,%d,%d", co2, temperature, humidity);
