            fprintf(stderr, "GPIO write failed\n");
            continue;
        }

        // Sleep for measurement interval
        nanosleep(&ts_next, &ts_prev);
    }

    // Clean up
    close(gpio_fd);
    i2cClose(i2c_fd);
    gpioTerminate();

    return 0;
}

void sigint_handler(int sig) {
    // Stop measurement
    gpioWrite(gpio_pin, 0);
    close(gpio_fd);
    i2cClose(i2c_fd);
    gpioTerminate();
    exit(0);
}

