#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

#define I2C_ADDRESS 0x25
#define I2C_ADDRESS_MASK 0x00
#define I2C_DATA_SIZE 3
#define I2C_DATA_OFFSET 0
#define I2C_DATA_SIZE_2 9
#define I2C_DATA_OFFSET_2 0
#define I2C_COMMAND 0x3615
#define I2C_COMMAND_MASK 0xFF
#define I2C_COMMAND_OFFSET 0
#define I2C_DATA_OFFSET_2 0
#define CRC_8_POLYNOMIAL 0x31
#define CRC_8_INIT_VALUE 0xFF

int main(int argc, char **argv) {
    int i, j;
    int gpio_fd;
    int i2c_fd;
    int8_t crc8;
    int8_t raw_pressure, raw_temperature;
    float pressure, temperature;
    float scale_factor_pressure, scale_factor_temperature;
    struct pigpio *gpio;
    struct pigpio_i2c *i2c;

    // Initialize pigpio
    if (gpio_init() < 0) {
        fprintf(stderr, "pigpio_init failed\n");
        return 1;
    }

    // Open I2C bus 1
    gpio_fd = gpio_get_fd(1);
    if (gpio_fd < 0) {
        fprintf(stderr, "gpio_get_fd failed\n");
        gpioTerminate();
        return 1;
    }

    i2c_fd = pigpio_i2c_open(gpio_fd, I2C_ADDRESS, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "pigpio_i2c_open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up I2C bus
    pigpio_i2c_set_bits(i2c_fd, I2C_ADDRESS, I2C_ADDRESS_MASK);
    pigpio_i2c_set_bits(i2c_fd, I2C_ADDRESS, I2C_DATA_SIZE);

    // Send continuous-measurement command
    pigpio_i2c_write(i2c_fd, I2C_COMMAND, I2C_COMMAND_MASK);
    pigpio_usleep(45);

    // Read 9 bytes containing pressure, temperature, and scale factors
    pigpio_i2c_read(i2c_fd, I2C_DATA_OFFSET_2, I2C_DATA_SIZE_2, &raw_pressure, &raw_temperature, &scale_factor_pressure, &scale_factor_temperature);

    // Validate CRC-8
    for (i = 0; i < I2C_DATA_SIZE_2; i += 3) {
        crc8 = pigpio_i2c_read(i2c_fd, I2C_DATA_OFFSET_2 + i, 1, &crc8);
        if (crc8 != CRC_8_INIT_VALUE) {
            fprintf(stderr, "CRC mismatch\n");
            pigpio_i2c_close(i2c_fd);
            gpioTerminate();
            return 1;
        }
    }

    // Convert raw values
    pressure = raw_pressure / scale_factor_pressure;
    temperature = raw_temperature / 200.0;

    // Log results
    printf("%.2f Pa, %.2f C\n", pressure, temperature);

    // Main loop
    while (1) {
        // Send continuous-measurement command
        pigpio_i2c_write(i2c_fd, I2C_COMMAND, I2C_COMMAND_MASK);
        pigpio_usleep(45);

        // Read 9 bytes containing pressure, temperature, and scale factors
        pigpio_i2c_read(i2c_fd, I2C_DATA_OFFSET_2, I2C_DATA_SIZE_2, &raw_pressure, &raw_temperature, &scale_factor_pressure, &scale_factor_temperature);

        // Validate CRC-8
        for (i = 0; i < I2C_DATA_SIZE_2; i += 3) {
            crc8 = pigpio_i2c_read(i2c_fd, I2C_DATA_OFFSET_2 + i, 1, &crc8);
            if (crc8 != CRC_8_INIT_VALUE) {
                fprintf(stderr, "CRC mismatch\n");
                pigpio_i2c_close(i2c_fd);
                gpioTerminate();
                return 1;
            }
        }

        // Convert raw values
        pressure = raw_pressure / scale_factor_pressure;
        temperature = raw_temperature / 200.0;

        // Log results
        printf("%.2f Pa, %.2f C\n", pressure, temperature);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    pigpio_i2c_close(i2c_fd);
    gpioTerminate();

    return 0;
}

