#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/i2c-dev.h>

#define I2C_ADDRESS 0x40
#define I2C_REG_CONFIG 0x02
#define I2C_REG_TEMP 0x00
#define I2C_REG_HUMID 0x01
#define I2C_REG_DATA 0x00
#define I2C_REG_STATUS 0x03
#define I2C_REG_DRDY 0x04

#define I2C_TIMEOUT 20
#define I2C_READ_SIZE 4

void sigint_handler(int sig) {
    close(i2c_fd);
    exit(0);
}

int main() {
    int i2c_fd = -1;
    struct i2c_client *client;
    struct i2c_dev *dev;
    unsigned char config = 0x00 | (1 << 12); // enable combined temperature and humidity measurement
    unsigned char temp[2], humid[2];
    int ret;

    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("open");
        return 1;
    }

    // Set I2C configuration
    ret = ioctl(i2c_fd, I2C_SLAVE, 1);
    if (ret == -1) {
        perror("ioctl");
        close(i2c_fd);
        return 1;
    }

    ret = ioctl(i2c_fd, I2C_SET_REG, I2C_REG_CONFIG, &config);
    if (ret == -1) {
        perror("ioctl");
        close(i2c_fd);
        return 1;
    }

    // Open I2C device
    client = i2c_get_client(i2c_fd);
    if (!client) {
        perror("i2c_get_client");
        close(i2c_fd);
        return 1;
    }

    dev = i2c_get_dev(client, I2C_ADDRESS);
    if (!dev) {
        perror("i2c_get_dev");
        close(i2c_fd);
        i2c_put_client(client);
        return 1;
    }

    while (1) {
        // Read temperature and humidity
        ret = ioctl(i2c_fd, I2C_READ, I2C_REG_DATA, I2C_READ_SIZE, temp, humid);
        if (ret == -1) {
            perror("ioctl");
            continue;
        }

        // Check if the sensor is present
        if (dev->addr != I2C_ADDRESS) {
            printf("Sensor not found\n");
            continue;
        }

        // Convert raw values
        float temp_c = (temp[0] * 165.0 / 65536.0) - 40.0;
        float humid = (humid[0] * 100.0 / 65536.0);

        // Log reading
        printf("Temperature: %.2f C, Humidity: %.2f %\n", temp_c, humid);

        // Wait for 5 seconds before taking the next reading
        sleep(5);
    }

    // Close I2C file descriptor
    close(i2c_fd);
    i2c_put_client(client);
    return 0;
}

