#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/statvfs.h>
#include <errno.h>

#define I2C_ADDRESS 0x40
#define I2C Bus 1
#define GPIO_SDA GPIO_BCM_DHT22_SDA
#define GPIO_SCL GPIO_BCM_DHT22_SCL
#define I2C_TIMEOUT 1000 // 1 second
#define I2C_READ 0x00
#define I2C_WRITE 0x01

int main(int argc, char *argv[]) {
    int fd;
    int i2c_fd;
    int gpio_fd;
    int ret;
    unsigned char readBuffer[2];
    unsigned char writeBuffer[2];
    struct sigaction sa;
    struct sigaction sa2;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up I2C pins
    gpio_fd = gpioGetFd(GPIO_SDA);
    if (gpio_fd < 0) {
        perror("gpioGetFd");
        gpioTerminate();
        return 1;
    }

    // Set I2C pins as alternate function
    gpioSetMode(GPIO_SDA, PI_BCM_DHT22);
    gpioSetMode(GPIO_SCL, PI_BCM_DHT22);

    // Open I2C device
    i2c_fd = i2cOpen(I2C Bus, I2C_ADDRESS, I2C_TIMEOUT);
    if (i2c_fd < 0) {
        perror("i2cOpen");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa2, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read temperature
        ret = i2cRead(i2c_fd, readBuffer, 2, I2C_READ);
        if (ret < 0) {
            if (errno == ETIMEDOUT) {
                printf("I2C read timed out\n");
            } else if (errno == EIO) {
                printf("I2C read error: %s\n", strerror(errno));
            } else {
                printf("I2C read error: %s\n", strerror(errno));
            }
            sleep(1);
            continue;
        }

        // Check if sensor is present
        if (readBuffer[0] == 0x00) {
            printf("Sensor not found\n");
            sleep(1);
            continue;
        }

        // Convert temperature to Celsius
        unsigned char msb = readBuffer[0] >> 4;
        unsigned char lsb = readBuffer[0] & 0x0F;
        unsigned char temp = (msb << 8) | lsb;
        float celsius = (temp / 16.0 - 273.15) * 5.0 / 9.0;

        // Log temperature
        printf("%.2f C\n", celsius);

        // Write dummy data to confirm sensor is present
        writeBuffer[0] = 0x00;
        writeBuffer[1] = 0x00;
        ret = i2cWrite(i2c_fd, writeBuffer, 2, I2C_WRITE);
        if (ret < 0) {
            if (errno == ETIMEDOUT) {
                printf("I2C write timed out\n");
            } else if (errno == EIO) {
                printf("I2C write error: %s\n", strerror(errno));
            } else {
                printf("I2C write error: %s\n", strerror(errno));
            }
        }
        sleep(1);
    }

    // Clean up
    i2cClose(i2c_fd);
    gpioTerminate();
    return 0;
}

