            } else {
                printf("I2C read error: %s\n", strerror(errno));
            }
            sleep(1);
            continue;
        }

        // Check if sensor is present
        if (readBuffer[0] == 0x00) {
            printf("Sensor not found\n");
            sleep(1);
            continue;
        }

        // Convert temperature to Celsius
        unsigned char msb = readBuffer[0] >> 4;
        unsigned char lsb = readBuffer[0] & 0x0F;
        unsigned char temp = (msb << 8) | lsb;
        float celsius = (temp / 16.0 - 273.15) * 5.0 / 9.0;

        // Log temperature
        printf("%.2f C\n", celsius);

        // Write dummy data to confirm sensor is present
        writeBuffer[0] = 0x00;
        writeBuffer[1] = 0x00;
        ret = i2cWrite(i2c_fd, writeBuffer, 2, I2C_WRITE);
        if (ret < 0) {
            if (errno == ETIMEDOUT) {
                printf("I2C write timed out\n");
            } else if (errno == EIO) {
                printf("I2C write error: %s\n", strerror(errno));
            } else {
                printf("I2C write error: %s\n", strerror(errno));
            }
        }
        sleep(1);
    }

    // Clean up
    i2cClose(i2c_fd);
    gpioTerminate();
    return 0;
}
