#define I2C_ADDRESS 0x63
#define I2C_COMMAND_READ Calibration 0x50
#define I2C_COMMAND_READ_MEAS 0x40
#define I2C_READ_SIZE 6
#define I2C_WRITE_SIZE 8

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up I2C
    if (gpioI2CSetup(1, I2C_ADDRESS, 100000) < 0) {
        fprintf(stderr, "Failed to set up I2C\n");
        gpioTerminate();
        return 1;
    }

    // Read calibration coefficients
    unsigned char calibration[8];
    if (gpioI2CWrite(1, I2C_COMMAND_READ, Calibration) < 0) {
        fprintf(stderr, "Failed to read calibration coefficients\n");
        gpioTerminate();
        return 1;
    }
    if (gpioI2CRead(1, I2C_ADDRESS, calibration, I2C_WRITE_SIZE) < 0) {
        fprintf(stderr, "Failed to read calibration coefficients\n");
        gpioTerminate();
        return 1;
    }

    // Compute scaling factors
    float scale_factor_lut = (calibration[0] + calibration[1] + calibration[2] + calibration[3] + calibration[4] + calibration[5]) / 6.0f;
    float scale_factor_h = (calibration[6] + calibration[7]) / 2.0f;
    float scale_factor_p = (calibration[0] + calibration[1] + calibration[2] + calibration[3]) / 4.0f;

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up SIGINT handler\n");
        gpioTerminate();
        return 1;
    }
    sa.sa_handler = sigterm_handler;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up SIGTERM handler\n");
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Trigger high-precision measurement
        if (gpioI2CWrite(1, I2C_COMMAND_READ_MEAS, 0) < 0) {
            fprintf(stderr, "Failed to trigger high-precision measurement\n");
            continue;
        }
        usleep(7);
        if (gpioI2CRead(1, I2C_ADDRESS, NULL, I2C_READ_SIZE) < 0) {
            fprintf(stderr, "Failed to read measurement\n");
            continue;
        }
        unsigned char temperature[2], pressure[4];
        if (gpioI2CRead(1, I2C_ADDRESS, temperature, 2) < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }
        if (gpioI2CRead(1, I2C_ADDRESS, pressure, 4) < 0) {
            fprintf(stderr, "Failed to read pressure\n");
            continue;
        }
        float temperature_c = (temperature[0] + temperature[1] * 256) / 65536.0f;
        float pressure_pa = (pressure[0] + pressure[1] + pressure[2] + pressure[3] * 256) / 65536.0f;
        float pressure_pascals = pressure_pa * scale_factor_p;
        float temperature_celsius = temperature_c * scale_factor_h;
        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temperature_celsius, pressure_pascals);
    }

    gpioTerminate();
    return 0;
}

void sigint_handler(int sig) {
    gpioTerminate();
    exit(0);
}

void sigterm_handler(int sig) {
    gpioTerminate();
    exit(0);
}

