#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_ADDRESS 0x60
#define I2C Bus 1
#define I2C_REG MSB 0xAA
#define I2C_REG_LSB 0xAB
#define I2C_REG_COUNT 16
#define I2C_REG_SIZE 2
#define I2C_READ 0x80
#define I2C_WRITE 0x00
#define I2C_DELAY 10

int main() {
    int fd;
    struct i2c_msg msg;
    struct i2c_file *file;
    struct i2c_msg *buf;
    unsigned char data[I2C_REG_SIZE];
    unsigned int pressure;
    unsigned int i;
    struct timespec ts;
    struct sigaction sa;

    // Install SIGINT/SIGTERM handler
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGPIPE);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C file descriptor
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set I2C bus and address
    if (ioctl(fd, I2C_SLAVE, I2C_Bus) < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    while (1) {
        // Trigger measurement
        if (ioctl(fd, I2C_READ, &msg) < 0) {
            perror("ioctl");
            continue;
        }

        // Read pressure value
        for (i = 0; i < I2C_REG_SIZE; i++) {
            if (msg->buf[i] == I2C_REG_MSBS) {
                data[I2C_REG_SIZE - 1 - i] = msg->buf[I2C_REG_MSBS - 1 - i];
            } else if (msg->buf[i] == I2C_REG_LSB) {
                data[i] = msg->buf[I2C_REG_LSB - 1 - i];
            } else {
                perror("Invalid register");
                continue;
            }
        }

        // Convert raw value to kPa
        pressure = (data[0] << 8) | data[1];
        pressure /= 0.1;

        // Log reading
        ts.tv_sec = time(NULL);
        ts.tv_nsec = 0;
        printf("%ld.%06ld %d\n", ts.tv_sec, ts.tv_nsec / 1000000, pressure);

        // Delay
        usleep(I2C_DELAY * 1000000);
    }

    // Close I2C file descriptor
    close(fd);

    return 0;
}

