int main() {
    struct i2c_client *client;
    int fd;
    uint8_t raw[9];
    uint8_t crc8[3];
    double pressure, temperature;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpio_initialise");
        exit(1);
    }

    // Set up GPIO for I2C
    if (gpioSetMode(GPIO_SDA, PI_INPUT) < 0) {
        perror("gpio_set_mode");
        exit(1);
    }
    if (gpioSetMode(GPIO_SCL, PI_INPUT) < 0) {
        perror("gpio_set_mode");
        exit(1);
    }

    // Open I2C interface
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    // Set I2C address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        i2c_error_handler(fd);
    }

    // Send continuous-measurement command
    if (i2c_write_handler(fd, &I2C_COMMAND, 1) < 0) {
        i2c_error_handler(fd);
    }

    // Wait 45 ms
    usleep(45000);

    // Read 9 bytes
    if (i2c_read_handler(fd, raw, 9) < 0) {
        i2c_error_handler(fd);
    }

    // Validate CRC-8
    crc8[0] = raw[8];
    crc8[1] = raw[7];
