#define WAIT_TIME_MS 8
#define PRESSURE_CONVERSION_FACTOR 60.0

// Function to calculate CRC-8 checksum
uint8_t calculate_crc(uint8_t *data, uint8_t size) {
    uint8_t crc = CRC_INIT_VALUE;
    for (uint8_t i = 0; i < size; i++) {
        crc = (crc >> 1);
        if (crc & 0x80) {
            crc = (crc ^ 0x31);
        }
        crc = (crc ^ data[i]);
    }
    return crc;
}

// Function to read differential pressure data from the sensor
void read_pressure(pigpio *gpio, uint8_t *data) {
    uint8_t command = MEASUREMENT_COMMAND | CONTINUOUS_MEASUREMENT;
    uint8_t crc = calculate_crc(&command, 1);
    gpioWrite(gpio, I2C_ADDRESS, command);
    gpioWrite(gpio, I2C_ADDRESS + I2C_ADDRESS_MASK, crc);
    usleep(WAIT_TIME_MS * 1000);
    uint8_t crc_read = gpioRead(gpio, I2C_ADDRESS + I2C_ADDRESS_MASK);
    if (crc != crc_read) {
        printf("CRC mismatch\n");
        return;
    }
    for (uint8_t i = 0; i < I2C_DATA_SIZE; i++) {
        data[i] = gpioRead(gpio, I2C_ADDRESS + i);
    }
}

