        printf("Error writing to log file\n");
        fclose(log_file);
        return;
    }
    if (fputc(',', log_file) == EOF) {
        printf("Error writing to log file\n");
        fclose(log_file);
        return;
    }
    if (fputc(pressure / PRESSURE_CONVERSION_FACTOR, log_file) == EOF) {
        printf("Error writing to log file\n");
        fclose(log_file);
        return;
    }
    if (fputc('\n', log_file) == EOF) {
        printf("Error writing to log file\n");
        fclose(log_file);
        return;
    }
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    pigpio *gpio = pigpio_init();
    if (gpio == NULL) {
        printf("Error initializing pigpio\n");
        return 1;
    }
    uint8_t data[I2C_DATA_SIZE];
