#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <time.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>

#define I2C_ADDRESS 0x40
#define I2C_BUS 1
#define SCALE_FACTOR 0.01
#define SAFE_PRESSURE_RANGE_MIN 200
#define SAFE_PRESSURE_RANGE_MAX 250

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    int i2c_fd = pigpioOpen(I2C_BUS, PI_I2C_MODE_BROADCAST);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    char log_file_path[256];
    sprintf(log_file_path, "pressure_log.csv");
    int log_fd = open(log_file_path, O_RDWR | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open I2C handle
    int i2c_handle = i2cOpen(i2c_fd, I2C_ADDRESS, PI_I2C_MODE_READ);
    if (i2c_handle < 0) {
        if (i2c_fd >= 0) {
            close(i2c_fd);
        }
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Read pressure every 1 second
    struct timespec start_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);
    while (1) {
        // Read pressure
        unsigned int pressure = i2cReadI2CBlockData(i2c_handle, 0x00, 2, PI_I2C_BLOCK_READ);
        if (pressure < 0) {
            if (i2c_fd >= 0) {
                close(i2c_fd);
            }
            if (i2c_handle >= 0) {
                i2cClose(i2c_handle);
            }
            pigpioClose(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Convert pressure to kPa
        float pressure_kPa = (pressure * SCALE_FACTOR);

        // Check if pressure is within safe range
        if (pressure_kPa < SAFE_PRESSURE_RANGE_MIN || pressure_kPa > SAFE_PRESSURE_RANGE_MAX) {
            fprintf(stderr, "Warning: Pressure out of range (%f kPa)\n", pressure_kPa);
        }

        // Log pressure
        char log_line[256];
        sprintf(log_line, "%f,%f\n", (float)clock_gettime(CLOCK_MONOTONIC.tv_sec) / CLOCKS_PER_SEC, pressure_kPa);
        if (log_fd >= 0) {
            if (fputs(log_line, log_fd) < 0) {
                if (log_fd >= 0) {
                    close(log_fd);
                }
                if (i2c_fd >= 0) {
                    close(i2c_fd);
                }
                if (i2c_handle >= 0) {
                    i2cClose(i2c_handle);
                }
                pigpioClose(i2c_fd);
                gpioTerminate();
                return 1;
            }
        }

        // Sleep for 1 second
        struct timespec sleep_time;
        clock_gettime(CLOCK_MONOTONIC, &sleep_time);
        sleep_time.tv_sec += 1;
        sleep(sleep_time.tv_sec - start_time.tv_sec);
    }

    // Clean up
    if (log_fd >= 0) {
        close(log_fd);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    pigpioClose(i2c_fd);
    gpioTerminate();

    return 0;
}

