#define I2C_ADDRESS 0x27
#define I2C_BUS 1
#define MEASUREMENT_INTERVAL 5000 // 5 seconds
#define FILE_SIZE 1048576 // 1 MB

int main(int argc, char **argv) {
    int fd;
    int i2c_fd;
    int status;
    unsigned char raw_T[2];
    unsigned char raw_H[2];
    unsigned char status_byte;
    time_t now;
    struct stat file_stat;
    char filename[256];
    char buffer[1024];

