    fd = open("environmental_data.log", O_RDWR | O_CREAT | O_APPEND | O_TRUNC, 0644);
    if (fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Open I2C device
    i2c_fd = i2cOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        perror("i2cOpen");
        close(fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Trigger measurement
        status_byte = 0x00;
        if (i2cWrite(i2c_fd, &status_byte, 1) < 0) {
            perror("i2cWrite");
            close(i2c_fd);
            close(fd);
            gpioTerminate();
            return 1;
