        if (raw_T[0] & 0x80) {
            printf("Sensor not found or bus error\n");
            close(i2c_fd);
            close(fd);
            gpioTerminate();
            return 1;
        }

        // Convert raw values
        float temperature = (raw_T[0] * 165.0 / 16383.0) - 40.0;
        float humidity = (raw_T[1] * 100.0 / 16383.0);

