#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>

#define GPIO_PIN 4
#define SENT_PROTOCOL_TICKS 56
#define SENT_STATUS_NIBBLES 4
#define SENT_DATA_NIBBLES 3
#define SENT_CHECKSUM_NIBBLES 1
#define SENT_CHECKSUM_WIDTH 12
#define SENT_CHECKSUM_WIDTH_MIN 36
#define SENT_CHECKSUM_WIDTH_MAX 813
#define SENT_CHECKSUM_ERROR 1
#define SENT_SENSOR_ABSENT_ERROR 2
#define SENT_BUS_ERROR_ERROR 3
#define SENT_PROTOCOL_ERROR 4
#define SENT_PROTOCOL_TICKS_MIN 36
#define SENT_PROTOCOL_TICKS_MAX 813
#define SENT_DATA_WIDTH 12
#define SENT_DATA_WIDTH_MIN 12
#define SENT_DATA_WIDTH_MAX 271
#define SENT_SCALE 0.01
#define SENT_OFFSET 0

// Global variables
int gpio;
int protocol_ticks;
int status_nibbles[SENT_STATUS_NIBBLES];
int data_nibbles[SENT_DATA_NIBBLES];
int checksum_nibble;
int pressure;
char log_file = "pressure_log.txt";
int log_fd = -1;

// Function to initialize pigpio
void init_pigpio() {
    if (gpio = pigpio_init()) {
        syslog(LOG_ERR, "pigpio_init failed");
        exit(1);
    }
}

// Function to read pressure data from the sensor
void read_pressure() {
    int i;
    int ticks;
    int status;
    int data;
    int checksum;
    int error;

    // Read the synchronization pulse
    ticks = pigpio_get_ticks();
    while (ticks < SENT_PROTOCOL_TICKS_MIN || ticks > SENT_PROTOCOL_TICKS_MAX) {
        ticks = pigpio_get_ticks();
    }

    // Read the status nibble
    status = pigpio_get_input(GPIO_PIN);
    if (status != 0) {
        syslog(LOG_ERR, "Invalid status nibble");
        return;
    }

    // Read the data nibbles
    for (i = 0; i < SENT_DATA_NIBBLES; i++) {
        data = pigpio_get_input(GPIO_PIN);
        if (data < SENT_DATA_WIDTH_MIN || data > SENT_DATA_WIDTH_MAX) {
            syslog(LOG_ERR, "Invalid data nibble");
            return;
        }
        data_nibbles[i] = data;
    }

    // Read the checksum nibble
    checksum = pigpio_get_input(GPIO_PIN);
    if (checksum < 0 || checksum > 15) {
        syslog(LOG_ERR, "Invalid checksum nibble");
        return;
    }
    checksum_nibble = checksum;

    // Calculate the checksum
    error = 0;
    for (i = 0; i < SENT_DATA_NIBBLES; i++) {
        error += data_nibbles[i];
    }
    error += checksum_nibble;
    if (error % 16 != checksum_nibble) {
        syslog(LOG_ERR, "Checksum error");
        return;
    }

    // Calculate the pressure
    pressure = (data_nibbles[0] * SENT_SCALE) + SENT_OFFSET;

    // Log the pressure
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    if (log_fd >= 0) {
        fprintf(log_fd, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
    }

    // Log the error
    if (error != 0) {
        syslog(LOG_ERR, "Error: %d", error);
    }
}

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int sig) {
    if (log_fd >= 0) {
        fclose(log_fd);
    }
    pigpio_close(gpio);
    exit(0);
}

int main() {
    // Initialize pigpio
    init_pigpio();

    // Open the log file
    log_fd = fopen(log_file, "a");
    if (log_fd < 0) {
        syslog(LOG_ERR, "Failed to open log file");
        return 1;
    }

    // Set up the GPIO pin
    pigpio_set_mode(GPIO_PIN, PI_INPUT);
    pigpio_pull_up(GPIO_PIN, PI_PUD_UP);

    // Read pressure data
    while (1) {
        read_pressure();
        sleep(0.1);
    }

    // Handle SIGINT and SIGTERM signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

