#define I2C_ADDRESS 0x44
#define I2C_BUS 1
#define CRC8_POLYNOM 0x31
#define CRC8_INIT 0xFF
#define MEASUREMENT_COMMAND 0xFD
#define MEASUREMENT_SIZE 6
#define MEASUREMENT_TYPE 0x00
#define MEASUREMENT_TYPE_HUMIDITY 0x01
#define MEASUREMENT_TYPE_TEMPERATURE 0x02

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C bus
    if (gpioI2COpen(I2C_BUS, I2C_ADDRESS) < 0) {
        perror("gpioI2COpen");
        gpioTerminate();
        return 1;
    }

    // Open log file
    int log_fd = open("environmental_data.txt", O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd < 0) {
        perror("open");
        gpioI2CClose(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Send measurement command
        uint8_t command = MEASUREMENT_COMMAND;
        uint8_t crc = MEASUREMENT_TYPE;
        if (gpioI2CWrite(I2C_BUS, I2C_ADDRESS, &command, 1) < 0) {
            perror("gpioI2CWrite");
            gpioI2CClose(I2C_BUS);
            gpioTerminate();
            close(log_fd);
            return 1;
        }
        if (gpioI2CWrite(I2C_BUS, I2C_ADDRESS, &crc, 1) < 0) {
            perror("gpioI2CWrite");
            gpioI2CClose(I2C_BUS);
            gpioTerminate();
            close(log_fd);
            return 1;
        }

        // Wait for conversion
        usleep(8500);

        // Read measurement
        uint8_t raw_temp[MEASUREMENT_SIZE];
        if (gpioI2CRead(I2C_BUS, I2C_ADDRESS, raw_temp, MEASUREMENT_SIZE) < 0) {
            perror("gpioI2CRead");
            gpioI2CClose(I2C_BUS);
            gpioTerminate();
            close(log_fd);
            return 1;
        }

        // Validate CRC-8 checksum
        uint8_t crc_temp = raw_temp[MEASUREMENT_SIZE - 1];
        uint8_t crc_hum = raw_temp[MEASUREMENT_SIZE - 2];
        if ((crc_temp ^ crc) != 0 || (crc_hum ^ raw_temp[MEASUREMENT_SIZE - 3]) != 0) {
            printf("Invalid CRC-8 checksum\n");
            continue;
        }

        // Convert raw values
        float temp = -45.0 + 175.0 * (raw_temp[0] / 65535.0);
        float hum = -6.0 + 125.0 * (raw_temp[1] / 65535.0);

        // Log reading
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_fd, "%s %f°C %f %RH\n", timestamp, temp, hum);
        fflush(log_fd);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    gpioI2CClose(I2C_BUS);
    gpioTerminate();
    close(log_fd);
    return 0;
}

