#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>

#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL 5  // in seconds
#define I2C_ADDRESS 0x48
#define I2C_REG 0x00
#define I2C_RES 0.0078125

int main(int argc, char **argv) {
    int i, j;
    int fd;
    pigpio *gpio;
    struct pigpio_i2c *i2c;
    unsigned char buffer[BUFFER_SIZE];
    unsigned char temp[2];
    struct timespec start_time;
    struct timespec end_time;
    struct timespec time_diff;
    struct timespec sleep_time;
    struct timespec sleep_interval;
    int ret;

    // Initialize pigpio
    gpio = pigpio_init();
    if (gpio == NULL) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    // Create I2C handle
    i2c = pigpio_i2c_open(1, I2C_ADDRESS, PI_I2C_MODE_READ);
    if (i2c == NULL) {
        fprintf(stderr, "I2C handle creation failed\n");
        pigpio_close(gpio);
        return 1;
    }

    // Create a circular buffer to store temperature readings
    FILE *log_file = fopen("temperature_log.dat", "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        pigpio_close(gpio);
        pigpio_i2c_close(i2c);
        return 1;
    }

    // Initialize the buffer
    memset(buffer, 0, BUFFER_SIZE * sizeof(buffer[0]));

    // Record the start time
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (1) {
        // Read the temperature register
        ret = pigpio_i2c_read(i2c, I2C_REG, temp, 2);
        if (ret != 2) {
            fprintf(stderr, "I2C read failed\n");
            continue;
        }

        // Convert the temperature to Celsius
        float temperature = (temp[0] << 8) | temp[1];
        temperature /= I2C_RES;

        // Store the temperature in the buffer
        for (i = BUFFER_SIZE - 1; i >= 0; i--) {
            buffer[i] = buffer[i + 1];
        }
        buffer[0] = temperature;

        // Flush the buffer to the log file
        fwrite(buffer, sizeof(buffer[0]), BUFFER_SIZE, log_file);

        // Sleep for the sample interval
        clock_gettime(CLOCK_MONOTONIC, &end_time);
        time_diff.tv_sec = end_time.tv_sec - start_time.tv_sec;
        time_diff.tv_nsec = end_time.tv_nsec - start_time.tv_nsec;
        sleep_time.tv_sec = (SAMPLE_INTERVAL - time_diff.tv_sec) * 1000000000;
        sleep_time.tv_nsec = 0;
        nanosleep(&sleep_time, NULL);

        // Record the end time
        clock_gettime(CLOCK_MONOTONIC, &end_time);
    }

    // Flush the buffer to the log file
    fwrite(buffer, sizeof(buffer[0]), BUFFER_SIZE, log_file);

    // Close the log file
    fclose(log_file);

    // Release the I2C handle
    pigpio_i2c_close(i2c);

    // Release the pigpio
    pigpio_close(gpio);

    return 0;
}

