#define SHTC3_WRITE 0x01
#define SHTC3_CRC8_POLYNOM 0x31
#define SHTC3_CRC8_INIT 0xFF

#define SHTC3_TEMPERATURE 0x00
#define SHTC3_HUMIDITY 0x01
#define SHTC3_CRC8 0x02
#define SHTC3_DATA 0x03

#define SHTC3_TEMPERATURE_SIZE 2
#define SHTC3_HUMIDITY_SIZE 2

#define SHTC3_DATA_SIZE SHTC3_TEMPERATURE_SIZE + SHTC3_HUMIDITY_SIZE

#define SHTC3_LOG_FILE "shtc3_environment.log"

int main(int argc, char **argv) {
    int i, j;
    int shtc3_fd;
    unsigned char shtc3_data[SHTC3_DATA_SIZE];
    unsigned char shtc3_crc8[SHTC3_DATA_SIZE];
    unsigned char shtc3_crc8_calculated[SHTC3_DATA_SIZE];
    float temperature, humidity;
    struct timespec start_time;
    struct timespec end_time;
    struct timeval tv;
    struct sigaction sa;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up I2C pins
    if (gpioSetMode(3, PI_INPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(4, PI_INPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    // Open I2C handle
    if ((shtc3_fd = i2cOpen(1, SHTC3_ADDRESS, 100)) < 0) {
        perror("i2cOpen");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Wait for 5 seconds
        clock_gettime(CLOCK_REALTIME, &start_time);

        // Send normal-power measurement command
        if (i2cWrite(shtc3_fd, SHTC3_COMMAND, 1) < 0) {
            perror("i2cWrite");
            continue;
        }

        // Wait for 12.4 ms
        usleep(12400);

        // Read 6 bytes
        if (i2cRead(shtc3_fd, shtc3_data, SHTC3_DATA_SIZE, 0) < 0) {
            perror("i2cRead");
            continue;
