        for (i = 0; i < SHTC3_DATA_SIZE; i++) {
            shtc3_crc8_calculated[i] = (shtc3_data[i] ^ shtc3_crc8_INIT) ^ (shtc3_crc8_INIT << 1);
            for (j = 0; j < 8; j++) {
                if (shtc3_crc8_calculated[i] & (1 << j)) {
                    shtc3_crc8_calculated[i] ^= shtc3_crc8_POLYNOM;
                }
            }
            if (shtc3_crc8_calculated[i] != shtc3_data[i]) {
                printf("CRC error\n");
                continue;
            }
        }

        // Convert temperature and humidity
        temperature = (shtc3_data[SHTC3_TEMPERATURE] * 175) / 65535.0 - 45.0;
        humidity = (shtc3_data[SHTC3_HUMIDITY] * 100) / 65535.0;

        // Validate temperature and humidity
        if (temperature < -40 || temperature > 125 || humidity < 0 || humidity > 100) {
            printf("Invalid reading\n");
            continue;
        }

        // Log valid reading
        tv.tv_sec = start_time.tv_sec;
        tv.tv_usec = start_time.tv_nsec / 1000;
        printf("%04d-%02d-%02d %02d:%02d:%02d,Temperature(%.2f),Humidity(%.2f)\n",
               tv.tv_sec, tv.tv_usec / 1000000, tv.tv_sec % 100, tv.tv_sec % 100, tv.tv_usec % 1000000, tv.tv_sec % 100, temperature, humidity);

        // Log to file
        FILE *log_file = fopen(SHTC3_LOG_FILE, "a");
        if (log_file == NULL) {
            perror("fopen");
            continue;
        }
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,Temperature(%.2f),Humidity(%.2f)\n",
                tv.tv_sec, tv.tv_usec / 1000000, tv.tv_sec % 100, tv.tv_sec % 100, tv.tv_usec % 1000000, tv.tv_sec % 100, temperature, humidity);
        fclose(log_file);
    }

    // Clean up
    i2cClose(shtc3_fd);
    gpioTerminate();
    return 0;
}

void sigint_handler(int sig) {
    i2cClose(shtc3_fd);
    gpioTerminate();
    exit(0);
}

