        perror("i2cOpen");
        i2cClose(I2C_BUS);
        close(fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read raw value from sensor
        unsigned char raw_value;
        if (i2cRead(i2c, &raw_value, 1) < 0) {
            printf("Error reading from sensor\n");
            continue;
