        if (fwrite(&temp_celsius, sizeof(float), 1, fd) < 0) {
            perror("fwrite");
            continue;
        }

        // Write newline character
        if (fwrite("\n", 1, 1, fd) < 0) {
            perror("fwrite");
            continue;
        }

        // Flush file
        if (fflush(fd) < 0) {
            perror("fflush");
            continue;
        }
    }

    // Close I2C device
    i2cClose(I2C_BUS);

    // Close I2C bus
    i2cClose(I2C_BUS);

    // Close file
    close(fd);

    // Terminate pigpio
    gpioTerminate();

