#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>

#define I2C_ADDRESS 0x48
#define I2C_BUS 1
#define I2C_REG 0x00
#define I2C_RES 0.0078125

int main() {
    int i2c_fd = -1;
    int retry = 0;
    struct sigaction sa;

    // Initialize signal handler for SIGINT
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    sigaction(SIGINT, &sa, NULL);

    while (1) {
        // Initialize I2C handle
        i2c_fd = pigpio_i2c_open(I2C_BUS, I2C_ADDRESS, PI_I2C_MODE_READ);
        if (i2c_fd < 0) {
            if (retry < 3) {
                retry++;
                printf("I2C initialization failed. Retrying...\n");
                sleep(1);
            } else {
                printf("I2C initialization failed after 3 retries. Exiting...\n");
                break;
            }
            continue;
        }

        // Read temperature
        unsigned char temp_buf[2];
        int ret = pigpio_i2c_read(i2c_fd, I2C_REG, temp_buf, 2);
        if (ret < 0) {
            if (retry < 3) {
                retry++;
                printf("I2C read failed. Retrying...\n");
                sleep(1);
            } else {
                printf("I2C read failed after 3 retries. Exiting...\n");
                break;
            }
            continue;
        }

        // Convert temperature
        int16_t temp = (temp_buf[0] << 8) | temp_buf[1];
        if (temp < 0) {
            temp += 0x10000;
        }

        // Calculate temperature in Celsius
        float celsius = (float)temp * I2C_RES;

        // Log temperature
        time_t now = time(NULL);
        char log_str[32];
        strftime(log_str, sizeof(log_str), "%Y-%m-%d %H:%M:%S, Temperature: %.2f C\n", localtime(&now));
        FILE *log_file = fopen("temperature_log.txt", "a");
        if (log_file == NULL) {
            printf("Failed to open log file\n");
            continue;
        }
        fprintf(log_file, "%s", log_str);
        fclose(log_file);

        // Clean up
        pigpio_i2c_close(i2c_fd);
        i2c_fd = -1;
    }

    return 0;
}

