#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <unistd.h>

#define SHT31_ADDRESS 0x44
#define SHT31_COMMAND 0x2C06
#define SHT31_READ_LENGTH 6
#define SHT31_CRC_LENGTH 2
#define SHT31_TEMPERATURE_OFFSET -45
#define SHT31_HUMIDITY_OFFSET 100

int main(int argc, char **argv) {
    int i, retry = 0;
    pigpio *gpio = pigpio_get();
    if (!gpio) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return 1;
    }

    if (gpio_i2c_open(gpio, 1, 0, 0) != 0) {
        syslog(LOG_ERR, "Failed to open I2C bus 1");
        pigpio_close(gpio);
        return 1;
    }

    FILE *log_file = fopen("sht31d_data.log", "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file");
        pigpio_close(gpio);
        return 1;
    }

    while (1) {
        struct timespec start_time;
        clock_gettime(CLOCK_REALTIME, &start_time);

        int raw_temperature = 0;
        int raw_humidity = 0;
        int temperature_crc = 0;
        int humidity_crc = 0;
        int retry_count = 0;

        while (retry_count < 3) {
            if (gpio_i2c_write(gpio, 1, SHT31_ADDRESS, SHT31_COMMAND) != 0) {
                syslog(LOG_ERR, "Failed to write to SHT31");
                retry_count++;
                usleep(15000);
                continue;
            }

            if (gpio_i2c_read(gpio, 1, SHT31_ADDRESS, SHT31_READ_LENGTH, &raw_temperature, &raw_humidity) != 0) {
                syslog(LOG_ERR, "Failed to read from SHT31");
                retry_count++;
                usleep(15000);
                continue;
            }

            if (raw_temperature < 0 || raw_temperature > 65535) {
                syslog(LOG_ERR, "Invalid temperature value");
                retry_count++;
                usleep(15000);
                continue;
            }

            temperature_crc = (raw_temperature & 0xFF) ^ (raw_temperature >> 8);
            humidity_crc = (raw_humidity & 0xFF) ^ (raw_humidity >> 8);

            if (temperature_crc != 0x31 || humidity_crc != 0x31) {
                syslog(LOG_ERR, "Invalid CRC");
                retry_count++;
                usleep(15000);
                continue;
            }

            raw_temperature = (raw_temperature - SHT31_TEMPERATURE_OFFSET) * 175 / 65535;
            raw_humidity = (raw_humidity - SHT31_HUMIDITY_OFFSET) * 100 / 65535;

            fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
                    start_time.tv_sec / 3600, start_time.tv_min, start_time.tv_sec % 60,
                    start_time.tv_sec % 60, start_time.tv_nsec / 1000000, start_time.tv_nsec % 1000000,
                    raw_temperature, raw_humidity);

            syslog(LOG_INFO, "Temperature: %.2f, Humidity: %.2f", raw_temperature, raw_humidity);

            clock_gettime(CLOCK_REALTIME, &start_time);
            usleep(5000000);
        }

        if (gpio_i2c_close(gpio) != 0) {
            syslog(LOG_ERR, "Failed to close I2C handle");
        }

        if (fclose(log_file) != 0) {
            syslog(LOG_ERR, "Failed to close log file");
        }

        pigpio_close(gpio);
        return 0;
    }

    return 0;
}

