#include <unistd.h>
#include <signal.h>

#define I2C_ADDRESS_64 0x64
#define I2C_ADDRESS_65 0x65
#define I2C_ADDRESS_ALT 0x66
#define I2C Bus 1
#define FILE_NAME "cct_log.csv"

int main(int argc, char **argv) {
    int i2c_fd[2];
    int ret;
    struct stat sb;
    FILE *fp;
    struct sigaction sa;
    struct sigaction sa_int, sa_term;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    if ((ret = i2cOpen(I2C Bus, 0, &i2c_fd[0]) != 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Open file for writing
    if ((ret = open(FILE_NAME, O_RDWR | O_CREAT | O_WRONLY | O_APPEND) != -1) {
        if (fstat(i2c_fd[0], &sb) != 0) {
            fprintf(stderr, "Failed to get I2C bus file status\n");
            close(i2c_fd[0]);
            gpioTerminate();
            return 1;
        }
        if (fstat(sb.st_size, &sb) != 0) {
            fprintf(stderr, "Failed to get file status\n");
            close(i2c_fd[0]);
            gpioTerminate();
            return 1;
        }
    } else {
        fprintf(stderr, "Failed to open file for writing\n");
        close(i2c_fd[0]);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    sa.sa_handler = sigpipe;
    sa_int.sa_handler = sigpipe;
    sa_term.sa_handler = sigpipe;
    sigemptyset(&sa);
    sigaddset(&sa, SIGPIPE);
    sigaddset(&sa, SIGINT);
    sigaddset(&sa, SIGTERM);
    if (sigaction(SIGINT, &sa_int, NULL) != 0) {
        fprintf(stderr, "Failed to set up SIGINT handler\n");
        close(i2c_fd[0]);
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa_term, NULL) != 0) {
        fprintf(stderr, "Failed to set up SIGTERM handler\n");
        close(i2c_fd[0]);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read device ID register
        if ((ret = i2cWriteI2CBlockData(i2c_fd[0], I2C_ADDRESS_64, 1, &0x00, 1)) != 0) {
            fprintf(stderr, "Failed to read device ID register\n");
            continue;
        }
        if (i2cReadI2CBlockData(i2c_fd[0], I2C_ADDRESS_64, 1, &0x00, 1) != 0) {
            fprintf(stderr, "Failed to read device ID register\n");
            continue;
        }
