        int red = (i2cReadI2CBlockData(i2c_fd[0], I2C_ADDRESS_64, 1, &0x00, 1)[0] << 8) | i2cReadI2CBlockData(i2c_fd[0], I2C_ADDRESS_64, 1, &0x00, 1)[1];
