#define FAN_HYST 2
#define FAN_ON 1
#define FAN_OFF 0

int main(int argc, char **argv) {
    int i, j, fan_state = FAN_OFF;
    unsigned char buffer[BUFFER_SIZE];
    unsigned char temperature;
    unsigned int running_sum = 0;
    unsigned int count = 0;
    struct sigaction sa;
    struct rlimit rlim;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    // Set up signal handlers
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGPIPE);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction setup failed\n");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction setup failed\n");
        return 1;
    }

    // Set up I2C bus
    if (gpioI2COpen(1, 0x48) < 0) {
        fprintf(stderr, "I2C open failed\n");
        return 1;
    }

    // Set up fan GPIO
    if (gpioMode(FAN_GPIO, GPIO_MODE_OUTPUT) < 0) {
        fprintf(stderr, "GPIO mode failed\n");
        return 1;
    }
    if (gpioWrite(FAN_GPIO, FAN_OFF) < 0) {
        fprintf(stderr, "GPIO write failed\n");
        return 1;
    }

    while (1) {
        // Read temperature
        if (gpioI2CRead(1, TEMPERATURE_REGISTER, &temperature, 1) < 0) {
            fprintf(stderr, "I2C read failed\n");
            sleep(1);
            continue;
        }

        // Convert temperature
        unsigned int temp = (temperature & 0x1F) - 0x10;
        running_sum += temp;
        count++;

        // Update fan state
        if (count >= BUFFER_SIZE) {
            running_sum -= buffer[0];
            count--;
        }
        if (running_sum / count > 28.0 + FAN_HYST) {
            fan_state = FAN_ON;
        } else if (running_sum / count < 26.0 - FAN_HYST) {
            fan_state = FAN_OFF;
        }

        // Write fan state
        if (fan_state == FAN_ON) {
            if (gpioWrite(FAN_GPIO, FAN_ON) < 0) {
                fprintf(stderr, "GPIO write failed\n");
                return 1;
            }
        } else {
            if (gpioWrite(FAN_GPIO, FAN_OFF) < 0) {
                fprintf(stderr, "GPIO write failed\n");
                return 1;
            }
        }

        // Log temperature
        printf("%.1f\n", (double)running_sum / count);

        // Sleep
        sleep(1);
    }

    // Clean up
    gpioClose(1);
    gpioTerminate();
    return 0;
}

