#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDRESS 0x25
#define I2C_ADDRESS_MASK 0x01
#define I2C_DATA_SIZE 9
#define CRC8_POLYNOM 0x31
#define SCALE_FACTOR_PRESSURE 60
#define SCALE_FACTOR_TEMPERATURE 200
#define LOG_FILE "airflow.log"

int main(int argc, char **argv) {
    int i2c_fd = -1;
    int gpio_fd = -1;
    int crc8;
    int pressure, temperature, status;
    int16_t raw_pressure, raw_temperature;
    struct timespec ts;
    struct sigaction sa;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C handle
    i2c_fd = i2cOpen(I2C_ADDRESS, I2C_ADDRESS_MASK, 100000);
    if (i2c_fd < 0) {
        perror("i2cOpen");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGPIPE);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        // Send continuous-measurement command
        if (i2cWrite(i2c_fd, 0x362F, 1) < 0) {
            perror("i2cWrite");
            continue;
        }

        // Wait for 45 ms
        usleep(45000);

        // Read 9 bytes
        if (i2cRead(i2c_fd, &crc8, I2C_DATA_SIZE, 0) < 0) {
            perror("i2cRead");
            continue;
        }

        // Validate CRC
        if (crc8 != (crc8 & 0xFF) ^ (crc8 >> 1)) {
            syslog(LOG_ERR, "CRC mismatch");
            continue;
        }

        // Read raw pressure and temperature
        if (i2cRead(i2c_fd, &raw_pressure, sizeof(raw_pressure), 1) < 0) {
            perror("i2cRead");
            continue;
        }
        if (i2cRead(i2c_fd, &raw_temperature, sizeof(raw_temperature), 1) < 0) {
            perror("i2cRead");
            continue;
        }

        // Convert raw values
        pressure = raw_pressure * SCALE_FACTOR_PRESSURE;
        temperature = raw_temperature * SCALE_FACTOR_TEMPERATURE;

        // Log data
        time(&ts);
        fprintf(stderr, "timestamp,%d,%d\n", ts.tv_sec, pressure);
        if (pressure > 5.0) {
            fprintf(stderr, "Warning: pressure %d Pa\n", pressure);
        }
        fprintf(LOG_FILE, "%d,%d,%d\n", ts.tv_sec, pressure, temperature);

        // Close I2C handle
        i2cClose(i2c_fd);
        i2c_fd = -1;
    }

    // Close log file
    fclose(LOG_FILE);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

