#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDRESS 0x25
#define I2C Bus 1
#define CONTINUOUS_MEASUREMENT 0x362F
#define WAIT_TIME 45
#define CRC_8_POLYNOMIAL 0x31
#define CRC_8_INIT_VALUE 0xFF
#define SCALE_FACTOR_LENGTH 3
#define PRESSURE_LENGTH 2
#define TEMPERATURE_LENGTH 2
#define TOTAL_LENGTH (PRESSURE_LENGTH + 1 + TEMPERATURE_LENGTH + 1 + SCALE_FACTOR_LENGTH)

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up I2C
    if (gpioSetMode(I2C_Bus, I2C_MODE_MASTER) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    // Set I2C clock speed
    if (gpioSetClock(I2C_Bus, 400000) < 0) {
        perror("gpioSetClock");
        gpioTerminate();
        return 1;
    }

    // Set I2C address
    if (gpioSetI2CAddress(I2C_Bus, I2C_ADDRESS) < 0) {
        perror("gpioSetI2CAddress");
        gpioTerminate();
        return 1;
    }

    // Send continuous-measurement command
    if (gpioWrite(I2C_Bus, CONTINUOUS_MEASUREMENT) < 0) {
        perror("gpioWrite");
        gpioTerminate();
        return 1;
    }

    // Wait for at least 45 ms
    usleep(WAIT_TIME * 1000);

    // Read data
    unsigned char data[TOTAL_LENGTH];
    if (gpioRead(I2C_Bus, data, TOTAL_LENGTH) < 0) {
        perror("gpioRead");
        gpioTerminate();
        return 1;
    }

    // Validate CRC-8 for pressure and temperature readings
    unsigned char crc8_pressure = (data[PRESSURE_LENGTH + 1] << 1);
    unsigned char crc8_temperature = (data[TEMPERATURE_LENGTH + 1] << 1);
    unsigned char crc8_scale_factor = (data[TOTAL_LENGTH - 1] << 1);

    if (crc8_pressure != (crc8_pressure ^ (crc8_pressure >> 1)) || crc8_temperature != (crc8_temperature ^ (crc8_temperature >> 1)) || crc8_scale_factor != (crc8_scale_factor ^ (crc8_scale_factor >> 1))) {
        printf("CRC-8 error\n");
        gpioTerminate();
        return 1;
    }

    // Convert raw differential pressure
    int pressure = (data[PRESSURE_LENGTH] << 8) | data[PRESSURE_LENGTH + 1];
    int scale_factor = (data[TOTAL_LENGTH - SCALE_FACTOR_LENGTH] << 16) | (data[TOTAL_LENGTH - SCALE_FACTOR_LENGTH + 1] << 8) | data[TOTAL_LENGTH - SCALE_FACTOR_LENGTH + 2];

    if (scale_factor == 0) {
        printf("Scale factor is zero\n");
        gpioTerminate();
        return 1;
    }

    pressure /= scale_factor;

    // Convert raw temperature
    float temperature = (data[TEMPERATURE_LENGTH] << 8) | data[TEMPERATURE_LENGTH + 1];
    temperature /= 200.0f;

    // Log reading
    FILE *file = fopen("flow_data.txt", "a");
    if (file == NULL) {
        perror("fopen");
        gpioTerminate();
        return 1;
    }

    fprintf(file, "%d %d %d %f\n", (int)time(NULL), pressure, temperature, temperature);
    fclose(file);

    // Release resources
    gpioTerminate();

    return 0;
}

// Signal handler for SIGINT
void sigint_handler(int sig) {
    gpioTerminate();
    exit(0);
}

// Register signal handler
void sigaction_handler(int sig) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(sig, &sa, NULL) < 0) {
        perror("sigaction");
        exit(1);
    }
}

int main() {
    // Register signal handler
    sigaction(SIGINT, &sigaction_handler, NULL);

    return main();
}

