#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <syslog.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDRESS 0x40
#define I2C_ADDRESS_RH 0xE0
#define I2C_ADDRESS_TEMP 0xF3
#define I2C_ADDRESS_ID 0xF2
#define I2C_ADDRESS_REVISION 0xF1
#define I2C_COMMAND_MEASURE_RH 0xF5
#define I2C_COMMAND_MEASURE_TEMP 0xF3
#define I2C_COMMAND_READ_RH 0xE0
#define I2C_COMMAND_READ_TEMP 0xE1
#define I2C_COMMAND_READ_ID 0xE2
#define I2C_COMMAND_READ_REVISION 0xE3
#define I2C_COMMAND_NO_HOLD 0x00
#define I2C_COMMAND_HOLD 0x01
#define I2C_TIMEOUT 0x00
#define I2C_RETRY 3

int main(int argc, char **argv) {
    int i, retry;
    int i2c_fd;
    int temp, rh;
    int id, revision;
    int temp_c, rh_pct;
    struct timespec t;
    struct timespec now;
    struct sigaction sa;
    char buffer[2];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        exit(1);
    }

    // Set up I2C
    if ((i2c_fd = i2cOpen(1, I2C_ADDRESS, I2C_TIMEOUT)) < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus");
        gpioTerminate();
        exit(1);
    }

    // Set up signal handlers
    sa.sa_handler = sigintHandler;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set up signal handler");
        gpioTerminate();
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set up signal handler");
        gpioTerminate();
        exit(1);
    }

    while (1) {
        // Measure temperature and humidity
        retry = 0;
        while (retry < I2C_RETRY) {
            if (i2cReadDevice(i2c_fd, I2C_ADDRESS_RH, I2C_COMMAND_MEASURE_RH, I2C_COMMAND_NO_HOLD, 2, buffer, 2) < 0) {
                syslog(LOG_ERR, "Failed to read RH");
                retry++;
            } else {
                rh = (buffer[0] << 8) | buffer[1];
                retry = 0;
            }
        }
        if (retry >= I2C_RETRY) {
            syslog(LOG_ERR, "Failed to read RH after %d retries", I2C_RETRY);
            continue;
        }

        retry = 0;
        while (retry < I2C_RETRY) {
            if (i2cReadDevice(i2c_fd, I2C_ADDRESS_TEMP, I2C_COMMAND_MEASURE_TEMP, I2C_COMMAND_NO_HOLD, 2, buffer, 2) < 0) {
                syslog(LOG_ERR, "Failed to read temp");
                retry++;
            } else {
                temp = (buffer[0] << 8) | buffer[1];
                retry = 0;
            }
        }
        if (retry >= I2C_RETRY) {
            syslog(LOG_ERR, "Failed to read temp after %d retries", I2C_RETRY);
            continue;
        }

        // Convert raw values
        temp_c = (175.72 * temp) / 65536 - 46.85;
        rh_pct = (125 * rh) / 65536 - 6;
        if (rh_pct < 0) rh_pct = 0;
        if (rh_pct > 100) rh_pct = 100;

        // Log data
        time(&now);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(stderr, "%s,%d,%d\n", buffer, temp_c, rh_pct);
        fprintf(stdout, "%s,%d,%d\n", buffer, temp_c, rh_pct);
        fflush(stdout);

        // Log to file
        FILE *log_file = fopen("environment.log", "a");
        if (log_file == NULL) {
            syslog(LOG_ERR, "Failed to open log file");
            continue;
        }
        fprintf(log_file, "%s,%d,%d\n", buffer, temp_c, rh_pct);
        fclose(log_file);

        // Wait 60 seconds before taking the next reading
        sleep(60);
    }

    // Clean up
    i2cClose(i2c_fd);
    gpioTerminate();
    exit(0);
}

void sigintHandler(int sig) {
    gpioTerminate();
    exit(0);
}

