#define HUMIDITY_REGISTER 0x01
#define TEMPERATURE_OFFSET 0
#define HUMIDITY_OFFSET 0
#define TEMPERATURE_SCALE 165.0
#define HUMIDITY_SCALE 100.0

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C bus
    int i2c_fd = i2cOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        perror("i2cOpen");
        gpioTerminate();
        return 1;
    }

    // Configure HDC1080
    if (i2cWrite(i2c_fd, CONFIG_REGISTER, 0x00) < 0) {
        perror("i2cWrite");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
