    unsigned char raw_temp[2];
    unsigned char raw_humidity[2];
    if (i2cRead(i2c_fd, TEMPERATURE_REGISTER, raw_temp, 2) < 0) {
        perror("i2cRead");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (i2cRead(i2c_fd, HUMIDITY_REGISTER, raw_humidity, 2) < 0) {
        perror("i2cRead");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
