    FILE *log_file = fopen("enviro_log.txt", "a");
    if (log_file == NULL) {
        perror("fopen");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "%s,%f,%f\n", time(NULL), temperature, humidity);
    fclose(log_file);

    // Main loop
    while (1) {
        // Wait for 5 seconds
        sleep(5);

        // Read temperature and humidity
        if (i2cRead(i2c_fd, TEMPERATURE_REGISTER, raw_temp, 2) < 0) {
            perror("i2cRead");
            i2cClose(i2c_fd);
            gpioTerminate();
            return 1;
        }
        if (i2cRead(i2c_fd, HUMIDITY_REGISTER, raw_humidity, 2) < 0) {
            perror("i2cRead");
            i2cClose(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Convert raw values
        temperature = (raw_temp[0] / 65536.0) * TEMPERATURE_SCALE - TEMPERATURE_OFFSET;
        humidity = (raw_humidity[0] / 65536.0) * HUMIDITY_SCALE;

        // Log reading
        log_file = fopen("enviro_log.txt", "a");
