#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>

#define I2C_ADDRESS 0x25
#define I2C Bus 1
#define I2C_COMMAND 0x3615
#define I2C_READ 0x00
#define I2C_WRITE 0x01
#define CRC_8_POLYNOMINAL 0x31
#define CRC_8_INIT_VALUE 0xFF

#define PRESSURE_SCALE_FACTOR 0x0000
#define TEMPERATURE_SCALE_FACTOR 0x0000

#define PRESSURE_SIZE 2
#define TEMPERATURE_SIZE 2
#define SCALE_FACTOR_SIZE 3

#define LOG_FILE "hvac_pressure_log.txt"

int main(int argc, char *argv[]) {
    int i2c_fd;
    int gpio_fd;
    int gpio_status;
    unsigned char i2c_buf[9];
    unsigned char crc_buf[9];
    unsigned char pressure_buf[PRESSURE_SIZE];
    unsigned char temperature_buf[TEMPERATURE_SIZE];
    unsigned char scale_factor_buf[SCALE_FACTOR_SIZE];
    struct timespec ts;
    struct stat sb;
    struct sigaction sa;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing GPIO\n");
        return 1;
    }

    // Open I2C
    if ((i2c_fd = pigpioOpen(I2C Bus, I2C_ADDRESS, PI_I2C_MODE_READ_WRITE)) < 0) {
        fprintf(stderr, "Error opening I2C\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    if ((gpio_fd = open(LOG_FILE, O_RDWR | O_CREAT | O_TRUNC, 0644)) < 0) {
        fprintf(stderr, "Error opening log file\n");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handler\n");
        close(gpio_fd);
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Send continuous-measurement command
        if (pigpioWrite(i2c_fd, I2C_COMMAND, 1) < 0) {
            fprintf(stderr, "Error sending continuous-measurement command\n");
            continue;
        }

        // Wait at least 50 ms
        usleep(50000);

        // Read 9 bytes: 2 bytes pressure plus 1 CRC, 2 bytes temperature plus 1 CRC, and 3 bytes of scale factor
        if (pigpioRead(i2c_fd, i2c_buf, 9, 0) < 0) {
            fprintf(stderr, "Error reading from I2C\n");
            continue;
        }

        // Validate CRC-8
        crc_buf[0] = i2c_buf[8];
        crc_buf[1] = i2c_buf[9];
        for (int i = 0; i < 8; i++) {
            crc_buf[1] = (crc_buf[1] ^ crc_buf[1]) ^ (crc_buf[1] << 1);
            crc_buf[1] = (crc_buf[1] ^ crc_buf[0]) ^ (crc_buf[1] << 4);
            crc_buf[0] = (crc_buf[0] ^ crc_buf[1]) ^ (crc_buf[0] << 3);
            crc_buf[1] = (crc_buf[1] ^ crc_buf[0]) ^ (crc_buf[1] << 5);
            crc_buf[0] = (crc_buf[0] ^ crc_buf[1]) ^ (crc_buf[0] << 2);
            crc_buf[1] = (crc_buf[1] ^ crc_buf[0]) ^ (crc_buf[1] << 4);
            crc_buf[0] = (crc_buf[0] ^ crc_buf[1]) ^ (crc_buf[0] << 3);
            crc_buf[1] = (crc_buf[1] ^ crc_buf[0]) ^ (crc_buf[1] << 5);
            crc_buf[0] = (crc_buf[0] ^ crc_buf[1]) ^ (crc_buf[0] << 2);
        }
        if (crc_buf[0] != CRC_8_INIT_VALUE) {
            fprintf(stderr, "Error: CRC-8 mismatch\n");
            continue;
        }

        // Read pressure and temperature
        if (pigpioRead(i2c_fd, pressure_buf, PRESSURE_SIZE, 0) < 0) {
            fprintf(stderr, "Error reading pressure\n");
            continue;
        }
        if (pigpioRead(i2c_fd, temperature_buf, TEMPERATURE_SIZE, 0) < 0) {
            fprintf(stderr, "Error reading temperature\n");
            continue;
        }

        // Read scale factor
        if (pigpioRead(i2c_fd, scale_factor_buf, SCALE_FACTOR_SIZE, 0) < 0) {
            fprintf(stderr, "Error reading scale factor\n");
            continue;
        }

        // Convert raw pressure and temperature
        double pressure = (pressure_buf[0] * pressure_buf[1] / scale_factor_buf[0]);
        double temperature = (temperature_buf[0] * temperature_buf[1] / scale_factor_buf[0]);

        // Log valid readings
        if (fstat(gpio_fd, &sb) == -1) {
            fprintf(stderr, "Error getting file status\n");
            continue;
        }
        if (ftruncate(gpio_fd, sb.st_size) < 0) {
            fprintf(stderr, "Error truncating file\n");
            continue;
        }
        if (fseek(gpio_fd, 0, SEEK_SET) < 0) {
            fprintf(stderr, "Error seeking file\n");
            continue;
        }
        if (fprintf(gpio_fd, "%ld,%f,%f\n", time(NULL), pressure, temperature) < 0) {
            fprintf(stderr, "Error writing to log file\n");
            continue;
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Close I2C and log file
    pigpioClose(i2c_fd);
    close(gpio_fd);

    // Terminate GPIO
    gpioTerminate();

    return 0;
}

void sigint_handler(int sig) {
    // Close I2C and log file
    pigpioClose(i2c_fd);
    close(gpio_fd);

    // Flush and close log file
    if (fdatasync(gpio_fd) < 0) {
        fprintf(stderr, "Error flushing log file\n");
    }
    if (close(gpio_fd) < 0) {
        fprintf(stderr, "Error closing log file\n");
    }

    // Terminate GPIO
    gpioTerminate();
}

