            perror("gpio_i2c_open");
            continue;
        }

        if (gpio_i2c_write(gpio, MEASUREMENT_COMMAND, 1) < 0) {
            perror("gpio_i2c_write");
            gpio_i2c_close(gpio);
            continue;
        }

        usleep(45000);

        if (gpio_i2c_read(gpio, MEASUREMENT_SIZE, NULL, NULL) < 0) {
            perror("gpio_i2c_read");
            gpio_i2c_close(gpio);
            continue;
        }

        unsigned char raw_pressure[DIFFERENTIAL_PRESSURE_SIZE];
        unsigned char raw_temperature[TEMPERATURE_SIZE];
        unsigned char raw_scale_factor[SCALE_FACTOR_SIZE];

        if (gpio_i2c_read(gpio, DIFFERENTIAL_PRESSURE_SIZE, raw_pressure, NULL) < 0) {
            perror("gpio_i2c_read");
            gpio_i2c_close(gpio);
            continue;
        }

        if (gpio_i2c_read(gpio, TEMPERATURE_SIZE, raw_temperature, NULL) < 0) {
            perror("gpio_i2c_read");
            gpio_i2c_close(gpio);
            continue;
        }

        if (gpio_i2c_read(gpio, SCALE_FACTOR_SIZE, raw_scale_factor, NULL) < 0) {
            perror("gpio_i2c_read");
            gpio_i2c_close(gpio);
            continue;
        }

        unsigned char crc8_diff = raw_pressure[0] ^ raw_pressure[1];
        unsigned char crc8_temp = raw_temperature[0] ^ raw_temperature[1];
        unsigned char crc8_scale = raw_scale_factor[0] ^ raw_scale_factor[1];

        if (crc8_diff != (crc8_diff ^ CRC_POLYNOMINAL) || crc8_temp != (crc8_temp ^ CRC_POLYNOMINAL) || crc8_scale != (crc8_scale ^ CRC_POLYNOMINAL)) {
            fprintf(log_file, "CRC error\n");
            continue;
        }

        float pressure_Pa = (raw_pressure[0] * raw_pressure[1] * 1000) / raw_scale_factor[0];
        float T = -45 + 175 * raw_temperature[0] / 65535;

        fprintf(log_file, "%ld,%f,%f\n", (long)clock_gettime(CLOCK_MONOTONIC.tv_sec + (clock_gettime(CLOCK_MONOTONIC.tv_nsec / 1000000000) * 1000000000) / 1000000, pressure_Pa, T);

        gpio_i2c_close(gpio);
        gpio_close(gpio);
        break;
    }

    fclose(log_file);
    pigpio_close(gpio);
    return 0;
}
```

This code uses the pigpio library to read from the Sensirion SDP810-500Pa sensor over the I2C bus. It sends the continuous-measurement command, waits for 45 ms, reads the 9 bytes of data, validates the CRC-8 values, and converts the raw data to pressure in Pascals and temperature in Celsius. It logs each reading to a file named "sdp810_log.txt" in CSV format once per second. If an error occurs, it logs the error and continues. On SIGINT, it closes the I2C handle, terminates pigpio, closes the log file, and exits cleanly.

