#define CALIBRATION_OFFSET 0x05
#define CALIBRATION_SIZE 4
#define PRESSURE_REGISTER 0x00
#define TEMPERATURE_REGISTER 0x01
#define PRESSURE_OFFSET 0x02
#define TEMPERATURE_OFFSET 0x03
#define PRESSURE_COEFFICIENT 0x04
#define TEMPERATURE_COEFFICIENT 0x05
#define PRESSURE_OFFSET_1 0x06
#define TEMPERATURE_OFFSET_1 0x07
#define PRESSURE_COEFFICIENT_1 0x08
#define TEMPERATURE_COEFFICIENT_1 0x09
#define PRESSURE_OFFSET_2 0x0A
#define TEMPERATURE_OFFSET_2 0x0B
#define PRESSURE_COEFFICIENT_2 0x0C
#define TEMPERATURE_COEFFICIENT_2 0x0D
#define PRESSURE_OFFSET_3 0x0E
#define TEMPERATURE_OFFSET_3 0x0F
#define PRESSURE_COEFFICIENT_3 0x10
#define TEMPERATURE_COEFFICIENT_3 0x11

int main(int argc, char *argv[]) {
    int i, j;
    int i2c_fd;
    int pressure_coefficient, temperature_coefficient;
    int pressure, temperature;
    struct timespec ts;
    struct timespec last_ts;
    struct sigaction sa;
    int exit_flag = 0;
    char filename[] = "environmental_data.txt";

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C bus 1
    if ((i2c_fd = i2cOpen(I2C_BUS_1, I2C_ADDRESS, 100)) < 0) {
        perror("i2cOpen");
        gpioTerminate();
        return 1;
    }

    // Verify sensor identity
    if (i2cReadI2CBlockData(i2c_fd, WHO_AM_I, 1, NULL, 1) < 0) {
        perror("i2cReadI2CBlockData");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (i2cReadI2CBlockData(i2c_fd, WHO_AM_I, 1, NULL, 1) != 0x08) {
        perror("i2cReadI2CBlockData");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Read calibration coefficients
    if (i2cReadI2CBlockData(i2c_fd, CALIBRATION_OFFSET, CALIBRATION_SIZE, NULL, CALIBRATION_SIZE) < 0) {
        perror("i2cReadI2CBlockData");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    for (i = 0; i < CALIBRATION_SIZE; i++) {
        if (i == 0) {
            pressure_coefficient = i2cReadI2CBlockData(i2c_fd, PRESSURE_OFFSET, 1, NULL, 1)[0];
        } else if (i == 1) {
            temperature_coefficient = i2cReadI2CBlockData(i2c_fd, TEMPERATURE_OFFSET, 1, NULL, 1)[0];
        } else if (i == 2) {
            pressure_coefficient = i2cReadI2CBlockData(i2c_fd, PRESSURE_OFFSET_1, 1, NULL, 1)[0];
        } else if (i == 3) {
            temperature_coefficient = i2cReadI2CBlockData(i2c_fd, TEMPERATURE_OFFSET_1, 1, NULL, 1)[0];
        } else if (i == 4) {
            pressure_coefficient = i2cReadI2CBlockData(i2c_fd, PRESSURE_OFFSET_2, 1, NULL, 1)[0];
        } else if (i == 5) {
            temperature_coefficient = i2cReadI2CBlockData(i2c_fd, TEMPERATURE_OFFSET_2, 1, NULL, 1)[0];
        } else if (i == 6) {
            pressure_coefficient = i2cReadI2CBlockData(i2c_fd, PRESSURE_OFFSET_3, 1, NULL, 1)[0];
        } else if (i == 7) {
            temperature_coefficient = i2cReadI2CBlockData(i2c_fd, TEMPERATURE_OFFSET_3, 1, NULL, 1)[0];
        } else if (i == 8) {
            pressure_coefficient = i2cReadI2CBlockData(i2c_fd, PRESSURE_OFFSET_4, 1, NULL, 1)[0];
        } else if (i == 9) {
            temperature_coefficient = i2cReadI2CBlockData(i2c_fd, TEMPERATURE_OFFSET_4, 1, NULL, 1)[0];
        }
    }

    // Main loop
    while (!exit_flag) {
        // Trigger measurement
        if (i2cWriteI2CBlockData(i2c_fd, PRESSURE_REGISTER, 1, &0x00, 1) < 0) {
            perror("i2cWriteI2CBlockData");
            continue;
        }
        usleep(10000);

        // Read pressure and temperature data
        if (i2cReadI2CBlockData(i2c_fd, PRESSURE_REGISTER, 6, NULL, 6) < 0) {
            perror("i2cReadI2CBlockData");
            continue;
        }
        pressure = (i2cReadI2CBlockData(i2c_fd, PRESSURE_REGISTER, 6, NULL, 6)[0] << 8) | i2cReadI2CBlockData(i2c_fd, PRESSURE_REGISTER, 6, NULL, 6)[1];
        temperature = (i2cReadI2CBlockData(i2c_fd, TEMPERATURE_REGISTER, 2, NULL, 2)[0] << 8) | i2cReadI2CBlockData(i2c_fd, TEMPERATURE_REGISTER, 2, NULL, 2)[1];

        // Convert to hPa and Celsius
        pressure /= pressure_coefficient;
        temperature /= temperature_coefficient;

        // Log and print data
        clock_gettime(CLOCK_REALTIME, &ts);
        if (ts.tv_sec != last_ts.tv_sec || ts.tv_nsec != last_ts.tv_nsec) {
            last_ts = ts;
            FILE *file = fopen(filename, "a");
            if (file == NULL) {
                perror("fopen");
                continue;
            }
            fprintf(file, "%Y-%m-%d %H:%M:%S.%06d %f %f\n", ts.tv_sec, pressure, temperature);
            fclose(file);
            fflush(file);
        }
        printf("%f %f\n", ts.tv_sec, temperature);

        // Check for SIGINT
        if (gpioGetSignalLevel(GPIOD_IRQ) != 0) {
            exit_flag = 1;
        }
    }

    // Clean up
    i2cClose(i2c_fd);
    gpioTerminate();

    return 0;
}

