#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

#define I2C_ADDRESS 0x5A
#define I2C Bus 1
#define GPIO_FAN 18
#define GPIO_FAN_HYST 2
#define GPIO_FAN_PIN GPIO_FAN
#define GPIO_FAN_ON 1
#define GPIO_FAN_OFF 0
#define TEMPERATURE_LOG_FILE "temperature_log.txt"

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up I2C
    if (gpioI2COpen(I2C Bus, I2C_ADDRESS) < 0) {
        perror("gpioI2COpen");
        gpioTerminate();
        return 1;
    }

    // Set up fan pin
    if (gpioMode(GPIO_FAN_PIN, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        gpioI2CClose(I2C Bus);
        gpioTerminate();
        return 1;
    }

    // Set up fan pin as output
    if (gpioWrite(GPIO_FAN_PIN, GPIO_FAN_OFF) < 0) {
        perror("gpioWrite");
        gpioI2CClose(I2C Bus);
        gpioTerminate();
        return 1;
    }

    // Set up fan pin with hysteresis
    if (gpioHysteresis(GPIO_FAN_PIN, GPIO_FAN_HYST) < 0) {
        perror("gpioHysteresis");
        gpioI2CClose(I2C Bus);
        gpioTerminate();
        return 1;
    }

    // Set up fan pin as output
    if (gpioWrite(GPIO_FAN_PIN, GPIO_FAN_OFF) < 0) {
        perror("gpioWrite");
        gpioI2CClose(I2C Bus);
        gpioTerminate();
        return 1;
    }

    // Read temperature from I2C
    unsigned char raw_ambient, raw_object;
    int retry = 0;
    while (1) {
        // Read ambient temperature
        if (gpioI2CRead(I2C Bus, I2C_ADDRESS, 0x06, &raw_ambient) < 0) {
            if (retry < 3) {
                usleep(10);
                retry++;
            } else {
                printf("Failed to read ambient temperature\n");
                break;
            }
        } else {
            retry = 0;
        }

        if (retry == 0) {
            // Convert raw ambient temperature to Celsius
            float ambient_temperature = (raw_ambient * 0.02) - 273.15;
            printf("%f %f\n", time(NULL), ambient_temperature);

            // Read object temperature
            if (gpioI2CRead(I2C Bus, I2C_ADDRESS, 0x07, &raw_object) < 0) {
                if (retry < 3) {
                    usleep(10);
                    retry++;
                } else {
                    printf("Failed to read object temperature\n");
                    break;
                }
            } else {
                retry = 0;
            }

            if (retry == 0) {
                // Convert raw object temperature to Celsius
                float object_temperature = (raw_object * 0.02) - 273.15;
                printf("%f %f\n", time(NULL), object_temperature);

                // Log temperature to file
                FILE *log_file = fopen(TEMPERATURE_LOG_FILE, "a");
                if (log_file == NULL) {
                    perror("fopen");
                    break;
                }

                fprintf(log_file, "%f %f %f\n", time(NULL), ambient_temperature, object_temperature);
                fclose(log_file);

                // Turn on fan if object temperature exceeds 30 °C
                if (object_temperature > 30) {
                    gpioWrite(GPIO_FAN_PIN, GPIO_FAN_ON);
                } else {
                    gpioWrite(GPIO_FAN_PIN, GPIO_FAN_OFF);
                }
            }
        }
    }

    // Clean up
    gpioI2CClose(I2C Bus);
    gpioTerminate();

    return 0;
}

