#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

#define I2C_ADDRESS 0x48
#define I2C_BUS 1
#define REG_ADDRESS 0x00
#define REG_LENGTH 12
#define REG_SHIFT 4
#define REG_MULTIPLIER 0.0625
#define CSV_FILE "temperature_log.csv"

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C handle
    int i2c_fd = pigpio_i2c_open(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_fd < 0) {
        perror("pigpio_i2c_open");
        gpioTerminate();
        return 1;
    }

    // Open CSV file for writing
    FILE *file = fopen(CSV_FILE, "a");
    if (file == NULL) {
        perror("fopen");
        pigpio_i2c_close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        fclose(file);
        pigpio_i2c_close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read 12-bit value from register
        uint16_t value = pigpio_i2c_read(i2c_fd, REG_ADDRESS, REG_LENGTH);
        if (value < 0) {
            perror("pigpio_i2c_read");
            continue;
        }

        // Shift right by 4 bits and multiply by 0.0625
        double temperature = (value >> REG_SHIFT) * REG_MULTIPLIER;

        // Format timestamp
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Log to CSV file
        fprintf(file, "%s,%.2f\n", timestamp, temperature);
        if (ferror(file)) {
            perror("fprintf");
            continue;
        }

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    pigpio_i2c_close(i2c_fd);
    gpioTerminate();
    fclose(file);
    return 0;
}

