#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

#define I2C_ADDRESS 0x40
#define MEASUREMENT_CONFIG 0x0E
#define CONFIG_HEATER_DISABLED 0x00
#define CONFIG_RESOLUTION_14BIT 0x14
#define MEASUREMENT_CONFIG_BIT0 0x01
#define MEASUREMENT_CONFIG_BIT0_CLEAR 0x00
#define MEASUREMENT_CONFIG_BIT0_SET 0x01
#define MEASUREMENT_CONFIG_TIMEOUT 500
#define MEASUREMENT_CONFIG_RETRY_COUNT 5

volatile sig_atomic_t sig_atomic_flag = 0;

void sig_handler(int sig) {
    sig_atomic_flag = 1;
}

int main() {
    int retry_count = 0;
    int i2c_handle;
    int raw_temperature, raw_humidity;
    int temperature, humidity;
    struct timespec timeout;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, sig_handler);

    // Open I2C handle
    if ((i2c_handle = i2cOpen(1, I2C_ADDRESS, 0)) < 0) {
        perror("i2cOpen");
        gpioTerminate();
        return 1;
    }

    while (!sig_atomic_flag) {
        // Trigger measurement
        if (i2cWrite(i2c_handle, MEASUREMENT_CONFIG, MEASUREMENT_CONFIG_BIT0_SET) < 0) {
            if (errno == EIO) {
                retry_count++;
                if (retry_count >= MEASUREMENT_CONFIG_RETRY_COUNT) {
                    printf("I2C error: unable to trigger measurement\n");
                    break;
                }
                usleep(100000);
                continue;
            } else {
                perror("i2cWrite");
                gpioTerminate();
                return 1;
            }
        }

        // Wait for measurement to complete
        timeout.tv_sec = MEASUREMENT_CONFIG_TIMEOUT / 1000;
        timeout.tv_nsec = (MEASUREMENT_CONFIG_TIMEOUT % 1000) * 1000000;
        if (nanosleep(&timeout, NULL) < 0) {
            perror("nanosleep");
            gpioTerminate();
            return 1;
        }

        // Check for measurement complete
        if (i2cRead(i2c_handle, MEASUREMENT_CONFIG, &raw_temperature) < 0) {
            if (errno == EIO) {
                retry_count++;
                if (retry_count >= MEASUREMENT_CONFIG_RETRY_COUNT) {
                    printf("I2C error: unable to read measurement\n");
                    break;
                }
                usleep(100000);
                continue;
            } else {
                perror("i2cRead");
                gpioTerminate();
                return 1;
            }
        }

        // Check for NAK or bus error
        if (raw_temperature & 0x80) {
            printf("NAK: unable to read measurement\n");
            break;
        }

        // Read temperature and humidity
        if (i2cRead(i2c_handle, 0x00, &raw_temperature) < 0) {
            if (errno == EIO) {
                retry_count++;
                if (retry_count >= MEASUREMENT_CONFIG_RETRY_COUNT) {
                    printf("I2C error: unable to read temperature\n");
                    break;
                }
                usleep(100000);
                continue;
            } else {
                perror("i2cRead");
                gpioTerminate();
                return 1;
            }
        }

        if (i2cRead(i2c_handle, 0x01, &raw_humidity) < 0) {
            if (errno == EIO) {
                retry_count++;
                if (retry_count >= MEASUREMENT_CONFIG_RETRY_COUNT) {
                    printf("I2C error: unable to read humidity\n");
                    break;
                }
                usleep(100000);
                continue;
            } else {
                perror("i2cRead");
                gpioTerminate();
                return 1;
            }
        }

        // Convert temperature and humidity
        temperature = raw_temperature / 65536 * 165 - 40;
        humidity = raw_humidity / 65536 * 100;

        printf("Temperature: %d°C, Humidity: %d%%\n", temperature, humidity);

        // Reset measurement configuration
        if (i2cWrite(i2c_handle, MEASUREMENT_CONFIG, MEASUREMENT_CONFIG_BIT0_CLEAR) < 0) {
            if (errno == EIO) {
                retry_count++;
                if (retry_count >= MEASUREMENT_CONFIG_RETRY_COUNT) {
                    printf("I2C error: unable to reset measurement\n");
                    break;
                }
                usleep(100000);
                continue;
            } else {
                perror("i2cWrite");
                gpioTerminate();
                return 1;
            }
        }
    }

    // Close I2C handle
    if (i2cClose(i2c_handle) < 0) {
        perror("i2cClose");
        return 1;
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

