#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

#define I2C_ADDRESS 0x25
#define I2C_ADDRESS_1 0x1E
#define CONTINUOUS_MEASUREMENT 0x362F
#define MEASUREMENT_SIZE 8
#define CRC_8_POLYNOMIAL 0x31
#define CRC_8_INIT_VALUE 0xFF

void sigint_handler(int sig) {
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up I2C
    if (gpioI2CSetup(1, 100000, 0) < 0) {
        perror("gpioI2CSetup");
        gpioTerminate();
        return 1;
    }

    // Set up I2C address
    if (gpioI2CWrite(1, I2C_ADDRESS, 0x00) < 0) {
        perror("gpioI2CWrite");
        gpioTerminate();
        return 1;
    }

    // Set up continuous measurement
    if (gpioI2CWrite(1, I2C_ADDRESS, CONTINUOUS_MEASUREMENT) < 0) {
        perror("gpioI2CWrite");
        gpioTerminate();
        return 1;
    }

    // Wait for measurement to complete
    usleep(45);

    // Read measurement data
    uint8_t data[MEASUREMENT_SIZE];
    if (gpioI2CRead(1, I2C_ADDRESS, data, MEASUREMENT_SIZE) < 0) {
        perror("gpioI2CRead");
        gpioTerminate();
        return 1;
    }

    // Calculate CRC-8 checksum
    uint8_t crc = 0;
    for (int i = 0; i < MEASUREMENT_SIZE; i += 2) {
        uint16_t word = (data[i] << 8) | data[i + 1];
        crc = crc8(crc, word, CRC_8_POLYNOMIAL);
    }

    // Check CRC-8 checksum
    if (crc != data[MEASUREMENT_SIZE - 1]) {
        printf("CRC-8 checksum error\n");
        gpioTerminate();
        return 1;
    }

    // Read temperature
    uint16_t temperature = (data[MEASUREMENT_SIZE - 2] << 8) | data[MEASUREMENT_SIZE - 1];
    printf("Temperature: %d\n", temperature);

    // Read pressure
    uint16_t pressure = (data[MEASUREMENT_SIZE - 4] << 8) | data[MEASUREMENT_SIZE - 3];
    printf("Pressure: %d Pa\n", pressure);

    // Sleep for 500 ms
    usleep(500000);

    // Clean up
    gpioTerminate();
    return 0;
}

uint8_t crc8(uint8_t crc, uint16_t word, uint8_t polynomial) {
    crc = (crc ^ word);
    for (int i = 0; i < 8; i++) {
        if (crc & 0x80) {
            crc = (crc ^ polynomial);
        }
        crc = (crc << 1) ^ (crc >> 7);
    }
    return crc;
}
