#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>

#define I2C_ADDRESS 0x76
#define I2C_RETRY_ATTEMPTS 3
#define I2C_RETRY_DELAY 10
#define I2C_TIMEOUT 100
#define PRESSURE_LOG_FILE "pressure_log.txt"

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up I2C
    int i2c_fd = -1;
    for (int retry = 0; retry < I2C_RETRY_ATTEMPTS; retry++) {
        i2c_fd = i2cOpen(I2C_ADDRESS, I2C_TIMEOUT);
        if (i2c_fd >= 0) {
            break;
        }
        usleep(I2C_RETRY_DELAY * 1000);
    }
    if (i2c_fd < 0) {
        perror("i2cOpen");
        return 1;
    }

    // Verify chip ID
    uint8_t chip_id;
    if (i2cRead(i2c_fd, 0xD0, 1, &chip_id) < 0) {
        perror("i2cRead");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (chip_id != 0x58) {
        printf("Invalid chip ID 0x%02x\n", chip_id);
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Read calibration block
    uint8_t calibration_block[24];
    if (i2cRead(i2c_fd, 0x88, 24, calibration_block) < 0) {
        perror("i2cRead");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Configure ctrl_meas
    uint8_t ctrl_meas = 0x27;
    ctrl_meas |= 0x01; // Forced mode
    if (i2cWrite(i2c_fd, 0xF4, 1, &ctrl_meas) < 0) {
        perror("i2cWrite");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Wait for conversion completion
        usleep(10);

        // Read raw data
        uint16_t raw_data[6];
        if (i2cRead(i2c_fd, 0xF7, 6, raw_data) < 0) {
            perror("i2cRead");
            i2cClose(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Apply Bosch compensation formulas
        uint16_t pressure = (raw_data[0] << 8) | raw_data[1];
        uint16_t temperature = (raw_data[2] << 8) | raw_data[3];
        pressure = pressure * calibration_block[0] + temperature * calibration_block[1] + calibration_block[2];
        temperature = temperature * calibration_block[3] + calibration_block[4] + calibration_block[5];

        // Check pressure threshold
        if (pressure > 1020) {
            printf("Pressure breach: %d hPa\n", pressure);
            FILE *fp = fopen(PRESSURE_LOG_FILE, "a");
            if (fp == NULL) {
                perror("fopen");
                continue;
            }
            fprintf(fp, "%d %d\n", time(NULL), pressure);
            fclose(fp);
        } else if (pressure < 980) {
            printf("Pressure breach: %d hPa\n", pressure);
            FILE *fp = fopen(PRESSURE_LOG_FILE, "a");
            if (fp == NULL) {
                perror("fopen");
                continue;
            }
            fprintf(fp, "%d %d\n", time(NULL), pressure);
            fclose(fp);
        }

        // Trigger measurement
        ctrl_meas |= 0x01;
        if (i2cWrite(i2c_fd, 0xF4, 1, &ctrl_meas) < 0) {
            perror("i2cWrite");
            i2cClose(i2c_fd);
            gpioTerminate();
            return 1;
        }
    }

    // Clean up
    i2cClose(i2c_fd);
    gpioTerminate();
    return 0;
}

// Signal handler for SIGINT
void sigint_handler(int sig) {
    i2cClose(i2c_fd);
    gpioTerminate();
    exit(0);
}

// Signal handler for SIGTERM
void sigterm_handler(int sig) {
    i2cClose(i2c_fd);
    gpioTerminate();
    exit(0);
}

// Register signal handlers
void sigaction_handler(int sig) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(sig, &sa, NULL) < 0) {
        perror("sigaction");
        exit(1);
    }
    sigaction(SIGTERM, &sigterm_handler, NULL);
}

int main() {
    sigaction(SIGINT, &sigaction_handler, NULL);
    return main();
}

