#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define constants for GPIO pins
#define RED_PIN 17
#define GREEN_PIN 22
#define BLUE_PIN 27

// Define constants for PWM frequency and duty cycle
#define PWM_FREQ 1000
#define PWM_DUTY_CYCLE 0.5

// Define constants for color mapping
#define RED 0xFF0000
#define GREEN 0xFFFF00
#define BLUE 0x00FF00

// Define a function to map CPU load to a color
uint32_t cpuLoadToColor(float load) {
    if (load < 0.5) {
        return GREEN;
    } else if (load < 1.0) {
        return (uint32_t)((load - 0.5) * 2 * RED);
    } else {
        return RED;
    }
}

// Define a function to update the LED based on CPU load
void updateLED(pigpio *gpio) {
    // Read the current CPU load
    FILE *statFile = fopen("/proc/stat", "r");
    if (statFile == NULL) {
        perror("Error opening /proc/stat");
        return;
    }

    char loadStr[256];
    fscanf(statFile, "%*s %lf", loadStr);
    float load = atof(loadStr);

    // Update the LED color based on the CPU load
    uint32_t color = cpuLoadToColor(load);

    // Set the PWM duty cycle for each color channel
    gpioSet PWM(gpio, RED_PIN, PWM_FREQ, (int)(color >> 16 & 0xFF));
    gpioSet PWM(gpio, GREEN_PIN, PWM_FREQ, (int)(color >> 8 & 0xFF));
    gpioSet PWM(gpio, BLUE_PIN, PWM_FREQ, (int)(color & 0xFF));

    // Flush the changes to the GPIO pins
    gpioFlush(gpio);

    // Close the stat file
    fclose(statFile);
}

// Define a function to handle SIGINT
void sigintHandler(int sig) {
    // Turn off the LED
    gpioSet PWM(gpio, RED_PIN, PWM_FREQ, 0);
    gpioSet PWM(gpio, GREEN_PIN, PWM_FREQ, 0);
    gpioSet PWM(gpio, BLUE_PIN, PWM_FREQ, 0);

    // Cleanly exit the process
    gpioTerminate(gpio);
    exit(0);
}

// Define a function to handle SIGTERM
void sigtermHandler(int sig) {
    // Turn off the LED
    gpioSet PWM(gpio, RED_PIN, PWM_FREQ, 0);
    gpioSet PWM(gpio, GREEN_PIN, PWM_FREQ, 0);
    gpioSet PWM(gpio, BLUE_PIN, PWM_FREQ, 0);

    // Cleanly exit the process
    gpioTerminate(gpio);
    exit(0);
}

int main() {
    // Initialize pigpio
    pigpio = pigpio_init();
    if (pigpio == -1) {
        fprintf(stderr, "Error initializing pigpio: %s\n", strerror(errno));
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, sigintHandler);
    signal(SIGTERM, sigtermHandler);

    // Set up the PWM pins
    gpioInitialise(gpio, NULL);
    gpioSet PWM(gpio, RED_PIN, PWM_FREQ, 0);
    gpioSet PWM(gpio, GREEN_PIN, PWM_FREQ, 0);
    gpioSet PWM(gpio, BLUE_PIN, PWM_FREQ, 0);

    // Update the LED every 500 ms
    while (1) {
        updateLED(gpio);
        usleep(500000);
    }

    // Cleanly exit the process
    gpioTerminate(gpio);
    return 0;
}

