    struct sigaction sa;
    struct sigaction sa_int;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open SPI channel 0
    if ((fd = spiOpen(0, 0, 500000)) < 0) {
        perror("spiOpen");
        gpioTerminate();
        return 1;
    }

    // Open PWM channel 18
    if ((gpio_fd = gpioOpen(18, GPIO_MODE PWM, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioOpen");
        spiClose(fd);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    if (gpioPWM(gpio_fd, 1000) < 0) {
        perror("gpioPWM");
        gpioClose(gpio_fd);
        spiClose(fd);
        gpioTerminate();
        return 1;
    }

    // Set PWM duty range
    if (gpioPWM(gpio_fd, MAX_DUTY) < 0) {
        perror("gpioPWM");
        gpioClose(gpio_fd);
        spiClose(fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioClose(gpio_fd);
        spiClose(fd);
        gpioTerminate();
        return 1;
    }

    sa_int.sa_handler = sigint_handler;
    sa_int.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa_int, NULL) < 0) {
        perror("sigaction");
        gpioClose(gpio_fd);
        spiClose(fd);
        gpioTerminate();
        return 1;
    }

