    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up GPIO2 as a falling-edge triggered interrupt
    if (gpioMode(GPIO_PIN, PI_INPUT) < 0) {
        perror("gpioMode");
        return 1;
    }
    if (gpioPullUpDn(GPIO_PIN, PI_HIGH) < 0) {
        perror("gpioPullUpDn");
        return 1;
    }
    if (gpioEdge(GPIO_PIN, PI_FALLING_EDGE, GPIO Callback) < 0) {
        perror("gpioEdge");
        return 1;
    }

    // Open I2C file
    int fd = open(FILE_NAME, O_RDWR | O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set up I2C
    if (i2cInit(I2C_BUS, I2C_ADDRESS) < 0) {
        perror("i2cInit");
        return 1;
    }

    // Read calibration data
    unsigned char cal_data[6];
    if (i2cWrite(I2C_BUS, I2C_ADDRESS, 0x00, 1, cal_data) < 0) {
        perror("i2cWrite");
        return 1;
    }
    if (i2cRead(I2C_BUS, I2C_ADDRESS, 0x00, 1, cal_data) < 0) {
        perror("i2cRead");
        return 1;
    }
    if (cal_data[0] != 0x00 || cal_data[1] != 0x00 || cal_data[2] != 0x00 || cal_data[3] != 0x00 || cal_data[4] != 0x00 || cal_data[5] != 0x00) {
        printf("Calibration data is invalid\n");
        return 1;
    }

    // Set oversampling to 3
    if (i2cWrite(I2C_BUS, I2C_ADDRESS, 0x00, 0x03, 1) < 0) {
        perror("i2cWrite");
        return 1;
    }

    // Main loop
    while (1) {
        // Read pressure and temperature
        unsigned char pressure_data[3];
        unsigned char temperature_data[2];
        if (i2cRead(I2C_BUS, I2C_ADDRESS, 0x00, 3, pressure_data) < 0) {
            perror("i2cRead");
            return 1;
        }
        if (i2cRead(I2C_BUS, I2C_ADDRESS, 0x00, 2, temperature_data) < 0) {
            perror("i2cRead");
            return 1;
        }
        if (pressure_data[0] != 0x00 || pressure_data[1] != 0x00 || pressure_data[2] != 0x00 || temperature_data[0] != 0x00 || temperature_data[1] != 0x00) {
            printf("Data is invalid\n");
            return 1;
        }

        // Convert pressure to Pa
        float pressure = (pressure_data[0] << 8) | pressure_data[1];

        // Convert temperature to Celsius
        float temperature = (temperature_data[0] << 8) | temperature_data[1];

        // Log data
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(NULL));
        fprintf(fd, "%s,%f,%f\n", timestamp, temperature, pressure);

        // Toggle data logging
        if (gpioRead(GPIO_PIN) == 0) {
            printf("Logging data...\n");
            // Toggle GPIO2
            gpioToggle(GPIO_PIN);
        } else {
            printf("Not logging data...\n");
            // Toggle GPIO2
            gpioToggle(GPIO_PIN);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    gpioCleanse(GPIO_PIN);
    gpioTerminate();
    close(fd);
    return 0;
}

