#define RTD_REG_T 0x01
#define RTD_REG_F 0x02
#define RTD_REG_BIAS 0x03
#define RTD_REG_FAULT 0x04

// Define the Callendar-Van Dusen equation constants
#define CV_D 0.0033928
#define CV_C1 0.0001500
#define CV_C2 0.0000005
#define CV_C3 0.0000000003

// Define the SPI device file descriptor
int spidev_fd = -1;

// Define the chip-select line file descriptor
int cs_fd = -1;

// Define the log file descriptor
int log_fd = -1;

// Define the log file pointer
FILE *log_file = NULL;

// Define the log line counter
int log_line = 0;

// Define the log line buffer
char log_line_buf[MAX_LOG_LINE];

// Define the RTD register values
int rtd_reg_r = 0;
int rtd_reg_t = 0;
int rtd_reg_f = 0;
int rtd_reg_bias = 0;
int rtd_reg_fault = 0;

// Define the temperature value
float temperature = 0.0;

// Define the signal handlers
void sigint_handler(int sig) {
    close(spidev_fd);
    close(cs_fd);
    close(log_fd);
    exit(0);
}

void sigterm_handler(int sig) {
    close(spidev_fd);
    close(cs_fd);
    close(log_fd);
    exit(0);
}

int main(int argc, char **argv) {
    // Initialize signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open the chip-select line
    cs_fd = gpiod_open("gpio-8", GPIOD_MODE_OUTPUT, 0);
    if (cs_fd < 0) {
        perror("gpiod_open");
        return 1;
    }

    // Open the SPI device
    spidev_fd = spidev_open("/dev/spidev0.0", 0, 0);
    if (spidev_fd < 0) {
        perror("spidev_open");
        return 1;
    }

    // Initialize the MAX31865
    rtd_reg_bias = 0x00;
    rtd_reg_fault = 0;
    rtd_reg_r = 0;
    rtd_reg_t = 0;

    // Open the log file
    log_fd = fopen(MAX_LOG_FILE, "a");
    if (log_fd < 0) {
        perror("fopen");
        return 1;
    }

    while (1) {
        // Set the chip-select line high
        gpiod_write(cs_fd, 1);

        // Send the SPI command to read the RTD register
        if (spidev_write(spidev_fd, 0x00, 0x00) < 0) {
            perror("spidev_write");
            continue;
        }

        // Read the RTD register
        if (spidev_read(spidev_fd, 0x00, &rtd_reg_r, 1) < 0) {
            perror("spidev_read");
            continue;
        }

        // Read the RTD register
        if (spidev_read(spidev_fd, 0x00, &rtd_reg_t, 1) < 0) {
            perror("spidev_read");
            continue;
        }

        // Read the RTD register
        if (spidev_read(spidev_fd, 0x00, &rtd_reg_f, 1) < 0) {
            perror("spidev_read");
            continue;
        }

        // Check the fault status register
        if (spidev_read(spidev_fd, 0x00, &rtd_reg_fault, 1) < 0) {
            perror("spidev_read");
            continue;
        }

        // Calculate the temperature
        if (rtd_reg_fault) {
            temperature = -273.15;
        } else {
            temperature = (rtd_reg_t * CV_D) + (rtd_reg_f * CV_C1) + (rtd_reg_f * CV_C2) + (rtd_reg_f * CV_C3);
        }

        // Log the temperature
        sprintf(log_line_buf, "%f\n", temperature);
        if (fwrite(log_line_buf, strlen(log_line_buf), 1, log_fd) < 0) {
            perror("fwrite");
            continue;
        }

        // Increment the log line counter
        log_line++;

        // Check if the log file is full
        if (log_line >= MAX_LOG_LINES) {
            fclose(log_file);
            log_fd = -1;
            log_file = fopen(MAX_LOG_FILE, "w");
            if (log_file < 0) {
                perror("fopen");
                continue;
            }
            log_line = 0;
        }

        // Delay for 5 seconds
        usleep(5000000);
    }

    // Close the log file
    if (log_fd >= 0) {
        fclose(log_file);
    }

    // Close the chip-select line
    if (cs_fd >= 0) {
        gpiod_close(cs_fd);
    }

    // Close the SPI device
    if (spidev_fd >= 0) {
        spidev_close(spidev_fd);
    }

    return 0;
}

