            log_fd = -1;
            log_file = fopen(MAX_LOG_FILE, "w");
            if (log_file < 0) {
                perror("fopen");
                continue;
            }
            log_line = 0;
        }

        // Delay for 5 seconds
        usleep(5000000);
    }

    // Close the log file
    if (log_fd >= 0) {
        fclose(log_file);
    }

    // Close the chip-select line
    if (cs_fd >= 0) {
        gpiod_close(cs_fd);
    }

    // Close the SPI device
    if (spidev_fd >= 0) {
        spidev_close(spidev_fd);
    }

    return 0;
}
