#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <time.h>

#define I2C_ADDRESS 0x76
#define I2C_BUS 1
#define I2C_SDA GPIO2
#define I2C_SCL GPIO3
#define CSV_FILE "bme280_log.csv"

int main(int argc, char **argv) {
    // Initialize signal handlers
    struct sigaction sa;
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Open I2C device
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    // Set I2C bus parameters
    if (ioctl(fd, I2C_SLAVE, I2C_BUS) == -1) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    // Set I2C clock speed
    if (ioctl(fd, I2C_SMBUS, I2C_SLAVE, I2C_ADDRESS) == -1) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    // Check BME280 chip ID
    unsigned char bme280_id;
    if (read(fd, &bme280_id, 1) != 1) {
        perror("read");
        close(fd);
        return 1;
    }
    if (bme280_id != 0x60) {
        fprintf(stderr, "Invalid BME280 chip ID 0x%02x\n", bme280_id);
        close(fd);
        return 1;
    }

    // Open CSV file
    int csv_fd = open(CSV_FILE, O_RDWR | O_CREAT | O_TRUNC, 0644);
    if (csv_fd == -1) {
        perror("open");
        close(fd);
        return 1;
    }

    // Map CSV file to memory
    struct iovec iov;
    iov.iov_base = mmap(NULL, 0, PROT_READ | PROT_WRITE, MAP_SHARED, csv_fd, 0);
    if (iov.iov_base == MAP_FAILED) {
        perror("mmap");
        close(csv_fd);
        close(fd);
        return 1;
    }

    while (1) {
        // Read BME280 data
        unsigned char bme280_data[7];
        if (read(fd, bme280_data, 7) != 7) {
            perror("read");
            close(csv_fd);
            close(fd);
            return 1;
        }

        // Extract temperature, humidity, and pressure
        float temperature = (bme280_data[0] << 8) | bme280_data[1];
        float humidity = (bme280_data[2] << 8) | bme280_data[3];
        float pressure = (bme280_data[4] << 8) | bme280_data[5];

        // Convert temperature to Celsius
        temperature /= 100;

        // Format timestamp
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Write to CSV file
        char *ptr = iov.iov_base;
        fwrite(timestamp, 20, 1, csv_fd);
        fwrite(&temperature, sizeof(float), 1, csv_fd);
        fwrite(&humidity, sizeof(float), 1, csv_fd);
        fwrite(&pressure, sizeof(float), 1, csv_fd);
        ptr += 20 + sizeof(float) * 3;

        // Flush file buffer
        fflush(csv_fd);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close file descriptors
    close(csv_fd);
    close(fd);

    return 0;
}

