#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <syslog.h>

#define GPIO18 18
#define PWM_FREQ 25000
#define PWM_MAX 255
#define PWM_MIN 0
#define TEMPERATURE_THRESHOLD 40
#define TEMPERATURE_MAX 70

int main(int argc, char **argv) {
    int fd;
    int pwm_fd;
    int ret;
    int pwm;
    int temperature;
    char log_file[] = "fan_log.txt";
    char log_buf[1024];

    // Initialize pigpio
    if ((ret = pigpio_init()) != 0) {
        syslog(LOG_ERR, "pigpio_init failed: %d", ret);
        return 1;
    }

    // Open log file for writing
    if ((fd = open(log_file, O_WRONLY | O_CREAT | O_APPEND, 0644)) == -1) {
        syslog(LOG_ERR, "open %s failed: %d", log_file, errno);
        pigpio_cleanup();
        return 1;
    }

    // Set up PWM
    if ((pwm_fd = pigpio_openwiringpi(GPIO18, PWM_FREQ)) == -1) {
        syslog(LOG_ERR, "pigpio_openwiringpi failed: %d", pwm_fd);
        close(fd);
        pigpio_cleanup();
        return 1;
    }

    while (1) {
        // Read temperature
        if ((ret = pigpio_readwiringpi(GPIO18, &temperature)) != 0) {
            syslog(LOG_ERR, "pigpio_readwiringpi failed: %d", ret);
            close(fd);
            pigpio_closewiringpi(pwm_fd);
            close(fd);
            pigpio_cleanup();
            return 1;
        }

        // Map temperature to duty cycle
        if (temperature < TEMPERATURE_THRESHOLD) {
            pwm = (int)((temperature * PWM_MAX) / (TEMPERATURE_MAX - TEMPERATURE_THRESHOLD) * PWM_MAX);
        } else if (temperature > TEMPERATURE_MAX) {
            pwm = PWM_MAX;
        } else {
            pwm = (int)((temperature - TEMPERATURE_THRESHOLD) * PWM_MAX / (TEMPERATURE_MAX - TEMPERATURE_THRESHOLD) * PWM_MAX);
        }

        // Clamp duty cycle
        pwm = (pwm < PWM_MIN) ? PWM_MIN : (pwm > PWM_MAX) ? PWM_MAX : pwm;

        // Set PWM
        if ((ret = pigpio_writewiringpi(pwm_fd, pwm)) != 0) {
            syslog(LOG_ERR, "pigpio_writewiringpi failed: %d", ret);
            close(fd);
            pigpio_closewiringpi(pwm_fd);
            close(fd);
            pigpio_cleanup();
            return 1;
        }

        // Log
        strftime(log_buf, sizeof(log_buf), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL));
        strcat(log_buf, " Temperature: %d°C Duty: %d%%\n", temperature, pwm);
        if (write(fd, log_buf, strlen(log_buf)) != strlen(log_buf)) {
            syslog(LOG_ERR, "write to %s failed: %d", log_file, errno);
        }

        // Sleep
        usleep(5000000);
    }

    // Clean up
    close(fd);
    pigpio_closewiringpi(pwm_fd);
    pigpio_cleanup();
    return 0;
}

