#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <signal.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_ADDRESS 0x76
#define I2C_ADDRESS_FALBACK 0x77
#define I2C_FILE "/dev/i2c-1"
#define I2C_SDA GPIO2
#define I2C_SCL GPIO3
#define I2C_MODE I2C_MODE_SMBUS
#define I2C_TIMEOUT 1000

int main() {
    int fd;
    struct i2c_client *client;
    void *mem;
    unsigned char buf[24];
    unsigned char ctrl_meas = 0;
    unsigned char dig_T1[6];
    unsigned char dig_P[6];
    unsigned char press_msb[6];
    unsigned short temp, press;
    struct timespec t;
    struct stat sb;
    struct i2c_msg msg;
    struct i2c_file *file;
    char timestamp[20];
    char error[256];

    // Initialize signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open I2C file descriptor
    fd = open(I2C_FILE, O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set I2C parameters
    msg.msg_ioctl = I2C_RDWR;
    msg.msg_addr = I2C_ADDRESS;
    msg.msg_flags = I2C_MODE;
    msg.msg_flags |= I2C_SMBUS_WRITE;
    msg.msg_buf = &ctrl_meas;
    msg.msg_len = sizeof(ctrl_meas);

    // Read chip ID
    if (ioctl(fd, msg.msg_ioctl, &msg) < 0) {
        perror("ioctl");
        return 1;
    }
    if (ctrl_meas != 0x58) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02x\n", ctrl_meas);
        return 1;
    }

    // Read calibration block
    msg.msg_addr = I2C_ADDRESS;
    msg.msg_flags = I2C_MODE;
    msg.msg_flags |= I2C_SMBUS_READ;
    msg.msg_buf = buf;
    msg.msg_len = sizeof(buf);
    if (ioctl(fd, msg.msg_ioctl, &msg) < 0) {
        perror("ioctl");
        return 1;
    }

    // Apply Bosch 64-bit compensation formulas
    for (int i = 0; i < 6; i++) {
        dig_T1[i] = buf[i];
        dig_P[i] = buf[i + 6];
    }
    for (int i = 0; i < 6; i++) {
        temp = (dig_T1[i] << 8) | dig_T1[i + 1];
        press = (dig_P[i] << 8) | dig_P[i + 1];
        temp = temp - 273.15;
        press = press * 0.001;
        printf("dig_T1[%d] = %d\n", i, temp);
        printf("dig_P[%d] = %d\n", i, press);
    }

    // Configure ctrl_meas for forced mode with oversampling x1
    msg.msg_addr = I2C_ADDRESS;
    msg.msg_flags = I2C_MODE;
    msg.msg_flags |= I2C_SMBUS_WRITE;
    msg.msg_buf = &ctrl_meas;
    msg.msg_len = sizeof(ctrl_meas);
    if (ioctl(fd, msg.msg_ioctl, &msg) < 0) {
        perror("ioctl");
        return 1;
    }

    // Poll status register until measuring
    while (1) {
        struct i2c_msg msg2;
        msg2.msg_addr = I2C_ADDRESS;
        msg2.msg_flags = I2C_MODE;
        msg2.msg_flags |= I2C_SMBUS_READ;
        msg2.msg_buf = &msg2.msg_ioctl;
        msg2.msg_len = sizeof(msg2.msg_ioctl);
        if (ioctl(fd, msg2.msg_ioctl, &msg2) < 0) {
            perror("ioctl");
            return 1;
        }
        if (msg2.msg_ioctl & 0x80) {
            // Measuring, wait for it to clear
            usleep(I2C_TIMEOUT * 1000);
        } else {
            // Not measuring, read raw data
            msg2.msg_addr = I2C_ADDRESS;
            msg2.msg_flags = I2C_MODE;
            msg2.msg_flags |= I2C_SMBUS_READ;
            msg2.msg_buf = &press_msb;
            msg2.msg_len = sizeof(press_msb);
            if (ioctl(fd, msg2.msg_ioctl, &msg2) < 0) {
                perror("ioctl");
                return 1;
            }
            for (int i = 0; i < 6; i++) {
                press_msb[i] = press_msb[i] >> 8;
            }
            temp = (press_msb[0] << 8) | press_msb[1];
            press = temp * 0.01;
            printf("Temperature: %.2f °C, Pressure: %.2f hPa\n", temp, press);
            // Log to file
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            file = fopen("weather_data.txt", "a");
            if (file == NULL) {
                perror("fopen");
                return 1;
            }
            fprintf(file, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", timestamp, temp, press);
            fclose(file);
            // Sleep for 5 seconds before next measurement
            sleep(5);
        }
    }

    return 0;
}

void sigint_handler(int sig) {
    close(fd);
    exit(0);
}

void sigterm_handler(int sig) {
    close(fd);
    exit(0);
}

