#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <libgpiod/libgpiod.h>
#include <libgpiod/async.h>
#include <libgpiod/async/async.h>
#include <libgpiod/async/async-poll.h>
#include <libgpiod/async/async-queue.h>
#include <libgpiod/async/async-queue-async.h>

#define BUFFER_SIZE 60
#define BUFFER_NAME "/tmp/temperature_buffer"
#define BUFFER_FILE_MODE 0644
#define GPIO_PIN 18
#define I2C_ADDRESS 0x48
#define I2C Bus 1

// Structure to hold temperature data
typedef struct {
    float temperature;
    int timestamp;
} TemperatureData;

// Mutex for the buffer
pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;

// Circular buffer
TemperatureData buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_size = 0;

// Function to read temperature from the LM75 sensor
int read_temperature(int fd) {
    int ret = 0;
    unsigned char data[2];
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C bus: %d\n", errno);
        return -1;
    }
    int temperature = (data[0] << 5) | data[1];
    temperature = (temperature & 0x1fff) - 0x1000; // Two's complement
    temperature /= 256.0;
    return temperature;
}

// Function to log temperature to the buffer
void log_temperature(float temperature) {
    pthread_mutex_lock(&buffer_mutex);
    if (buffer_size >= BUFFER_SIZE) {
        buffer_index = 0;
    }
    buffer[buffer_index].temperature = temperature;
    buffer[buffer_index].timestamp = time(NULL);
    buffer_size++;
    pthread_mutex_unlock(&buffer_mutex);
}

// Function to compute the running average
float compute_average() {
    float sum = 0.0;
    int count = 0;
    for (int i = 0; i < buffer_size; i++) {
        sum += buffer[i].temperature;
        count++;
    }
    return sum / count;
}

// Function to trigger the LED
void trigger_led(float temperature) {
    if (temperature > 28.0) {
        gpiod_async_set_high(GPIO_18, 1);
    } else {
        gpiod_async_set_low(GPIO_18, 1);
    }
}

// Function to handle the background thread
void* background_thread(void* arg) {
    while (1) {
        float temperature = read_temperature(I2C Bus);
        if (temperature < 0) {
            continue;
        }
        log_temperature(temperature);
        float average = compute_average();
        trigger_led(average);
        usleep(1000000); // Wait 1 second
    }
    return NULL;
}

int main() {
    // Initialize the I2C bus
    int fd = gpiod_async_open(I2C Bus, I2C_ADDRESS, 0, NULL);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", errno);
        return 1;
    }

    // Initialize the GPIO pin
    gpiod_async_open(GPIO_18, 0, 0, NULL);

    // Create a mutex for the buffer
    pthread_mutex_init(&buffer_mutex, NULL);

    // Create a circular buffer
    int buffer_fd = open(BUFFER_NAME, O_RDWR | O_CREAT, BUFFER_FILE_MODE);
    if (buffer_fd < 0) {
        fprintf(stderr, "Error creating buffer file: %d\n", errno);
        return 1;
    }
    if (ftruncate(buffer_fd, BUFFER_SIZE * sizeof(TemperatureData)) < 0) {
        fprintf(stderr, "Error truncating buffer file: %d\n", errno);
        return 1;
    }

    // Create a background thread
    pthread_t thread;
    pthread_create(&thread, NULL, background_thread, NULL);

    // Main loop
    while (1) {
        // Check for SIGINT
        if (killpg(0, SIGINT)) {
            break;
        }

        // Read the temperature
        float temperature = read_temperature(I2C Bus);

        // Check for errors
        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature: %d\n", errno);
            continue;
        }

        // Log the temperature
        log_temperature(temperature);

        // Compute the running average
        float average = compute_average();

        // Trigger the LED
        trigger_led(average);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Close the I2C file descriptor
    close(fd);

    // Release the GPIO lines
    gpiod_async_close(GPIO_18, 0);

    // Destroy the mutex
    pthread_mutex_destroy(&buffer_mutex);

    // Close the buffer file descriptor
    close(buffer_fd);

    // Destroy the background thread
    pthread_join(thread, NULL);

    return 0;
}

