#define SPI_MOSI 23
#define SPI_MISO 24
#define SPI_SCK 25
#define R_REF 430.0
#define R0 100.0
#define A 0.0039
#define B 0.00000675

// Define structures
typedef struct {
    float target;
    float kp;
    float ki;
    float kd;
} pid_tunings;

// Define functions
void init_pigpio();
void init_spi();
void init_max31865();
void read_rtd();
void read_faults();
void pid_control();
void pwm_control();
void failsafe();
void load_config();
void log_error(const char *msg);
void cleanup();

int main(int argc, char **argv) {
    // Initialize pigpio
    init_pigpio();

    // Initialize SPI
    init_spi();

    // Initialize MAX31865
    init_max31865();

    // Load configuration
    load_config();

    // Initialize PID gains
    pid_tunings pid;
    pid.target = 25.0;
    pid.kp = 1.0;
    pid.ki = 0.1;
    pid.kd = 0.01;

    // Main loop
    while (1) {
        // Read RTD
        read_rtd();

        // Read faults
        read_faults();

        // PID control
        pid_control();

        // PWM control
        pwm_control();

        // Failsafe
        failsafe();

        // Sleep
        usleep(100000);
    }

    // Cleanup
    cleanup();

    return 0;
}

void init_pigpio() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        exit(1);
    }
}

void init_spi() {
    if (gpioSetMode(SPI_CE0, PI_OUTPUT) < 0) {
        log_error("Failed to set SPI CE0 as output");
        exit(1);
    }
    if (gpioSetMode(SPI_MOSI, PI_OUTPUT) < 0) {
        log_error("Failed to set SPI MOSI as output");
        exit(1);
    }
    if (gpioSetMode(SPI_MISO, PI_INPUT) < 0) {
        log_error("Failed to set SPI MISO as input");
        exit(1);
    }
    if (gpioSetMode(SPI_SCK, PI_OUTPUT) < 0) {
        log_error("Failed to set SPI SCK as output");
        exit(1);
    }
    if (gpioSetClock(SPI_CE0, SPI_SPEED, SPI_MODE) < 0) {
        log_error("Failed to set SPI clock");
        exit(1);
    }
}

void init_max31865() {
    if (gpioWrite(SPI_CE0, 0xC1) < 0) {
        log_error("Failed to write to MAX31865 config register");
        exit(1);
    }
}

void read_rtd() {
    uint16_t code = 0;
    if (gpioRead(SPI_MISO) < 0) {
        log_error("Failed to read RTD code");
        exit(1);
    }
    code = (gpioRead(SPI_MISO) << 8) | gpioRead(SPI_MISO);
    if (code & (1 << 15)) {
        log_error("RTD fault detected");
        exit(1);
    }
    float R_rtd = (code / 32768.0) * R_REF;
    float R = R_rtd / (R_rtd + R0);
    float t = (A * R - B * R * R) / (R0 * (1 + B * R));
    printf("R_rtd: %f Ohms, R: %f Ohms, T: %f°C\n", R_rtd, R, t);
}

void read_faults() {
    uint8_t faults = 0;
    if (gpioRead(SPI_CE0) < 0) {
        log_error("Failed to read MAX31865 faults");
        exit(1);
    }
    faults = gpioRead(SPI_CE0);
    if (faults & (1 << 0)) {
        log_error("MAX31865 fault detected");
        exit(1);
    }
}

