    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up I2C
    if (gpioSetMode(I2C_Bus, I2C_MODE_MASTER) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    // Set up I2C clock
    if (gpioSetClock(I2C_Bus, 100000) < 0) {
        perror("gpioSetClock");
        gpioTerminate();
        return 1;
    }

    // Set up fan
    if (gpioMode(GPIO_FAN, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }
    gpioWrite(GPIO_FAN, GPIO_FAN_LOW);

    // Read calibration table
    uint8_t calibrationTable[11];
    if (i2cWrite(I2C_Bus, I2C_ADDRESS, 0xAA, 11, calibrationTable) < 0) {
        perror("i2cWrite");
        gpioTerminate();
        return 1;
    }
    if (i2cRead(I2C_Bus, I2C_ADDRESS, 0x00, 1, calibrationTable) < 0) {
        perror("i2cRead");
        gpioTerminate();
        return 1;
    }

    // Set up timer
    struct itimer it;
    it.it_value.tv_sec = 0;
    it.it_value.tv_usec = SAMPLE_INTERVAL;
    it.it_interval.tv_sec = 0;
    it.it_interval.tv_usec = 0;
    if (gpioSetAlarm(I2C_Bus, &it) < 0) {
        perror("gpioSetAlarm");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        struct itimer it;
        it.it_value.tv_sec = 0;
        it.it_value.tv_usec = 0;
        it.it_interval.tv_sec = 0;
        it.it_interval.tv_usec = 0;
        if (gpioGetAlarm(I2C_Bus, &it) < 0) {
            perror("gpioGetAlarm");
            gpioTerminate();
            return 1;
        }

        // Read BMP180
        uint8_t b1, b2, b3, b4, b5, b6, b7;
        if (i2cRead(I2C_Bus, I2C_ADDRESS, 0x00, 1, &b1) < 0) {
            perror("i2cRead");
            continue;
        }
        if (i2cRead(I2C_Bus, I2C_ADDRESS, 0x01, 1, &b2) < 0) {
            perror("i2cRead");
            continue;
        }
        if (i2cRead(I2C_Bus, I2C_ADDRESS, 0x02, 1, &b3) < 0) {
            perror("i2cRead");
            continue;
        }
        if (i2cRead(I2C_Bus, I2C_ADDRESS, 0x03, 1, &b4) < 0) {
            perror("i2cRead");
            continue;
        }
        if (i2cRead(I2C_Bus, I2C_ADDRESS, 0x04, 1, &b5) < 0) {
            perror("i2cRead");
            continue;
        }
        if (i2cRead(I2C_Bus, I2C_ADDRESS, 0x05, 1, &b6) < 0) {
            perror("i2cRead");
            continue;
        }
        if (i2cRead(I2C_Bus, I2C_ADDRESS, 0x06, 1, &b7) < 0) {
            perror("i2cRead");
            continue;
        }

        // Validate calibration table
        if (b1 != calibrationTable[0] || b2 != calibrationTable[1] || b3 != calibrationTable[2] || b4 != calibrationTable[3] || b5 != calibrationTable[4] || b6 != calibrationTable[5] || b7 != calibrationTable[6]) {
            printf("Calibration table mismatch\n");
            continue;
        }

        // Compute temperature and pressure
        uint16_t temperature = (b1 << 8) | b2;
        uint16_t pressure = (b3 << 8) | b4;
        temperature = (temperature - calibrationTable[7]) / calibrationTable[8] * 175 - 5;
        pressure = pressure / 16384;

        // Store reading
        struct BMP180Reading *reading = &buffer[BUFFER_INDEX];
        reading->timestamp = time(NULL);
        reading->temperature = temperature;
        reading->pressure = pressure;
        BUFFER_INDEX = (BUFFER_INDEX + 1) % BUFFER_SIZE;

        // Check temperature
        if (temperature > TEMPERATURE_THRESHOLD) {
            gpioWrite(GPIO_FAN, GPIO_FAN_HIGH);
        } else {
            gpioWrite(GPIO_FAN, GPIO_FAN_LOW);
        }

        // Print reading
        printf("%d %d %d\n", reading->timestamp, reading->temperature, reading->pressure);
    }

    // Clean up
    gpioTerminate();
    return 0;
}

