#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>

#define PI_GPIO17 17
#define PI_GPIO8  8
#define PI_GPIO9  9
#define PI_GPIO10 10
#define PI_GPIO11 11
#define PI_SPI0 0
#define PI_SPI_CE0 PI_GPIO8
#define PI_SPI_MISO PI_GPIO9
#define PI_SPI_MOSI PI_GPIO10
#define PI_SPI_SCLK PI_GPIO11
#define PI_SPI_SPEED 2000000 // 2 MHz

#define MAX_DUTY_CYCLE 80
#define MAX_TEMP 100.0
#define MIN_TEMP 0.0
#define PI_LOG_FILE "heater_log.csv"

// Structure to hold temperature and duty cycle data
typedef struct {
    double temp;
    double duty_cycle;
    time_t timestamp;
} heater_data_t;

// Function to initialize pigpio
void init_pigpio() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(1);
    }
}

// Function to close pigpio
void close_pigpio() {
    gpioTerminate();
}

// Function to read temperature from MAX31855
int read_temp(int cs, int mosi, int miso, int sclk) {
    int ret = 0;
    unsigned char temp_byte = 0;
    unsigned char data[2] = {0, 0};

    // Set CS low
    gpioWrite(cs, 0);

    // Send start bit
    gpioWrite(mosi, 1);
    usleep(10);
    gpioWrite(mosi, 0);
    usleep(10);

    // Send data byte
    gpioWrite(mosi, 1);
    usleep(10);
    for (int i = 0; i < 8; i++) {
        gpioWrite(mosi, (data[i] >> (7 - i)) & 1);
        usleep(10);
    }
    gpioWrite(mosi, 0);
    usleep(10);

    // Wait for clock pulse
    usleep(10);
    gpioWrite(sclk, 1);
    usleep(10);
    gpioWrite(sclk, 0);
    usleep(10);

    // Read data byte
    gpioWrite(mosi, 1);
    usleep(10);
    for (int i = 0; i < 8; i++) {
        gpioWrite(miso, (temp_byte >> (7 - i)) & 1);
        usleep(10);
    }
    gpioWrite(miso, 0);
    usleep(10);

    // Set CS high
    gpioWrite(cs, 1);

    // Return temperature
    return (temp_byte & 0x3F);
}

// Function to write temperature to MAX31855
int write_temp(int cs, int mosi, int miso, int sclk, int temp) {
    int ret = 0;
    unsigned char data[2] = {0, 0};

    // Set CS low
    gpioWrite(cs, 0);

    // Send start bit
    gpioWrite(mosi, 1);
    usleep(10);
    gpioWrite(mosi, 0);
    usleep(10);

    // Send data byte
    gpioWrite(mosi, 1);
    usleep(10);
    for (int i = 0; i < 8; i++) {
        gpioWrite(mosi, (temp >> (7 - i)) & 1);
        usleep(10);
    }
    gpioWrite(mosi, 0);
    usleep(10);

    // Wait for clock pulse
    usleep(10);
    gpioWrite(sclk, 1);
    usleep(10);
    gpioWrite(sclk, 0);
    usleep(10);

    // Read data byte
    gpioWrite(mosi, 1);
    usleep(10);
    for (int i = 0; i < 8; i++) {
        gpioWrite(miso, (data[i] >> (7 - i)) & 1);
        usleep(10);
    }
    gpioWrite(miso, 0);
    usleep(10);

    // Set CS high
    gpioWrite(cs, 1);

    // Return temperature
    return (data[0] & 0x3F);
}

// Function to modulate heater duty cycle
void modulate_duty_cycle(double temp, double duty_cycle) {
    int ret = 0;
    int heater_pin = PI_GPIO17;

    // Set duty cycle
    gpioWrite(heater_pin, (int)(duty_cycle * 100));

    // Log temperature and duty cycle
    time_t now = time(NULL);
    struct tm *ltm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", ltm);
    FILE *log_file = fopen(PI_LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        exit(1);
    }
    fprintf(log_file, "%s,%f,%f\n", timestamp, temp, duty_cycle);
    fclose(log_file);
}

// Function to PI controller
void pi_controller(double target_temp) {
    int ret = 0;
    int heater_pin = PI_GPIO17;
    int heater_cs = PI_GPIO8;
    int heater_mosi = PI_GPIO9;
    int heater_sclk = PI_GPIO10;
    double temp = 0.0;
    double duty_cycle = 0.0;
    double error = 0.0;
    double k_p = 0.1;
    double k_i = 0.01;
    double k_d = 0.1;
    double integral = 0.0;
    double prev_error = 0.0;
    double prev_duty_cycle = 0.0;
    int max_duty_cycle = MAX_DUTY_CYCLE;
    int min_duty_cycle = 0;
    int max_temp = MAX_TEMP;
    int min_temp = MIN_TEMP;

    // Initialize SPI
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(1);
    }
    if (gpioMode(heater_cs, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        exit(1);
    }
    if (gpioMode(heater_mosi, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        exit(1);
    }
    if (gpioMode(heater_sclk, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        exit(1);
    }
    if (gpioMode(heater_pin, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        exit(1);
    }
    if (gpioWrite(heater_cs, 0) < 0) {
        perror("gpioWrite");
        exit(1);
    }

    // Main loop
    while (1) {
        // Read temperature
        temp = read_temp(heater_cs, heater_mosi, heater_sclk, heater_sclk);

        // Calculate error
        error = target_temp - temp;

        // Calculate integral
        integral += error;
        integral = (integral * k_i) + error;

        // Calculate derivative
        double delta_error = error - prev_error;
        integral = (integral * k_d) + delta_error;

        // Calculate duty cycle
        duty_cycle = k_p * error + integral;
        duty_cycle = max(min_duty_cycle, min(max_duty_cycle, duty_cycle));

        // Clamp duty cycle
        duty_cycle = max(min_duty_cycle, max_duty_cycle);

        // Modulate heater duty cycle
        modulate_duty_cycle(temp, duty_cycle);

        // Update previous error and duty cycle
        prev_error = error;
        prev_duty_cycle = duty_cycle;

        // Check for SPI read failure or MAX31855 fault
