}

// Function to close pigpio
void close_pigpio() {
    gpioTerminate();
}

// Function to read temperature from MAX31855
int read_temp(int cs, int mosi, int miso, int sclk) {
    int ret = 0;
    unsigned char temp_byte = 0;
    unsigned char data[2] = {0, 0};

    // Set CS low
    gpioWrite(cs, 0);

    // Send start bit
    gpioWrite(mosi, 1);
    usleep(10);
    gpioWrite(mosi, 0);
    usleep(10);

    // Send data byte
    gpioWrite(mosi, 1);
    usleep(10);
    for (int i = 0; i < 8; i++) {
        gpioWrite(mosi, (data[i] >> (7 - i)) & 1);
        usleep(10);
    }
    gpioWrite(mosi, 0);
    usleep(10);

    // Wait for clock pulse
    usleep(10);
    gpioWrite(sclk, 1);
    usleep(10);
    gpioWrite(sclk, 0);
    usleep(10);

    // Read data byte
    gpioWrite(mosi, 1);
    usleep(10);
    for (int i = 0; i < 8; i++) {
        gpioWrite(miso, (temp_byte >> (7 - i)) & 1);
        usleep(10);
    }
    gpioWrite(miso, 0);
    usleep(10);

    // Set CS high
    gpioWrite(cs, 1);

    // Return temperature
    return (temp_byte & 0x3F);
}

// Function to write temperature to MAX31855
int write_temp(int cs, int mosi, int miso, int sclk, int temp) {
    int ret = 0;
