    gpioWrite(cs, 0);

    // Send start bit
    gpioWrite(mosi, 1);
    usleep(10);
    gpioWrite(mosi, 0);
    usleep(10);

    // Send data byte
    gpioWrite(mosi, 1);
    usleep(10);
    for (int i = 0; i < 8; i++) {
        gpioWrite(mosi, (temp >> (7 - i)) & 1);
        usleep(10);
    }
    gpioWrite(mosi, 0);
    usleep(10);

    // Wait for clock pulse
    usleep(10);
    gpioWrite(sclk, 1);
    usleep(10);
    gpioWrite(sclk, 0);
    usleep(10);

    // Read data byte
    gpioWrite(mosi, 1);
    usleep(10);
    for (int i = 0; i < 8; i++) {
        gpioWrite(miso, (data[i] >> (7 - i)) & 1);
        usleep(10);
    }
    gpioWrite(miso, 0);
    usleep(10);

    // Set CS high
    gpioWrite(cs, 1);

    // Return temperature
    return (data[0] & 0x3F);
}

// Function to modulate heater duty cycle
void modulate_duty_cycle(double temp, double duty_cycle) {
    int ret = 0;
    int heater_pin = PI_GPIO17;

    // Set duty cycle
    gpioWrite(heater_pin, (int)(duty_cycle * 100));

    // Log temperature and duty cycle
    time_t now = time(NULL);
    struct tm *ltm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", ltm);
    FILE *log_file = fopen(PI_LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        exit(1);
    }
    fprintf(log_file, "%s,%f,%f\n", timestamp, temp, duty_cycle);
    fclose(log_file);
}

// Function to PI controller
void pi_controller(double target_temp) {
    int ret = 0;
    int heater_pin = PI_GPIO17;
    int heater_cs = PI_GPIO8;
    int heater_mosi = PI_GPIO9;
    int heater_sclk = PI_GPIO10;
    double temp = 0.0;
    double duty_cycle = 0.0;
    double error = 0.0;
    double k_p = 0.1;
    double k_i = 0.01;
    double k_d = 0.1;
    double integral = 0.0;
    double prev_error = 0.0;
    double prev_duty_cycle = 0.0;
    int max_duty_cycle = MAX_DUTY_CYCLE;
    int min_duty_cycle = 0;
    int max_temp = MAX_TEMP;
    int min_temp = MIN_TEMP;

    // Initialize SPI
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(1);
    }
    if (gpioMode(heater_cs, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        exit(1);
    }
    if (gpioMode(heater_mosi, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        exit(1);
    }
    if (gpioMode(heater_sclk, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        exit(1);
    }
    if (gpioMode(heater_pin, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        exit(1);
    }
    if (gpioWrite(heater_cs, 0) < 0) {
        perror("gpioWrite");
        exit(1);
    }

    // Main loop
    while (1) {
        // Read temperature
        temp = read_temp(heater_cs, heater_mosi, heater_sclk, heater_sclk);

        // Calculate error
        error = target_temp - temp;

        // Calculate integral
        integral += error;
        integral = (integral * k_i) + error;

        // Calculate derivative
        double delta_error = error - prev_error;
        integral = (integral * k_d) + delta_error;

        // Calculate duty cycle
        duty_cycle = k_p * error + integral;
        duty_cycle = max(min_duty_cycle, min(max_duty_cycle, duty_cycle));

        // Clamp duty cycle
        duty_cycle = max(min_duty_cycle, max_duty_cycle);

        // Modulate heater duty cycle
        modulate_duty_cycle(temp, duty_cycle);

        // Update previous error and duty cycle
        prev_error = error;
        prev_duty_cycle = duty_cycle;

        // Check for SPI read failure or MAX31855 fault
        if (gpioRead(heater_cs) == 0) {
            printf("SPI read failure or MAX31855 fault\n");
            duty_cycle = 0.0;
            modulate_duty_cycle(temp, duty_cycle);
        }

        // Check for temperature out of range
        if (temp < min_temp || temp > max_temp) {
            printf("Temperature out of range\n");
            duty_cycle = 0.0;
            modulate_duty_cycle(temp, duty_cycle);
        }
    }
}

int main() {
    // Initialize pigpio
    init_pigpio();

    // Set target temperature
    double target_temp = 25.0;

    // Start PI controller
    pi_controller(target_temp);

    // Close pigpio
    close_pigpio();

    return 0;
}
