    pigpio_delay_ms(1);
    pigpio_write(pin, LOW);
    pigpio_delay_ms(1);
    pigpio_write(pin, HIGH);
    pigpio_delay_ms(1);

    char buffer[DHT22_DATA_LENGTH];
    pigpio_i2c_read(fd, buffer, DHT22_DATA_LENGTH);
    pigpio_close(fd);

    int checksum = 0;
    for (int i = 0; i < DHT22_CHECKSUM_LENGTH; i++) {
        checksum += buffer[DHT22_CHECKSUM_OFFSET + i];
    }

    if (checksum != DHT22_CHECKSUM) {
        printf("Checksum mismatch\n");
        return;
    }

    char* humidity = malloc(5);
    char* temperature = malloc(6);
    char* payload = malloc((DHT22_DATA_LENGTH + DHT22_CHECKSUM_LENGTH) * 2);

    sprintf(payload, "{\"humidity\":%s,\"temperature\":%s}", humidity, temperature);

    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;
    struct curl_slist *header_list = NULL;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
