void send_dht22_data(int pin, int data) {
    int fd = pigpio_i2c_open(pin, I2C_MODE_MASTER);
    if (fd < 0) {
        printf("Failed to open I2C bus\n");
        return;
    }

    pigpio_delay_ms(1);
    pigpio_write(pin, LOW);
    pigpio_delay_ms(1);
    pigpio_write(pin, HIGH);
    pigpio_delay_ms(1);

    char buffer[DHT22_DATA_LENGTH];
    pigpio_i2c_read(fd, buffer, DHT22_DATA_LENGTH);
    pigpio_close(fd);

    int checksum = 0;
    for (int i = 0; i < DHT22_CHECKSUM_LENGTH; i++) {
        checksum += buffer[DHT22_CHECKSUM_OFFSET + i];
    }

    if (checksum != DHT22_CHECKSUM) {
        printf("Checksum mismatch\n");
        return;
    }

    char* humidity = malloc(5);
    char* temperature = malloc(6);
    char* payload = malloc((DHT22_DATA_LENGTH + DHT22_CHECKSUM_LENGTH) * 2);

    sprintf(payload, "{\"humidity\":%s,\"temperature\":%s}", humidity, temperature);

    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;
    struct curl_slist *header_list = NULL;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        headers = curl_slist_append(NULL, "Content-Type: application/json");
        header_list = curl_slist_append(header_list, "Content-Length: ");
        header_list = curl_slist_append(header_list, (char*)payload);
        curl_easy_setopt(curl, CURLOPT_URL, "http://yourserver.com/api/humidity");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, header_list);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_memory_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, NULL);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_memory_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, NULL);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            printf("cURL error: %s\n", curl_easy_strerror(res));
            free(payload);
            free(humidity);
            free(temperature);
            curl_easy_cleanup(curl);
            curl_global_cleanup();
            return;
        }

        free(payload);
        free(humidity);
        free(temperature);
        curl_easy_cleanup(curl);
        curl_global_cleanup();
    }

    free(payload);
    free(humidity);
    free(temperature);
}

void write_memory_callback(void *ptr, size_t size, size_t nmemb, void *data) {
    char* buffer = (char*)data;
    for (size_t i = 0; i < size; i++) {
        buffer[i] = ptr[i];
    }
}

int main(int argc, char **argv) {
    signal(SIGINT, SIG_IGN);
    signal(SIGTERM, SIG_IGN);

    pigpio_init();
    if (pigpio_i2c_open(DHT22_PIN, I2C_MODE_MASTER) < 0) {
        printf("Failed to open I2C bus\n");
        return 1;
    }

    send_dht22_data(DHT22_PIN, 0);

    pigpio_close(DHT22_PIN);
    pigpioTerminate();

    return 0;
}
