#define FAN_SPEED_MAP  { 0, 0, 0, 3 }
#define FAN_SPEED_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define FAN_SPEED_LOG_FILE "/var/log/fan_control.log"

int main(int argc, char **argv) {
    int fd;
    char temp_str[20];
    int temp;
    int fan_state;
    struct timespec delay;
    struct itimerval it;

    // Initialize logging
    openlog("fan_control", LOG_PID, LOG_USER);
    setlogmask(LOG_UPTIME | LOG_PID);
    syslog(LOG_INFO, "Fan control started");

    // Set up signal handlers
    signal(SIGINT, SIG_IGN);
    signal(SIGTERM, SIG_IGN);

    // Open fan speed file
    fd = open(FAN_SPEED_FILE, O_RDONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open fan speed file: %s", strerror(errno));
        return 1;
    }

    while (1) {
        // Read temperature
        ssize_t len = read(fd, temp_str, sizeof(temp_str));
        if (len < 0) {
            syslog(LOG_ERR, "Failed to read temperature: %s", strerror(errno));
            continue;
        }
        temp = atoi(temp_str);
        if (temp < 0) {
            syslog(LOG_ERR, "Invalid temperature value: %d", temp);
            continue;
        }

        // Validate temperature and set fan state
        fan_state = 0;
        if (temp < 45) {
            fan_state = 0;
        } else if (temp < 55) {
            fan_state = 1;
        } else if (temp < 65) {
            fan_state = 2;
        } else {
            fan_state = 3;
        }

        // Validate fan state
        if (fan_state < 0 || fan_state > 3) {
            syslog(LOG_ERR, "Invalid fan state: %d", fan_state);
            continue;
        }

        // Write fan state
        if (write(fd, &fan_state, sizeof(fan_state)) < 0) {
            syslog(LOG_ERR, "Failed to write fan state: %s", strerror(errno));
            continue;
        }

        // Log fan speed change
        if (fan_state != 0) {
            struct timespec now;
            clock_gettime(CLOCK_REALTIME, &now);
            char log_str[256];
            strftime(log_str, sizeof(log_str), "%Y-%m-%d %H:%M:%S", localtime(&now));
            syslog(LOG_INFO, "%s Fan speed: %d", log_str, fan_state);
        }

        // Delay before next iteration
        delay.tv_sec = 5;
        delay.tv_nsec = 0;
        if (nanosleep(&delay, NULL) < 0) {
            syslog(LOG_ERR, "Failed to delay: %s", strerror(errno));
        }
    }

    // Clean up
    close(fd);
    syslog(LOG_INFO, "Fan control stopped");
    exit(0);
}

