#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>

#define PI 3.14159265359
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01
#define TARGET 50.0
#define MAXTEMP 100.0
#define MINTEMP 0.0
#define FAULT_OPEN 0x01
#define FAULT_SHORT_TO_GND 0x02
#define FAULT_SHORT_TO_VCC 0x04
#define FAULT_OVERHEAT 0x08
#define FAULT_UNDERHEAT 0x10
#define FAULT_OK 0x00

#define SPI_CLK 11
#define SPI_CS 8
#define SPI_DO 9
#define SPI_MOSI 10
#define SPI_MISO 12
#define GPIO_HEATER 18

int pid_state = 0;
int heater_duty = 0;
int heater_fault = 0;
int heater_open = 0;
int heater_short_to_gnd = 0;
int heater_short_to_vcc = 0;
int heater_overheat = 0;
int heater_underheat = 0;
int last_temp = 0;
int last_duty = 0;
int last_error = 0;
int last_output = 0;
int last_spi_error = 0;
int last_spi_fault = 0;

void heater_init() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio\n");
        exit(1);
    }
    if (gpioSetMode(GPIO_HEATER, PI_OUTPUT) < 0) {
        printf("Failed to set heater mode\n");
        exit(1);
    }
    if (gpioSetLevel(GPIO_HEATER, 0) < 0) {
        printf("Failed to set heater off\n");
        exit(1);
    }
}

void heater_off() {
    if (gpioSetLevel(GPIO_HEATER, 0) < 0) {
        printf("Failed to set heater off\n");
        exit(1);
    }
}

void heater_reset() {
    heater_off();
    heater_duty = 0;
    heater_fault = 0;
    heater_open = 0;
    heater_short_to_gnd = 0;
    heater_short_to_vcc = 0;
    heater_overheat = 0;
    heater_underheat = 0;
    last_temp = 0;
    last_duty = 0;
    last_error = 0;
    last_output = 0;
    last_spi_error = 0;
    last_spi_fault = 0;
}

void heater_set_duty(int duty) {
    if (gpioSetLevel(GPIO_HEATER, duty) < 0) {
        printf("Failed to set heater duty\n");
        exit(1);
    }
}

void heater_log() {
    FILE *log_file = fopen("heater_log.txt", "a");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        exit(1);
    }
    fprintf(log_file, "%f %d %d %d %d %d %d %d\n", (double)time(NULL), heater_duty, heater_fault, heater_open, heater_short_to_gnd, heater_short_to_vcc, heater_overheat, heater_underheat);
    fclose(log_file);
}

void pid_update() {
    int error = 0;
    int output = 0;
    int temp = 0;
    int i;

    // Read temperature from thermocouple
    if (spiTransfer(SPI_CLK, SPI_CS, SPI_DO, SPI_MOSI, SPI_MISO, 4) < 0) {
        heater_fault |= FAULT_SPI_ERROR;
        heater_log();
        heater_reset();
        return;
    }
    for (i = 0; i < 4; i++) {
        temp += (spiRead(SPI_CLK, SPI_CS, SPI_DO, SPI_MOSI, SPI_MISO) << (i * 8));
    }
    temp >>= 24;

    // Check for faults
    if (temp < MINTEMP) {
        heater_fault |= FAULT_UNDERHEAT;
    } else if (temp > MAXTEMP) {
        heater_fault |= FAULT_OVERHEAT;
    }

    // Calculate PID error
    error = (temp - TARGET) * Kp;
    error += (last_temp - temp) * Ki;
    error -= (last_duty - heater_duty) * Kd;

    // Update PID output
    output = heater_duty + error;

    // Limit output to 0-100%
    output = (int)(output * 100);
    if (output < 0) {
        output = 0;
    } else if (output > 100) {
        output = 100;
    }

    // Update last values
    last_temp = temp;
    last_duty = heater_duty;
    last_error = error;
    last_output = output;

    // Update heater duty
    heater_set_duty(output);

    // Check for faults
    if (temp < MINTEMP) {
        heater_fault |= FAULT_UNDERHEAT;
    } else if (temp > MAXTEMP) {
        heater_fault |= FAULT_OVERHEAT;
    }

    // Log temperature, PWM duty cycle, and PID output
    heater_log();
}

void heater_loop() {
    while (1) {
        pid_update();
        usleep(1000);
    }
}

void sigint_handler(int sig) {
    heater_off();
    heater_reset();
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    sigaction(SIGINT, &sa, NULL);

    heater_init();
    heater_set_duty(0);
    heater_log();

    heater_loop();

    heater_off();
    gpioTerminate();
    return 0;
}

