    if (temp < MINTEMP) {
        heater_fault |= FAULT_UNDERHEAT;
    } else if (temp > MAXTEMP) {
        heater_fault |= FAULT_OVERHEAT;
    }

    // Log temperature, PWM duty cycle, and PID output
    heater_log();
}

void heater_loop() {
    while (1) {
        pid_update();
        usleep(1000);
    }
}

void sigint_handler(int sig) {
    heater_off();
    heater_reset();
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    sigaction(SIGINT, &sa, NULL);

    heater_init();
    heater_set_duty(0);
    heater_log();

    heater_loop();

    heater_off();
    gpioTerminate();
    return 0;
}
```

This code implements a PID controller that maintains a target temperature by PWM-controlling a resistive heater on GPIO18. It reads temperature from a MAX31855 thermocouple amplifier over SPI0 and logs the temperature, PWM duty cycle, and PID output to a file every second. The code handles SPI communication errors and thermocouple faults, and ensures clean resource release on SIGINT/SIGTERM.

