#define TEMPERATURE_THRESHOLD 40
#define TEMPERATURE_MAX 70

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

