    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioPWMWrite(PWM_PIN, PWM_FREQ) < 0) {
        perror("gpioPWMWrite");
        gpioTerminate();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("cooling_log.csv", "w");
    if (log_file == NULL) {
        perror("fopen");
        gpioTerminate();
        return 1;
    }

    // Write CSV header
    fprintf(log_file, "timestamp,temperature,pwm_duty\n");

    while (1) {
        // Read temperature
        char temp_str[10];
        ssize_t bytes_read = readlink("/sys/class/thermal/thermal_zone0/temp", temp_str, sizeof(temp_str));
        if (bytes_read < 0) {
            perror("readlink");
            break;
        }
        float temperature = (temp_str[0] - '0') + (temp_str[1] - '0') / 100.0f;
        temperature /= 1000.0f; // Convert from millidegrees Celsius to degrees Celsius

        // Map temperature to PWM duty cycle
        float duty = (temperature > TEMPERATURE_MAX) ? PWM_DUTY_MAX : (temperature < TEMPERATURE_THRESHOLD) ? PWM_DUTY_MIN : (temperature - TEMPERATURE_THRESHOLD) / (TEMPERATURE_MAX - TEMPERATURE_THRESHOLD) * (PWM_DUTY_MAX - PWM_DUTY_MIN) + PWM_DUTY_MIN;

        // Log temperature and PWM duty cycle
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s,%f,%f\n", timestamp, temperature, duty);

        // Set PWM duty cycle
        if (gpioPWMWrite(PWM_PIN, (unsigned int)(duty * 100)) < 0) {
            perror("gpioPWMWrite");
            break;
        }

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    gpioTerminate();
    fclose(log_file);

    return 0;
}

