#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

#define I2C_ADDRESS 0x08
#define I2C_ADDRESS_1 0x09
#define I2C_RETRY 3
#define I2C_TIMEOUT 100
#define I2C_READ_SIZE 3
#define I2C_WRITE_SIZE 1

int main(int argc, char **argv) {
    int i, j, fd, ret;
    struct timespec start;
    struct stat sb;
    char filename[256];
    char buffer[I2C_READ_SIZE];
    unsigned char crc;
    float flow1, flow2;
    struct timespec end;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open log file
    sprintf(filename, "flow_log.txt");
    if ((fd = open(filename, O_RDWR | O_CREAT | O_WRONLY | O_APPEND) < 0) {
        perror("open");
        return 1;
    }

    // Open I2C handles
    if ((ret = pigpio_i2c_open(1, I2C_ADDRESS, 0, &sb) < 0) {
        perror("pigpio_i2c_open");
        return 1;
    }
    if ((ret = pigpio_i2c_open(1, I2C_ADDRESS_1, 0, &sb) < 0) {
        perror("pigpio_i2c_open");
        return 1;
    }

    while (1) {
        // Get current time
        clock_gettime(CLOCK_REALTIME, &start);

        // Read from both sensors
        for (i = 0; i < I2C_RETRY; i++) {
            for (j = 0; j < 2; j++) {
                if ((ret = pigpio_i2c_read(1, I2C_ADDRESS + j, I2C_READ_SIZE, buffer, I2C_TIMEOUT) < 0) {
                    if (errno == EIO) {
                        // Retry
                        continue;
                    } else {
                        perror("pigpio_i2c_read");
                        return 1;
                    }
                }
                // Validate CRC
                if (buffer[I2C_READ_SIZE - 1] != (buffer[I2C_READ_SIZE - 1] + 0xFF) {
                    continue;
                }
                // Convert raw values to flow rates
                flow1 = (buffer[0] * 0.01);
                flow2 = (buffer[1] * 0.01);
                // Log flow rates
                if (fwrite(&flow1, sizeof(float), 1, fd) < 0) {
                    perror("fwrite");
                    return 1;
                }
                if (fwrite(&flow2, sizeof(float), 1, fd) < 0) {
                    perror("fwrite");
                    return 1;
                }
                if (fputc(',', fd) < 0) {
                    perror("fputc");
                    return 1;
                }
            }
        }

        // Wait for 1 second
        clock_gettime(CLOCK_REALTIME, &end);
        sleep((end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1000000000.0);

        // Close I2C handles
        pigpio_i2c_close(1, I2C_ADDRESS);
        pigpio_i2c_close(1, I2C_ADDRESS_1);
    }

    // Clean up
    pigpio_close();
    close(fd);
    return 0;
}

