#define GPIO_A 17
#define GPIO_B 18
#define FILE_NAME "encoder_log.txt"

// Define the number of bits in the encoder
#define ENCODER_BITS 2

// Define the number of steps per revolution
#define STEPS_PER_REV 360

// Define the maximum and minimum angular positions
#define MAX_ANGLE 360.0
#define MIN_ANGLE 0.0

// Define the rotation direction
#define CLOCKWISE 1
#define COUNTERCLOCKWISE -1

// Define the encoder states
typedef enum {
    STATE_STOP,
    STATE_COUNTING_UP,
    STATE_COUNTING_DOWN
} EncoderState;

// Define the encoder states and their corresponding angles
typedef enum {
    STATE_0 = 0,
    STATE_1,
    STATE_2,
    STATE_3
} EncoderState;

// Define the encoder states and their corresponding angles
typedef enum {
    ANGLE_0 = 0,
    ANGLE_1,
    ANGLE_2,
    ANGLE_3
} EncoderAngle;

// Define the rotation direction
typedef enum {
    ROTATION_CW = 1,
    ROTATION_CCW = -1
} RotationDirection;

// Structure to hold the encoder state and angle
typedef struct {
    EncoderState state;
    EncoderAngle angle;
    RotationDirection direction;
} EncoderStateStruct;

// Structure to hold the encoder data
typedef struct {
    EncoderStateStruct state;
    time_t last_state_change;
    time_t last_rotation;
} EncoderData;

// Function to initialize the encoder
void init_encoder(pigpio *gpio) {
    // Initialize the GPIO pins
    gpioInitialise(gpio, GPIO_A, PI_INPUT, PI_INT_EDGE_RISING);
    gpioInitialise(gpio, GPIO_B, PI_INPUT, PI_INT_EDGE_RISING);

    // Set the pull-up resistors
    gpioSetPullUpDn(gpio, GPIO_A, PI_PUD_UP);
    gpioSetPullUpDn(gpio, GPIO_B, PI_PUD_UP);

    // Initialize the encoder data
    encoder_data = (EncoderData){.state = STATE_STOP, .last_state_change = 0, .last_rotation = 0};
}

// Function to update the encoder state
void update_encoder(pigpio *gpio) {
    // Read the encoder values
    int a = gpioGet(gpio, GPIO_A);
    int b = gpioGet(gpio, GPIO_B);

    // Update the encoder state
    if (a == 0 && b == 1) {
        if (encoder_data.state.state == STATE_COUNTING_UP) {
            encoder_data.state.state = STATE_STOP;
            encoder_data.state.last_state_change = time(NULL);
        } else {
            encoder_data.state.state = STATE_COUNTING_UP;
            encoder_data.state.last_state_change = time(NULL);
        }
    } else if (a == 1 && b == 0) {
        if (encoder_data.state.state == STATE_COUNTING_DOWN) {
            encoder_data.state.state = STATE_STOP;
            encoder_data.state.last_state_change = time(NULL);
        } else {
            encoder_data.state.state = STATE_COUNTING_DOWN;
            encoder_data.state.last_state_change = time(NULL);
        }
    }

    // Update the encoder angle
    if (encoder_data.state.state == STATE_COUNTING_UP) {
        encoder_data.state.angle = (encoder_data.state.angle + 1) % STEPS_PER_REV;
    } else {
        encoder_data.state.angle = (encoder_data.state.angle - 1 + STEPS_PER_REV) % STEPS_PER_REV;
    }

    // Update the last rotation time
    encoder_data.last_rotation = time(NULL);
}

// Function to log the encoder data
void log_encoder(pigpio *gpio) {
    // Open the log file
    int fd = open(FILE_NAME, O_WRONLY | O_CREAT, 0644);
    if (fd == -1) {
        perror("open");
        return;
    }

    // Log the encoder data
    time_t now = time(NULL);
    struct tm *time_info;
    time_info = localtime(&now);
    char buffer[20];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", time_info);
    fprintf(fd, "%s %d %d %d %d\n", buffer, encoder_data.state.state, encoder_data.state.angle, encoder_data.state.last_state_change, encoder_data.last_rotation);
    fclose(fd);
}

// Function to handle the SIGINT signal
void sigint_handler(int sig) {
    // Release the GPIO resources
    gpioTerminate();
    exit(0);
}

int main(int argc, char **argv) {
    // Initialize the pigpio library
    pigpio = pigpio_init();
    if (pigpio == -1) {
        perror("pigpio_init");
        return 1;
    }

    // Initialize the encoder
    init_encoder(pigpio);

    // Set up the signal handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Update the encoder state
        update_encoder(pigpio);

        // Log the encoder data
        log_encoder(pigpio);

        // Sleep for a short period
        usleep(100000);
    }

    // Release the GPIO resources
    gpioTerminate();

    return 0;
}

