    struct i2c_dev *dev;
    struct gpio_event_handler event_handler;
    struct timespec ts;
    struct timespec last_ts;
    FILE *log_file;

    // Initialize libgpiod
    if (gpio_init() < 0) {
        perror("gpio_init");
        return 1;
    }

    // Open I2C file descriptor
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open");
        gpio_cleanup();
        return 1;
    }

