    if ((client = i2c_get_client(i2c_fd, I2C_ADDRESS)) == NULL) {
        perror("i2c_get_client");
        close(i2c_fd);
        gpio_cleanup();
        return 1;
    }

    // Get I2C device structure
    if ((dev = i2c_get_client_data(client)) == NULL) {
        perror("i2c_get_client_data");
        close(i2c_fd);
        gpio_cleanup();
        return 1;
    }

    // Set up GPIO event handler
    event_handler.callback = gpio_callback;
    event_handler.flags = GPIO_FALLING_EDGE;
    event_handler.gpio = GPIO_PIN;
    event_handler.data = NULL;
    gpio_event_handler_setup(&event_handler);

    // Open log file
    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        perror("fopen");
        gpio_cleanup();
        close(i2c_fd);
        return 1;
    }

    // Read FIFO data
    if (ioctl(i2c_fd, I2C_SMBUS_READ, dev, FIFO_ADDRESS, 2, NULL, 0) < 0) {
        perror("ioctl");
        fclose(log_file);
        gpio_cleanup();
        close(i2c_fd);
        return 1;
    }

    // Read timestamp
    clock_gettime(CLOCK_REALTIME, &ts);

    // Check if sensor is present
    if (ts.tv_sec - last_ts.tv_sec > 0) {
        last_ts = ts;
        fprintf(log_file, "%ld,%d,%d\n", ts.tv_sec, dev->addr, dev->addr);
    }

    // Check if IR reading exceeds threshold
    if (ts.tv_sec - last_ts.tv_sec > 0) {
        last_ts = ts;
        if (dev->addr > THRESHOLD) {
            gpio_set_high(GPIO_PIN);
        } else {
            gpio_set_low(GPIO_PIN);
        }
        fprintf(log_file, "%ld,%d,%d\n", ts.tv_sec, dev->addr, dev->addr);
    }

    // Clean up
    gpio_cleanup();
    close(i2c_fd);
    fclose(log_file);

    // Handle SIGINT and SIGTERM
    signal(SIGINT, SIG_IGN);
    signal(SIGTERM, SIG_IGN);

    return 0;
}

