#define GPIO 18
#define LOG_FILE "rpm_log.txt"

// Structure to hold the log data
typedef struct {
    int count;
    time_t timestamp;
} rpm_log_entry;

// Mutex for protecting the pulse counter
pthread_mutex_t rpm_mutex = PTHREAD_MUTEX_INITIALIZER;

// Flag to indicate if the sensor is connected
int sensor_connected = 0;

// Function to initialize pigpio
void init_pigpio() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(1);
    }
}

// Function to read RPM from the sensor
void* read_rpm_thread(void* arg) {
    int fd;
    struct stat sb;
    char filename[256];
    pthread_mutex_t* mutex = (pthread_mutex_t*) arg;

    // Open the log file
    fd = open(LOG_FILE, O_RDWR | O_CREAT | O_APPEND | O_TRUNC, 0644);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    // Get the current directory
    if (stat(".", &sb) != 0) {
        perror("stat");
        exit(1);
    }

    // Create the log directory if it doesn't exist
    if (mkdir(sb.d_name, 0755) < 0) {
        perror("mkdir");
        exit(1);
    }

    // Open the log file
    if (fstat(fd, &sb) < 0) {
        perror("fstat");
        exit(1);
    }

    // Register the interrupt handler
    gpioSetMode(GPIO, PI_INPUT);
    gpioCleared(GPIO);
    gpioPullUpDn(GPIO);
    gpioEdgeDetect(GPIO, PI_RISING, read_rpm_isr);

    // Initialize the pulse counter
    pthread_mutex_lock(mutex);
    rpm_log_entry log_entry;
    log_entry.count = 0;
    log_entry.timestamp = time(NULL);
    pthread_mutex_unlock(mutex);

    // Read RPM for 1 second
    sleep(1);

    // Close the log file
    close(fd);

    // Destroy the mutex
    pthread_mutex_destroy(mutex);

    return NULL;
}

// Interrupt service routine for the sensor
void read_rpm_isr(int signal) {
    pthread_mutex_t* mutex = (pthread_mutex_t*) signal;

    // Acquire the mutex
    pthread_mutex_lock(mutex);

    // Increment the pulse counter
    rpm_log_entry* log_entry = (rpm_log_entry*) malloc(sizeof(rpm_log_entry));
    log_entry->count++;
    log_entry->timestamp = time(NULL);

    // Release the mutex
    pthread_mutex_unlock(mutex);

    // Log the RPM value
    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        exit(1);
    }
    fprintf(log_file, "%.2f\n", (double) log_entry->count);
    fclose(log_file);
}

// Signal handler for SIGINT/SIGTERM
void sigint_handler(int signal) {
    // Terminate pigpio
    gpioTerminate();

    // Close the log file
    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        exit(1);
    }
    fclose(log_file);

    // Destroy the mutex
    pthread_mutex_destroy(&rpm_mutex);

    // Exit
    exit(0);
}

int main() {
    // Initialize pigpio
    init_pigpio();

    // Register the interrupt handler
    pthread_mutex_t* mutex = (pthread_mutex_t*) malloc(sizeof(pthread_mutex_t));
    pthread_mutex_init(mutex, NULL);

    // Create and start the read RPM thread
    pthread_t thread;
    if (pthread_create(&thread, NULL, read_rpm_thread, mutex) != 0) {
        perror("pthread_create");
        exit(1);
    }

    // Register the signal handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Wait for the thread to finish
    pthread_join(thread, NULL);

    return 0;
}

