#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <signal.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <libgpiod.h>

#define I2C_ADDRESS 0x39
#define GPIO_LED 17
#define FIFO_ADDRESS 0x00
#define FIFO_READ 0x01
#define FIFO_WRITE 0x02
#define THRESHOLD 2000
#define LOG_FILE "adpd144ri_log.txt"

int main(int argc, char **argv) {
    // Initialize libgpiod
    gpiod_init();

    // Open I2C device
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C bus parameters
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C bus parameters");
        close(fd);
        return 1;
    }

    // Initialize GPIO pin
    gpio_init();
    gpio_set_mode(GPIO_LED, PI_INPUT);
    gpio_direction_output(GPIO_LED, PI_HIGH);

    // Open log file
    int log_fd = open(LOG_FILE, O_RDWR | O_CREAT | O_WRONLY, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        close(fd);
        gpio_close(GPIO_LED);
        return 1;
    }

    // Read PART_ID register
    unsigned char part_id;
    if (ioctl(fd, I2CMasterRead, &part_id) < 0) {
        perror("Failed to read PART_ID register");
        close(fd);
        gpio_close(GPIO_LED);
        close(log_fd);
        return 1;
    }

    if (part_id != 0x00) {
        printf("Sensor not found or faulty\n");
        close(fd);
        gpio_close(GPIO_LED);
        close(log_fd);
        return 1;
    }

    // Read red and IR channel data from FIFO
    unsigned char red, ir;
    while (1) {
        if (ioctl(fd, I2CMasterWrite, FIFO_WRITE) < 0) {
            perror("Failed to write to FIFO");
            close(fd);
            gpio_close(GPIO_LED);
            close(log_fd);
            return 1;
        }

        if (ioctl(fd, I2CMasterRead, &red) < 0) {
            perror("Failed to read from FIFO");
            close(fd);
            gpio_close(GPIO_LED);
            close(log_fd);
            return 1;
        }

        if (ioctl(fd, I2CMasterRead, &ir) < 0) {
            perror("Failed to read from FIFO");
            close(fd);
            gpio_close(GPIO_LED);
            close(log_fd);
            return 1;
        }

        // Trigger LED if IR reading exceeds threshold
        if (ir > THRESHOLD) {
            gpio_write(GPIO_LED, PI_LOW);
        } else {
            gpio_write(GPIO_LED, PI_HIGH);
        }

        // Log reading
        fprintf(log_fd, "%d,%d\n", (int)time(NULL), ir);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    gpio_close(GPIO_LED);
    close(log_fd);
    close(fd);
    gpiod_exit();
    return 0;
}

