    gpiod_exit();
    exit(0);
}

int main() {
    // Initialize signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize libgpiod
    gpiod_init();

    // Open GPIO device
    gpiod_device_t *dev = gpiod_device_open("gpio-17", GPIO_IN);
    if (!dev) {
        gpiod_perror("Failed to open GPIO device");
        return 1;
    }

    // Configure GPIO 17 as input
    gpiod_device_config_input(dev, GPIO_IN);
    if (gpiod_device_config_error(dev)) {
        gpiod_perror("Failed to configure GPIO 17 as input");
        gpiod_device_close(dev);
        return 1;
    }

    // Open GPIO device for GPIO 18
    gpiod_device_t *out_dev = gpiod_device_open("gpio-18", GPIO_OUT);
    if (!out_dev) {
        gpiod_perror("Failed to open GPIO device");
        gpiod_device_close(dev);
        return 1;
    }

    // Configure GPIO 18 as output
    gpiod_device_config_output(dev, GPIO_OUT);
    if (gpiod_device_config_error(dev)) {
        gpiod_perror("Failed to configure GPIO 18 as output");
        gpiod_device_close(out_dev);
        gpiod_device_close(dev);
        return 1;
    }

    // Set GPIO 18 to LOW to select 60dB gain
    gpiod_device_write(dev, GPIO_OUT, 0);
    if (gpiod_device_write_error(dev)) {
        gpiod_perror("Failed to set GPIO 18 to LOW");
        gpiod_device_close(out_dev);
        gpiod_device_close(dev);
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        gpiod_perror("Failed to open log file");
        gpiod_device_close(out_dev);
        gpiod_device_close(dev);
        return 1;
    }

    // Run indefinitely
    while (1) {
        // Read GPIO 17
        uint8_t level = gpiod_device_read(dev, GPIO_IN);
        if (gpiod_device_read_error(dev)) {
