#define GPIO_PIN 17
#define GPIO_CHIP_NAME "gpiochip0"
#define LINE_NAME "ttp223_tamper"
#define POLL_INTERVAL 100
#define MAX_TIME 5000

int main(int argc, char **argv) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_consumer *consumer;
    struct gpiod_event *event;
    struct gpiod_event_handler handler;
    struct timespec last_touch;
    struct timespec last_release;
    struct timespec poll_time;
    int running = 0;

    // Register signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize libgpiod
    if (gpiod_init() != 0) {
        perror("gpiod_init");
        return EXIT_FAILURE;
    }

    // Open gpiochip0 by name
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Request the line as input with the consumer label "ttp223_tamper"
    line = gpiod_line_request(chip, GPIO_PIN, LINE_NAME, &consumer, NULL);
    if (!line) {
        perror("gpiod_line_request");
        gpiod_chip_close(chip);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set the line as an input
    if (gpiod_line_set_direction(line, GpioDirectionInput) != 0) {
        perror("gpiod_line_set_direction");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Create an event handler
    event = gpiod_event_create(&handler);
    if (!event) {
        perror("gpiod_event_create");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set the event handler
    if (gpiod_event_set_handler(event, gpiod_event_handler, line) != 0) {
        perror("gpiod_event_set_handler");
        gpiod_event_destroy(event);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Initialize variables
    last_touch.tv_sec = 0;
    last_release.tv_sec = 0;
    poll_time.tv_sec = 0;
    poll_time.tv_nsec = 0;

    // Main loop
    while (1) {
        // Poll the line
        if (gpiod_event_poll(event, &poll_time) != 0) {
            perror("gpiod_event_poll");
            gpiod_event_destroy(event);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            gpiod_exit();
            return EXIT_FAILURE;
        }

        // Check if the sensor is touched
        if (gpiod_line_get_value(line) == GpioValueHigh) {
            // Check if the sensor was previously released
            if (clock_gettime(CLOCK_MONOTONIC, &last_release) != 0) {
                last_release.tv_sec = 0;
                last_release.tv_nsec = 0;
            }
            if (clock_gettime(CLOCK_MONOTONIC, &last_release) != 0) {
                perror("clock_gettime");
                gpiod_event_destroy(event);
                gpiod_line_release(line);
                gpiod_chip_close(chip);
                gpiod_exit();
                return EXIT_FAILURE;
            }
            if (difftime(last_release.tv_sec, last_touch.tv_sec) > MAX_TIME) {
                printf("Intrusion detected!\n");
                last_touch.tv_sec = last_release.tv_sec;
                last_touch.tv_nsec = last_release.tv_nsec;
            }
        } else {
            // Reset the timer
            last_touch.tv_sec = 0;
            last_touch.tv_nsec = 0;
        }
    }

    // Clean up
    gpiod_event_destroy(event);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    gpiod_exit();

    return EXIT_SUCCESS;
}

void sigint_handler(int sig) {
    gpiod_event_destroy(event);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    gpiod_exit();
    exit(EXIT_SUCCESS);
}

void sigterm_handler(int sig) {
    gpiod_event_destroy(event);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    gpiod_exit();
    exit(EXIT_SUCCESS);
}

