#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <gpiod/gpiod.h>

#define GPIO_PIN 17
#define I2S_ADDRESS 0x44
#define I2S_REG_LEFT_RIGHT 0x00
#define I2S_REG_DATA 0x04
#define I2S_REG_CONTROL 0x08
#define I2S_FRAME_SIZE 32
#define I2S_SAMPLE_SIZE 24

// Define the I2S control register values
#define I2S_LEFT_RIGHT 0x01
#define I2S_LEFT 0x00
#define I2S_RIGHT 0x02

// Define the signal handling function
void signal_handler(int sig) {
    gpio_close(gpio);
    close(fd);
    munmap(map, size);
    exit(0);
}

int main() {
    // Initialize the GPIO library
    gpio_init();
    gpio_set_mode(GPIO_PIN, PI_INPUT);

    // Open the I2S device
    fd = open("/dev/snd/pcmC0D0c", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2S device");
        return 1;
    }

    // Map the I2S memory
    size = mmap(NULL, I2S_FRAME_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (size == MAP_FAILED) {
        perror("Failed to map I2S memory");
        close(fd);
        return 1;
    }

    // Set the I2S control register to select the left channel
    *(volatile unsigned int *)map + I2S_REG_CONTROL = I2S_LEFT_RIGHT;

    // Set up the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the output file
    file = fopen("audio_capture.pcm", "wb");
    if (file == NULL) {
        perror("Failed to open output file");
        close(fd);
        munmap(map, size);
        return 1;
    }

    while (1) {
        // Read the I2S data
        for (int i = 0; i < I2S_FRAME_SIZE; i += I2S_SAMPLE_SIZE) {
            // Read the left channel data
            unsigned int left_channel = *(volatile unsigned int *)map + I2S_REG_LEFT_RIGHT + i;
            unsigned int right_channel = *(volatile unsigned int *)map + I2S_REG_LEFT_RIGHT + i + I2S_SAMPLE_SIZE;

            // Right-shift the left channel data to produce 16-bit PCM samples
            unsigned short left_sample = (left_channel >> 8) & 0xFFFF;
            unsigned short right_sample = (right_channel >> 8) & 0xFFFF;

            // Write the 16-bit PCM samples to the output file
            fwrite(&left_sample, sizeof(unsigned short), 1, file);
            fwrite(&right_sample, sizeof(unsigned short), 1, file);
        }
    }

    // Close the output file and I2S device
    fclose(file);
    close(fd);
    munmap(map, size);

    return 0;
}

