            unsigned int left_channel = *(volatile unsigned int *)map + I2S_REG_LEFT_RIGHT + i;
            unsigned int right_channel = *(volatile unsigned int *)map + I2S_REG_LEFT_RIGHT + i + I2S_SAMPLE_SIZE;

            // Right-shift the left channel data to produce 16-bit PCM samples
            unsigned short left_sample = (left_channel >> 8) & 0xFFFF;
            unsigned short right_sample = (right_channel >> 8) & 0xFFFF;

            // Write the 16-bit PCM samples to the output file
            fwrite(&left_sample, sizeof(unsigned short), 1, file);
            fwrite(&right_sample, sizeof(unsigned short), 1, file);
        }
    }

    // Close the output file and I2S device
    fclose(file);
    close(fd);
    munmap(map, size);

    return 0;
}
