// Structure to hold log entries
typedef struct {
    time_t timestamp;
    char event[256];
} log_entry_t;

// Function to log an event
void log_event(const char *event) {
    time_t now = time(NULL);
    strftime(log_entry.event, sizeof(log_entry.event), "%Y-%m-%d %H:%M:%S", localtime(&now));
    log_entry.event[strcspn(log_entry.event, "\n")] = 0;
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        exit(1);
    }
    fprintf(log_file, "%s %s\n", log_entry.event, event);
    fclose(log_file);
}

// Function to scale duty cycle based on flame duration
float scale_duty_cycle(float duration) {
    return (duration / 1000.0f) * PWM_MAX;
}

