        log_event("GPIO 4 mode failed");
        pigpioTerminate();
        return 1;
    }

    // Set up GPIO 18 as an output with hardware PWM
    if (pigpioMode(GPIO_OUT, GPIO_MODE PWM) < 0) {
        log_event("GPIO 18 mode failed");
        pigpioTerminate();
        return 1;
    }
    if (pigpioPWMWrite(GPIO_OUT, PWM_FREQ, PWM_MIN) < 0) {
        log_event("PWM write failed");
        pigpioTerminate();
        return 1;
    }

    // Set up debouncing
    int prev_state = pigpioRead(GPIO_IN);
    float prev_duration = 0;
    float prev_duty_cycle = PWM_MIN;

    while (1) {
        // Read the sensor
        int state = pigpioRead(GPIO_IN);
        if (state == 0) {
            // Flame detected
            float duration = time_diff(prev_state, state);
            float duty_cycle = scale_duty_cycle(duration);
            pigpioPWMWrite(GPIO_OUT, PWM_FREQ, duty_cycle);
            log_event("Flame detected");
            prev_state = state;
            prev_duration = duration;
        } else {
            // No flame detected
            pigpioPWMWrite(GPIO_OUT, PWM_FREQ, PWM_MIN);
            log_event("Flame ended");
            prev_state = state;
            prev_duration = 0;
        }

        // Debounce
        if (state != prev_state) {
            usleep(DEBOUNCE_MS * 1000);
        }

        // Sleep for 50 ms
        usleep(50 * 1000);
    }

    return 0;
}

// Function to calculate time difference in seconds
float time_diff(int state1, int state2) {
    return (state1 == 0) ? (time(NULL) - state2) : (state2 - state1);
}

// Signal handler for SIGINT and SIGTERM
void sigint_handler(int sig) {
    sig_handler(sig);
}

// Signal handler for SIGINT and SIGTERM
void sigterm_handler(int sig) {
    sig_handler(sig);
}

// Register signal handlers
void sigaction_handler(int sig) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(sig, &sa, NULL) < 0) {
        log_event("sigaction failed");
        return;
    }
}

int main() {
    // Register signal handlers
    sigaction(SIGINT, &sigterm_handler, NULL);
    sigaction(SIGTERM, &sigterm_handler, NULL);

    // Run the program
    sigaction_handler(2);
    return main();
}

