#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>

#define MAGIC_NUMBER 0x52444144
#define GPIO_TRIGGER 23
#define GPIO_DATA 24
#define GPIO_CE0 8
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_SIZE 32768
#define FRAME_SIZE 64
#define SAMPLE_SIZE 256
#define FRAME_PERIOD 100

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open SPI0.0 at 1 MHz mode 0
    int spi_fd = spiOpen(0, GPIO_CE0, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI0.0\n");
        gpioTerminate();
        return 1;
    }

    // Create a binary log file
    char log_file[] = "log.bin";
    if (access(log_file, F_OK) == 0) {
        unlink(log_file);
    }
    if (mknod(log_file, S_IRUSR | S_IWUSR, 0) < 0) {
        fprintf(stderr, "Failed to create log file\n");
        gpioTerminate();
        return 1;
    }

    // Write log file header
    FILE *log_file_ptr = fopen(log_file, "wb");
    if (log_file_ptr == NULL) {
        fprintf(stderr, "Failed to open log file for writing\n");
        gpioTerminate();
        return 1;
    }
    fwrite(&MAGIC_NUMBER, sizeof(MAGIC_NUMBER), 1, log_file_ptr);
    struct timespec timestamp;
    clock_gettime(CLOCK_REALTIME, &timestamp);
    fwrite(&timestamp.tv_sec, sizeof(timestamp.tv_sec), 1, log_file_ptr);
    struct {
        uint32_t start_freq;
        uint32_t end_freq;
        uint32_t num_chirps;
        uint32_t num_samples;
        uint32_t frame_period;
    } config;
    config.start_freq = 77;
    config.end_freq = 79;
    config.num_chirps = FRAME_SIZE;
    config.num_samples = SAMPLE_SIZE;
    config.frame_period = FRAME_PERIOD;
    fwrite(&config, sizeof(config), 1, log_file_ptr);
    fclose(log_file_ptr);

    // Loop and read frames
    while (1) {
        // Assert GPIO hardware trigger
        if (gpioWrite(GPIO_TRIGGER, 1) < 0) {
            fprintf(stderr, "Failed to assert GPIO trigger\n");
            gpioTerminate();
            return 1;
        }
        // Wait for data-ready interrupt
        if (gpioRead(GPIO_DATA) < 0) {
            fprintf(stderr, "Failed to read GPIO data\n");
            gpioTerminate();
            return 1;
        }
        // Read 32768 bytes of heatmap data via SPI full-duplex transfer
        if (spiXfer(spi_fd, NULL, NULL, SPI_SIZE, SPI_SPEED) < 0) {
            fprintf(stderr, "Failed to read SPI data\n");
            gpioTerminate();
            return 1;
        }
        // Log each frame
        FILE *log_file_ptr = fopen(log_file, "ab");
        if (log_file_ptr == NULL) {
            fprintf(stderr, "Failed to open log file for appending\n");
            gpioTerminate();
            return 1;
        }
        clock_gettime(CLOCK_REALTIME, &timestamp);
        fwrite(&timestamp.tv_sec, sizeof(timestamp.tv_sec), 1, log_file_ptr);
        fwrite(&FRAME_SIZE, sizeof(FRAME_SIZE), 1, log_file_ptr);
        fwrite(&SAMPLE_SIZE, sizeof(SAMPLE_SIZE), 1, log_file_ptr);
        fwrite(&FRAME_PERIOD, sizeof(FRAME_PERIOD), 1, log_file_ptr);
        fwrite(&timestamp.tv_nsec, sizeof(timestamp.tv_nsec), 1, log_file_ptr);
        fwrite(&FRAME_SIZE, sizeof(FRAME_SIZE), 1, log_file_ptr);
        fwrite(&SAMPLE_SIZE, sizeof(SAMPLE_SIZE), 1, log_file_ptr);
        fwrite(&FRAME_PERIOD, sizeof(FRAME_PERIOD), 1, log_file_ptr);
        fclose(log_file_ptr);
    }

    // Handle SIGINT/SIGTERM
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGTERM handler\n");
        gpioTerminate();
        return 1;
    }

    // Close SPI and GPIO
    if (spiClose(spi_fd) < 0) {
        fprintf(stderr, "Failed to close SPI0.0\n");
    }
    if (gpioTerminate() < 0) {
        fprintf(stderr, "Failed to release GPIO\n");
    }

    return 0;
}

