#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <syslog.h>
#include <libgpiod.h>
#include <libgpiod-event.h>

#define GPIO_PIN 20
#define LOG_FILE "flame_log.txt"

int main(int argc, char **argv) {
    // Initialize libgpiod
    if (gpiod_init() != 0) {
        syslog(LOG_ERR, "Failed to initialize libgpiod: %s", strerror(errno));
        return 1;
    }

    // Open the log file
    int log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        gpiod_exit();
        return 1;
    }

    // Open the GPIO pin
    int gpio_fd = gpiod_open(GPIO_20, GPIOD_DIR_OUT, 0);
    if (gpio_fd == -1) {
        syslog(LOG_ERR, "Failed to open GPIO pin %d: %s", GPIO_20, strerror(errno));
        close(log_fd);
        gpiod_exit();
        return 1;
    }

    // Create an event handler for the GPIO pin
    gpiod_event_t *event = gpiod_event_new(gpio_fd, GPIOD_EVENT_EDGE_BOTH, 100);
    if (event == NULL) {
        syslog(LOG_ERR, "Failed to create event handler for GPIO pin %d: %s", GPIO_20, strerror(errno));
        close(log_fd);
        gpiod_close(gpio_fd);
        gpiod_exit();
        return 1;
    }

    // Register the event handler
    if (gpiod_event_register(event) != 0) {
        syslog(LOG_ERR, "Failed to register event handler: %s", strerror(errno));
        gpiod_event_free(event);
        close(log_fd);
        gpiod_close(gpio_fd);
        gpiod_exit();
        return 1;
    }

    // Set the initial state of the GPIO pin
    if (gpiod_event_set_state(event, 0) != 0) {
        syslog(LOG_ERR, "Failed to set initial state of GPIO pin %d: %s", GPIO_20, strerror(errno));
        gpiod_event_free(event);
        close(log_fd);
        gpiod_close(gpio_fd);
        gpiod_exit();
        return 1;
    }

    // Main loop
    while (1) {
        // Poll the event handler
        gpiod_event_poll(event);

        // Check if the event occurred
        if (gpiod_event_occurred(event)) {
            // Get the current state of the GPIO pin
            int state = gpiod_event_get_state(event);

            // Log the state transition
            time_t now = time(NULL);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&now));
            fprintf(log_fd, "%s %s\n", timestamp, state == 0 ? "flame cleared" : "flame detected");
        }
    }

    // Clean up
    gpiod_event_free(event);
    close(log_fd);
    gpiod_close(gpio_fd);
    gpiod_exit();

    return 0;
}

