        close(log_fd);
        gpiod_close(gpio_fd);
        gpiod_exit();
        return 1;
    }

    // Set the initial state of the GPIO pin
    if (gpiod_event_set_state(event, 0) != 0) {
        syslog(LOG_ERR, "Failed to set initial state of GPIO pin %d: %s", GPIO_20, strerror(errno));
        gpiod_event_free(event);
        close(log_fd);
        gpiod_close(gpio_fd);
        gpiod_exit();
        return 1;
    }

    // Main loop
    while (1) {
        // Poll the event handler
        gpiod_event_poll(event);

        // Check if the event occurred
        if (gpiod_event_occurred(event)) {
            // Get the current state of the GPIO pin
            int state = gpiod_event_get_state(event);

            // Log the state transition
            time_t now = time(NULL);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&now));
            fprintf(log_fd, "%s %s\n", timestamp, state == 0 ? "flame cleared" : "flame detected");
        }
    }

    // Clean up
    gpiod_event_free(event);
    close(log_fd);
    gpiod_close(gpio_fd);
    gpiod_exit();

    return 0;
}
