#include <gpiod/gpiod.h>
#include <gpiod/gpiod_types.h>

// Define a volatile sig_atomic_t flag to exit the main loop
volatile sig_atomic_t exit_flag = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int sig) {
    exit_flag = 1;
}

int main(int argc, char **argv) {
    // Initialize the signal handler
    signal(SIGINT, sigint_handler);

    // Open the chip
    gpiod_chip_t *chip;
    gpiod_chip_open(&chip, "gpiochip-pi", NULL, NULL, NULL, NULL, NULL);

    // Request the line
    gpiod_line_config_t *line_config;
    gpiod_line_config_new(&line_config, chip, 17, GPIOD_LINE_CONFIG_INPUT, GPIOD_LINE_CONFIG_ACTIVE_HIGH, GPIOD_LINE_CONFIG_BIAS_PULLED_UP);
    if (line_config == NULL) {
        fprintf(stderr, "Failed to create line config\n");
        return 1;
    }

    gpiod_line_settings_t *line_settings;
    gpiod_line_settings_new(&line_settings, line_config);
    if (line_settings == NULL) {
        fprintf(stderr, "Failed to create line settings\n");
        gpiod_line_config_free(line_config);
        return 1;
