code:
#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %d\n", gpioInitialise());
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(17, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 17 as input: %d\n", gpioSetMode(17, PI_INPUT));
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(18, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 18 as input: %d\n", gpioSetMode(18, PI_INPUT));
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(27, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 27 as input: %d\n", gpioSetMode(27, PI_INPUT));
        gpioTerminate();
        return 1;
    }

    // Set GPIO pull-up resistors
    if (gpioSetPullUpDowntime(17, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set GPIO 17 with pull-up resistor: %d\n", gpioSetPullUpDowntime(17, PI_PUD_UP));
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDowntime(18, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set GPIO 18 with pull-up resistor: %d\n", gpioSetPullUpDowntime(18, PI_PUD_UP));
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDowntime(27, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set GPIO 27 with pull-up resistor: %d\n", gpioSetPullUpDowntime(27, PI_PUD_UP));
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        int left = gpioRead(17);
        int center = gpioRead(18);
        int right = gpioRead(27);

        printf("Left: %d, Center: %d, Right: %d\n", left, center, right);

        // Sleep for 50 ms
        usleep(50000);
    }

    // Clean up
    gpioTerminate();
    return 0;
}

