#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>

#define GPIO_NUM  (2)  // Broadcom GPIO pin numbers
#define CHANNELS  8

int main(int argc, char **argv) {
    int gpio;
    int i;
    struct sigaction sa;
    struct sigaction sa_int, sa_term;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    // Set up signal handlers
    sa.sa_handler = sigpipe;
    sa_int.sa_handler = sigpipe;
    sa_term.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    sigaddset(&sa.sa_mask, SIGTERM);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction SIGINT failed\n");
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa_term, NULL) < 0) {
        fprintf(stderr, "sigaction SIGTERM failed\n");
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGALRM, &sa_int, NULL) < 0) {
        fprintf(stderr, "sigaction SIGALRM failed\n");
        gpioTerminate();
        return 1;
    }

    // Configure GPIOs
    for (i = 0; i < CHANNELS; i++) {
        gpio = gpioGet(GPIO_NUM + i);
        if (gpio < 0) {
            fprintf(stderr, "gpioGet GPIO %d failed\n", GPIO_NUM + i);
            gpioTerminate();
            return 1;
        }
        if (gpioSetMode(gpio, PI_INPUT) < 0) {
            fprintf(stderr, "gpioSetMode GPIO %d failed\n", gpio);
            gpioTerminate();
            return 1;
        }
        if (gpioSetPullUpDowntime(gpio, 100) < 0) {
            fprintf(stderr, "gpioSetPullUpDowntime GPIO %d failed\n", gpio);
            gpioTerminate();
            return 1;
        }
    }

    // Set up alarm
    alarm(100);

    while (1) {
        // Poll and log touch state
        for (i = 0; i < CHANNELS; i++) {
            gpio = gpioGet(GPIO_NUM + i);
            if (gpio < 0) {
                fprintf(stderr, "gpioGet GPIO %d failed\n", GPIO_NUM + i);
                gpioTerminate();
                return 1;
            }
            if (gpioRead(gpio) < 0) {
                fprintf(stderr, "gpioRead GPIO %d failed\n", gpio);
                gpioTerminate();
                return 1;
            }
            printf("[%d ms] CH%d=%d\n", (int)usleep(100), GPIO_NUM + i, gpioRead(gpio));
        }
    }

    // Cleanup
    gpioTerminate();
    return 0;
}

