#include <pigpio.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

#define GPIO_NUM1 4
#define GPIO_NUM2 5
#define INTERVAL 500

int main() {
    int gpio1, gpio2;
    int state1, state2;
    int i;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    // Set GPIO mode to input
    if (gpioMode(GPIO_NUM1, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to input mode\n", GPIO_NUM1);
        gpioTerminate();
        return 1;
    }
    if (gpioMode(GPIO_NUM2, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to input mode\n", GPIO_NUM2);
        gpioTerminate();
        return 1;
    }

    // Read initial state of sensors
    state1 = gpioRead(GPIO_NUM1);
    state2 = gpioRead(GPIO_NUM2);

    while (1) {
        // Read current state of sensors
        state1 = gpioRead(GPIO_NUM1);
        state2 = gpioRead(GPIO_NUM2);

        // Log sensor states
        printf("Sensor 1: %d, Sensor 2: %d\n", state1, state2);

        // Sleep for INTERVAL ms
        usleep(INTERVAL * 1000);

        // Check for SIGINT (Ctrl+C)
        if (gpioGetSignalLevel(SIGINT) > 0) {
            break;
        }
    }

    // Release GPIO resources
    gpioWrite(GPIO_NUM1, 1);
    gpioWrite(GPIO_NUM2, 1);
    gpioTerminate();

    return 0;
}

