#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod/libgpiod.h>

#define GPIO_PIN_2 3
#define GPIO_PIN_3 5
#define GPIO_PIN_4 7
#define GPIO_PIN_17 11
#define GPIO_PIN_27 13
#define GPIO_PIN_22 15
#define GPIO_PIN_10 19
#define GPIO_PIN_9 21

int main(int argc, char *argv[]) {
    gpiod_t *gpiochip;
    gpiod_line_request_t *line_requests[8];
    gpiod_line_request_t *line_request;
    gpiod_line_t *line;
    gpiod_line_t *line2, *line3, *line4, *line17, *line27, *line22, *line10, *line9;
    struct timespec delay;
    struct timespec start_time;
    struct timespec last_poll_time;
    int i, j, ret;
    int pin;

    // Install SIGINT handler for graceful shutdown
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Open gpiochip
    gpiochip = gpiod_chip_open("gpiochip-bcm2835", 0);
    if (gpiochip == NULL) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Request lines
    for (i = 0; i < 8; i++) {
        pin = i + GPIO_PIN_2;
        line_request = gpiod_line_request_new(gpiochip, pin, GPIOD_LINE_INPUT, GPIOD_LINE_EDGE_RISING, GPIOD_LINE_BIAS_DISABLE);
        if (line_request == NULL) {
            perror("gpiod_line_request_new");
            return 1;
        }
        line_requests[i] = line_request;
    }

    // Set up last poll time
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (1) {
        // Poll lines
        for (i = 0; i < 8; i++) {
            pin = i + GPIO_PIN_2;
            line = gpiod_line_request_get(line_requests[i]);
            if (line == NULL) {
                perror("gpiod_line_request_get");
                return 1;
            }
            ret = gpiod_line_request_poll(line, &delay);
            if (ret < 0) {
                perror("gpiod_line_request_poll");
                return 1;
            }
            if (ret > 0) {
                gpiod_line_request_release(line);
                line = NULL;
            }
        }

        // Log binary state to console
        for (i = 0; i < 8; i++) {
            pin = i + GPIO_PIN_2;
            line = gpiod_line_request_get(line_requests[i]);
            if (line == NULL) {
                perror("gpiod_line_request_get");
                return 1;
            }
            ret = gpiod_line_request_get_value(line, &pin);
            if (ret < 0) {
                perror("gpiod_line_request_get_value");
                return 1;
            }
            printf("%ld,%d,%d\n", (long)clock_gettime(CLOCK_MONOTONIC, &last_poll_time).tv_sec,
                   (line->value & 0x1) ? 1 : 0,
                   (line->value & 0x2) ? 1 : 0);
            gpiod_line_request_release(line);
            line = NULL;
        }

        // Update last poll time
        clock_gettime(CLOCK_MONOTONIC, &last_poll_time);

        // Sleep for 50 ms
        nanosleep(&delay, NULL);
    }

    // Release resources
    for (i = 0; i < 8; i++) {
        gpiod_line_request_release(line_requests[i]);
        line_requests[i] = NULL;
    }
    gpiod_chip_close(gpiochip);
    gpiochip = NULL;

    return 0;
}

void sigint_handler(int sig) {
    // Release resources
    for (int i = 0; i < 8; i++) {
        gpiod_line_request_release(line_requests[i]);
        line_requests[i] = NULL;
    }
    gpiod_chip_close(gpiochip);
    gpiochip = NULL;

    // Exit
    exit(0);
}

