// Define the SIGINT handler
void sigint_handler(int sig) {
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", gpioGetError());
        return 1;
    }

    // Set up the GPIO pin as a digital input with internal pull-up resistor
    if (gpioMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting GPIO mode: %s\n", gpioGetError());
        gpioTerminate();
        return 1;
    }

    // Install the SIGINT handler
    signal(SIGINT, sigint_handler);

    // Print the startup banner
    printf("Omron D7E-1 Tilt Sensor Poller\n");

    // Enter the poll loop
    while (1) {
        // Poll the GPIO pin
        int value = gpioRead(GPIO_PIN);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO pin: %s\n", gpioGetError());
            gpioTerminate();
            return 1;
        }

        // Log the tilt state
        if (value == 0) {
            printf("%d.%06d: Tilted\n", time(NULL), getpid());
        } else {
            printf("%d.%06d: Not Tilted\n", time(NULL), getpid());
        }

        // Flush stdout to prevent output loss on early termination
        fflush(stdout);

        // Sleep for the poll interval
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up
    gpioTerminate();
    return 0;
}
