    sa_sigterm.sa_handler = sigpipe;
    sa_sigint.sa_flags = SA_RESTART;
    sa_sigterm.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa_sigint, NULL) < 0) {
        perror("sigaction");
        close(fd);
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa_sigterm, NULL) < 0) {
        perror("sigaction");
        close(fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read UV index and Visible ALS data
        ret = i2cReadByte(fd, I2C_ADDRESS, 0x00);
        if (ret < 0) {
            perror("i2cReadByte");
            close(fd);
            gpioTerminate();
            return 1;
        }
        ret = i2cReadByte(fd, I2C_ADDRESS, 0x01);
        if (ret < 0) {
            perror("i2cReadByte");
            close(fd);
            gpioTerminate();
            return 1;
        }

        // Convert data to uint16_t
        uint16_t data = (ret << 8) | i2cReadByte(fd, I2C_ADDRESS, 0x00);

        // Log data
        time(&ts);
        fprintf(stderr, "Timestamp: %ld, UV Index: %d, Visible ALS: %d\n", ts.tv_sec, data >> 8, data & 0xFF);
        fprintf(CSV_FILE, "%ld,%d,%d\n", ts.tv_sec, data >> 8, data & 0xFF);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    close(fd);
    gpioTerminate();
    return 0;
}

