#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>

#define BUFFER_SIZE 100
#define BUFFER_MAX_AGE 10
#define POLL_INTERVAL_MS 50
#define GPIO_PIN 4

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Verify success
    if (gpioGetVersion() < 0) {
        fprintf(stderr, "Failed to get pigpio version\n");
        gpioTerminate();
        return 1;
    }

    // Configure GPIO 4 as input with internal pull-up resistor
    if (gpioMode(GPIO_PIN, GPIO_IN) < 0) {
        fprintf(stderr, "Failed to configure GPIO %d as input\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioCtsSetup(GPIO_PIN, GPIO_CTS) < 0) {
        fprintf(stderr, "Failed to set up GPIO %d as CTS\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    // Create a circular buffer to store readings
    struct timespec buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int buffer_max_age = 0;

    // Signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler for SIGINT\n");
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Poll GPIO 4
        int reading = gpioGet(GPIO_PIN);
        if (reading == 0) {
            // Record timestamp and reading into the buffer
            struct timespec now;
            clock_gettime(CLOCK_REALTIME, &now);
            buffer[buffer_index].tv_sec = now.tv_sec;
            buffer[buffer_index].tv_nsec = now.tv_nsec;
            buffer[buffer_index].reading = reading;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            buffer_max_age = (buffer_max_age + 1) % BUFFER_MAX_AGE;

            // Print alert if buffer is full
            if (buffer_max_age == BUFFER_MAX_AGE) {
                printf("Obstacle detected!\n");
            }
        }

        // Sleep for POLL_INTERVAL_MS
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Print buffer contents on SIGINT
    if (sigaction(SIGINT, NULL, &sa) < 0) {
        fprintf(stderr, "Failed to restore signal handler for SIGINT\n");
        return 1;
    }

    // Print buffer contents
    printf("Obstacle detection buffer:\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (i > 0) {
            printf("  ");
        }
        if (i < buffer_max_age) {
            printf("%d ", buffer[i].reading);
        } else {
            printf("  -");
        }
        struct timespec now;
        clock_gettime(CLOCK_REALTIME, &now);
        char buffer_time[20];
        strftime(buffer_time, sizeof(buffer_time), "%Y-%m-%d %H:%M:%S", localtime(&now));
        printf("%s", buffer_time);
    }
    printf("\n");

    // Release pigpio resources
    gpioTerminate();
    return 0;
}

void sigint_handler(int sig) {
    // Print buffer contents
    printf("Obstacle detection buffer:\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (i > 0) {
            printf("  ");
