    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(GPIO_LED, 0) < 0) {
        perror("gpioWrite");
        gpioTerminate();
        return 1;
    }
    if (gpioPullUpDowntime(GPIO_LED, PI_PUD_UP) < 0) {
        perror("gpioPullUpDowntime");
        gpioTerminate();
        return 1;
    }

    // Main loop
