        // Read sensor values
        int sensor1 = gpioRead(GPIO_Sensor1);
        int sensor2 = gpioRead(GPIO_Sensor2);

        // Check for obstacles
        if (sensor1 == 0 || sensor2 == 0) {
            // Turn on LED
            gpioWrite(GPIO_LED, 1);
        } else {
            // Turn off LED
            gpioWrite(GPIO_LED, 0);
        }

        // Wait for next poll
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up
    gpioTerminate();
    return 0;
