#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define GPIO17 17
#define GPIO18 18
#define STALL_THRESHOLD 2000 // 2 seconds in milliseconds
#define LOG_FILE "stall_log.txt"

// Initialize pigpio
void init_pigpio() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(1);
    }
}

// Clean up pigpio resources
void cleanup_pigpio() {
    gpioTerminate();
}

// Check if a sensor is active
int is_sensor_active(int gpio) {
    int value;
    if (gpioGetValue(gpio, &value) < 0) {
        perror("gpioGetValue");
        return 1;
    }
    return value;
}

// Log a stall event
void log_stall() {
    struct stat info;
    if (stat(LOG_FILE, &info) == -1) {
        if (mkdir(LOG_FILE, 0755) == -1) {
            perror("mkdir");
            return;
        }
    }
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_file, "%s: Stall detected at %s\n", timestamp, LOG_FILE);
    fclose(log_file);
}

// Main loop
void main_loop() {
    int gpio17_value, gpio18_value;
    int stall_detected = 0;
    int last_stall_time = 0;
    int last_stall_detected = 0;

    init_pigpio();

    while (1) {
        gpio17_value = is_sensor_active(GPIO17);
        gpio18_value = is_sensor_active(GPIO18);

        if (gpio17_value == 0 && gpio18_value == 0) {
            if (time(NULL) - last_stall_time > STALL_THRESHOLD) {
                if (last_stall_detected == 0) {
                    log_stall();
                    last_stall_detected = 1;
                }
            } else {
                last_stall_detected = 0;
            }
        } else {
            last_stall_detected = 0;
        }

        if (gpio17_value == 1 && gpio18_value == 1) {
            last_stall_time = time(NULL);
        }
    }

    cleanup_pigpio();
}

// Signal handler for SIGINT and SIGTERM
void sig_handler(int sig) {
    cleanup_pigpio();
    exit(0);
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    main_loop();

    return 0;
}

