            if (time(NULL) - last_stall_time > STALL_THRESHOLD) {
                if (last_stall_detected == 0) {
                    log_stall();
                    last_stall_detected = 1;
                }
            } else {
                last_stall_detected = 0;
            }
        } else {
            last_stall_detected = 0;
        }

        if (gpio17_value == 1 && gpio18_value == 1) {
            last_stall_time = time(NULL);
        }
    }

    cleanup_pigpio();
}

// Signal handler for SIGINT and SIGTERM
void sig_handler(int sig) {
    cleanup_pigpio();
    exit(0);
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    main_loop();

    return 0;
}
