#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>

#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    // Set GPIO pin 4 as input with internal pull-up resistor
    if (gpioMode(GPIO_PIN, GPIO_IN) < 0) {
        fprintf(stderr, "Failed to set GPIO pin 4 as input\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin 4 as an interrupt on rising edge
    if (gpioEdge(GPIO_PIN, GPIO_RISING, GPIO_INT_EDGE) < 0) {
        fprintf(stderr, "Failed to set GPIO pin 4 as interrupt on rising edge\n");
        gpioTerminate();
        return 1;
    }

    // Set up a timer to trigger every 1 second
    struct itimer it;
    it.it_value.tv_sec = 1;
    it.it_value.tv_usec = 0;
    if (itimerSet(&it) < 0) {
        fprintf(stderr, "Failed to set timer\n");
        gpioTerminate();
        return 1;
    }

    // Set up a callback function to handle interrupts
    void (*callback)(void) = [](void* arg) {
        // Get the current time
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Read the RPM
        int rpm = 0;
        if (gpioRead(GPIO_PIN) == 0) {
            rpm = 0;
        } else {
            // Count rising-edge pulses in a 1-second window
            int pulses = 0;
            for (int i = 0; i < 100; i++) {
                if (gpioRead(GPIO_PIN) == 0) {
                    pulses++;
                }
                usleep(10000); // 10ms delay
            }
            rpm = pulses * 60;
        }

        // Log RPM to file and stdout
        FILE* log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            gpioTerminate();
            return;
        }
        fprintf(log_file, "%s %d\n", timestamp, rpm);
        fclose(log_file);

        printf("%s %d\n", timestamp, rpm);

        // Disable the timer
        itimerDisable(&it);
    };

    // Install the callback function
    if (gpioHook(GPIO_PIN, GPIO_RISING, callback, NULL) < 0) {
        fprintf(stderr, "Failed to install callback function\n");
        gpioTerminate();
        return 1;
    }

    // Install SIGINT and SIGTERM handlers
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler\n");
        gpioTerminate();
        return 1;
    }

    // Run the timer
    itimerEnable(&it);

    // Wait for the program to exit
    while (1) {
        // Do nothing
    }

    // Clean up
    gpioTerminate();
    return 0;
}

