#include <fcntl.h>
#include <errno.h>

#define GPIO_A 17
#define GPIO_B 27
#define GPIO_PUD 1
#define LOG_FILE "rotation_log.txt"

// Mutex for shared state
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// State machine states
enum state {
    STATE_STOP,
    STATE_A_HIGH,
    STATE_A_LOW,
    STATE_B_HIGH,
    STATE_B_LOW,
    STATE_QUAD
};

// State machine transitions
enum state transition(enum state, enum state) {
    enum state next_state;
    switch (state) {
        case STATE_STOP:
            next_state = STATE_A_HIGH;
            break;
        case STATE_A_HIGH:
            if (gpioRead(GPIO_A) == 0) {
                next_state = STATE_A_LOW;
            } else {
                next_state = STATE_B_HIGH;
            }
            break;
        case STATE_A_LOW:
            if (gpioRead(GPIO_A) == 1) {
                next_state = STATE_A_HIGH;
            } else {
                next_state = STATE_B_LOW;
            }
            break;
        case STATE_B_HIGH:
            if (gpioRead(GPIO_B) == 0) {
                next_state = STATE_B_LOW;
            } else {
                next_state = STATE_A_HIGH;
            }
            break;
        case STATE_B_LOW:
            if (gpioRead(GPIO_B) == 1) {
                next_state = STATE_B_HIGH;
            } else {
                next_state = STATE_STOP;
            }
            break;
        default:
            next_state = STATE_STOP;
            break;
    }
    return next_state;
}

// State machine function
void state_machine(enum state *state) {
    enum state next_state = transition(*state, *state);
    pthread_mutex_lock(&mutex);
    *state = next_state;
    pthread_mutex_unlock(&mutex);
}

// Alert function for edge-triggered interrupts
void alert_func(int gpio, int level, int edge) {
    enum state state;
    pthread_mutex_lock(&mutex);
    state = *state_machine;
    pthread_mutex_unlock(&mutex);
