#define GPIO_A 17
#define GPIO_B 27
#define GPIO_PUD 1
#define LOG_FILE "rotation_log.txt"

// Mutex for shared state
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// State machine states
enum state {
    STATE_STOP,
    STATE_A_HIGH,
    STATE_A_LOW,
    STATE_B_HIGH,
    STATE_B_LOW,
    STATE_QUAD
};

// State machine transitions
enum state transition(enum state, enum state) {
    enum state next_state;
    switch (state) {
        case STATE_STOP:
            next_state = STATE_A_HIGH;
            break;
        case STATE_A_HIGH:
            if (gpioRead(GPIO_A) == 0) {
                next_state = STATE_A_LOW;
            } else {
                next_state = STATE_B_HIGH;
            }
            break;
        case STATE_A_LOW:
            if (gpioRead(GPIO_A) == 1) {
                next_state = STATE_A_HIGH;
            } else {
                next_state = STATE_B_LOW;
            }
            break;
        case STATE_B_HIGH:
            if (gpioRead(GPIO_B) == 0) {
                next_state = STATE_B_LOW;
            } else {
                next_state = STATE_A_HIGH;
            }
            break;
        case STATE_B_LOW:
            if (gpioRead(GPIO_B) == 1) {
                next_state = STATE_B_HIGH;
            } else {
                next_state = STATE_STOP;
            }
            break;
        default:
            next_state = STATE_STOP;
            break;
    }
    return next_state;
}

// State machine function
void state_machine(enum state *state) {
    enum state next_state = transition(*state, *state);
    pthread_mutex_lock(&mutex);
    *state = next_state;
    pthread_mutex_unlock(&mutex);
}

// Alert function for edge-triggered interrupts
void alert_func(int gpio, int level, int edge) {
    enum state state;
    pthread_mutex_lock(&mutex);
    state = *state_machine;
    pthread_mutex_unlock(&mutex);
    if (edge == PIGO_EDGE_RISING) {
        if (state == STATE_A_HIGH && state_machine(&state) == STATE_B_HIGH) {
            printf("%s CW\n", ctime(&time(NULL));
            FILE *log_file = fopen(LOG_FILE, "a");
            if (log_file == NULL) {
                perror("fopen");
                exit(1);
            }
            fprintf(log_file, "%s %d:%d\n", ctime(&time(NULL)), GPIO_A, GPIO_B);
            fclose(log_file);
        } else if (state == STATE_B_HIGH && state_machine(&state) == STATE_A_HIGH) {
            printf("%s CCW\n", ctime(&time(NULL)));
            FILE *log_file = fopen(LOG_FILE, "a");
            if (log_file == NULL) {
                perror("fopen");
                exit(1);
            }
            fprintf(log_file, "%s %d:%d\n", ctime(&time(NULL)), GPIO_A, GPIO_B);
            fclose(log_file);
        }
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(1);
    }

    // Set up GPIO pins
    if (gpioSetPullUpDown(GPIO_A, PUD_UP) < 0) {
        perror("gpioSetPullUpDown");
        exit(1);
    }
    if (gpioSetPullUpDown(GPIO_B, PUD_UP) < 0) {
        perror("gpioSetPullUpDown");
        exit(1);
    }

