#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod/libgpiod.h>

// Define constants
#define GPIO_LINE_17 17
#define GPIO_LINE_18 18
#define DEBOUNCE_TIME 50

// Define the chip and line
gpiod_chip_t *chip;
gpiod_line_t *line;

// Define the LED pin
gpiod_pin_t *led_pin;

// Define the event callback
void event_cb(gpiod_line_event_t event, void *user_data) {
    if (event == GPIOD_LINE_RISING) {
        // Toggle the LED
        gpiod_pin_write(led_pin, !gpiod_pin_read(led_pin));
    }
}

int main(int argc, char *argv[]) {
    // Initialize libgpiod
    if (gpiod_init() != 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Open the chip
    chip = gpiod_chip_open("gpiochip-pi", NULL);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open chip\n");
        gpiod_exit();
        return 1;
    }

    // Open the line
    line = gpiod_line_open(chip, GPIO_LINE_17, GPIOD_LINE_RISING, event_cb, NULL);
    if (line == NULL) {
        fprintf(stderr, "Failed to open line %d\n", GPIO_LINE_17);
        gpiod_chip_close(chip);
        gpiod_exit();
        return 1;
    }

    // Open the LED pin
    led_pin = gpiod_pin_open(chip, GPIO_LINE_18, GPIOD_OUTPUT);
    if (led_pin == NULL) {
        fprintf(stderr, "Failed to open pin %d\n", GPIO_LINE_18);
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        gpiod_exit();
        return 1;
    }

    // Set the LED pin as output
    if (gpiod_pin_direction(led_pin, GPIOD_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set pin %d as output\n", GPIO_LINE_18);
        gpiod_pin_close(led_pin);
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        gpiod_exit();
        return 1;
    }

    // Drive the LED pin low
    if (gpiod_pin_write(led_pin, 0) != 0) {
        fprintf(stderr, "Failed to write to pin %d\n", GPIO_LINE_18);
        gpiod_pin_close(led_pin);
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        gpiod_exit();
        return 1;
    }

    // Wait for the program to be interrupted
    signal(SIGINT, SIG_IGN);
    signal(SIGTERM, SIG_IGN);

    // Main loop
    while (1) {
        // Wait for an event on the line
        gpiod_line_wait(line, DEBOUNCE_TIME);
        if (gpiod_line_is_event(line) != 0) {
            fprintf(stderr, "Event on line %d\n", GPIO_LINE_17);
        }
    }

    // Release resources
    gpiod_pin_close(led_pin);
    gpiod_line_close(line);
    gpiod_chip_close(chip);
    gpiod_exit();

    return 0;
}

