#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#define BUFFER_SIZE 100
#define LED1_GPIO 27
#define LED2_GPIO 22
#define TOUCH1_GPIO 4
#define TOUCH2_GPIO 17
#define DEBOUNCE_TIME 50
#define LOG_FILE "/var/log/touch_log.txt"

int gpio;
int led1, led2, touch1, touch2;
int buffer[BUFFER_SIZE];
int buffer_index = 0;
int overflow_count = 0;

void init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        exit(1);
    }

    if (gpioSetMode(led1, GPIO_MODE_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(led1) failed\n");
        gpioTerminate();
        exit(1);
    }
    if (gpioSetMode(led2, GPIO_MODE_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(led2) failed\n");
        gpioTerminate();
        exit(1);
    }
    if (gpioSetMode(touch1, GPIO_MODE_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(touch1) failed\n");
        gpioTerminate();
        exit(1);
    }
    if (gpioSetMode(touch2, GPIO_MODE_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(touch2) failed\n");
        gpioTerminate();
        exit(1);
    }

    gpioWrite(led1, 0);
    gpioWrite(led2, 0);
}

void log_event(int sensor, int state) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    char buffer[20];
    sprintf(buffer, "%d %s %d %d\n", sensor, timestamp, state, state);
    if (buffer_index >= BUFFER_SIZE) {
        overflow_count++;
    } else {
        buffer[buffer_index] = '\0';
        strcat(buffer, buffer);
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    }
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "fopen failed\n");
        gpioTerminate();
        exit(1);
    }
    fprintf(log_file, "%s", buffer);
    fclose(log_file);
}

void handle_signal(int sig) {
    gpioWrite(led1, 0);
    gpioWrite(led2, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed\n");
        gpioTerminate();
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed\n");
        gpioTerminate();
        exit(1);
    }

    init_gpio();

    while (1) {
        int state1 = gpioRead(touch1);
        int state2 = gpioRead(touch2);
        if (state1 == 1) {
            log_event(TOUCH1_GPIO, 1);
            gpioWrite(led1, 1);
        } else {
            log_event(TOUCH1_GPIO, 0);
            gpioWrite(led1, 0);
        }
        if (state2 == 1) {
            log_event(TOUCH2_GPIO, 1);
            gpioWrite(led2, 1);
        } else {
            log_event(TOUCH2_GPIO, 0);
            gpioWrite(led2, 0);
        }
        usleep(DEBOUNCE_TIME * 1000);
    }

    FILE *log_file = fopen(LOG_FILE, "r");
    if (log_file == NULL) {
        fprintf(stderr, "fopen failed\n");
        exit(1);
    }
    fprintf(stderr, "Log:\n");
    while (fgets(buffer, BUFFER_SIZE, log_file) != NULL) {
        fprintf(stderr, "%s", buffer);
    }
    fprintf(stderr, "Overflow count: %d\n", overflow_count);
    fclose(log_file);
    return 0;
}

