    pigpio *gpio = pigpio_get();
    if (gpio == NULL) {
        perror("pigpio_get");
        return 1;
    }

    gpio_set_mode(GPIO_PIN, PI_INPUT);
    gpio_pull_up_downtime(GPIO_PIN, 1);

