    if (log_file == NULL) {
        perror("fopen");
        pigpio_close(gpio);
        return 1;
    }

    struct timespec last_state = {0, 0};
    while (1) {
        int state = gpio_get_value(GPIO_PIN);
        if (state != last_state.value) {
            char state_str[10];
            if (state == 0) {
                sprintf(state_str, "Rain Detected at %ld", time(NULL));
            } else {
                sprintf(state_str, "No Rain at %ld", time(NULL));
            }
            syslog(LOG_INFO, "%s", state_str);
            fwrite(state_str, strlen(state_str), 1, log_file);
            last_state = (struct timespec){time(NULL), 0};
        }
        usleep(500000);
    }

    fclose(log_file);
    pigpio_close(gpio);
    return 0;
}

