    time_t last_state_change;
} sensor_state_t;

// Structure to hold sensor data
typedef struct {
    sensor_state_t sensor1;
    sensor_state_t sensor2;
} sensor_data_t;

// Function to read sensor data
sensor_data_t read_sensor_data(pigpio *gpio) {
    sensor_data_t data;
    data.sensor1.state = gpio.read(GPIO17);
    data.sensor1.last_state_change = time(NULL);
    data.sensor2.state = gpio.read(GPIO18);
    data.sensor2.last_state_change = time(NULL);
    return data;
}

// Function to calculate RPM
int calculate_rpm(sensor_data_t data) {
    int time_diff = difftime(time(NULL), data.sensor1.last_state_change);
    if (time_diff == 0) {
        return 0;
    }
    return (data.sensor1.state == data.sensor2.state) ? 0 : 60000 / time_diff;
}

// Function to write to CSV file
void write_to_csv(pigpio *gpio, sensor_data_t data) {
    FILE *file = fopen(CSV_FILE, "a");
    if (file == NULL) {
        perror("Error opening CSV file");
        return;
    }
    fprintf(file, "%ld,%d,%d\n", time(NULL), data.sensor1.state, data.sensor2.state);
    fclose(file);
}

// Function to handle signal SIGINT
void sigint_handler(int sig) {
    pigpio_close(gpio);
    exit(0);
}

int main() {
    pigpio *gpio = pigpio_init();
    if (gpio == NULL) {
        perror("Error initializing pigpio");
        return 1;
    }

    // Set GPIO 17 and 18 as output
    gpio_set_mode(GPIO17, PI_OUTPUT);
    gpio_set_mode(GPIO18, PI_OUTPUT);

    // Set GPIO 17 and 18 as output with initial state
    gpio.write(GPIO17, 1);
    gpio.write(GPIO18, 1);

    // Debounce mechanism
    struct timespec debounce_time = {0, 5};
    struct timespec last_debounce_time = {0, 0};

    while (1) {
        sensor_data_t data = read_sensor_data(gpio);
        int rpm = calculate_rpm(data);

        // Debounce mechanism
        struct timespec current_time = {0, 0};
        if (difftime(current_time.tv_sec, last_debounce_time.tv_sec) > debounce_time.tv_sec ||
            difftime(current_time.tv_sec, last_debounce_time.tv_sec) == 0 &&
            difftime(current_time.tv_nsec, last_debounce_time.tv_nsec) > debounce_time.tv_nsec) {
            if (data.sensor1.state != data.sensor2.state) {
                write_to_csv(gpio, data);
                last_debounce_time = current_time;
            }
        }

        // Update last state change time
        data.sensor1.last_state_change = current_time.tv_sec;
        data.sensor2.last_state_change = current_time.tv_sec;

        // Print RPM
        printf("%d\n", rpm);

        // Update GPIO state
        gpio.write(GPIO17, data.sensor1.state);
        gpio.write(GPIO18, data.sensor2.state);

        // Sleep for 1 ms
        usleep(1000);
    }

    // Clean up
    pigpio_close(gpio);
    return 0;
}
```

This code initializes the pigpio library, sets up GPIO 17 and 18 as output, and reads the state of the two sensors. It calculates the RPM based on the sensor states and prints it to the console. The code also writes the sensor states to a CSV file and implements a debounce mechanism to avoid false readings. The program handles potential errors and cleans up resources on exit. The signal handler for SIGINT (Ctrl+C) is also implemented to ensure clean exit.

