#include <sys/mman.h>
#include <sys/ioctl.h>
#include <termios.h>
#include <unistd.h>

#define I2C_ADDRESS 0x28
#define I2C Bus 1
#define CONFIG_REGISTER 0x30
#define PART_ID_REGISTER 0x00
#define HEART_RATE_REGISTER 0x02
#define SPO2_REGISTER 0x04
#define LOG_FILE "biometric_log.txt"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C bus
    int i2c_fd = i2cOpen(I2C Bus, I2C_ADDRESS);
    if (i2c_fd < 0) {
        perror("i2cOpen");
        gpioTerminate();
        return 1;
    }

    // Verify sensor is present
    unsigned char part_id;
    if (i2cRead(i2c_fd, &part_id, 1) < 0) {
        perror("i2cRead");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (part_id != 0x00) {
        fprintf(stderr, "Sensor not found\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Configure sensor for continuous measurement
    if (i2cWrite(i2c_fd, CONFIG_REGISTER, 0x01) < 0) {
        perror("i2cWrite");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    int log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd < 0) {
        perror("open");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        close(log_fd);
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read heart rate data
        unsigned char heart_rate;
        if (i2cRead(i2c_fd, &heart_rate, 1) < 0) {
            perror("i2cRead");
            continue;
        }

        // Read SpO2 data
        unsigned char spo2;
        if (i2cRead(i2c_fd, &spo2, 1) < 0) {
            perror("i2cRead");
            continue;
        }

        // Calculate heart rate in BPM
        int heart_rate_bpm = (heart_rate & 0x3F) * 2;

        // Log reading
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_fd, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate_bpm, spo2);
        fflush(log_fd);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    close(log_fd);
    i2cClose(i2c_fd);
    gpioTerminate();

    return 0;
}

