#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>

#define GPIO_TILT1 17
#define GPIO_TILT2 18
#define GPIO_ALARM 27
#define LOG_FILE "bridge_integrity.log"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        return 1;
    }

    // Set GPIO 27 as an output
    if (gpioMode(GPIO_ALARM, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO 27 as output");
        gpioTerminate();
        return 1;
    }

    // Set GPIO 27 as LOW
    if (gpioWrite(GPIO_ALARM, 0) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO 27 as LOW");
        gpioTerminate();
        return 1;
    }

    // Set GPIO 17 and 18 as inputs with internal pull-down resistors
    if (gpioMode(GPIO_TILT1, PI_INPUT_PUD_DOWN) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO 17 as input with pull-down resistor");
        gpioTerminate();
        return 1;
    }
    if (gpioMode(GPIO_TILT2, PI_INPUT_PUD_DOWN) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO 18 as input with pull-down resistor");
        gpioTerminate();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Set up alarm
    struct timespec last_tilt1, last_tilt2;
    struct timespec now;
    while (1) {
        // Get current time
        clock_gettime(CLOCK_REALTIME, &now);

        // Read sensor values
        int tilt1 = gpioRead(GPIO_TILT1);
        int tilt2 = gpioRead(GPIO_TILT2);

        // Check if either sensor has exceeded threshold
        if (tilt1 == 1 && last_tilt1.tv_sec != now.tv_sec || tilt2 == 1 && last_tilt2.tv_sec != now.tv_sec) {
            // Log tilt event
            fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02d.000000Z Tilt detected\n",
                    now.tv_year, now.tv_mon + 1, now.tv_mday, now.tv_hour, now.tv_min, now.tv_sec);
            if (tilt1 == 1) {
                fprintf(log_file, "Sensor 1 exceeded threshold\n");
            } else {
                fprintf(log_file, "Sensor 2 exceeded threshold\n");
            }
            last_tilt1 = now;
            last_tilt2 = now;
        }

        // Check if both sensors have returned to LOW
        if (tilt1 == 0 && tilt2 == 0) {
            // Log tilt-end event
            fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02d.000000Z Tilt ended\n",
                    now.tv_year, now.tv_mon + 1, now.tv_mday, now.tv_hour, now.tv_min, now.tv_sec);
            last_tilt1 = {0, 0};
            last_tilt2 = {0, 0};
        }

        // Activate alarm if either sensor has exceeded threshold for more than 2 seconds
        if (tilt1 == 1 && (last_tilt1.tv_sec + 2 < now.tv_sec) || tilt2 == 1 && (last_tilt2.tv_sec + 2 < now.tv_sec)) {
            gpioWrite(GPIO_ALARM, 1);
            fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02d.000000Z Alarm triggered\n",
                    now.tv_year, now.tv_mon + 1, now.tv_mday, now.tv_hour, now.tv_min, now.tv_sec);
        } else if (tilt1 == 0 && tilt2 == 0) {
            gpioWrite(GPIO_ALARM, 0);
        }

        // Log last_tilt1 and last_tilt2 values
        fprintf(log_file, "last_tilt1.tv_sec = %d, last_tilt2.tv_sec = %d\n", last_tilt1.tv_sec, last_tilt2.tv_sec);

        // Delay for 100 ms
        gpioDelay(100);

        // Update last_tilt1 and last_tilt2
        last_tilt1.tv_sec = now.tv_sec;
        last_tilt2.tv_sec = now.tv_sec;
    }

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

