#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod/gpiod.h>

// Define constants
#define GPIO_PIN_4 4
#define GPIO_PIN_17 17
#define GPIO_PIN_27 27
#define GPIO_PIN_22 22
#define GPIO_PIN_LED 18
#define POLL_INTERVAL 50

// Define a structure to hold the GPIO lines
struct gpio_lines {
    gpiod_line_t *line4;
    gpiod_line_t *line17;
    gpiod_line_t *line27;
    gpiod_line_t *line22;
    gpiod_line_t *led;
};

// Function to initialize the GPIO lines
int init_gpio_lines(struct gpio_lines *lines) {
    // Initialize the GPIO lines
    if (gpiod_line_open(&lines->line4, GPIO_PIN_4, GPIOD_LINE_IN, GPIOD_LINE_EDGE_RISING, NULL, NULL) < 0) {
        perror("Failed to open line 4");
        return -1;
    }
    if (gpiod_line_open(&lines->line17, GPIO_PIN_17, GPIOD_LINE_IN, GPIOD_LINE_EDGE_RISING, NULL, NULL) < 0) {
        perror("Failed to open line 17");
        gpiod_line_close(lines->line4);
        return -1;
    }
    if (gpiod_line_open(&lines->line27, GPIO_PIN_27, GPIOD_LINE_IN, GPIOD_LINE_EDGE_RISING, NULL, NULL) < 0) {
        perror("Failed to open line 27");
        gpiod_line_close(lines->line4);
        gpiod_line_close(lines->line17);
        return -1;
    }
    if (gpiod_line_open(&lines->line22, GPIO_PIN_22, GPIOD_LINE_IN, GPIOD_LINE_EDGE_RISING, NULL, NULL) < 0) {
        perror("Failed to open line 22");
        gpiod_line_close(lines->line4);
        gpiod_line_close(lines->line17);
        gpiod_line_close(lines->line27);
        return -1;
    }
    if (gpiod_line_open(&lines->led, GPIO_PIN_LED, GPIOD_LINE_OUT, GPIOD_LINE_HIGH, NULL, NULL) < 0) {
        perror("Failed to open LED line");
        gpiod_line_close(lines->line4);
        gpiod_line_close(lines->line17);
        gpiod_line_close(lines->line27);
        gpiod_line_close(lines->line22);
        return -1;
    }

    return 0;
}

// Function to handle the SIGINT signal
void sigint_handler(int sig) {
    // Close all GPIO lines
    gpiod_line_close(lines->line4);
    gpiod_line_close(lines->line17);
    gpiod_line_close(lines->line27);
    gpiod_line_close(lines->line22);
    gpiod_line_close(lines->led);

    // Exit the program
    exit(0);
}

int main() {
    // Register the SIGINT handler
    signal(SIGINT, sigint_handler);

    // Define the GPIO lines
    struct gpio_lines lines;
    lines.line4 = NULL;
    lines.line17 = NULL;
    lines.line27 = NULL;
    lines.line22 = NULL;
    lines.led = NULL;

    // Initialize the GPIO lines
    if (init_gpio_lines(&lines) < 0) {
        perror("Failed to initialize GPIO lines");
        return -1;
    }

    // Poll the lines every 50 ms
    while (1) {
        // Read the lines
        int state4 = gpiod_line_read(lines.line4);
        int state17 = gpiod_line_read(lines.line17);
        int state27 = gpiod_line_read(lines.line27);
        int state22 = gpiod_line_read(lines.line22);

        // Turn on the LED if any sensor detects an object
        if (state4 == 0 || state17 == 0 || state27 == 0 || state22 == 0) {
            gpiod_line_write(lines.led, 0);
        } else {
            gpiod_line_write(lines.led, 1);
        }

        // Sleep for 50 ms
        usleep(POLL_INTERVAL * 1000);
    }

    // Cleanly release all resources
    gpiod_line_close(lines.line4);
    gpiod_line_close(lines.line17);
    gpiod_line_close(lines.line27);
    gpiod_line_close(lines.line22);
    gpiod_line_close(lines.led);

    return 0;
}

