#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod/gpiod.h>
#include <gpiod/gpiod-internal.h>

#define NUM_SENSORS 5
#define GPIO Pins (2, 3, 4, 17, 27)
#define DEBOUNCE_TIME 50
#define LOG_FILE "/var/log/flame_events.log"

volatile sig_atomic_t stop = 0;

void sigint_handler(int sig) {
    stop = 1;
    gpiod_chip_close(chip);
    syslog(LOG_USER, "flame_monitor: SIGINT received, shutting down");
    closelog();
    exit(0);
}

void sigterm_handler(int sig) {
    stop = 1;
    gpiod_chip_close(chip);
    syslog(LOG_USER, "flame_monitor: SIGTERM received, shutting down");
    closelog();
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_SENSORS];
    struct gpiod_line_request *requests[NUM_SENSORS];
    struct gpiod_line *line;
    struct gpiod_line_request *req;
    struct timespec delay;
    struct timespec last_read;
    struct timespec now;
    char timestamp[32];
    char sensor_id[10];
    char pin[10];
    char event[128];

    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open chip
    chip = gpiod_chip_open("gpio-3.3v3");
    if (!chip) {
        syslog(LOG_USER, "flame_monitor: failed to open chip");
        return 1;
    }

    // Open lines
    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_line_open(chip, GPIO_Pins[i]);
        if (!lines[i]) {
            syslog(LOG_USER, "flame_monitor: failed to open line %d", GPIO_Pins[i]);
            continue;
        }

        // Request line
        requests[i] = gpiod_line_request(chip, lines[i], GPIO_Pins[i], GPIO_DIR_IN, GPIO_EDGE_RISING, NULL);
        if (!requests[i]) {
            syslog(LOG_USER, "flame_monitor: failed to request line %d", GPIO_Pins[i]);
            gpiod_line_close(lines[i]);
            continue;
        }

        // Read line
        req = gpiod_line_request_get(requests[i]);
        if (!req) {
            syslog(LOG_USER, "flame_monitor: failed to get request for line %d", GPIO_Pins[i]);
            gpiod_line_request_cancel(requests[i]);
            gpiod_line_close(lines[i]);
            continue;
        }

        // Read line
        gpiod_line_read(req, &last_read, &delay);
        if (last_read.value == 0) {
            // Debounce
            struct timespec now;
            gpiod_line_read(req, &now, &delay);
            if (now.tv_sec != last_read.tv_sec || now.tv_nsec != last_read.tv_nsec) {
                // Write event to log
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S%z", localtime(&now));
                sprintf(sensor_id, "%s", "Sensor");
                sprintf(pin, "GPIO %d", GPIO_Pins[i]);
                sprintf(event, "%s - %s (%s) - Flame Detected", timestamp, sensor_id, pin);
                FILE *log_file = fopen(LOG_FILE, "a");
                if (!log_file) {
                    syslog(LOG_USER, "flame_monitor: failed to open log file");
                    continue;
                }
                fprintf(log_file, "%s\n", event);
                fclose(log_file);
            }
        }

        gpiod_line_request_cancel(req);
        gpiod_line_close(lines[i]);
    }

    // Close chip
    gpiod_chip_close(chip);

    // Wait for signal
    while (!stop) {
        usleep(1000000);
    }

    return 0;
}

