    { .index = 2, .physical = 13 },
    { .index = 3, .physical = 19 },
    { .index = 4, .physical = 26 },
    { .index = 5, .physical = 12 },
    { .index = 6, .physical = 16 },
    { .index = 7, .physical = 20 }
