int main(int argc, char **argv) {
    gpiod_context_t *ctx;
    gpiod_pin_t *pins[8];
    gpiod_line_t *lines[8];
    gpiod_line_bulk_t *bulk;
    gpiod_event_t *events;
    gpiod_event_t *event;
    gpiod_event_t *new_event;
    int i, j, ret, state, state_prev;
    struct timespec ts;
    struct timespec ts_prev;
    struct sigaction sa;

    // Initialize signal handler for SIGINT
    sa.sa_handler = sigaction(SIGINT, SIG_IGN, NULL);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    // Initialize libgpiod
    ctx = gpiod_context_new(NULL);
    if (!ctx) {
        perror("gpiod_context_new");
        return 1;
    }

    // Create a new event loop
    events = gpiod_event_new(ctx, GPIOD_EVENT_TYPE_LINE, NULL);
    if (!events) {
        gpiod_context_free(ctx);
        perror("gpiod_event_new");
        return 1;
    }

    // Create a new bulk line request
    bulk = gpiod_line_bulk_new(ctx, 8, TOUCH_PIN_MAP, NULL);
    if (!bulk) {
        gpiod_event_free(events);
        gpiod_context_free(ctx);
        perror("gpiod_line_bulk_new");
        return 1;
    }

    // Create individual lines
    for (i = 0; i < 8; i++) {
        pins[i] = gpiod_pin_new(ctx, TOUCH_PIN_MAP[i].physical);
        if (!pins[i]) {
            gpiod_line_bulk_free(bulk);
            gpiod_event_free(events);
            gpiod_context_free(ctx);
            perror("gpiod_pin_new");
            return 1;
        }
        lines[i] = gpiod_line_new(ctx, pins[i], bulk);
        if (!lines[i]) {
            gpiod_pin_free(pins[i]);
            gpiod_line_bulk_free(bulk);
            gpiod_event_free(events);
            gpiod_context_free(ctx);
            perror("gpiod_line_new");
            return 1;
        }
    }

    // Set the initial state of the lines
    for (i = 0; i < 8; i++) {
        gpiod_line_set_state(lines[i], 0);
    }

    // Main loop
    while (1) {
        // Get the current time
        clock_gettime(CLOCK_REALTIME, &ts);

        // Check for new events
        gpiod_event_wait(events, &ts, 50);

        // Check for new events
        for (i = 0; i < 8; i++) {
            gpiod_event_get(events, &event, 1);
            if (event) {
                // Check if the event is a line change
                if (event->type == GPIOD_EVENT_TYPE_LINE) {
                    // Get the line index and state
                    j = event->line->index;
                    state = event->line->state;

                    // Check if the state has changed
                    if (state != state_prev) {
                        // Log the event
                        printf("%Y-%m-%d %H:%M:%S.%06d %d %d\n",
                               ts.tv_sec, ts.tv_nsec / 1000000000,
                               TOUCH_PIN_MAP[j].index, TOUCH_PIN_MAP[j].physical,
                               state);

                        // Update the previous state
                        state_prev = state;
                    }

                    // Release the event
                    gpiod_event_free(event);
                }
            }
        }

        // Release the bulk line request
        gpiod_line_bulk_release(bulk);
    }

    // Clean up
    for (i = 0; i < 8; i++) {
        gpiod_line_free(lines[i]);
        gpiod_pin_free(pins[i]);
    }
    gpiod_line_bulk_free(bulk);
    gpiod_event_free(events);
    gpiod_context_free(ctx);

    return 0;
}

