#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDRESS 0x10
#define I2C Bus 1
#define GPIO_PIN 18
#define PWM_FREQ 1000
#define PWM_RANGE 100
#define ALS_GAIN 0x00
#define ALS_INTEGRATION_TIME 0x00
#define ALS_REG_CONFIG 0x00
#define ALS_REG_DATA 0x04
#define LOG_FILE "grow_log.txt"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    // Open I2C bus
    if (i2cInit(I2C Bus, I2C_ADDRESS) < 0) {
        fprintf(stderr, "I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Configure ALS sensor
    uint16_t config = (ALS_GAIN << 8) | ALS_INTEGRATION_TIME;
    if (i2cWrite(I2C Bus, ALS_REG_CONFIG, config) < 0) {
        fprintf(stderr, "ALS config write failed\n");
        i2cClose(I2C Bus);
        gpioTerminate();
        return 1;
    }

    // Open log file
    struct stat sb;
    if (stat(LOG_FILE, &sb) != 0) {
        if (mkdir(LOG_FILE, 0755) != 0) {
            fprintf(stderr, "Failed to create log file %s\n", LOG_FILE);
            i2cClose(I2C Bus);
            gpioTerminate();
            return 1;
        }
    }

    // Open log file for writing
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(I2C Bus);
        gpioTerminate();
        return 1;
    }

    // Set up PWM
    if (gpioSetupPWM(GPIO_PIN, PWM_FREQ, PWM_RANGE) < 0) {
        fprintf(stderr, "PWM setup failed\n");
        fclose(log_file);
        i2cClose(I2C Bus);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read ALS data
        uint16_t raw;
        if (i2cRead(I2C Bus, ALS_REG_DATA, &raw) < 0) {
            fprintf(stderr, "ALS read failed\n");
            break;
        }

        // Convert ALS data to lux
        double lux = raw * 0.0576;

        // Calculate brightness
        double brightness = 0.0;
        if (lux < 100) {
            brightness = 1.0;
        } else if (lux < 500) {
            brightness = 0.75;
        } else if (lux < 1000) {
            brightness = 0.5;
        } else {
            brightness = 0.25;
        }

        // Log data
        time_t now = time(NULL);
        struct tm *ltm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", ltm);
        fprintf(log_file, "%s %f %f %f\n", timestamp, lux, brightness, 0.0); // error code is always 0
        fflush(log_file);

        // Set PWM
        if (gpioSet PWM(GPIO_PIN, brightness * PWM_RANGE)) {
            fprintf(stderr, "PWM set failed\n");
            break;
        }
    }

    // Clean up
    gpioCleansePWM(GPIO_PIN);
    gpioTerminate();
    i2cClose(I2C Bus);
    fclose(log_file);

    return 0;
}

