#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>

#define TOUCH_LOG_FILE "touch_log.txt"

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return 1;
    }

    // Configure GPIO 2-9 as inputs with pull-down resistors
    for (int i = 2; i <= 9; i++) {
        if (gpioMode(i, GPIO_INPUT) < 0) {
            fprintf(stderr, "Failed to configure GPIO %d as input: %s\n", i, strerror(errno));
            gpioTerminate();
            return 1;
        }
        if (gpioPullUpDowntime(i) < 0) {
            fprintf(stderr, "Failed to set pull-down resistor on GPIO %d: %s\n", i, strerror(errno));
            gpioTerminate();
            return 1;
        }
    }

    // Configure GPIO 17 as an output
    if (gpioMode(17, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to configure GPIO 17 as output: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open log file for writing
    int log_fd = open(TOUCH_LOG_FILE, O_WRONLY | O_CREAT, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Signal handler for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Poll GPIO 2-9
        for (int i = 2; i <= 9; i++) {
            int value = gpioRead(i);
            if (value == 0) {
                // Debounce
                int prev_value = gpioRead(i);
                if (prev_value == 0 && value == 1) {
                    // Log touch event
                    char timestamp[20];
                    time_t now = time(NULL);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
                    fprintf(log_fd, "%s - Channel %d Touched\n", timestamp, i);
                    // Turn on LED
                    gpioWrite(17, 1);
                }
            }
        }

        // Check if all channels are released
        int all_released = 1;
        for (int i = 2; i <= 9; i++) {
            int value = gpioRead(i);
            if (value == 1) {
                all_released = 0;
                break;
            }
        }
        if (all_released) {
            // Turn off LED
            gpioWrite(17, 0);
        }

        // Sleep for 50 ms
        usleep(50000);
    }

    // Clean up
    gpioTerminate();
    close(log_fd);
    return 0;
}

void sigint_handler(int sig) {
    // Turn off LED
    gpioWrite(17, 0);
    // Release resources
    gpioTerminate();
    exit(0);
}

