#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <signal.h>

#define I2C_ADDRESS 0x44
#define CONFIG_REGISTER 0x01
#define RESULT_REGISTER 0x00
#define CONFIG_WORD 0xC810
#define CONVERSION_TIME_MS 100
#define CONVERSION_TIME_USEC 100
#define I2C_BUS 1
#define I2C_HANDLE -1

int main() {
    int i, j, lux;
    char filename[] = "light_data.txt";
    FILE *fp;
    struct sigaction sa;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    // Set up signal handler for clean shutdown
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGPIPE);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C handle
    I2C_HANDLE = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (I2C_HANDLE < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        gpioTerminate();
        return 1;
    }

    // Configure the sensor
    if (i2cWriteWordData(I2C_HANDLE, CONFIG_REGISTER, (uint16_t)(CONFIG_WORD & 0xFFFF)) < 0) {
        fprintf(stderr, "Failed to write configuration register\n");
        i2cClose(I2C_HANDLE);
        gpioTerminate();
        return 1;
    }

    // Wait for the first conversion
    usleep(CONVERSION_TIME_USEC * 1000);

    // Open log file
    fp = fopen(filename, "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
