#include <errno.h>
#include <libgpiod/libgpiod.h>

#define GPIO_PIN 4
#define DEBOUNCE_INTERVAL 50
#define LOG_FILE "touch_log.txt"

int main(int argc, char **argv) {
    // Initialize libgpiod
    gpiod_init();

    // Open the log file
    int log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        gpiod_close(GPIO_PIN);
        gpiod_close(GPIO_PIN);
        perror("Failed to open log file");
        return 1;
    }

    // Open the GPIO pin
    int gpio_fd = gpiod_open(GPIO_PIN, GPIOD_INPUT, GPIOD PullDown);
    if (gpio_fd < 0) {
        close(log_fd);
        gpiod_close(GPIO_PIN);
        gpiod_close(GPIO_PIN);
        perror("Failed to open GPIO pin");
        return 1;
    }

    // Set the GPIO pin as an interrupt
    gpiod_set_interrupt(gpio_fd, GPIO_INT_EDGE, GPIO_INT_EDGE_RISING, GPIO_INT_EDGE_FALLING);

    // Set the debounce interval
    gpiod_set_interrupt_coalesce(gpio_fd, DEBOUNCE_INTERVAL);

    // Main loop
    while (1) {
        // Read the GPIO pin
        int value = gpiod_read(gpio_fd);
        if (value < 0) {
            perror("Failed to read GPIO pin");
            break;
        }

        // Check for touch event
        if (value == 1) {
            // Append to log file
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_fd, "%s: Touch Detected\n", timestamp);
            fflush(log_fd);
        } else {
            // Append to log file
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_fd, "%s: Touch Released\n", timestamp);
            fflush(log_fd);
        }
    }

    // Close the GPIO pin
    gpiod_close(gpio_fd);

    // Close the log file
    close(log_fd);

    // Release the GPIO pin
    gpiod_release(GPIO_PIN);

    // Release the libgpiod
    gpiod_release();

    return 0;
}

