#include <unistd.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>

#define GPIO17 17
#define GPIO27 27
#define GPIO22 22
#define CSV_FILE "path_log.csv"

int main() {
    // Initialize libgpiod
    gpiod_init();

    // Open the GPIO chip
    int gpiochip = gpiod_chip_open("gpiochip");
    if (gpiochip < 0) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Open the log file
    int log_fd = open(CSV_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        perror("open");
        gpiod_chip_close(gpiochip);
        return 1;
    }

    // Open the GPIO lines
    int left_fd = gpiod_chip_get_line(gpiochip, GPIO17, GPIOD_LINE_IN);
    if (left_fd < 0) {
        perror("gpiod_chip_get_line");
        close(log_fd);
        gpiod_chip_close(gpiochip);
        return 1;
    }

    int middle_fd = gpiod_chip_get_line(gpiochip, GPIO27, GPIOD_LINE_IN);
    if (middle_fd < 0) {
        perror("gpiod_chip_get_line");
        close(log_fd);
        gpiod_chip_close(gpiochip);
        return 1;
    }

    int right_fd = gpiod_chip_get_line(gpiochip, GPIO22, GPIOD_LINE_IN);
    if (right_fd < 0) {
        perror("gpiod_chip_get_line");
        close(log_fd);
        gpiod_chip_close(gpiochip);
        return 1;
    }

    // Set the GPIO lines to input mode
    gpiod_chip_set_mode(gpiochip, GPIO17, GPIOD_MODE_INPUT);
    gpiod_chip_set_mode(gpiochip, GPIO27, GPIOD_MODE_INPUT);
    gpiod_chip_set_mode(gpiochip, GPIO22, GPIOD_MODE_INPUT);

    // Poll the GPIO lines every 50 ms
    struct timespec delay;
    struct timespec now;
    while (1) {
        // Get the current time
        clock_gettime(CLOCK_REALTIME, &now);

        // Read the GPIO lines
        int left_value = gpiod_chip_get_value(gpiochip, GPIO17);
        int middle_value = gpiod_chip_get_value(gpiochip, GPIO27);
        int right_value = gpiod_chip_get_value(gpiochip, GPIO22);

        // Append the readings to the log file
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%6N", &now);
        fprintf(log_fd, "%s,%d,%d,%d\n", timestamp, left_value, middle_value, right_value);

        // Delay for 50 ms
        delay.tv_sec = now.tv_sec + 50 / 1000000;
        delay.tv_nsec = (now.tv_nsec + 500000) % 1000000000;
        nanosleep(&delay, NULL);

        // Handle SIGINT
        if (signal(SIGINT, SIG_DFL) == SIG_DFL) {
            break;
        }
    }

    // Close the GPIO lines
    gpiod_chip_close(gpiochip);
    close(log_fd);

    // Close the log file
    if (close(log_fd) < 0) {
        perror("close");
    }

    // Flush the GPIO chip
    gpiod_chip_flush(gpiochip);

    // Close the GPIO chip
    if (gpiod_chip_close(gpiochip) < 0) {
        perror("gpiod_chip_close");
    }

    return 0;
}

