#define GPIO23 23
#define GPIO24 24
#define LOG_FILE "touch_log.txt"

int main(int argc, char *argv[]) {
    gpiod_context_t ctx;
    gpiod_line_event_t event;
    gpiod_line_request_t req;
    gpiod_line_event_callback_t callback;
    gpiod_line_event_callback_data_t data;
    gpiod_gpio_t gpio24;
    FILE *log_file;

    // Initialize libgpiod context
    if (gpiod_context_new(&ctx) != 0) {
        fprintf(stderr, "Failed to initialize libgpiod context\n");
        return 1;
    }

    // Open GPIO chip
    if (gpiod_gpiochip_open(&ctx, "gpiochip4", 0) != 0) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpiod_context_free(&ctx);
        return 1;
    }

    // Request GPIO lines
    if (gpiod_line_request(&ctx, GPIO23, &req) != 0) {
        fprintf(stderr, "Failed to request GPIO line 23\n");
        gpiod_gpiochip_close(&ctx);
        gpiod_context_free(&ctx);
        return 1;
    }

    // Request GPIO line 24
    if (gpiod_line_request(&ctx, GPIO24, &req) != 0) {
        fprintf(stderr, "Failed to request GPIO line 24\n");
        gpiod_line_request_cancel(&req);
        gpiod_gpiochip_close(&ctx);
        gpiod_context_free(&ctx);
        return 1;
    }

    // Set up callback for rising edge events on GPIO 23
    callback = gpiod_line_event_callback_new(&ctx, &req, gpiod_line_event_callback_type RisingEdge);
    if (callback == NULL) {
        fprintf(stderr, "Failed to create callback\n");
        gpiod_line_request_cancel(&req);
        gpiod_gpiochip_close(&ctx);
        gpiod_context_free(&ctx);
        return 1;
    }

    // Set up callback data
    data.callback = callback;
    data.data = &event;

    // Set up callback
    if (gpiod_line_event_callback_set(&req, callback, &data) != 0) {
        fprintf(stderr, "Failed to set callback\n");
        gpiod_line_request_cancel(&req);
        gpiod_gpiochip_close(&ctx);
        gpiod_context_free(&ctx);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_request_cancel(&req);
        gpiod_gpiochip_close(&ctx);
        gpiod_context_free(&ctx);
        return 1;
    }

    // Main loop
    while (1) {
        // Poll for events
        if (gpiod_line_event_poll(&ctx, &req, 1000) != 0) {
            fprintf(stderr, "Failed to poll for events\n");
            gpiod_line_request_cancel(&req);
            gpiod_gpiochip_close(&ctx);
            gpiod_context_free(&ctx);
            fclose(log_file);
            return 1;
        }

        // Check if an event occurred
        if (gpiod_line_event_get(&req, &event) != 0) {
            fprintf(stderr, "Failed to get event\n");
            gpiod_line_request_cancel(&req);
            gpiod_gpiochip_close(&ctx);
            gpiod_context_free(&ctx);
            fclose(log_file);
            return 1;
        }

        // Check if the event is a rising edge on GPIO 23
        if (event.type == gpiod_line_event_type_RisingEdge && event.line == GPIO23) {
            // Toggle the LED on GPIO 24
            if (gpiod_gpio_request(&ctx, GPIO24, &gpio24) != 0) {
                fprintf(stderr, "Failed to request GPIO line 24\n");
                gpiod_line_request_cancel(&req);
                gpiod_gpiochip_close(&ctx);
                gpiod_context_free(&ctx);
                fclose(log_file);
                return 1;
            }

            if (gpiod_gpio_write(&gpio24, 1) != 0) {
                fprintf(stderr, "Failed to write to GPIO line 24\n");
                gpiod_gpio_request_cancel(&gpio24);
                gpiod_line_request_cancel(&req);
                gpiod_gpiochip_close(&ctx);
                gpiod_context_free(&ctx);
                fclose(log_file);
                return 1;
            }

            // Log the event
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
            fprintf(log_file, "%s: Touch detected, LED on\n", timestamp);
        }

        // Toggle the LED off
        if (gpiod_gpio_request(&ctx, GPIO24, &gpio24) != 0) {
            fprintf(stderr, "Failed to request GPIO line 24\n");
            gpiod_line_request_cancel(&req);
            gpiod_gpiochip_close(&ctx);
            gpiod_context_free(&ctx);
            fclose(log_file);
            return 1;
        }

        if (gpiod_gpio_write(&gpio24, 0) != 0) {
            fprintf(stderr, "Failed to write to GPIO line 24\n");
            gpiod_gpio_request_cancel(&gpio24);
            gpiod_line_request_cancel(&req);
            gpiod_gpiochip_close(&ctx);
            gpiod_context_free(&ctx);
            fclose(log_file);
            return 1;
        }
    }

    // Clean up
    gpiod_line_request_cancel(&req);
    gpiod_gpiochip_close(&ctx);
    gpiod_context_free(&ctx);
    fclose(log_file);

    return 0;
}

