#include <stdio.h>
#include <stdlib.h>
#include <gpiod/gpiod.h>

#define CHIP_NAME "gpiochip0"
#define LINE_NAME "line0"
#define BUZZER_PIN 17
#define FLAME_PIN 11
#define BUZZER_PIN2 18
#define LOG_FILE "alert_log.txt"

int main(int argc, char **argv) {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line *buzzer;
    struct gpiod_line *flame;
    FILE *log_file;

    // Initialize libgpiod
    ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "gpiod_init failed: %s\n", strerror(errno));
        return 1;
    }

    // Open the chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        gpiod_exit();
        return 1;
    }

    // Open the line
    line = gpiod_chip_get_line(chip, LINE_NAME);
    if (!line) {
        fprintf(stderr, "gpiod_chip_get_line failed: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_exit();
        return 1;
    }

    // Open the buzzer
    buzzer = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer) {
        fprintf(stderr, "gpiod_chip_get_line failed: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_close(line);
        gpiod_exit();
        return 1;
    }

    // Open the flame sensor
    flame = gpiod_chip_get_line(chip, FLAME_PIN);
    if (!flame) {
        fprintf(stderr, "gpiod_chip_get_line failed: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_close(line);
        gpiod_line_close(buzzer);
        gpiod_exit();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "fopen failed: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_close(line);
        gpiod_line_close(buzzer);
        gpiod_line_close(flame);
        gpiod_exit();
        return 1;
    }

    // Set the line to input mode
    ret = gpiod_line_request_input(line);
    if (ret < 0) {
        fprintf(stderr, "gpiod_line_request_input failed: %s\n", strerror(errno));
        fclose(log_file);
        gpiod_chip_close(chip);
        gpiod_line_close(line);
        gpiod_line_close(buzzer);
        gpiod_line_close(flame);
        gpiod_exit();
        return 1;
    }

    // Set the buzzer to output mode
    ret = gpiod_line_request_output(buzzer);
    if (ret < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n", strerror(errno));
        fclose(log_file);
        gpiod_chip_close(chip);
        gpiod_line_close(line);
        gpiod_line_close(buzzer);
        gpiod_line_close(flame);
        gpiod_exit();
        return 1;
    }

    // Set the flame sensor to input mode
    ret = gpiod_line_request_input(flame);
    if (ret < 0) {
        fprintf(stderr, "gpiod_line_request_input failed: %s\n", strerror(errno));
        fclose(log_file);
        gpiod_chip_close(chip);
        gpiod_line_close(line);
        gpiod_line_close(buzzer);
        gpiod_line_close(flame);
        gpiod_exit();
        return 1;
    }

    // Log system start
    fprintf(log_file, "%s\n", "System started");

    // Poll the flame sensor
    struct timespec start;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        // Poll the flame sensor
        ret = gpiod_line_get_value(flame);
        if (ret < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n", strerror(errno));
