#include <errno.h>

#define GPIO4 4
#define GPIO17 17
#define DEBOUNCE_MS 200
#define LOG_FILE "touch_log.txt"

int main(int argc, char **argv) {
    int gpio;
    int fd;
    struct timespec last_touch;
    struct timespec now;
    struct stat st;
    int ret;

    // Initialize pigpio
    if (gpio = pigpio_init()) {
        fprintf(stderr, "pigpio_init() failed: %d\n", gpio);
        return 1;
    }

    // Configure GPIO4 as input
    if (gpio_mode(GPIO4, PI_INPUT) != 0) {
        fprintf(stderr, "gpio_mode() failed: %d\n", gpio);
        pigpio_close(gpio);
        pigpioTerminate();
        return 1;
    }

    // Configure GPIO17 as output
    if (gpio_mode(GPIO17, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpio_mode() failed: %d\n", gpio);
        pigpio_close(gpio);
        pigpioTerminate();
        return 1;
    }

    // Open log file
    if ((fd = open(LOG_FILE, O_RDWR | O_CREAT | O_TRUNC, 0644)) < 0) {
        fprintf(stderr, "open() failed: %d\n", errno);
        pigpio_close(gpio);
        pigpioTerminate();
        return 1;
    }

    // Set up debouncing
    while (1) {
        // Read GPIO4
        int value = gpio_read(GPIO4);
        if (value == 0) {
            // Debounce
            struct timespec now;
            clock_gettime(CLOCK_REALTIME, &now);
            if (time_diff(&last_touch, &now) > DEBOUNCE_MS) {
                last_touch = now;
                // Toggle LED
                gpio_write(GPIO17, 1);
                // Log touch
                fprintf(fd, "%s %d\n", ctime(&now), now.tv_sec);
            }
        } else {
            last_touch = now;
        }

        // Sleep
        usleep(10);
    }

    // Clean up
    close(fd);
    pigpio_close(gpio);
    pigpioTerminate();

    return 0;
}

