#define MAGNET1_ID "Magnet 1"
#define MAGNET2_ID "Magnet 2"
#define MAGNET3_ID "Magnet 3"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set GPIO modes and pull-up resistors
    if (gpioMode(MAGNET1_PIN, GPIO_MODE_INPUT, GPIO_PUD_UP) < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }
    if (gpioMode(MAGNET2_PIN, GPIO_MODE_INPUT, GPIO_PUD_UP) < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }
    if (gpioMode(MAGNET3_PIN, GPIO_MODE_INPUT, GPIO_PUD_UP) < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("fopen");
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    sa.sa_handler = sigterm_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor states
    int magnet1_state = MAGNET0;
    int magnet2_state = MAGNET0;
    int magnet3_state = MAGNET0;

    while (1) {
        // Poll sensors
        int magnet1_value = gpioRead(MAGNET1_PIN);
        int magnet2_value = gpioRead(MAGNET2_PIN);
        int magnet3_value = gpioRead(MAGNET3_PIN);

        // Check for state changes
        if (magnet1_value != magnet1_state) {
            magnet1_state = magnet1_value;
            fprintf(log_file, "%s %s %d %d %d\n", ctime(NULL), MAGNET1_ID, magnet1_state, magnet2_state, magnet3_state);
        }
        if (magnet2_value != magnet2_state) {
            magnet2_state = magnet2_value;
            fprintf(log_file, "%s %s %d %d %d\n", ctime(NULL), MAGNET2_ID, magnet1_state, magnet2_state, magnet3_state);
        }
        if (magnet3_value != magnet3_state) {
            magnet3_state = magnet3_value;
            fprintf(log_file, "%s %s %d %d %d\n", ctime(NULL), MAGNET3_ID, magnet1_state, magnet2_state, magnet3_state);
        }

        // Log initial state
        if (magnet1_state == MAGNET0 && magnet2_state == MAGNET0 && magnet3_state == MAGNET0) {
            fprintf(log_file, "%s %s %d %d %d\n", ctime(NULL), MAGNET1_ID, magnet1_state, magnet2_state, magnet3_state);
        }

        // Delay
        gpioDelay(100);
    }

    // Close the log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

