#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDRESS 0x4A
#define I2C Bus 1
#define PART_ID 0x00
#define HW_REV 0x01
#define LED_CURRENT 0x3F
#define AVERAGING 0x04
#define ENABLE 0x01
#define HEART_RATE 0x2A

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C bus
    int i2c_fd = i2cOpen(I2C Bus, I2C_ADDRESS);
    if (i2c_fd < 0) {
        perror("i2cOpen");
        gpioTerminate();
        return 1;
    }

    // Read PART_ID and HW_REV registers
    uint8_t part_id, hw_rev;
    if (i2cReadWordData(i2c_fd, &part_id, 1) < 0) {
        perror("i2cReadWordData");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (part_id != PART_ID) {
        fprintf(stderr, "Invalid PART_ID: 0x%02x\n", part_id);
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (i2cReadWordData(i2c_fd, &hw_rev, 1) < 0) {
        perror("i2cReadWordData");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (hw_rev != HW_REV) {
        fprintf(stderr, "Invalid HW_REV: 0x%02x\n", hw_rev);
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (i2cWriteByte(i2c_fd, LED_CURRENT, 0x3F) < 0) {
        perror("i2cWriteByte");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (i2cWriteByte(i2c_fd, AVERAGING, 0x04) < 0) {
        perror("i2cWriteByte");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (i2cWriteByte(i2c_fd, ENABLE, 0x01) < 0) {
        perror("i2cWriteByte");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Read heart-rate register
    uint16_t heart_rate;
    while (1) {
        if (i2cReadWordData(i2c_fd, &heart_rate, 2) < 0) {
            if (errno == EIO) {
                // Retry on transient I2C read error
                sleep(0.1);
                continue;
            } else {
                perror("i2cReadWordData");
                i2cClose(i2c_fd);
                gpioTerminate();
                return 1;
            }
        }
