#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>

// Define constants
#define GPIO_PIN 17
#define GPIO_CHIP 17
#define LOG_FILE "flame_log.txt"

// Define a function to handle the SIGINT and SIGTERM signals
void sig_handler(int sig) {
    // Release the GPIO line
    gpiod_chip_close(gpiod_chip_get_default());

    // Close the log file
    if (remove(LOG_FILE) != 0) {
        perror("Error removing log file");
    }

    // Exit the program
    exit(0);
}

int main() {
    // Install the signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open the log file in append mode
    int log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd == -1) {
        perror("Error opening log file");
        return 1;
    }

    // Open the GPIO chip
    gpiod_chip_t *chip = gpiod_chip_get_default();
    if (!chip) {
        perror("Error getting default GPIO chip");
        return 1;
    }

    // Configure the GPIO pin as an input with an internal pull-up
    gpiod_line_t *line = gpiod_chip_get_line(chip, GPIO_CHIP);
    if (!line) {
        perror("Error getting GPIO line");
        return 1;
    }
    gpiod_line_config(line, GPIOD_LINE_MODE_INPUT, GPIOD_LINE_PULL_UP, GPIOD_LINE_PULL_UP_ENABLE);

    // Poll the GPIO line every 100 ms
    struct timespec ts;
    while (1) {
        // Get the current time
        clock_gettime(CLOCK_MONOTONIC, &ts);

        // Read the GPIO line
        int value = gpiod_line_get_value(line);
        if (value == 0) {
            // Write to the log file
            fprintf(log_fd, "%ld FLAME DETECTED\n", ts.tv_sec);
            fflush(log_fd);
        }

        // Sleep for 100 ms
        nanosleep(&ts, NULL);
    }

    // Close the log file
    close(log_fd);

    // Close the GPIO line
    gpiod_line_close(line);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

