#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <gpiod/gpiod.h>
#include <gpiod/gpiodchip.h>
#include <gpiod/gpiodline.h>
#include <gpiod/gpiodlineconfig.h>
#include <gpiod/gpiodlineconfigv2.h>
#include <gpiod/gpiodlineconfigv2bulk.h>

#define CHIP_NAME "touch_counter"
#define CHIP_ID 0
#define NUM_CHANNELS 8
#define DELAY_MS 200
#define POLL_MS 10
#define LOG_FILE "touch_log.txt"

int main(int argc, char **argv) {
    int chip_fd, chip;
    gpiod_chip_t *chip_ptr;
    gpiod_line_t *lines[NUM_CHANNELS];
    gpiod_lineconfig_t *line_configs[NUM_CHANNELS];
    gpiod_lineconfigv2_t *line_configs_v2[NUM_CHANNELS];
    gpiod_lineconfigv2bulk_t *line_configs_v2bulk;
    gpiod_lineconfigv2bulk_request_t request;
    gpiod_lineconfigv2bulk_response_t response;
    gpiod_lineconfigv2bulk_release_t release;
    gpiod_line_t *line;
    gpiod_lineconfig_t *line_config;
    gpiod_lineconfigv2_t *line_config_v2;
    gpiod_lineconfigv2bulk_request_t *line_config_v2_request;
    gpiod_lineconfigv2bulk_response_t *line_config_v2_response;
    gpiod_lineconfigv2bulk_release_t *line_config_v2_release;
    int counter = 0;
    int prev_state[NUM_CHANNELS];
    struct timespec delay;
    struct timespec now;
    struct stat log_stat;
    int log_fd;
    int ret;

    // Initialize libgpiod
    if ((ret = gpiod_init()) != 0) {
        fprintf(stderr, "gpiod_init failed: %s\n", strerror(errno));
        return ret;
    }

    // Open chip
    if ((ret = gpiod_chip_open(&chip_fd, CHIP_NAME, CHIP_ID)) != 0) {
        fprintf(stderr, "gpiod_chip_open failed: %s\n", strerror(errno));
        gpiod_exit();
        return ret;
    }

    // Get chip pointer
    if ((ret = gpiod_chip_get(&chip, chip_fd)) != 0) {
        fprintf(stderr, "gpiod_chip_get failed: %s\n", strerror(errno));
        gpiod_chip_close(chip_fd);
        gpiod_exit();
        return ret;
    }

    // Request lines
    if ((ret = gpiod_chip_request_lines(chip, CHIP_ID, NUM_CHANNELS, &lines)) != 0) {
        fprintf(stderr, "gpiod_chip_request_lines failed: %s\n", strerror(errno));
        gpiod_chip_close(chip_fd);
        gpiod_exit();
        return ret;
    }

    // Create line configs
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if ((ret = gpiod_lineconfig_new(&line_config, lines[i])) != 0) {
            fprintf(stderr, "gpiod_lineconfig_new failed: %s\n", strerror(errno));
            for (int j = 0; j < i; j++) {
                gpiod_lineconfig_release(line_configs[j]);
            }
            gpiod_chip_release_lines(chip, lines);
            gpiod_chip_close(chip_fd);
            gpiod_exit();
            return ret;
        }
        line_configs[i] = line_config;
    }

    // Create line configs v2
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if ((ret = gpiod_lineconfigv2_new(&line_config_v2, line_configs[i])) != 0) {
            fprintf(stderr, "gpiod_lineconfigv2_new failed: %s\n", strerror(errno));
            for (int j = 0; j < i; j++) {
                gpiod_lineconfig_release(line_configs[j]);
            }
            for (int j = 0; j < i; j++) {
                gpiod_lineconfigv2_release(line_configs_v2[j]);
            }
            gpiod_chip_release_lines(chip, lines);
            gpiod_chip_close(chip_fd);
            gpiod_exit();
            return ret;
        }
        line_configs_v2[i] = line_config_v2;
    }

    // Create line configs v2 bulk
    if ((ret = gpiod_lineconfigv2bulk_new(&line_configs_v2bulk)) != 0) {
        fprintf(stderr, "gpiod_lineconfigv2bulk_new failed: %s\n", strerror(errno));
        for (int i = 0; i < NUM_CHANNELS; i++) {
            gpiod_lineconfigv2_release(line_configs_v2[i]);
        }
        gpiod_chip_release_lines(chip, lines);
        gpiod_chip_close(chip_fd);
        gpiod_exit();
        return ret;
    }

    // Request line configs v2 bulk
    if ((ret = gpiod_lineconfigv2bulk_request(&request, line_configs_v2bulk)) != 0) {
        fprintf(stderr, "gpiod_lineconfigv2bulk_request failed: %s\n", strerror(errno));
        gpiod_lineconfigv2bulk_release(line_configs_v2bulk);
        for (int i = 0; i < NUM_CHANNELS; i++) {
            gpiod_lineconfigv2_release(line_configs_v2[i]);
        }
        gpiod_chip_release_lines(chip, lines);
        gpiod_chip_close(chip_fd);
        gpiod_exit();
        return ret;
    }

    // Wait for stabilization
    nanosleep(&delay, NULL);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if ((ret = gpiod_lineconfigv2bulk_get(line_configs_v2bulk, i, &line_config_v2_request)) != 0) {
            fprintf(stderr, "gpiod_lineconfigv2bulk_get failed: %s\n", strerror(errno));
            gpiod_lineconfigv2bulk_release(line_configs_v2bulk);
            for (int j = 0; j < i; j++) {
                gpiod_lineconfigv2_release(line_configs_v2[j]);
            }
            gpiod_chip_release_lines(chip, lines);
            gpiod_chip_close(chip_fd);
            gpiod_exit();
            return ret;
        }
        line_config_v2_response = gpiod_lineconfigv2bulk_get_response(line_configs_v2bulk, line_config_v2_request);
        if (line_config_v2_response->direction == GPIOD_LINE_CONFIGV2_DIRECTION_IN) {
            gpiod_lineconfigv2bulk_release(line_configs_v2bulk);
            for (int j = 0; j < i; j++) {
                gpiod_lineconfigv2_release(line_configs_v2[j]);
            }
            gpiod_chip_release_lines(chip, lines);
            gpiod_chip_close(chip_fd);
            gpiod_exit();
            return ret;
        }
    }

    // Release line configs v2 bulk
    gpiod_lineconfigv2bulk_release(line_configs_v2bulk);

    // Release line configs v2
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpiod_lineconfigv2_release(line_configs_v2[i]);
    }

    // Release line configs
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpiod_lineconfig_release(line_configs[i]);
    }

    // Release lines
    gpiod_chip_release_lines(chip, lines);

    // Open log file
    if ((ret = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644)) != 0) {
        fprintf(stderr, "open failed: %s\n", strerror(errno));
        return ret;
    }
    log_fd = ret;

    // Main loop
    while (1) {
        // Get current time
        clock_gettime(CLOCK_REALTIME, &now);

        // Read sensor values
        for (int i = 0; i < NUM_CHANNELS; i++) {
            if ((ret = gpiod_line_request_get_value(line_configs_v2[i], &line)) != 0) {
                fprintf(stderr, "gpiod_line_request_get_value failed: %s\n", strerror(errno));
                gpiod_chip_close(chip_fd);
                gpiod_exit();
                return ret;
            }
            if (line->value == 0) {
                continue;
            }
            if (prev_state[i] == 0) {
                counter++;
                prev_state[i] = 1;
                fprintf(log_fd, "%04d-%02d-%02dT%02d:%02d:%02dZ, Channel: %d, Counter: %d\n", now.tv_sec, now.tv_usec / 1000000, now.tv_sec % 100, now.tv_nsec / 1000000, now.tv_sec % 100, now.tv_nsec % 1000000, i + 1, counter);
                fprintf(stdout, "Touch on channel %d | Counter: %d\n", i + 1, counter);
            } else {
                prev_state[i] = 0;
            }
            gpiod_line_request_release(line);
        }

        // Update output
        for (int i = 0; i < NUM_CHANNELS; i++) {
            if ((ret = gpiod_line_request_get_value(line_configs_v2[i], &line)) != 0) {
                fprintf(stderr, "gpiod_line_request_get_value failed: %s\n", strerror(errno));
                gpiod_chip_close(chip_fd);
                gpiod_exit();
                return ret;
            }
            if (line->value == 1) {
                gpiod_line_request_set_value(line_configs_v2[i], 0);
            } else {
                gpiod_line_request_set_value(line_configs_v2[i], 1);
            }
            gpiod_line_request_release(line);
        }

        // Sleep
        nanosleep(&delay, NULL);
    }

    // Reset output
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpiod_line_request_set_value(line_configs_v2[i], 0);
    }

    // Close log file
    if (close(log_fd) != 0) {
        fprintf(stderr, "close failed: %s\n", strerror(errno));
    }

    // Release chip
    gpiod_chip_close(chip_fd);

    // Exit
    gpiod_exit();
    return 0;
}

