int main(int argc, char **argv) {
    // Initialize libgpiod
    gpiod_t *gpiod;
    gpiod_new(&gpiod, GpioController, GpioDevice);
    if (gpiod == NULL) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Create a new line group
    gpiod_line_t *line_group;
    gpiod_line_new(&line_group, gpiod, GPIO_NUM, GPIO_PIN, GPIO_INPUT, GPIO_EDGE_BOTH);
    if (line_group == NULL) {
        fprintf(stderr, "Failed to create line group\n");
        gpiod_free(gpiod);
        return 1;
    }

    // Request the GPIO lines
    gpiod_line_request_input(line_group, GPIO_NUM, GPIO_PIN, NULL);
    if (line_group == NULL) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        gpiod_free(gpiod);
        gpiod_line_free(line_group);
        return 1;
    }

    // Open the CSV file
    int fd = open(CSV_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd == -1) {
        fprintf(stderr, "Failed to open CSV file\n");
        gpiod_free(gpiod);
        gpiod_line_free(line_group);
        return 1;
    }

    // Set up the async callback
    gpiod_async_t *async;
    gpiod_async_new(&async, gpiod, line_group, gpiod_line_get_value, NULL);
    if (async == NULL) {
        fprintf(stderr, "Failed to create async callback\n");
        close(fd);
        gpiod_free(gpiod);
        gpiod_line_free(line_group);
        return 1;
    }

    // Set the async callback to run every 100 ms
    gpiod_async_set_interval(async, 100);

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set signal handler for SIGINT\n");
        gpiod_free(gpiod);
        gpiod_line_free(line_group);
        close(fd);
        return 1;
    }
    sa.sa_handler = sigterm_handler;
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set signal handler for SIGTERM\n");
        gpiod_free(gpiod);
        gpiod_line_free(line_group);
        close(fd);
        return 1;
    }

    // Start the async callback
    gpiod_async_start(async);

    // Main loop
    while (1) {
        // Read the GPIO values
        gpiod_line_get_value(line_group, GPIO_NUM, GPIO_PIN, NULL);
        if (line_group == NULL) {
            fprintf(stderr, "Failed to read GPIO values\n");
            gpiod_free(gpiod);
            gpiod_line_free(line_group);
            close(fd);
            return 1;
        }

        // Get the current time
        time_t now = time(NULL);

        // Write to the CSV file
        char buffer[256];
        sprintf(buffer, "%ld,%d,%d,%d,%d\n", now, gpiod_line_get_value(line_group, GPIO_NUM, GPIO_PIN), gpiod_line_get_value(line_group, GPIO_NUM, GPIO_PIN + 1), gpiod_line_get_value(line_group, GPIO_NUM, GPIO_PIN + 2), gpiod_line_get_value(line_group, GPIO_NUM, GPIO_PIN + 3));
        if (write(fd, buffer, strlen(buffer)) == -1) {
            fprintf(stderr, "Failed to write to CSV file\n");
            gpiod_free(gpiod);
            gpiod_line_free(line_group);
            close(fd);
            return 1;
        }

        // Flush the file
        if (fflush(fd) == -1) {
            fprintf(stderr, "Failed to flush CSV file\n");
            gpiod_free(gpiod);
            gpiod_line_free(line_group);
            close(fd);
            return 1;
        }
    }

    // Clean up
    gpiod_async_stop(async);
    gpiod_async_free(async);
    gpiod_line_free(line_group);
    gpiod_free(gpiod);
    close(fd);

    return 0;
}

void sigint_handler(int sig) {
    gpiod_async_stop(gpiod_async_get(gpiod, NULL));
    gpiod_async_free(gpiod_async_get(gpiod, NULL));
    gpiod_line_free(gpiod_line_get(gpiod, NULL));
    gpiod_free(gpiod);
    close(gpiod_line_get(gpiod, NULL));
    exit(0);
}

void sigterm_handler(int sig) {
    gpiod_async_stop(gpiod_async_get(gpiod, NULL));
    gpiod_async_free(gpiod_async_get(gpiod, NULL));
    gpiod_line_free(gpiod_line_get(gpiod, NULL));
    gpiod_free(gpiod);
    close(gpiod_line_get(gpiod, NULL));
    exit(0);
}

