#include <string.h>
#include <syslog.h>
#include <unistd.h>
#include <errno.h>
#include <libgpiod/libgpiod.h>

#define GPIO17 17
#define GPIO18 18
#define DEBOUNCE 50
#define POLL_INTERVAL 100

int main(int argc, char **argv) {
    gpiod_context_t ctx;
    gpiod_chip_t chip;
    gpiod_line_t line1, line2;
    gpiod_event_t event1, event2;
    gpiod_event_handler_t handler1, handler2;
    FILE *log_file;

    // Initialize libgpiod
    if (gpiod_init(&ctx) != 0) {
        fprintf(stderr, "libgpiod initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Create a chip
    if (gpiod_chip_create(&ctx, &chip, "tilt_sensors", NULL) != 0) {
        fprintf(stderr, "Failed to create chip: %s\n", strerror(errno));
        gpiod_exit(&ctx);
        return 1;
    }

    // Configure GPIO17 and GPIO18 as inputs with active-low pull-up
    if (gpiod_chip_add_line(&chip, GPIO17, &line1, GPIOD_LINE_INPUT, GPIOD_LINE_ACTIVE_LOW, NULL) != 0) {
        fprintf(stderr, "Failed to add line 1: %s\n", strerror(errno));
        gpiod_chip_destroy(&chip);
        gpiod_exit(&ctx);
        return 1;
    }
    if (gpiod_chip_add_line(&chip, GPIO18, &line2, GPIOD_LINE_INPUT, GPIOD_LINE_ACTIVE_LOW, NULL) != 0) {
        fprintf(stderr, "Failed to add line 2: %s\n", strerror(errno));
        gpiod_chip_destroy(&chip);
        gpiod_exit(&ctx);
        return 1;
    }

    // Install event handlers
    handler1 = gpiod_event_handler_new(&event1, gpiod_chip_get_event(&chip, line1, GPIOD_EVENT_EDGE_RISING, NULL, NULL, NULL, NULL, NULL);
    handler2 = gpiod_event_handler_new(&event2, gpiod_chip_get_event(&chip, line2, GPIOD_EVENT_EDGE_RISING, NULL, NULL, NULL, NULL, NULL);
    if (handler1 == NULL || handler2 == NULL) {
        fprintf(stderr, "Failed to create event handlers\n");
        gpiod_chip_destroy(&chip);
        gpiod_exit(&ctx);
        return 1;
    }
    gpiod_event_handler_set_handler(&event1, handler1);
    gpiod_event_handler_set_handler(&event2, handler2);

    // Open log file
    log_file = fopen("/var/log/tilt_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_destroy(&chip);
        gpiod_exit(&ctx);
        return 1;
    }

    // Poll lines
    while (1) {
        gpiod_chip_poll(&chip, &line1, NULL, NULL, NULL);
        gpiod_chip_poll(&chip, &line2, NULL, NULL, NULL);
        usleep(POLL_INTERVAL * 1000);
    }

    // Cleanup
    gpiod_event_handler_destroy(handler1);
    gpiod_event_handler_destroy(handler2);
    gpiod_chip_destroy(&chip);
    fclose(log_file);
    gpiod_exit(&ctx);
    return 0;
}

