#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <libgpiod/libgpiod.h>

#define GPIO17 17
#define GPIO27 27
#define GPIO22 22
#define LOG_FILE "obstacle_log.csv"

int main() {
    // Initialize libgpiod
    gpiod_t *chip;
    gpiod_chip_t *gpiochip0;
    gpiod_line_t *line;
    gpiod_line_t *led;

    // Open gpiochip0
    chip = gpiod_chip_open("gpiochip0", GpioChipOpenFlagsNone);
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return 1;
    }

    // Get gpiochip0
    gpiochip0 = gpiod_chip_get(chip, 0);
    if (!gpiochip0) {
        fprintf(stderr, "Failed to get gpiochip0: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Get lines
    line = gpiod_line_get(gpiochip0, GPIO17);
    if (!line) {
        fprintf(stderr, "Failed to get line GPIO17: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    led = gpiod_line_get(gpiochip0, GPIO22);
    if (!led) {
        fprintf(stderr, "Failed to get line GPIO22: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Get sensor lines
    line = gpiod_line_get(gpiochip0, GPIO27);
    if (!line) {
        fprintf(stderr, "Failed to get line GPIO27: %s\n", strerror(errno));
        gpiod_line_release(led);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set direction for all lines
    gpiod_line_direction(line, GpioDirectionIn);
    gpiod_line_direction(led, GpioDirectionOut);

    // Open log file
    int log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_line_release(led);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open log file for writing
