    stop = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        exit(1);
    }

    // Set GPIO4 as an input with a pull-up resistor
    if (gpioMode(4, GPIO_INPUT) < 0) {
        fprintf(stderr, "gpioMode(4, GPIO_INPUT) failed\n");
        gpioTerminate();
        exit(1);
    }

    // Set GPIO17 as an output
    if (gpioMode(17, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "gpioMode(17, GPIO_OUTPUT) failed\n");
        gpioTerminate();
        exit(1);
    }

    // Set GPIO17 as a low
    if (gpioWrite(17, 0) < 0) {
        fprintf(stderr, "gpioWrite(17, 0) failed\n");
        gpioTerminate();
        exit(1);
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Set up clock
    struct timespec start;
    clock_gettime(CLOCK_REALTIME, &start);

    while (!stop) {
        // Read GPIO4
        int value = gpioRead(4);
        if (value == 1) {
            // Record timestamp
            struct timespec end;
            clock_gettime(CLOCK_REALTIME, &end);
            printf("%f\n", (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e6);

            // Turn on LED
            if (gpioWrite(17, 1) < 0) {
                fprintf(stderr, "gpioWrite(17, 1) failed\n");
                gpioTerminate();
                exit(1);
            }
            // Delay for 100ms
            if (gpioDelay(100) < 0) {
                fprintf(stderr, "gpioDelay(100) failed\n");
                gpioTerminate();
                exit(1);
            }
            // Turn off LED
            if (gpioWrite(17, 0) < 0) {
                fprintf(stderr, "gpioWrite(17, 0) failed\n");
                gpioTerminate();
                exit(1);
            }
        }

        // Delay for 125 microseconds
        if (gpioDelay(125) < 0) {
            fprintf(stderr, "gpioDelay(125) failed\n");
            gpioTerminate();
            exit(1);
        }
    }

    // Clean up
    gpioTerminate();
    return 0;
}

