#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod/gpiod.h>

// Define the GPIO chip and line IDs
#define CHIP_ID 0
#define LINE_IDS (1 << 8) | (1 << 7 | 1 << 6 | 1 << 5 | 1 << 4 | 1 << 3 | 1 << 2 | 1 << 1 | 1 << 0)

// Define the poll interval in milliseconds
#define POLL_INTERVAL 200

// Define the signal handlers
void sigint_handler(int sig) {
    gpiod_chip_close(CHIP_ID);
    exit(0);
}

void sigterm_handler(int sig) {
    gpiod_chip_close(CHIP_ID);
    exit(0);
}

int main(int argc, char **argv) {
    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize libgpiod
    if (gpiod_init() != 0) {
        fprintf(stderr, "Error initializing libgpiod: %s\n", gpiod_strerror());
        return 1;
    }

    // Open the GPIO chip
    gpiod_chip_t *chip = gpiod_chip_open(CHIP_ID, "gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening chip: %s\n", gpiod_strerror());
        gpiod_exit();
        return 1;
    }

    // Request all 8 lines as inputs
    gpiod_line_t *lines[] = gpiod_chip_get_lines(chip, LINE_IDS);
    if (!lines) {
        fprintf(stderr, "Error requesting lines: %s\n", gpiod_strerror());
        gpiod_chip_close(chip);
        gpiod_exit();
        return 1;
    }

    // Poll every 200 ms
    struct timespec last_poll;
    while (1) {
        // Get the current time
        clock_gettime(CLOCK_MONOTONIC, &last_poll);

        // Read the line values
        for (int i = 0; i < 8; i++) {
            gpiod_line_t *line = &lines[i];
            gpiod_line_get_value(line, &last_poll.tv_sec, &last_poll.tv_nsec);
            if (gpiod_line_get_value_error(line) != 0) {
                fprintf(stderr, "Error reading line %d: %s\n", i, gpiod_line_get_value_error(line));
                gpiod_chip_close(chip);
                gpiod_exit();
                return 1;
            }
        }

        // Print the line values
        char buffer[32];
        sprintf(buffer, "[%.3f.s] CH%d=0 CH%d=0 CH%d=0 CH%d=0 CH%d=0 CH%d=0 CH%d=0 CH%d=0",
                (last_poll.tv_sec + last_poll.tv_nsec / 1e9), lines[0]->id, lines[1]->id, lines[2]->id, lines[3]->id, lines[4]->id, lines[5]->id, lines[6]->id, lines[7]->id);
        printf("%s\n", buffer);

        // Sleep for the next poll interval
        nanosleep(&last_poll, NULL);
    }

    // Release resources
    for (int i = 0; i < 8; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    gpiod_exit();

    return 0;
}

