#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>
#include <time.h>
#include <sys/types.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <termios.h>
#include <unistd.h>

#define LED_RED 17
#define LED_GREEN 18
#define LED_BLUE 27
#define PWM_FREQ 1000
#define PWM_BIT 8
#define FADE_TIME 5
#define NUM_STEPS 50

int main() {
    int gpio;
    int pwm;
    int ret;
    struct sigaction sa;
    struct sigaction old_sa;

    // Initialize pigpio
    if (gpio = pigpio_init()) {
        syslog(LOG_ERR, "pigpio_init failed: %d", gpio);
        return 1;
    }

    // Set up PWM mode
    if ((pwm = gpioGetConstrainedMode(gpio, GPIO_MODE PWM, PWM_FREQ, PWM_BIT)) < 0) {
        syslog(LOG_ERR, "gpioGetConstrainedMode failed: %d", pwm);
        pigpio_cleanup();
        return 1;
    }

    // Set up GPIO for LED control
    if ((ret = gpioInitialise(gpio, LED_RED, GPIO_MODE_OUTPUT)) < 0) {
        syslog(LOG_ERR, "gpioInitialise failed: %d", ret);
        pigpio_cleanup();
        return 1;
    }
    if ((ret = gpioInitialise(gpio, LED_GREEN, GPIO_MODE_OUTPUT)) < 0) {
        syslog(LOG_ERR, "gpioInitialise failed: %d", ret);
        gpioDestroy(gpio, LED_RED);
        pigpio_cleanup();
        return 1;
    }
    if ((ret = gpioInitialise(gpio, LED_BLUE, GPIO_MODE_OUTPUT)) < 0) {
        syslog(LOG_ERR, "gpioInitialise failed: %d", ret);
        gpioDestroy(gpio, LED_GREEN);
        gpioDestroy(gpio, LED_BLUE);
        pigpio_cleanup();
        return 1;
    }

    // Set up signal handlers
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, &old_sa) < 0) {
        syslog(LOG_ERR, "sigaction failed: %d", sigaction);
        gpioDestroy(gpio, LED_RED);
        gpioDestroy(gpio, LED_GREEN);
        gpioDestroy(gpio, LED_BLUE);
        pigpio_cleanup();
        return 1;
    }

    // Seed random number generator
    srand(time(NULL));

    while (1) {
        // Generate a random hue
        int hue = rand() % 256;

        // Convert hue to RGB
        int r, g, b;
        int h, s, v;
        int i;
        float f;
        float q;
        float p;

        h = hue / 360.0;
        s = 1.0;
        v = 1.0;
        if (h < 1.0 / 6.0) {
            r = v;
            g = v * 6.0 * (1.0 - h);
            b = v * (2.0 - h);
        } else if (h < 2.0 / 6.0) {
            r = v * (2.0 - h);
            g = v;
            b = v;
        } else if (h < 3.0 / 6.0) {
            r = 0.0;
            g = v;
            b = v * (6.0 - h);
        } else if (h < 4.0 / 6.0) {
            r = v * (6.0 - h);
            g = v;
            b = 0.0;
        } else if (h < 5.0 / 6.0) {
            r = 0.0;
            g = v * (6.0 - h);
            b = v;
        } else {
            r = v;
            g = 0.0;
            b = v * (6.0 - h);
        }

        // Apply saturation and value
        r = (int)(r * s + 0.5);
        g = (int)(g * s + 0.5);
        b = (int)(b * s + 0.5);

        // Clamp values to [0, 255]
        r = (r < 0) ? 0 : (r > 255) ? 255 : r;
        g = (g < 0) ? 0 : (g > 255) ? 255 : g;
        b = (b < 0) ? 0 : (b > 255) ? 255 : b;

        // Invert PWM duty cycle for common-anode LED
        r = 255 - r;
        g = 255 - g;
        b = 255 - b;

        // Set PWM duty cycle
        for (i = 0; i < NUM_STEPS; i++) {
            f = (float)i / (NUM_STEPS - 1);
            q = f * f * (3.0 - 2.0 * f);
            p = f * (f * (3.0 - 2.0 * f) * 3.0);
            r = (int)(r + (q * (2.0 * b - b * p) + r * (3.0 - 2.0 * b + b * p)));
            g = (int)(g + (q * (2.0 * g - g * p) + g * (3.0 - 2.0 * g + g * p)));
            b = (int)(b + (q * (2.0 * r - r * p) + b * (3.0 - 2.0 * r + r * p)));
            if (r < 0) r = 0;
            if (r > 255) r = 255;
            if (g < 0) g = 0;
            if (g > 255) g = 255;
            if (b < 0) b = 0;
            if (b > 255) b = 255;
            gpioWrite(gpio, LED_RED, r);
            gpioWrite(gpio, LED_GREEN, g);
            gpioWrite(gpio, LED_BLUE, b);
            usleep(1000 / PWM_FREQ);
        }
    }

    // Clean up
    gpioDestroy(gpio, LED_RED);
    gpioDestroy(gpio, LED_GREEN);
    gpioDestroy(gpio, LED_BLUE);
    pigpio_cleanup();
    return 0;
}

void sigint_handler(int sig) {
    // Turn off LED
    gpioWrite(gpio, LED_RED, 0);
    gpioWrite(gpio, LED_GREEN, 0);
    gpioWrite(gpio, LED_BLUE, 0);

    // Release pigpio resources
    pigpio_cleanup();

    // Close syslog
    syslog_close();

    // Exit
    exit(0);
}

