#define REG_ID 0x12
#define REG_CLEAR 0x14
#define REG_RED 0x16
#define REG_GREEN 0x18
#define REG_BLUE 0x1A
#define REG_GAIN 0x04
#define REG_OFFSET 0x05

int main() {
    int fd, gpio_fd;
    struct i2c_file *i2c;
    struct i2c_dev *i2c_dev;
    struct gpio_array *gpio;
    struct gpio_value *gpio_value;
    struct timespec delay;
    int ret, red, green, blue, clear, gain, offset, i, j;
    int threshold = 200;

    // Initialize GPIO
    gpio = pigpio_init();
    if (gpio == NULL) {
        perror("pigpio_init");
        return 1;
    }

    // Initialize I2C
    i2c = i2c_open(I2C_FILE, O_RDWR);
    if (i2c == -1) {
        perror("i2c_open");
        return 1;
    }

    // Set up I2C device
    i2c_dev = i2c_get_device(i2c, I2C_ADDRESS);
    if (i2c_dev == NULL) {
        perror("i2c_get_device");
        return 1;
    }

    // Power on sensor
    ret = ioctl(i2c, I2C_PON, 0);
    if (ret == -1) {
        perror("i2c_PON");
        return 1;
    }

    // Enable RGBC
    ret = ioctl(i2c, I2C_GSET, REG_RGBC);
    if (ret == -1) {
        perror("i2c_GSET");
        return 1;
    }

    // Set integration time
    ret = ioctl(i2c, I2C_WREG, REG_ATIME, 0x00);
    if (ret == -1) {
        perror("i2c_WREG");
        return 1;
    }

    // Set gain
    ret = ioctl(i2c, I2C_WREG, REG_CONTROL, 0x00);
    if (ret == -1) {
        perror("i2c_WREG");
        return 1;
    }

    // Read sensor ID
    ret = ioctl(i2c, I2C_RDREG, REG_ID);
    if (ret == -1) {
        perror("i2c_RDREG");
        return 1;
    }
    if (ret != 0x44) {
        printf("Invalid sensor ID\n");
        return 1;
    }

    // Read clear, red, green, and blue registers
    ret = ioctl(i2c, I2C_RDREG, REG_CLEAR);
    if (ret == -1) {
        perror("i2c_RDREG");
        return 1;
    }
    clear = (ret >> 8) & 0xFF;

    ret = ioctl(i2c, I2C_RDREG, REG_RED);
    if (ret == -1) {
        perror("i2c_RDREG");
        return 1;
    }
    red = (ret >> 8) & 0xFF;

    ret = ioctl(i2c, I2C_RDREG, REG_GREEN);
    if (ret == -1) {
        perror("i2c_RDREG");
        return 1;
