    ret = ioctl(i2c, I2C_WREG, REG_GAIN, 0x01);
    if (ret == -1) {
        perror("i2c_WREG");
        return 1;
    }
    ret = ioctl(i2c, I2C_WREG, REG_OFFSET, 0x00);
    if (ret == -1) {
        perror("i2c_WREG");
        return 1;
