    while (1) {
        // Poll sensor
        ret = ioctl(i2c, I2C_RDREG, REG_CLEAR);
        if (ret == -1) {
            perror("i2c_RDREG");
            return 1;
        }
        clear = (ret >> 8) & 0xFF;

        // Apply gain and offset calibration
        ret = ioctl(i2c, I2C_WREG, REG_GAIN, 0x01);
        if (ret == -1) {
            perror("i2c_WREG");
            return 1;
        }
        ret = ioctl(i2c, I2C_WREG, REG_OFFSET, 0x00);
        if (ret == -1) {
            perror("i2c_WREG");
            return 1;
        }

        // Check if red value exceeds threshold
        if (red > threshold) {
            gpio_value = gpio_get_value(gpio_fd);
            if (gpio_value == 0) {
                gpio_set_value(gpio_fd, 1);
            } else {
                gpio_set_value(gpio_fd, 0);
            }
        } else {
            gpio_set_value(gpio_fd, 0);
        }

        // Sleep for 200 ms
        nanosleep(&delay, NULL);
        delay.tv_sec = 0;
        delay.tv_nsec = 200 * 1000000;
    }

    // Clean up
    gpio_set_value(gpio_fd, 0);
    gpio_close(gpio_fd);
    pigpio_close(gpio);
    close(i2c);
    close(gpio_fd);
    return 0;
}

