#define LED_PIN 18
#define I2C_ADDRESS 0x23
#define I2C_TIMEOUT 0.1
#define I2C_RETRY 3
#define MAX_LUX 1000
#define MIN_LUX 0
#define MAX_BRIGHTNESS 255
#define MIN_BRIGHTNESS 0

int main(int argc, char *argv[]) {
    int i, j;
    int led, i2c_fd;
    unsigned char i2c_buf[2];
    unsigned int lux;
    unsigned int brightness;
    struct timespec delay;
    struct sigaction sa;
    struct sigaction old_sa;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up GPIO18 as output
    if (gpioMode(LED_PIN, PI_OUTPUT) < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }

    // Set up I2C
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR) < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set I2C address and mode
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set continuous high-resolution mode
    if (ioctl(i2c_fd, 0x10, NULL) < 0) {
        perror("ioctl");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Wait for 180 ms
    nanosleep(&delay, NULL);
    delay.tv_sec = 0;
    delay.tv_nsec = 180 * 1000000;

    // Read 2 bytes
    if (read(i2c_fd, i2c_buf, 2) < 2) {
        perror("read");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Compute lux
    lux = (i2c_buf[0] << 8) | i2c_buf[1];
    if (lux > MAX_LUX) {
        lux = MAX_LUX;
    } else if (lux < MIN_LUX) {
        lux = MIN_LUX;
    }

    // Map lux to brightness
    brightness = (int)(log(lux / MAX_LUX) * (MAX_BRIGHTNESS - MIN_BRIGHTNESS) + MIN_BRIGHTNESS);

    // Ensure brightness is within valid range
    if (brightness < MIN_BRIGHTNESS) {
        brightness = MIN_BRIGHTNESS;
    } else if (brightness > MAX_BRIGHTNESS) {
        brightness = MAX_BRIGHTNESS;
    }

    // Set brightness
    if (gpioWrite(LED_PIN, brightness) < 0) {
        perror("gpioWrite");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, &old_sa) < 0) {
        perror("sigaction");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read 2 bytes
        if (read(i2c_fd, i2c_buf, 2) < 2) {
            perror("read");
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Compute lux
        lux = (i2c_buf[0] << 8) | i2c_buf[1];
        if (lux > MAX_LUX) {
            lux = MAX_LUX;
        } else if (lux < MIN_LUX) {
            lux = MIN_LUX;
        }

        // Map lux to brightness
        brightness = (int)(log(lux / MAX_LUX) * (MAX_BRIGHTNESS - MIN_BRIGHTNESS) + MIN_BRIGHTNESS);

        // Ensure brightness is within valid range
        if (brightness < MIN_BRIGHTNESS) {
            brightness = MIN_BRIGHTNESS;
        } else if (brightness > MAX_BRIGHTNESS) {
            brightness = MAX_BRIGHTNESS;
        }

        // Set brightness
        if (gpioWrite(LED_PIN, brightness) < 0) {
            perror("gpioWrite");
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Wait 100 ms
        nanosleep(&delay, NULL);
    }

    // Clean up
    close(i2c_fd);
    gpioTerminate();
    return 0;
}

void sigint_handler(int sig) {
    gpioTerminate();
    exit(0);
}

