// Global variables
int bh1750_addr_low = 0x23;
int bh1750_addr_high = 0x5C;
int gpio_mosi = 10;
int gpio_sclk = 11;
int gpio_led = 18; // APA102 LED strip GPIO
int brightness = 0;
int brightness_target = 0;
int brightness_step = 0;
int num_sensors = 0;
int sensor_readings[2];
int sensor_errors = 0;

// Function to read a BH1750 sensor
int read_bh1750(int addr) {
    int ret = pigpio_i2c_read(addr, 0x21, 2);
    if (ret < 0) {
        printf("I2C error reading BH1750 sensor at address %d\n", addr);
        return -1;
    }
    return ret;
}

// Function to calculate the average lux reading from multiple sensors
int calculate_average_lux(int num_sensors) {
    int total = 0;
    for (int i = 0; i < num_sensors; i++) {
        int reading = read_bh1750(i < 2 ? bh1750_addr_low : bh1750_addr_high);
        if (reading < 0) {
            sensor_errors++;
            continue;
        }
        total += reading;
    }
    if (num_sensors == 0) {
        sensor_errors++;
        return 0;
    }
    return total / num_sensors;
}

// Function to map lux reading to brightness level
int map_lux_to_brightness(int lux) {
    return (int)(31 - (lux / 1000.0));
}

// Function to smoothly fade the LED strip's brightness
void fade_brightness() {
    if (brightness_target != brightness) {
        if (brightness_target > brightness) {
            brightness += brightness_step;
            if (brightness > 31) {
                brightness = 31;
            }
        } else {
            brightness -= brightness_step;
            if (brightness < 0) {
                brightness = 0;
            }
        }
        pigpio_write(gpio_led, brightness);
    }
}

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    pigpio_close(gpio_led);
    pigpio_close(gpio_sclk);
    pigpio_close(gpio_mosi);
    pigpio_close(bh1750_addr_low);
    pigpio_close(bh1750_addr_high);
    exit(0);
}

