    if (sensor_readings[0] < 0 || sensor_readings[1] < 0) {
        sensor_errors += 2;
        num_sensors = 0;
    } else {
        brightness = map_lux_to_brightness(calculate_average_lux(num_sensors));
    }

    // Main loop
    while (1) {
        // Read sensor data
        if (num_sensors > 0) {
            sensor_readings[0] = read_bh1750(bh1750_addr_low);
