#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod/gpiod.h>
#include <gpiod/gpiod-async.h>
#include <gpiod/gpiod-line.h>

// Define constants
#define GPIO4 4
#define GPIO17 17
#define GPIO18 18
#define BuzzerPin GPIO17
#define LEDPin GPIO18
#define PollInterval 50
#define SelfTestDuration 500
#define SelfTestBlinkDuration 100
#define SelfTestBlinkInterval 100
#define SelfTestBlinkPattern 5
#define SelfTestBuzzerPattern 3
#define SelfTestBuzzerShort 200
#define SelfTestBuzzerLong 600
#define SelfTestBlinkPatternDuration SelfTestBlinkDuration * SelfTestBlinkInterval
#define SelfTestBuzzerPatternDuration SelfTestBuzzerShort * SelfTestBuzzerPattern
#define SelfTestBlinkPatternDuration SelfTestBlinkPattern * SelfTestBlinkInterval
#define SelfTestBuzzerPatternDuration SelfTestBuzzerPattern * SelfTestBlinkInterval
#define SelfTestDurationMs SelfTestDuration * 1000

// Define structures
typedef struct {
    gpiod_line_t line;
    gpiod_async_t async;
    gpiod_async_callback_t callback;
} FlameSensor;

// Define signal handler
void sigint_handler(int sig) {
    gpiod_async_cancel(&async);
    gpiod_line_cancel(&line);
    gpiod_line_release(&line);
    exit(1);
}

// Define main function
int main() {
    // Initialize signal handler
    signal(SIGINT, sigint_handler);

    // Initialize libgpiod
    if (gpiod_init() != 0) {
        fprintf(stderr, "Error initializing libgpiod: %s\n", gpiod_strerror());
        return 1;
    }

    // Create a new line object for the flame sensor
    if (gpiod_line_create(&line, GPIO4, GPIOD_LINE_IN, GPIOD_LINE_EDGE_RISING, NULL, NULL) != 0) {
        fprintf(stderr, "Error creating line object for flame sensor: %s\n", gpiod_strerror());
        gpiod_exit();
        return 1;
    }

    // Create a new async object for the flame sensor
    if (gpiod_async_create(&async, &line, NULL, NULL) != 0) {
        fprintf(stderr, "Error creating async object for flame sensor: %s\n", gpiod_strerror());
        gpiod_line_release(&line);
        gpiod_exit();
        return 1;
    }

    // Set up the async callback
    gpiod_async_callback_set(&async, &callback, NULL);

    // Set up the line callback
    gpiod_line_callback_set(&line, &callback, NULL);

    // Initialize the flame sensor
    gpiod_line_request(&line, GPIOD_LINE_VALUE, NULL, NULL);

    // Run self-test
    if (self_test() != 0) {
        // Signal error
        gpiod_async_cancel(&async);
        gpiod_line_cancel(&line);
        gpiod_line_release(&line);
        gpiod_exit();
        return 1;
    }

    // Main loop
    while (1) {
        // Poll the flame sensor
        if (gpiod_line_read(&line) == 0) {
            // Flame detected, activate buzzer and LED
            activate_buzzer_and_led();
        }
        usleep(PollInterval * 1000);
    }

    // Clean up
    gpiod_async_cancel(&async);
    gpiod_line_cancel(&line);
    gpiod_line_release(&line);
    gpiod_exit();

    return 0;
}

// Define self-test function
int self_test() {
    // Blink LED twice
    for (int i = 0; i < 2; i++) {
        activate_buzzer_and_led();
        usleep(SelfTestBlinkDuration * 1000);
        deactivate_buzzer_and_led();
        usleep(SelfTestBlinkDuration * 1000);
    }

    // Read flame sensor 5 times
    for (int i = 0; i < 5; i++) {
        if (gpiod_line_read(&line) != 0) {
            return 1; // Flame not detected
        }
        usleep(SelfTestDurationMs);
    }

    // Signal success
    return 0;
}

// Define activate_buzzer_and_led function
void activate_buzzer_and_led() {
    // Activate buzzer
    gpiod_line_request(&line, GPIOD_LINE_VALUE, NULL, NULL);
    gpiod_line_write(&line, 0);

    // Activate LED
    gpiod_line_request(&line, GPIOD_LINE_VALUE, NULL, NULL);
    gpiod_line_write(&line, 0);
}

// Define deactivate_buzzer_and_led function
void deactivate_buzzer_and_led() {
    // Deactivate buzzer
    gpiod_line_request(&line, GPIOD_LINE_VALUE, NULL, NULL);
    gpiod_line_write(&line, 1);

    // Deactivate LED
    gpiod_line_request(&line, GPIOD_LINE_VALUE, NULL, NULL);
    gpiod_line_write(&line, 1);
}

// Define signal handler for error
void error_handler(gpiod_async_error_t error) {
    fprintf(stderr, "Error: %s\n", gpiod_strerror(error));
    gpiod_async_cancel(&async);
    gpiod_line_cancel(&line);
    gpiod_line_release(&line);
    gpiod_exit();
    exit(1);
}

