#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <linux/i2c-dev.h>
#include <linux/gpio.h>

#define I2C_ADDRESS 0x23
#define I2C_FILE "/dev/i2c-1"
#define GPIO_PIN 17
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL 1000
#define SAMPLE_RATE 0.5
#define MAX_LUX 1000
#define MIN_LUX 0.5
#define MAX_BRIGHTNESS 5.0
#define DUTY_CYCLE 0.5

int main() {
    int fd, gpio_fd;
    unsigned char buffer[BUFFER_SIZE];
    unsigned int avg_lux = 0;
    unsigned int rate = 0;
    unsigned int i;
    struct i2c_client *client;
    struct i2c_dev *dev;
    struct gpio_export *gpio_export;
    struct gpio_request *gpio_request;
    struct gpio_flags *gpio_flags;
    struct gpio_value *gpio_value;

    // Initialize signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Open I2C file descriptor
    fd = open(I2C_FILE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C file");
        return 1;
    }

    // Get I2C device
    client = i2c_get_client(fd);
    if (!client) {
        perror("Failed to get I2C client");
        close(fd);
        return 1;
    }

    // Get I2C device
    dev = i2c_get_clientdata(client);
    if (!dev) {
        perror("Failed to get I2C device");
        i2c_release_client(client);
        close(fd);
        return 1;
    }

    // Export GPIO pin
    gpio_export = gpio_export(GPIO_PIN);
    if (!gpio_export) {
        perror("Failed to export GPIO pin");
        i2c_release_client(client);
        close(fd);
        return 1;
    }

    // Get GPIO request
    gpio_request = gpio_request(gpio_export);
    if (!gpio_request) {
        perror("Failed to get GPIO request");
        gpio_unexport(gpio_export);
        i2c_release_client(client);
        close(fd);
        return 1;
    }

    // Get GPIO flags
    gpio_flags = gpio_get_requestdata(gpio_request);
    if (!gpio_flags) {
        perror("Failed to get GPIO flags");
        gpio_request_free(gpio_request);
        gpio_unexport(gpio_export);
        i2c_release_client(client);
        close(fd);
        return 1;
    }

    // Get GPIO value
    gpio_value = gpio_get_requestdata(gpio_request);
    if (!gpio_value) {
        perror("Failed to get GPIO value");
        gpio_flags_free(gpio_flags);
