#include <gpiod/gpiod.h>

#define GPIO CHIP 0
#define GPIO_LINE 17
#define GPIO_LINE2 18

int main(int argc, char **argv) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_event *line_event;
    struct gpiod_line_event_wait *line_event_wait;
    struct gpiod_line_event_wait_options wait_options;
    struct gpiod_line_event_wait_options2 wait_options2;
    int ret;

    // Set up signal handling for SIGINT
    signal(SIGINT, sigint_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP, GpioChipOpenFlagsDefault);
    if (chip == NULL) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Request the LED line as output initially low
    line = gpiod_line_request(chip, GPIO_LINE, GpioLineRequestFlagsOutput, GpioLineRequestFlagsDefault);
    if (line == NULL) {
        perror("gpiod_line_request");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the button line as input with internal pull-up and falling-edge event detection
    line_event = gpiod_line_event_request(chip, GPIO_LINE2, GpioLineEventRequestFlagsInput, GpioLineEventRequestFlagsDefault);
    if (line_event == NULL) {
        perror("gpiod_line_event_request");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the initial state of the LED line
    ret = gpiod_line_set_value(line, 0);
    if (ret != 0) {
        perror("gpiod_line_set_value");
        gpiod_line_release(line);
        gpiod_line_event_release(line_event);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the initial state of the button line
    ret = gpiod_line_get_value(line_event, &wait_options2);
    if (ret != 0) {
        perror("gpiod_line_get_value");
        gpiod_line_release(line);
        gpiod_line_event_release(line_event);
        gpiod_chip_close(chip);
        return 1;
    }
    if (wait_options2.value != 0) {
        gpiod_line_set_value(line, 0);
    }

    // Create a line event wait object
    line_event_wait = gpiod_line_event_wait_request(line_event, &wait_options);
    if (line_event_wait == NULL) {
        perror("gpiod_line_event_wait_request");
        gpiod_line_event_release(line_event);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the initial timeout for the line event wait
    ret = gpiod_line_event_wait_set_timeout(line_event_wait, 1);
    if (ret != 0) {
        perror("gpiod_line_event_wait_set_timeout");
        gpiod_line_event_wait_release(line_event_wait);
        gpiod_line_event_release(line_event);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Toggle the LED
        ret = gpiod_line_set_value(line, 1);
        if (ret != 0) {
            perror("gpiod_line_set_value");
            gpiod_line_event_wait_release(line_event_wait);
            gpiod_line_event_release(line_event);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return 1;
        }

        // Wait for a button press
        ret = gpiod_line_event_wait(line_event_wait, &wait_options2, &wait_options);
        if (ret != 0) {
            perror("gpiod_line_event_wait");
            gpiod_line_event_wait_release(line_event_wait);
            gpiod_line_event_release(line_event);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return 1;
        }

        // If a button press is detected, stop the blinking immediately, turn off the LED, print a message, and exit cleanly
        if (wait_options2.value == 0) {
            gpiod_line_set_value(line, 0);
            printf("Button pressed, stopping blinking\n");
            break;
        }
    }

    // Release all resources
    gpiod_line_event_wait_release(line_event_wait);
    gpiod_line_event_release(line_event);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

void sigint_handler(int sig) {
    // Release all resources
    gpiod_line_event_wait_release(line_event_wait);
    gpiod_line_event_release(line_event);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    // Exit cleanly
    exit(0);
}

