int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    // Check for failure
    if (gpioCheckErrors() != 0) {
        fprintf(stderr, "pigpio error\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO5 as an output
    if (gpioMode(5, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO5 as output\n");
        gpioTerminate();
        return 1;
    }

    // Infinite loop
    while (1) {
        // Turn the LED on
        if (gpioWrite(5, 1) < 0) {
            fprintf(stderr, "Failed to turn LED on\n");
            gpioTerminate();
            return 1;
        }
        printf("LED ON\n");
        fflush(stdout);

        // Wait 750 ms
        if (time_sleep(0.75) < 0) {
            fprintf(stderr, "Failed to wait 750 ms\n");
            gpioTerminate();
            return 1;
        }

        // Turn the LED off
        if (gpioWrite(5, 0) < 0) {
            fprintf(stderr, "Failed to turn LED off\n");
            gpioTerminate();
            return 1;
        }
        printf("LED OFF\n");
        fflush(stdout);

        // Flush stdout to ensure output is visible immediately
        fflush(stdout);
    }

    // Cleanly terminate pigpio on SIGINT
    signal(SIGINT, SIG_IGN);
    gpioTerminate();
    return 0;
}

