#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod/gpiod.h>

// Define signal handler for SIGINT
void sigint_handler(int sig) {
    gpiod_chip_close(gpiod_chip_open_by_number(0));
    exit(0);
}

int main() {
    // Initialize signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Seed random number generator with current time
    srand(time(NULL));

    // Open the gpiod chip
    gpiod_chip *chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Failed to open gpiod chip\n");
        return 1;
    }

    // Get the line objects for the three GPIOs
    gpiod_line *red = gpiod_chip_get_line(chip, 24);
    gpiod_line *green = gpiod_chip_get_line(chip, 23);
    gpiod_line *blue = gpiod_chip_get_line(chip, 18);

    // Request output for each line
    if (!gpiod_line_request_output(red)) {
        fprintf(stderr, "Failed to request output for red line\n");
        gpiod_chip_close(chip);
        return 1;
    }
    if (!gpiod_line_request_output(green)) {
        fprintf(stderr, "Failed to request output for green line\n");
        gpiod_chip_close(chip);
        return 1;
    }
    if (!gpiod_line_request_output(blue)) {
        fprintf(stderr, "Failed to request output for blue line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the GPIOs as outputs
    gpiod_line_set_direction(red, gpiod_line_direction_output);
    gpiod_line_set_direction(green, gpiod_line_direction_output);
    gpiod_line_set_direction(blue, gpiod_line_direction_output);

    // Main loop
    while (1) {
        // Generate random RGB values
        uint8_t r = rand() % 101;
        uint8_t g = rand() % 101;
        uint8_t b = rand() % 101;

        // Calculate PWM duty cycles
        uint32_t duty_cycles[3] = {r, g, b};
        uint32_t period = 10000; // 10 ms period
        uint32_t ticks = period / 10; // 100 Hz

        // Busy-wait PWM loop
        for (uint32_t i = 0; i < ticks; i++) {
            // Calculate the current time
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);

            // Calculate the elapsed time since the last iteration
            struct timespec elapsed;
            clock_gettime(CLOCK_MONOTONIC, &elapsed);
            uint32_t elapsed_ms = (elapsed.tv_sec * 1000) + (elapsed.tv_nsec / 1000000);

            // Calculate the remaining time until the next iteration
            uint32_t remaining = ticks - (i + 1);

            // Calculate the duty cycle for each channel
            uint32_t red_duty = (r * remaining) / ticks;
            uint32_t green_duty = (g * remaining) / ticks;
            uint32_t blue_duty = (b * remaining) / ticks;

            // Set the PWM duty cycles
            gpiod_line_set_value(red, gpiod_line_value_to_uint32(gpiod_line_get_value(red), red_duty));
            gpiod_line_set_value(green, gpiod_line_value_to_uint32(gpiod_line_get_value(green), green_duty));
            gpiod_line_set_value(blue, gpiod_line_value_to_uint32(gpiod_line_get_value(blue), blue_duty));

            // Sleep for the remaining time
            struct timespec sleep_time;
            sleep_time.tv_sec = remaining / 1000000;
            sleep_time.tv_nsec = (remaining % 1000000) * 1000;
            clock_nanosleep(CLOCK_MONOTONIC, 0, &sleep_time);
        }
    }

    // Clean up
    gpiod_chip_close(chip);
    return 0;
}

