#define I2C_ADDRESS_LSB 0x64
#define I2C_ADDRESS_MSB 0x65
#define I2C_ADDRESS_RED 0x66
#define I2C_ADDRESS_GREEN 0x68
#define I2C_ADDRESS_BLUE 0x6A
#define I2C_ADDRESS_COLOR 0x69
#define I2C_ADDRESS_LED 0x6B
#define I2C Bus 1
#define LED_PIN 18
#define CSV_FILE "color_log.csv"

int main() {
    int i2c_fd;
    int led_fd;
    int led_state = 0;
    int retry_count = 0;
    struct sigaction sa;
    struct sigaction old_sa;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up signal handling
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, &old_sa) < 0) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, &old_sa) < 0) {
        perror("sigaction");
        return 1;
    }

    // Open I2C file
    if ((i2c_fd = open(CSV_FILE, O_RDWR | O_CREAT | O_WRONLY | O_APPEND) < 0) {
        perror("open");
        return 1;
    }

    while (1) {
        // Initialize I2C
        if (i2c_init(i2c_fd, I2C Bus, I2C_ADDRESS) < 0) {
            perror("i2c_init");
            retry_count++;
            usleep(100 * 1000);
            continue;
        }

        // Write to MODE register
        if (i2c_write(i2c_fd, I2C_ADDRESS_MODE, 0x01) < 0) {
            perror("i2c_write");
            retry_count++;
            usleep(100 * 1000);
            continue;
        }

        // Read ALS data
        uint16_t als_value;
        if (i2c_read(i2c_fd, I2C_ADDRESS_LSB, 2, &als_value) < 0) {
            perror("i2c_read");
            retry_count++;
            usleep(100 * 1000);
            continue;
        }
        als_value = (als_value << 8) | i2c_read(i2c_fd, I2C_ADDRESS_MSB, 1, NULL);
        if (als_value > 0xFFFF) {
            printf("ALS value out of range\n");
            continue;
        }

        // Read color data
        uint16_t red, green, blue;
        if (i2c_read(i2c_fd, I2C_ADDRESS_RED, 1, &red) < 0) {
            perror("i2c_read");
            retry_count++;
            usleep(100 * 1000);
            continue;
        }
        if (i2c_read(i2c_fd, I2C_ADDRESS_GREEN, 1, &green) < 0) {
            perror("i2c_read");
            retry_count++;
            usleep(100 * 1000);
            continue;
        }
        if (i2c_read(i2c_fd, I2C_ADDRESS_BLUE, 1, &blue) < 0) {
            perror("i2c_read");
            retry_count++;
            usleep(100 * 1000);
            continue;
        }

        // Log data
        fprintf(i2c_fd, "%d,%d,%d,%d\n", (int)als_value, red, green, blue);

        // Adjust LED brightness
        led_state = (als_value / 65535.0) * 255;
        if (led_state < 0) {
            led_state = 0;
        } else if (led_state > 255) {
            led_state = 255;
        }
        if (gpioWrite(led_fd, led_state) < 0) {
            perror("gpioWrite");
            retry_count++;
            usleep(100 * 1000);
            continue;
        }

        // Sleep
        usleep(500 * 1000);

        // Clean up
        if (i2c_close(i2c_fd) < 0) {
            perror("i2c_close");
            retry_count++;
            usleep(100 * 1000);
            continue;
        }
        if (gpioClose(led_fd) < 0) {
            perror("gpioClose");
            retry_count++;
            usleep(100 * 1000);
            continue;
        }
    }

    // Clean up
    if (gpioTerminate() < 0) {
        perror("gpioTerminate");
        return 1;
    }
    if (close(i2c_fd) < 0) {
        perror("close");
        return 1;
    }
    if (close(led_fd) < 0) {
        perror("close");
        return 1;
    }
    if (fclose(i2c_fd) < 0) {
        perror("fclose");
        return 1;
    }
    return 0;
}

void sigint_handler(int sig) {
    printf("Received SIGINT\n");
    gpioTerminate();
    exit(0);
}

