#include <sys/types.h>
#include <signal.h>

#define I2C_ADDRESS 0x1F
#define I2C_BUS 1
#define WHO_AM_I 0x0D
#define CTRL_REG1 0x2A
#define XYZ_DATA_CFG 0x0E
#define OUT_X_MSB 0x01
#define OUT_X_LSB 0x02
#define OUT_Y_MSB 0x03
#define OUT_Y_LSB 0x04
#define OUT_Z_MSB 0x05
#define OUT_Z_LSB 0x06
#define SENSITIVITY 4096
#define G_TO_MPS 9.81
#define THRESHOLD 19.62

int main() {
    int i, j, k;
    int i2c_fd;
    unsigned char whoami;
    unsigned char ctrl_reg1;
    unsigned char xyz_data_cfg;
    unsigned char out_x_msb, out_x_lsb, out_y_msb, out_y_lsb, out_z_msb, out_z_lsb;
    float x, y, z, magnitude;
    struct timespec ts;
    struct timespec last_impact;
    FILE *log_file;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C handle
    if ((i2c_fd = pigpioOpen(I2C_BUS, I2C_ADDRESS, PI_MMAP)) < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        gpioTerminate();
        return 1;
    }

    // Read WHO_AM_I register
    if (pigpioWrite(i2c_fd, WHO_AM_I, 1) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (pigpioRead(i2c_fd, &whoami, 1) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (whoami != 0xC7) {
        fprintf(stderr, "WHO_AM_I register does not match expected value 0xC7\n");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (pigpioWrite(i2c_fd, CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Failed to clear CTRL_REG1\n");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (pigpioWrite(i2c_fd, XYZ_DATA_CFG, 0x00) < 0) {
        fprintf(stderr, "Failed to configure XYZ_DATA_CFG\n");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (pigpioWrite(i2c_fd, CTRL_REG1, 0x02) < 0) {
        fprintf(stderr, "Failed to activate sensor\n");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Read acceleration data
    while (1) {
        if (pigpioRead(i2c_fd, &out_x_msb, 1) < 0) {
            fprintf(stderr, "Failed to read OUT_X_MSB register\n");
            continue;
