        if (pigpioRead(i2c_fd, &out_x_lsb, 1) < 0) {
            fprintf(stderr, "Failed to read OUT_X_LSB register\n");
            continue;
        }
        if (pigpioRead(i2c_fd, &out_y_msb, 1) < 0) {
