#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <time.h>

#define I2C_ADDRESS 0x69
#define I2C Bus 1
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define SENSITIVITY 0.00875
#define SAMPLES 100
#define LOG_INTERVAL 50
#define LOG_FILE "gyro_log.txt"

int main() {
    int fd, i, j, k, ret;
    struct i2c_msg msg;
    struct i2c_file *file;
    struct timespec start, end;
    struct timespec now;
    struct tm time;
    char buf[6];

    // Open I2C file descriptor
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Configure I2C bus
    ret = ioctl(fd, I2C_SLAVE, I2C Bus);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    // Write CTRL_REG1 (0x20) to 0x0F (normal mode, all axes enabled, 100 Hz ODR)
    msg.msg_name = CTRL_REG1;
    msg.msg_type = I2C_WRITE;
    msg.msg_dir = I2C_WRITE;
    msg.buf = &msg;
    msg.len = 1;
    ret = ioctl(fd, msg.msg_name, msg);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    // Write CTRL_REG4 (0x23) to 0x00 (250 dps full-scale, continuous update)
    msg.msg_name = CTRL_REG4;
    msg.msg_type = I2C_WRITE;
    msg.msg_dir = I2C_WRITE;
    msg.buf = &msg;
    msg.len = 1;
    ret = ioctl(fd, msg.msg_name, msg);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    // Read 6-byte OUT_X_L..OUT_Z_H block starting at register 0x28 using an auto-increment read
    msg.msg_name = OUT_X_L;
    msg.msg_type = I2C_READ;
    msg.msg_dir = I2C_READ;
    msg.buf = buf;
    msg.len = 6;
    ret = ioctl(fd, msg.msg_name, msg);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    // Convert raw 16-bit signed values to degrees per second
    for (i = 0; i < 6; i++) {
        buf[i] = (buf[i] << 8) | buf[i + 1];
        buf[i] = (buf[i] * SENSITIVITY) / 65536;
    }

    // Perform 100-sample stationary calibration at startup to compute X/Y/Z zero-rate offsets
    for (i = 0; i < SAMPLES; i++) {
        // Read raw values
        ret = ioctl(fd, msg.msg_name, msg);
        if (ret < 0) {
            perror("ioctl");
            close(fd);
            return 1;
        }

        // Compute zero-rate offsets
        for (j = 0; j < 3; j++) {
            for (k = 0; k < 6; k++) {
                buf[k] = (buf[k] << 8) | buf[k + 1];
                buf[k] = (buf[k] * SENSITIVITY) / 65536;
            }
            if (buf[0] > 50 || buf[1] > 50 || buf[2] > 50) {
                fprintf(stderr, "Warning: axis %c exceeds 50 dps\n", j + 'A');
            }
        }

        // Log calibrated X, Y, Z readings with ISO-8601 timestamps
        time_t now = time(NULL);
        struct tm *ltm = localtime(&now);
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", ltm);
        file = fopen(LOG_FILE, "a");
        if (file == NULL) {
            perror("fopen");
            close(fd);
            return 1;
        }
        fprintf(file, "%s %f %f %f\n", buf, buf[0], buf[1], buf[2]);
        fclose(file);
    }

    // Close I2C file descriptor
    close(fd);

    // Cleanly release the I2C file descriptor and log file on SIGINT/SIGTERM
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    return 0;
}

