#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <signal.h>

#define I2C_ADDRESS 0x53
#define I2C_ADDRESS_DEVID 0x00
#define I2C_ADDRESS_DATA 0x32
#define I2C_DATA_SIZE 6
#define GPIO_PIN 17
#define LOG_FILE "accel_log.txt"

int main(int argc, char **argv) {
    int i, j, k;
    int i2c_handle;
    int gpio;
    FILE *log_file;
    struct sigaction sa;
    struct sigaction sa_int;

    // Initialize pigpio
    if (gpio = pigpio_init()) {
        printf("pigpio_init() failed\n");
        return 1;
    }

    // Set up I2C
    if (i2c_handle = gpio_i2c_open(1, I2C_ADDRESS)) {
        printf("gpio_i2c_open() failed\n");
        pigpio_cleanup();
        return 1;
    }

    // Configure I2C
    if (gpio_i2c_write(i2c_handle, I2C_ADDRESS_DEVID, 0xE5)) {
        printf("gpio_i2c_write() failed\n");
        gpio_i2c_close(i2c_handle);
        pigpio_cleanup();
        return 1;
    }

    // Configure I2C for full-resolution, ±2g range
    if (gpio_i2c_write(i2c_handle, I2C_ADDRESS_DATA, 0x08)) {
        printf("gpio_i2c_write() failed\n");
        gpio_i2c_close(i2c_handle);
        pigpio_cleanup();
        return 1;
    }

    // Set up GPIO pin for output
    if (gpio = gpio_get(GPIO_PIN)) {
        printf("gpio_get() failed\n");
        gpio_i2c_close(i2c_handle);
        pigpio_cleanup();
        return 1;
    }

    // Set GPIO pin as output
    if (gpio = gpio_mode(GPIO_PIN, PI_OUTPUT Pull_up_down)) {
        printf("gpio_mode() failed\n");
        gpio = gpio_get(GPIO_PIN);
        gpio_i2c_close(i2c_handle);
        pigpio_cleanup();
        return 1;
    }

    // Set GPIO pin as active-high
    if (gpio = gpio_write(GPIO_PIN, 1)) {
        printf("gpio_write() failed\n");
        gpio = gpio_get(GPIO_PIN);
        gpio_i2c_close(i2c_handle);
        pigpio_cleanup();
        return 1;
    }

    // Set up signal handler for SIGINT and SIGTERM
    sa.sa_handler = sigint_handler;
    sa_int.sa_handler = sigterm_handler;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    sigaddset(&sa.sa_mask, SIGTERM);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        printf("sigaction() failed\n");
        gpio = gpio_get(GPIO_PIN);
        gpio_i2c_close(i2c_handle);
        pigpio_cleanup();
        return 1;
    }
    if (sigaction(SIGTERM, &sa_int, NULL) == -1) {
        printf("sigaction() failed\n");
        gpio = gpio_get(GPIO_PIN);
        gpio_i2c_close(i2c_handle);
        pigpio_cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        printf("fopen() failed\n");
        gpio = gpio_get(GPIO_PIN);
        gpio_i2c_close(i2c_handle);
        pigpio_cleanup();
        return 1;
    }

    // Main loop
    while (1) {
        // Read DEVID register
        if (gpio_i2c_read(i2c_handle, I2C_ADDRESS_DEVID, &i) == -1) {
            printf("gpio_i2c_read() failed\n");
            gpio = gpio_get(GPIO_PIN);
            gpio_i2c_close(i2c_handle);
            pigpio_cleanup();
            return 1;
        }
        if (i != 0xE5) {
            printf("DEVID register read failed\n");
            gpio = gpio_get(GPIO_PIN);
            gpio_i2c_close(i2c_handle);
            pigpio_cleanup();
            return 1;
        }

        // Read X, Y, Z data
        if (gpio_i2c_read(i2c_handle, I2C_ADDRESS_DATA, &i) == -1) {
            printf("gpio_i2c_read() failed\n");
            gpio = gpio_get(GPIO_PIN);
            gpio_i2c_close(i2c_handle);
            pigpio_cleanup();
            return 1;
        }
        if (i < I2C_DATA_SIZE || i > I2C_DATA_SIZE + 1) {
            printf("Invalid I2C data\n");
            gpio = gpio_get(GPIO_PIN);
            gpio_i2c_close(i2c_handle);
            pigpio_cleanup();
            return 1;
        }

        // Extract X, Y, Z values
        int x = (i >> 8) & 0xFF;
        int y = (i >> 4) & 0xFF;
        int z = i & 0xFF;

        // Log data
        fprintf(log_file, "%d,%d,%d\n", (int)(time(NULL) * 1000), x, y);
        if (x > 2.0 || y > 2.0 || z > 2.0) {
            gpio_write(GPIO_PIN, 0);
        } else {
            gpio_write(GPIO_PIN, 1);
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    gpio_i2c_close(i2c_handle);
    gpio = gpio_get(GPIO_PIN);
    gpio_write(GPIO_PIN, 0);
    pigpio_cleanup();

    return 0;
}

void sigint_handler(int sig) {
    gpio_i2c_close(-1);
    gpio = gpio_get(GPIO_PIN);
    gpio_write(GPIO_PIN, 0);
    pigpio_cleanup();
    exit(0);
}

void sigterm_handler(int sig) {
    gpio_i2c_close(-1);
    gpio = gpio_get(GPIO_PIN);
    gpio_write(GPIO_PIN, 0);
    pigpio_cleanup();
    exit(0);
}

