#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/time.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>

#define I2C_ADDRESS1 0x68
#define I2C_ADDRESS2 0x69
#define I2C_ADDRESS 1
#define I2C_REG_DATA 0x01
#define I2C_REG_CONTROL 0x00
#define I2C_CONTROL_ENABLE 0x80
#define I2C_SAMPLE_INTERVAL 10
#define LOG_FILE "audio_log.dat"

void sigint_handler(int sig) {
    pigpio_close(I2C_HANDLE1);
    pigpio_close(I2C_HANDLE2);
    close(LOG_FILE);
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    sigaction(SIGINT, &sa, NULL);

    if (pigpio_init() < 0) {
        perror("pigpio_init");
        return 1;
    }

    if (pigpio_i2c_open(I2C_ADDRESS, I2C_ADDRESS1, &I2C_HANDLE1) < 0) {
        perror("pigpio_i2c_open");
        pigpio_close(I2C_HANDLE1);
        pigpio_close(I2C_HANDLE2);
        return 1;
    }

    if (pigpio_i2c_open(I2C_ADDRESS, I2C_ADDRESS2, &I2C_HANDLE2) < 0) {
        pigpio_close(I2C_HANDLE1);
        pigpio_close(I2C_HANDLE2);
        return 1;
    }

    if (pigpio_i2c_write(I2C_HANDLE1, I2C_REG_CONTROL, I2C_CONTROL_ENABLE) < 0) {
        pigpio_close(I2C_HANDLE1);
        pigpio_close(I2C_HANDLE2);
        return 1;
    }

    if (pigpio_i2c_write(I2C_HANDLE2, I2C_REG_CONTROL, I2C_CONTROL_ENABLE) < 0) {
        pigpio_close(I2C_HANDLE1);
        pigpio_close(I2C_HANDLE2);
        return 1;
    }

    struct timeval start_time;
    gettimeofday(&start_time, NULL);

    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("fopen");
        pigpio_close(I2C_HANDLE1);
        pigpio_close(I2C_HANDLE2);
        return 1;
    }

    while (1) {
        struct timeval end_time;
        gettimeofday(&end_time, NULL);
        struct timespec time_diff;
        clock_gettime(CLOCK_REALTIME, &time_diff);
        time_t sec = time_diff.tv_sec;
        long nsec = time_diff.tv_nsec;

        if (pigpio_i2c_read(I2C_HANDLE1, I2C_ADDRESS1, I2C_REG_DATA, &data1, sizeof(data1)) < 0) {
            pigpio_close(I2C_HANDLE1);
            pigpio_close(I2C_HANDLE2);
            fclose(log_file);
            return 1;
        }

        if (pigpio_i2c_read(I2C_HANDLE2, I2C_ADDRESS2, I2C_REG_DATA, &data2, sizeof(data2)) < 0) {
            pigpio_close(I2C_HANDLE1);
            pigpio_close(I2C_HANDLE2);
            fclose(log_file);
            return 1;
        }

        if (data1 < 0 || data2 < 0) {
            pigpio_close(I2C_HANDLE1);
            pigpio_close(I2C_HANDLE2);
            fclose(log_file);
            return 1;
        }

        int16_t signed_data1 = (data1 & 0x7FFF);
        int16_t signed_data2 = (data2 & 0x7FFF);

        int16_t tdoa = signed_data1 - signed_data2;

        fprintf(log_file, "%ld,%09ld,%d,%d,%d\n", sec, nsec, signed_data1, signed_data2, tdoa);

        if (nsec >= 1000000) {
            gettimeofday(&start_time, NULL);
        }
    }

    pigpio_close(I2C_HANDLE1);
    pigpio_close(I2C_HANDLE2);
    fclose(log_file);
    pigpioTerminate();
    return 0;
}

