                        (int)(time(NULL) * 1000),
                        buffer[1],
                        accelValue,
                        buffer[2] * accelSensitivity,
                        buffer[3] * accelSensitivity);
            }
        }

        // Check for signals
        struct sigaction sa;
        sa.sa_handler = sigHandler;
        sa.sa_flags = SA_RESTART;
        if (sigaction(SIGINT, &sa, NULL) < 0) {
            fprintf(stderr, "Failed to set signal handler\n");
            continue;
        }
        if (sigaction(SIGTERM, &sa, NULL) < 0) {
            fprintf(stderr, "Failed to set signal handler\n");
            continue;
        }
        if (sigaction(SIGALRM, &sa, NULL) < 0) {
            fprintf(stderr, "Failed to set signal handler\n");
            continue;
        }

        // Delay for 100 ms
        usleep(100000);
    }

    // Cleanup
    cleanup();

    return 0;
}

