#include <signal.h>
#include <libgpiod/libgpiod.h>
#include <pigpio.h>

#define ADIS16448_CS 8
#define ADIS16448_SPI_MODE 3
#define ADIS16448_SPI_SPEED 1000000
#define ADIS16448_SPI_CS_PIN 0
#define ADIS16448_GYRO_OUT 0x04
#define ADIS16448_ACCEL_OUT 0x0A
#define ADIS16448_GYRO_SCALE 0.02
#define ADIS16448_ACCEL_SCALE 0.00025

int main() {
    int spi_fd, cs_fd;
    struct spi_ioc_transfer transfers[] = {
        { .tx { .buf = (uint8_t *) &0x80, .len = 1 },
        { .tx = { .buf = (uint8_t *) &0x80, .len = 1 },
        .rx = { .buf = (uint8_t *) &0x00, .len = 2 },
    };
    struct spi_ioc_transfer transfers2[] = {
        { .tx = { .buf = (uint8_t *) &0x00, .len = 2 },
        { .rx = { .buf = (uint8_t *) &0x00, .len = 6 },
    };

    // Initialize libgpiod
    gpiod_init();
    gpiod_chip_init(ADIS16448_CS, ADIS16448_CS_PIN, GPIOD CHIP_INITFlags());

    // Open SPI device
    spi_fd = spidev_open(0, 0);
    if (spi_fd < 0) {
        perror("spidev_open");
        return 1;
    }

    // Set up SPI mode
    if (ioctl(spi_fd, SPI_IOC_SET_MODE, ADIS16448_SPI_MODE) < 0) {
        perror("ioctl");
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_SET_SPEED, ADIS16448_SPI_SPEED) < 0) {
        perror("ioctl");
        return 1;
    }

    // Set up chip-select
    cs_fd = open(ADIS16448_CS, O_RDWR);
    if (cs_fd < 0) {
        perror("open");
        return 1;
    }
    if (ioctl(cs_fd, GPIO_SET, ADIS16448_CS_PIN) < 0) {
        perror("ioctl");
        return 1;
    }

    while (1) {
        // Read gyroscope and accelerometer data
        if (ioctl(spi_fd, SPI_IOC_READ, transfers) < 0) {
            perror("ioctl");
            return 1;
        }
        uint16_t gyro_x = (transfers[0].rx[0] << 8) | transfers[0].rx[1];
        uint16_t gyro_y = (transfers[1].rx[0] << 8) | transfers[1].rx[1];
        uint16_t gyro_z = (transfers[1].rx[2] << 8) | transfers[1].rx[3];
        uint16_t accel_x = (transfers[2].rx[0] << 8) | transfers[2].rx[1];
        uint16_t accel_y = (transfers[2].rx[2] << 8) | transfers[2].rx[3];
        uint16_t accel_z = (transfers[2].rx[4] << 8) | transfers[2].rx[5];

        // Apply scale factors
        gyro_x *= ADIS16448_GYRO_SCALE;
        gyro_y *= ADIS16448_GYRO_SCALE;
        gyro_z *= ADIS16448_GYRO_SCALE;
        accel_x *= ADIS16448_ACCEL_SCALE;
        accel_y *= ADIS16448_ACCEL_SCALE;
        accel_z *= ADIS16448_ACCEL_SCALE;

        // Log data
        printf("gyro_x: %f, gyro_y: %f, gyro_z: %f, accel_x: %f, accel_y: %f, accel_z: %f\n",
               gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        // Wait 100 ms
        usleep(100000);
    }

    // Clean up
    close(cs_fd);
    close(spi_fd);
    gpiod_chip_release(ADIS16448_CS);
    gpiod_exit();
    return 0;
}

