#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>

#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_CS 8
#define SPI_SCK 9
#define SPI_MOSI 10
#define SPI_MISO 11
#define ADIS16448_READ_COMMAND 0x80
#define ADIS16448_GYRO_X_OUT 0x04
#define ADIS16448_GYRO_Y_OUT 0x06
#define ADIS16448_GYRO_Z_OUT 0x08
#define ADIS16448_ACCL_X_OUT 0x0A
#define ADIS16448_ACCL_Y_OUT 0x0C
#define ADIS16448_ACCL_Z_OUT 0x0E
#define ADIS16448_GYRO_SCALE 0.05
#define ADIS16448_ACCL_SCALE 0.00025

int main() {
    int spi;
    int ret;
    int i;
    unsigned char read_cmd;
    unsigned char gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
    unsigned char dummy;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    // Set up SPI
    spi = spiOpen(SPI_CS, SPI_MODE, SPI_SPEED, SPI_SCK, SPI_MOSI, SPI_MISO);
    if (spi < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up SPI CS pin as output
    gpioSetMode(SPI_CS, PI_OUTPUT);
    gpioPullUp(SPI_CS, PI_HIGH);

    // Set up SPI SCK, MOSI, and MISO pins as output
    gpioSetMode(SPI_SCK, PI_OUTPUT);
    gpioSetMode(SPI_MOSI, PI_OUTPUT);
    gpioSetMode(SPI_MISO, PI_INPUT);

    // Set up SPI clock stretching
    spiTransfer spi_stretch = spiTransfer(SPI_CS, SPI_SCK, SPI_MOSI, SPI_MISO, 40);
    if (spi_stretch < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Send read command
        read_cmd = (ADIS16448_READ_COMMAND | 0x80);
        ret = spiTransfer(SPI_CS, SPI_SCK, SPI_MOSI, SPI_MISO, &read_cmd, 1);
        if (ret < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            gpioTerminate();
            return 1;
        }

        // Wait for 40 microseconds
        usleep(40 * 1000);

        // Send dummy 0x0000
        dummy = 0x0000;
        ret = spiTransfer(SPI_CS, SPI_SCK, SPI_MOSI, SPI_MISO, &dummy, 1);
        if (ret < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            gpioTerminate();
            return 1;
        }

        // Read gyroscope and accelerometer data
        ret = spiTransfer(SPI_CS, SPI_SCK, SPI_MOSI, SPI_MISO, &gyro_x, 2);
        if (ret < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            gpioTerminate();
            return 1;
        }
        ret = spiTransfer(SPI_CS, SPI_SCK, SPI_MOSI, SPI_MISO, &gyro_y, 2);
        if (ret < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            gpioTerminate();
            return 1;
        }
        ret = spiTransfer(SPI_CS, SPI_SCK, SPI_MOSI, SPI_MISO, &gyro_z, 2);
        if (ret < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            gpioTerminate();
            return 1;
        }
        ret = spiTransfer(SPI_CS, SPI_SCK, SPI_MOSI, SPI_MISO, &accel_x, 2);
        if (ret < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            gpioTerminate();
            return 1;
        }
        ret = spiTransfer(SPI_CS, SPI_SCK, SPI_MOSI, SPI_MISO, &accel_y, 2);
        if (ret < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            gpioTerminate();
            return 1;
        }
        ret = spiTransfer(SPI_CS, SPI_SCK, SPI_MOSI, SPI_MISO, &accel_z, 2);
        if (ret < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            gpioTerminate();
            return 1;
        }

        // Convert data to degrees and g
        gyro_x = (gyro_x << 8) | gyro_y;
        gyro_z = (gyro_z << 8) | gyro_x;
        accel_x = (accel_x << 8) | accel_y;
        accel_z = (accel_z << 8) | accel_x;

        // Print data
        printf("gyro_x: %.2f deg/s, gyro_y: %.2f deg/s, gyro_z: %.2f deg/s, accel_x: %.2f g, accel_y: %.2f g, accel_z: %.2f g\n",
               (gyro_x * ADIS16448_GYRO_SCALE) / 65536.0, (gyro_y * ADIS16448_GYRO_SCALE) / 65536.0, (gyro_z * ADIS16448_GYRO_SCALE) / 65536.0,
               (accel_x * ADIS16448_ACCL_SCALE) / 65536.0, (accel_y * ADIS16448_ACCL_SCALE) / 65536.0, (accel_z * ADIS16448_ACCL_SCALE) / 65536.0);

        // Sleep for 100 ms
        sleep(0.1);
    }

    // Clean up
    gpioTerminate();
    return 0;
}

