        ret = spiTransfer(SPI_CS, SPI_SCK, SPI_MOSI, SPI_MISO, &read_cmd, 1);
        if (ret < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            gpioTerminate();
            return 1;
        }

        // Wait for 40 microseconds
        usleep(40 * 1000);

        // Send dummy 0x0000
        dummy = 0x0000;
        ret = spiTransfer(SPI_CS, SPI_SCK, SPI_MOSI, SPI_MISO, &dummy, 1);
        if (ret < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            gpioTerminate();
            return 1;
        }

        // Read gyroscope and accelerometer data
        ret = spiTransfer(SPI_CS, SPI_SCK, SPI_MOSI, SPI_MISO, &gyro_x, 2);
        if (ret < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            gpioTerminate();
            return 1;
        }
        ret = spiTransfer(SPI_CS, SPI_SCK, SPI_MOSI, SPI_MISO, &gyro_y, 2);
        if (ret < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            gpioTerminate();
            return 1;
        }
        ret = spiTransfer(SPI_CS, SPI_SCK, SPI_MOSI, SPI_MISO, &gyro_z, 2);
        if (ret < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            gpioTerminate();
            return 1;
        }
        ret = spiTransfer(SPI_CS, SPI_SCK, SPI_MOSI, SPI_MISO, &accel_x, 2);
        if (ret < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            gpioTerminate();
            return 1;
        }
        ret = spiTransfer(SPI_CS, SPI_SCK, SPI_MOSI, SPI_MISO, &accel_y, 2);
        if (ret < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            gpioTerminate();
            return 1;
        }
        ret = spiTransfer(SPI_CS, SPI_SCK, SPI_MOSI, SPI_MISO, &accel_z, 2);
        if (ret < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            gpioTerminate();
            return 1;
        }

        // Convert data to degrees and g
        gyro_x = (gyro_x << 8) | gyro_y;
        gyro_z = (gyro_z << 8) | gyro_x;
        accel_x = (accel_x << 8) | accel_y;
        accel_z = (accel_z << 8) | accel_x;

        // Print data
        printf("gyro_x: %.2f deg/s, gyro_y: %.2f deg/s, gyro_z: %.2f deg/s, accel_x: %.2f g, accel_y: %.2f g, accel_z: %.2f g\n",
               (gyro_x * ADIS16448_GYRO_SCALE) / 65536.0, (gyro_y * ADIS16448_GYRO_SCALE) / 65536.0, (gyro_z * ADIS16448_GYRO_SCALE) / 65536.0,
               (accel_x * ADIS16448_ACCL_SCALE) / 65536.0, (accel_y * ADIS16448_ACCL_SCALE) / 65536.0, (accel_z * ADIS16448_ACCL_SCALE) / 65536.0);

        // Sleep for 100 ms
        sleep(0.1);
    }

    // Clean up
    gpioTerminate();
    return 0;
}
