#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

#define I2C_ADDRESS 0x53
#define I2C_ADDRESS_CHECK 0x00
#define LED_GPIO 17
#define LOG_FILE "impact_log.txt"

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open log file
    int log_fd = open(LOG_FILE, O_RDWR | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set up I2C
    int i2c_fd = i2cOpen(I2C_ADDRESS, 0, 1000);
    if (i2c_fd < 0) {
        perror("i2cOpen");
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Check device ID
    uint8_t device_id;
    if (i2cRead(i2c_fd, I2C_ADDRESS, I2C_ADDRESS_CHECK, 1, &device_id) < 0) {
        perror("i2cRead");
        close(i2c_fd);
        close(log_fd);
        gpioTerminate();
        return 1;
    }
    if (device_id != 0xE5) {
        printf("Invalid device ID 0x%02x\n", device_id);
        close(i2c_fd);
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Set up GPIO
    if (gpioMode(LED_GPIO, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        close(i2c_fd);
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Set up I2C
    if (i2cWrite(i2c_fd, I2C_ADDRESS, 0x31, 1) < 0) {
        perror("i2cWrite");
        close(i2c_fd);
        close(log_fd);
        gpioTerminate();
        return 1;
    }
    if (i2cWrite(i2c_fd, I2C_ADDRESS, 0x00, 1) < 0) {
        perror("i2cWrite");
        close(i2c_fd);
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read acceleration data
        uint8_t data[6];
        if (i2cRead(i2c_fd, I2C_ADDRESS, 0x32, 6, data) < 0) {
            perror("i2cRead");
            close(i2c_fd);
            close(log_fd);
            gpioTerminate();
            return 1;
        }

        // Calculate acceleration magnitude
        float x = (data[0] * 2.0f / 16384.0f);
        float y = (data[1] * 2.0f / 16384.0f);
        float z = (data[2] * 2.0f / 16384.0f);
        float magnitude = sqrt(x * x + y * y + z * z);

        // Check for impact
        if (magnitude > 2.5f) {
            gpioWrite(LED_GPIO, 1);
            printf("Impact detected at %f g, X: %f, Y: %f, Z: %f\n", magnitude, x, y, z);
            FILE *log_file = fopen(LOG_FILE, "a");
            if (log_file == NULL) {
                perror("fopen");
                gpioWrite(LED_GPIO, 0);
                continue;
            }
            fprintf(log_file, "%f %f %f %f\n", magnitude, x, y, z);
            fclose(log_file);
            sleep(0.5);
            gpioWrite(LED_GPIO, 0);
        }

        // Sleep for 10 ms
        usleep(10000);
    }

    // Clean up
    close(i2c_fd);
    close(log_fd);
    gpioTerminate();
    return 0;
}

