#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <termios.h>
#include <unistd.h>

#define I2C_ADDRESS 0x68
#define I2C Bus 1
#define WHO_AM_I 0x75
#define ACCEL_CONFIG 0x00
#define GYRO_CONFIG 0x00
#define ACCEL_OFFSET 0x3B
#define GYRO_OFFSET 0x43
#define CSV_FILE "imu_log.csv"

int main(int argc, char **argv) {
    int i2c_fd;
    int pigpio_fd;
    struct termios oldt, newt;
    struct sigaction sa;
    FILE *csv_file;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C
    if ((i2c_fd = i2cOpen(I2C Bus, I2C_ADDRESS)) < 0) {
        perror("i2cOpen");
        return 1;
    }

    // Set PWR_MGMT_1 to wake up the device
    if (i2cWrite(i2c_fd, PWR_MGMT_1, 0x00) < 0) {
        perror("i2cWrite");
        return 1;
    }

    // Set ACCEL_CONFIG to +-2g
    if (i2cWrite(i2c_fd, ACCEL_CONFIG, 0x00) < 0) {
        perror("i2cWrite");
        return 1;
    }

    // Set GYRO_CONFIG to +-250 dps
    if (i2cWrite(i2c_fd, GYRO_CONFIG, 0x00) < 0) {
        perror("i2cWrite");
        return 1;
    }

    // Verify the sensor is present
    if (i2cRead(i2c_fd, WHO_AM_I, 1) < 0) {
        perror("i2cRead");
        return 1;
    }
    if (i2cRead(i2c_fd, WHO_AM_I, 1) != 0x12) {
        fprintf(stderr, "Unexpected WHO_AM_I value 0x%02x\n", i2cRead(i2c_fd, WHO_AM_I, 1));
        return 1;
    }

    // Open CSV file
    if ((csv_file = fopen(CSV_FILE, "w")) == NULL) {
        perror("fopen");
        return 1;
    }

    // Set up signal handler for SIGINT
    sa.sa_handler = sigpipe;
    sigemptyset(&sa);
    sigaddsignal(SIGINT, &sa);

    while (1) {
        // Read accelerometer data
        if (i2cReadI2CBlockData(i2c_fd, ACCEL_OFFSET, 6, NULL, 6) < 0) {
            perror("i2cReadI2CBlockData");
            continue;
        }
        int accl[6];
        memcpy(accl, i2cReadBuffer, 6);
        double ax = (accl[0] * 16384.0 / 1024.0) / 2.0;
        double ay = (accl[1] * 16384.0 / 1024.0) / 2.0;
        double az = (accl[2] * 16384.0 / 1024.0) / 2.0;
        fprintf(csv_file, "%f,%f,%f\n", time(NULL), ax, ay);

        // Read gyroscope data
        if (i2cReadI2CBlockData(i2c_fd, GYRO_OFFSET, 6, NULL, 6) < 0) {
            perror("i2cReadI2CBlockData");
            continue;
        }
        int grr[6];
        memcpy(grr, i2cReadBuffer, 6);
        double gx = (grr[0] * 131.0 / 1024.0);
        double gy = (grr[1] * 131.0 / 1024.0);
        double gz = (grr[2] * 131.0 / 1024.0);
        fprintf(csv_file, "%f,%f,%f\n", time(NULL), gx, gy);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    if (i2cClose(i2c_fd) < 0) {
        perror("i2cClose");
    }
    if (gpioTerminate() < 0) {
        perror("gpioTerminate");
    }
    if (fclose(csv_file) < 0) {
        perror("fclose");
    }
    return 0;
}

