#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <sys/time.h>

#define I2C_ADDRESS 0x35
#define I2C_REGISTER_X 0x10
#define I2C_REGISTER_Y 0x11
#define I2C_REGISTER_Z 0x12
#define I2C_REGISTER_SIZE 3

int main() {
    // Initialize signal handler for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Open I2C file descriptor
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    // Set I2C address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
        perror("ioctl");
        return 1;
    }

    // Open CSV file for writing
    char filename[] = "magnetic_field_log.csv";
    struct stat sb;
    if (fstat(filename, &sb) == -1) {
        if (errno != ENOENT) {
            perror("fstat");
            return 1;
        }
    }
    if (fopen(filename, "w") == NULL) {
        perror("fopen");
        return 1;
    }

    // Write CSV header row
    fprintf(stderr, "Timestamp,X,Y,Z\n");
    fflush(stderr);

    // Main loop
    struct timeval tv;
    while (1) {
        gettimeofday(&tv, NULL);
        uint16_t x, y, z;
        if (ioctl(fd, I2C_READ, &x) == -1) {
            perror("ioctl");
            continue;
        }
        if (ioctl(fd, I2C_READ, &y) == -1) {
            perror("ioctl");
            continue;
        }
        if (ioctl(fd, I2C_READ, &z) == -1) {
            perror("ioctl");
            continue;
        }

        // Convert 16-bit values to 32-bit values
        x = (x << 8) | (x >> 8);
        y = (y << 8) | (y >> 8);
        z = (z << 8) | (z >> 8);

        // Write data to CSV file
        fprintf(stderr, "%ld,%d,%d,%d\n", tv.tv_sec, x, y, z);
        fflush(stderr);

        // Sleep for 1 second
        sleep(1);
    }

    // Close I2C file descriptor and CSV file
    if (close(fd) == -1) {
        perror("close");
        return 1;
    }
    if (fclose(stdin) == -1) {
        perror("fclose");
        return 1;
    }
    if (remove(filename) == -1) {
        perror("remove");
        return 1;
    }

    return 0;
}

void sigint_handler(int sig) {
    // Close I2C file descriptor
    close(STDIN_FILENO);

    // Close CSV file
    fclose(stdin);

    // Exit
    exit(0);
}

