#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <sys/statvfs.h>

#define I2C_ADDRESS 0x6A
#define I2C_SDA GPIO2
#define I2C_SCL GPIO3
#define I2C_FREQ 104
#define FREEFALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 2.5
#define FREEFALL_WINDOW 1000 // 1 second in milliseconds
#define BUFFER_SIZE 100

// Define the struct for the IMU data
typedef struct {
    float ax, ay, az;
    float gx, gy, gz;
} imu_data;

// Define the state machine states
enum state {
    IDLE,
    FREEFALL,
    IMPACT
};

// Define the state machine functions
void idle(void);
void freefall(void);
void impact(void);

// Define the I2C functions
void i2c_init(void);
void i2c_read(void);
void i2c_write(uint8_t reg, uint8_t value);
void i2c_check_error(void);

// Define the main function
int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up I2C pins
    if (gpioSetMode(I2C_SDA, PI_INPUT) < 0) {
        perror("gpioSetMode");
        return 1;
    }
    if (gpioSetMode(I2C_SCL, PI_INPUT) < 0) {
        perror("gpioSetMode");
        return 1;
    }
    if (gpioPullUpDowntime(I2C_SDA, PI_HIGH) < 0) {
        perror("gpioPullUpDowntime");
        return 1;
    }
    if (gpioPullUpDowntime(I2C_SCL, PI_HIGH) < 0) {
        perror("gpioPullUpDowntime");
        return 1;
    }

    // Initialize I2C
    i2c_init();

    // Open the log file
    int log_fd = open("motion_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        return 1;
    }

    // Set up the state machine
    enum state state = IDLE;

    // Main loop
    while (1) {
        // Read IMU data
        imu_data imu;
        if (i2c_read(&imu) < 0) {
            i2c_check_error();
            continue;
        }

        // Check WHO_AM_I
        if (imu.ax == 0x00 && imu.ay == 0x00 && imu.az == 0x00 && imu.gx == 0x00 && imu.gy == 0x00 && imu.gz == 0x00) {
            printf("Sensor absent\n");
            continue;
        }

        // Update state machine
        if (state == IDLE) {
            if (imu.ax < -FREEFALL_THRESHOLD && imu.ay < -FREEFALL_THRESHOLD && imu.az < -FREEFALL_THRESHOLD) {
                state = FREEFALL;
            }
        } else if (state == FREEFALL) {
            if (imu.ax > IMPACT_THRESHOLD || imu.ay > IMPACT_THRESHOLD || imu.az > IMPACT_THRESHOLD) {
                state = IMPACT;
            } else if (time(NULL) - state_time > FREEFALL_WINDOW) {
                state = IDLE;
            }
        } else if (state == IMPACT) {
            state = IDLE;
        }

        // Log data
        if (state != IDLE) {
            time_t now = time(NULL);
            struct tm *time_info = localtime(&now);
            char log_line[256];
            sprintf(log_line, "%d,%d,%d,%d,%d,%d,%d,%d\n",
                    state, imu.ax, imu.ay, imu.az, imu.gx, imu.gy, imu.gz, now);
            write(log_fd, log_line, strlen(log_line));
        }

        // Update state time
        state_time = time(NULL);
    }

    // Clean up
    i2c_close();
    gpioCleanUp();
    close(log_fd);

    return 0;
}

// Define the I2C functions
void i2c_init(void) {
    // Initialize I2C
    if (gpioMode(I2C_SDA, PI_OUTPUT) < 0) {
        perror("gpioMode");
        return;
    }
    if (gpioMode(I2C_SCL, PI_OUTPUT) < 0) {
        perror("gpioMode");
        return;
    }
    if (gpioPullUpDowntime(I2C_SDA, PI_HIGH) < 0) {
        perror("gpioPullUpDowntime");
        return;
    }
    if (gpioPullUpDowntime(I2C_SCL, PI_HIGH) < 0) {
        perror("gpioPullUpDowntime");
        return;
    }
}

void i2c_read(imu_data *imu) {
    // Send start condition
    if (i2cWrite(I2C_ADDRESS, 0x00) < 0) {
        i2c_check_error();
        return;
    }

    // Read data
    if (i2cRead(I2C_ADDRESS, 0x00, 6, imu) < 0) {
        i2c_check_error();
        return;
    }

    // Send stop condition
    if (i2cWrite(I2C_ADDRESS, 0x00) < 0) {
        i2c_check_error();
        return;
    }
}

void i2c_write(uint8_t reg, uint8_t value) {
    // Send start condition
    if (i2cWrite(I2C_ADDRESS, reg) < 0) {
        i2c_check_error();
        return;
    }

    // Write data
    if (i2cWrite(I2C_ADDRESS, value) < 0) {
        i2c_check_error();
        return;
    }

    // Send stop condition
    if (i2cWrite(I2C_ADDRESS, 0x00) < 0) {
        i2c_check_error();
        return;
    }
}

void i2c_check_error(void) {
    // Check for I2C errors
    if (i2cGetError() != 0) {
        printf("I2C error\n");
        return;
    }
}

// Define the signal handlers
void sigint_handler(int sig) {
    // Clean up
    i2c_close();
    gpioCleanUp();
    close(log_fd);
    exit(0);
}

void sigterm_handler(int sig) {
    // Clean up
    i2c_close();
    gpioCleanUp();
    close(log_fd);
    exit(0);
}

