#include <unistd.h>
#include <signal.h>

#define SPI_MODE SPI_MODE_3
#define SPI_SPEED 1000000
#define SPI_CS 8
#define SPI_CS_PIN GPIO_PIN_8
#define SPI_CS_GPIO GPIO_NUM_8
#define WHO_AM_I 0x3F5A
#define X_GYRO_OUT 0x14
#define GYRO_SCALE 0.0305

int main(int argc, char **argv) {
    int spi_fd, gyro_fd;
    pigpio *gpio;
    FILE *log_file;

    // Initialize pigpio
    if (gpio = pigpio_init()) {
        printf("pigpio initialization failed\n");
        return 1;
    }

    // Open SPI file
    log_file = fopen("gyro_log.csv", "w");
    if (!log_file) {
        printf("Failed to open log file\n");
        pigpio_close(gpio);
        return 1;
    }

    // Write CSV header
    fprintf(log_file, "timestamp,gyro_x,gyro_y,gyro_z\n");

    // Open SPI interface
    if ((spi_fd = spi_open(gpio, SPI_CS_PIN, SPI_MODE, SPI_SPEED)) < 0) {
        printf("SPI open failed\n");
        pigpio_close(gpio);
        fclose(log_file);
        return 1;
    }

    // Set up SPI mode
    if (spi_set_mode(spi_fd, SPI_MODE_3) < 0) {
        printf("SPI mode set failed\n");
        spi_close(spi_fd);
        pigpio_close(gpio);
        fclose(log_file);
        return 1;
    }

    // Set SPI clock polarity and phase
    if (spi_set_bits(spi_fd, SPI_CPOL, 1) < 0) {
        printf("SPI clock polarity set failed\n");
        spi_close(spi_fd);
        pigpio_close(gpio);
        fclose(log_file);
        return 1;
    }
    if (spi_set_bits(spi_fd, SPI_CPHA, 1) < 0) {
        printf("SPI clock phase set failed\n");
        spi_close(spi_fd);
        pigpio_close(gpio);
        fclose(log_file);
        return 1;
    }

    // Write WHO_AM_I register
    if (spi_write(spi_fd, WHO_AM_I, 0x80) < 0) {
        printf("WHO_AM_I write failed\n");
        spi_close(spi_fd);
        pigpio_close(gpio);
        fclose(log_file);
        return 1;
    }

    // Read X_GYRO_OUT register
    uint16_t gyro_value;
    while (1) {
        if (spi_read(spi_fd, &gyro_value, 2) < 0) {
            printf("SPI read failed\n");
            spi_close(spi_fd);
            pigpio_close(gpio);
            fclose(log_file);
            return 1;
        }

        // Scale gyro value
        gyro_value >>= 1;
        gyro_value = (gyro_value & 0x7FFF) * GYRO_SCALE;

        // Log gyro reading
        time_t now = time(NULL);
        fprintf(log_file, "%.3f,%.3f,%.3f\n", now, gyro_value, 0.0, 0.0);

        // Wait 10 ms
        usleep(10000);
    }

    // Close SPI interface
    spi_close(spi_fd);

    // Close pigpio
    pigpio_close(gpio);

    // Close log file
    fclose(log_file);

    return 0;
}

