#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <time.h>

#define I2C_ADDRESS 0x69
#define I2C Bus 1
#define CTRL_REG1 0x00
#define CTRL_REG4 0x04
#define OUT_X_L 0x28
#define WHO_AM_I 0x0F
#define SENSITIVITY 8.75
#define FS_RANGE 250
#define FS_RANGE_MAX 114.285
#define SAMPLING_INTERVAL 10
#define MAX_RETRIES 3

int main(int argc, char **argv) {
    int i2c_fd;
    int retries = 0;
    int gyro_fd;
    unsigned char gyro_data[6];
    struct timespec timestamp;
    struct sigaction sa;
    struct sigaction old_sa;

    // Initialize signal handling
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, &old_sa) < 0) {
        perror("sigaction");
        return 1;
    }

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open");
        return 1;
    }

    // Configure I2C bus
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        return 1;
    }

    // Wait for WHO_AM_I register to be ready
    while (1) {
        if (read(i2c_fd, &gyro_data[0], 1) < 0) {
            perror("read");
            close(i2c_fd);
            return 1;
        }
        if (gyro_data[0] == WHO_AM_I) {
            break;
        }
        retries++;
        if (retries >= MAX_RETRIES) {
            perror("WHO_AM_I not found");
            close(i2c_fd);
            return 1;
        }
    }

    // Configure sensor
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        return 1;
    }
    if (write(i2c_fd, &CTRL_REG1, 1) < 0) {
        perror("write");
        close(i2c_fd);
        return 1;
    }
    if (write(i2c_fd, &CTRL_REG4, 1) < 0) {
        perror("write");
        close(i2c_fd);
        return 1;
    }

    // Open file for writing
    gyro_fd = open("gyro_log.csv", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (gyro_fd < 0) {
        perror("open");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        // Read data
        if (read(i2c_fd, gyro_data, 6) < 0) {
            perror("read");
            close(i2c_fd);
            close(gyro_fd);
            gpioTerminate();
            return 1;
        }

        // Convert raw values to degrees per second
        gyro_data[0] = (gyro_data[0] << 8) | gyro_data[1];
        gyro_data[1] = (gyro_data[2] << 8) | gyro_data[3];
        gyro_data[2] = (gyro_data[4] << 8) | gyro_data[5];
        double x = (gyro_data[0] * SENSITIVITY) / FS_RANGE_MAX;
        double y = (gyro_data[1] * SENSITIVITY) / FS_RANGE_MAX;
        double z = (gyro_data[2] * SENSITIVITY) / FS_RANGE_MAX;

        // Log data
        clock_gettime(CLOCK_MONOTONIC, &timestamp);
        fprintf(gyro_fd, "%llu,%f,%f,%f\n", timestamp.tv_sec, x, y, z);

        // Sleep for sampling interval
        usleep(SAMPLING_INTERVAL * 1000);
    }

    // Close file and I2C handle
    close(gyro_fd);
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

void sigint_handler(int sig) {
    close(gyro_fd);
    close(i2c_fd);
    gpioTerminate();
    exit(0);
}

