#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>

#define LOG_FILE "flame_events.log"
#define GPIO_PIN 17
#define POLL_INTERVAL 500

int main() {
    int gpio_fd = -1;
    int log_fd = -1;
    int pin = GPIO_PIN;
    int state = 0;
    int poll_result = 0;
    int sig_int = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_APPEND);
    if (log_fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Enable internal pull-up resistor on GPIO17
    if (gpioMode(pin, GPIO_MODE_INPUT) < 0) {
        perror("gpioMode");
        close(log_fd);
        gpioTerminate();
        return 1;
    }
    if (gpioPullUp(pin, GPIO_PULLUP_DISABLE) < 0) {
        perror("gpioPullUp");
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    sig_int = signal(SIGINT, SIG_IGN);
    if (sig_int < 0) {
        perror("signal");
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Poll sensor
        poll_result = gpioRead(pin);
        if (poll_result == PI_BAD_GPIO) {
            syslog(LOG_ERR, "gpioRead returned PI_BAD_GPIO");
            continue;
        }

        // Log result
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        if (poll_result == 0) {
            syslog(LOG_INFO, "%s - Flame detected: YES", timestamp);
        } else {
            syslog(LOG_INFO, "%s - Flame detected: NO", timestamp);
        }
        fflush(log_fd);

        // Check for flame detection
        if (poll_result == 0) {
            printf("FLAME DETECTED!\n");
        }
    }

    // Clean up
    if (log_fd >= 0) {
        close(log_fd);
    }
    gpioTerminate();
    return 0;
}

