#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <sys/mman.h>
#include <sys/mount.h>

#define I2C_ADDRESS 0x53
#define I2C_BUS "/dev/i2c-1"
#define CSV_FILE "vibration_log.csv"
#define CSV_HEADER "Timestamp,X,Y,Z\n"

int main() {
    // Install SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Open I2C file descriptor
    int fd = open(I2C_BUS, O_RDWR);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    // Set I2C bus parameters
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    // Open CSV file for writing
    int csv_fd = open(CSV_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (csv_fd == -1) {
        perror("open");
        close(fd);
        return 1;
    }

    // Map I2C memory
    void* i2c_map = mmap(NULL, 256, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (i2c_map == MAP_FAILED) {
        perror("mmap");
        close(fd);
        close(csv_fd);
        return 1;
    }

    // Define I2C register addresses
    uint8_t reg_x_lsb = 0x28;
    uint8_t reg_x_msb = 0x29;
    uint8_t reg_y_lsb = 0x2A;
    uint8_t reg_y_msb = 0x2B;
    uint8_t reg_z_lsb = 0x2C;
    uint8_t reg_z_msb = 0x2D;

    // Main loop
    while (true) {
        // Read I2C registers
        uint8_t x_lsb = i2c_map[reg_x_lsb];
        uint8_t x_msb = i2c_map[reg_x_msb];
        uint8_t y_lsb = i2c_map[reg_y_lsb];
        uint8_t y_msb = i2c_map[reg_y_msb];
        uint8_t z_lsb = i2c_map[reg_z_lsb];
        uint8_t z_msb = i2c_map[reg_z_msb];

        // Check for sensor-absent paths
        if (x_msb == 0xFF || y_msb == 0xFF || z_msb == 0xFF) {
            printf("Sensor absent\n");
            continue;
        }

        // Combine acceleration values
        int16_t x_accel = (x_msb << 8) | x_lsb;
        int16_t y_accel = (y_msb << 8) | y_lsb;
        int16_t z_accel = (z_msb << 8) | z_lsb;

        // Log acceleration data
        time_t now = time(NULL);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S%z", localtime(&now));
        fprintf(csv_fd, "%s,%d,%d,%d\n", timestamp, x_accel, y_accel, z_accel);

        // Check for bus errors
        if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
            perror("ioctl");
            continue;
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Close I2C file descriptor and CSV file
    close(fd);
    close(csv_fd);

    // Unmap I2C memory
    munmap(i2c_map, 256);

    return 0;
}

void sigint_handler(int sig) {
    // Close I2C file descriptor and CSV file
    close(0);
    close(1);
    close(2);

    // Exit
    exit(0);
}

