        if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
            perror("ioctl");
            continue;
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Close I2C file descriptor and CSV file
    close(fd);
    close(csv_fd);

    // Unmap I2C memory
    munmap(i2c_map, 256);

    return 0;
}

void sigint_handler(int sig) {
    // Close I2C file descriptor and CSV file
    close(0);
    close(1);
    close(2);

    // Exit
    exit(0);
}
