#include <math.h>
#include <stdint.h>
#include <stdbool.h>
#include <libgpiod.h>

#define I2C_ADDRESS 0x1D
#define I2C_FILE "/dev/i2c-1"
#define LOG_FILE "fall_log.txt"

int main() {
    int fd;
    struct i2c_client *client;
    struct i2c_dev *dev;
    struct i2c_msg msg;
    struct i2c_msg msg2;
    uint8_t buf[6];
    int ret;
    int log_fd = -1;
    int log_file = -1;
    int i;

    // Install SIGINT and SIGTERM handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open I2C file descriptor
    fd = open(I2C_FILE, O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd < 0) {
        perror("open");
        close(fd);
        return 1;
    }

    // Initialize I2C client
    client = i2c_new_client(fd, I2C_ADDRESS, NULL, NULL);
    if (!client) {
        perror("i2c_new_client");
        close(fd);
        close(log_fd);
        return 1;
    }

    // Initialize I2C device
    dev = i2c_get_clientdata(client);
    if (!dev) {
        perror("i2c_get_clientdata");
        i2c_release_client(client);
        close(fd);
        close(log_fd);
        return 1;
    }

    // Verify sensor identity
    msg.msg_type = I2C_MSG_READ;
    msg.msg_flags = I2C_MREQ;
    msg.msg_addr = 0x0D;
    msg.msg_len = 1;
    ret = i2c_master_send(client, &msg);
    if (ret < 0) {
        perror("i2c_master_send");
        i2c_release_client(client);
        close(fd);
        close(log_fd);
        return 1;
    }
    msg.msg_len = 1;
    ret = i2c_master_recv(client, &msg);
    if (ret < 0) {
        perror("i2c_master_recv");
        i2c_release_client(client);
        close(fd);
        close(log_fd);
        return 1;
    }
    if (msg.msg_len != 1 || msg.buf[0] != 0x2A) {
        fprintf(stderr, "Invalid sensor identity\n");
        i2c_release_client(client);
        close(fd);
        close(log_fd);
        return 1;
    }

    // Initialize sensor
    msg.msg_type = I2C_MSG_WRITE;
    msg.msg_flags = I2C_MREQ;
    msg.msg_addr = 0x2A;
    msg.msg_len = 1;
    msg.buf[0] = 0x00;
    ret = i2c_master_send(client, &msg);
    if (ret < 0) {
        perror("i2c_master_send");
        i2c_release_client(client);
        close(fd);
        close(log_fd);
        return 1;
    }
    msg.msg_len = 1;
    msg.buf[0] = 0x00;
    ret = i2c_master_send(client, &msg);
    if (ret < 0) {
        perror("i2c_master_send");
        i2c_release_client(client);
        close(fd);
        close(log_fd);
        return 1;
    }
    msg.msg_len = 1;
    msg.buf[0] = 0x10;
    ret = i2c_master_send(client, &msg);
    if (ret < 0) {
        perror("i2c_master_send");
        i2c_release_client(client);
        close(fd);
        close(log_fd);
        return 1;
    }
    msg.msg_len = 1;
    msg.buf[0] = 0x01;
    ret = i2c_master_send(client, &msg);
    if (ret < 0) {
        perror("i2c_master_send");
        i2c_release_client(client);
        close(fd);
        close(log_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Poll accelerometer
        msg.msg_type = I2C_MSG_READ;
        msg.msg_flags = I2C_MREQ;
        msg.msg_addr = 0x01;
        msg.msg_len = 6;
        ret = i2c_master_send(client, &msg);
        if (ret < 0) {
            perror("i2c_master_send");
            continue;
        }
        ret = i2c_master_recv(client, &msg);
        if (ret < 0) {
            perror("i2c_master_recv");
            continue;
        }
        for (i = 0; i < 6; i++) {
            buf[i] = msg.buf[i];
        }
        for (i = 0; i < 6; i++) {
            buf[i] = (buf[i] << 4) | (buf[i + 1];
            buf[i + 1] = (buf[i + 1] >> 4);
        }
        for (i = 0; i < 3; i++) {
            buf[i] = -buf[i];
        }
        float x = (buf[0] + 0.5) / 2048.0;
        float y = (buf[1] + 0.5) / 2048.0;
        float z = (buf[2] + 0.5) / 2048.0;
        float angle = atan2(y, sqrt(x * x + z * z));
        if (abs(angle) > M_PI / 4) {
            fprintf(log_fd, "%d %d %d %f\n", buf[0], buf[1], buf[2], angle);
        }
        usleep(10);
    }

    // Clean up
    i2c_release_client(client);
    close(fd);
    close(log_fd);
    return 0;
}

void sigint_handler(int sig) {
    i2c_release_client(client);
    close(fd);
    close(log_fd);
    exit(0);
}

void sigterm_handler(int sig) {
    i2c_release_client(client);
    close(fd);
    close(log_fd);
    exit(0);
}

