#include <unistd.h>
#include <sys/types.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <termios.h>
#include <unistd.h>

#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_CS 8
#define ADXL354B_RESET 0x1F
#define ADXL354B_POWER_CTL 0x2D
#define ADXL354B_STATUS 0x04
#define ADXL354B_XDATA 0x08
#define ADXL354B_YDATA 0x0B
#define ADXL354B_ZDATA 0x0E
#define ADXL354B_PARTID 0x01
#define ADXL354B_MEASUREMENT_MODE 0x00
#define ADXL354B_RUN 0x80
#define ADXL354B_STABLE 0x40
#define ADXL354B_RESET_VALUE 0x52

int main(int argc, char **argv) {
    int spi_fd;
    pigpio *gpio;
    struct termios oldt, newt;
    struct sigaction sa;
    FILE *log_file;

    // Initialize pigpio
    gpio = pigpio_init();
    if (gpio == -1) {
        perror("pigpio_init");
        return 1;
    }

    // Set up terminal for logging
    tcgetattr(STDIN_FILENO, &oldt);
    newt = oldt;
    newt.c_lflag &= ~ICANON;
    newt.c_lflag &= ~ECHO;
    tcsetattr(STDIN_FILENO, TCSANOW, &newt);

    // Open log file
    log_file = fopen("vibration_log.txt", "w");
    if (log_file == NULL) {
        perror("fopen");
        return 1;
    }

    // Set up SPI
    spi_fd = spi_open(gpio, SPI_CS, SPI_MODE, SPI_SPEED);
    if (spi_fd == -1) {
        perror("spi_open");
        return 1;
    }

    // Reset ADXL354B
    if (spi_write(spi_fd, ADXL354B_RESET_VALUE, 1) != 1) {
        perror("spi_write");
        return 1;
    }
    usleep(1000);
    if (spi_write(spi_fd, ADXL354B_RESET_VALUE, 1) != 1) {
        perror("spi_write");
        return 1;
    }

    // Set measurement mode
    if (spi_write(spi_fd, ADXL354B_MEASUREMENT_MODE, 1) != 1) {
        perror("spi_write");
        return 1;
    }
    usleep(1000);
    if (spi_write(spi_fd, ADXL354B_RUN, 1) != 1) {
        perror("spi_write");
        return 1;
