#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/spi/spi.h>
#include <linux/spi/spi.h>
#include <libgpiod/libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CS_PIN "gpio-8"
#define MSC_CTRL 0x24
#define X_REG 0x04
#define Y_REG 0x06
#define Z_REG 0x08
#define SCALE_FACTOR 0.02

int main(int argc, char **argv) {
    int fd, cs_fd, ret;
    struct gpiod_line *line;
    struct gpiod_device *device;
    struct gpiod_device *cs_device;
    struct spidev *spi;
    struct spidev_args args;
    struct spidev_args *args_copy;
    unsigned char msb, data[2];
    int i;

    // Initialize signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    // Open SPI device
    if ((fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        perror("open");
        return 1;
    }

    // Open CS line
    if ((cs_fd = gpiod_open(CS_PIN, GpioDirectionOut, NULL)) < 0) {
        perror("gpiod_open");
        close(fd);
        return 1;
    }

    // Create libgpiod line and device
    if ((line = gpiod_line_create(CS_PIN, GpioDirectionOut, NULL)) < 0) {
        perror("gpiod_line_create");
        gpiod_close(cs_fd);
        close(fd);
        return 1;
    }
    if ((device = gpiod_device_create(line, NULL)) < 0) {
        perror("gpiod_device_create");
        gpiod_line_destroy(line);
        gpiod_close(cs_fd);
        close(fd);
        return 1;
    }

    // Create SPI device
    if ((args = spidev_args_create()) < 0) {
        perror("spidev_args_create");
        gpiod_device_destroy(device);
        gpiod_line_destroy(line);
        gpiod_close(cs_fd);
        close(fd);
        return 1;
    }

    // Set up SPI device
    args->mode = SPI_MODE_3;
    args->bits_per_word = 8;
    args->clock_speed = 1000000;
    args->cs_high = 1;
    args->cs_low = 0;
    args->cs_edge = SPI_CSEdge_RISING;
    args->cs_polarity = SPI_CSEdgeActiveLow;
    if ((ret = spidev_open(fd, &args)) < 0) {
        perror("spidev_open");
        spidev_args_destroy(args);
        gpiod_device_destroy(device);
        gpiod_line_destroy(line);
        gpiod_close(cs_fd);
        close(fd);
        return 1;
    }

    // Set up CS line
    if ((ret = gpiod_line_set_value(line, 0)) < 0) {
        perror("gpiod_line_set_value");
        spidev_close(args);
        gpiod_device_destroy(device);
        gpiod_line_destroy(line);
        gpiod_close(cs_fd);
        close(fd);
        return 1;
    }

    // Enable data ready mode
    if ((ret = ioctl(fd, SPI_IOC_SET_MODE, 0)) < 0) {
        perror("ioctl");
        gpiod_line_set_value(line, 1);
        spidev_close(args);
        gpiod_device_destroy(device);
        gpiod_line_destroy(line);
        gpiod_close(cs_fd);
        close(fd);
        return 1;
    }

    // Create spidev_args_copy
    if ((args_copy = spidev_args_copy(args)) < 0) {
        perror("spidev_args_copy");
        gpiod_line_set_value(line, 1);
        spidev_close(args);
        gpiod_device_destroy(device);
        gpiod_line_destroy(line);
        gpiod_close(cs_fd);
        close(fd);
        return 1;
    }

    // Set up spidev_args_copy
    msb = 0x80;
    if ((ret = spidev_args_set_address(args_copy, msb)) < 0) {
        perror("spidev_args_set_address");
        spidev_args_destroy(args_copy);
        gpiod_line_set_value(line, 1);
        spidev_close(args);
        gpiod_device_destroy(device);
        gpiod_line_destroy(line);
        gpiod_close(cs_fd);
        close(fd);
        return 1;
    }

    // Read X, Y, and Z registers
    while (1) {
        // Read X register
        if ((ret = spidev_read(args_copy, &msb, data, 2)) < 0) {
            perror("spidev_read");
            spidev_args_destroy(args_copy);
            gpiod_line_set_value(line, 1);
            spidev_close(args);
            gpiod_device_destroy(device);
            gpiod_line_destroy(line);
            gpiod_close(cs_fd);
            close(fd);
            return 1;
        }
        if (data[0] & 0x80) {
            // MSB set, read Y and Z registers
            if ((ret = spidev_read(args_copy, &msb, data, 2)) < 0) {
                perror("spidev_read");
                spidev_args_destroy(args_copy);
                gpiod_line_set_value(line, 1);
                spidev_close(args);
                gpiod_device_destroy(device);
                gpiod_line_destroy(line);
                gpiod_close(cs_fd);
                close(fd);
                return 1;
            }
            if (data[1] & 0x80) {
                // MSB set, read Z register
                if ((ret = spidev_read(args_copy, &msb, data, 2)) < 0) {
                    perror("spidev_read");
                    spidev_args_destroy(args_copy);
                    gpiod_line_set_value(line, 1);
                    spidev_close(args);
                    gpiod_device_destroy(device);
                    gpiod_line_destroy(line);
                    gpiod_close(cs_fd);
                    close(fd);
                    return 1;
                }
            }
            // Convert raw values to angular rates
            int x = (data[0] & 0x7F) * SCALE_FACTOR;
            int y = (data[1] & 0x7F) * SCALE_FACTOR;
            int z = (data[2] & 0x7F) * SCALE_FACTOR;
            printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        } else {
            // LSB set, read X and Y registers
            if ((ret = spidev_read(args_copy, &msb, data, 2)) < 0) {
                perror("spidev_read");
                spidev_args_destroy(args_copy);
                gpiod_line_set_value(line, 1);
                spidev_close(args);
                gpiod_device_destroy(device);
                gpiod_line_destroy(line);
                gpiod_close(cs_fd);
                close(fd);
                return 1;
            }
            // Convert raw values to angular rates
            int x = (data[0] * SCALE_FACTOR);
            int y = (data[1] * SCALE_FACTOR);
            printf("X: %d, Y: %d\n", x, y);
        }
        usleep(100000);
    }

    // Clean up
    spidev_args_destroy(args_copy);
    gpiod_line_destroy(line);
    gpiod_device_destroy(device);
    gpiod_close(cs_fd);
    close(fd);
    return 0;
}

