            accel_x += (accel_offset_x + accel[i] * accel_sensitivity);
            accel_y += (accel_offset_y + accel[i + 4] * accel_sensitivity);
            accel_z += (accel_offset_z + accel[i + 8] * accel_sensitivity);
        }

        // Print data
        if (time(NULL) - last_time > 100) {
            last_time = time(NULL);
            printf("%.3f %.3f %.3f %.3f %.3f %.3f %.3f\n", gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
        }
    }

    // Clean up
    i2cClose(i2c_fd);
    gpioTerminate();

    return 0;
}

void sigint_handler(int sig) {
    i2cClose(i2c_fd);
    gpioTerminate();
    exit(0);
