#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>

#define I2C_ADDRESS 0x1D
#define I2C_BUS 1
#define I2C_SDA GPIO2
#define I2C_SCL GPIO3
#define WHO_AM_I 0x0D
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define M_CTRL_REG1 0x5B
#define M_CTRL_REG2 0x5C
#define OUT_X_MSB 0x01

void init_sensor(pigpio *gpio) {
    if (gpio->i2c_open(I2C_BUS, I2C_ADDRESS, 1000) < 0) {
        printf("Failed to open I2C bus\n");
        exit(1);
    }

    if (gpio->i2c_write(I2C_BUS, CTRL_REG1, 0x00) < 0) {
        printf("Failed to write to CTRL_REG1\n");
        gpio->i2c_close(I2C_BUS);
        exit(1);
    }

    if (gpio->i2c_write(I2C_BUS, CTRL_REG2, 0x00) < 0) {
        printf("Failed to write to CTRL_REG2\n");
        gpio->i2c_close(I2C_BUS);
        exit(1);
    }

    if (gpio->i2c_write(I2C_BUS, M_CTRL_REG1, 0x00) < 0) {
        printf("Failed to write to M_CTRL_REG1\n");
        gpio->i2c_close(I2C_BUS);
        exit(1);
    }

    if (gpio->i2c_write(I2C_BUS, M_CTRL_REG2, 0x00) < 0) {
        printf("Failed to write to M_CTRL_REG2\n");
        gpio->i2c_close(I2C_BUS);
        exit(1);
    }

    if (gpio->i2c_read(I2C_BUS, WHO_AM_I, 1) < 0) {
        printf("Failed to read WHO_AM_I register\n");
        gpio->i2c_close(I2C_BUS);
        exit(1);
    }

    if (gpio->i2c_read(I2C_BUS, WHO_AM_I, 1) != 0xC7) {
        printf("Sensor not found\n");
        gpio->i2c_close(I2C_BUS);
        exit(1);
    }

    gpio->i2c_close(I2C_BUS);
}

void read_sensor(pigpio *gpio) {
    if (gpio->i2c_open(I2C_BUS, I2C_ADDRESS, 1000) < 0) {
        printf("Failed to open I2C bus\n");
        exit(1);
    }

    if (gpio->i2c_read(I2C_BUS, OUT_X_MSB, 12) < 0) {
        printf("Failed to read data from sensor\n");
        gpio->i2c_close(I2C_BUS);
        exit(1);
    }

    uint8_t data[12];
    if (gpio->i2c_read(I2C_BUS, OUT_X_MSB, 12, data, 12) < 0) {
        printf("Failed to read data from sensor\n");
        gpio->i2c_close(I2C_BUS);
        exit(1);
    }

    uint16_t x = (data[0] << 14) | data[1];
    uint16_t y = (data[2] << 14) | data[3];
    uint16_t z = (data[4] << 14) | data[5];
    uint16_t mx = (data[6] << 16) | data[7];
    uint16_t my = (data[8] << 16) | data[9];
    uint16_t mz = (data[10] << 16) | data[11];

    printf("X: %d, Y: %d, Z: %d, Mx: %d, My: %d, Mz: %d\n", x, y, z, mx, my, mz);

    gpio->i2c_close(I2C_BUS);
}

void sigint_handler(int sig) {
    gpio_close();
    exit(0);
}

int main() {
    pigpio *gpio = pigpio_init();
    if (gpio == NULL) {
        printf("Failed to initialize pigpio\n");
        exit(1);
    }

    signal(SIGINT, sigint_handler);

    init_sensor(gpio);

    while (1) {
        read_sensor(gpio);
        sleep(0.1);
    }

    gpio_close();
    pigpioTerminate();
    return 0;
}

