#define I2C_ADDRESS 0x53
#define I2C_ADDRESS_MASK 0x03
#define I2C_REG_X 0x32
#define I2C_REG_Y 0x33
#define I2C_REG_Z 0x34
#define I2C_REG_DATA 0x35
#define I2C_REG_STATUS 0x36
#define I2C_REG_THRESHOLD 0x37

#define TILT_THRESHOLD 30.0

struct gpiod_context *ctx;
struct gpiod_device *dev;
struct gpiod_event *event;
struct gpiod_event *tilt_event;
struct gpiod_event *log_event;

void handle_tilt_event(struct gpiod_event *event) {
    double x, y, z;
    int status;

    if (event->type != GPIOD_EVENT_TYPE_VALUE) {
        return;
    }

    status = gpiod_i2c_read(ctx, dev, I2C_ADDRESS, I2C_REG_X, &x);
    if (status != 0) {
        gpiod_event_cancel(event);
        return;
    }

    status = gpiod_i2c_read(ctx, dev, I2C_ADDRESS, I2C_REG_Y, &y);
    if (status != 0) {
        gpiod_event_cancel(event);
        return;
    }

    status = gpiod_i2c_read(ctx, dev, I2C_ADDRESS, I2C_REG_Z, &z);
    if (status != 0) {
        gpiod_event_cancel(event);
        return;
    }

    double tilt_x = atan2(y, x);
    double tilt_y = atan2(z, sqrt(x * x + y * y));
    double tilt_z = atan2(z, sqrt(x * x + y * y));

    if (tilt_x > TILT_THRESHOLD || tilt_y > TILT_THRESHOLD || tilt_z > TILT_THRESHOLD) {
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        char log_message[100];
        sprintf(log_message, "Tilt event detected at %s, x=%f, y=%f, z=%f\n", timestamp, tilt_x, tilt_y, tilt_z);
        gpiod_event_send(log_event, log_message);
    }

    gpiod_event_cancel(event);
}

