// Function to generate a random 6-digit code
uint32_t generate_code() {
    uint32_t code = 0;
    for (int i = 0; i < 6; i++) {
        code = (code << 4) | rand() % 10;
    }
    return code;
}

// Function to handle invalid non-numeric input
void handle_invalid_input() {
    int c;
    while ((c = getchar()) != EOF && !isdigit(c)) {
        // Clear the buffer
        while (c != EOF && !isdigit(c)) {
            c = getchar();
        }
    }
}

// Function to handle SIGINT/SIGTERM signals
void sig_handler(int sig) {
    exit = 1;
}

int main() {
    // Initialize signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Initialize random number generator
    srand(time(NULL));

    // Initialize libgpiod
    if (gpiod_init() != 0) {
        fprintf(stderr, "Error initializing libgpiod: %s\n", gpiod_strerror());
        return 1;
    }

    // Open the chip
    chip = gpiod_chip_open("gpio-17", GpioDirectionOutput, NULL);
    if (chip == NULL) {
        fprintf(stderr, "Error opening chip gpio-17: %s\n", gpiod_strerror());
        gpiod_exit();
        return 1;
    }

    // Open the lines
    line_a = gpiod_line_open(chip, "gpio-17", LineDirectionOutput, NULL);
    if (line_a == NULL) {
        fprintf(stderr, "Error opening line gpio-17: %s\n", gpiod_strerror());
        gpiod_chip_close(chip);
        gpiod_exit();
        return 1;
    }

    line_b = gpiod_line_open(chip, "gpio-27", LineDirectionOutput, NULL);
    if (line_b == NULL) {
        fprintf(stderr, "Error opening line gpio-27: %s\n", gpiod_strerror());
        gpiod_line_close(line_a);
        gpiod_chip_close(chip);
        gpiod_exit();
        return 1;
    }

    // Request the lines
    req_a = gpiod_line_request(chip, line_a, LineRequestActiveHigh, NULL);
    if (req_a == NULL) {
        fprintf(stderr, "Error requesting line gpio-17: %s\n", gpiod_strerror());
        gpiod_line_close(line_b);
        gpiod_chip_close(chip);
        gpiod_exit();
        return 1;
    }

    req_b = gpiod_line_request(chip, line_b, LineRequestActiveHigh, NULL);
    if (req_b == NULL) {
        fprintf(stderr, "Error requesting line gpio-27: %s\n", gpiod_strerror());
        gpiod_line_close(line_a);
        gpiod_line_close(line_b);
        gpiod_chip_close(chip);
        gpiod_exit();
        return 1;
    }

    // Open the log file
    log_file = fopen("access_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_line_close(req_a);
        gpiod_line_close(req_b);
        gpiod_line_close(line_a);
        gpiod_line_close(line_b);
        gpiod_chip_close(chip);
        gpiod_exit();
        return 1;
    }

    // Generate a random code
    uint32_t code = generate_code();
    fprintf(stderr, "Generated code: %08x\n", code);

    // Main loop
    while (!exit) {
        char input[10];
        printf("Enter the code: ");
        fgets(input, sizeof(input), stdin);
        handle_invalid_input();

        // Parse the input
        uint32_t input_code = 0;
        for (int i = 0; i < 6; i++) {
            input_code = (input_code << 4) | (input[i] - '0');
        }

        // Check if the input is valid
        if (input_code == code) {
            // Unlock Door A
            gpiod_line_request_set_active_high(req_a, 1);
            usleep(5000000);
            gpiod_line_request_set_active_high(req_a, 0);

            // Log the successful entry
            fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,000000\n",
                    2023, 1, 1, 12, 30, 0);
            fflush(log_file);

            // Generate a new code
            code = generate_code();
        } else {
            printf("Access denied\n");
        }
    }

    // Clean up
    fclose(log_file);
    gpiod_line_close(req_a);
    gpiod_line_close(req_b);
    gpiod_line_close(line_a);
    gpiod_line_close(line_b);
    gpiod_chip_close(chip);
    gpiod_exit();

    return 0;
}

