#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_ADDRESS 0x23
#define I2C_TIMEOUT 180
#define I2C_READ 0x21
#define I2C_WRITE 0x22
#define I2C_DATA 0x00
#define I2C_REG 0x00

int main(int argc, char *argv[]) {
    int fd;
    struct timespec start_time;
    struct timespec end_time;
    struct timespec interval;
    struct sigaction sa;
    int i;
    unsigned char raw_value[2];
    unsigned char command = I2C_WRITE;
    unsigned char addr = I2C_ADDRESS;
    unsigned char data = I2C_DATA;
    unsigned char reg = I2C_REG;
    unsigned char read_data[2];
    int ret;
    int lux;
    char timestamp[20];

    // Initialize signal handling
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    sigaction(SIGINT, &sa, NULL);

    // Open I2C bus
    fd = pigpio_open(1, PI_MODE PWM, NULL);
    if (fd < 0) {
        perror("pigpio_open");
        return 1;
    }

    // Set I2C clock speed
    ret = pigpio_i2c_set_clock_speed(fd, 400000);
    if (ret < 0) {
        perror("pigpio_i2c_set_clock_speed");
        pigpio_close(fd);
        return 1;
    }

    // Write One-Time High-Resolution Mode 2 command
    ret = pigpio_i2c_write(fd, addr, command, 1, &data);
    if (ret < 0) {
        perror("pigpio_i2c_write");
        pigpio_close(fd);
        return 1;
    }

    // Wait for maximum conversion time
    clock_gettime(CLOCK_MONOTONIC, &start_time);
    while (clock_gettime(CLOCK_MONOTONIC, &end_time).tv_sec - start_time.tv_sec < I2C_TIMEOUT / 1000000) {
        // Read 2 bytes of data
        ret = pigpio_i2c_read(fd, addr, 2, read_data, 2);
        if (ret < 0) {
            perror("pigpio_i2c_read");
            pigpio_close(fd);
            return 1;
        }

        // Calculate illuminance
        lux = (read_data[0] * 5) / 6;

        // Log sensor reading
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&start_time));
        printf("%s, Lux: %u\n", timestamp, lux);

        // Sleep for 5 seconds
        clock_nanosleep(CLOCK_MONOTONIC, 0, 500000000);
    }

    // Close I2C bus
    pigpio_close(fd);

    return 0;
}

void sigint_handler(int sig) {
    printf("\n");
    exit(0);
}

