#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <pigpio.h>
#include <syslog.h>

#define I2C_ADDRESS 0x1E
#define I2C_ADDRESS_MAGNETOMETER 0x1E
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define OUT_X_H_M 0x0A
#define OUT_Y_L_M 0x0C
#define OUT_Y_H_M 0x0E
#define OUT_Z_L_M 0x10
#define OUT_Z_H_M 0x12
#define PWM_PIN 17

int main(int argc, char *argv[]) {
    int i2c_fd, pwm_fd, log_fd;
    struct i2c_file i2c;
    struct pigpio gpio;
    struct sigaction sa;
    int sample_count = 0;
    float z_magnitude = 0.0;
    float z_magnitude_prev = 0.0;
    int pwm_value = 0;

    // Initialize libgpiod
    if (pigpio_init() < 0) {
        perror("pigpio_init");
        return 1;
    }

    // Open I2C file descriptor
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open");
        return 1;
    }

    // Set up I2C interface
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS_MAGNETOMETER) < 0) {
        perror("ioctl");
        close(i2c_fd);
        return 1;
    }

    // Set up PWM interface
    if (gpioInitialise(pwm_fd, PWM_PIN, PI_OUTPUT) < 0) {
        perror("gpioInitialise");
        close(i2c_fd);
        return 1;
    }

    // Set up signal handler for SIGINT and SIGTERM
    sa.sa_handler = sigpipe_handler;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGPIPE);
    sigaddset(&sa.sa_mask, SIGTERM);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        close(i2c_fd);
        gpioTerminate(pwm_fd);
        return 1;
    }

    while (1) {
        // Read 6 bytes of data from magnetometer
        if (ioctl(i2c_fd, I2C_SMBUS_WRITE_byte_data, I2C_ADDRESS_MAGNETOMETER, CTRL_REG1_M, 0x18) < 0) {
            perror("ioctl");
            continue;
        }
        if (ioctl(i2c_fd, I2C_SMBUS_READ_block_data, I2C_ADDRESS_MAGNETOMETER, OUT_X_L_M, 6) < 0) {
            perror("ioctl");
            continue;
        }

        // Extract X, Y, Z magnetic field data
        unsigned char x_l_m = (unsigned char)((i2c_fd) >> 8);
        unsigned char x_h_m = (unsigned char)((i2c_fd) & 0xFF);
        unsigned char y_l_m = (unsigned char)((i2c_fd) >> 16);
        unsigned char y_h_m = (unsigned char)((i2c_fd) & 0xFF00);
        unsigned char z_l_m = (unsigned char)((i2c_fd) >> 24);
        unsigned char z_h_m = (unsigned char)((i2c_fd) & 0xFF0000);

        // Compute Z-axis magnitude
        z_magnitude = sqrt((z_l_m * 0.000061024) + (z_h_m * 0.000061024) + (z_magnitude_prev * 0.000061024));
        z_magnitude_prev = z_magnitude;

        // Adjust PWM value based on Z-axis magnitude
        pwm_value = (int)(255 * (z_magnitude / 1000.0));

        // Set PWM value
        if (gpioWrite(pwm_fd, pwm_value) < 0) {
            perror("gpioWrite");
            continue;
        }

        // Increment sample count
        sample_count++;

        // Sleep for 100 ms
        usleep(100000);

        // Log sample count
        if (log_fd >= 0) {
            fprintf(log_fd, "Sample %d: Z-magnitude = %f\n", sample_count, z_magnitude);
        }
    }

    // Clean up
    gpioTerminate(pwm_fd);
    close(i2c_fd);
    close(log_fd);

    return 0;
}

void sigpipe_handler(int sig) {
    syslog(LOG_ERR, "SIGPIPE received");
    exit(1);
}

