#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/statvfs.h>
#include <errno.h>

#define I2C_ADDRESS 0x1E
#define I2C_BUS 1
#define SAMPLE_AVERAGE 8
#define OUTPUT_RATE 15
#define GAIN 0x70
#define CONFIG_B 0x20
#define MODE 0x00
#define HARD_IRON_WINDOW 100
#define HARD_IRON_RATE 500

int main(int argc, char **argv) {
    int i, j, k;
    int fd;
    int i2c_fd;
    unsigned char config_a, config_b, mode;
    unsigned char raw_x, raw_y, raw_z;
    unsigned char offset_x, offset_y, offset_z;
    unsigned char buffer[2];
    unsigned long long sum_x, sum_y, sum_z;
    unsigned long long count_x, count_y, count_z;
    unsigned long long window_x, window_y, window_z;
    unsigned long long window_count;
    struct sigaction sa;
    struct sigaction old_sa;
    struct stat sb;
    struct statvfs st;
    struct i2c_client *client;
    struct i2c_dev *dev;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set up I2C device
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        return 1;
    }

    // Set up I2C configuration
    config_a = 0x00;
    config_b = 0x20;
    mode = 0x00;
    if (ioctl(fd, I2C_SMBUS_WRITE_byte, (void *) &config_a) < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return 1;
    }
    if (ioctl(fd, I2C_SMBUS_WRITE_byte, (void *) &config_b) < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return 1;
    }
    if (ioctl(fd, I2C_SMBUS_WRITE_byte, (void *) &mode) < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return 1;
    }

    // Initialize variables
    sum_x = 0;
    sum_y = 0;
    sum_z = 0;
    count_x = 0;
    count_y = 0;
    count_z = 0;
    window_x = 0;
    window_y = 0;
    window_z = 0;
    window_count = 0;

    // Set up signal handlers
    sa.sa_handler = sigpipe;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, &old_sa) < 0) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, &old_sa) < 0) {
        perror("sigaction");
        return 1;
    }

    while (1) {
        // Read raw values
        if (ioctl(fd, I2C_SMBUS_READ_byte, (void *) &raw_x) < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            continue;
        }
        if (ioctl(fd, I2C_SMBUS_READ_byte, (void *) &raw_y) < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            continue;
        }
        if (ioctl(fd, I2C_SMBUS_READ_byte, (void *) &raw_z) < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            continue;
        }

        // Compute hard-iron offsets
        offset_x = (int) ((raw_x - sum_x) / SAMPLE_AVERAGE);
        offset_y = (int) ((raw_y - sum_y) / SAMPLE_AVERAGE);
        offset_z = (int) ((raw_z - sum_z) / SAMPLE_AVERAGE);

        // Update running averages
        sum_x += offset_x;
        sum_y += offset_y;
        sum_z += offset_z;
        count_x++;
        count_y++;
        count_z++;

        // Update window
        window_x = (window_x * (HARD_IRON_WINDOW - 1) + offset_x) / HARD_IRON_WINDOW;
        window_y = (window_y * (HARD_IRON_WINDOW - 1) + offset_y) / HARD_IRON_WINDOW;
        window_z = (window_z * (HARD_IRON_WINDOW - 1) + offset_z) / HARD_IRON_WINDOW;
        window_count++;

        // Apply hard-iron offsets
        if (window_count >= HARD_IRON_RATE) {
            window_x = 0;
            window_y = 0;
            window_z = 0;
            window_count = 0;
        }

        // Print offset-corrected values
        printf("%llu %llu %llu\n", window_x, window_y, window_z);
    }

    // Clean up
    close(fd);
    gpioTerminate();
    return 0;
}

