#include <signal.h>
#include <gpiod/gpiod.h>

// Define the GPIO lines
#define SOLENOID1_GPIO 17
#define SOLENOID2_GPIO 27

// Define the GPIO chip
#define GPIO_CHIP GPIOChip *gpio_chip;

// Define the consumer labels
const char *consumer_label1 = "solenoid1";
const char *consumer_label2 = "solenoid2";

int main() {
    // Initialize libgpiod
    gpiochip = gpiod_init();
    if (!gpiochip) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Request the GPIO lines with consumer labels
    gpio_request(gpio_chip, SOLENOID1_GPIO, consumer_label1);
    gpio_request(gpio_chip, SOLENOID2_GPIO, consumer_label2);

    // Set the initial state of the lines to LOW
    gpio_set_value(gpio_chip, SOLENOID1_GPIO, 0);
    gpio_set_value(gpio_chip, SOLENOID2_GPIO, 0);

    // Install a SIGINT/SIGTERM handler
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler\n");
        return 1;
    }

    while (1) {
        // Energize solenoid 1
        gpio_set_value(gpio_chip, SOLENOID1_GPIO, 1);
        if (gpiochip->err) {
            fprintf(stderr, "Failed to energize solenoid 1\n");
            break;
        }
        nanosleep(500000, NULL); // 500 ms

        // De-energize solenoid 1 and energize solenoid 2
        gpio_set_value(gpio_chip, SOLENOID1_GPIO, 0);
        if (gpiochip->err) {
            fprintf(stderr, "Failed to de-energize solenoid 1 and energize solenoid 2\n");
            break;
        }
        gpio_set_value(gpio_chip, SOLENOID2_GPIO, 1);
        if (gpiochip->err) {
            fprintf(stderr, "Failed to energize solenoid 2\n");
            break;
        }
        nanosleep(500000, NULL); // 500 ms

        // De-energize solenoid 2
        gpio_set_value(gpio_chip, SOLENOID2_GPIO, 0);
        if (gpiochip->err) {
            fprintf(stderr, "Failed to de-energize solenoid 2\n");
            break;
        }
    }

    // Clean up
    gpio_release(gpio_chip, SOLENOID1_GPIO);
    gpio_release(gpio_chip, SOLENOID2_GPIO);
    gpiod_exit(gpiochip);
    return 0;
}

void sig_handler(int sig) {
    // Clean up
    gpio_release(gpio_chip, SOLENOID1_GPIO);
    gpio_release(gpio_chip, SOLENOID2_GPIO);
    gpiod_exit(gpiochip);
    exit(0);
}

