#include <signal.h>
#include <sys/select.h>
#include <termios.h>
#include <fcntl.h>

#define SERIAL_PORT0 "/dev/serial0"
#define SERIAL_PORT1 "/dev/serial1"
#define LOCK_GPIO17 17
#define LOCK_GPIO27 27
#define LOCK_CODE "123456"
#define SERIAL_BAUD 9600
#define SERIAL_TIMEOUT 5
#define SERIAL_FRAMING 8N1

int main(int argc, char **argv) {
    int gpio, serial0, serial1;
    struct termios options;
    struct sigaction sa;
    char code0[7], code1[7];
    int code0_len, code1_len;
    int lock0, lock1;
    int timeout;
    int ret;

    // Initialize signal handler for SIGINT and SIGTERM
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize pigpio
    if ((ret = pigpio_init()) != 0) {
        fprintf(stderr, "pigpio_init() failed: %d\n", ret);
        return 1;
    }

    // Configure GPIO17 and GPIO27 as outputs
    if ((ret = pigpio_set_mode(LOCK_GPIO17, PI_OUTPUT)) != 0) {
        fprintf(stderr, "pigpio_set_mode() failed: %d\n", ret);
        pigpioTerminate();
        return 1;
    }
    if ((ret = pigpio_set_mode(LOCK_GPIO27, PI_OUTPUT)) != 0) {
        fprintf(stderr, "pigpio_set_mode() failed: %d\n", ret);
        pigpioTerminate();
        return 1;
    }

    // Configure serial ports
    if ((serial0 = open(SERIAL_PORT0, O_RDWR | O_NOCTTY | O_NONBLOCK)) == -1) {
        fprintf(stderr, "open() failed: %d\n", serial0);
        pigpioTerminate();
        return 1;
    }
    if ((ret = tcgetattr(serial0, &options)) != 0) {
        fprintf(stderr, "tcgetattr() failed: %d\n", ret);
        close(serial0);
        pigpioTerminate();
        return 1;
    }
    if ((ret = cfsetispeed(&options, SERIAL_BAUD)) != 0) {
        fprintf(stderr, "cfsetispeed() failed: %d\n", ret);
        close(serial0);
        pigpioTerminate();
        return 1;
    }
    if ((ret = cfsetospeed(&options, SERIAL_BAUD)) != 0) {
        fprintf(stderr, "cfsetospeed() failed: %d\n", ret);
        close(serial0);
        pigpioTerminate();
        return 1;
    }
    if ((ret = tcsetattr(serial0, TCSANOW, &options)) != 0) {
        fprintf(stderr, "tcsetattr() failed: %d\n", ret);
        close(serial0);
        pigpioTerminate();
        return 1;
    }

    if ((serial1 = open(SERIAL_PORT1, O_RDWR | O_NOCTTY | O_NONBLOCK)) == -1) {
        fprintf(stderr, "open() failed: %d\n", serial1);
        close(serial0);
        pigpioTerminate();
        return 1;
    }
    if ((ret = tcgetattr(serial1, &options)) != 0) {
        fprintf(stderr, "tcgetattr() failed: %d\n", ret);
        close(serial0);
        close(serial1);
        pigpioTerminate();
        return 1;
    }
    if ((ret = cfsetispeed(&options, SERIAL_BAUD)) != 0) {
        fprintf(stderr, "cfsetispeed() failed: %d\n", ret);
        close(serial0);
        close(serial1);
        pigpioTerminate();
        return 1;
    }
    if ((ret = cfsetospeed(&options, SERIAL_BAUD)) != 0) {
        fprintf(stderr, "cfsetospeed() failed: %d\n", ret);
        close(serial0);
        close(serial1);
        pigpioTerminate();
        return 1;
    }
    if ((ret = tcsetattr(serial1, TCSANOW, &options)) != 0) {
        fprintf(stderr, "tcsetattr() failed: %d\n", ret);
        close(serial0);
        close(serial1);
        pigpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read from serial ports
        if ((ret = read(serial0, code0, 7)) == -1) {
            if (errno == EAGAIN) {
                // Timeout
                continue;
            } else {
                fprintf(stderr, "read() failed: %d\n", ret);
                close(serial0);
                close(serial1);
                pigpioTerminate();
                return 1;
            }
        }
        code0[6] = '\0';
        code0_len = 0;
        while (code0[code0_len] != '\n' && code0_len < 6) {
            code0[code0_len++] = getchar();
        }
        if (code0_len < 6) {
            // Invalid code
            continue;
        }

        if ((ret = read(serial1, code1, 7)) == -1) {
            if (errno == EAGAIN) {
                // Timeout
                continue;
            } else {
                fprintf(stderr, "read() failed: %d\n", ret);
                close(serial0);
                close(serial1);
                pigpioTerminate();
                return 1;
            }
        }
        code1[6] = '\0';
        code1_len = 0;
        while (code1[code1_len] != '\n' && code1_len < 6) {
            code1[code1_len++] = getchar();
        }
        if (code1_len < 6) {
            // Invalid code
            continue;
        }

        // Compare codes
        if (strcmp(code0, LOCK_CODE) != 0 || strcmp(code1, LOCK_CODE) != 0) {
            // Invalid code
            continue;
        }

        // Unlock and re-lock
        pigpio_delay(2000);
        pigpio_write(LOCK_GPIO17, 1);
        pigpio_delay(2000);
        pigpio_write(LOCK_GPIO17, 0);
        pigpio_write(LOCK_GPIO27, 1);
        pigpio_delay(2000);
        pigpio_write(LOCK_GPIO27, 0);
    }

    // Clean shutdown
    pigpio_close(LOCK_GPIO17);
    pigpio_close(LOCK_GPIO27);
    close(serial0);
    close(serial1);
    pigpioTerminate();
    return 0;
}

void sigint_handler(int sig) {
    // Clean shutdown
    pigpio_close(LOCK_GPIO17);
    pigpio_close(LOCK_GPIO27);
    close(serial0);
    close(serial1);
    pigpioTerminate();
    exit(0);
}

