    struct gpiod_log_request *log_req;
    struct gpiod_line_request_input *req_in_input;
    struct gpiod_line_request_output *req_out_output;
    struct gpiod_line_get_value_input *get_in_input;
    struct gpiod_line_get_value_output *get_out_output;
    struct gpiod_line_set_value_input *set_out_input;
    struct gpiod_line_set_value_output *set_out_output;
