    if (!log_req) {
        syslog(LOG_ERR, "Failed to create log request");
        return 1;
    }
    log = gpiod_log_new(log_req);
    if (!log) {
        syslog(LOG_ERR, "Failed to create log");
        gpiod_log_request_free(log_req);
        return 1;
    }

    // Open the gpiochip
    chip = gpiod_chip_open("gpiochip0", NULL);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip");
        gpiod_log_close(log);
        gpiod_log_request_free(log_req);
        return 1;
    }

    // Request the lines
    req_in = gpiod_line_request_input_new(chip, PIR_PIN, NULL);
    if (!req_in) {
        syslog(LOG_ERR, "Failed to request input line");
        gpiod_chip_close(chip);
        gpiod_log_close(log);
        gpiod_log_request_free(log_req);
        return 1;
    }
    req_out = gpiod_line_request_output_new(chip, RELAY_PIN, NULL);
