    get_in = gpiod_line_get_value_input_new(req_in);
    if (!get_in) {
        syslog(LOG_ERR, "Failed to get input line value");
        gpiod_line_request_input_free(req_in);
        gpiod_line_request_output_free(req_out);
        gpiod_chip_close(chip);
        gpiod_log_close(log);
        gpiod_log_request_free(log_req);
        return 1;
    }
    get_out = gpiod_line_get_value_output_new(req_out);
    if (!get_out) {
        syslog(LOG_ERR, "Failed to get output line value");
        gpiod_line_get_value_input_free(get_in);
        gpiod_line_request_input_free(req_in);
        gpiod_line_request_output_free(req_out);
        gpiod_chip_close(chip);
        gpiod_log_close(log);
        gpiod_log_request_free(log_req);
        return 1;
    }

