void log_state(int relay, int state) {
    char buffer[256];
    strftime(buffer, sizeof(buffer), "Relay %d: %s", relay, state == RELAY_STATE_ON ? "ON" : "OFF");
    syslog(LOG_INFO, "%s", buffer);
}

void activate_relay(int relay) {
    if (relay >= RELAY_COUNT) {
        return;
    }
    if (relay_states[relay] != RELAY_STATE_OFF) {
        log_state(relay, RELAY_STATE_DEACTIVATING);
        relay_states[relay] = RELAY_STATE_DEACTIVATING;
        gpioWrite(relay, 0);
        sleep(1);
        log_state(relay, RELAY_STATE_DEACTIVATED);
        relay_states[relay] = RELAY_STATE_DEACTIVATED;
        return;
    }
    log_state(relay, RELAY_STATE_ACTIVE);
    relay_states[relay] = RELAY_STATE_ACTIVE;
    gpioWrite(relay, 0);
    sleep(300);
    log_state(relay, RELAY_STATE_OFF);
    relay_states[relay] = RELAY_STATE_OFF;
}

void deactivate_relay(int relay) {
    if (relay >= RELAY_COUNT) {
        return;
    }
    if (relay_states[relay] != RELAY_STATE_ON) {
        log_state(relay, RELAY_STATE_DEACTIVATING);
        relay_states[relay] = RELAY_STATE_DEACTIVATING;
        gpioWrite(relay, 1);
        sleep(1);
        log_state(relay, RELAY_STATE_DEACTIVATED);
        relay_states[relay] = RELAY_STATE_DEACTIVATED;
        return;
    }
    log_state(relay, RELAY_STATE_DEACTIVATING);
    relay_states[relay] = RELAY_STATE_DEACTIVATING;
    gpioWrite(relay, 1);
    sleep(1);
    log_state(relay, RELAY_STATE_OFF);
    relay_states[relay] = RELAY_STATE_OFF;
}

void timer_func(int timer_id, void *data) {
    if (timer_running) {
        switch (state) {
            case RELAY_STATE_ACTIVE:
                for (int i = 0; i < RELAY_COUNT; i++) {
                    activate_relay(i);
                }
                state = RELAY_STATE_PAUSED;
                break;
            case RELAY_STATE_PAUSED:
                for (int i = 0; i < RELAY_COUNT; i++) {
                    deactivate_relay(i);
                }
                state = RELAY_STATE_ACTIVE;
                break;
            case RELAY_STATE_DEACTIVATING:
                for (int i = 0; i < RELAY_COUNT; i++) {
                    deactivate_relay(i);
                }
                state = RELAY_STATE_OFF;
                break;
            case RELAY_STATE_DEACTIVATED:
                for (int i = 0; i < RELAY_COUNT; i++) {
                    activate_relay(i);
                }
                state = RELAY_STATE_PAUSED;
                break;
        }
    }
}

int main() {
    pigpio = gpioInit();
    if (pigpio == -1) {
        syslog(LOG_ERR, "gpioInit failed");
        return 1;
    }

    for (int i = 0; i < RELAY_COUNT; i++) {
        gpioSetMode(i, PI_OUTPUT);
        gpioWrite(i, 1);
    }

    gpioSetTimerFuncEx(0, timer_func, NULL);
    timer_id = gpioSetTimer(0, 60 * 1000, 0);

    if (timer_id == -1) {
        syslog(LOG_ERR, "gpioSetTimer failed");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, SIG_IGN);
    signal(SIGTERM, SIG_IGN);

    while (1) {
        if (timer_running) {
            sleep(1);
        } else {
            break;
        }
    }

    gpioTerminate();
    close(syslog);
    return 0;
}

