#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>

// Define constants
#define RELAY_PIN 27
#define RELAY_RELAY_PIN 17
#define RELAY_THRESHOLD 0.5  // Adjust the threshold value as needed
#define DEBOUNCE_TIME 100  // Debounce time in milliseconds
#define LOG_FILE "alarm_log.txt"

// Global variables
int gpio;
int relay_state = 0;
int last_debounce_time = 0;
int last_relay_state = 0;
int last_log_time = 0;

// Function to initialize pigpio
void init_pigpio() {
    if (gpio = pigpio_init()) {
        printf("pigpio initialization failed\n");
        exit(1);
    }
}

// Function to clean up pigpio
void cleanup_pigpio() {
    if (gpio) {
        pigpio_close(gpio);
        pigpio_uninit();
    }
}

// Function to read the sound sensor
int read_sound_sensor() {
    int value = pigpio_get_value(RELAY_RELAY_PIN);
    if (value == 1) {
        return 1;
    } else {
        return 0;
    }
}

// Function to log the timestamp
void log_timestamp() {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s\n", timestamp);
        fclose(log_file);
    }
}

// Function to trigger the relay
void trigger_relay() {
    if (gpio) {
        pigpio_write(gpio, RELAY_PIN, 1);
        sleep(3);
        pigpio_write(gpio, RELAY_PIN, 0);
    }
}

// Function to debounce the relay
void debounce_relay() {
    int current_time = time(NULL);
    if (current_time - last_debounce_time > DEBOUNCE_TIME) {
        last_debounce_time = current_time;
        if (relay_state == 1 && last_relay_state == 0) {
            trigger_relay();
            last_relay_state = 1;
        } else if (relay_state == 0 && last_relay_state == 1) {
            last_relay_state = 0;
        }
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    cleanup_pigpio();
    exit(0);
}

int main() {
    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    init_pigpio();

    // Open the log file
    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file) {
        fclose(log_file);
    }

    while (1) {
        // Read the sound sensor
        int sound_value = read_sound_sensor();

        // Debounce the relay
        debounce_relay();

        // Log the timestamp
        log_timestamp();

        // Sleep for 100 ms
        sleep(0.1);
    }

    return 0;
}
```

This code initializes the pigpio library, sets up a signal handler for SIGINT and SIGTERM, and enters an infinite loop to continuously monitor the sound sensor, trigger the relay, and log the timestamp. The debounce mechanism ensures that the relay is not retriggered while already active. The relay is turned off when the program exits.

