#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_ADDRESS 0x68
#define GYRO_XOUT_H 0x43
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define GYRO_SENSITIVITY 131.0
#define BUFFER_SIZE 100
#define THRESHOLD 50.0

// Structure to hold gyroscope data
typedef struct {
    float x, y, z;
} GyroData;

// Structure to hold callback function
typedef void (*Callback)(float);

// Global variables
int fd;
char *buffer;
GyroData *data;
Callback callback;

// Function to initialize the I2C device
int init_i2c() {
    int ret = open("/dev/i2c-1", O_RDWR);
    if (ret < 0) {
        perror("open");
        return -1;
    }

    if (ioctl(ret, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(ret);
        return -1;
    }

    return ret;
}

// Function to read gyroscope data
int read_gyro_data() {
    int ret = read(fd, buffer, BUFFER_SIZE);
    if (ret < 0) {
        perror("read");
        return -1;
    }

    // Convert raw data to gyroscope values
    data->x = (float)htonl(*(uint32_t *)buffer) * GYRO_SENSITIVITY / 65536.0;
    data->y = (float)htonl(*(uint32_t *)(buffer + 4)) * GYRO_SENSITIVITY / 65536.0;
    data->z = (float)htonl(*(uint32_t *)(buffer + 8)) * GYRO_SENSITIVITY / 65536.0;

    return ret;
}

// Function to check if the absolute angular velocity exceeds the threshold
int check_threshold() {
    float magnitude = sqrt(data->x * data->x + data->y * data->y + data->z * data->z);
    if (magnitude > THRESHOLD) {
        callback(magnitude);
        return 1;
    }
    return 0;
}

// Function to initialize the gyroscope
int init_gyro() {
    // Clear the sleep bit
    uint8_t reg = 0x00;
    if (write(fd, &reg, 1) < 0) {
        perror("write");
        return -1;
    }

    // Verify the device
    reg = 0x75;
    if (read(fd, &reg, 1) < 0) {
        perror("read");
        return -1;
    }
    if (reg != I2C_ADDRESS) {
        perror("WHO_AM_I");
        return -1;
    }

    return 0;
}

// Function to handle SIGINT
void sigint_handler(int sig) {
    close(fd);
    munmap(buffer, BUFFER_SIZE);
    free(data);
    exit(0);
}

int main() {
    // Initialize the I2C device
    fd = init_i2c();
    if (fd < 0) {
        perror("init_i2c");
        return -1;
    }

    // Initialize the gyroscope
    if (init_gyro() < 0) {
        perror("init_gyro");
        close(fd);
        return -1;
    }

    // Allocate memory for the buffer
    buffer = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return -1;
    }

    // Initialize the data structure
    data = malloc(sizeof(GyroData));
    if (data == NULL) {
        perror("malloc");
        munmap(buffer, BUFFER_SIZE);
        close(fd);
        return -1;
    }

    // Set the callback function
    callback = check_threshold;

    // Read gyroscope data in a loop
    while (1) {
        if (read_gyro_data() < 0) {
            perror("read_gyro_data");
            break;
        }
        if (check_threshold()) {
            break;
        }
        usleep(100000); // sleep for 100ms
    }

    // Clean up
    munmap(buffer, BUFFER_SIZE);
    close(fd);
    free(data);

    return 0;
}

