#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/statvfs.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <json/json.h>

#define BAUD 9600
#define BUFFER_SIZE 9
#define CO2_COMMAND {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79}
#define CO2_CHECKSUM 0x79
#define CO2_OFFSET 2
#define CO2_CO2 3

void co2_monitor(int argc, char **argv) {
    int fd;
    int ret;
    pigpio *pigpio;
    struct stat sb;
    struct statvfs buf;
    FILE *log_file;
    FILE *co2_log_file;
    FILE *co2_error_log_file;
    struct timespec start;
    struct timespec end;
    struct timespec sleep_time;
    struct timespec sleep_interval;
    struct timespec last_sleep;
    int sleep_count;
    int co2_valid;
    int co2_error;
    uint8_t response[BUFFER_SIZE];
    uint8_t checksum;
    char timestamp[20];
    char co2_value[10];
    char error[10];

    // Initialize pigpio
    pigpio = pigpio_init();
    if (pigpio == -1) {
        fprintf(stderr, "pigpio_init failed\n");
        return;
    }

    // Open serial port
    fd = serOpen("/dev/serial0", BAUD, pigpio, pigpio, NULL);
    if (fd == -1) {
        fprintf(stderr, "serOpen failed\n");
        pigpio_close(pigpio);
        return;
    }

    // Open log files
    log_file = fopen("co2_error.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "fopen co2_error.log failed\n");
        serClose(fd);
        pigpio_close(pigpio);
        return;
    }
    co2_log_file = fopen("co2_log.json", "a");
    if (co2_log_file == NULL) {
        fclose(log_file);
        fprintf(stderr, "fopen co2_log.json failed\n");
        serClose(fd);
        pigpio_close(pigpio);
        return;
    }
    co2_error_log_file = fopen("co2_error.log", "a");
    if (co2_error_log_file == NULL) {
        fclose(log_file);
        fclose(co2_log_file);
        fprintf(stderr, "fopen co2_error.log failed\n");
        serClose(fd);
        pigpio_close(pigpio);
        return;
    }

    // Set up sleep interval
    sleep_time.tv_sec = 5;
    sleep_time.tv_nsec = 0;
    sleep_interval.tv_sec = 0;
    sleep_interval.tv_nsec = 100000000;

    // Main loop
    while (1) {
        // Send command
        ret = serWrite(fd, CO2_COMMAND, 9);
        if (ret == -1) {
            fprintf(stderr, "serWrite failed\n");
            serClose(fd);
            pigpio_close(pigpio);
            fclose(log_file);
            fclose(co2_log_file);
            fclose(co2_error_log_file);
            return;
        }

        // Wait for response
        ret = serDataAvailable(fd, 1000);
        if (ret == -1) {
            fprintf(stderr, "serDataAvailable failed\n");
            serClose(fd);
            pigpio_close(pigpio);
            fclose(log_file);
            fclose(co2_log_file);
            fclose(co2_error_log_file);
            return;
        }
        ret = serRead(fd, response, BUFFER_SIZE);
        if (ret == -1) {
            fprintf(stderr, "serRead failed\n");
            serClose(fd);
            pigpio_close(pigpio);
            fclose(log_file);
            fclose(co2_log_file);
            fclose(co2_error_log_file);
            return;
        }

        // Validate checksum
        checksum = 0;
        for (int i = 1; i < 8; i++) {
            checksum += response[i];
        }
        checksum = ~checksum + 1;
        if (checksum != response[8]) {
            fprintf(stderr, "Checksum error\n");
            fprintf(co2_error_log_file, "%ls\n", ctime(&start));
            fprintf(co2_error_log_file, "%s\n", error);
            fprintf(log_file, "%ls\n", ctime(&start));
            fprintf(log_file, "%s\n", error);
            serClose(fd);
            pigpio_close(pigpio);
            fclose(log_file);
            fclose(co2_log_file);
            fclose(co2_error_log_file);
            return;
        }

        // Extract CO2 value
        co2_valid = 0;
        for (int i = CO2_OFFSET; i < CO2_OFFSET + 2; i++) {
            if (response[i] != 0) {
                co2_valid = 1;
                sprintf(co2_value, "%d", (response[i] << 8) | response[i + 1]);
                break;
            }
        }
        if (!co2_valid) {
            fprintf(stderr, "CO2 value not found\n");
            fprintf(co2_error_log_file, "%ls\n", ctime(&start));
            fprintf(co2_error_log_file, "%s\n", error);
            fprintf(log_file, "%ls\n", ctime(&start));
            fprintf(log_file, "%s\n", error);
            serClose(fd);
            pigpio_close(pigpio);
            fclose(log_file);
            fclose(co2_log_file);
            fclose(co2_error_log_file);
            return;
        }

        // Log data
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%06d", localtime(&start));
        fprintf(co2_log_file, "{\"timestamp\":\"%s\",\"co2\":\"%s\",\"error\":\"%s\"}\n", timestamp, co2_value, error);
        fprintf(stdout, "{\"timestamp\":\"%s\",\"co2\":\"%s\",\"error\":\"%s\"}\n", timestamp, co2_value, error);
        fflush(stdout);
        fprintf(log_file, "%s\n", timestamp);
        fprintf(log_file, "%s\n", error);
        fflush(log_file);

        // Sleep
        nanosleep(&sleep_interval, &last_sleep);
        if (nanosleep(&sleep_interval, &last_sleep) == -1) {
            fprintf(stderr, "nanosleep failed\n");
            serClose(fd);
            pigpio_close(pigpio);
            fclose(log_file);
            fclose(co2_log_file);
            fclose(co2_error_log_file);
            return;
        }
        sleep_count++;
        if (sleep_count >= 5) {
            sleep_count = 0;
            sleep_time.tv_sec += 5;
            sleep_time.tv_nsec = 0;
        }
    }

    // Clean up
    serClose(fd);
    pigpio_close(pigpio);
    fclose(log_file);
    fclose(co2_log_file);
    fclose(co2_error_log_file);
}

int main(int argc, char **argv) {
    struct sigaction sa;
    struct sigaction old_sa;

    // Set up signal handlers
    sa.sa_handler = SIG_IGN;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, &old_sa) == -1) {
        fprintf(stderr, "sigaction failed\n");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, &old_sa) == -1) {
        fprintf(stderr, "sigaction failed\n");
        return 1;
    }

    // Run monitor
    co2_monitor(argc, argv);

    return 0;
}

