#define CONFIG_A 0x00
#define CONFIG_B 0x01
#define MODE 0x02
#define OFFSET_X 100
#define OFFSET_Y -50
#define TARGET_HEADING 90.0
#define SAMPLE_INTERVAL 100
#define I2C_TIMEOUT 0.1

struct buffer_entry {
    double heading;
    time_t timestamp;
};

struct buffer_entry buffer[BUFFER_MAX_SIZE];

int main(int argc, char **argv) {
    int i, j;
    int i2c_fd;
    int gpio_fd;
    int retry_count = 0;
    int retry_limit = 3;
    int buffer_index = BUFFER_INDEX;
    struct timeval tv;
    struct sigaction sa;
    struct sigaction old_sa;
    struct timeval old_tv;
    struct timeval tv2;
    double heading;
    double compensated_heading;
    int error;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up I2C
    if ((i2c_fd = i2cOpen(I2C Bus, I2C_ADDRESS, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Configure HMC5883L
    if (i2cWrite(i2c_fd, CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Failed to configure HMC5883L\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (i2cWrite(i2c_fd, CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Failed to configure HMC5883L\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (i2cWrite(i2c_fd, MODE, 0x00) < 0) {
        fprintf(stderr, "Failed to configure HMC5883L\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up GPIO
    if (gpioMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, &old_sa) < 0) {
        fprintf(stderr, "Failed to set up signal handling\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    sa.sa_handler = sigterm_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGTERM, &sa, &old_sa) < 0) {
        fprintf(stderr, "Failed to set up signal handling\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

