    for (i = 0; i < BUFFER_MAX_SIZE; i++) {
        buffer[i].heading = 0.0;
        buffer[i].timestamp = 0;
    }

    while (1) {
        // Read data from HMC5883L
        if ((error = i2cRead(i2c_fd, 0x03, 6, 0, NULL, NULL)) < 0) {
            if (retry_count < retry_limit) {
                retry_count++;
                usleep(I2C_TIMEOUT * 1000000);
                continue;
            } else {
                fprintf(stderr, "Failed to read from HMC5883L\n");
                i2cClose(i2c_fd);
                gpioTerminate();
                return 1;
            }
        }

        // Compensate for hard-iron distortion
        heading = (error & 0x3F) * 0.5;
        heading += (error >> 8) * 0.25;
        heading += (error >> 16) * 0.125;
        heading += (error >> 24) * 0.0625;
        heading += OFFSET_X;
        heading += OFFSET_Y;
        heading = (heading + TARGET_HEADING) * 0.5;

        // Update buffer
        buffer[buffer_index].heading = heading;
        buffer[buffer_index].timestamp = time(NULL);
        buffer_index = (buffer_index + 1) % BUFFER_MAX_SIZE;

        // Check if buffer is full
        if (buffer_index == BUFFER_INDEX) {
            buffer_index = BUFFER_INDEX;
        }

        // Check if buffer is not empty
        if (buffer_index > 0) {
            double oldest_heading = buffer[0].heading;
            double oldest_timestamp = buffer[0].timestamp;
            for (i = 1; i < BUFFER_MAX_SIZE; i++) {
                if (buffer[i].timestamp > oldest_timestamp) {
                    oldest_heading = buffer[i].heading;
                    oldest_timestamp = buffer[i].timestamp;
                }
