        tv.tv_sec = 0;
        tv.tv_usec = 0;
        tv.tv_sec = SAMPLE_INTERVAL / 1000000;
        tv.tv_usec = (SAMPLE_INTERVAL % 1000000);
        select(0, NULL, NULL, NULL, &tv);
    }

    // Clean up
    i2cClose(i2c_fd);
    gpioTerminate();
    return 0;
}

void sigint_handler(int sig) {
    printf("Received SIGINT\n");
    exit(0);
}

