#define RELAY_PIN_RED 17
#define RELAY_PIN_GREEN 27
#define RELAY_PIN_BLUE 22
#define BH1750_ADDRESS 0x23
#define I2C_BUS 1
#define I2C_FILE "/dev/i2c-1"
#define LOG_FILE "lighting_log.txt"

int main() {
    // Initialize libgpiod
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C file descriptor
    int fd = open(I2C_FILE, O_RDWR);
    if (fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Configure I2C bus
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDRESS) < 0) {
        perror("ioctl");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Configure BH1750 for continuous high-resolution mode
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDRESS) < 0) {
        perror("ioctl");
        close(fd);
        gpioTerminate();
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDRESS) < 0) {
        perror("ioctl");
        close(fd);
        gpioTerminate();
        return 1;
    }
    if (ioctl(fd, BH1750_SET_MODE, 0x10) < 0) {
        perror("ioctl");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Wait for the first conversion
    usleep(120 * 1000);

    // Read the 2-byte lux value
    unsigned short lux;
    if (ioctl(fd, BH1750_GET_LUX, &lux) < 0) {
        perror("ioctl");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Compute lux value
    float lux_value = (float)lux / 1.2;

    // Initialize relay states
    int relay_states[3] = {0, 0, 0};

    // Main loop
    while (1) {
        // Log timestamp, lux value, and relay states
        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("fopen");
            gpioTerminate();
            return 1;
        }
        fprintf(log_file, "%d %f %d %d %d\n", (int)time(NULL), lux_value, relay_states[0], relay_states[1], relay_states[2]);
        fclose(log_file);

        // Update relay states based on lux value
        if (lux_value < 50) {
            relay_states[0] = 1;
            relay_states[1] = 0;
            relay_states[2] = 0;
        } else if (lux_value < 150) {
            relay_states[0] = 0;
            relay_states[1] = 1;
            relay_states[2] = 0;
        } else if (lux_value < 300) {
            relay_states[0] = 0;
            relay_states[1] = 0;
            relay_states[2] = 1;
        } else {
            relay_states[0] = 1;
            relay_states[1] = 1;
            relay_states[2] = 1;
        }

        // Drive relays
        gpioWrite(RELAY_PIN_RED, relay_states[0]);
        gpioWrite(RELAY_PIN_GREEN, relay_states[1]);
        gpioWrite(RELAY_PIN_BLUE, relay_states[2]);

        // Check for SIGINT and SIGTERM signals
        if (gpioGetSignal(RELAY_PIN_RED) == 1) {
            gpioWrite(RELAY_PIN_RED, 0);
            gpioWrite(RELAY_PIN_GREEN, 0);
            gpioWrite(RELAY_PIN_BLUE, 0);
            break;
        }
        if (gpioGetSignal(RELAY_PIN_GREEN) == 1) {
            gpioWrite(RELAY_PIN_RED, 0);
            gpioWrite(RELAY_PIN_GREEN, 0);
            gpioWrite(RELAY_PIN_BLUE, 0);
            break;
        }
        if (gpioGetSignal(RELAY_PIN_BLUE) == 1) {
            gpioWrite(RELAY_PIN_RED, 0);
            gpioWrite(RELAY_PIN_GREEN, 0);
            gpioWrite(RELAY_PIN_BLUE, 0);
            break;
        }

        // Check for I2C errors
        if (ioctl(fd, BH1750_GET_LUX, &lux) < 0) {
            perror("ioctl");
            break;
        }

        // Wait for 1 second
        usleep(1000 * 1000);
    }

    // Release I2C file descriptor
    close(fd);

    // Release GPIO lines
    gpioCleanUp();
    gpioTerminate();

    return 0;
}

