#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/signal.h>
#include <time.h>

#define I2C_ADDRESS 0x68
#define I2C Bus 1
#define GPIO_SDA 2
#define GPIO_SCL 3
#define GPIO_SERVO 18
#define PWM_CHANNEL 0
#define LOG_FILE "solar_tracker.log"

int main(int argc, char **argv) {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C device
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set I2C bus parameters
    if (ioctl(fd, I2C_SLAVE, I2C Bus) < 0) {
        perror("ioctl");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set I2C address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Map I2C memory
    void *i2c_mem = mmap(NULL, 1024, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (i2c_mem == MAP_FAILED) {
        perror("mmap");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050 registers
    unsigned char mpuproxy[6] = {0x60, 0x00, 0x00, 0x00, 0x00, 0x00};
    if (memcpy(i2c_mem, mpuproxy, 6) < 0) {
        perror("memcpy");
        munmap(i2c_mem, 1024);
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Enable DLPF and set sample rate
    mpuproxy[0] = 0x10; // enable DLPF
    mpuproxy[1] = 0x00; // set sample rate to 100 Hz
    if (memcpy(i2c_mem, mpuproxy, 6) < 0) {
        perror("memcpy");
        munmap(i2c_mem, 1024);
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Read and log initial values
    unsigned char data[6];
    if (memcpy(data, i2c_mem, 6) < 0) {
        perror("memcpy");
        munmap(i2c_mem, 1024);
        close(fd);
        gpioTerminate();
        return 1;
    }
    printf("%s,%d,%d\n", ctime((time_t *)time(NULL)), data[0], data[1]);
    munmap(i2c_mem, 1024);
    close(fd);

    // Set up PWM
    if (gpioSetMode(GPIO_SERVO, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioPWMWrite(GPIO_SERVO, PWM_CHANNEL, 0) < 0) {
        perror("gpioPWMWrite");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor data
        if (memcpy(data, i2c_mem, 6) < 0) {
            perror("memcpy");
            break;
        }

        // Calculate pitch and roll
        float pitch = atan2(data[1], data[0]);
        float roll = atan2(data[2], data[3]);

        // Log values
        printf("%s,%f,%f\n", ctime((time_t *)time(NULL)), pitch, roll);

        // Adjust servo position
        float servo_position = 0.5 * (pitch + roll);
        if (servo_position < 0) servo_position = 0;
        if (servo_position > 180) servo_position = 180;
        if (gpioPWMWrite(GPIO_SERVO, PWM_CHANNEL, servo_position) < 0) {
            perror("gpioPWMWrite");
            break;
        }

        // Exponential backoff on errors
        if (errno == EIO) {
            usleep(100000);
        } else if (errno == EBUSY) {
            usleep(500000);
        } else {
            break;
        }
    }

    // Clean up
    gpioPWMWrite(GPIO_SERVO, PWM_CHANNEL, 0);
    gpioTerminate();
    munmap(i2c_mem, 1024);
    close(fd);

    return 0;
}

