#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18
#define MIN_FREQ 200
#define MAX_FREQ 2000
#define MIN_DISTANCE 2
#define MAX_DISTANCE 30
#define TRIGGER_DURATION 10
#define MEASUREMENT_INTERVAL 60

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return 1;
    }

    // Set up GPIO pins
    if (gpioSetMode(TRIGGER_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set up trigger pin %d: %s\n", TRIGGER_PIN, strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set up echo pin %d: %s\n", ECHO_PIN, strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up buzzer pin %d: %s\n", BUZZER_PIN, strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up PWM for buzzer
    if (gpioPWMWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set up PWM for buzzer pin %d: %s\n", BUZZER_PIN, strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up trigger and echo pin pull-downs
    if (gpioPullDown(TRIGGER_PIN) < 0) {
        fprintf(stderr, "Failed to set up trigger pin %d pull-down: %s\n", TRIGGER_PIN, strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (gpioPullDown(ECHO_PIN) < 0) {
        fprintf(stderr, "Failed to set up echo pin %d pull-down: %s\n", ECHO_PIN, strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up timer for measuring echo pulse width
    struct timespec start;
    struct timespec end;
    struct timespec interval;
    interval.tv_sec = 0;
    interval.tv_nsec = MEASUREMENT_INTERVAL * 1000000;

    while (1) {
        // Trigger the sensor
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(TRIGGER_DURATION);
        gpioWrite(TRIGGER_PIN, 0);

        // Measure echo pulse width
        gpioTick(&start);
        gpioTick(&end);
        gpioDelay(1);
        gpioTick(&end);

        // Calculate distance
        double distance = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 2;
        if (distance < 0) {
            distance = 0;
        } else if (distance > 300000) {
            distance = 300000;
        }

        // Map distance to frequency
        double frequency = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (MAX_FREQ - MIN_FREQ) + MIN_FREQ;
        if (frequency < MIN_FREQ) {
            frequency = MIN_FREQ;
        } else if (frequency > MAX_FREQ) {
            frequency = MAX_FREQ;
        }

        // Play buzzer
        gpioPWMWrite(BUZZER_PIN, frequency);

        // Sleep for measurement interval
        struct timespec sleep;
        sleep.tv_sec = interval.tv_sec;
        sleep.tv_nsec = interval.tv_nsec;
        nanosleep(&sleep, NULL);
    }

    // Silence buzzer and deinitialise pigpio on SIGINT
    signal(SIGINT, SIG_IGN);
    gpioPWMWrite(BUZZER_PIN, 0);
    gpioTerminate();
    return 0;
}

