void sigint_handler(int sig) {
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Set up PWM for each LED
    if (gpioSetupPWM(LED_RED, PWM_FREQ, PWM_MAX_VALUE) < 0) {
        fprintf(stderr, "Failed to set up PWM for LED %d\n", LED_RED);
        gpioTerminate();
        return 1;
    }
    if (gpioSetupPWM(LED_GREEN, PWM_FREQ, PWM_MAX_VALUE) < 0) {
        fprintf(stderr, "Failed to set up PWM for LED %d\n", LED_GREEN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetupPWM(LED_BLUE, PWM_FREQ, PWM_MAX_VALUE) < 0) {
        fprintf(stderr, "Failed to set up PWM for LED %d\n", LED_BLUE);
        gpioTerminate();
        return 1;
    }

    // Set up GPIO for each LED
    if (gpioMode(LED_RED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO %d as output\n", LED_RED);
        gpioTerminate();
        return 1;
    }
    if (gpioMode(LED_GREEN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO %d as output\n", LED_GREEN);
        gpioTerminate();
        return 1;
    }
    if (gpioMode(LED_BLUE, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO %d as output\n", LED_BLUE);
        gpioTerminate();
        return 1;
    }

    // Set initial PWM values
    gpioPWM(LED_RED, 0);
    gpioPWM(LED_GREEN, 0);
    gpioPWM(LED_BLUE, 0);

    // Simulate proximity value
    double proximity = 0.0;
    time_t last_time = time(NULL);
    while (1) {
        // Calculate new proximity value
        double dt = difftime(time(NULL), last_time);
        proximity = sin(2 * 3.14159 * PWM_FREQ * dt);
        last_time = time(NULL);

        // Map proximity value to PWM values
        int red = (int)(proximity * PWM_MAX_VALUE);
        int green = (int)(1 - proximity * PWM_MAX_VALUE);
        int blue = (int)(proximity * PWM_MAX_VALUE);

        // Set PWM values
        gpioPWM(LED_RED, red);
        gpioPWM(LED_GREEN, green);
        gpioPWM(LED_BLUE, blue);

        // Sleep for 0.01 seconds
        usleep(10000);
    }

    // Turn off LEDs and release resources
    gpioPWM(LED_RED, 0);
    gpioPWM(LED_GREEN, 0);
    gpioPWM(LED_BLUE, 0);
    gpioTerminate();
    return 0;
}

