#include <sys/types.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-smbus.h>

#define I2C_ADDRESS 0x1E
#define I2C_REG_M 0x02
#define I2C_REG_CRA 0x00
#define I2C_REG_M1 0x03
#define I2C_REG_M2 0x04
#define I2C_REG_M3 0x05
#define I2C_REG_M4 0x06
#define I2C_REG_M5 0x07
#define I2C_REG_M6 0x08

#define CSV_FILE "mag_log.csv"

int main() {
    int fd;
    int ret;
    char buffer[256];
    struct i2c_smbus *bus;
    struct i2c_client *client;
    struct i2c_client_info info;
    struct stat sb;
    FILE *fp;

    // Install signal handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open I2C file descriptor
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Get I2C client info
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    // Configure continuous-conversion mode
    ret = ioctl(fd, I2C_SMBUS_WRITEByte, I2C_REG_M, 0x00);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    // Configure output data rate (optional)
    if (argc > 1 && strcmp(argv[1], "rate=15") == 0) {
        ret = ioctl(fd, I2C_SMBUS_WRITEByte, I2C_REG_CRA, 0x14);
        if (ret < 0) {
            perror("ioctl");
            close(fd);
            return 1;
        }
    }

    // Open CSV file
    fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        perror("fopen");
        close(fd);
        return 1;
    }

    // Check if file exists and write header
    if (fstat(fileno(fp), &sb) == -1) {
        perror("fstat");
        fclose(fp);
        close(fd);
        return 1;
    }
    if (fstat(fileno(fp), &sb) == -1) {
        perror("fstat");
        fclose(fp);
        close(fd);
        return 1;
    }
    if (fseek(fp, 0, SEEK_SET) == -1) {
        perror("fseek");
        fclose(fp);
        close(fd);
        return 1;
    }
    fprintf(fp, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
    fclose(fp);

    // Main loop
    while (1) {
        // Read data from I2C
        ret = i2c_smbus_read(fd, I2C_ADDRESS, I2C_REG_M1, 6, buffer, 6);
        if (ret < 0) {
            perror("i2c_smbus_read");
            continue;
        }

        // Unpack data
        int16_t x_msb = (buffer[0] << 8) | buffer[1];
        int16_t x_lsb = buffer[2];
        int16_t z_msb = (buffer[3] << 8) | buffer[4];
        int16_t z_lsb = buffer[5];
        int16_t y_msb = (buffer[6] << 8) | buffer[7];

        // Apply hard-iron calibration offsets
        int16_t x = x_msb + x_lsb + 10;
        int16_t y = y_msb + y_lsb - 5;
        int16_t z = z_msb + z_lsb + 20;

        // Compute compass heading
        float x_norm = sqrt(x * x + y * y);
        float y_norm = sqrt(x_norm * x_norm + z * z);
        float heading = atan2f(y, x) * 180 / M_PI;
        if (heading < 0) {
            heading += 360;
        }

        // Map heading to compass direction
        int direction;
        if (x_norm > y_norm) {
            if (x_norm > z_norm) {
                direction = 0; // N
            } else if (x_norm < z_norm) {
                direction = 1; // S
            } else {
                if (y > 0) {
                    direction = 2; // NE
                } else {
                    direction = 5; // SW
                }
            }
        } else {
            if (y_norm > z_norm) {
                direction = 3; // E
            } else {
                direction = 4; // W
            }
        }

        // Write to CSV file
        fp = fopen(CSV_FILE, "a");
        if (fp == NULL) {
            perror("fopen");
            close(fd);
            return 1;
        }
        if (fstat(fileno(fp), &sb) == -1) {
            perror("fstat");
            fclose(fp);
            close(fd);
            return 1;
        }
        if (fseek(fp, 0, SEEK_END) == -1) {
            perror("fseek");
            fclose(fp);
            close(fd);
            return 1;
        }
        fprintf(fp, "%d,%d,%d,%d,%d\n", time(NULL), x, y, z, direction);
        fclose(fp);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    fclose(fp);
    close(fd);

    return 0;
}

void sigint_handler(int sig) {
    // Close I2C file descriptor
    close(0);

    // Close CSV file
    fclose(0);

    // Exit
    exit(0);
}

