#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <json-c/json.h>

// Define constants
#define GPIO4 4
#define GPIO17 17
#define RELAY_PIN GPIO17
#define RELAY_STATE_ON "ON"
#define RELAY_STATE_OFF "OFF"
#define RELAY_LOG_FILE "relay_log.json"

// Define the JSON log format
const char *json_log_format = R"(
{
    "timestamp": "%Y-%m-%d %H:%M:%S",
    "relay_state": "%s"
}
)";

// Define the debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Define the log file mode
#define LOG_FILE_MODE O_WRONLY | S_IRUSR | S_IWUSR

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Configure GPIO4 with a pull-down resistor
    if (gpioMode(GPIO4, GPIO_INPUT) < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }

    // Configure GPIO17 as an output
    if (gpioMode(RELAY_PIN, GPIO_OUTPUT) < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }

    // Set the initial relay state to OFF
    gpioWrite(RELAY_PIN, 0);

    // Set the ISR function for GPIO4
    if (gpioSetISRFunc(GPIO4, GPIO_RISING, gpioISR) < 0) {
        perror("gpioSetISRFunc");
        gpioTerminate();
        return 1;
    }

    // Open the log file
    int log_fd = open(RELAY_LOG_FILE, LOG_FILE_MODE);
    if (log_fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set the file to append mode
    if (flock(log_fd, LOCK_EX | LOCK_NB) < 0) {
        perror("flock");
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Check for debounced touches
        if (gpioRead(GPIO4) == 1) {
            // Toggle the relay
            gpioWrite(RELAY_PIN, 1);
            // Append the log entry
            char timestamp[32];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), json_log_format, &now);
            char log_entry[64];
            sprintf(log_entry, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}", timestamp, RELAY_STATE_ON);
            if (write(log_fd, log_entry, strlen(log_entry)) < 0) {
                perror("write");
                flock(log_fd, LOCK_UN);
                close(log_fd);
                gpioTerminate();
                return 1;
            }
            // Wait for the debounce time
            usleep(DEBOUNCE_TIME * 1000);
        } else {
            // Toggle the relay
            gpioWrite(RELAY_PIN, 0);
            // Append the log entry
            char timestamp[32];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), json_log_format, &now);
            char log_entry[64];
            sprintf(log_entry, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}", timestamp, RELAY_STATE_OFF);
            if (write(log_fd, log_entry, strlen(log_entry)) < 0) {
                perror("write");
                flock(log_fd, LOCK_UN);
                close(log_fd);
                gpioTerminate();
                return 1;
            }
        }
    }

    // Turn the relay OFF on SIGINT
    if (kill(getpid, SIGINT) == -1) {
        perror("kill");
        return 1;
    }

    // Append the final log entry
    char timestamp[32];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), json_log_format, &now);
    char log_entry[64];
    sprintf(log_entry, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}", timestamp, RELAY_STATE_OFF);
    if (write(log_fd, log_entry, strlen(log_entry)) < 0) {
        perror("write");
        flock(log_fd, LOCK_UN);
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Terminate pigpio
    gpioTerminate();

    // Close the log file
    if (flock(log_fd, LOCK_UN) < 0) {
        perror("flock");
        return 1;
    }
    close(log_fd);

    return 0;
}

// ISR function for GPIO4
void gpioISR(int gpio, int level, void *arg) {
    // Check for debounced touches
    if (level == 1) {
        // Toggle the relay
        gpioWrite(RELAY_PIN, 1);
    } else {
        // Toggle the relay
        gpioWrite(RELAY_PIN, 0);
    }
}

