    struct gpiod_chip *chip;
    struct gpiod_line *lines[RELAY_LINES];
    struct gpiod_line_request req;
    struct timespec delay;
    struct timespec start_time;
    struct timespec last_activation;
    int moisture;
    int i;

    // Seed random number generator
    srand(time(NULL));

    // Open the gpiochip
    fd = gpiod_chip_open("gpiochip-5", O_RDWR);
    if (fd < 0) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Request the four lines as outputs with an inactive (OFF) drive of 1
    for (i = 0; i < RELAY_LINES; i++) {
        req.type = GPIOD_LINE_REQUEST;
        req.line = RELAY_LINES_NAMES[i];
        req.direction = GPIOD_LINE_DIR_OUT;
        req.drive = RELAY_ACTIVE_LOW;
        req.flags = GPIOD_LINE_REQUEST_DEFAULT;
        req.callback = NULL;
        req.user_data = NULL;
        if (gpiod_chip_request_line(fd, &req) < 0) {
