    while (1) {
        // Generate a simulated soil-moisture value from 0 to 100
        moisture = rand() % 101;

        // Check if it's time to activate the relays
        if (time(NULL) - last_activation.tv_sec > 10) {
            // Deactivate all relays
            for (i = 0; i < RELAY_LINES; i++) {
                gpiod_line_set_value(lines[i], RELAY_DEACTIVE_LOW);
            }

            // Log the activation
            time_t now = time(NULL);
            struct tm *time_info = localtime(&now);
            char log_message[64];
            strftime(log_message, sizeof(log_message), "%Y-%m-%d %H:%M:%S", time_info);
            printf("%s %s %d %d\n", log_message, RELAY_LINES_NAMES[i], moisture, RELAY_ON_DURATION);
            fflush(stdout);

            // Activate the relays sequentially
            for (i = 0; i < RELAY_LINES; i++) {
                gpiod_line_set_value(lines[i], RELAY_ON_DURATION);
                // Log the activation
                time_info = localtime(&now);
                strftime(log_message, sizeof(log_message), "%Y-%m-%d %H:%M:%S", time_info);
                printf("%s %s %d %d\n", log_message, RELAY_LINES_NAMES[i], moisture, RELAY_ON_DURATION);
                fflush(stdout);
                // Wait for the duration
                nanosleep(&delay, NULL);
                gpiod_line_set_value(lines[i], RELAY_DEACTIVE_LOW);
                // Log the deactivation
                time_info = localtime(&now);
                strftime(log_message, sizeof(log_message), "%Y-%m-%d %H:%M:%S", time_info);
                printf("%s %s %d %d\n", log_message, RELAY_LINES_NAMES[i], moisture, RELAY_GAP_DURATION);
                fflush(stdout);
                // Wait for the gap
                nanosleep(&delay, NULL);
            }

            // Update the last activation time
            last_activation = time(NULL);
        }
    }

    // Deactivate all relays
    for (i = 0; i < RELAY_LINES; i++) {
        gpiod_line_set_value(lines[i], RELAY_DEACTIVE_LOW);
    }

    // Release the lines
    for (i = 0; i < RELAY_LINES; i++) {
        gpiod_line_release(lines[i]);
    }

    // Close the chip
    gpiod_chip_close(fd);

    // Close the log file
    if ((fd = open(LOG_FILE, O_RDWR | O_APPEND)) < 0) {
        perror("open");
        return 1;
    }
    if (fclose(fd) < 0) {
        perror("fclose");
        return 1;
    }

    return 0;
}

