#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <time.h>

#define VALVE_PIN 17
#define NOZZLE_PIN 18
#define VALVE_OPEN 90
#define NOZZLE_ANGLE 0
#define NOZZLE_ANGLE_45 45
#define NOZZLE_ANGLE_90 90
#define NOZZLE_ANGLE_135 135
#define NOZZLE_ANGLE_180 180
#define VALVE_CLOSE 0
#define NOZZLE_STEP 2
#define VALVE_OPEN_THRESHOLD 50
#define VALVE_CLOSE_THRESHOLD 100
#define MAX_RETRIES 3
#define BACKOFF_MS 100

volatile sig_atomic_t stop = 0;

void sig_handler(int sig) {
    gpioServo(NOZZLE_PIN, 0);
    gpioServo(VALVE_PIN, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    int moisture = 0;
    int valve_retries = 0;
    int nozzle_retries = 0;

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "gpioInitialise failed");
        exit(1);
    }

    while (!stop) {
        moisture = (rand() % 80) + 20; // simulate soil moisture reading
        if (moisture < VALVE_OPEN_THRESHOLD) {
            gpioServo(VALVE_PIN, VALVE_OPEN);
            gpioServo(NOZZLE_PIN, NOZZLE_ANGLE);
            for (int i = NOZZLE_ANGLE; i <= NOZZLE_ANGLE_180; i += NOZZLE_STEP) {
                gpioServo(NOZZLE_PIN, i);
                usleep(2000000); // 2 seconds
            }
            gpioServo(NOZZLE_PIN, NOZZLE_ANGLE);
            gpioServo(VALVE_PIN, VALVE_CLOSE);
            usleep(5000000); // 5 seconds
            nozzle_retries = 0;
        } else {
            nozzle_retries++;
            if (nozzle_retries >= 5) {
                syslog(LOG_ERR, "Nozzle failed to reach all angles");
                continue;
            }
        }
        valve_retries = 0;
        while (valve_retries < MAX_RETRIES) {
            if (gpioServo(VALVE_PIN, VALVE_OPEN) < 0) {
                syslog(LOG_ERR, "Failed to open valve");
                usleep(BACKOFF_MS);
                valve_retries++;
            } else {
                break;
            }
        }
        if (valve_retries >= MAX_RETRIES) {
            syslog(LOG_ERR, "Failed to open valve after %d retries", valve_retries);
            continue;
        }
        usleep(5000000); // wait 5 seconds before reading next moisture value
    }

    gpioServo(VALVE_PIN, 0);
    gpioServo(NOZZLE_PIN, 0);

    gpioTerminate();
    return 0;
}

