        fprintf(stderr, "Error setting GPIO23 pull-up resistor: %d\n", gpioSetPullUpDowntime(GPIO23, PI_PUD_UP));
        gpioTerminate();
        return 1;
    }

    // Set GPIO25 and GPIO26 as output
    if (gpioSetMode(GPIO25, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO25 mode: %d\n", gpioSetMode(GPIO25, PI_OUTPUT));
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GPIO26, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO26 mode: %d\n", gpioSetMode(GPIO26, PI_OUTPUT));
        gpioTerminate();
        return 1;
    }

    // Set GPIO25 and GPIO26 as output
