        fprintf(stderr, "Error writing GPIO25: %d\n", gpioWrite(GPIO25, 0));
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(GPIO26, 0) < 0) {
        fprintf(stderr, "Error writing GPIO26: %d\n", gpioWrite(GPIO26, 0));
        gpioTerminate();
        return 1;
