                for (int i = 0; i < steps; i++) {
                    // Set coil 1
                    gpioWrite(GPIO4, 1);
                    gpioWrite(GPIO17, 0);
                    gpioWrite(GPIO27, 0);
                    gpioWrite(GPIO22, 0);
                    // Delay
                    usleep(3000);
                    // Set coil 2
                    gpioWrite(GPIO4, 0);
                    gpioWrite(GPIO17, 1);
                    gpioWrite(GPIO27, 0);
                    gpioWrite(GPIO22, 0);
                    // Delay
                    usleep(3000);
                }
                // De-energize coils
                gpioWrite(GPIO4, 0);
                gpioWrite(GPIO17, 0);
                gpioWrite(GPIO27, 0);
                gpioWrite(GPIO22, 0);
                gpioWrite(GPIO25, 0);
                gpioWrite(GPIO26, 0);
            }
        } else if (gpioRead(GPIO23) == 0) {
            unlockButtonState = 1;
            if (lockButtonState != unlockButtonState) {
                // Unlock
                printf("Unlocking...\n");
                for (int i = 0; i < steps; i++) {
                    // Set coil 1
                    gpioWrite(GPIO4, 0);
                    gpioWrite(GPIO17, 0);
                    gpioWrite(GPIO27, 1);
                    gpioWrite(GPIO22, 0);
                    // Delay
                    usleep(3000);
                    // Set coil 2
                    gpioWrite(GPIO4, 0);
                    gpioWrite(GPIO17, 0);
                    gpioWrite(GPIO27, 0);
                    gpioWrite(GPIO22, 1);
                    // Delay
                    usleep(3000);
                }
                // De-energize coils
                gpioWrite(GPIO4, 0);
                gpioWrite(GPIO17, 0);
                gpioWrite(GPIO27, 0);
                gpioWrite(GPIO22, 0);
                gpioWrite(GPIO25, 0);
                gpioWrite(GPIO26, 0);
            }
        } else {
            lockButtonState = 0;
            unlockButtonState = 0;
        }

        // Check for SIGINT
        if (gpioGetSignal(GPIO24) == SIGINT) {
            printf("SIGINT received, terminating...\n");
            gpioTerminate();
            return 0;
        }
    }

    return 0;
}

