#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

// Define the GPIO chip and pin numbers
#define GPIO_CHIP gpiochip0
#define GPIO_PINS { GPIO17, GPIO18, GPIO27, GPIO22 }

// Define the relay pin numbers
#define RELAY_PINS { 11, 12, 13, 15 }

// Define the log file name
#define LOG_FILE "watering_log.txt"

// Define the interval between waterings in seconds
#define WATERING_INTERVAL 86400

// Define the duration of each watering cycle in seconds
#define WATERING_DURATION 5

// Define the signal handlers
void sigint_handler(int sig) {
    gpio_chip_close(GPIO_CHIP);
    exit(0);
}

void sigterm_handler(int sig) {
    gpio_chip_close(GPIO_CHIP);
    exit(0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open the GPIO chip
    gpiochip_t *chip = gpiochip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiochip_open");
        return 1;
    }

    // Request all four lines as outputs with active-low semantics
    for (size_t i = 0; i < GPIO_PINS.size; i++) {
        gpio_request(chip, GPIO_PINS[i], GPIOF_OUT | GPIOF_DIR | GPIOF_ACTIVE_LOW);
    }

    // Set all lines HIGH (inactive) at startup
    for (size_t i = 0; i < GPIO_PINS.size; i++) {
        gpio_set_value(chip, GPIO_PINS[i], 0);
    }

    // Open the log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        gpiochip_close(chip);
        return 1;
    }

    // Simulate an automated plant watering system
    struct timespec start_time;
    clock_gettime(CLOCK_REALTIME, &start_time);
    while (1) {
        // Activate each relay sequentially for 5 seconds every 24 hours
        for (size_t i = 0; i < GPIO_PINS.size; i++) {
            gpio_set_value(chip, GPIO_PINS[i], 1);
            clock_gettime(CLOCK_REALTIME, &start_time);
            sleep(WATERING_DURATION);
            gpio_set_value(chip, GPIO_PINS[i], 0);
        }

        // Log the start time of each watering cycle
        char log_time[20];
        strftime(log_time, sizeof(log_time), "%Y-%m-%d %H:%M:%S", localtime(&start_time));
        fprintf(log_file, "%s\n", log_time);

        // Wait for 24 hours before the next watering cycle
        sleep(WATERING_INTERVAL);
    }

    // Close the log file
    fclose(log_file);

    // Release all GPIO lines
    for (size_t i = 0; i < GPIO_PINS.size; i++) {
        gpio_set_value(chip, GPIO_PINS[i], 0);
    }

    // Close the GPIO chip
    gpiochip_close(chip);

    return 0;
}

