#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>

#define BUFFER_SIZE 100
#define BUFFER_INDEX 0
#define BUFFER_MAX_VALUE 250.0

// Structure to hold gyroscope data
typedef struct {
    int timestamp;
    float x, y, z;
} GyroscopeData;

// Function to read gyroscope data
void readGyroscope(pigpio *gpio, int i2cHandle) {
    if (gpio->i2cWrite(i2cHandle, 0x43, 6, NULL, 0) < 0) {
        printf("I2C read failed\n");
        return;
    }

    if (gpio->i2cRead(i2cHandle, 0x43, 6, NULL, 0) < 0) {
        printf("I2C read failed, retrying...\n");
        readGyroscope(gpio, i2cHandle);
        return;
    }

    unsigned char data[6];
    gpio->i2cRead(i2cHandle, 0x43, 6, data, 6);

    float x = (data[0] << 8) | data[1];
    float y = (data[2] << 8) | data[3];
    float z = (data[4] << 8) | data[5];

    GyroscopeData *buffer = (GyroscopeData *)malloc(sizeof(GyroscopeData));
    buffer->timestamp = time(NULL);
    buffer->x = x;
    buffer->y = y;
    buffer->z = z;

    if (x > BUFFER_MAX_VALUE || x < -BUFFER_MAX_VALUE || y > BUFFER_MAX_VALUE || y < -BUFFER_MAX_VALUE || z > BUFFER_MAX_VALUE || z < -BUFFER_MAX_VALUE) {
        gpio->gpioWrite(17, 1);
    } else {
        gpio->gpioWrite(17, 0);
    }

    if (bufferIndex >= BUFFER_SIZE) {
        free(buffer);
        return;
    }

    buffer[bufferIndex].timestamp = buffer[bufferIndex].x = buffer[bufferIndex].y = buffer[bufferIndex].z = 0;
    bufferIndex = (bufferIndex + 1) % BUFFER_SIZE;
}

int main(int argc, char **argv) {
    pigpio *gpio = new pigpio();
    if (!gpio) {
        printf("Failed to create pigpio instance\n");
        return 1;
    }

    if (gpio->i2cInit(1, 0x68, GPIO_BCM_DHT22) < 0) {
        printf("I2C initialisation failed\n");
        gpio->Terminate();
        delete gpio;
        return 1;
    }

    if (gpio->i2cWrite(1, 0x6B, 1, NULL, 0) < 0) {
        printf("I2C write failed\n");
        gpio->Terminate();
        delete gpio;
        return 1;
    }

    if (gpio->i2cWrite(1, 0x19, 1, NULL, 0) < 0) {
        printf("I2C write failed\n");
        gpio->Terminate();
        delete gpio;
        return 1;
    }

    if (gpio->i2cWrite(1, 0x1B, 1, NULL, 0) < 0) {
        printf("I2C write failed\n");
        gpio->Terminate();
        delete gpio;
        return 1;
    }

    if (gpio->i2cRead(1, 0x75, 1, NULL, 0) < 0) {
        printf("I2C read failed\n");
        gpio->Terminate();
        delete gpio;
        return 1;
    }

    if (gpio->i2cRead(1, 0x75, 1, NULL, 0) != 0x68) {
        printf("WHO_AM_I register read failed\n");
        gpio->Terminate();
        delete gpio;
        return 1;
    }

    int bufferIndex = 0;
    while (1) {
        readGyroscope(gpio, 1);
        sleep(0.05);
    }

    gpio->Terminate();
    delete gpio;

    return 0;
}

