#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <linux/spi/spidev.h>

#define BUFFER_SIZE 64
#define BUFFER_NAME "/dev/spidev0.0"
#define CHIP_SELECT GPIO_8
#define LED_PIN GPIO_17
#define LED_HIGH 1
#define LED_LOW 0
#define SPI_MODE 0
#define SPI_SPEED 3900000
#define SENSITIVITY 131.0
#define MAX_DEG_S 200.0

int main() {
    int fd, spi_fd, gpio_fd;
    struct spidev *spi;
    struct gpio_array *gpio;
    struct gpio_array_entry *buffer;
    struct timespec start_time;
    struct timespec end_time;
    int i, j;
    int axis, data;
    int led_state = LED_LOW;
    char buffer_str[BUFFER_SIZE * 10 + 1];

    // Initialize GPIO
    gpio = gpio_init();
    if (gpio == NULL) {
        perror("gpio_init");
        return 1;
    }

    // Initialize SPI
    spi_fd = spidev_open(BUFFER_NAME, 0);
    if (spi_fd < 0) {
        perror("spidev_open");
        gpio_close(gpio);
        return 1;
    }

    // Configure SPI
    spi = spidev_open(spi_fd, 0);
    if (spi == NULL) {
        perror("spidev_open");
        spidev_close(spi_fd);
        gpio_close(gpio);
        return 1;
    }

    gpio_fd = gpio_get_fd(CHIP_SELECT);
    if (gpio_fd < 0) {
        perror("gpio_get_fd");
        spidev_close(spi);
        gpio_close(gpio);
        return 1;
    }

    gpio_set_dir(gpio_fd, CHIP_SELECT, GPIO_OUT);
    gpio_set_level(gpio_fd, CHIP_SELECT, LED_LOW);

    // Initialize circular buffer
    buffer = gpio_array_init(BUFFER_SIZE);
    if (buffer == NULL) {
        perror("gpio_array_init");
        spidev_close(spi);
        gpio_close(gpio);
        return 1;
    }

    // Initialize SPI chip-select
    gpio_array_set_chip_select(buffer, CHIP_SELECT);
    gpio_array_set_mode(buffer, SPI_MODE);
    gpio_array_set_speed(buffer, SPI_SPEED);

    // Read gyroscope data
    while (1) {
        // Read gyroscope data
        spi->transfer(0x43, &data, 1);
        axis = (data & 0xFF);
        spi->transfer(0x45, &data, 1);
        axis += (data & 0xFF) << 8;
        spi->transfer(0x47, &data, 1);
        axis += (data & 0xFF) << 16;

        // Convert to degrees per second
        axis = (axis * SENSITIVITY) / 65536.0;

        // Store in circular buffer
        struct timespec now;
        clock_gettime(CLOCK_REALTIME, &now);
        end_time = now;
        now = start_time;
        start_time = end_time;
        end_time = now;
        end_time.tv_sec += 1;
        end_time.tv_nsec += 1000000;
        if (end_time.tv_nsec >= 1000000000) {
            end_time.tv_sec += 1;
            end_time.tv_nsec = 0;
        }

        // Check for overflow
        if (axis > MAX_DEG_S || axis < -MAX_DEG_S) {
            led_state = LED_HIGH;
        } else {
            led_state = LED_LOW;
        }

        // Store in buffer
        gpio_array_set(buffer, i, (int) (end_time.tv_sec * 1000000000 + end_time.tv_nsec / 1000000.0), axis, (int) (end_time.tv_sec * 1000000000 + end_time.tv_nsec / 1000000.0), axis, (int) (end_time.tv_sec * 1000000000 + end_time.tv_nsec / 1000000.0), axis, led_state);
        i = (i + 1) % BUFFER_SIZE;

        // Blink LED
        gpio_set_level(gpio_fd, LED_PIN, led_state);

        // Check for SIGINT
        if (killpg(0, SIGINT) == -1) {
            break;
        }
    }

    // Release resources
    gpio_array_free(buffer);
    spidev_close(spi);
    gpio_close(gpio_fd);
    gpio_close(gpio);

    // Print circular buffer
    for (i = 0; i < BUFFER_SIZE; i++) {
        sprintf(buffer_str, "%d,%d,%d,%d,%d\n", buffer->data[i].time, buffer->data[i].x, buffer->data[i].y, buffer->data[i].z, buffer->data[i].led);
        printf("%s", buffer_str);
    }

    return 0;
}
```

This code uses the `libgpiod` library to control the GPIO and SPI interfaces, and the `spidev` interface to communicate with the gyroscope. It reads the gyroscope data, stores it in a circular buffer, and blinks an LED if any axis exceeds ±200 deg/s. The program also handles SIGINT (Ctrl+C) and prints the entire circular buffer as CSV when the program exits.

