#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>

// Define constants
#define I2C_ADDRESS 0x68
#define I2C_ADDRESS_ACCEL 0x1E
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_X 0x3B
#define ACCEL_Y 0x3C
#define ACCEL_Z 0x3D
#define ACCEL_GYRO 0x3E
#define ACCEL_DATA 0x3F
#define LED_GPIO 21
#define LED_GPIO_DIR 17
#define LOG_FILE "tilt_log.txt"

// Define structures
typedef struct {
    int fd;
    int error;
} I2C_HANDLE;

// Function to initialize I2C
I2C_HANDLE i2c_init(int bus) {
    I2C_HANDLE handle;
    handle.error = 0;
    handle.fd = pigpio_open(bus, I2C_MODE_MASTER);
    if (handle.fd < 0) {
        handle.error = pigpio_geterror();
        return handle;
    }
    pigpio_delay(100);
    pigpio_write(handle.fd, PWR_MGMT_1, 0x00);
    pigpio_delay(100);
    pigpio_write(handle.fd, ACCEL_CONFIG, 0x00);
    pigpio_delay(100);
    return handle;
}

// Function to read accelerometer data
void i2c_read(I2C_HANDLE handle) {
    int error;
    char data[6];
    pigpio_delay(100);
    error = pigpio_read(handle.fd, ACCEL_DATA, data, 6);
    if (error) {
        printf("I2C read error: %d\n", error);
        return;
    }
    int x = (data[0] << 8) | data[1];
    int y = (data[2] << 8) | data[3];
    int z = (data[4] << 8) | data[5];
    double roll = atan2(y, z) * 180 / M_PI;
    double pitch = atan2(-x, sqrt(y * y + z * z)) * 180 / M_PI;
    if (abs(roll) > 45) {
        pigpio_write(LED_GPIO, LED_GPIO_DIR, 1);
    } else {
        pigpio_write(LED_GPIO, LED_GPIO_DIR, 0);
    }
    printf("%.2f %.2f\n", roll, pitch);
    printf("%s %f %f\n", ctime(&time(NULL)), roll, pitch);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s %f %f\n", ctime(&time(NULL)), roll, pitch);
        fclose(log_file);
    }
}

// Function to handle SIGINT
void sigint_handler(int sig) {
    pigpio_close(I2C_HANDLE.fd);
    pigpio_close(LED_GPIO);
    pigpio_close(LED_GPIO_DIR);
    pigpio_close(I2C_HANDLE.fd);
    exit(0);
}

int main() {
    // Initialize signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        printf("Error setting signal handler\n");
        return 1;
    }

    // Initialize I2C
    I2C_HANDLE handle = i2c_init(1);
    if (handle.error) {
        printf("I2C initialization error: %d\n", handle.error);
        return 1;
    }

    // Initialize LED
    pigpio_close(LED_GPIO);
    pigpio_close(LED_GPIO_DIR);
    pigpio_init();
    pigpio_set_mode(LED_GPIO, PI_INPUT);
    pigpio_pull_up(LED_GPIO, PI_PUD_UP);
    pigpio_write(LED_GPIO, LED_GPIO_DIR, 0);

    while (1) {
        i2c_read(handle);
    }

    return 0;
}

