#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <signal.h>
#include <gpiod/gpiod.h>
#include <gpiod/gpiod-async.h>
#include <gpiod/gpiod-async-async.h>

#define I2C_ADDRESS 0x5A
#define I2C_REGISTER_AMBIENT_LIGHT 0x20
#define I2C_REGISTER_PROXIMITY 0x22
#define GPIO_PIN 17
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY 10
#define LOG_FILE "biometric_log.txt"

int main() {
    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    // Open I2C file descriptor
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Open log file
    int log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd < 0) {
        perror("open");
        close(fd);
        return 1;
    }

    // Set up GPIO pin
    struct gpiod_line *line = gpiod_line_create(&gpiod_line_ops, GPIO_PIN, GPIO_DIR_OUT);
    if (!line) {
        perror("gpiod_line_create");
        close(fd);
        close(log_fd);
        return 1;
    }
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);

    // Set up I2C interface
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(fd);
        close(log_fd);
        gpiod_line_release(line);
        return 1;
    }

    // Read and log ambient-light and proximity values
    while (1) {
        int retry_count = 0;
        int i2c_result = i2c_read(fd, I2C_REGISTER_AMBIENT_LIGHT, 2, 0, 0);
        if (i2c_result < 0) {
            if (retry_count < I2C_RETRY_COUNT) {
                usleep(I2C_RETRY_DELAY * 1000);
                retry_count++;
                continue;
            } else {
                perror("i2c_read");
                close(fd);
                close(log_fd);
                gpiod_line_release(line);
                return 1;
            }
        }
        uint16_t ambient_light = i2c_result[0] | (i2c_result[1] << 8);
        i2c_result = i2c_read(fd, I2C_REGISTER_PROXIMITY, 2, 0, 0);
        if (i2c_result < 0) {
            if (retry_count < I2C_RETRY_COUNT) {
                usleep(I2C_RETRY_DELAY * 1000);
                retry_count++;
                continue;
            } else {
                perror("i2c_read");
                close(fd);
                close(log_fd);
                gpiod_line_release(line);
                return 1;
            }
        }
        uint16_t proximity = i2c_result[0] | (i2c_result[1] << 8);
        char log_message[64];
        sprintf(log_message, "%04d-%02d-%02d %02d:%02d:%02d,AmbientLight:%04x,Proximity:%04x", 
                1900 + (time_t)time(NULL) / 1000, 
                (time_t)time(NULL) % 100, 
                (time_t)time(NULL) % 100, 
                (time_t)time(NULL) / 1000 % 24, 
                (time(NULL) % 60), 
                ambient_light, proximity);
        write(log_fd, log_message, strlen(log_message));
        if (proximity > 100) {
            gpiod_line_set_value(line, 1);
        } else {
            gpiod_line_set_value(line, 0);
        }
    }

    // Clean up
    close(fd);
    close(log_fd);
    gpiod_line_release(line);
    return 0;
}

void sigint_handler(int sig) {
    close(fd);
    close(log_fd);
    gpiod_line_release(line);
    exit(0);
}

