#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/statvfs.h>
#include <string.h>
#include <errno.h>

#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_CS 8
#define SPI_DUMMY 0x00
#define SPI_READ 0x80
#define ADXRS290_X 0x02
#define ADXRS290_Y 0x04
#define SENSITIVITY 200

int main() {
    int spi_fd, gyro_fd;
    pigpio *gpio;
    struct timespec start, end;
    struct stat sb;
    char filename[] = "gyro_data.csv";
    int retries = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI file
    if ((gyro_fd = open(filename, O_RDWR | O_CREAT | O_TRUNC, 0644)) < 0) {
        fprintf(stderr, "Failed to open file '%s': %s\n", filename, strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Map file to memory
    if (fstat(gyro_fd, &sb) < 0) {
        fprintf(stderr, "Failed to get file stats: %s\n", strerror(errno));
        close(gyro_fd);
        gpioTerminate();
        return 1;
    }
    if (mmap(gyro_fd, sb.st_size, PROT_READ | PROT_WRITE, MAP_SHARED, -1, 0) == MAP_FAILED) {
        fprintf(stderr, "Failed to map file to memory: %s\n", strerror(errno));
        close(gyro_fd);
        gpioTerminate();
        return 1;
    }

    // Open SPI
    if ((spi_fd = spiOpen(SPI_CS, SPI_MODE, SPI_SPEED)) < 0) {
        fprintf(stderr, "Failed to open SPI: %s\n", strerror(errno));
        munmap(gyro_fd, sb.st_size);
        close(gyro_fd);
        gpioTerminate();
        return 1;
    }

    // Set up SPI
    if (spiXfer(spi_fd, SPI_READ, SPI_DUMMY, 1) < 0) {
        fprintf(stderr, "Failed to set up SPI: %s\n", strerror(errno));
        close(spi_fd);
        munmap(gyro_fd, sb.st_size);
        close(gyro_fd);
        gpioTerminate();
        return 1;
    }

    // Read gyro data
    while (1) {
        // Read X axis
        uint16_t x_rate = 0;
        if (spiXfer(spi_fd, ADXRS290_X | SPI_READ, SPI_DUMMY, 1) < 0) {
            retries++;
            if (retries > 3) {
                break;
            }
            continue;
        }
        x_rate = (uint16_t) ((mmap(gyro_fd, 1, PROT_READ, MAP_SHARED, -1, 0) + SPI_DUMMY) >> 8);

        // Read Y axis
        uint16_t y_rate = 0;
        if (spiXfer(spi_fd, ADXRS290_Y | SPI_READ, SPI_DUMMY, 1) < 0) {
            retries++;
            if (retries > 3) {
                break;
            }
            continue;
        }
        y_rate = (uint16_t) ((mmap(gyro_fd, 1, PROT_READ, MAP_SHARED, -1, 0) + SPI_DUMMY) >> 8);

        // Calculate and log data
        struct timespec now;
