#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/time.h>
#include <signal.h>

#define BUFFER_SIZE 100
#define LED_PIN 17
#define SPI_ADDRESS 0x02
#define SPI_DATA 0x03
#define SPI_SCK GPIO11
#define SPI_MOSI GPIO10
#define SPI_MISO GPIO9
#define SPI_CE0 GPIO8
#define SENSITIVITY 200
#define THRESHOLD 20.0

int led;
int spi;
int buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_size = 0;

void init_led() {
    if (gpioInitialise() < 0) {
        printf("Error initializing GPIO\n");
        exit(1);
    }
    if (gpioMode(LED_PIN, GPIO_MODE_OUTPUT) < 0) {
        printf("Error setting LED mode\n");
        exit(1);
    }
    if (gpioWrite(LED_PIN, 0) < 0) {
        printf("Error setting LED low\n");
        exit(1);
    }
}

void init_spi() {
    if (gpioInitialise() < 0) {
        printf("Error initializing GPIO\n");
        exit(1);
    }
    if (gpioMode(SPI_CE0, GPIO_MODE_OUTPUT) < 0) {
        printf("Error setting SPI CE0 mode\n");
        exit(1);
    }
    if (gpioMode(SPI_SCK, GPIO_MODE_OUTPUT) < 0) {
        printf("Error setting SPI SCK mode\n");
        exit(1);
    }
    if (gpioMode(SPI_MOSI, GPIO_MODE_OUTPUT) < 0) {
        printf("Error setting SPI MOSI mode\n");
        exit(1);
    }
    if (gpioMode(SPI_MISO, GPIO_MODE_INPUT) < 0) {
        printf("Error setting SPI MISO mode\n");
        exit(1);
    }
    if (gpioMode(SPI_CE0, GPIO_MODE_OUTPUT) < 0) {
        printf("Error setting SPI CE0 mode\n");
        exit(1);
    }
    if (gpioWrite(SPI_CE0, 1) < 0) {
        printf("Error setting SPI CE0 high\n");
        exit(1);
    }
}

void read_gyro() {
    struct timespec ts;
    struct timespec now;
    int ret;

    clock_gettime(CLOCK_MONOTONIC, &ts);
    now = ts;

    if (gpioRead(SPI_CE0) < 0) {
        printf("Error reading SPI CE0\n");
        exit(1);
    }

    ret = spiTransfer(SPI_CE0, SPI_SCK, SPI_MOSI, SPI_MISO, SPI_ADDRESS, 1, SPI_MODE_0, 1000000);
    if (ret < 0) {
        printf("Error reading SPI\n");
        exit(1);
    }

    int rate_xl = (spiRead(SPI_MISO) & 0xFF);
    int rate_xh = (spiRead(SPI_MISO) >> 8);
    int rate = (rate_xl << 8) | rate_xh;

    if (rate > 0) {
        double angular_velocity = (double)rate * SENSITIVITY / 65536.0;
        if (abs(angular_velocity) > THRESHOLD) {
            gpioWrite(LED_PIN, 1);
        } else {
            gpioWrite(LED_PIN, 0);
        }
        buffer[buffer_index] = (int)now.tv_sec * 1000000000 + now.tv_nsec;
        buffer_size = (buffer_size + 1) % BUFFER_SIZE;
        if (buffer_size == 0) {
            buffer_size = BUFFER_SIZE;
        }
    }

    if (buffer_size == BUFFER_SIZE) {
        printf("Buffer full, discarding oldest entry\n");
        buffer[buffer_index] = (int)now.tv_sec * 1000000000 + now.tv_nsec;
        buffer_size--;
    }
}

void cleanup() {
    if (gpioTerminate() < 0) {
        printf("Error terminating GPIO\n");
        exit(1);
    }
    if (spiClose() < 0) {
        printf("Error closing SPI\n");
        exit(1);
    }
    if (gpioWrite(LED_PIN, 0) < 0) {
        printf("Error setting LED low\n");
        exit(1);
    }
}

int main() {
    init_led();
    init_spi();

    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        printf("Error setting SIGINT handler\n");
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        printf("Error setting SIGTERM handler\n");
        exit(1);
    }

    while (1) {
        read_gyro();
        usleep(100000);
    }

    cleanup();
    return 0;
}

