#define RELAY3 GPIO_PIN_23
#define RELAY4 GPIO_PIN_24
#define RELAY_VALUE_LOW 0
#define RELAY_VALUE_HIGH 1

int main(int argc, char *argv[]) {
    // Initialize libgpiod
    gpiod_t *gpiod;
    gpiod_init(&gpiod, 0);

    // Open the chip
    gpiod_chip_t *chip;
    gpiod_chip_open(&gpiod, &chip, 0);

    // Open the line
    gpiod_line_t *line;
    gpiod_line_open(&gpiod, chip, "traffic_light", &line);

    // Open the GPIO lines
    gpiod_line_open(&gpiod, chip, "relay1", &line);
    gpiod_line_open(&gpiod, chip, "relay2", &line);
    gpiod_line_open(&gpiod, chip, "relay3", &line);
    gpiod_line_open(&gpiod, chip, "relay4", &line);

    // Set the initial state
    gpiod_line_set_value(&gpiod, line, RELAY1, RELAY_VALUE_LOW);
    gpiod_line_set_value(&gpiod, line, RELAY2, RELAY_VALUE_LOW);
    gpiod_line_set_value(&gpiod, line, RELAY3, RELAY_VALUE_LOW);
    gpiod_line_set_value(&gpiod, line, RELAY4, RELAY_VALUE_LOW);

