        usleep(10000000);

        // Red+yellow state
        gpiod_line_set_value(&gpiod, line, RELAY1, RELAY_VALUE_LOW);
        gpiod_line_set_value(&gpiod, line, RELAY2, RELAY_VALUE_LOW);
        gpiod_line_set_value(&gpiod, line, RELAY3, RELAY_VALUE_LOW);
        gpiod_line_set_value(&gpiod, line, RELAY4, RELAY_VALUE_HIGH);
