        gpiod_line_set_value(&gpiod, line, RELAY4, RELAY_VALUE_HIGH);
        printf("Green\n");
        usleep(10000000);

        // Yellow state
        gpiod_line_set_value(&gpiod, line, RELAY1, RELAY_VALUE_LOW);
        gpiod_line_set_value(&gpiod, line, RELAY2, RELAY_VALUE_LOW);
        gpiod_line_set_value(&gpiod, line, RELAY3, RELAY_VALUE_LOW);
        gpiod_line_set_value(&gpiod, line, RELAY4, RELAY_VALUE_HIGH);
        printf("Yellow\n");
        usleep(3000000);
    }

    // Release resources
    gpiod_line_close(&gpiod, line);
    gpiod_chip_close(&gpiod, chip);
    gpiod_close(&gpiod);

    return 0;
}

void sigint_handler(int sig) {
    // Release resources
    gpiod_line_close(&gpiod, line);
    gpiod_chip_close(&gpiod, chip);
    gpiod_close(&gpiod);

    // Exit
    exit(0);
}

