#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <syslog.h>

#define I2C_ADDRESS 0x5A
#define I2C_BUS 1
#define GPIO_PIN 17
#define RELAY_PIN GPIO_PIN
#define RELAY_VALUE_LOW 0
#define RELAY_VALUE_HIGH 1
#define TOUCH_THRESHOLD 0x0A
#define DEBOUNCE_TIME 0x21
#define CHARGE_TIME 0x0D
#define STOP_MODE 0x00
#define RESET 0x63
#define ENABLE_ELECTRODE 0x5D
#define READ_STATUS 0x00
#define READ_STATUS_MSBS 0x01

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        exit(1);
    }

    // Set GPIO17 as output, default LOW
    if (gpioMode(RELAY_PIN, GPIO_MODE_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO17 as output");
        gpioTerminate();
        exit(1);
    }
    gpioWrite(RELAY_PIN, RELAY_VALUE_LOW);

    // Open I2C device
    int i2c_fd = pigpioOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device");
        gpioTerminate();
        exit(1);
    }

    // Configure MPR121
    if (i2cWrite(i2c_fd, RESET, 0x63) < 0) {
        syslog(LOG_ERR, "Failed to reset MPR121");
        pigpioClose(i2c_fd);
        gpioTerminate();
        exit(1);
    }
    if (i2cWrite(i2c_fd, STOP_MODE, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to set stop mode");
        pigpioClose(i2c_fd);
        gpioTerminate();
        exit(1);
    }
    if (i2cWrite(i2c_fd, ENABLE_ELECTRODE, 0x01) < 0) {
        syslog(LOG_ERR, "Failed to enable electrode 0");
        pigpioClose(i2c_fd);
        gpioTerminate();
        exit(1);
    }
    if (i2cWrite(i2c_fd, TOUCH_THRESHOLD, 0x0A) < 0) {
        syslog(LOG_ERR, "Failed to set touch threshold");
        pigpioClose(i2c_fd);
        gpioTerminate();
        exit(1);
    }
    if (i2cWrite(i2c_fd, READ_STATUS, 0x08) < 0) {
        syslog(LOG_ERR, "Failed to set release threshold");
        pigpioClose(i2c_fd);
        gpioTerminate();
        exit(1);
    }
    if (i2cWrite(i2c_fd, DEBOUNCE_TIME, 0x21) < 0) {
        syslog(LOG_ERR, "Failed to set debounce time");
        pigpioClose(i2c_fd);
        gpioTerminate();
        exit(1);
    }
    if (i2cWrite(i2c_fd, CHARGE_TIME, 0x0D) < 0) {
        syslog(LOG_ERR, "Failed to set charge time");
        pigpioClose(i2c_fd);
        gpioTerminate();
        exit(1);
    }
    if (i2cWrite(i2c_fd, READ_STATUS_MSBS, 0x0D) < 0) {
        syslog(LOG_ERR, "Failed to set run mode");
        pigpioClose(i2c_fd);
        gpioTerminate();
        exit(1);
    }

    // Read touch status every 10 ms
    struct timespec delay;
    struct timespec sleep_time;
    struct itimerval it;
    it.it_value.tv_sec = 0;
    it.it_value.tv_usec = 10;
    it.it_interval.tv_sec = 0;
    it.it_interval.tv_usec = 10;
    while (1) {
        // Read touch status
        int status = i2cRead(i2c_fd, READ_STATUS, 0);
        if (status < 0) {
            syslog(LOG_ERR, "Failed to read touch status");
            pigpioClose(i2c_fd);
            gpioTerminate();
            exit(1);
        }
        int touch_status = (status & 0xFF) << 8 | (i2cRead(i2c_fd, READ_STATUS_MSBS, 0) & 0xFF);
        if (touch_status == 0x00) {
            // Touch detected, toggle relay
            gpioWrite(RELAY_PIN, RELAY_VALUE_HIGH);
        } else {
            // No touch detected, toggle relay
            gpioWrite(RELAY_PIN, RELAY_VALUE_LOW);
        }

        // Debounce touch events
        struct timespec now;
        clock_gettime(CLOCK_REALTIME, &now);
        if (now.tv_sec != it.it_value.tv_sec || now.tv_usec != it.it_value.tv_usec) {
            it.it_value.tv_sec = now.tv_sec;
            it.it_value.tv_usec = now.tv_usec;
            it.it_interval.tv_sec = it.it_interval.tv_sec;
            it.it_interval.tv_usec = it.it_interval.tv_usec;
            itimerval_set(&it);
        }
        nanosleep(&delay, &sleep_time);
    }

    // Handle SIGINT and SIGTERM
    signal(SIGINT, SIG_IGN);
    signal(SIGTERM, SIG_IGN);

    // Close I2C handle and GPIO
    pigpioClose(i2c_fd);
    gpioTerminate();

    return 0;
}

