        int touch_status = (status & 0xFF) << 8 | (i2cRead(i2c_fd, READ_STATUS_MSBS, 0) & 0xFF);
        if (touch_status == 0x00) {
            // Touch detected, toggle relay
            gpioWrite(RELAY_PIN, RELAY_VALUE_HIGH);
        } else {
            // No touch detected, toggle relay
            gpioWrite(RELAY_PIN, RELAY_VALUE_LOW);
        }

        // Debounce touch events
        struct timespec now;
        clock_gettime(CLOCK_REALTIME, &now);
        if (now.tv_sec != it.it_value.tv_sec || now.tv_usec != it.it_value.tv_usec) {
            it.it_value.tv_sec = now.tv_sec;
            it.it_value.tv_usec = now.tv_usec;
            it.it_interval.tv_sec = it.it_interval.tv_sec;
            it.it_interval.tv_usec = it.it_interval.tv_usec;
            itimerval_set(&it);
        }
        nanosleep(&delay, &sleep_time);
    }

    // Handle SIGINT and SIGTERM
    signal(SIGINT, SIG_IGN);
    signal(SIGTERM, SIG_IGN);

    // Close I2C handle and GPIO
    pigpioClose(i2c_fd);
    gpioTerminate();

    return 0;
}
