#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>
#include <signal.h>

#define LOG_FILE "dispense_log.txt"
#define DISPENSE_DURATION 1000
#define DISPENSE_INTERVAL 5000

int dispense_solenoid(pigpio *gpio, int pin, int state) {
    if (gpio->set_mode(pin, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", pin);
        return 1;
    }
    if (gpio->write(pin, state) < 0) {
        syslog(LOG_ERR, "Failed to write to GPIO %d", pin);
        return 1;
    }
    return 0;
}

int dispense_cycle(pigpio *gpio) {
    int solenoid1 = 1;
    int solenoid2 = 0;
    int start_time = 0;
    int end_time = 0;

    if (dispense_solenoid(gpio, 17, solenoid1) != 0) {
        return 1;
    }
    if (dispense_solenoid(gpio, 27, solenoid2) != 0) {
        return 1;
    }

    start_time = gpio->get_time_us();
    gpio->delay_us(DISPENSE_DURATION);
    end_time = gpio->get_time_us();

    if (dispense_solenoid(gpio, 17, 0) != 0) {
        return 1;
    }
    if (dispense_solenoid(gpio, 27, 0) != 0) {
        return 1;
    }

    return 0;
}

int dispense_loop(pigpio *gpio) {
    int ret = 0;
    int last_time = 0;

    while (1) {
        if (dispense_cycle(gpio) != 0) {
            return 1;
        }

        int current_time = gpio->get_time_us();
        if (current_time - last_time >= DISPENSE_INTERVAL) {
            last_time = current_time;
            FILE *log_file = fopen(LOG_FILE, "a");
            if (log_file == NULL) {
                syslog(LOG_ERR, "Failed to open log file %s", LOG_FILE);
                return 1;
            }
            fprintf(log_file, "%d %d %d %d\n", current_time / 1000, 17, 27, DISPENSE_DURATION);
            fclose(log_file);
        }
    }
}

int main(int argc, char **argv) {
    pigpio *gpio = pigpio_init();
    if (gpio == NULL) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return 1;
    }

    if (gpio->init() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        pigpio_exit(gpio);
        return 1;
    }

    if (gpio->get_version() != 0) {
        syslog(LOG_ERR, "Failed to get pigpio version");
        pigpio_exit(gpio);
        return 1;
    }

    if (gpio->get_mode(17) != 0) {
        syslog(LOG_ERR, "GPIO 17 is not available");
        pigpio_exit(gpio);
        return 1;
    }
    if (gpio->get_mode(27) != 0) {
        syslog(LOG_ERR, "GPIO 27 is not available");
        pigpio_exit(gpio);
        return 1;
    }

    if (dispense_loop(gpio) != 0) {
        return 1;
    }

    return 0;
}

void sigint_handler(int sig) {
    pigpio_exit(gpio);
    exit(0);
}

int main(int argc, char **argv) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set SIGINT handler");
        return 1;
    }

    if (atexit(pigpio_exit)) {
        syslog(LOG_ERR, "Failed to register pigpio exit handler");
        return 1;
    }

    return main(argc, argv);
}

