    int motor_b_forward = 22;
    int motor_b_backward = 23;
    int enable_a = 24;
    int enable_b = 25;
    int log_fd = -1;
    int pid = -1;
    int error = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set motor modes to PWM
    gpioSetMode(motor_a_forward, PIROUTPUT);
    gpioSetMode(motor_a_backward, PIROUTPUT);
    gpioSetMode(motor_b_forward, PIROUTPUT);
    gpioSetMode(motor_b_backward, PIROUTPUT);
    gpioSetMode(enable_a, PIROUTPUT);
    gpioSetMode(enable_b, PIROUTPUT);

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set up PID controller
    double kp = 1.0;
    double ki = 0.01;
    double kd = 0.1;
    double tilt_error = 0.0;
    double distance = 0.0;
    double motor_a_speed = 0.0;
    double motor_b_speed = 0.0;
    double dt = 0.05;

    while (1) {
        // Simulate tilt error
        tilt_error = (double)rand() / RAND_MAX * 20.0 - 10.0;

        // Simulate distance
        distance = (double)rand() / RAND_MAX * 400.0;

        // PID control
        double error = tilt_error;
        double output = kp * error + ki * (error + dt * (motor_a_speed + motor_b_speed) / 2) + kd * dt * (motor_a_speed - motor_b_speed);
        motor_a_speed = clamp(output * MAX_MOTOR_SPEED / (2 * kp), MIN_MOTOR_SPEED, MAX_MOTOR_SPEED);
        motor_b_speed = clamp(output * MAX_MOTOR_SPEED / (2 * kp), MIN_MOTOR_SPEED, MAX_MOTOR_SPEED);

        // Obstacle avoidance
        if (distance < 20.0) {
            motor_a_speed = motor_b_speed = 50.0;
        }

        // Set motor speeds
        gpioWrite(motor_a_forward, motor_a_speed);
        gpioWrite(motor_a_backward, 0);
        gpioWrite(motor_b_forward, motor_b_speed);
        gpioWrite(motor_b_backward, 0);

        // Enable motors
        gpioWrite(enable_a, 1);
        gpioWrite(enable_b, 1);

        // Log data
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_fd, "%s %f %f %f %f\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);

        // Delay
        gpioDelay((unsigned int)(dt * 1000000));

        // Check for SIGINT
        if (killpg(pid, SIGINT) == -1) {
            break;
        }
    }

    // Stop motors
    gpioWrite(motor_a_forward, 0);
    gpioWrite(motor_a_backward, 0);
    gpioWrite(motor_b_forward, 0);
    gpioWrite(motor_b_backward, 0);

    // Disable motors
    gpioWrite(enable_a, 0);
    gpioWrite(enable_b, 0);

    // Close log file
    if (close(log_fd) < 0) {
        perror("close");
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

double clamp(double value, double min, double max) {
    if (value < min) {
        return min;
    } else if (value > max) {
        return max;
    } else {
        return value;
    }
}
