// Initialize pigpio
void init_pigpio() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(1);
    }
}

// Release pigpio resources
void cleanup_pigpio() {
    gpioTerminate();
}

// Toggle relay state
void toggle_relay() {
    int relay_state = 0;
    FILE *file = fopen(RELAY_STATE_FILE, "r");
    if (file == NULL) {
        perror("fopen");
        return;
    }
    if (fscanf(file, "%d", &relay_state) != 1) {
        perror("fscanf");
        fclose(file);
        return;
    }
    fclose(file);

    if (relay_state) {
        gpioWrite(RELAY_PIN, 0);
    } else {
        gpioWrite(RELAY_PIN, 1);
    }
}

// Debounce touch detection
void debounce_touch() {
    int touch_state = gpioRead(TOUCH_PIN);
    if (touch_state == 1) {
        sleep(TOUCH_DEBOUNCE_TIME);
        if (gpioRead(TOUCH_PIN) == 0) {
            toggle_relay();
        }
    }
}

int main() {
    // Signal handling
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    // Initialize pigpio
    init_pigpio();

    // Configure touch pin as input with internal pull-up
    gpioSetMode(TOUCH_PIN, PI_INPUT);
    gpioPullUp(TOUCH_PIN, PI_HIGH);

    // Toggle relay on initial state
    toggle_relay();

    while (1) {
        debounce_touch();
        sleep(0.1);
    }

    // Clean up
    cleanup_pigpio();
    return 0;
}

