#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDRESS 0x29
#define I2C Bus 1
#define REG_POWER_ON 0x80
#define REG_RGBC_ENABLE 0x03
#define REG_INTEGRATION_TIME 0x81
#define REG_DATA 0x14
#define REG_DATA_END 0x1A

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Initialize I2C
    if (i2cInit(I2C Bus, I2C_ADDRESS) < 0) {
        perror("i2cInit");
        gpioTerminate();
        return 1;
    }

    // Set power-on and RGBC enable
    if (i2cWrite(I2C Bus, REG_POWER_ON, 0x03) < 0) {
        perror("i2cWrite");
        i2cClose(I2C Bus);
        gpioTerminate();
        return 1;
    }

    // Set integration time
    if (i2cWrite(I2C Bus, REG_INTEGRATION_TIME, 0xD5) < 0) {
        perror("i2cWrite");
        i2cClose(I2C Bus);
        gpioTerminate();
        return 1;
    }

    // Open file for writing
    FILE *file = fopen("color_data.csv", "w");
    if (file == NULL) {
        perror("fopen");
        i2cClose(I2C Bus);
        gpioTerminate();
        return 1;
    }

    // Register SIGINT and SIGTERM handlers
    struct sigaction sa;
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        fclose(file);
        i2cClose(I2C Bus);
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        fclose(file);
        i2cClose(I2C Bus);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read data
        uint8_t data[5];
        if (i2cRead(I2C Bus, REG_DATA, data, 5) < 0) {
            perror("i2cRead");
            i2cClose(I2C Bus);
            gpioTerminate();
            return 1;
        }

        // Log data
        time_t now = time(NULL);
        fprintf(file, "%ld,%d,%d,%d,%d\n", now, data[0], data[1], data[2], data[3]);

        // Delay
        gpioDelay(500);

        // Reset sensor values
        if (i2cWrite(I2C Bus, REG_DATA, 0) < 0) {
            perror("i2cWrite");
            i2cClose(I2C Bus);
            gpioTerminate();
            return 1;
        }
        if (i2cWrite(I2C Bus, REG_DATA + 1, 0) < 0) {
            perror("i2cWrite");
            i2cClose(I2C Bus);
            gpioTerminate();
            return 1;
        }
        if (i2cWrite(I2C Bus, REG_DATA + 2, 0) < 0) {
            perror("i2cWrite");
            i2cClose(I2C Bus);
            gpioTerminate();
            return 1;
        }
        if (i2cWrite(I2C Bus, REG_DATA + 3, 0) < 0) {
            perror("i2cWrite");
            i2cClose(I2C Bus);
            gpioTerminate();
            return 1;
        }
        if (i2cWrite(I2C Bus, REG_DATA + 4, 0) < 0) {
            perror("i2cWrite");
            i2cClose(I2C Bus);
            gpioTerminate();
            return 1;
        }
    }

    // Close file and I2C
    fclose(file);
    i2cClose(I2C Bus);
    gpioTerminate();

    return 0;
}

