#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod/gpiod.h>

#define RELAY_PINS (11, 13, 15, 17)
#define RELAY_GPIO_MAP (GPIO17, GPIO27, GPIO22, GPIO23)
#define RELAY_NAME "relays"
#define RELAY_VALUE_ON 0
#define RELAY_VALUE_OFF 1
#define RELAY_DUTY_CYCLE_MAX 100
#define RELAY_DUTY_CYCLE_MIN 0
#define RELAY_BRIGHTNESS_INCREMENT 10
#define RELAY_BRIGHTNESS_DECREMENT 10
#define RELAY CycleDuration Sunrise 3600
#define RELAY CycleDuration Daytime 21600
#define RELAY CycleDuration Sunset 3600
#define RELAY CycleDuration Nighttime 172800

int main(int argc, char *argv[]) {
    gpiod_chip_t *chip;
    gpiod_line_t *line;
    int i, j, duty_cycle, brightness;
    struct gpiod_chip_info info;

    // Initialize signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Open the chip
    chip = gpiod_chip_open_by_name(RELAY_NAME, 0, NULL);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    // Get chip info
    if (gpiod_chip_get_info(chip, &info) == -1) {
        perror("gpiod_chip_get_info");
        gpiod_chip_close(chip);
        return 1;
    }

    // Open lines
    for (i = 0; i < 4; i++) {
        line = gpiod_line_get(chip, info.gpio, RELAY_GPIO_MAP[i]);
        if (!line) {
            perror("gpiod_line_get");
            gpiod_chip_close(chip);
            return 1;
        }
        if (gpiod_line_request_output(line) == -1) {
            perror("gpiod_line_request_output");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Main loop
    while (1) {
        // Sunrise phase
        for (i = 0; i < RELAY_DUTY_CYCLE_MAX; i++) {
            for (j = 0; j < 4; j++) {
                gpiod_line_set_value(line[j], RELAY_VALUE_ON);
            }
            usleep(100000);
            duty_cycle = (RELAY_DUTY_CYCLE_MAX - i) * 100 / RELAY_DUTY_CYCLE_MAX;
            for (j = 0; j < 4; j++) {
                gpiod_line_set_value(line[j], (duty_cycle > 0) ? RELAY_VALUE_ON : RELAY_VALUE_OFF);
            }
            usleep(100000);
        }

        // Daytime phase
        for (i = 0; i < RELAY_BRIGHTNESS_INCREMENT; i++) {
            for (j = 0; j < 4; j++) {
                gpiod_line_set_value(line[j], RELAY_VALUE_ON);
            }
            usleep(100000);
            brightness = (RELAY_BRIGHTNESS_INCREMENT - i) * 100 / RELAY_BRIGHTNESS_INCREMENT;
            for (j = 0; j < 4; j++) {
                gpiod_line_set_value(line[j], (brightness > 0) ? RELAY_VALUE_ON : RELAY_VALUE_OFF);
            }
            usleep(100000);
        }

        // Sunset phase
        for (i = RELAY_BRIGHTNESS_INCREMENT - 1; i >= 0; i--) {
            for (j = 0; j < 4; j++) {
                gpiod_line_set_value(line[j], RELAY_VALUE_ON);
            }
            usleep(100000);
            brightness = (i * 100 / RELAY_BRIGHTNESS_INCREMENT);
            for (j = 0; j < 4; j++) {
                gpiod_line_set_value(line[j], (brightness > 0) ? RELAY_VALUE_ON : RELAY_VALUE_OFF);
            }
            usleep(100000);
        }

        // Nighttime phase
        for (i = 0; i < RELAY CycleDuration Nighttime; i++) {
            for (j = 0; j < 4; j++) {
                gpiod_line_set_value(line[j], RELAY_VALUE_OFF);
            }
            usleep(100000);
        }
    }

    // Clean up
    for (i = 0; i < 4; i++) {
        gpiod_line_release(line[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}

void sigint_handler(int sig) {
    // Turn off all relays
    for (int i = 0; i < 4; i++) {
        gpiod_line_set_value(gpiod_line_get(chip, info.gpio, RELAY_GPIO_MAP[i]), RELAY_VALUE_OFF);
    }

    // Release GPIO resources
    for (int i = 0; i < 4; i++) {
        gpiod_line_release(gpiod_line_get(chip, info.gpio, RELAY_GPIO_MAP[i]));
    }

    // Close the chip
    gpiod_chip_close(chip);

    // Exit
    exit(0);
}

