#define VIDEO_DIR "/home/pi/videos"
#define LOG_FILE "/home/pi/logs/motion_log.txt"

// Initialize pigpio
void init_pigpio() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(1);
    }
}

// Debounce function
void debounce(int pin, int timeout) {
    int last_state = 0;
    int current_state = 0;
    int last_change_time = 0;
    int timeout_counter = 0;

    while (1) {
        current_state = gpioGet(pin);
        if (current_state != last_state) {
            last_change_time = time(NULL);
            last_state = current_state;
        }

        if (current_state == 0 && last_state == 1) {
            if (time(NULL) - last_change_time > timeout) {
                return;
            }
        } else if (current_state == 1 && last_state == 0) {
            if (time(NULL) - last_change_time > timeout) {
                return;
            }
        }

        usleep(10000); // 10ms
        timeout_counter++;
        if (timeout_counter > 100) {
            return;
        }
    }
}

// Record video and log motion events
void record_motion() {
    char filename[256];
    struct stat info;
    struct timespec start_time;
    struct timespec end_time;
    FILE *log_file;
    FILE *video_file;

    // Get current timestamp
    clock_gettime(CLOCK_REALTIME, &start_time);

    // Create video file
    sprintf(filename, "%s/%s.h264", VIDEO_DIR, ctime(&start_time.tv_sec));
    if (stat(filename, &info) != 0) {
        mkdir(VIDEO_DIR, 0777);
        if (stat(filename, &info) != 0) {
            perror("mkdir");
            return;
        }
    }

    // Open video file
    video_file = fopen(filename, "wb");
    if (video_file == NULL) {
        perror("fopen");
        return;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        fclose(video_file);
        return;
    }

    // Set up video recording
    pigpio = pigpio;
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioPullUpDnControl(GPIO_PIN, PI_PUD_UP);
    gpioEdgeMode(GPIO_PIN, PI_EDGE_BOTH);

    // Record video and log motion events
    while (1) {
        debounce(GPIO_PIN, DEBOUNCE_TIME);
        int state = gpioGet(GPIO_PIN);
        if (state == 0) {
            // Motion detected
            fprintf(log_file, "%s Motion detected at %s\n", ctime(&start_time), ctime(&end_time));
            fprintf(log_file, "%s\n", filename);
            fclose(log_file);
            log_file = fopen(LOG_FILE, "a");
            if (log_file == NULL) {
                perror("fopen");
                return;
            }
        }

        // Record video frame
        pigpioDelay(1000); // 1s
        pigpioWrite(GPIO_PIN, 0);
        pigpioDelay(1000); // 1s
        pigpioWrite(GPIO_PIN, 1);
        pigpioDelay(1000); // 1s
        pigpioWrite(GPIO_PIN, 0);
