#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>
#include <syslog.h>

// Define constants for GPIO pins
#define RELAY_PINS {4, 17, 27, 22}

// Define constants for log file
#define LOG_FILE "irrigation_log.txt"

// Define constants for relay states
#define RELAY_HIGH 0
#define RELAY_LOW 1

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Seed random number generator
    srand(time(NULL));

    // Define relay states
    int relays[4] = {RELAY_LOW, RELAY_LOW, RELAY_LOW, RELAY_LOW};

    while (1) {
        // Read moisture sensor readings
        int readings[4];
        for (int i = 0; i < 4; i++) {
            readings[i] = rand() % 101;
        }

        // Log sensor readings and relay states
        for (int i = 0; i < 4; i++) {
            fprintf(log_file, "%d %d %d %d %d\n", i, readings[i], relays[i], time(NULL), time(NULL));
        }

        // Update relay states
        for (int i = 0; i < 4; i++) {
            if (readings[i] < 30) {
                relays[i] = RELAY_LOW;
            } else {
                relays[i] = RELAY_HIGH;
            }
        }

        // Set relay states
        for (int i = 0; i < 4; i++) {
            gpioWrite(RELAY_PINS[i], relays[i]);
        }

        // Sleep for 5 seconds
        sleep(5);
    }

    // Deactivate all relays
    for (int i = 0; i < 4; i++) {
        gpioWrite(RELAY_PINS[i], RELAY_LOW);
    }

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

