#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

#define ADXL345_I2C_ADDRESS 0x53
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAX2 0x34
#define ADXL345_DATAY0 0x35
#define ADXL345_DATAY1 0x36
#define ADXL345_DATAY2 0x37
#define ADXL345_DATAZ0 0x38
#define ADXL345_DATAZ1 0x39
#define ADXL345_DATAZ2 0x3A
#define ADXL345_GYRO 0x32
#define ADXL345_ACCEL_X 0x00
#define ADXL345_ACCEL_Y 0x01
#define ADXL345_ACCEL_Z 0x02
#define ADXL345_GYRO_X 0x03
#define ADXL345_GYRO_Y 0x04
#define ADXL345_GYRO_Z 0x05

#define ADXL345_SCALE 256
#define ADXL345_GForce 0.2

int main(int argc, char **argv) {
    int i2c_fd;
    int gpio_fd;
    int i;
    int x, y, z;
    int x1, y1, z1;
    int x2, y2, z2;
    int freefall_detected = 0;
    int freefall_confirmed = 0;
    struct timespec start_time;
    struct timespec end_time;
    struct timespec delay;
    struct stat sb;
    char log_file[256];
    char timestamp[32];
    char freefall_log[256];

    // Initialize pigpio
    if (gpio_init() < 0) {
        perror("gpio_init");
        return 1;
    }

    // Open I2C
    if ((i2c_fd = i2c_open(ADXL345_I2C_ADDRESS, I2C_MODE_READ, 100)) < 0) {
        perror("i2c_open");
        return 1;
    }

    // Configure ADXL345
    if (i2c_write(i2c_fd, ADXL345_DATA_FORMAT, 0x0B) < 0) {
        perror("i2c_write");
        return 1;
    }
    if (i2c_write(i2c_fd, ADXL345_POWER_CTL, 0x08) < 0) {
        perror("i2c_write");
        return 1;
    }

    // Set up GPIO for alarm
    if (gpio_mode(27, GPIO_MODE_OUTPUT) < 0) {
        perror("gpio_mode");
        return 1;
    }
    if (gpio_write(27, 1) < 0) {
        perror("gpio_write");
        return 1;
    }

    // Set up log file
    sprintf(log_file, "/var/log/freefall.log");
    if (mkdir(log_file, 0777) < 0) {
        perror("mkdir");
        return 1;
    }

    // Main loop
    while (1) {
        // Read data
        if (i2c_read(i2c_fd, ADXL345_DATAX0, 6, &x, &y, &z) < 0) {
            perror("i2c_read");
            continue;
        }
        if (i2c_read(i2c_fd, ADXL345_DATAX1, 6, &x1, &y1, &z1) < 0) {
            perror("i2c_read");
            continue;
        }
        if (i2c_read(i2c_fd, ADXL345_DATAX2, 6, &x2, &y2, &z2) < 0) {
            perror("i2c_read");
            continue;
        }

        // Convert to g-force
        x = (x * ADXL345_SCALE) / 16384;
        y = (y * ADXL345_SCALE) / 16384;
        z = (z * ADXL345_SCALE) / 16384;

        // Check for freefall
        if (x < -ADXL345_GForce && y < -ADXL345_GForce && z < -ADXL345_GForce) {
            if (!freefall_detected) {
                freefall_detected = 1;
                start_time.tv_sec = time(NULL);
                start_time.tv_nsec = 0;
            }
        } else if (freefall_detected) {
            if (x > ADXL345_GForce && y > ADXL345_GForce && z > ADXL345_GForce) {
                freefall_confirmed = 1;
                end_time.tv_sec = time(NULL);
                end_time.tv_nsec = 0;
            }
            if (freefall_confirmed) {
                // Log freefall event
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&start_time));
                sprintf(freefall_log, "%s,%f,%f,%f\n", timestamp, x, y, z);
                FILE *log_file_ptr = fopen(log_file, "a");
                if (log_file_ptr == NULL) {
                    perror("fopen");
                    continue;
                }
                fprintf(log_file_ptr, "%s", freefall_log);
                fclose(log_file_ptr);

                // Simulate alarm
                for (i = 0; i < 5; i++) {
                    gpio_write(27, 1);
                    usleep(1000000);
                    gpio_write(27, 0);
                    usleep(1000000);
                }

                // Reset freefall variables
                freefall_detected = 0;
                freefall_confirmed = 0;
            }
        }

        // Check for freefall for 0.5 seconds
        if (freefall_detected && (time(NULL) - start_time.tv_sec) >= 0.5) {
            freefall_detected = 0;
        }

        // Check for freefall for 0.5 seconds again
        if (freefall_detected && (time(NULL) - start_time.tv_sec) >= 1.0) {
            freefall_detected = 0;
        }

        // Check for I2C errors
        if (i2c_is_err(i2c_fd)) {
            perror("i2c_is_err");
            continue;
        }
    }

    // Close I2C
    if (i2c_close(i2c_fd) < 0) {
        perror("i2c_close");
        return 1;
    }

    // Close GPIO
    if (gpio_close(27) < 0) {
        perror("gpio_close");
        return 1;
    }

    // Close log file
    if (close(0) < 0) {
        perror("close");
        return 1;
    }

    return 0;
}

