        pthread_mutex_lock(&g_mutex);
        g_last_trig_time = g_last_trig_time + PULSE_WIDTH_US;
        pthread_mutex_unlock(&g_mutex);
    }

    pthread_mutex_lock(&g_mutex);
    g_last_valid_distance = 0;
    g_last_valid_distance_ns = 0;
    g_last_valid_distance_ns_count = 0;
    pthread_mutex_unlock(&g_mutex);

    pthread_cancel(trig_thread_id);
