    pthread_join(trig_thread_id, NULL);
    pthread_join(echo_thread_id, NULL);

    pigpio_close(g_trig_pin);
    pigpio_close(g_echo_pin);
    pigpio_cleanup();
    close(g_pigpio);
    return 0;
}

