#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>
#include <libgpiod-cdev.h>

// Define constants
#define BUFFER_SIZE 5
#define ALERT_PIN 22
#define LEFT_PIN 4
#define CENTER_PIN 17
#define RIGHT_PIN 27
#define LINE_SPEED 10  // placeholder for motor control
#define ALERT_DURATION 2000  // 2 seconds

// Define structures
typedef struct {
    int left;
    int center;
    int right;
} SensorReading;

// Define functions
void init_gpiod(void);
void cleanup_gpiod(void);
void handle_alert(void);
void log_sensor_readings(SensorReading *buffer);
void update_motor_control(SensorReading *buffer);
void handle_sigint(int sig);
void handle_sigterm(int sig);

int main(int argc, char **argv) {
    // Initialize libgpiod
    if (init_gpiod() != 0) {
        printf("Error initializing libgpiod\n");
        return 1;
    }

    // Initialize GPIO pins
    if (gpiod_init_pin(LEFT_PIN, GPIOD_DIR_IN, GPIOD_INT_EDGE_RISING, NULL) != 0) {
        printf("Error initializing GPIO pin %d\n", LEFT_PIN);
        cleanup_gpiod();
        return 1;
    }
    if (gpiod_init_pin(CENTER_PIN, GPIOD_DIR_IN, GPIOD_INT_EDGE_RISING, NULL) != 0) {
        printf("Error initializing GPIO pin %d\n", CENTER_PIN);
        cleanup_gpiod();
        return 1;
    }
    if (gpiod_init_pin(RIGHT_PIN, GPIOD_DIR_IN, GPIOD_INT_EDGE_RISING, NULL) != 0) {
        printf("Error initializing GPIO pin %d\n", RIGHT_PIN);
        cleanup_gpiod();
        return 1;
    }
    if (gpiod_init_pin(ALERT_PIN, GPIOD_DIR_OUT, GPIOD_DIR_HIGH, NULL) != 0) {
        printf("Error initializing GPIO pin %d\n", ALERT_PIN);
        cleanup_gpiod();
        return 1;
    }

    // Initialize sensor buffer
    SensorReading buffer[BUFFER_SIZE];
    memset(buffer, 0, sizeof(buffer));

    // Main loop
    while (1) {
        // Read sensor values
        int left = gpiod_read(LEFT_PIN);
        int center = gpiod_read(CENTER_PIN);
        int right = gpiod_read(RIGHT_PIN);

        // Log sensor readings
        log_sensor_readings(buffer);

        // Update motor control
        update_motor_control(buffer);

        // Check for alert condition
        if (center == 0 && (left == 0 || right == 0)) {
            handle_alert();
        }

        // Sleep for 10 ms
        usleep(10000);
    }

    // Clean up
    cleanup_gpiod();
    return 0;
}

void init_gpiod(void) {
    gpiod_init();
    return 0;
}

void cleanup_gpiod(void) {
    gpiod_cleanup();
    return 0;
}

void handle_alert(void) {
    gpiod_write(ALERT_PIN, GPIOD_DIR_HIGH);
    sleep(ALERT_DURATION / 1000);
    gpiod_write(ALERT_PIN, GPIOD_DIR_LOW);
    return;
}

void log_sensor_readings(SensorReading *buffer) {
    buffer[0] = gpiod_read(LEFT_PIN);
    buffer[1] = gpiod_read(CENTER_PIN);
    buffer[2] = gpiod_read(RIGHT_PIN);
    if (buffer[0] == 0 && buffer[1] == 0 && buffer[2] == 0) {
        buffer[0] = 0;
        buffer[1] = 0;
        buffer[2] = 0;
    }
    return;
}

void update_motor_control(SensorReading *buffer) {
    if (buffer[1] == 0) {
        // Move forward
        LINE_SPEED = 10;
    } else if (buffer[0] == 0) {
        // Turn left
        LINE_SPEED = -10;
    } else if (buffer[2] == 0) {
        // Turn right
        LINE_SPEED = 10;
    } else {
        // Stop
        LINE_SPEED = 0;
    }
    return;
}

void handle_sigint(int sig) {
    cleanup_gpiod();
    exit(0);
}

void handle_sigterm(int sig) {
    cleanup_gpiod();
    exit(0);
}

