    if (gpioWrite(RELAY_PIN, RELAY_VALUE) < 0) {
        fprintf(stderr, "Failed to set relay value\n");
        gpioMode(RELAY_PIN, PI_INPUT);
        i2cClose(i2c_handle);
        pigpioTerminate();
        return 1;
    }

    // Set up I2C read/write functions
    void (*i2cReadByte)(int, int, int*) = i2cReadByte;
    void (*i2cWriteByte)(int, int, int) = i2cWriteByte;
    void (*i2cReadByteData)(int, int, int*, int*) = i2cReadByteData;
    void (*i2cWriteByteData)(int, int, int, int) = i2cWriteByteData;

    i2cReadByte = (void (*)(int, int, int*))dlsym(i2c_fd, "i2cReadByte");
    if (i2cReadByte == NULL) {
        fprintf(stderr, "Failed to get i2cReadByte symbol\n");
        i2cClose(i2c_handle);
        pigpioTerminate();
        return 1;
    }

    i2cWriteByte = (void (*)(int, int, int))dlsym(i2c_fd, "i2cWriteByte");
    if (i2cWriteByte == NULL) {
