#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>

#define RELAY_GPIO 18
#define RELAY_LOG_FILE "relay_log.txt"

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int sig) {
    // Close all sockets
    close(sock);
    // Close the log file
    fclose(log_file);
    // Turn off the relay
    pigpio_close(RELAY_GPIO);
    // Terminate pigpio
    pigpioTerminate();
    // Exit the program
    exit(0);
}

int main() {
    // Initialize pigpio
    if (pigpioInit() != PI_OK) {
        perror("pigpioInit");
        return 1;
    }

    // Open the log file for writing
    log_file = fopen(RELAY_LOG_FILE, "w");
    if (log_file == NULL) {
        perror("fopen");
        pigpioTerminate();
        return 1;
    }

    // Create a socket
    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket");
        pigpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Bind the socket to port 5000
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(5000);
    server_addr.sin_addr.s_addr = INADDR_ANY;
    if (bind(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind");
        close(sock);
        pigpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Listen for incoming connections
    if (listen(sock, 3) < 0) {
        perror("listen");
        close(sock);
        pigpioTerminate();
        fclose(log_file);
        return 1;
    }

    printf("Server listening on port 5000...\n");

    while (1) {
        // Accept an incoming connection
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_sock = accept(sock, (struct sockaddr *)&client_addr, &client_len);
        if (client_sock < 0) {
            perror("accept");
            continue;
        }

        char buffer[256];
        // Read the command from the client
        if (read(client_sock, buffer, 256) < 0) {
            perror("read");
            close(client_sock);
            continue;
        }
        buffer[read(client_sock, buffer, 256)] = '\0'; // Null-terminate the string

        // Convert the command to uppercase
        for (int i = 0; i < strlen(buffer); i++) {
            buffer[i] = toupper(buffer[i]);
        }

        // Check if the command is "ON" or "OFF"
        if (strcmp(buffer, "ON") == 0) {
            // Turn on the relay
            if (pigpioWrite(RELAY_GPIO, PI_HIGH) != PI_OK) {
                perror("pigpioWrite");
                close(client_sock);
                continue;
            }
            fprintf(log_file, "%s %s\n", ctime(localtime(time(NULL)), "Relay turned ON");
        } else if (strcmp(buffer, "OFF") == 0) {
            // Turn off the relay
            if (pigpioWrite(RELAY_GPIO, PI_LOW) != PI_OK) {
                perror("pigpioWrite");
                close(client_sock);
                continue;
            }
            fprintf(log_file, "%s %s\n", ctime(localtime(time(NULL)), "Relay turned OFF");
        } else {
            // Log an invalid command
            fprintf(log_file, "%s %s\n", ctime(localtime(time(NULL)), "Invalid command");
        }

        // Close the client socket
        close(client_sock);
    }

    // Close the server socket
    close(sock);

    // Close the log file
    fclose(log_file);

    // Terminate pigpio
    pigpioTerminate();

    return 0;
}

