#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>

#define PI_GPIO_18 18
#define PI_GPIO_19 19
#define PI_I2C Bus 1
#define SLF3S_ADDR1 0x08
#define SLF3S_ADDR2 0x09
#define SLF3S_CMD_START 0x36
#define SLF3S_CMD_ABORT 0x37
#define SLF3S_SCALE 1.0 / 1500.0
#define SLF3S_CRC 0x31
#define SLF3S_INIT 0xFF

volatile int stop = 0;

void sigint_handler(int sig) {
    stop = 1;
}

int main() {
    int i, j, ret;
    pigpio *gpio = pigpio_get();
    if (!gpio) {
        fprintf(stderr, "pigpio_get() failed\n");
        return 1;
    }

    if (gpio->i2cOpen(PI_I2C, SLF3S_ADDR1, 0, 1000) < 0) {
        gpio->i2cClose(PI_I2C, SLF3S_ADDR1);
        gpio->i2cOpen(PI_I2C, SLF3S_ADDR2, 0, 1000);
        if (gpio->i2cOpen(PI_I2C, SLF3S_ADDR2, 0, 1000) < 0) {
            fprintf(stderr, "i2cOpen() failed\n");
            gpio->i2cClose(PI_I2C, SLF3S_ADDR1);
            return 1;
        }
    }

    if (gpio->i2cWrite(PI_I2C, SLF3S_ADDR1, &SLF3S_CMD_START, 1) < 0) {
        gpio->i2cClose(PI_I2C, SLF3S_ADDR1);
        gpio->i2cClose(PI_I2C, SLF3S_ADDR2);
        return 1;
    }

    if (gpio->i2cWrite(PI_I2C, SLF3S_ADDR2, &SLF3S_CMD_START, 1) < 0) {
        gpio->i2cClose(PI_I2C, SLF3S_ADDR1);
        gpio->i2cClose(PI_I2C, SLF3S_ADDR2);
        return 1;
    }

    if (gpio->gpioWrite(PI_GPIO_18, 0) < 0) {
        gpio->i2cClose(PI_I2C, SLF3S_ADDR1);
        gpio->i2cClose(PI_I2C, SLF3S_ADDR2);
        return 1;
    }

    for (;;) {
        if (stop) break;

        for (i = 0; i < 3; i++) {
            int data1[3], data2[3];
            int crc1, crc2;

            if (gpio->i2cRead(PI_I2C, SLF3S_ADDR1, data1, 3) < 0) {
                fprintf(stderr, "i2cRead() failed\n");
                continue;
            }

            if (gpio->i2cRead(PI_I2C, SLF3S_ADDR2, data2, 3) < 0) {
                fprintf(stderr, "i2cRead() failed\n");
                continue;
            }

            crc1 = (data1[2] ^ (data1[2] << 8) ^ (data1[2] >> 16)) & 0xFF;
            crc2 = (data2[2] ^ (data2[2] << 8) ^ (data2[2] >> 16)) & 0xFF;

            if (crc1 != SLF3S_CRC || crc2 != SLF3S_CRC) {
                fprintf(stderr, "CRC mismatch\n");
