#include <time.h>

#define GPIO_RAIN 17
#define GPIO_ENA 22
#define GPIO_IN1 23
#define GPIO_IN2 24
#define POLL_INTERVAL 200
#define RAIN_DETECTION_THRESHOLD 3
#define RAIN_DETECTION_WINDOW 600
#define GPIO_PULL_UP 1

int main(int argc, char **argv) {
    int gpio;
    int rain_detected = 0;
    int motor_running = 0;
    int dry_count = 0;
    int prev_rain_state = 0;
    struct timespec delay;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_USER, "Failed to initialize pigpio: %d", gpioInitialise());
        exit(1);
    }

    // Configure rain sensor as input with pull-up
    gpio = gpioInitialise(GPIO_RAIN);
    if (gpio < 0) {
        syslog(LOG_USER, "Failed to configure GPIO %d: %d", GPIO_RAIN, gpio);
        gpioTerminate();
        exit(1);
    }
    gpioSetMode(gpio, PI_INPUT);
    gpioSetPullUpDnLevel(gpio, GPIO_PULL_UP);

    // Configure motor pins as output
    gpio = gpioInitialise(GPIO_ENA);
    if (gpio < 0) {
        syslog(LOG_USER, "Failed to configure GPIO %d: %d", GPIO_ENA, gpio);
        gpioTerminate();
        exit(1);
    }
    gpio = gpioInitialise(GPIO_IN1);
    if (gpio < 0) {
        syslog(LOG_USER, "Failed to configure GPIO %d: %d", GPIO_IN1, gpio);
        gpioTerminate();
        exit(1);
    }
    gpio = gpioInitialise(GPIO_IN2);
    if (gpio < 0) {
        syslog(LOG_USER, "Failed to configure GPIO %d: %d", GPIO_IN2, gpio);
        gpioTerminate();
        exit(1);
    }
    gpioSetMode(gpio, PI_OUTPUT);
    gpio = gpioInitialise(GPIO_ENA);
    if (gpio < 0) {
        syslog(LOG_USER, "Failed to configure GPIO %d: %d", GPIO_ENA, gpio);
        gpioTerminate();
        exit(1);
    }
    gpio = gpioInitialise(GPIO_IN1);
    if (gpio < 0) {
        syslog(LOG_USER, "Failed to configure GPIO %d: %d", GPIO_IN1, gpio);
        gpioTerminate();
        exit(1);
    }
    gpio = gpioInitialise(GPIO_IN2);
    if (gpio < 0) {
        syslog(LOG_USER, "Failed to configure GPIO %d: %d", GPIO_IN2, gpio);
        gpioTerminate();
        exit(1);
    }
    gpioSetMode(gpio, PI_OUTPUT);

    // Set initial state of motor pins
    gpioWrite(GPIO_ENA, 0);
    gpioWrite(GPIO_IN1, 0);
    gpioWrite(GPIO_IN2, 0);

    // Main loop
    while (1) {
        // Poll rain sensor
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (now.tv_sec - prev_rain_state.tv_sec > RAIN_DETECTION_WINDOW) {
            dry_count = 0;
        } else if (gpioRead(GPIO_RAIN) == 0 && prev_rain_state.tv_sec == now.tv_sec) {
            dry_count++;
        } else {
            dry_count = 0;
        }
        prev_rain_state = now;

        if (dry_count >= RAIN_DETECTION_THRESHOLD) {
            // Rain is dry, check for rising edge
            if (gpioRead(GPIO_RAIN) == 0 && gpioRead(GPIO_RAIN) == 1) {
                rain_detected = 1;
                motor_running = 1;
                gpioWrite(GPIO_ENA, 1);
                gpioWrite(GPIO_IN1, 1);
                gpioWrite(GPIO_IN2, 0);
                syslog(LOG_INFO, "Rain detected, motor started");
            }
        } else if (rain_detected) {
            // Rain is wet, check for falling edge
            if (gpioRead(GPIO_RAIN) == 1 && gpioRead(GPIO_RAIN) == 0) {
                rain_detected = 0;
                motor_running = 0;
                gpioWrite(GPIO_ENA, 0);
                gpioWrite(GPIO_IN1, 0);
                gpioWrite(GPIO_IN2, 0);
                syslog(LOG_INFO, "Rain stopped, motor stopped");
            }
        }

        // Delay for POLL_INTERVAL ms
        delay.tv_sec = 0;
        delay.tv_nsec = POLL_INTERVAL * 1000000;
        nanosleep(&delay, NULL);
    }

    // Clean up
    gpioTerminate();
    close(STDOUT_FILENO);
    exit(0);
}

// Signal handler for SIGINT and SIGTERM
void sigint_handler(int sig) {
    gpioWrite(GPIO_ENA, 0);
    gpioWrite(GPIO_IN1, 0);
    gpioWrite(GPIO_IN2, 0);
    gpioTerminate();
    close(STDOUT_FILENO);
    exit(0);
}

// Register signal handler
void sigaction_handler(int sig) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(sig, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to register signal handler for %d: %d", sig, sigaction(sig, NULL, NULL));
    }
}

int main() {
    sigaction(SIGINT, &sigaction_handler, NULL);
    sigaction(SIGTERM, &sigaction_handler, NULL);
    return 0;
}

