    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %d\n", gpioInitialise());
        return 1;
    }

    // Set up GPIO 18 as an output for the servo
    if (gpioMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set servo pin mode: %d\n", gpioMode(SERVO_PIN, PI_OUTPUT));
        gpioTerminate();
        return 1;
    }

    // Set up GPIO 21 and 22 as inputs with pull-ups
    if (gpioMode(BUTTON1_PIN, PI_INPUT_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set button 1 pin mode: %d\n", gpioMode(BUTTON1_PIN, PI_INPUT_PUD_UP));
        gpioTerminate();
        return 1;
    }
    if (gpioMode(BUTTON2_PIN, PI_INPUT_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set button 2 pin mode: %d\n", gpioMode(BUTTON2_PIN, PI_INPUT_PUD_UP));
        gpioTerminate();
        return 1;
    }

    // Set up debouncing for button 1
    gpioSetPull(BUTTON1_PIN, PI_PUD_UP);
    gpioSetPull(BUTTON2_PIN, PI_PUD_UP);

    // Set up servo pulse width
    gpioServo(SERVO_PIN, SERVO_LOCK_TIME);

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler: %d\n", sigaction(SIGINT, &sa, NULL));
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Check button 1 state
        int button1_state = gpioRead(BUTTON1_PIN);
        if (button1_state == 0) {
            // Button 1 pressed, servo to locked position
            gpioServo(SERVO_PIN, SERVO_LOCK_TIME);
            printf("Button 1 pressed, locking door\n");
        }

        // Check button 2 state
        int button2_state = gpioRead(BUTTON2_PIN);
        if (button2_state == 0) {
            // Button 2 pressed, servo to unlocked position
            gpioServo(SERVO_PIN, SERVO_UNLOCK_TIME);
            printf("Button 2 pressed, unlocking door\n");
        }

        // Sleep for a short period to avoid high CPU usage
        usleep(10000);
    }

    // Clean up
    gpioTerminate();
    return 0;
}

void sigint_handler(int sig) {
    // Clean up and exit
    gpioTerminate();
    exit(0);
