#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define constants
#define GPIO_PIR 4
#define GPIO_FLOODLIGHT 17
#define RELAY_PIN GPIO_FLOODLIGHT
#define RELAY_HIGH 1
#define RELAY_LOW 0
#define LOG_FILE "security_log.txt"

// Define a function to log events
void log_event(const char *event, const char *timestamp) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        printf("Error opening log file: unable to open %s\n", LOG_FILE);
        gpioWrite(RELAY_PIN, RELAY_LOW);
        exit(1);
    }
    fprintf(log_file, "%s %s\n", timestamp, event);
    fclose(log_file);
}

// Define a function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    gpioWrite(RELAY_PIN, RELAY_LOW);
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        printf("Error initializing pigpio: %d\n", gpioInitialise());
        exit(1);
    }

    // Set up GPIO 4 as an input with a rising edge detection
    if (gpioSetMode(GPIO_PIR, PI_INPUT) < 0) {
        printf("Error setting up GPIO %d as input: %d\n", GPIO_PIR, gpioSetMode(GPIO_PIR, PI_INPUT));
        gpioWrite(RELAY_PIN, RELAY_LOW);
        exit(1);
    }

    // Set up GPIO 17 as an output
    if (gpioSetMode(GPIO_FLOODLIGHT, PI_OUTPUT) < 0) {
        printf("Error setting up GPIO %d as output: %d\n", GPIO_FLOODLIGHT, gpioSetMode(GPIO_FLOODLIGHT, PI_OUTPUT));
        gpioWrite(RELAY_PIN, RELAY_LOW);
        exit(1);
    }

    // Set the initial state of the relay to low
    gpioWrite(RELAY_PIN, RELAY_LOW);

    // Set up a signal handler for SIGINT and SIGTERM
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open the log file for writing
    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        printf("Error opening log file: unable to open %s\n", LOG_FILE);
        gpioWrite(RELAY_PIN, RELAY_LOW);
        exit(1);
    }

    // Log the initial state
    time_t now = time(NULL);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    log_event("Initial state", timestamp);

    // Main loop
    while (1) {
        // Read the state of the PIR sensor
        int pir_state = gpioRead(GPIO_PIR);
        if (pir_state == 1) {
            // Motion detected, turn on the floodlight
            gpioWrite(RELAY_PIN, RELAY_HIGH);
            time_t now = time(NULL);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            log_event("Motion detected", timestamp);
            sleep(60); // Wait for 60 seconds
            gpioWrite(RELAY_PIN, RELAY_LOW);
            time_t now2 = time(NULL);
            char timestamp2[32];
            strftime(timestamp2, sizeof(timestamp2), "%Y-%m-%d %H:%M:%S", localtime(&now2));
            log_event("Floodlight turned off", timestamp2);
        }
        sleep(0.1); // Poll at 100 ms interval
    }

    // Clean up
    gpioCleanUp();
    fclose(log_file);
    return 0;
}
