        exit(1);
    }
}

void set_baseline_filtering() {
    uint8_t baseline_filtering = 0x00;
    if (i2cWrite(MPR121_ADDRESS, 0x00, &baseline_filtering, 1) < 0) {
        printf("Failed to set baseline filtering\n");
        exit(1);
    }
    if (i2cWrite(MPR121_ADDRESS, 0x01, &baseline_filtering, 1) < 0) {
        printf("Failed to set baseline filtering\n");
        exit(1);
    }
    if (i2cWrite(MPR121_ADDRESS, 0x02, &baseline_filtering, 1) < 0) {
        printf("Failed to set baseline filtering\n");
        exit(1);
    }
    if (i2cWrite(MPR121_ADDRESS, 0x03, &baseline_filtering, 1) < 0) {
        printf("Failed to set baseline filtering\n");
        exit(1);
    }
}

void set_debounce() {
    uint8_t debounce = 0x00;
    if (i2cWrite(MPR121_ADDRESS, 0x5B, &debounce, 1) < 0) {
        printf("Failed to set debounce\n");
        exit(1);
    }
}

void set_ffi_sfi_cdt() {
    uint8_t ffisfi_cdt = 0x00;
    if (i2cWrite(MPR121_ADDRESS, 0x2C, &ffisfi_cdt, 1) < 0) {
        printf("Failed to set FFI/SFI/CDT\n");
        exit(1);
    }
}

void set_auto_config() {
    uint8_t auto_config = 0x00;
    if (i2cWrite(MPR121_ADDRESS, 0x7B, &auto_config, 1) < 0) {
        printf("Failed to set auto-config\n");
        exit(1);
    }
    if (i2cWrite(MPR121_ADDRESS, 0x7C, &auto_config, 1) < 0) {
        printf("Failed to set auto-config\n");
        exit(1);
    }
    if (i2cWrite(MPR121_ADDRESS, 0x7D, &auto_config, 1) < 0) {
        printf("Failed to set auto-config\n");
        exit(1);
    }
}

void enable_electrodes() {
    uint8_t electrodes = 0x0C;
    if (i2cWrite(MPR121_ADDRESS, 0x5E, &electrodes, 1) < 0) {
        printf("Failed to enable electrodes\n");
        exit(1);
    }
}

void toggle_relay() {
    uint8_t relay_state = 0x00;
    if (gpioWrite(RELAY_PIN, relay_state) < 0) {
        printf("Failed to toggle relay\n");
        exit(1);
    }
}

void handle_signal(int sig) {
    gpioCleanUp();
    exit(0);
}

