    init_pigpio();
    init_mpr121();

    set_baseline_filtering();
    set_debounce();
    set_ffi_sfi_cdt();
    set_auto_config();
    enable_electrodes();

    // Set relay to OFF
    gpioWrite(RELAY_PIN, 0x00);

    while (1) {
        uint16_t touch_status = 0;
        if (i2cRead(MPR121_ADDRESS, 0x00, &touch_status, 1) < 0) {
            printf("Failed to read touch status\n");
            exit(1);
        }
        if (touch_status & 0x0FFF) {
            uint8_t electrode = touch_status & 0x0F;
            if (electrode == 0) {
                gpioCleanUp();
                sleep(200);
                toggle_relay();
            }
        }
        sleep(10);
    }

    gpioCleanUp();
    return 0;
}

