#include <libgpiod/async/async.h>
#include <libgpiod/async/async-poll.h>
#include <libgpiod/async/async-poll/async-poll.h>

#define HX711_DOUT 23
#define HX711_SCK 24
#define HX711_GND 17
#define HX711_VCC 18
#define HX711_SOLENOID 25
#define TARE_OFFSET 0x8000
#define SCALE 128

int main(int argc, char **argv) {
    int threshold = 1000;
    int scale = 1;
    int duration = 500;
    int tare_offset = 0;
    int solenoid = 0;
    int retry = 0;
    int retry_count = 0;
    int solenoid_state = 0;
    int solenoid_duration = 0;
    int solenoid_start_time = 0;
    int solenoid_end_time = 0;
    int solenoid_duration_count = 0;
    int solenoid_duration_total = 0;
    int solenoid_duration_average = 0;
    int solenoid_duration_stddev = 0;
    int solenoid_duration_stddev_count = 0;
    int solenoid_duration_max = 0;
    int solenoid_duration_min = 1000000;
    int solenoid_duration_median = 0;
    int solenoid_duration_quartile1 = 0;
    int solenoid_duration_quartile3 = 0;
    int solenoid_duration_quartile4 = 0;
    int solenoid_duration_quartile5 = 0;
    int solenoid_duration_quartile6 = 0;
    int solenoid_duration_quintile1 = 0;
    int solenoid_duration_quintile3 = 0;
    int solenoid_duration_quintile4 = 0;
    int solenoid_duration_quintile5 = 0;
    int solenoid_duration_quintile6 = 0;
    int solenoid_duration_outlier1 = 0;
    int solenoid_duration_outlier3 = 0;
    int solenoid_duration_outlier4 = 0;
    int solenoid_duration_outlier5 = 0;
    int solenoid_duration_outlier6 = 0;
    int solenoid_duration_outlier = 0;
    int solenoid_duration = 0;
    int solenoid_duration_count = 0;
    int solenoid_duration_total = 0;
    int solenoid_duration_average = 0;
    int solenoid_duration_stddev = 0;
    int solenoid_duration_stddev_count = 0;
    int solenoid_duration_max = 0;
    int solenoid_duration_min = 1000000;
    int solenoid_duration_median = 0;
    int solenoid_duration_quartile1 = 0;
    int solenoid_duration_quartile3 = 0;
    int solenoid_duration_quartile4 = 0;
    int solenoid_duration_quintile1 = 0;
    int solenoid_duration_quintile3 = 0;
    int solenoid_duration_quintile4 = 0;
    int solenoid_duration_quintile5 = 0;
    int solenoid_duration_quintile6 = 0;
    int solenoid_duration_outlier1 = 0;
    int solenoid_duration_outlier3 = 0;
    int solenoid_duration_outlier4 = 0;
    int solenoid_duration_outlier5 = 0;
    int solenoid_duration_outlier6 = 0;
    int solenoid_duration_outlier = 0;

    // Initialize GPIO lines
    gpiod_async_init();
    gpiod_async_set_mode(HX711_DOUT, gpiod_async_mode_output);
    gpiod_async_set_mode(HX711_SCK, gpiod_async_mode_output);
    gpiod_async_set_mode(HX711_GND, gpiod_async_mode_input);
    gpiod_async_set_mode(HX711_VCC, gpiod_async_mode_input);
    gpiod_async_set_mode(HX711_SOLENOID, gpiod_async_mode_output);

    // Set up solenoid
    gpiod_async_set_value(HX711_SOLENOID, 0);

    // Set up syslog
    openlog("weight_monitor", LOG_PID, LOG_USER);

    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--threshold") == 0) {
            threshold = atoi(argv[++i]);
        } else if (strcmp(argv[i], "--scale") == 0) {
            scale = atoi(argv[++i]);
        } else if (strcmp(argv[i], "--duration") == 0) {
            duration = atoi(argv[++i]);
        }
    }

    // Perform startup tare
    for (int i = 0; i < 10; i++) {
        gpiod_async_set_value(HX711_SCK, 1);
        gpiod_async_set_value(HX711_DOUT, 0);
        usleep(1000);
        gpiod_async_set_value(HX711_SCK, 0);
        usleep(1000);
        gpiod_async_set_value(HX711_DOUT, 1);
        usleep(1000);
        gpiod_async_set_value(HX711_SCK, 0);
        usleep(1000);
        gpiod_async_set_value(HX711_DOUT, 0);
        usleep(1000);
        tare_offset += gpiod_async_get_value(HX711_DOUT);
    }
    tare_offset /= 10;

    // Main loop
    while (1) {
        // Wait for DOUT to go LOW
        gpiod_async_set_value(HX711_DOUT, 0);
        int start_time = gpiod_async_get_value(HX711_SCK);
        while (gpiod_async_get_value(HX711_DOUT) != 0) {
            usleep(1000);
        }
        int end_time = gpiod_async_get_value(HX711_SCK);
        if (end_time - start_time > 1000000) {
