            solenoid_duration_quartile4 = 0;
            solenoid_duration_quintile1 = 0;
            solenoid_duration_quintile3 = 0;
            solenoid_duration_quintile4 = 0;
            solenoid_duration_quintile5 = 0;
            solenoid_duration_quintile6 = 0;
