            return 1;
        }
        if (gpioSetPWM(pins[i], 1000, positions[i]) < 0) {
            printf("Failed to set PWM duty cycle for pin %d\n", pins[i]);
            return 1;
        }
    }

    // Hold the signals for 3 seconds
    sleep(3);

    // Cleanly stop the PWM and release the library resources
    for (int i = 0; i < 5; i++) {
        if (gpioSetPWM(pins[i], 0, 0) < 0) {
