#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>

#define RELAY_GPIO 17
#define BH1750_I2C_ADDRESS 0x23
#define BH1750_I2C Bus 1
#define RELAY_PIN 12
#define RELAY_HIGH 1
#define RELAY_LOW 0
#define RELAY_ON "ON"
#define RELAY_OFF "OFF"
#define RELAY_LOG_FILE "chicken_coop_log.txt"

int main(int argc, char **argv) {
    int i, lux;
    int relay_state = RELAY_LOW;
    int i2c_fd;
    int bh1750_fd;
    int pigpio_fd;
    int log_fd;
    struct stat log_stat;
    struct sigaction sa;

    // Initialize pigpio
    pigpio_fd = pigpio_open();
    if (pigpio_fd < 0) {
        perror("pigpio_open");
        return 1;
    }

    // Initialize I2C bus
    i2c_fd = pigpio_i2c_open(BH1750_I2C_Bus, BH1750_I2C_Address);
    if (i2c_fd < 0) {
        perror("pigpio_i2c_open");
        pigpio_close(pigpio_fd);
        return 1;
    }

    // Open log file
    log_fd = open(RELAY_LOG_FILE, O_RDWR | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        pigpio_close(pigpio_fd);
        pigpio_i2c_close(i2c_fd);
        return 1;
    }

    // Set up signal handlers
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        // Read lux from BH1750 sensor
        if (pigpio_i2c_write(i2c_fd, 0x21, 1) < 0) {
            perror("pigpio_i2c_write");
            pigpio_close(pigpio_fd);
            pigpio_i2c_close(i2c_fd);
            close(log_fd);
            return 1;
        }
        usleep(180000);
        if (pigpio_i2c_read(i2c_fd, &lux, 2) < 0) {
            perror("pigpio_i2c_read");
            pigpio_close(pigpio_fd);
            pigpio_i2c_close(i2c_fd);
            close(log_fd);
            return 1;
        }
        lux /= 1.2;

        // Update relay state
        if (lux < 50) {
            if (relay_state == RELAY_LOW) {
                pigpio_write(pigpio_fd, RELAY_PIN, RELAY_HIGH);
                relay_state = RELAY_HIGH;
            }
        } else if (lux > 200) {
            if (relay_state == RELAY_HIGH) {
                pigpio_write(pigpio_fd, RELAY_PIN, RELAY_LOW);
                relay_state = RELAY_LOW;
            }
        }

        // Log sensor reading and relay state
        if (log_fd >= 0) {
            char log_str[256];
            sprintf(log_str, "%04d-%02d-%02d %02d:%02d:%02d: Lux = %d, Relay = %s\n",
                    1900 + time(0) / 100, month(1900 + time(0)) % 12 + 1, day(1900 + time(0)) % 31 + 1,
                    hour(1900 + time(0)) % 24, minute(1900 + time(0)) % 60, second(1900 + time(0)) % 60,
                    lux, relay_state == RELAY_HIGH ? RELAY_ON : RELAY_OFF);
            write(log_fd, log_str, strlen(log_str));
        }

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    pigpio_close(pigpio_fd);
    pigpio_i2c_close(i2c_fd);
    close(log_fd);
    return 0;
}

void sigint_handler(int sig) {
    pigpio_close(pigpio_fd);
    pigpio_i2c_close(i2c_fd);
    close(log_fd);
    exit(0);
}

