        lux /= 1.2;

        // Update relay state
        if (lux < 50) {
            if (relay_state == RELAY_LOW) {
                pigpio_write(pigpio_fd, RELAY_PIN, RELAY_HIGH);
                relay_state = RELAY_HIGH;
            }
        } else if (lux > 200) {
            if (relay_state == RELAY_HIGH) {
                pigpio_write(pigpio_fd, RELAY_PIN, RELAY_LOW);
                relay_state = RELAY_LOW;
            }
        }

        // Log sensor reading and relay state
        if (log_fd >= 0) {
            char log_str[256];
            sprintf(log_str, "%04d-%02d-%02d %02d:%02d:%02d: Lux = %d, Relay = %s\n",
                    1900 + time(0) / 100, month(1900 + time(0)) % 12 + 1, day(1900 + time(0)) % 31 + 1,
                    hour(1900 + time(0)) % 24, minute(1900 + time(0)) % 60, second(1900 + time(0)) % 60,
                    lux, relay_state == RELAY_HIGH ? RELAY_ON : RELAY_OFF);
            write(log_fd, log_str, strlen(log_str));
        }

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    pigpio_close(pigpio_fd);
    pigpio_i2c_close(i2c_fd);
    close(log_fd);
    return 0;
}

void sigint_handler(int sig) {
    pigpio_close(pigpio_fd);
    pigpio_i2c_close(i2c_fd);
    close(log_fd);
    exit(0);
}
