#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <pigpio.h>
#include <syslog.h>
#include <unistd.h>
#include <string.h>

#define LOG_FILE "water_flow.log"
#define GPIO_FLOW 17
#define GPIO_VALVE 27
#define GPIO_PIN 11
#define DEBOUNCE_TIME 1000 // 1 second
#define PULSE_PER_L 450.0
#define LPM_HYSTERESIS 0.5
#define LPM_THRESHOLD 5.0
#define LPM_SAFE 4.5

int flow_pulses = 0;
pthread_mutex_t flow_mutex = PTHREAD_MUTEX_INITIALIZER;
int flow_pin = -1;
int valve_pin = -1;
int valve_state = 1; // 1 = open, 0 = closed
int log_fd = -1;

void* flow_isr(void* arg) {
    pthread_mutex_lock(&flow_mutex);
    flow_pulses = 0;
    pthread_mutex_unlock(&flow_mutex);
    return NULL;
}

void log_event(const char* event, int level) {
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    if (log_fd >= 0) {
        fprintf(log_fd, "%s %s %d\n", timestamp, event, flow_pulses);
        fflush(log_fd);
    }
}

void solenoid_state(int state) {
    if (valve_pin >= 0) {
        if (state == 0) {
            gpioWrite(valve_pin, 0);
            log_event("Solenoid closed", LOG_INFO);
        } else {
            gpioWrite(valve_pin, 1);
            log_event("Solenoid opened", LOG_INFO);
        }
    }
}

void* main_thread(void* arg) {
    int ret;
    ret = gpioInitialise();
    if (ret != 0) {
        log_event("gpioInitialise failed", LOG_ERR);
        return NULL;
    }
    ret = gpioSetMode(GPIO_FLOW, PI_INPUT);
    if (ret != 0) {
        log_event("gpioSetMode failed", LOG_ERR);
        gpioTerminate();
        return NULL;
    }
    ret = gpioSetISRFuncEx(GPIO_FLOW, flow_isr, DEBOUNCE_TIME);
    if (ret != 0) {
        log_event("gpioSetISRFuncEx failed", LOG_ERR);
        gpioTerminate();
        return NULL;
    }
    ret = gpioSetMode(GPIO_VALVE, PI_OUTPUT);
    if (ret != 0) {
        log_event("gpioSetMode failed", LOG_ERR);
        gpioTerminate();
        return NULL;
    }
    ret = gpioWrite(GPIO_VALVE, 1);
    if (ret != 0) {
        log_event("gpioWrite failed", LOG_ERR);
        gpioTerminate();
        return NULL;
    }
    ret = gpioSetISRFuncEx(GPIO_VALVE, NULL, 0);
    if (ret != 0) {
        log_event("gpioSetISRFuncEx failed", LOG_ERR);
        gpioTerminate();
        return NULL;
    }
    ret = pthread_mutex_init(&flow_mutex, NULL);
    if (ret != 0) {
        log_event("pthread_mutex_init failed", LOG_ERR);
        gpioTerminate();
        return NULL;
    }
    ret = log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (ret != 0) {
        log_event("open log file failed", LOG_ERR);
        pthread_mutex_destroy(&flow_mutex);
        gpioTerminate();
        return NULL;
    }
    while (1) {
        pthread_mutex_lock(&flow_mutex);
        ret = gpioRead(GPIO_FLOW);
        if (ret != 0) {
            log_event("gpioRead failed", LOG_ERR);
            pthread_mutex_unlock(&flow_mutex);
            break;
        }
        flow_pulses++;
        pthread_mutex_unlock(&flow_mutex);
        sleep(1);
        if (flow_pulses >= PULSE_PER_L) {
            double lpm = (double)flow_pulses / PULSE_PER_L * 60.0;
            flow_pulses = 0;
            if (lpm > LPM_THRESHOLD) {
                solenoid_state(0);
            } else if (lpm < LPM_SAFE) {
                solenoid_state(1);
            }
            log_event("LPM: %f", lpm, LOG_INFO);
        }
    }
    pthread_mutex_destroy(&flow_mutex);
    close(log_fd);
    gpioTerminate();
    return NULL;
}

int main(int argc, char** argv) {
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        log_event("sigaction failed", LOG_ERR);
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        log_event("sigaction failed", LOG_ERR);
        return 1;
    }
    pthread_t thread;
    ret = pthread_create(&thread, NULL, main_thread, NULL);
    if (ret != 0) {
        log_event("pthread_create failed", LOG_ERR);
        return 1;
    }
    pthread_join(thread, NULL);
    return 0;
}

