// Define constants
#define RELAY_PIN 17
#define TOUCH_PIN 4
#define DEBOUNCE_MS 50

// Global variables
int gpio;
int relay_state = 0;
int debounce_timer = 0;
int debounce_start_time = 0;

// Function to toggle the relay
void toggle_relay() {
    if (relay_state) {
        gpioWrite(gpio, RELAY_PIN, 0);
        printf("%04d-%02d-%02d %02d:%02d:%02d Relay: OFF\n",
               time(0), 1, 1, 0, 0, 0);
        relay_state = 0;
    } else {
        gpioWrite(gpio, RELAY_PIN, 1);
        printf("%04d-%02d-%02d %02d:%02d:%02d Relay: ON\n",
               time(0), 1, 1, 0, 0, 0);
        relay_state = 1;
    }
}

// Function to handle touch events
void touch_handler(int gpio, int level, int edge) {
    if (edge == PI_RISING) {
        if (gpio == TOUCH_PIN) {
            if (debounce_timer == 0) {
                debounce_start_time = time(0);
                debounce_timer = 1;
            }
        } else if (debounce_timer != 0) {
            if (time(0) - debounce_start_time > DEBOUNCE_MS) {
                toggle_relay();
                debounce_timer = 0;
            }
        }
    } else if (edge == PI_FALLING) {
        if (gpio == TOUCH_PIN) {
            debounce_timer = 0;
        }
    }
}

