    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up GPIO mode and pull-up resistor
    if (gpioSetMode(TOUCH_PIN, PI_INPUT PullUpDowntimeout) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    // Set up relay pin
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    // Set relay initial state
    gpioWrite(RELAY_PIN, 0);

    // Set up interrupt handler
    if (gpioBindInterrupt(TOUCH_PIN, touch_handler, 0) < 0) {
        perror("gpioBindInterrupt");
        gpioTerminate();
        return 1;
    }

    // Parse command-line argument for debounce time
    int debounce_ms = 50;
    if (argc > 1) {
        if (sscanf(argv[1], "%d", &debounce_ms) != 1) {
            fprintf(stderr, "Invalid debounce time argument\n");
            gpioTerminate();
            return 1;
        }
    }

    // Main loop
    while (1) {
        sleep(1);
    }

    // Clean up
    gpioTerminate();
    return 0;
}

// Signal handlers
void sigint_handler(int sig) {
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    exit(0);
}

void sigterm_handler(int sig) {
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    exit(0);
}

// Install signal handlers
void install_signal_handlers() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);
}

