#include <pigpio.h>
#include <signal.h>
#include <termios.h>
#include <unistd.h>

#define SERVO_PIN 18
#define SERVO_MIN 500
#define SERVO_MAX 2500
#define SERVO_CENTER 1500
#define SERVO_STEP 10
#define SERVO_MAX_ANGLE 180
#define SERVO_MIN_ANGLE 0

int main() {
    int servo_angle = SERVO_CENTER;
    int servo_period = 20;
    int servo_pulse_width = SERVO_CENTER;
    int gpio_fd;
    struct termios oldt, newt;
    struct winsize w;
    int c;

    // Initialize pigpio
    gpio_fd = pigpio_init();
    if (gpio_fd < 0) {
        fprintf(stderr, "pigpio_init() failed\n");
        return 1;
    }

    // Set up terminal settings
    tcgetattr(gpio_fd, &oldt);
    tcgetattr(gpio_fd, &newt);
    newt.c_lflag &= ~(ICANON | ECHO);
    tcsetattr(gpio_fd, TCSANOW, &newt);

    // Set up PWM
    gpioInitialise(gpio_fd, SERVO_PIN, PI_OUTPUT);
    gpioSetMode(gpio_fd, SERVO_PIN, PI PWM, 50, SERVO_CENTER, SERVO_CENTER);
    gpioServo(gpio_fd, SERVO_PIN, SERVO_CENTER);

    while (1) {
        // Read keyboard input
        c = getchar();
        if (c == 'q' || c == 'Q') {
            break;
        } else if (c == '\n') {
            continue;
        } else if (c >= '0' && c <= '9') {
            servo_angle += c - '0';
            servo_angle = (servo_angle < SERVO_MIN_ANGLE) ? SERVO_MIN_ANGLE : (servo_angle > SERVO_MAX_ANGLE) ? SERVO_MAX_ANGLE : servo_angle;
            servo_pulse_width = (servo_angle * SERVO_STEP) / SERVO_MAX_ANGLE;
            servo_pulse_width = (servo_pulse_width < SERVO_MIN) ? SERVO_MIN : (servo_pulse_width > SERVO_MAX) ? SERVO_MAX : servo_pulse_width;
            gpioServo(gpio_fd, SERVO_PIN, servo_pulse_width);
            printf("Servo angle: %d\n", servo_angle);
        }
    }

    // Restore terminal settings
    tcsetattr(gpio_fd, TCSANOW, &oldt);

    // Clean up
    gpioTerminate(gpio_fd);
    return 0;
}

