#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod/gpiod.h>
#include <gpiod/gpiod_types.h>
#include <gpiod/gpiod_event.h>
#include <gpiod/gpiod_chip.h>
#include <gpiod/gpiod_line.h>
#include <gpiod/gpiod_line_event.h>
#include <time.h>

#define GPIO_PIN 17
#define GPIO_PIN_NAME "GPIO 17"
#define LOG_FILE "motor_rpm.log"

int main(int argc, char **argv) {
    int fd;
    gpiod_chip_t *chip;
    gpiod_line_t *line;
    gpiod_line_event_t *event;
    gpiod_line_event_wait_t wait;
    struct timespec start;
    uint64_t pulseCount = 0;
    double rpm = 0.0;
    FILE *logFile;

    // Initialize the log file
    logFile = fopen(LOG_FILE, "w");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        return 1;
    }

    // Open the chip
    fd = gpiod_chip_open(GPIOD_chip_type(), NULL, NULL);
    if (fd < 0) {
        fprintf(stderr, "Failed to open chip\n");
        fclose(logFile);
        return 1;
    }

    // Get the chip object
    chip = gpiod_chip_get(fd, NULL);
    if (chip == NULL) {
        fprintf(stderr, "Failed to get chip object\n");
        gpiod_chip_close(fd);
        fclose(logFile);
        return 1;
    }

    // Get the line object
    line = gpiod_chip_get_line(chip, GPIO_PIN, GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (line == NULL) {
        fprintf(stderr, "Failed to get line object\n");
        gpiod_chip_close(fd);
        fclose(logFile);
        return 1;
    }

    // Request the line as an input with edge-triggered event detection
    if (gpiod_line_request_input(line, GPIOD_LINE_EVENT_EDGE, &wait) < 0) {
        fprintf(stderr, "Failed to request line as input\n");
        gpiod_line_release(line);
        gpiod_chip_close(fd);
        fclose(logFile);
        return 1;
    }

    // Set the debounce window
    wait.debounce = 2;

    // Start the main loop
    while (1) {
        // Get the current time
        clock_gettime(CLOCK_MONOTONIC, &start);

        // Wait for an event
        if (gpiod_line_event_wait(line, &wait) < 0) {
            fprintf(stderr, "Failed to wait for event\n");
            break;
        }

        // Increment the pulse count
        pulseCount++;

        // Compute the RPM
        rpm = (pulseCount / 5.0) * 60.0;

        // Append the sample to the log file
        fprintf(logFile, "%s,%f\n", ctime(&start), rpm);
        fflush(logFile);

        // Print the current RPM
        printf("%.2f\n", rpm);
    }

    // Release the GPIO line
    gpiod_line_release(line);

    // Close the chip
    gpiod_chip_close(fd);

    // Close the log file
    fclose(logFile);

    return 0;
}

