#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>

#define RELAY_PIN 17
#define TOUCH_PIN 4
#define RELAY_STATE 0
#define TOUCH_STATE 1
#define RELAY_ON 1
#define RELAY_OFF 0
#define TOUCH_HIGH 1
#define TOUCH_LOW 0
#define RELAY_TIMEOUT 10  // seconds
#define POLL_INTERVAL 50  // ms

volatile int relay_state = RELAY_OFF;
volatile int touch_state = TOUCH_LOW;
volatile int timeout = 0;
volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        exit(1);
    }

    // Set up GPIO mode and direction
    if (gpioSetMode(TOUCH_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode() failed\n");
        gpioTerminate();
        exit(1);
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode() failed\n");
        gpioTerminate();
        exit(1);
    }

    // Set relay to OFF
    if (gpioWrite(RELAY_PIN, RELAY_OFF) < 0) {
        fprintf(stderr, "gpioWrite() failed\n");
        gpioTerminate();
        exit(1);
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        // Read touch state
        int touch_value = gpioRead(TOUCH_PIN);
        if (touch_value == PI_BAD_GPIO) {
            fprintf(stderr, "gpioRead() failed\n");
            gpioTerminate();
            exit(1);
        }
        if (touch_value == TOUCH_HIGH) {
            touch_state = TOUCH_HIGH;
            if (timeout == 0) {
                timeout = time(NULL) + RELAY_TIMEOUT;
            } else {
                timeout = 0;
            }
        } else {
            touch_state = TOUCH_LOW;
            if (timeout > 0) {
                timeout--;
            }
        }

        // Toggle relay state
        if (touch_state == TOUCH_HIGH && timeout == 0) {
            if (relay_state == RELAY_OFF) {
                if (gpioWrite(RELAY_PIN, RELAY_ON) < 0) {
                    fprintf(stderr, "gpioWrite() failed\n");
                    gpioTerminate();
                    exit(1);
                }
                relay_state = RELAY_ON;
            } else {
                if (gpioWrite(RELAY_PIN, RELAY_OFF) < 0) {
                    fprintf(stderr, "gpioWrite() failed\n");
                    gpioTerminate();
                    exit(1);
                }
                relay_state = RELAY_OFF;
            }
        }

        // Sleep for POLL_INTERVAL ms
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up
    gpioTerminate();
    return 0;
}

