#define B 6
#define A2 26
#define B2 19
#define SAMPLE_TIME_MS 100
#define TARGET_RPM 60
#define KP 1.0
#define KI 0.1
#define KD 0.01
#define LOG_FILE "motor_log.csv"

// Structure to hold motor data
typedef struct {
    int speed;
    double pidP;
    double pidI;
    double pidD;
} motor_t;

// Structure to hold encoder data
typedef struct {
    int count;
    pthread_mutex_t mutex;
} encoder_t;

// Global variables
motor_t motor1, motor2;
encoder_t encoder1, encoder2;
gpiod_chip_t chip1, chip2;
gpiod_line_t line1, line2;
gpiod_edge_t edge1, edge2;
gpiod_mutex_t mutex1, mutex2;
gpiod_semaphore_t sem1, sem2;
gpiod_timer_t timer;
int log_fd = -1;

// Function to decode encoder signals
void decode_encoder(gpiod_edge_t *edge, gpiod_line_t *line, int *count, pthread_mutex_t *mutex) {
    int direction = 0;
    if (line->get_value(edge) == GPIOD_LINE_EDGE_RISING) {
        direction = 1;
    } else if (line->get_value(edge) == GPIOD_LINE_EDGE_FALLING) {
        direction = -1;
    }
    *count += direction;
    pthread_mutex_lock(mutex);
    *count %= 600;
    pthread_mutex_unlock(mutex);
}

// Function to update PID controller
void update_pid(double *pidP, double *pidI, double *pidD, double dt) {
    double error = motor1.speed - TARGET_RPM;
    *pidP += KI * error * dt;
    *pidI += KI * dt;
    *pidD += KD * error * dt;
    *pidP = fmax(*pidP, 0.0);
    *pidI = fmax(*pidI, 0.0);
    *pidD = fmax(*pidD, 0.0);
}

// Function to update motor speed
void update_motor(double *speed, double pidP, double pidI, double pidD) {
    *speed = fmin(fmax(TARGET_RPM, *speed + pidP), TARGET_RPM);
    *speed = fmin(fmax(0.0, *speed + pidI), TARGET_RPM);
    *speed = fmin(fmax(0.0, *speed + pidD), TARGET_RPM);
}

// Function to write to log file
void write_log(double speed, double pidP, double pidI, double pidD) {
    char buffer[256];
    sprintf(buffer, "%f,%f,%f,%f\n", motor1.speed, motor1.pidP, motor1.pidI, motor1.pidD);
    if (log_fd >= 0) {
        write(log_fd, buffer, strlen(buffer));
    }
}

// Function to handle encoder events
void *encoder_thread(void *arg) {
    int count1 = 0, count2 = 0;
    pthread_mutex_t *mutex1 = (pthread_mutex_t *)arg;
    while (1) {
        gpiod_edge_wait(&edge1, &line1, GPIOD_LINE_EDGE_BOTH, 0);
        decode_encoder(&edge1, &line1, &count1, mutex1);
        gpiod_edge_wait(&edge2, &line2, GPIOD_LINE_EDGE_BOTH, 0);
        decode_encoder(&edge2, &line2, &count2, mutex2);
        pthread_mutex_lock(mutex1);
        motor1.count = count1;
        pthread_mutex_unlock(mutex1);
        pthread_mutex_lock(mutex2);
        motor2.count = count2;
        pthread_mutex_unlock(mutex2);
    }
    return NULL;
}

