#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <string.h>

#define RELAY_PIN 17
#define I2C_ADDRESS 0x5A
#define I2C Bus 1
#define TOUCH_THRESHOLD 100
#define RELEASE_THRESHOLD 500
#define RELAY_LOG_FILE "relay_log.txt"

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("pigpio initialization failed");
        return 1;
    }

    // Open I2C bus
    int i2c_fd = pigpioOpen(I2C Bus, I2C_ADDRESS);
    if (i2c_fd < 0) {
        perror("I2C open failed");
        gpioTerminate();
        return 1;
    }

    // Configure MPR121
    if (pigpioWrite(i2c_fd, 0x00, 0x00) < 0) {
        perror("MPR121 config write failed");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (pigpioWrite(i2c_fd, 0x00, 0x01) < 0) {
        perror("MPR121 config write failed");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (pigpioWrite(i2c_fd, 0x00, 0x02) < 0) {
        perror("MPR121 config write failed");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (pigpioWrite(i2c_fd, 0x00, 0x03) < 0) {
        perror("MPR121 config write failed");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (pigpioWrite(i2c_fd, 0x00, 0x04) < 0) {
        perror("MPR121 config write failed");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (pigpioWrite(i2c_fd, 0x00, 0x05) < 0) {
        perror("MPR121 config write failed");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (pigpioWrite(i2c_fd, 0x00, 0x06) < 0) {
        perror("MPR121 config write failed");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (pigpioWrite(i2c_fd, 0x00, 0x07) < 0) {
        perror("MPR121 config write failed");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (pigpioWrite(i2c_fd, 0x00, 0x08) < 0) {
        perror("MPR121 config write failed");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (pigpioWrite(i2c_fd, 0x00, 0x09) < 0) {
        perror("MPR121 config write failed");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (pigpioWrite(i2c_fd, 0x00, 0x0A) < 0) {
        perror("MPR121 config write failed");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (pigpioWrite(i2c_fd, 0x00, 0x0B) < 0) {
        perror("MPR121 config write failed");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (pigpioWrite(i2c_fd, 0x00, 0x0C) < 0) {
        perror("MPR121 config write failed");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (pigpioWrite(i2c_fd, 0x00, 0x0D) < 0) {
        perror("MPR121 config write failed");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (pigpioWrite(i2c_fd, 0x00, 0x0E) < 0) {
        perror("MPR121 config write failed");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (pigpioWrite(i2c_fd, 0x00, 0x0F) < 0) {
        perror("MPR121 config write failed");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (pigpioWrite(i2c_fd, 0x00, 0x10) < 0) {
        perror("MPR121 config write failed");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (pigpioWrite(i2c_fd, 0x00, 0x11) < 0) {
        perror("MPR121 config write failed");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (pigpioWrite(i2c_fd, 0x00, 0x12) < 0) {
        perror("MPR121 config write failed");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set touch and release thresholds
    if (pigpioWrite(i2c_fd, 0x01, TOUCH_THRESHOLD) < 0) {
        perror("MPR121 threshold write failed");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (pigpioWrite(i2c_fd, 0x01, RELEASE_THRESHOLD) < 0) {
        perror("MPR121 threshold write failed");
        pigpioClose(i2c_fd);
        gpioTerminate();
        return 1;
