#include <unistd.h>
#include <errno.h>
#include <gpiod/gpiod.h>
#include <gpiod/gpiod-async.h>
#include <gpiod/gpiod-async-event.h>
#include <gpiod/gpiod-async-event-queue.h>
#include <gpiod/gpiod-async-event-queue-async.h>

#define VALVE1_GPIO 17
#define VALVE2_GPIO 18
#define VALVE1_RELAY 1
#define VALVE2_RELAY 2
#define VALVE1_VALVE 997
#define VALVE2_VALVE 998
#define VALVE_LOG_FILE "valve_log.txt"

int main(int argc, char *argv[]) {
    int valve1_fd, valve2_fd;
    gpiod_async_context_t ctx;
    gpiod_async_event_t event1, event2;
    gpiod_async_event_queue_t queue;
    gpiod_async_event_queue_async_t queue_async;
    gpiod_async_event_queue_async_init(&queue_async);
    gpiod_async_event_queue_init(&queue, &queue_async);

    // Open log file
    int log_fd = open(VALVE_LOG_FILE, O_RDWR | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        return 1;
    }

    // Initialize GPIO
    int ret = gpiod_async_context_new(&ctx);
    if (ret < 0) {
        perror("Failed to initialize GPIO context");
        return 1;
    }

    // Create events
    gpiod_async_event_init(&event1, VALVE1_GPIO, gpiod_async_event_type_edge_rising, gpiod_async_event_edge_level_high, VALVE1_RELAY);
    gpiod_async_event_init(&event2, VALVE2_GPIO, gpiod_async_event_type_edge_rising, gpiod_async_event_edge_level_high, VALVE2_RELAY);

    // Add events to queue
    ret = gpiod_async_event_queue_add(&queue, &event1);
    if (ret < 0) {
        perror("Failed to add event to queue");
        return 1;
    }
    ret = gpiod_async_event_queue_add(&queue, &event2);
    if (ret < 0) {
        perror("Failed to add event to queue");
        return 1;
    }

    // Set up async events
    gpiod_async_event_queue_async_init(&queue_async, &queue);
    gpiod_async_event_queue_async_set_callback(&queue_async, &event1, gpiod_async_event_callback, NULL);
    gpiod_async_event_queue_async_set_callback(&queue_async, &event2, gpiod_async_event_callback, NULL);

    // Open valve files
    valve1_fd = gpiod_async_open(ctx, VALVE1_VALVE, gpiod_async_open_flags_output);
    if (valve1_fd < 0) {
        perror("Failed to open valve 1");
        return 1;
    }
    valve2_fd = gpiod_async_open(ctx, VALVE2_VALVE, gpiod_async_open_flags_output);
    if (valve2_fd < 0) {
        perror("Failed to open valve 2");
        return 1;
    }

    // Main loop
    while (1) {
        // Activate Valve 1
        gpiod_async_request_output(ctx, VALVE1_GPIO, gpiod_async_request_flags_output_high);
        gpiod_async_write(ctx, valve1_fd, 0);
        gpiod_async_write(ctx, valve2_fd, 0);
        gpiod_async_event_queue_async_trigger(&queue_async);
        gpiod_async_event_queue_async_wait(&queue_async, &event1, gpiod_async_event_timeout_ms(500));
        gpiod_async_event_queue_async_trigger(&queue_async);
        gpiod_async_event_queue_async_wait(&queue_async, &event1, gpiod_async_event_timeout_ms(5000));

        // Activate Valve 2
        gpiod_async_request_output(ctx, VALVE2_GPIO, gpiod_async_request_flags_output_high);
        gpiod_async_write(ctx, valve1_fd, 0);
        gpiod_async_write(ctx, valve2_fd, 0);
        gpiod_async_event_queue_async_trigger(&queue_async);
        gpiod_async_event_queue_async_wait(&queue_async, &event2, gpiod_async_event_timeout_ms(1000));
        gpiod_async_event_queue_async_trigger(&queue_async);
        gpiod_async_event_queue_async_wait(&queue_async, &event2, gpiod_async_event_timeout_ms(10000));
    }

    // Clean up
    gpiod_async_event_queue_async_destroy(&queue_async);
    gpiod_async_event_queue_destroy(&queue);
    gpiod_async_event_destroy(&event1);
    gpiod_async_event_destroy(&event2);
    gpiod_async_context_destroy(ctx);
    close(log_fd);
    return 0;
}

