#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>

#define I2C_ADDRESS 0x5A
#define I2C Bus 1
#define RELAY_PIN 17
#define TOUCH_THRESHOLD 0x10
#define RELEASE_THRESHOLD 0x0A
#define FILTER_CHARGE_TIME 0x20
#define ELECTRODE_CURRENT 0x01
#define ELE_EN 0x20
#define RELAY_ON 1
#define RELAY_OFF 0

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Initialize I2C bus
    if (i2cInit(I2C Bus, I2C_ADDRESS) < 0) {
        perror("i2cInit");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (i2cWrite(I2C Bus, TOUCH_THRESHOLD, 0x00) < 0) {
        perror("i2cWrite");
        i2cClose(I2C Bus);
        gpioTerminate();
        return 1;
    }
    if (i2cWrite(I2C Bus, RELEASE_THRESHOLD, 0x00) < 0) {
        perror("i2cWrite");
        i2cClose(I2C Bus);
        gpioTerminate();
        return 1;
    }
    if (i2cWrite(I2C Bus, FILTER_CHARGE_TIME, 0x00) < 0) {
        perror("i2cWrite");
        i2cClose(I2C Bus);
        gpioTerminate();
        return 1;
    }
    if (i2cWrite(I2C Bus, ELECTRODE_CURRENT, 0x00) < 0) {
        perror("i2cWrite");
        i2cClose(I2C Bus);
        gpioTerminate();
        return 1;
    }
    if (i2cWrite(I2C Bus, ELE_EN, 0x20) < 0) {
        perror("i2cWrite");
        i2cClose(I2C Bus);
        gpioTerminate();
        return 1;
    }

    // Wait for stabilization
    usleep(100000);

    // Set relay pin as output
    if (gpioMode(RELAY_PIN, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        i2cClose(I2C Bus);
        gpioTerminate();
        return 1;
    }

    // Set relay to off
    if (gpioWrite(RELAY_PIN, RELAY_OFF) < 0) {
        perror("gpioWrite");
        i2cClose(I2C Bus);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read touch status
        uint8_t touch_status = 0;
        if (i2cRead(I2C Bus, &touch_status, 2) < 0) {
            perror("i2cRead");
            i2cClose(I2C Bus);
            gpioTerminate();
            return 1;
        }

        // Toggle relay if any electrode is touched
        if (touch_status > 0) {
            gpioWrite(RELAY_PIN, RELAY_ON);
            printf("Relay is on\n");
        } else {
            gpioWrite(RELAY_PIN, RELAY_OFF);
            printf("Relay is off\n");
        }

        // Delay
        usleep(100000);
    }

    // Handle SIGINT and SIGTERM
    signal(SIGINT, SIG_IGN);
    signal(SIGTERM, SIG_IGN);

    // Close I2C bus
    i2cClose(I2C Bus);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

