        return 1;
    }

    // Set relay to off
    if (gpioWrite(RELAY_PIN, RELAY_OFF) < 0) {
        perror("gpioWrite");
        i2cClose(I2C Bus);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read touch status
        uint8_t touch_status = 0;
        if (i2cRead(I2C Bus, &touch_status, 2) < 0) {
            perror("i2cRead");
            i2cClose(I2C Bus);
            gpioTerminate();
            return 1;
        }

        // Toggle relay if any electrode is touched
        if (touch_status > 0) {
            gpioWrite(RELAY_PIN, RELAY_ON);
            printf("Relay is on\n");
        } else {
            gpioWrite(RELAY_PIN, RELAY_OFF);
            printf("Relay is off\n");
        }

        // Delay
        usleep(100000);
    }

    // Handle SIGINT and SIGTERM
    signal(SIGINT, SIG_IGN);
    signal(SIGTERM, SIG_IGN);

    // Close I2C bus
    i2cClose(I2C Bus);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}
