                fprintf(log_file, "%ld: No motion\n", now.tv_sec);
            }
        }

        // Sleep for 50 ms
        usleep(50 * 1000);
    }

    // Clean up
    pigpio_close(gpio);
    pigpio_exit();
    fclose(log_file);
    return 0;
