        exit(1);
    }
    if (gpioPWM(GPIO_MOTOR2, PI_HIGH, 0) != 0) {
        perror("gpioPWM");
        exit(1);
    }
}

void cleanup_gpio() {
    if (gpioPWM(GPIO_MOTOR1, PI_LOW, 0) != 0) {
        perror("gpioPWM");
    }
    if (gpioPWM(GPIO_MOTOR2, PI_LOW, 0) != 0) {
        perror("gpioPWM");
    }

    gpioTerminate();
}

void generate_pattern(int motor1, int motor2) {
    int step;
    int duration;
    int duty_cycle1, duty_cycle2;

    for (step = 0; step < 5; step++) {
        duty_cycle1 = rand() % 256;
        duty_cycle2 = rand() % 256;

        if (gpioPWM(motor1, PI_HIGH, duty_cycle1) != 0) {
            perror("gpioPWM");
