#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <signal.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

#define GPIO_DATA 4
#define GPIO_CLOCK 17
#define GPIO_LOCK 27
#define GPIO_LOG 23
#define SCALE_FACTOR 1.0
#define OFFSET 0.0
#define THRESHOLD 10.0
#define READ_INTERVAL 500
#define MAX_READS 100

int main(int argc, char *argv[]) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return 1;
    }

    // Open log file
    int log_fd = open("weight_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Read calibration data from file
    char calibration[1024];
    ssize_t len = readlink("calibration.txt", calibration, sizeof(calibration));
    if (len < 0) {
        fprintf(stderr, "Failed to read calibration data: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    calibration[len] = '\0';

    // Parse calibration data
    char *scale_str = strtok(calibration, " \n");
    if (scale_str == NULL) {
        scale_str = "1.0";
    }
    float scale = atof(scale_str);
    scale_str = strtok(NULL, " \n");
    if (scale_str == NULL) {
        scale = 1.0;
    }
    float offset = atof(scale_str);

    // Perform one-time startup calibration
    float sum = 0.0;
    int count = 0;
    for (int i = 0; i < MAX_READS; i++) {
        int raw_value = gpioGetRead(GPIO_DATA);
        if (raw_value < 0) {
            fprintf(stderr, "Failed to read from HX711: %s\n", strerror(errno));
            gpioTerminate();
            return 1;
        }
        sum += raw_value;
        count++;
        usleep(1000);
    }
    offset = sum / count;
    gpioWrite(GPIO_CLOCK, 0);
    gpioWrite(GPIO_DATA, 0);
    gpioWrite(GPIO_LOCK, 0);
    gpioWrite(GPIO_LOG, 1);
    printf("Calibration complete. Offset: %f\n", offset);

    // Save calibration data to file
    FILE *fp = fopen("calibration.txt", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open calibration file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    fprintf(fp, "%f %f\n", scale, offset);
    fclose(fp);

    // Main loop
    while (1) {
        int raw_value = gpioGetRead(GPIO_DATA);
        if (raw_value < 0) {
            fprintf(stderr, "Failed to read from HX711: %s\n", strerror(errno));
            gpioTerminate();
            return 1;
        }
        gpioWrite(GPIO_CLOCK, 1);
        gpioWrite(GPIO_DATA, 0);
        float weight = (raw_value - offset) * scale;
        if (weight > THRESHOLD) {
            gpioWrite(GPIO_LOCK, 1);
        } else {
            gpioWrite(GPIO_LOCK, 0);
        }
        printf("%f\n", weight);
        if (gpioGetRead(GPIO_LOG) == 0) {
            break;
        }
        usleep(READ_INTERVAL * 1000);
    }

    // Release resources
    gpioTerminate();
    close(log_fd);

    return 0;
}

