        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    int calib_fd = open(CALIBRATION_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (calib_fd < 0) {
        fprintf(stderr, "Failed to open calibration file\n");
        close(log_fd);
        gpioTerminate();
        return 1;
    }

    // Read calibration value from user
    printf("Place a known weight on the load cell and press Enter to calibrate...\n");
    getchar();
    printf("Enter the weight in kilograms: ");
    double calib_weight;
    if (scanf("%lf", &calib_weight) != 1) {
        fprintf(stderr, "Failed to read calibration weight\n");
        close(log_fd);
        close(calib_fd);
        gpioTerminate();
        return 1;
    }

    // Read calibration value
    int calib_raw;
    if (gpioRead(HX711_DATA_PIN, &calib_raw) < 0) {
        fprintf(stderr, "Failed to read calibration value\n");
        close(log_fd);
        close(calib_fd);
        gpioTerminate();
        return 1;
    }

    // Compute calibration factor
    double calib_factor = calib_raw / calib_weight;

    // Write calibration factor to file
    if (fwrite(&calib_factor, sizeof(double), 1, calib_fd) != 1) {
        fprintf(stderr, "Failed to write calibration factor to file\n");
        close(log_fd);
        close(calib_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read raw value
        int raw;
        if (gpioRead(HX711_DATA_PIN, &raw) < 0) {
            fprintf(stderr, "Failed to read raw value\n");
            break;
        }

        // Compute weight
        double weight = raw * calib_factor;

        // Log weight
        time_t now = time(NULL);
        struct tm *time_info = localtime(&now);
        char log_message[100];
        strftime(log_message, sizeof(log_message), "%Y-%m-%d %H:%M:%S", time_info);
        fprintf(log_fd, "%s %f\n", log_message, weight);
        if (weight > 5.0) {
            fprintf(log_fd, "Solenoid lock engaged\n");
        }

        // Drive solenoid lock
        if (weight > 5.0) {
            gpioWrite(SOLENOID_LOCK_PIN, PI_HIGH);
            sleep(5);
            gpioWrite(SOLENOID_LOCK_PIN, PI_LOW);
        }

        // Check for SIGINT
        if (gpioGetSignal(HX711_CLOCK_PIN, PI_INPUT) == 0) {
            break;
        }
    }

    // Close files
    close(log_fd);
    close(calib_fd);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}
```

This code uses the pigpio library to read the raw value from the HX711 load cell and compute the weight in kilograms using the calibration factor. It logs the weight to a file and drives the solenoid lock on GPIO27 high for 5 seconds when the weight exceeds 5.0 kg. The program handles errors, including pigpio initialization failure, file open and write failures, calibration read errors, and HX711 communication timeouts. The program also installs a SIGINT handler to gracefully unlock the solenoid and terminate pigpio on every exit path.

