    int fd;
    int relay_state = 0;
    struct timespec last_state_change;

    // Initialize logging
    if (access(RELAY_LOG_FILE, F_OK) == -1) {
        mkdir(RELAY_LOG_FILE, 0644);
    }

    // Open the log file
    fd = open(RELAY_LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd == -1) {
        perror("Failed to open log file");
        return 1;
    }

    // Open the chip
    chip = gpiod_chip_open_by_name("gpio-0", NULL);
    if (!chip) {
        perror("Failed to open chip");
        return 1;
