    line = gpiod_chip_get_line(chip, GPIO16);
    if (!line) {
        perror("Failed to get line for GPIO16");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the line for input
    if (gpiod_line_request_bulk_inputs(line, 1, &relay_line) != 0) {
        perror("Failed to request line for input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Get the initial relay line
    relay_line = gpiod_line_get_value(relay_line);
    if (relay_line->value != RELAY_VALUE) {
        gpiod_line_release(relay_line);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up the log line
    log_line = gpiod_chip_get_line(chip, "log");
    if (!log_line) {
        perror("Failed to get log line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the log line for output
    if (gpiod_line_request_bulk_outputs(log_line, 1, &log_line) != 0) {
        perror("Failed to request log line for output");
        gpiod_line_release(log_line);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up the log line to write to the log file
    gpiod_line_set_value(log_line, RELAY_STATE, RELAY_VALUE);

    // Main loop
    while (1) {
        // Read the sensor value
        gpiod_line_get_value(relay_line, &relay_state);
        if (relay_state == 0) {
            // Relay is active-low, toggle the relay
            gpiod_line_set_value(relay_line, RELAY_DIR, RELAY_VALUE);
            gpiod_line_set_value(relay_line, RELAY_STATE, RELAY_VALUE);
            clock_gettime(CLOCK_REALTIME, &last_state_change);
            gpiod_line_set_value(log_line, RELAY_STATE, RELAY_VALUE);
            fprintf(fd, "%s %d\n", ctime(&last_state_change), RELAY_STATE);
        }

        // Sleep for 100ms
        usleep(100000);
    }

    // Release the log line
    gpiod_line_release(log_line);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    // Close the log file
    close(fd);

    return 0;
}

