#include <gpiod/chip.h>
#include <gpiod/line.h>

#define GPIO17 17
#define GPIO18 18
#define BUZZER_PIN GPIO18
#define LOG_FILE "motion_log.txt"

int main() {
    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return 1;
    }

    // Open the chip
    struct gpiod_chip *chip = gpiod_chip_open("gpio-0", NULL);
    if (chip == NULL) {
        perror("gpiod_chip_open");
        fclose(log_file);
        return 1;
    }

    // Open the line
    struct gpiod_line *line = gpiod_line_request_input(chip, GPIO17, NULL);
    if (line == NULL) {
        perror("gpiod_line_request_input");
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    // Set the line to input mode
    if (gpiod_line_set_mode(line, GpioLineModeInput) < 0) {
        perror("gpiod_line_set_mode");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    // Open the buzzer line
    line = gpiod_line_request_output(chip, GPIO18, NULL);
    if (line == NULL) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    // Set the buzzer line to output mode
    if (gpiod_line_set_mode(line, GpioLineModeOutput) < 0) {
        perror("gpiod_line_set_mode");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    // Set the initial state of the buzzer line
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("gpiod_line_set_value");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    // Main loop
    while (1) {
        // Read the line value
        uint32_t value = gpiod_line_get_value(line);
        if (value == 1) {
            // Log the timestamp
            time_t now = time(NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_file, "%s\n", timestamp);

            // Activate the buzzer
            if (gpiod_line_set_value(line, 1) < 0) {
                perror("gpiod_line_set_value");
                break;
            }

            // Wait for 2 seconds
            usleep(2000000);

            // Deactivate the buzzer
            if (gpiod_line_set_value(line, 0) < 0) {
                perror("gpiod_line_set_value");
                break;
            }
        }
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

void sigint_handler(int sig) {
    // Turn off the buzzer
    struct gpiod_line *line = gpiod_line_request_output(gpiod_chip_get_default(), GPIO18, NULL);
    if (line == NULL) {
        perror("gpiod_line_request_output");
        return;
    }
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("gpiod_line_set_value");
        return;
    }
    gpiod_line_release(line);
}

