#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>
#include <libgpiod/err.h>

#define GPIO_LINE 18
#define GPIO_PIN 0
#define VALVE_PIN 1
#define VALVE_VALVE 0
#define VALVE_OFF 0
#define VALVE_ON 1

volatile sig_atomic_t stop = 0;

void sigint_handler(int sig) {
    stop = 1;
}

void sigterm_handler(int sig) {
    stop = 1;
}

int main(int argc, char *argv[]) {
    gpiod_t *chip;
    gpiod_line_t *line;
    gpiod_pin_t *pin;
    gpiod_valve_t *valve;
    gpiod_valve_t *valve_config;
    gpiod_valve_config_t valve_config_t;
    char *duration_str;
    int duration;
    int ret;

    // Initialize libgpiod
    if ((ret = gpiod_init()) != 0) {
        fprintf(stderr, "gpiod_init failed: %s\n", gpiod_strerror(ret));
        return 1;
    }

    // Create a new chip
    chip = gpiod_chip_new();
    if ((ret = gpiod_chip_add(chip, GPIO_LINE, GPIO_PIN, GPIO_LINE_MODE_OUTPUT, GPIO_LINE_ACTIVE_LOW)) != 0) {
        fprintf(stderr, "gpiod_chip_add failed: %s\n", gpiod_strerror(ret));
        gpiod_chip_free(chip);
        return 1;
    }

    // Create a new line
    line = gpiod_line_new(chip, GPIO_LINE);
    if ((ret = gpiod_line_add(chip, line, GPIO_PIN, VALVE_PIN, VALVE_VALVE)) != 0) {
        fprintf(stderr, "gpiod_line_add failed: %s\n", gpiod_strerror(ret));
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        return 1;
    }

    // Set the initial state of the valve
    valve_config_t = gpiod_valve_config_new();
    if ((ret = gpiod_valve_config_init(valve_config_t, VALVE_VALVE)) != 0) {
        fprintf(stderr, "gpiod_valve_config_init failed: %s\n", gpiod_strerror(ret));
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        return 1;
    }
    valve_config_t.valve = VALVE_OFF;
    if ((ret = gpiod_valve_config_set(chip, line, valve_config_t)) != 0) {
        fprintf(stderr, "gpiod_valve_config_set failed: %s\n", gpiod_strerror(ret));
        gpiod_valve_config_free(valve_config_t);
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        return 1;
    }

    // Read the watering duration from the configuration file
    FILE *fp = fopen("watering.conf", "r");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open 'watering.conf'\n");
        gpiod_valve_config_free(valve_config_t);
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        return 1;
    }
    if (fscanf(fp, "%s", duration_str) != 1) {
        fprintf(stderr, "Invalid format in 'watering.conf'\n");
        fclose(fp);
        gpiod_valve_config_free(valve_config_t);
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        return 1;
    }
    if (sscanf(duration_str, "%d", &duration) != 1) {
        fprintf(stderr, "Invalid duration in 'watering.conf'\n");
        fclose(fp);
        gpiod_valve_config_free(valve_config_t);
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        return 1;
    }
    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Invalid duration in 'watering.conf'\n");
        fclose(fp);
        gpiod_valve_config_free(valve_config_t);
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        return 1;
    }
    fclose(fp);

    // Set the initial state of the valve
    if ((ret = gpiod_valve_config_set(chip, line, valve_config_t)) != 0) {
        fprintf(stderr, "gpiod_valve_config_set failed: %s\n", gpiod_strerror(ret));
        gpiod_valve_config_free(valve_config_t);
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        return 1;
    }

    // Install signal handlers
    if (sigaction(SIGINT, sigint_handler, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        gpiod_valve_config_free(valve_config_t);
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        return 1;
    }
    if (sigaction(SIGTERM, sigterm_handler, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler\n");
        gpiod_valve_config_free(valve_config_t);
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        return 1;
    }

    // Main loop
    while (!stop) {
        // Activate the valve
        if ((ret = gpiod_valve_config_set(chip, line, valve_config_t)) != 0) {
            fprintf(stderr, "gpiod_valve_config_set failed: %s\n", gpiod_strerror(ret));
            gpiod_valve_config_free(valve_config_t);
            gpiod_line_free(line);
            gpiod_chip_free(chip);
            return 1;
        }
        printf("Valve activated\n");

        // Wait for the configured duration
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        while (ts.tv_sec < duration) {
            if (stop) {
                break;
            }
            nanosleep(&ts, NULL);
            clock_gettime(CLOCK_REALTIME, &ts);
        }
        if (stop) {
            break;
        }

        // Deactivate the valve
        if ((ret = gpiod_valve_config_set(chip, line, valve_config_t)) != 0) {
            fprintf(stderr, "gpiod_valve_config_set failed: %s\n", gpiod_strerror(ret));
            gpiod_valve_config_free(valve_config_t);
            gpiod_line_free(line);
            gpiod_chip_free(chip);
            return 1;
        }
        printf("Valve deactivated\n");
    }

    // Release resources
    gpiod_valve_config_free(valve_config_t);
    gpiod_line_free(line);
    gpiod_chip_free(chip);

    return 0;
}
