#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define BH1750_ADDRESS 0x23
#define BH1750_COMMAND 0x10
#define BH1750_MODE_CONTINUOUS 0x01
#define BH1750_DELAY 180
#define RELAY_GPIO 23
#define RELAY_PIN 17
#define RELAY_STATE_ON 1
#define RELAY_STATE_OFF 0
#define RELAY_LOG_FILE "grow_log.txt"

int main(int argc, char **argv) {
    int i2c_fd;
    int relay_fd;
    int relay_state = RELAY_STATE_OFF;
    struct timespec last_measurement;
    struct timespec current_time;
    struct timespec delay;
    struct stat log_stat;
    struct stat log_stat_old;
    int i;
    int ret;
    int error;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C file descriptor
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set I2C address and mode
    ret = ioctl(i2c_fd, 0x40, BH1750_ADDRESS);
    if (ret < 0) {
        perror("ioctl");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    ret = ioctl(i2c_fd, 0x41, BH1750_MODE_CONTINUOUS);
    if (ret < 0) {
        perror("ioctl");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open relay file descriptor
    relay_fd = open(RELAY_LOG_FILE, O_RDWR | O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (relay_fd < 0) {
        perror("open");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up relay pin
    if (gpioMode(RELAY_PIN, GPIO_MODE_OUTPUT) < 0) {
        perror("gpioMode");
        close(i2c_fd);
        close(relay_fd);
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(RELAY_PIN, RELAY_STATE_OFF) < 0) {
        perror("gpioWrite");
        close(i2c_fd);
        close(relay_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Get current time
        clock_gettime(CLOCK_REALTIME, &current_time);

        // Read illuminance
        ret = i2cRead(i2c_fd, BH1750_ADDRESS, 3, 0x00, 0x00, 0x00);
        if (ret < 0) {
            error = errno;
            if (error == EIO) {
                // Sensor not detected, log and continue
                fprintf(relay_fd, "%ld %d %d\n", current_time.tv_sec, current_time.tv_nsec, error);
            } else {
                perror("i2cRead");
                close(i2c_fd);
                close(relay_fd);
                gpioTerminate();
                return 1;
            }
            continue;
        }

        // Check if sensor is ready
        if (ret & 0x80) {
            // Sensor not ready, log and continue
            fprintf(relay_fd, "%ld %d %d\n", current_time.tv_sec, current_time.tv_nsec, EIO);
            continue;
        }

        // Read illuminance
        int lux = (ret >> 8) & 0xFF;
        fprintf(relay_fd, "%ld %d %d\n", current_time.tv_sec, current_time.tv_nsec, lux);

        // Check if lux reading is below threshold
        if (lux < 150) {
            // Turn on relay
            gpioWrite(RELAY_PIN, RELAY_STATE_ON);
            relay_state = RELAY_STATE_ON;
        } else {
            // Turn off relay
            gpioWrite(RELAY_PIN, RELAY_STATE_OFF);
            relay_state = RELAY_STATE_OFF;
        }
    }

    // Clean up
    close(relay_fd);
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

