// Define constants
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22
#define SERVO_MIN 500
#define SERVO_MAX 2500
#define DEBOUNCE_DELAY 100

// Structure to hold servo position and state
typedef struct {
    int position;
    int locked;
} servo_state_t;

// Global variables
pigpio gpio;
servo_state_t servo_state;

// Function to initialize pigpio
void init_pigpio() {
    if (gpio_init(&gpio) != 0) {
        printf("Error initializing pigpio: %d\n", gpio_get_error());
        exit(1);
    }
}

// Function to clean up pigpio
void cleanup_pigpio() {
    gpio_close(SERVO_PIN);
    gpio_close(LOCK_BUTTON_PIN);
    gpio_close(UNLOCK_BUTTON_PIN);
    gpioTerminate(&gpio);
}

// Function to set servo position
void set_servo_position(int position) {
    if (position < SERVO_MIN || position > SERVO_MAX) {
        printf("Invalid servo position: %d\n", position);
        return;
    }
    if (gpio_set_servo_pulsewidth(SERVO_PIN, position) != 0) {
        printf("Error setting servo position: %d\n", gpio_get_error());
    }
}

// Function to handle button press
void button_press(int button, int level) {
    if (button == LOCK_BUTTON_PIN) {
        if (level == 0) {
            printf("Lock button pressed\n");
            set_servo_position(SERVO_MAX);
            servo_state.locked = 1;
        }
    } else if (button == UNLOCK_BUTTON_PIN) {
        if (level == 0) {
            printf("Unlock button pressed\n");
            set_servo_position(SERVO_MIN);
            servo_state.locked = 0;
        }
    }
}

// Function to handle servo position change
void servo_position_changed() {
    if (servo_state.locked) {
        set_servo_position(SERVO_MAX);
    } else {
        set_servo_position(SERVO_MIN);
    }
}

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    cleanup_pigpio();
    exit(0);
}

int main() {
    // Initialize pigpio
    init_pigpio();

    // Set up GPIO pins
    if (gpio_set_mode(SERVO_PIN, PI_OUTPUT) != 0) {
        printf("Error setting servo pin mode: %d\n", gpio_get_error());
        cleanup_pigpio();
        exit(1);
    }
    if (gpio_set_mode(LOCK_BUTTON_PIN, PI_INPUT) != 0) {
        printf("Error setting lock button pin mode: %d\n", gpio_get_error());
        cleanup_pigpio();
        exit(1);
    }
    if (gpio_set_mode(UNLOCK_BUTTON_PIN, PI_INPUT) != 0) {
        printf("Error setting unlock button pin mode: %d\n", gpio_get_error());
        cleanup_pigpio();
        exit(1);
    }

    // Set up servo position
    set_servo_position(SERVO_MIN);

    // Set up button press handler
    gpio_callback_add(LOCK_BUTTON_PIN, button_press, NULL);
    gpio_callback_add(UNLOCK_BUTTON_PIN, button_press, NULL);

    // Set up servo position change handler
    gpio_callback_add(SERVO_PIN, servo_position_changed, NULL);

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Check for button presses
        if (gpio_read(LOCK_BUTTON_PIN) == 0) {
            sleep(DEBOUNCE_DELAY);
            if (gpio_read(LOCK_BUTTON_PIN) == 0) {
                button_press(LOCK_BUTTON_PIN, 0);
            }
        }
        if (gpio_read(UNLOCK_BUTTON_PIN) == 0) {
            sleep(DEBOUNCE_DELAY);
            if (gpio_read(UNLOCK_BUTTON_PIN) == 0) {
                button_press(UNLOCK_BUTTON_PIN, 0);
            }
        }
    }

    return 0;
}

