#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>
#include <gpiod/gpiod.h>
#include <gpiod/gpiod-async.h>

// Define constants
#define GPIO17 17
#define GPIO27 27
#define PULSE1 200
#define PULSE2 300
#define LINE1 "line1"
#define LINE2 "line2"
#define LINE1_REQUEST "line1_request"
#define LINE2_REQUEST "line2_request"

// Define a function to handle signals
void signal_handler(int sig) {
    gpiod_line_release(LINE1_REQUEST);
    gpiod_line_release(LINE2_REQUEST);
    exit(0);
}

int main() {
    // Register signal handlers
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        perror("gpiod_init");
        return 1;
    }

    // Create lines
    struct gpiod_line *line1, *line2;
    if ((line1 = gpiod_line_request_output(LINE1_REQUEST, GPIO17, 0, 0)) == NULL) {
        perror("gpiod_line_request_output");
        gpiod_exit();
        return 1;
    }
    if ((line2 = gpiod_line_request_output(LINE2_REQUEST, GPIO27, 0, 0)) == NULL) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line1);
        gpiod_exit();
        return 1;
    }

    // Set line directions
    if (gpiod_line_set_direction(line1, GpioDirectionOutput) < 0) {
        perror("gpiod_line_set_direction");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_exit();
        return 1;
    }
    if (gpiod_line_set_direction(line2, GpioDirectionOutput) < 0) {
        perror("gpiod_line_set_direction");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_exit();
        return 1;
    }

    // Set line values
    if (gpiod_line_set_value(line1, 0) < 0) {
        perror("gpiod_line_set_value");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_exit();
        return 1;
    }
    if (gpiod_line_set_value(line2, 0) < 0) {
        perror("gpiod_line_set_value");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_exit();
        return 1;
    }

    // Main loop
    while (1) {
        // Pulse motor 1
        if (gpiod_line_set_value(line1, 1) < 0) {
            perror("gpiod_line_set_value");
            gpiod_line_release(line1);
            gpiod_line_release(line2);
            gpiod_exit();
            return 1;
        }
        usleep(PULSE1 * 1000);
        gpiod_line_set_value(line1, 0);

        // Pulse motor 2
        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("gpiod_line_set_value");
            gpiod_line_release(line1);
            gpiod_line_release(line2);
            gpiod_exit();
            return 1;
        }
        usleep(PULSE2 * 1000);
        gpiod_line_set_value(line2, 0);
    }

    // Release lines
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_exit();
    return 0;
}

