#include <arpa/inet.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_ADDR_23 0x23
#define I2C_ADDR_24 0x24
#define I2C_ADDR_25 0x25
#define I2C_ADDR_26 0x26
#define I2C_ADDR_5C 0x5C
#define I2C_SLAVE 0x70
#define I2C_MODE 0x20
#define I2C_READ 0x00
#define I2C_WRITE 0x01
#define I2C_TIMEOUT 0.1
#define I2C_DELAY 180
#define I2C_BUFFER_SIZE 2
#define I2C_MULTICAST_ADDR 239.255.255.250
#define I2C_MULTICAST_PORT 5005

int fd[4];
int i;
int exit_flag = 0;
int s;
struct sockaddr_in server_addr;
struct i2c_client *clients[4];
char buffer[I2C_BUFFER_SIZE];

void handle_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    exit(1);
}

void close_all() {
    for (i = 0; i < 4; i++) {
        if (clients[i] != NULL) {
            i2c_release(clients[i]);
            clients[i] = NULL;
        }
    }
    close(s);
    close(fd[0]);
    close(fd[1]);
    exit(0);
}

void send_multicast_packet() {
    char packet[I2C_BUFFER_SIZE * 4 + 1];
    int bytes_read = 0;
    for (i = 0; i < 4; i++) {
        if (clients[i] == NULL) {
            sprintf(packet + bytes_read, "%d,NAN;", i + 1);
            bytes_read += 4;
        } else {
            int lux = 0;
            if (i2c_read(clients[i], I2C_ADDR_23 + i, I2C_READ, I2C_TIMEOUT, buffer, I2C_BUFFER_SIZE) == -1) {
                sprintf(packet + bytes_read, "%d,NAN;", i + 1);
                bytes_read += 4;
            } else {
                lux = ((buffer[0] << 8) | buffer[1]) / 1.2;
                sprintf(packet + bytes_read, "%d,%d;", i + 1, lux);
                bytes_read += 5;
            }
        }
    }
    packet[bytes_read] = '\0';
    if (sendto(s, packet, bytes_read, 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) == -1) {
        handle_error("sendto");
    }
}

