#include <errno.h>

#define I2C_ADDRESS 0x28
#define I2C_FILE "/dev/i2c-1"
#define LOG_FILE "airflow_log.txt"

int main() {
    int fd;
    int retry = 0;
    int retry_count = 0;
    int raw;
    int flow;
    struct i2c_client *client;
    struct i2c_msg msg;
    struct i2c_file *file;

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open I2C file descriptor
    fd = open(I2C_FILE, O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    // Get I2C client
    client = i2c_get_client(fd);
    if (!client) {
        perror("i2c_get_client");
        exit(1);
    }

    // Open log file
    file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("fopen");
        exit(1);
    }

    while (1) {
        // Zero-length I2C write as start condition
        msg.msg_type = I2C_WRITE;
        msg.msg_dir = I2C_WRITE;
        msg.addr = I2C_ADDRESS;
        msg.flags = 0;
        msg.len = 0;
        msg.buf = NULL;

        // Read 2 bytes
        msg.msg_type = I2C_READ;
        msg.msg_dir = I2C_READ;
        msg.addr = I2C_ADDRESS;
        msg.flags = 0;
        msg.len = 2;
        msg.buf = malloc(2);
        if (!msg.buf) {
            perror("malloc");
            exit(1);
        }

        retry_count = 0;
        while (retry_count < 3) {
            if (i2c_transfer(client, &msg, 1) < 0) {
                if (errno == EIO) {
                    retry_count++;
                    usleep(100 * 1000);
                } else {
                    perror("i2c_transfer");
                    exit(1);
                }
            } else {
                break;
            }
        }

        if (retry_count == 3) {
            perror("i2c_transfer");
            exit(1);
        }

        // Check if read was successful
        if (msg.len < 2) {
            perror("i2c_transfer");
            exit(1);
        }

        // Mask raw value with 0x3FFF
        raw = msg.buf[0] | (msg.buf[1] << 8);

        // Convert raw value to SLPM
        flow = (raw - 3277) * 0.1;

        // Log flow rate
        fprintf(file, "%d %f\n", time(NULL), flow);

        // Close I2C file descriptor
        close(fd);
        fd = -1;

        // Flush log file
        fflush(file);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Close log file
    fclose(file);

    return 0;
}

void sigint_handler(int sig) {
    // Close I2C file descriptor
    close(0);

    // Flush log file
    fflush(1);

    // Exit
    exit(0);
}

