#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <syslog.h>

#define I2C_ADDRESS 0x37
#define I2C_FILE "/dev/i2c-1"
#define CSV_FILE "seismic_data.csv"
#define CSV_ERROR_FILE "seismic_error.log"

int main(int argc, char *argv[]) {
    int i2c_fd = -1;
    int retry_count = 0;
    int retry_delay = 10;
    int interval = 1;
    char *output_file = CSV_FILE;

    // Parse command-line options
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-a") == 0) {
            if (i + 1 < argc) {
                i2c_fd = open(I2C_FILE, O_RDWR);
                if (i2c_fd < 0) {
                    perror("open");
                    return 1;
                }
                if (ioctl(i2c_fd, I2C_SLAVE, atoi(argv[++i])) < 0) {
                    perror("ioctl");
                    return 1;
                }
                I2C_ADDRESS = atoi(argv[++i]);
            } else {
                fprintf(stderr, "Error: -a option requires a value\n");
                return 1;
            }
        } else if (strcmp(argv[i], "-i") == 0) {
            if (i + 1 < argc) {
                interval = atoi(argv[++i]);
                if (interval <= 0) {
                    fprintf(stderr, "Error: -i option requires a positive value\n");
                    return 1;
                }
            } else {
                fprintf(stderr, "Error: -i option requires a value\n");
                return 1;
            }
        } else if (strcmp(argv[i], "-f") == 0) {
            if (i + 1 < argc) {
                output_file = argv[++i];
                if (access(output_file, W_OK) != 0) {
                    fprintf(stderr, "Error: output file '%s' not writable\n", output_file);
                    return 1;
                }
            } else {
                fprintf(stderr, "Error: -f option requires a value\n");
                return 1;
            }
        } else {
            fprintf(stderr, "Error: unknown option '%s\n", argv[i]);
            return 1;
        }
    }

    // Open I2C file descriptor
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }

    // Open CSV file
    FILE *csv_file = fopen(output_file, "w");
    if (csv_file == NULL) {
        perror("fopen");
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    sa.sa_handler = sigterm_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    while (1) {
        // Read tri-axial acceleration
        uint8_t raw[6];
        if (i2c_rdwr(i2c_fd, I2C_ADDRESS, 0x28, 6, raw, 6, 0) < 0) {
            if (errno == EIO) {
                retry_count = 0;
                retry_delay = 10;
            } else if (errno == EBUSY) {
                retry_count = 0;
                retry_delay = 10;
            } else {
                retry_count++;
                if (retry_count < 3) {
                    usleep(retry_delay * 1000);
                    retry_delay *= 2;
                } else {
                    fprintf(csv_file, "%ld,%d,%d,%d\n", time(NULL), raw[0], raw[1], raw[2]);
                    fprintf(csv_file, "%ld,%d,%d,%d\n", time(NULL), raw[3], raw[4], raw[5]);
                    fclose(csv_file);
                    return 0;
                }
            }
        } else {
            if (retry_count > 0) {
                retry_count = 0;
                retry_delay = 10;
            }
            // Convert tri-axial acceleration to g
            float x_g = (raw[0] * 0.000244);
            float y_g = (raw[1] * 0.000244);
            float z_g = (raw[2] * 0.000244);
            fprintf(csv_file, "%ld,%f,%f,%f\n", time(NULL), x_g, y_g, z_g);
        }
    }

    // Close I2C file descriptor
    if (close(i2c_fd) < 0) {
        perror("close");
        return 1;
    }

    // Close CSV file
    if (fclose(csv_file) < 0) {
        perror("fclose");
        return 1;
    }

    return 0;
}

void sigint_handler(int sig) {
    // Close I2C file descriptor
    if (close(i2c_fd) < 0) {
        perror("close");
    }
    // Close CSV file
    if (fclose(csv_file) < 0) {
        perror("fclose");
    }
    // Exit
    exit(0);
}

void sigterm_handler(int sig) {
    // Close I2C file descriptor
    if (close(i2c_fd) < 0) {
        perror("close");
    }
    // Close CSV file
    if (fclose(csv_file) < 0) {
        perror("fclose");
    }
    // Exit
    exit(0);
}

