#include <string.h>
#include <pigpio.h>
#include <sys/select.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <syslog.h>

#define UART_BAUD 921600
#define UART_PORT "/dev/ttyS0"
#define CSV_FILE "radar_data.csv"
#define MAGIC_WORD 0x0204 0x0306 0x0805 0x0709
#define TLV_SIZE 8
#define OBJECT_SIZE 4

int main(int argc, char **argv) {
    int uart_fd, csv_fd;
    struct termios uart_settings;
    struct termios csv_settings;
    struct sigaction sigint_handler;
    struct sigaction sigterm_handler;
    struct timeval timeout;
    char buffer[TLV_SIZE];
    int object_index = 0;
    int object_count = 0;
    int range_m = 0;
    int velocity_mps = 0;
    struct timespec timestamp;
    struct timespec last_timestamp;
    struct stat csv_stat;
    struct sigaction sigpipe_handler;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up UART
    if ((uart_fd = open(UART_PORT, O_RDWR)) < 0) {
        perror("open");
        return 1;
    }

    if (tcgetattr(uart_fd, &uart_settings) < 0) {
        perror("tcgetattr");
        return 1;
    }

    cfsetispeed(&uart_settings, UART_BAUD);
    cfsetospeed(&uart_settings, UART_BAUD);
    if (tcsetattr(uart_fd, TCSANOW, &uart_settings) < 0) {
        perror("tcsetattr");
        return 1;
    }

    // Set up CSV file
    if ((csv_fd = open(CSV_FILE, O_RDWR | O_CREAT | O_TRUNC, 0644)) < 0) {
        perror("open");
        return 1;
    }

    if (fstat(csv_fd, &csv_stat) < 0) {
        perror("fstat");
        return 1;
    }

    // Set up signal handlers
    sigemptyset(&sigint_handler);
    sigaddsignal(SIGINT, &sigint_handler);
    sigemptyset(&sigterm_handler);
    sigaddsignal(SIGTERM, &sigterm_handler);
    sigpipe(&sigpipe_handler);
    sigaction(SIGPIPE, &sigpipe_handler, NULL);

    while (1) {
        // Read from UART
        ssize_t bytes_read = read(uart_fd, buffer, TLV_SIZE);
        if (bytes_read < 0) {
            perror("read");
            continue;
        }

        // Check for magic word
        if (memcmp(buffer, &MAGIC_WORD, TLV_SIZE) != 0) {
            continue;
        }

        // Validate TLV payload
        if (bytes_read < TLV_SIZE) {
            continue;
        }

        // Extract object data
        range_m = (buffer[TLV_SIZE - 1] << 16) | (buffer[TLV_SIZE - 2] << 8) | buffer[TLV_SIZE - 3];
        velocity_mps = (buffer[TLV_SIZE - 4] << 16) | (buffer[TLV_SIZE - 5] << 8) | buffer[TLV_SIZE - 6];

        // Log data
        time(&timestamp);
        if (fstat(csv_fd, &csv_stat) < 0) {
            perror("fstat");
            continue;
        }
        if (ftruncate(csv_fd, csv_stat.st_size + TLV_SIZE) < 0) {
            perror("ftruncate");
            continue;
        }
        if (fwrite(csv_fd, &timestamp.tv_sec, sizeof(timestamp.tv_sec), csv_fd) < 0) {
            perror("fwrite");
            continue;
        }
        if (fwrite(csv_fd, &object_index, sizeof(object_index), csv_fd) < 0) {
            perror("fwrite");
            continue;
        }
        if (fwrite(csv_fd, &range_m, sizeof(range_m), csv_fd) < 0) {
            perror("fwrite");
            continue;
        }
        if (fwrite(csv_fd, &velocity_mps, sizeof(velocity_mps), csv_fd) < 0) {
            perror("fwrite");
            continue;
        }

        object_index++;
        if (object_index >= 10) {
            object_index = 0;
        }

        // Sleep for 10ms
        usleep(10000);
    }

    // Clean up
    close(uart_fd);
    close(csv_fd);
    gpioTerminate();
    return 0;
}

