#include <sys/select.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/time.h>

#define UART_FILE "/dev/serial0"
#define BAUDRATE 115200
#define TIMEOUT 2
#define BUFFER_SIZE 1024

int main() {
    int uart_fd, uart_flags;
    struct termios old_flags, new_flags;
    struct timeval timeout;
    char buffer[BUFFER_SIZE];
    char *line;
    struct tm time;
    time_t last_timestamp;
    int line_count = 0;
    int running = 1;

    // Set up signal handlers
    signal(SIGINT, SIGTERM);
    signal(SIGPIPE, SIG_IGN);

    // Open UART
    if ((uart_fd = open(UART_FILE, O_RDWR)) == -1) {
        perror("open");
        return 1;
    }

    // Set up UART
    if (tcgetattr(uart_fd, &old_flags) == -1) {
        perror("tcgetattr");
        return 1;
    }
    cfsetispeed(&new_flags, BAUDRATE);
    cfsetospeed(&new_flags, BAUDRATE);
    if (tcsetattr(uart_fd, TCSANOW, &new_flags) == -1) {
        perror("tcsetattr");
        return 1;
    }

    // Set up non-canonical mode
    if (tcgetattr(uart_fd, &old_flags) == -1) {
        perror("tcgetattr");
        return 1;
    }
    old_flags.c_lflag &= ~ICANON;
    old_flags.c_lflag &= ~ECHO;
    if (tcsetattr(uart_fd, TCSANOW, &old_flags) == -1) {
        perror("tcsetattr");
        return 1;
    }

    // Set up timeout
    timeout.tv_sec = TIMEOUT;
    timeout.tv_usec = 0;
    if (select(uart_fd + 1, NULL, NULL, NULL, &timeout) == -1) {
        perror("select");
        return 1;
    }

    // Main loop
    while (running) {
        // Read from UART
        ssize_t bytes_read = read(uart_fd, buffer, BUFFER_SIZE);
        if (bytes_read == -1) {
            perror("read");
            return 1;
        }
        if (bytes_read == 0) {
            // No data available
            continue;
        }

        // Parse line
        line = strdup(buffer);
        if (line == NULL) {
            perror("strdup");
            return 1;
        }
        char *token = strtok(line, "\n");
        if (token == NULL) {
            free(line);
            continue;
        }
        char *timestamp = strtok(NULL, ",");
        if (timestamp == NULL) {
            free(line);
            continue;
        }
        char *range = strtok(NULL, ",");
        if (range == NULL) {
            free(line);
            continue;
        }

        // Parse timestamp
        time_t current_timestamp = time(NULL);
        if (difftime(current_timestamp, last_timestamp) > 1) {
            printf("Timestamp: %04d-%02d-%02d %02d:%02d:%02d, Range: %s meters\n",
                   time.tm_year + 1900, time.tm_mon + 1, time.tm_mday, time.tm_hour, time.tm_min, time.tm_sec, range);
            last_timestamp = current_timestamp;
            line_count = 0;
        }

        // Log range
        if (line_count % 10 == 0) {
            printf("Timestamp: %04d-%02d-%02d %02d:%02d:%02d, Range: %s meters\n",
                   time.tm_year + 1900, time.tm_mon + 1, time.tm_mday, time.tm_hour, time.tm_min, time.tm_sec, range);
        }
        line_count++;

        free(line);
    }

    // Close UART
    if (close(uart_fd) == -1) {
        perror("close");
        return 1;
    }

    return 0;
}

